// Static option list for streamVacancyFields when a required State field's real DOM options can't be
// read at collect time — the Workday US State dropdown is the same fixed 50-state + territories list on
// every tenant, so the model always has real choices to pick from instead of an empty options[].
const WORKDAY_US_STATE_OPTIONS = [
    ...Object.values(US_STATE_BY_ABBREV),
    'Puerto Rico', 'Guam', 'American Samoa', 'U.S. Virgin Islands', 'Northern Mariana Islands',
    'Armed Forces Americas', 'Armed Forces Europe', 'Armed Forces Pacific',
];

function getUSCityFromJobLocation() {
    const loc = String(window.__wdHistoryLocation || '').replace(/\s+/g, ' ').trim();
    const m = loc.match(/^([^,]+),\s*(?:[A-Z]{2}|[A-Za-z])/);
    if (m) return m[1].trim();
    if (/\bremote\b|usa-remote/i.test(loc.toLowerCase())) {
        return 'Boston';
    }
    return '';
}

function getDefaultUSZipForJobLocation() {
    const city = getUSCityFromJobLocation().toLowerCase();
    const known = {
        'clarks summit': '18411', scranton: '18503', 'wilkes-barre': '18701',
        pittsburgh: '15201', philadelphia: '19103', houston: '77001', dallas: '75201',
        'los angeles': '90001', 'san francisco': '94102', chicago: '60601', miami: '33101',
        atlanta: '30301', boston: '02108', seattle: '98101', denver: '80201', tampa: '33602',
    };
    if (city && known[city]) return known[city];
    const state = getUSStateFromJobLocation();
    const stateZip = {
        Pennsylvania: '18411', California: '90001', Texas: '77001', Florida: '33101',
        'New York': '10001', Illinois: '60601', Ohio: '43201', Georgia: '30301',
        'North Carolina': '27601', Virginia: '23219', Washington: '98101', Colorado: '80201',
        Arizona: '85001',         Massachusetts: '02108', Maryland: '21201', Michigan: '48201', Maine: '04609',
    };
    if (state) return stateZip[state] || null;
    if (profileExpectsUS(window.__wdApplyData?.profile)) return '20001';
    return null;
}

function getDefaultUSStreetForJobLocation() {
    const city = getUSCityFromJobLocation();
    if (city) return `100 ${city} Street`;
    return '100 Main Street';
}

function getUSStateFromJobLocation() {
    const loc = String(window.__wdHistoryLocation || '').replace(/\s+/g, ' ').trim();
    if (!loc) return null;
    const abbrMatch = loc.match(/,\s*([A-Z]{2})(?:\s*,|\s+(?:USA|United States)\b|\s*$)/i);
    if (abbrMatch) {
        const name = US_STATE_BY_ABBREV[abbrMatch[1].toUpperCase()];
        if (name) return name;
    }
    for (const name of Object.values(US_STATE_BY_ABBREV)) {
        if (new RegExp(`\\b${name.replace(/\s+/g, '\\s+')}\\b`, 'i').test(loc)) return name;
    }
    return null;
}

function getUSStateFromZip(zip) {
    const z = parseInt(String(zip || '').replace(/\D/g, '').slice(0, 3), 10);
    if (!Number.isFinite(z)) return null;
    const ranges = [
        [350, 369, 'Alabama'], [995, 999, 'Alaska'], [850, 865, 'Arizona'], [716, 729, 'Arkansas'],
        [900, 961, 'California'], [800, 816, 'Colorado'], [60, 69, 'Connecticut'], [197, 199, 'Delaware'],
        [320, 349, 'Florida'], [300, 319, 'Georgia'], [967, 968, 'Hawaii'], [832, 838, 'Idaho'],
        [600, 629, 'Illinois'], [460, 479, 'Indiana'], [500, 528, 'Iowa'], [660, 679, 'Kansas'],
        [700, 714, 'Louisiana'], [39, 49, 'Maine'], [206, 219, 'Maryland'], [10, 27, 'Massachusetts'],
        [480, 499, 'Michigan'], [550, 567, 'Minnesota'], [386, 397, 'Mississippi'], [630, 658, 'Missouri'],
        [590, 599, 'Montana'], [680, 693, 'Nebraska'], [889, 898, 'Nevada'], [30, 38, 'New Hampshire'],
        [70, 89, 'New Jersey'], [870, 884, 'New Mexico'], [100, 149, 'New York'], [270, 289, 'North Carolina'],
        [580, 588, 'North Dakota'], [430, 459, 'Ohio'], [730, 749, 'Oklahoma'], [970, 979, 'Oregon'],
        [150, 196, 'Pennsylvania'], [28, 29, 'Rhode Island'], [290, 299, 'South Carolina'],
        [570, 577, 'South Dakota'], [370, 385, 'Tennessee'], [750, 799, 'Texas'], [885, 885, 'Texas'],
        [840, 847, 'Utah'], [50, 59, 'Vermont'], [201, 246, 'Virginia'], [980, 994, 'Washington'],
        [247, 268, 'West Virginia'], [530, 549, 'Wisconsin'], [820, 831, 'Wyoming'], [200, 205, 'District of Columbia'],
    ];
    for (const [lo, hi, state] of ranges) {
        if (z >= lo && z <= hi) return state;
    }
    return null;
}

function isWorkdayStateFieldLabel(label) {
    const l = String(label || '').toLowerCase().trim();
    if (/phone/.test(l)) return false;
    const firstLine = l.split('\n')[0].trim();
    return /^(state|state\/province|state or province)(\s*\*)?$/.test(firstLine);
}

function isWorkdayStateFieldFilled(container) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/select one/i.test(preview) || /error:/i.test(preview)) return false;
    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const selected = (selectionLabel?.innerText || '').trim();
    if (selected && !/^select one$/i.test(selected)) return true;
    const combobox = container.querySelector('input[role="combobox"]');
    const val = (combobox?.value || '').trim();
    return Boolean(val && /^[a-f0-9]{20,}$/i.test(val));
}

function deriveUSStateFromProfile(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const area = residency.area || profile?.residencyArea;
    if (area) return area;
    const zip = residency.zip || profile?.residencyZip;
    if (profileExpectsUS(profile) && zip) {
        const fromZip = getUSStateFromZip(zip);
        if (fromZip) return fromZip;
    }
    const city = (residency.city || profile?.residencyCity || '').toLowerCase();
    if (city.includes('los angeles') || city.includes('fontana') || city.includes('san ')) return 'California';
    if (/pearland|houston|dallas|austin|san antonio|fort worth|plano|arlington|irving|katy|sugar land|the woodlands|corpus christi|el paso|laredo|amarillo|lubbock|mckinney|frisco|round rock|richardson|carrollton|lewisville|denton|waco|tyler|beaumont|galveston|college station|bryan|conroe|baytown|mission|pharr|league city|flower mound|georgetown|cedar park|san marcos|temple|missouri city|desoto|wylie|burleson|grapevine|port arthur|rockwall|huntsville|texas city|victoria|sherman|new braunfels|edinburg|longview|harlingen|north richland hills|rowlett|allen|mesquite|garland|mcallen|brownsville|killeen|midland|odessa|abilene|pasadena|spring|tomball|humble|kingwood|stafford|missouri city|friendswood|lake jackson|sugarland/i.test(city)) {
        return 'Texas';
    }
    if (/tampa|miami|orlando|jacksonville|st\.?\s*petersburg|fort lauderdale|hialeah|tallahassee|port st\.?\s*lucie|cape coral|pembroke pines|hollywood|miramar|gainesville|coral springs|palm bay|west palm|clearwater|brandon|lakeland|palm coast|deltona|daytona|kissimmee|naples|sarasota|pensacola|fort myers|ocala|melbourne|boynton beach|plantation|sunrise|boca raton|delray beach|winter haven|doral|homestead|north port|port charlotte|palm harbor|wellington|jupiter|sanford|altamonte|apopka|clermont|riverview|largo|pinellas|hillsborough|polk county|broward|palm beach|duval|orange county.*fl/i.test(city)) {
        return 'Florida';
    }
    return null;
}

const US_STATE_NAME_RE = /^(alabama|alaska|arizona|arkansas|california|colorado|connecticut|delaware|florida|georgia|hawaii|idaho|illinois|indiana|iowa|kansas|kentucky|louisiana|maine|maryland|massachusetts|michigan|minnesota|mississippi|missouri|montana|nebraska|nevada|new hampshire|new jersey|new mexico|new york|north carolina|north dakota|ohio|oklahoma|oregon|pennsylvania|rhode island|south carolina|south dakota|tennessee|texas|utah|vermont|virginia|washington|west virginia|wisconsin|wyoming|district of columbia|washington dc|d\.?c\.?)$/i;

function getUSCountyForProfile(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const area = String(residency.area || profile?.residencyArea || '').trim();
    // residency.area is often the state name on US profiles — only use it when it looks like a county.
    if (area && /county/i.test(area)) return area.replace(/\s+county$/i, '').trim() || area;
    if (area && !US_STATE_NAME_RE.test(area) && area.length >= 3 && area.length <= 40) return area;
    const city = String(residency.city || profile?.residencyCity || '').toLowerCase().trim();
    const cityCounty = {
        'san jose': 'Santa Clara',
        'san francisco': 'San Francisco',
        'oakland': 'Alameda',
        'los angeles': 'Los Angeles',
        'san diego': 'San Diego',
        'sacramento': 'Sacramento',
        'fresno': 'Fresno',
        'boston': 'Suffolk',
        'cambridge': 'Middlesex',
        'new york': 'New York',
        'brooklyn': 'Kings',
        'chicago': 'Cook',
        'houston': 'Harris',
        'dallas': 'Dallas',
        'austin': 'Travis',
        'seattle': 'King',
        'denver': 'Denver',
        'phoenix': 'Maricopa',
        'miami': 'Miami-Dade',
        'atlanta': 'Fulton',
    };
    if (cityCounty[city]) return cityCounty[city];
    for (const [key, county] of Object.entries(cityCounty)) {
        if (city.includes(key)) return county;
    }
    // Last resort: never stream County to AI (2×120s timeouts). City is accepted on many tenants.
    return residency.city || profile?.residencyCity || getUSCityFromJobLocation() || 'Other';
}

// UK Workday "County" lists local authorities / London boroughs — NOT meta-regions like "Greater London".
const UK_META_REGION_RE = /^(greater\s+london|greater\s+manchester|west\s+midlands|south\s+yorkshire|west\s+yorkshire|merseyside|tyne\s+and\s+wear|inner\s+london|outer\s+london|central\s+london)$/i;

function profileExpectsUK(profile) {
    const raw = getProfileCountryName(profile).toLowerCase();
    if (/united kingdom|\buk\b|great britain|england|scotland|wales|northern ireland/.test(raw)) return true;
    const phone = String(profile?.phoneCountryCode || profile?.general?.phoneCountryCode || '');
    return phone === '+44';
}

function isWorkdayCountyFieldLabel(label) {
    const l = String(label || '').toLowerCase().replace(/\*/g, ' ').replace(/\s+/g, ' ').trim();
    if (/^county$/.test(l)) return true;
    if (/\bcounty\b/.test(l) && l.length < 48 && !/country|account|discount|visa|citizen/.test(l)
        && !/\?/.test(l) && !/^\s*(are|do|have|is|can|will|did)\s+you\b/.test(l)) {
        return true;
    }
    return false;
}

/** UK outward code from postcode (inward is always the last 3 chars when concatenated). */
function getUKOutwardPostcode(zip) {
    const cleaned = String(zip || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (cleaned.length >= 5) return cleaned.slice(0, -3);
    return cleaned;
}

