function getUKLocalAuthorityFromPostcode(zip) {
    const outward = getUKOutwardPostcode(zip);
    if (!outward) return null;
    if (UK_LONDON_OUTWARD_TO_BOROUGH[outward]) return UK_LONDON_OUTWARD_TO_BOROUGH[outward];
    // Progressive shorten: N1C → N1, SW1A → SW1, EC1A → EC1
    for (let i = outward.length - 1; i >= 2; i--) {
        const key = outward.slice(0, i);
        if (UK_LONDON_OUTWARD_TO_BOROUGH[key]) return UK_LONDON_OUTWARD_TO_BOROUGH[key];
    }
    return null;
}

function getUKCityLocalAuthority(city) {
    const c = String(city || '').toLowerCase().trim();
    if (!c || /^london$/.test(c)) return null;
    const map = {
        birmingham: 'Birmingham', manchester: 'Manchester', leeds: 'Leeds', liverpool: 'Liverpool',
        sheffield: 'Sheffield', bristol: 'Bristol', edinburgh: 'City of Edinburgh', glasgow: 'Glasgow City',
        cardiff: 'Cardiff', belfast: 'Belfast', newcastle: 'Newcastle upon Tyne',
        'newcastle upon tyne': 'Newcastle upon Tyne', nottingham: 'Nottingham', leicester: 'Leicester',
        coventry: 'Coventry', bradford: 'Bradford', reading: 'Reading', oxford: 'Oxford',
        cambridge: 'Cambridge', brighton: 'Brighton and Hove', southampton: 'Southampton',
        portsmouth: 'Portsmouth', plymouth: 'Plymouth', derby: 'Derby', york: 'York',
        islington: 'Islington', camden: 'Camden', hackney: 'Hackney', southwark: 'Southwark',
        westminster: 'Westminster', lambeth: 'Lambeth',
    };
    if (map[c]) return map[c];
    for (const [key, la] of Object.entries(map)) {
        if (c.includes(key)) return la;
    }
    return null;
}

function getUKCountyForProfile(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const fromZip = getUKLocalAuthorityFromPostcode(residency.zip || profile?.residencyZip);
    if (fromZip) return fromZip;
    const fromCity = getUKCityLocalAuthority(residency.city || profile?.residencyCity);
    if (fromCity) return fromCity;
    const area = String(residency.area || profile?.residencyArea || '').trim();
    if (area && !UK_META_REGION_RE.test(area)) return area;
    const city = String(residency.city || profile?.residencyCity || '').trim();
    if (city && !/^london$/i.test(city) && !UK_META_REGION_RE.test(city)) return city;
    return null;
}

/** Prefer UK local authority / US county — never stream County (AI timeouts). */
function getCountyForProfile(profile) {
    if (profileExpectsUK(profile)) {
        const uk = getUKCountyForProfile(profile);
        if (uk) return uk;
        // Bare "London" / meta-regions are not in Workday LA lists — fill resolves via options + postcode.
        const city = String(profile?.residency?.city || profile?.residencyCity || '').trim();
        if (city && !/^london$/i.test(city) && !UK_META_REGION_RE.test(city)) return city;
        return 'Other';
    }
    return getUSCountyForProfile(profile);
}

function getCountyFillCandidates(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const out = [];
    const add = (v) => {
        const s = String(v || '').trim();
        if (!s || UK_META_REGION_RE.test(s)) return;
        if (out.some((x) => x.toLowerCase() === s.toLowerCase())) return;
        out.push(s);
    };
    if (profileExpectsUK(profile)) {
        add(getUKLocalAuthorityFromPostcode(residency.zip || profile?.residencyZip));
        add(getUKCityLocalAuthority(residency.city || profile?.residencyCity));
        const area = String(residency.area || profile?.residencyArea || '').trim();
        if (area && !UK_META_REGION_RE.test(area)) add(area);
        const city = String(residency.city || profile?.residencyCity || '').trim();
        if (city && !/^london$/i.test(city)) add(city);
        add(getUKCountyForProfile(profile));
    } else {
        add(getUSCountyForProfile(profile));
    }
    return out.length ? out : [getCountyForProfile(profile)];
}

function looksLikeUKLocalAuthorityOptions(optionLabels) {
    const sample = (optionLabels || []).slice(0, 20).join(' ').toLowerCase();
    return /aberdeen city|aberdeenshire|barking and dagenham|ards and north down|argyll and bute|antrim and newtownabbey/.test(sample);
}

/** Match County candidates against an open Workday option list (UK borough / US county). */
function resolveCountyOptionAgainstList(options, profile) {
    if (!options?.length) return null;
    const labels = options.map((o) => optionText(o)).filter((t) => t && !/^select one$/i.test(t));
    const candidates = getCountyFillCandidates(profile);
    if (looksLikeUKLocalAuthorityOptions(labels) || profileExpectsUK(profile)) {
        const fromZip = getUKLocalAuthorityFromPostcode(
            profile?.residency?.zip || profile?.residencyZip || profile?.general?.residency?.zip,
        );
        if (fromZip) candidates.unshift(fromZip);
    }
    for (const candidate of candidates) {
        const cl = String(candidate).toLowerCase();
        const found = options.find((o) => optionText(o) === cl)
            || options.find((o) => {
                const ot = optionText(o);
                return ot.includes(cl) || cl.includes(ot);
            });
        if (found) return found;
    }
    return null;
}

function getConsistentUSStateForProfile(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const zip = residency.zip || profile?.residencyZip;
    const fromZip = profileExpectsUS(profile) && zip ? getUSStateFromZip(zip) : null;
    const fromDerived = deriveUSStateFromProfile(profile);
    if (fromZip && fromDerived && fromZip !== fromDerived) {
        debugLog(`${WD} state zip/profile conflict, zip wins`, fromDerived, '->', fromZip, 'zip=', zip);
        return fromZip;
    }
    const fromJob = getUSStateFromJobLocation();
    if (fromZip && fromJob && fromZip !== fromJob) {
        debugLog(`${WD} state zip/job conflict, zip wins`, fromJob, '->', fromZip, 'zip=', zip);
        return fromZip;
    }
    return fromZip || fromDerived || fromJob || null;
}

function isWorkAuthorizedWithoutSponsorshipQuestion(label) {
    const l = String(label || '').toLowerCase();
    if (/require.*sponsorship|need sponsorship|will you require|future require|sponsorship.*required|require.*visa/i.test(l)) return false;
    return /without.*sponsorship|without the need for sponsorship|legally work unrestricted|work unrestricted|able to legally work.*without|authorized to work.*without|legally authorized.*without/i.test(l);
}

function isWorkdaySponsorshipRequiredQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /require.*sponsorship|need sponsorship|will you require|future require|sponsorship.*required|require.*visa|visa sponsorship|immigration sponsorship/i.test(l);
}

function getWorkdayYesNoSmartDefault(label) {
    const l = String(label || '').toLowerCase();
    if (isWorkdayGpaQuestion(l)) return null;
    if (isWorkdaySmsConsentDropdownField(label)) return getWorkdaySmsConsentCandidates()[0];
    if (isWorkdayPrivacyConsentDropdownField(label)) return getWorkdayPrivacyConsentCandidates()[0];
    const profileAnswer = getProfileDerivedYesNoAnswer(window.__wdApplyData?.profile, l);
    if (profileAnswer) return profileAnswer;
    return getHardcodedYesNoAnswer(l);
}

function markWorkdayLockedYesNoFilled(label) {
    window.__wdLockedYesNoFilled = window.__wdLockedYesNoFilled || new Set();
    window.__wdLockedYesNoFilled.add(normalizeDropdownOpenKey(label));
}

function isWorkdayLockedYesNoField(label) {
    return Boolean(getProfileDerivedYesNoAnswer(window.__wdApplyData?.profile, label))
        || Boolean(getHardcodedYesNoAnswer(label));
}

function isWorkdayYesNoFieldLockedAndFilled(container, label) {
    const key = normalizeDropdownOpenKey(label);
    if (!window.__wdLockedYesNoFilled?.has(key)) return false;
    const profile = window.__wdApplyData?.profile;
    const expected = (profile && getProfileFieldValue(profile, label))
        || getHardcodedYesNoAnswer(label)
        || getWorkdayYesNoSmartDefault(label);
    if (/^(yes|no)$/i.test(String(expected))) {
        return isWorkdayYesNoFilled(container, expected)
            || isWorkdaySingleSelectFilled(container, [expected, String(expected).toLowerCase()]);
    }
    return isWorkdayYesNoFilled(container, 'Yes') || isWorkdayYesNoFilled(container, 'No');
}

async function getWorkdayResumeOnce(data, callSite = '') {
    window.__wdResumeFetchLog = window.__wdResumeFetchLog || [];
    if (window.__wdCachedResume) {
        debugLog(`${WD} getResume CACHE`, callSite, window.__wdCachedResume.originalFilename,
            `priorFetches=${window.__wdResumeFetchLog.length}`);
        return window.__wdCachedResume;
    }
    if (window.__wdResumeFetchPromise) {
        debugLog(`${WD} getResume AWAIT`, callSite);
        return window.__wdResumeFetchPromise;
    }
    debugLog(`${WD} getResume FETCH`, callSite);
    window.__wdResumeFetchPromise = (async () => {
        window.__wdResumeFetchLog.push(callSite);
        const cv = await getResume(data);
        window.__wdCachedResume = cv;
        debugLog(`${WD} getResume DONE`, callSite, cv?.originalFilename,
            `totalFetches=${window.__wdResumeFetchLog.length}`);
        return cv;
    })().finally(() => {
        window.__wdResumeFetchPromise = null;
    });
    return window.__wdResumeFetchPromise;
}

async function waitForReviewPageReady(maxMs = 8000) {
    const t0 = Date.now();
    if (isReviewPageContentReady()) {
        wdTiming.mark('review-page-ready', '0ms immediate');
        return true;
    }
    let delay = 100;
    while (Date.now() - t0 < maxMs) {
        await wait(delay);
        if (isReviewPageContentReady()) {
            wdTiming.mark('review-page-ready', `${Date.now() - t0}ms`);
            return true;
        }
        delay = Math.min(delay + 50, 250);
    }
    debugLog(`${WD} review page wait timeout`, Date.now() - t0, 'ms');
    return false;
}

function isWorkdayVeteranFieldLabel(label) {
    const l = String(label || '').toLowerCase();
    // Long EEO / policy acknowledgments mention "veteran status" but are Agree/Disagree consents
    if (/please read before signing|equal employment opportunities|without regard to an applicant/i.test(l)) {
        return false;
    }
    if (isWorkdayPrivacyConsentDropdownField(label)) return false;
    // "disclose your status as a veteran" reverses the usual "veteran status" word order and doesn't
    // contain "identify as a veteran" or "protected veteran" either — missed entirely by the patterns
    // below, so this field fell through to the generic questions dropdown filler (which only tries a
    // single AI-streamed/smart-default candidate, not the full veteran candidate list) and could never
    // match the tenant's real option text ("I am not a veteran" vs. the single candidate tried). Not
    // tenant-specific: any tenant phrasing the veteran-status question this way hits the same fallthrough
    // (observed on seminolehardrock.wd503).
    // "Are you a veteran?" (boeing.wd1) is the same EEO multi-option list ("I am not a veteran" /
    // "I do not wish to self-identify") — must NOT be treated as binary Yes/No (always-no target=no).
    return /\bidentify as a veteran\b|\bare you a veteran\b|\bveterans?\s+status\b|protected veteran|section 4212|status as a veteran/i.test(l)
        || (/federal government contractor/i.test(l) && /section 4212|veteran/i.test(l));
}

function isWorkdayVeteranFilled(container) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    const fieldLabel = (getContainerLabel(container) || '').replace(/\s+/g, ' ').trim();
    let bodyPreview = preview;
    if (fieldLabel && bodyPreview.toLowerCase().startsWith(fieldLabel.toLowerCase())) {
        bodyPreview = bodyPreview.slice(fieldLabel.length).replace(/^\s*\*?\s*/, '').trim();
    }
    if (/error:.*required|(?:^|\s)select one\b/i.test(bodyPreview)) {
        const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').trim();
        const comboboxValue = (container.querySelector('input[role="combobox"]')?.value || '').trim();
        if ((!selectionLabel || /^select one$/i.test(selectionLabel)) && !comboboxValue) return false;
    }
    const candidates = getWorkdayVeteranCandidates(window.__wdApplyData?.profile);
    return isDisclosureChoiceFilled(container, candidates)
        || isWorkdaySingleSelectFilled(container, candidates);
}

function getWorkdayClearanceCandidates() {
    return [
        'No, never have held a security clearance',
        'No, currently inactive (greater than 24 months)',
        'No, currently inactive (less than 24 months)',
        'None',
        'No Clearance',
        'No Security Clearance',
        'No Active Clearance',
        'Not Applicable',
        'N/A',
        'Other',
        'Public Trust',
    ];
}

function isWorkdayClearanceFieldLabel(label) {
    return /clearance|security clearance/i.test(String(label || ''));
}

function isWorkdayClearanceYesNoQuestion(label) {
    return /do you have.*clearance|have a current.*clearance|currently hold.*clearance/i.test(String(label || '').toLowerCase());
}

function isWorkdayClearanceFilled(container) {
    if (!container) return false;
    if (isWorkdayYesNoFilled(container, 'No') || isWorkdayYesNoFilled(container, 'Yes')) return true;
    return isWorkdaySingleSelectFilled(container, getWorkdayClearanceCandidates())
        || isDisclosureChoiceFilled(container, getWorkdayClearanceCandidates());
}

async function fillWorkdayClearanceField(container, label = '') {
    const labelText = label || getContainerLabel(container);
    const labelLower = labelText.toLowerCase();
    if (isWorkdayClearanceFilled(container)) return true;
    if (isDisclosureLocalFillDone(labelText)) return isWorkdayClearanceFilled(container);
    const openKey = normalizeDropdownOpenKey(labelText);
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        debugLog(`${WD} clearance skip excess opens`, labelText.slice(0, 60), 'count=', wdDropdownOpenCounts[openKey]);
        markDisclosureLocalFilled(labelText);
        return isWorkdayClearanceFilled(container);
    }
    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!control) return false;
    let filled = false;
    if (isWorkdayClearanceYesNoQuestion(labelText)) {
        // Parsons-style: options are "Yes, currently active" / "No, never have held..." — not bare Yes/No.
        clearWorkdaySingleSelectMissKey(labelText);
        resetWorkdayDropdownOpenCount(openKey);
        filled = await fillWorkdaySingleSelectDropdown(control, getWorkdayClearanceCandidates().concat(['No', 'no']), labelLower)
            || await fillWorkdayYesNoField(container, 'No');
    } else {
        clearWorkdaySingleSelectMissKey(labelText);
        filled = await fillWorkdaySingleSelectDropdown(control, getWorkdayClearanceCandidates(), labelLower);
    }
    if (filled || isWorkdayClearanceFilled(container)) {
        markDisclosureLocalFilled(labelText);
        return true;
    }
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        markDisclosureLocalFilled(labelText);
        debugLog(`${WD} clearance give up`, labelText.slice(0, 60));
    }
    return filled;
}

function getWorkdayVeteranCandidates(profile) {
    const mapped = mapProfileVeteranToWorkday(profile?.general?.veteranStatus);
    return [...new Set([mapped, ...getVeteranStatusCandidates()].filter(Boolean))];
}

function markDisclosureLocalFilled(label) {
    window.__wdDisclosureLocalFilled = window.__wdDisclosureLocalFilled || new Set();
    window.__wdDisclosureLocalFilled.add(normalizeDropdownOpenKey(label));
}

function isDisclosureLocalFillDone(label) {
    return Boolean(window.__wdDisclosureLocalFilled?.has(normalizeDropdownOpenKey(label)));
}

async function fillWorkdayVeteranField(container, label = '', profile = window.__wdApplyData?.profile) {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const labelLower = labelText.toLowerCase();
    if (isWorkdayVeteranFilled(container)) return true;
    if (isDisclosureLocalFillDone(labelText) && isWorkdayVeteranFilled(container)) return true;

    const openKey = normalizeDropdownOpenKey(labelText);
    clearWorkdaySingleSelectMissKey(openKey);
    clearWorkdaySingleSelectMissKey('veteran');
    clearWorkdaySingleSelectMissKey('veterans status');
    clearWorkdaySingleSelectMissKey('section 4212');
    resetWorkdayDropdownOpenCount(openKey);
    if ((wdDropdownOpenCounts[openKey] || 0) >= 3) {
        markDisclosureStreamFallback(labelText);
        return isWorkdayVeteranFilled(container);
    }

    const candidates = getWorkdayVeteranCandidates(profile);
    if (isDisclosureChoiceGroup(container)) {
        const ok = await fillWorkdayDisclosureChoiceGroup(container, candidates);
        if (isWorkdayVeteranFilled(container)) {
            markDisclosureLocalFilled(labelText);
            return true;
        }
    }

    const control = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!control) {
        markDisclosureStreamFallback(labelText);
        return false;
    }
    workdayScrollToTarget(container, 120);
    await wait(200);
    const popupHint = /section 4212/i.test(labelLower) ? 'section 4212' : (openKey || 'veteran');
    await fillWorkdayDisclosureSingleSelectDropdown(control, candidates, popupHint);
    let filled = isWorkdayVeteranFilled(container);
    debugLog(`${WD} disclosure veteran fill`, labelText.slice(0, 60), 'verified=', filled);
    if (!filled) {
        resetWorkdayDropdownOpenCount(openKey);
        clearWorkdaySingleSelectMissKey(popupHint);
        clearWorkdaySingleSelectMissKey(openKey);
        const retry = await fillWorkdaySingleSelectDropdown(control, candidates, popupHint);
        filled = isWorkdayVeteranFilled(container);
        debugLog(`${WD} disclosure veteran retry`, labelText.slice(0, 60), 'ok=', retry, 'verified=', filled);
    }
    if (filled) markDisclosureLocalFilled(labelText);
    else markDisclosureStreamFallback(labelText);
    return filled;
}

/** Yes/No dropdown: "Do your salary expectations align with the posted range?" — not a salary bracket picker. */
function isSalaryAlignmentYesNoQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /salary expectation.*align|align.*posted range|expectations.*align.*(?:posted|salary).*range|within the posted (?:salary )?range/i.test(l);
}

function extractPostedSalaryRangeText(label, container = null) {
    const parts = [String(label || '')];
    if (container) parts.push(container.innerText || '');
    const combined = parts.join(' ');
    const m = combined.match(/\$\s*[\d,]+(?:\s*k)?\s*[-–—]\s*\$\s*[\d,]+(?:\s*k)?/i);
    return m ? m[0] : '';
}

function getSalaryAlignmentYesNoAnswer(profile, label, container = null) {
    const amount = getProfileSalaryAmount(profile);
    const bounds = parseSalaryBracketBounds(extractPostedSalaryRangeText(label, container));
    if (bounds) {
        return (amount >= bounds.min && amount <= bounds.max) ? 'Yes' : 'No';
    }
    return 'Yes';
}

function isSalaryAlignmentFieldAcceptable(container, label) {
    const answer = getSalaryAlignmentYesNoAnswer(window.__wdApplyData?.profile || {}, label, container);
    return isWorkdayYesNoFilled(container, answer)
        || isWorkdaySingleSelectFilled(container, [answer, String(answer).toLowerCase()]);
}

async function fillWorkdaySalaryAlignmentField(container, profile, label) {
    const answer = getSalaryAlignmentYesNoAnswer(profile, label, container);
    clearWorkdaySingleSelectMissKey(label);
    debugLog(`${WD} salary alignment fill`, label.slice(0, 60), answer);
    const control = getContainerControl(container);
    if (control) {
        const ok = await fillWorkdaySingleSelectDropdown(control, [answer, String(answer).toLowerCase()], label)
            || await fillWorkdayYesNoField(container, answer);
        if (ok) markWorkdayLockedYesNoFilled(label);
        return ok;
    }
    return fillWorkdayYesNoField(container, answer);
}

function isCompensationFieldLabel(label) {
    const l = String(label || '').toLowerCase();
    if (isSalaryAlignmentYesNoQuestion(l)) return false;
    // W-2/T-4 prior-year wages (hrone.wd1) — numeric compensation-like, not free-text N/A.
    if (/w-?2|t-?4|wages for the previous year|previous year.?s? wages|prior year wages/i.test(l)) return true;
    return /desired base compensation|base compensation|desired compensation|expected compensation|expected salary|salary expectation|compensation expectation|desired salary|desired annualized salary|annualized salary|annual salary|pay expectation|expected pay|target compensation|total annual compensation|desired total annual compensation|total compensation|expectations for total compensation|salary \+ bonus|compensation \(salary|pay rate type|desired pay rate type|pay rate amount|pay expectations|desired pay expectation|monthly gross|gross salary|please include the amount|include the amount|^amount\b/i.test(l)
        && !/non-compete|non-solicit|non-disclosure|conflict.*interest/i.test(l);
}

/**
 * Application Questions fields that must go through streamVacancyFields — local smart-defaults
 * (e.g. fallback "No") misfire on multi-option dropdowns ("No" matches "Non-Speaker").
 */
function isApplicationQuestionStreamField(label) {
    const l = String(label || '').toLowerCase();
    // Years-band selects with a profile-derived answer are local (not AI).
    if (isWorkdayYearsExperienceBandQuestion(l)) return false;
    return /highest level of education|education level|level of education|desired base salary|hourly pay rate|pay rate amount|date available|available for work|lie detector/i.test(l)
        || isCompensationFieldLabel(l);
}

function isWorkdayYearsExperienceBandQuestion(label) {
    const l = String(label || '').toLowerCase();
    // Yes/No qualification checks ("Do you meet the minimum years…?", "Do you have 2+ years of
    // experience working as a behavioral health professional?") are single-select YES/NO controls,
    // not multi-range band dropdowns — matching "years of experience" inside a yes/no-phrased
    // question here misclassified it as a band selector on ANY tenant using this common
    // "Do you have <N>+ years of experience..."-style screening-question wording (observed on
    // humana.wd5, not tenant-specific): the code then tries to force a "6+ years"/"5+ years" style
    // candidate into a dropdown whose real options are just Select one/Yes/No, causing repeated
    // dropdown open/close cycles that never match and leaving the field unfilled — "Workday step
    // stuck: questions". A leading interrogative auxiliary ("do/have/are/is/can/will/did you") is a
    // reliable, tenant-agnostic signal that the question expects a Yes/No answer regardless of the
    // "years of experience" wording inside it.
    if (/do you meet|meet the minimum|indicated on the (?:job )?posting|minimum qualifications/i.test(l)
        || /^\s*(do|have|are|is|can|will|did)\s+you\b/i.test(l)) {
        return false;
    }
    return /how many years|years of experience|years do you have|experience in the|years.*(sales|healthcare|nursing|retail|management)/i.test(l);
}

/** Map profile YOE onto simple threshold options like "Less than 2 years" / "2 years or more". */
function getWorkdayYearsExperienceBandAnswer(label, options, profile = window.__wdApplyData?.profile) {
    if (!isWorkdayYearsExperienceBandQuestion(label)) return null;
    const years = Number(profile?.workingExperienceInYears ?? profile?.working_experience_in_years);
    if (!Number.isFinite(years)) return null;
    let opts = (Array.isArray(options) ? options : []).map(o => String(o || '').trim()).filter(Boolean);
    if (!opts.length) {
        // Common bands when options were not yet enriched (include N+ / N-M retail styles)
        opts = [
            'No experience', 'None', 'Less than 1 year', 'Less than one year', 'Less than 2 years',
            '1 year or more', '2 years or more', 'Less than 3 years', '3 years or more',
            'Less than 5 years', '5 years or more', '5+ years', '6+ years', '4+ years', '3+ years',
            '1-3 years', '2-4 years', '3-6 years', '4-6 years', 'Between 1-3 years', 'Between 3-5 years',
            "Over 5 years' experience", 'Over 5 years experience', 'Over 5 years',
        ];
    }
    let bestAtLeast = null;
    let bestAtLeastN = -1;
    let bestLess = null;
    let bestLessN = Infinity;
    let bestBetween = null;
    let bestBetweenLo = -1;
    for (const o of opts) {
        if (/^select one$|^please select$/i.test(o)) continue;
        if (/^no experience$|^none$|^n\/?a$/i.test(o)) {
            if (years <= 0) return o;
            continue;
        }
        // "6+ years", "5+ Years Experience", "3 years or more", "more than 5 years", "over 5 years"
        const more = o.match(/(\d+)\s*\+\s*years?/i)
            || o.match(/(\d+)\s*years?\s+or\s+more/i)
            || o.match(/(\d+)\s*years?\s*(?:and|&|\+)\s*above/i)
            || o.match(/more than\s+(\d+)/i)
            || o.match(/over\s+(\d+)\s*years?/i);
        if (more) {
            const n = Number(more[1]);
            if (years >= n && n >= bestAtLeastN) {
                bestAtLeast = o;
                bestAtLeastN = n;
            }
            continue;
        }
        const between = o.match(/between\s+(\d+)\s*[-–]\s*(\d+)\s*years?/i)
            || o.match(/(\d+)\s*[-–]\s*(\d+)\s*years?/i);
        if (between) {
            const lo = Number(between[1]);
            const hi = Number(between[2]);
            if (years >= lo && years <= hi && lo >= bestBetweenLo) {
                bestBetween = o;
                bestBetweenLo = lo;
            }
            continue;
        }
        const less = o.match(/less than\s+(?:one|1\b|\d+)/i) || o.match(/under\s+(\d+)/i)
            || o.match(/fewer than\s+(\d+)/i) || o.match(/^0\s*[-–]\s*(\d+)/);
        if (less) {
            let n = Number((less[1] || '').replace(/one/i, '1'));
            if (!Number.isFinite(n) && /less than\s+one/i.test(o)) n = 1;
            if (!Number.isFinite(n)) {
                const m2 = o.match(/less than\s+(\d+)/i);
                n = m2 ? Number(m2[1]) : NaN;
            }
            if (Number.isFinite(n) && years < n && n <= bestLessN) {
                bestLess = o;
                bestLessN = n;
            }
        }
    }
    // Prefer the tightest matching between-band when years fall inside one; else highest "N+" floor.
    if (bestBetween && (!bestAtLeast || bestBetweenLo >= bestAtLeastN)) return bestBetween;
    if (bestAtLeast) return bestAtLeast;
    if (bestBetween) return bestBetween;
    if (bestLess) return bestLess;
    // Prefer highest band when years are high but wording didn't match parsers
    if (years >= 5) {
        const over5 = opts.find(o => /over\s*5|5\s*\+|6\s*\+|more than\s*5|5\s*years?\s+or\s+more/i.test(o));
        if (over5) return over5;
    }
    if (years >= 3) {
        const over3 = opts.find(o => /3\s*\+|3\s*years?\s+or\s+more|3-6\s*years/i.test(o));
        if (over3) return over3;
    }
    return null;
}

function isWorkdayStartAvailabilityBandQuestion(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (!/available to start|when can you start|when are you available|availability to start|how soon can you start/i.test(l)) {
        return false;
    }
    // Explicit calendar-date variants stay on the date path
    if (/date of availability|desired start date|target start date|expected start date|\bstart date\b/i.test(l)
        && !/available to start|when are you available/i.test(l)) {
        return false;
    }
    const preview = String(container?.innerText || '').toLowerCase();
    if (/\b(immediately|1 week|2 weeks|3 weeks|4 weeks)\b/i.test(preview)) return true;
    if (container) {
        const hasDateInput = container.querySelector(
            'input[data-automation-id*="date"], input[placeholder*="/"], input[aria-label*="date" i]'
        );
        const hasList = container.querySelector('[aria-haspopup="listbox"], button[aria-haspopup], [role="combobox"]');
        if (hasList && !hasDateInput) return true;
        if (hasDateInput && !hasList) return false;
    }
    // Default for "available to start" labels: week-band select (ALS Global etc.)
    return /available to start|when are you available|how soon can you start/i.test(l);
}

function getWorkdayStartAvailabilityBandCandidates() {
    return [
        '2 weeks', 'Immediately', '1 week', '3 weeks', '4 weeks or more',
        'Within 2 weeks', 'Within two weeks', 'ASAP', 'Immediate',
    ];
}

async function fillWorkdayStartAvailabilityBandField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const cands = getWorkdayStartAvailabilityBandCandidates();
    if (isWorkdaySingleSelectFilled(container, cands)) return true;
    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!ctrl) return false;
    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(labelText || '')));
    const ok = await fillWorkdaySingleSelectDropdown(ctrl, cands, String(labelText || '').slice(0, 80));
    debugLog(`${WD} start-availability band`, String(labelText || '').slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, cands);
}

function isLikelyYesNoDropdown(container, labelLower) {
    if (getHardcodedYesNoAnswer(labelLower)) return true;
    if (isWorkdayPrivacyConsentDropdownField(labelLower, container)) return false;
    if (container?.querySelector('input[type="radio"]')) return true;
    const preview = (container?.innerText || '').toLowerCase();
    if (/i agree/i.test(preview) && /i do not agree/i.test(preview)) return false;
    return /\byes\b/.test(preview) && /\bno\b/.test(preview);
}

function shouldStreamWorkdayQuestionField(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (isWorkdayPrivacyConsentDropdownField(label, container)) return false;
    if (containerPreviewHasAgreeDisagreePair(container)) return false;
    if (isWorkdayGpaQuestion(l)) return false;
    if (/my proficiency with|proficiency with (?:google|microsoft)|google workspace|microsoft office/i.test(l)) return false;
    if (/right to work status|additional details about your right to work/i.test(l)) return false;
    if (/do you have the (?:legal )?right to work|legal right to work/i.test(l)) return false;
    if (/require any adjustments|disability confident scheme|considered under the dcs|\bunder the dcs\b/i.test(l)) return false;
    if (/isle of man|born on the island|license enabling you to work in the isle|how long have you lived there/i.test(l)) return false;
    if (/which region are you willing to work|region are you willing to work in/i.test(l)) return false;
    if (/i confirm that i have read the above statement|information provided is correct to the best of my knowledge/i.test(l)) return false;
    if (isWorkdayStartAvailabilityBandQuestion(l, container)) return false;
    if (isGenpactAiMatchingOptInField(l)) return false;
    if (isWorkdayClinicalSettingsQuestion(l)) return false;
    if (isWorkdayShiftAvailabilityQuestion(l)) return false;
    if (isWorkdayEmploymentTypeQuestion(l)) return false;
    if (isWorkdayBestContactTimeQuestion(l)) return false;
    if (isWorkdayNaIfNoTextField(l)) return false;
    if (isWorkdayAlwaysNoQuestion(l)) return false;
    // Hybrid/office attendance Yes/No — local Yes (getHardcodedYesNoAnswer); do not burn stream budget
    if (/hybrid work model|days in the office|work in the office location|ability to work in the office/i.test(l)) {
        return false;
    }
    if (isWorkdayFormerEmployerAffiliateTextField(l)) return false;
    if (isWorkdayFormerEmployerTextFollowUp(l)) return false;
    const stepKey = typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : '';
    const onQuestionsStep = stepKey === 'questions' || isApplicationQuestionStreamField(l);
    if (!onQuestionsStep) return false;

    if (/proficiency|fluency/i.test(l) && (/english|language|indicate your proficiency/i.test(l))) {
        return true;
    }
    // Years-of-experience bands (Less than N / N or more) are answered from profile locally —
    // do not force-stream; stream miss + max-calls left these empty (Abbott sales years).

    const profile = window.__wdApplyData?.profile;
    const kv = profile ? getProfileFieldValue(profile, label) : null;
    if (kv !== null && kv !== undefined && kv !== '') {
        // Profile already has a mapped answer — fill locally, never stream
        return false;
    }
    if (isWorkdayYearsExperienceBandQuestion(l) && getWorkdayYearsExperienceBandAnswer(l, null, profile)) {
        return false;
    }

    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    const ctrl = getContainerControl(container);
    const isEmptyDropdown = (/select one|0 items selected/i.test(preview)
        || (ctrl && (ctrl.tagName === 'BUTTON' || ctrl.getAttribute('aria-haspopup') === 'listbox')))
        && !container.querySelector('textarea')
        && !container.querySelector('input[type="radio"]');
    if (!isEmptyDropdown || !isContainerRequired(container)) return false;

    if (getHardcodedYesNoAnswer(l)) return false;
    if (isWorkdayTotalHoursPerWeekField(l)) return false;
    if (/select all that apply/i.test(l)
        && /availability|available to work|indicate your availability|shifts?\b/i.test(l)) {
        return false;
    }
    if (isWorkdayShiftAvailabilityQuestion(l)) return false;
    if (/read carefully before signing|significant matters in connection with your application/i.test(l)) {
        return false;
    }
    if (/united states armed (?:forces|services)|served in the (?:u\.?s\.?|united states) armed/i.test(l)) {
        return false;
    }

    if (isWorkdayGenderIdentityField(l) || isWorkdayDisclosureGenderField(l)) {
        return false;
    }

    if (/pay rate type|travel.*percentage|preferred location/i.test(l)) {
        return false;
    }
    if (isCompensationFieldLabel(l)) return false;
    if (/ethnicity|race|hispanic/i.test(l)) return false;
    // DaVita conditional follow-up after "place of work" = Healthcare — fill locally from profile
    if (/non-?dialysis healthcare/i.test(l)) return false;
    if (isWorkdayAdditionalDetailsTextField(l)) return false;
    if (isWorkdayNotToMyKnowledgeLabel(l) || /family member.*works for|close family member.*employed/i.test(l)) return false;
    return true;
}

/** Approximate FX → USD for Workday $ salary brackets (local currencies often stored as IND/INR etc.). */
const WORKDAY_SALARY_TO_USD = {
    usd: 1, us: 1, '$': 1,
    inr: 1 / 83, ind: 1 / 83, rs: 1 / 83, '₹': 1 / 83,
    eur: 1.08, gbp: 1.27, cad: 0.74, aud: 0.66,
    sgd: 0.74, aed: 0.27, sar: 0.27, php: 0.018, mxn: 0.055,
    brl: 0.18, zar: 0.055, jpy: 0.0067, cny: 0.14, hkd: 0.13,
    pln: 0.25, chf: 1.12, sek: 0.095, nok: 0.092, dkk: 0.145,
};

function getProfileSalaryCurrency(profile) {
    const general = profile?.general || {};
    return String(
        general.expectedAnnualSalaryCurrency
        ?? profile?.expectedAnnualSalaryCurrency
        ?? general.currentAnnualSalaryCurrency
        ?? profile?.currentAnnualSalaryCurrency
        ?? ''
    ).trim().toLowerCase();
}

function convertSalaryAmountToUsd(amount, currency) {
    const n = Number(amount);
    if (!Number.isFinite(n) || n <= 0) return 85000;
    const cur = String(currency || '').trim().toLowerCase();
    if (!cur || cur === 'usd' || cur === 'us' || cur === '$') return n;
    const rate = WORKDAY_SALARY_TO_USD[cur];
    if (rate != null && rate !== 1) {
        const usd = Math.round(n * rate);
        debugLog(`${WD} salary FX`, n, cur, '→', usd, 'USD');
        return Math.max(1, usd);
    }
    // Unknown currency but amount looks like local (e.g. 2e6) — treat as non-USD and cap for brackets
    if (n >= 500000) {
        const usd = Math.round(n / 83);
        debugLog(`${WD} salary FX heuristic`, n, cur || '?', '→', usd, 'USD');
        return Math.max(1, usd);
    }
    return n;
}

function getProfileSalaryAmount(profile) {
    const general = profile?.general || {};
    const expected = general.expectedAnnualSalary ?? profile?.expectedAnnualSalary;
    const current = general.currentAnnualSalary ?? profile?.currentAnnualSalary;
    const raw = (expected != null && Number(expected) > 0)
        ? Number(expected)
        : (current != null && Number(current) > 0 ? Number(current) : 85000);
    return convertSalaryAmountToUsd(raw, getProfileSalaryCurrency(profile));
}

/** Raw profile salary in stored currency (for INR/LPA bracket matching). */
function getProfileSalaryAmountLocal(profile) {
    const general = profile?.general || {};
    const expected = general.expectedAnnualSalary ?? profile?.expectedAnnualSalary;
    if (expected != null && Number(expected) > 0) return Number(expected);
    const current = general.currentAnnualSalary ?? profile?.currentAnnualSalary;
    if (current != null && Number(current) > 0) return Number(current);
    return 85000;
}

/** Single numeric dollar amount for text/number salary inputs (not dropdown range bands). */
function isHourlyCompensationLabel(label) {
    const l = String(label || '').toLowerCase();
    // Follow-up amount after Hourly/Annual type often lacks "hourly" in the label
    if (/please include the amount|include the amount|^amount\b/.test(l)) {
        const hay = `${l} ${window.__wdHistoryRole || ''} ${location.href}`.toLowerCase();
        if (/part[\s-]?time|hourly|warehouse|order selector|retail/i.test(hay)) return true;
    }
    return /hourly rate|hourly pay|hourly wage|pay per hour|per hour|salary\/hourly|\bpay rate\b.*hour|\bhourly\b/.test(l);
}

function isWorkdayPayRateTypeOnlyOptions(options) {
    const texts = (options || [])
        .map(o => optionText(o))
        .map(t => String(t || '').replace(/\s+/g, ' ').trim())
        .filter(t => t && !/^select one$/i.test(t));
    if (texts.length < 1 || texts.length > 6) return false;
    return texts.every(t => /^(hourly|annual(?:\s+salary)?|yearly|salary|per hour|monthly(?:\s+salary)?)\b/i.test(t));
}

function getWorkdayPayRateTypeCandidates(profile = null, label = '') {
    const hay = `${label} ${window.__wdHistoryRole || ''} ${location.href}`.toLowerCase();
    const preferHourly = /part[\s-]?time|hourly|warehouse|order selector|retail associate/i.test(hay);
    if (preferHourly) {
        return ['Hourly', 'Hourly Rate', 'Per Hour', 'Annual Salary', 'Annual', 'Yearly', 'Salary'];
    }
    return ['Annual Salary', 'Annual', 'Yearly', 'Salary', 'Hourly', 'Hourly Rate', 'Per Hour'];
}

function getWorkdayNumericSalaryValue(profile, label = '', element = null) {
    // Numeric inputs expect the profile's stored currency amount (INR stays INR).
    // USD conversion is only for $ dropdown brackets via getProfileSalaryAmount().
    const amount = Math.round(getProfileSalaryAmountLocal(profile));
    const raw = String(label || '').toLowerCase();
    const maxLen = element?.maxLength > 0 ? element.maxLength : null;
    if (maxLen && maxLen <= 4 && amount >= 1000) {
        return String(Math.round(amount / 1000));
    }
    const digits = String(element?.value || '').replace(/[^\d]/g, '');
    if (element?.value && digits) {
        const n = Number(digits);
        if (Number.isFinite(n) && n > 0 && n <= 99999999 && digits.length <= 8) {
            if (isHourlyCompensationLabel(raw) && n > 500) {
                return String(Math.max(12, Math.min(75, Math.round(n / 2080))));
            }
            if (amount >= 10000 && n < amount / 10) {
                debugLog(`${WD} salary ignore stale field value`, n, 'profile=', amount);
            } else {
                return String(n);
            }
        }
    }
    if (/monthly/i.test(raw) && !/annual/i.test(raw)) {
        return String(Math.max(1000, Math.round(amount / 12)));
    }
    if (isHourlyCompensationLabel(raw)
        || /(?:hourly\/annual|hourly\s*\/\s*annual|\bhourly\b.*\bannual\b|pay rate.*hour|per hour)/i.test(raw)) {
        const hourly = Math.max(12, Math.min(75, Math.round(amount / 2080)));
        return String(hourly);
    }
    return String(amount);
}

function isNumericCompensationField(label, element = null) {
    const l = String(label || '').toLowerCase();
    if (!isCompensationFieldLabel(l)) return false;
    const container = element?.closest?.('[data-automation-id*="formField"]') || element?.closest?.('[data-automation-id*="FormField"]');
    const preview = (container?.innerText || '').toLowerCase();
    // Explicit dropdown chrome → not numeric
    if (element?.getAttribute('aria-haspopup') === 'listbox' || element?.getAttribute('role') === 'combobox') return false;
    if (element?.tagName === 'BUTTON') return false;
    if (container?.querySelector('button[aria-haspopup="listbox"], [data-automation-id="promptSelectionLabel"], [data-automation-id="multiselectInputContainer"]')) {
        return false;
    }
    if (/select one|0 items selected/i.test(preview)
        && container?.querySelector('button, [role="combobox"], [aria-haspopup="listbox"]')) {
        return false;
    }
    if (element?.type === 'number') return true;
    if (element?.tagName === 'TEXTAREA') {
        if (isCompensationExpectationsNarrative(l)) return false;
        return /desired salary|expected salary|what is your.*salary|salary expectation|compensation|pay expectation|gross salary|base salary/i.test(l);
    }
    if (element?.tagName === 'INPUT' && (element.type === 'text' || element.type === '' || !element.type || element.type === 'tel')) {
        return /pay rate amount|pay expectations|desired pay expectation|nearest dollar|hourly pay expectation|hourly\/annual|salary expectations|hourly rate|salary\/hourly|please include the amount|include the amount|enter.*amount|compensation amount|salary amount|monthly gross|gross salary|annual or monthly|base salary expectation|desired salary|expected salary|what is your.*salary|salary expectation|desired compensation|expected compensation|desired base compensation/i.test(l);
    }
    if (/monthly/i.test(l) && !/annual/i.test(l)) return true;
    if (/hourly\/annual|salary expectations|hourly rate|salary\/hourly/i.test(l)) return true;
    if (!element) {
        return /pay rate amount|pay expectations|desired pay expectation|nearest dollar|hourly pay expectation|hourly\/annual|salary expectations|hourly rate|salary\/hourly|enter.*amount|compensation amount|salary amount|monthly gross|gross salary|desired salary|expected salary|what is your.*salary/i.test(l);
    }
    return false;
}

function shouldUseNumericCompensation(label, element = null) {
    const l = String(label || '').toLowerCase();
    if (!isCompensationFieldLabel(l)) return false;
    if (isNumericCompensationField(l, element)) return true;
    if (isHourlyCompensationLabel(l) && element?.tagName === 'INPUT') return true;
    // Plain text/number input with no dropdown chrome → numeric even for generic salary labels
    if (element && element.tagName === 'INPUT'
        && (element.type === 'text' || element.type === 'number' || element.type === 'tel' || element.type === '' || !element.type)
        && !element.getAttribute('aria-haspopup')
        && element.getAttribute('role') !== 'combobox') {
        const container = element.closest?.('[data-automation-id*="formField"]');
        const hasDropdownChrome = !!container?.querySelector(
            'button[aria-haspopup="listbox"], [data-automation-id="promptSelectionLabel"], [data-automation-id="multiselectInputContainer"]'
        );
        if (!hasDropdownChrome) return true;
    }
    if (element && element.tagName === 'INPUT'
        && (element.type === 'text' || element.type === 'number' || element.type === 'tel')
        && !element.getAttribute('aria-haspopup')
        && element.getAttribute('role') !== 'combobox'
        && /monthly|gross|enter.*amount|nearest dollar|desired salary|expected salary/i.test(l)) {
        return true;
    }
    return false;
}

function isCompensationFieldAcceptable(container, label, element) {
    const preview = (container?.innerText || '').replace(/\s+/g, ' ');
    if (/error:.*required/i.test(preview)) return false;
    if (container?.querySelector('input[type="radio"]:checked, [role="radio"][aria-checked="true"]')) {
        const amount = getProfileSalaryAmount(window.__wdApplyData?.profile || {});
        const local = getProfileSalaryAmountLocal(window.__wdApplyData?.profile || {});
        if (salaryAmountFitsPreviewBracket(preview, amount) || salaryAmountFitsPreviewBracket(preview, local)) {
            return true;
        }
        // Any checked salary radio counts as filled (required satisfied)
        return true;
    }
    // Hourly / Annual Salary type already committed (Sysco two-step compensation)
    const selected = getWorkdayFieldSelectedText(container) || '';
    if (/\b(hourly|annual salary|annual|yearly)\b/i.test(selected)
        && !/^select one$/i.test(selected.trim())
        && !/\$\s*\d|please include the amount/i.test(selected)) {
        return true;
    }
    if (shouldUseNumericCompensation(label, element) || /please include the amount|include the amount|^amount\b/i.test(String(label || ''))) {
        const val = (element?.value || '').trim();
        const digits = val.replace(/\D/g, '');
        if (isHourlyCompensationLabel(label) || /please include the amount/i.test(String(label || ''))) {
            const n = Number(digits);
            // Hourly amount after selecting Hourly type
            if (n >= 10 && n <= 250) return true;
        }
        return Boolean(digits) && digits.length <= 8 && !/–|—/.test(val);
    }
    const candidates = getSalaryRangeCandidates(getProfileSalaryAmount(window.__wdApplyData?.profile || {}));
    if (isWorkdaySingleSelectFilled(container, candidates)) return true;
    const amount = getProfileSalaryAmount(window.__wdApplyData?.profile || {});
    return salaryAmountFitsPreviewBracket(preview, amount);
}

function getWorkdayCompensationOpenTrigger(fieldRoot, combobox) {
    return fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"] button')
        || fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
        || fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
        || fieldRoot.querySelector('[data-automation-id="promptArrow"]')
        || fieldRoot.querySelector('[data-automation-id="promptIcon"]')
        || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
        || fieldRoot.querySelector('button[aria-haspopup="true"]')
        || fieldRoot.querySelector('[aria-haspopup="listbox"]')
        || fieldRoot.querySelector('[aria-haspopup="true"]')
        || fieldRoot.querySelector('[role="combobox"]')
        || combobox
        || fieldRoot.querySelector('button')
        || getWorkdayDropdownTrigger(fieldRoot);
}

async function openWorkdayCompensationPopup(fieldRoot, labelLower) {
    const combobox = fieldRoot.querySelector('input[role="combobox"]')
        || fieldRoot.querySelector('[role="combobox"]');
    const openTrigger = getWorkdayCompensationOpenTrigger(fieldRoot, combobox);
    if (!openTrigger) {
        debugLog(`${WD} compensation no trigger`, labelLower.slice(0, 60));
        return null;
    }
    const dump = {
        trigger: openTrigger.tagName,
        auto: openTrigger.getAttribute('data-automation-id') || '',
        role: openTrigger.getAttribute('role') || '',
        haspopup: openTrigger.getAttribute('aria-haspopup') || '',
        ariaControls: openTrigger.getAttribute('aria-controls') || '',
        preview: (fieldRoot.innerText || '').replace(/\s+/g, ' ').slice(0, 120),
    };
    debugLog(`${WD} compensation open dump`, JSON.stringify(dump));
    await closeWorkdayPopups();
    await wait(300);
    workdayScrollToTarget(openTrigger, 120);
    trackWorkdayDropdownOpen(normalizeDropdownOpenKey(labelLower || 'desired salary'));
    await workdayClick(openTrigger);
    let popup = null;
    for (let i = 0; i < 10; i++) {
        await wait(350);
        popup = findPopupNearField(fieldRoot, labelLower);
        if (popup && !isWrongPopupForField(popup, labelLower)) {
            const opts = getSingleSelectDropdownOptions(popup, false);
            if (opts.length > 0) {
                debugLog(`${WD} compensation popup ready`, 'poll=', i + 1, 'opts=', opts.length);
                return popup;
            }
        }
        popup = findActiveWorkdayPopup();
        if (popup) {
            const opts = getSingleSelectDropdownOptions(popup, false);
            if (opts.length > 0) {
                debugLog(`${WD} compensation active popup`, 'poll=', i + 1, 'opts=', opts.length);
                return popup;
            }
        }
    }
    const visiblePopups = [...document.querySelectorAll(
        '[data-automation-id="activeListContainer"], [data-automation-id="wd-MenuList"], [data-automation-id="promptOptions"], ul[role="listbox"], div[role="listbox"], [data-automation-id="promptOptionList"]'
    )].filter(isVisibleElement);
    debugLog(`${WD} compensation popup miss`, 'visiblePopups=', visiblePopups.length,
        visiblePopups.map(p => p.getAttribute('data-automation-id') || p.getAttribute('role') || p.tagName).slice(0, 5));
    return popup;
}

function getCompensationRadioOptions(container) {
    const radios = [...container.querySelectorAll('input[type="radio"], [role="radio"]')];
    return radios.map(radio => {
        const labelEl = radio.closest('label')
            || (radio.id ? container.querySelector(`label[for="${CSS.escape(radio.id)}"]`) : null)
            || radio.parentElement;
        const text = (labelEl?.innerText || radio.getAttribute('aria-label') || radio.value || '')
            .replace(/\s+/g, ' ').trim();
        return { el: radio, text, textLower: text.toLowerCase() };
    }).filter(o => o.textLower && !/^select one$/i.test(o.textLower));
}

async function fillWorkdayCompensationRadioGroup(container, profile, label) {
    const options = getCompensationRadioOptions(container);
    if (options.length < 2) return false;
    const usdAmount = getProfileSalaryAmount(profile);
    const localAmount = getProfileSalaryAmountLocal(profile);
    debugLog(`${WD} compensation radio options`, options.slice(0, 12).map(o => o.textLower));
    // Reuse bracket matcher against synthetic option nodes
    const fakeOpts = options.map(o => {
        const span = document.createElement('span');
        span.textContent = o.text;
        span.__wdRadio = o.el;
        return span;
    });
    const match = findSalaryBracketDropdownMatch(fakeOpts, usdAmount, localAmount);
    let radio = match?.__wdRadio || null;
    if (!radio) {
        const candidates = getSalaryRangeCandidates(usdAmount).map(c => String(c).toLowerCase());
        for (const c of candidates) {
            const hit = options.find(o => o.textLower === c || o.textLower.includes(c) || c.includes(o.textLower));
            if (hit) { radio = hit.el; break; }
        }
    }
    if (!radio && options.length) {
        // Closest already handled in findSalaryBracketDropdownMatch; last resort: middle option
        radio = options[Math.floor(options.length / 2)]?.el;
    }
    if (!radio) return false;
    const picked = options.find(o => o.el === radio);
    debugLog(`${WD} compensation radio pick`, picked?.text || '', 'usd=', usdAmount, 'local=', localAmount);
    workdayScrollToTarget(radio, 80);
    const clickTargets = [
        radio,
        radio.closest('label'),
        radio.parentElement,
    ].filter(Boolean);
    for (const t of clickTargets) {
        workdayClickElement(t);
        await wait(300);
        if (typeof t.click === 'function') t.click();
        await wait(300);
        if (container.querySelector('input[type="radio"]:checked, [role="radio"][aria-checked="true"]')) {
            return true;
        }
    }
    return !!container.querySelector('input[type="radio"]:checked');
}

function dumpCompensationFieldDom(container, label) {
    try {
        const nodes = [...container.querySelectorAll('input, button, select, textarea, [role="combobox"], [role="listbox"], [role="radio"], [data-automation-id]')]
            .slice(0, 20)
            .map(el => ({
                tag: el.tagName,
                type: el.getAttribute('type') || '',
                role: el.getAttribute('role') || '',
                auto: el.getAttribute('data-automation-id') || '',
                haspopup: el.getAttribute('aria-haspopup') || '',
                name: (el.getAttribute('name') || '').slice(0, 40),
                text: (el.innerText || el.value || '').replace(/\s+/g, ' ').slice(0, 40),
            }));
        debugLog(`${WD} compensation DOM dump`, label.slice(0, 50), JSON.stringify(nodes));
    } catch (e) {
        debugLog(`${WD} compensation DOM dump failed`, String(e));
    }
}

async function fillWorkdayCompensationField(container, profile, label) {
    const labelLower = String(label || '').toLowerCase();
    const control = getContainerControl(container);

    // Follow-up numeric amount after Hourly/Annual type (Sysco "Please include the amount.")
    if (/please include the amount|include the amount|^amount\b/i.test(labelLower)) {
        if (!control) return false;
        const numVal = getWorkdayNumericSalaryValue(profile, 'hourly rate', control);
        debugLog(`${WD} compensation amount follow-up`, label.slice(0, 60), numVal);
        return commitWorkdayNumericInput(control, numVal, label);
    }

    // Type already selected — don't reopen; fill amount sibling if empty
    const selectedAlready = getWorkdayFieldSelectedText(container) || '';
    if (/\b(hourly|annual salary|annual|yearly)\b/i.test(selectedAlready) && !/^select one$/i.test(selectedAlready.trim())) {
        debugLog(`${WD} compensation type already set`, selectedAlready.slice(0, 40));
        for (const sibling of getWorkdayFieldContainers()) {
            const sibLabel = getContainerLabel(sibling);
            if (!/please include the amount|include the amount|^amount\b/i.test(sibLabel)) continue;
            const sibCtrl = getContainerControl(sibling);
            if (!sibCtrl || (sibCtrl.value || '').trim()) continue;
            const numVal = getWorkdayNumericSalaryValue(profile, 'hourly rate', sibCtrl);
            debugLog(`${WD} compensation fill amount sibling`, numVal);
            await commitWorkdayNumericInput(sibCtrl, numVal, sibLabel);
        }
        return true;
    }

    if (!control) {
        dumpCompensationFieldDom(container, label);
        // Radio-only groups may have no "control" matching getContainerControl selectors first pass
        if (container.querySelector('input[type="radio"], [role="radio"]')) {
            return fillWorkdayCompensationRadioGroup(container, profile, label);
        }
        return false;
    }
    dumpCompensationFieldDom(container, label);

    // Radio salary bands (common on Mastercard / India Workday)
    if (control.type === 'radio' || container.querySelectorAll('input[type="radio"]').length >= 2) {
        const ok = await fillWorkdayCompensationRadioGroup(container, profile, label);
        if (ok) return true;
    }

    // Narrative "compensation expectations" textareas reject bare digits — use a short sentence.
    if (control.tagName === 'TEXTAREA' && isCompensationExpectationsNarrative(labelLower)) {
        const narrative = getCompensationExpectationsNarrativeValue(profile);
        const current = (control.value || '').trim();
        if (current.length >= 20 && !/error:.*required/i.test(container.innerText || '')) {
            debugLog(`${WD} compensation narrative already filled`, label.slice(0, 60));
            return true;
        }
        debugLog(`${WD} compensation narrative fill`, label.slice(0, 60), narrative.slice(0, 60));
        workdayScrollToTarget(control, 120);
        await workdayTypeElement(control, narrative);
        control.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
        control.dispatchEvent(new Event('blur', { bubbles: true, composed: true }));
        await wait(400);
        return (control.value || '').trim().length >= 10
            && !/error:.*required/i.test((container.innerText || '').toLowerCase());
    }

    const numericInput = (control.tagName === 'INPUT'
            && (control.type === 'number' || control.type === 'text' || control.type === '' || control.type === 'tel')
            && !control.getAttribute('aria-haspopup')
            && control.getAttribute('role') !== 'combobox')
        || control.tagName === 'TEXTAREA';
    const hasDropdownChrome = !!container.querySelector(
        'button[aria-haspopup="listbox"], button[aria-haspopup="true"], [data-automation-id="promptSelectionLabel"], [data-automation-id="multiselectInputContainer"], [data-automation-id="promptIcon"], [aria-haspopup="listbox"]'
    );
    // Text/number/textarea salary with no dropdown chrome → always numeric (Mastercard "desired salary")
    if (numericInput && !hasDropdownChrome) {
        const numVal = getWorkdayNumericSalaryValue(profile, label, control);
        const digitsMatch = (control.value || '').replace(/\D/g, '') === String(numVal).replace(/\D/g, '')
            && (control.value || '').trim();
        if (digitsMatch && isCompensationFieldAcceptable(container, label, control)) {
            debugLog(`${WD} compensation already filled`, label.slice(0, 60), control.value);
            return true;
        }
        debugLog(`${WD} compensation numeric fill (plain input)`, label.slice(0, 60), numVal,
            'tag=', control.tagName, 'type=', control.type || 'textarea',
            'hadValue=', Boolean((control.value || '').trim()),
            'acceptable=', isCompensationFieldAcceptable(container, label, control));
        return commitWorkdayNumericInput(control, numVal, label);
    }
    if (shouldUseNumericCompensation(labelLower, control)
        || (numericInput && /hourly\/annual|salary expectations|desired salary|expected salary/i.test(labelLower))) {
        const numVal = getWorkdayNumericSalaryValue(profile, label, control);
        debugLog(`${WD} compensation numeric fill`, label.slice(0, 60), numVal);
        return commitWorkdayNumericInput(control, numVal, label);
    }
    if (/pay rate type|desired pay rate type/i.test(labelLower)) {
        return fillWorkdaySingleSelectDropdown(control, ['Annual Salary', 'annual salary', 'Annual'], labelLower);
    }
    if (shouldUseNumericCompensation(labelLower, control)) {
        const numVal = getWorkdayNumericSalaryValue(profile, label, control);
        debugLog(`${WD} compensation numeric fill`, label.slice(0, 60), numVal);
        return commitWorkdayNumericInput(control, numVal, label);
    }

    const usdAmount = getProfileSalaryAmount(profile);
    const localAmount = getProfileSalaryAmountLocal(profile);
    const candidates = getSalaryRangeCandidates(usdAmount);
    debugLog(`${WD} compensation dropdown fill`, label.slice(0, 60), candidates[0], 'usd=', usdAmount, 'local=', localAmount);
    const openKey = normalizeDropdownOpenKey(labelLower);
    resetWorkdayDropdownOpenCount(labelLower.slice(0, 80));
    if (/desired salary|salary expectation/i.test(labelLower)) {
        resetWorkdayDropdownOpenCount('desired salary');
    }
    window.__wdSingleSelectMissKeys?.delete(openKey);
    window.__wdSingleSelectMissKeys?.delete(normalizeDropdownOpenKey('desired salary'));

    // Prefer open → collect options → match by amount (avoids wrong $2M INR-as-USD strings)
    if (isCompensationFieldAcceptable(container, label, control)) return true;
    const popup = await openWorkdayCompensationPopup(container, labelLower);
    if (popup) {
        const options = getSingleSelectDropdownOptions(popup, false);
        debugLog(`${WD} compensation options`, options.slice(0, 12).map(o => optionText(o)));
        // Sysco etc.: first dropdown is Hourly vs Annual Salary — not a dollar bracket.
        if (isWorkdayPayRateTypeOnlyOptions(options)) {
            const typeCands = getWorkdayPayRateTypeCandidates(profile, label);
            debugLog(`${WD} compensation pay-rate-type options`, typeCands[0]);
            await closeWorkdayPopups();
            const typeOk = await fillWorkdaySingleSelectDropdown(control, typeCands, labelLower);
            if (typeOk) {
                await wait(600);
                // Follow-up amount field may appear after type is chosen
                for (const sibling of getWorkdayFieldContainers()) {
                    const sibLabel = getContainerLabel(sibling);
                    if (sibling === container) continue;
                    if (!isCompensationFieldLabel(sibLabel)) continue;
                    if (isCompensationFieldAcceptable(sibling, sibLabel, getContainerControl(sibling))) continue;
                    if (/pay rate type|hourly|annual salary/i.test(sibLabel) && isWorkdaySingleSelectFilled(sibling, typeCands)) continue;
                    debugLog(`${WD} compensation fill follow-up amount`, sibLabel.slice(0, 60));
                    await fillWorkdayCompensationField(sibling, profile, sibLabel);
                }
            }
            return typeOk || isCompensationFieldAcceptable(container, label, control);
        }
        let match = findSalaryBracketDropdownMatch(options, usdAmount, localAmount);
        if (!match) {
            for (const c of candidates) {
                const t = String(c).toLowerCase();
                match = options.find(o => optionText(o) === t)
                    || options.find(o => optionText(o).includes(t) || t.includes(optionText(o)));
                if (match) break;
            }
        }
        if (match) {
            const targetLabel = optionText(match);
            debugLog(`${WD} compensation bracket pick`, targetLabel, 'usd=', usdAmount);
            const combobox = container.querySelector('input[role="combobox"]') || control;
            workdayClickElement(match);
            await wait(400);
            if (typeof match.click === 'function') match.click();
            await wait(400);
            await commitWorkdayComboboxSelection(container, combobox, match, targetLabel);
            await closeWorkdayPopups();
            if (isCompensationFieldAcceptable(container, label, control)
                || isWorkdaySingleSelectFilled(container, [targetLabel, ...candidates])) {
                return true;
            }
        } else {
            await closeWorkdayPopups();
        }
    } else if (numericInput) {
        // No dropdown popup found — fall back to typing local amount
        const numVal = getWorkdayNumericSalaryValue(profile, label, control);
        debugLog(`${WD} compensation fallback numeric after popup miss`, label.slice(0, 60), numVal);
        return commitWorkdayNumericInput(control, numVal, label);
    } else if (container.querySelector('input[type="radio"]')) {
        return fillWorkdayCompensationRadioGroup(container, profile, label);
    }

    // Last resort: use control itself as open trigger
    if (control && !getWorkdayCompensationOpenTrigger(container, null)) {
        debugLog(`${WD} compensation try control as trigger`, control.tagName, control.getAttribute('data-automation-id') || control.type || '');
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(control);
        await wait(1500);
        const popup2 = findPopupNearField(container, labelLower) || findActiveWorkdayPopup();
        if (popup2) {
            const options = getSingleSelectDropdownOptions(popup2, false);
            debugLog(`${WD} compensation control-trigger options`, options.slice(0, 12).map(o => optionText(o)));
            const match = findSalaryBracketDropdownMatch(options, usdAmount, localAmount);
            if (match) {
                workdayClickElement(match);
                await wait(500);
                await closeWorkdayPopups();
                if (isCompensationFieldAcceptable(container, label, control)
                    || isWorkdaySingleSelectFilled(container, [optionText(match), ...candidates])) {
                    return true;
                }
            }
            await closeWorkdayPopups();
        }
    }

    return fillWorkdaySingleSelectDropdown(control, candidates, labelLower);
}

function normalizeWorkdaySalaryInputValue(value, profile, label = '', element = null) {
    if (shouldUseNumericCompensation(label, element)) {
        return getWorkdayNumericSalaryValue(profile, label, element);
    }
    const str = String(value ?? '').trim();
    const digits = str.replace(/[^\d]/g, '');
    const n = Number(digits);
    if (isHourlyCompensationLabel(label) && Number.isFinite(n) && n > 500) {
        return String(Math.max(12, Math.min(75, Math.round(n / 2080))));
    }
    if (digits.length > 7 || /–|—/.test(str) || (str.match(/\$/g) || []).length > 1) {
        return getWorkdayNumericSalaryValue(profile, label, element);
    }
    return value;
}

function formatWorkdaySalaryRange(amount) {
    const n = Number(amount) || 85000;
    if (n < 25000) return 'Under $25,000';
    if (n < 30000) return '$25,000-$29,999';
    if (n < 35000) return '$30,000-$34,999';
    if (n < 40000) return '$35,000-$39,999';
    if (n < 45000) return '$40,000-$44,999';
    if (n < 55000) return '$45,000-$54,999';
    if (n < 65000) return '$55,000-$64,999';
    if (n < 75000) return '$65,000-$74,999';
    if (n < 90000) return '$75,000-$89,999';
    if (n < 100000) return '$90,000-$99,999';
    if (n < 110000) return '$100,000-$109,999';
    if (n < 125000) return '$110,000-$124,999';
    if (n < 150000) return '$125,000-$149,999';
    if (n < 175000) return '$150,000-$174,999';
    if (n < 200000) return '$175,000-$199,999';
    if (n < 225000) return '$200,000-$224,999';
    if (n < 250000) return '$225,000-$249,999';
    if (n < 275000) return '$250,000-$274,999';
    if (n < 300000) return '$275,000-$299,999';
    if (n < 350000) return '$300,000-$349,999';
    return '$350,000+';
}

function formatWorkdaySalaryRangeEnDash(amount) {
    const n = Number(amount) || 85000;
    if (n < 40000) return '$30,000 – $40,000';
    if (n < 50000) return '$40,000 – $50,000';
    if (n < 60000) return '$50,000 – $60,000';
    if (n < 80000) return '$60,000 – $80,000';
    if (n < 100000) return '$80,000 – $100,000';
    if (n < 125000) return '$100,000 – $125,000';
    return '$125,000 – $150,000';
}

function formatWorkdayTenKSalaryBracket(amount) {
    const n = Number(amount) || 85000;
    const bracketLow = Math.floor(n / 10000) * 10000;
    const bracketHigh = bracketLow + 9000;
    return `$${bracketLow.toLocaleString('en-US')} - $${bracketHigh.toLocaleString('en-US')}`;
}

function parseSalaryBracketBounds(text) {
    const raw = String(text || '');
    // India LPA / lakhs (e.g. "15-20 LPA", "20 Lacs", "₹15,00,000 - ₹20,00,000")
    const lpa = raw.match(/([\d,.]+)\s*[-–—]\s*([\d,.]+)\s*(?:lpa|lacs?|lakhs?)/i);
    if (lpa) {
        const min = Math.round(parseFloat(lpa[1].replace(/,/g, '')) * 100000);
        const max = Math.round(parseFloat(lpa[2].replace(/,/g, '')) * 100000);
        if (Number.isFinite(min) && Number.isFinite(max)) return { min, max, unit: 'inr' };
    }
    const lpaSingle = raw.match(/([\d,.]+)\s*\+?\s*(?:lpa|lacs?|lakhs?)/i);
    if (lpaSingle && !/[-–—]/.test(raw)) {
        const min = Math.round(parseFloat(lpaSingle[1].replace(/,/g, '')) * 100000);
        if (Number.isFinite(min)) return { min, max: min * 10, unit: 'inr' };
    }
    // Indian-format lakhs with commas: 15,00,000
    const inrPair = raw.match(/₹\s*([\d,]+)\s*[-–—]\s*₹?\s*([\d,]+)/);
    if (inrPair) {
        const min = parseInt(inrPair[1].replace(/,/g, ''), 10);
        const max = parseInt(inrPair[2].replace(/,/g, ''), 10);
        if (Number.isFinite(min) && Number.isFinite(max)) return { min, max, unit: 'inr' };
    }
    if (/k/i.test(raw)) {
        const kPair = raw.match(/\$?\s*([\d,]+)\s*k\s*[-–—]\s*\$?\s*([\d,]+)\s*k/i);
        if (kPair) {
            const min = parseInt(kPair[1].replace(/,/g, ''), 10) * 1000;
            const max = parseInt(kPair[2].replace(/,/g, ''), 10) * 1000;
            if (Number.isFinite(min) && Number.isFinite(max)) return { min, max };
        }
        const mixed = raw.match(/\$?\s*([\d,]+)\s*[-–—]\s*\$?\s*([\d,]+)\s*k/i);
        if (mixed) {
            const min = parseInt(mixed[1].replace(/,/g, ''), 10);
            const max = parseInt(mixed[2].replace(/,/g, ''), 10) * 1000;
            if (Number.isFinite(min) && Number.isFinite(max)) return { min, max };
        }
    }
    const under = raw.match(/under\s*\$?\s*([\d,]+)/i);
    if (under) {
        const max = parseInt(under[1].replace(/,/g, ''), 10);
        if (Number.isFinite(max)) return { min: 0, max };
    }
    const plus = raw.match(/\$\s*([\d,]+)\s*\+/);
    if (plus) {
        const min = parseInt(plus[1].replace(/,/g, ''), 10);
        if (Number.isFinite(min)) return { min, max: min * 100 };
    }
    // "Between $X and $Y" / "$X to $Y" — wording seen instead of a dash separator on several
    // tenants (e.g. desjardins.wd10 Canadian salary bracket dropdown: "between $70,000 and
    // $84,999"). The dash-only regex below never matched this phrasing, so every bracket option
    // parsed to null bounds and findSalaryBracketDropdownMatch() always returned nothing — this
    // silently left the field's "no match" path to run, causing "Workday step stuck: questions"
    // on ANY tenant using "between X and Y" bracket wording, not one company.
    const between = raw.match(/(?:between\s+)?\$?\s*([\d,]+)\s*(?:and|to)\s*\$?\s*([\d,]+)/i);
    if (between) {
        const min = parseInt(between[1].replace(/,/g, ''), 10);
        const max = parseInt(between[2].replace(/,/g, ''), 10);
        if (Number.isFinite(min) && Number.isFinite(max) && max > min) return { min, max };
    }
    const m = raw.match(/\$?\s*([\d,]+)\s*[-–—]\s*\$?\s*([\d,]+)/);
    if (!m) return null;
    const min = parseInt(m[1].replace(/,/g, ''), 10);
    const max = parseInt(m[2].replace(/,/g, ''), 10);
    if (!Number.isFinite(min) || !Number.isFinite(max)) return null;
    return { min, max };
}

function formatWorkdayKSalaryBracket(amount) {
    const n = Number(amount) || 85000;
    const brackets = [
        [0, 55000, '$0 - $55k'],
        [55001, 70000, '$55k-$70k'],
        [70001, 84999, '$70k-$85k'],
        [85000, 100000, '$85k-$100k'],
        [100001, 115000, '$100k-$115k'],
        [115001, 130000, '$115k-$130k'],
        [130001, 145000, '$130k-$145k'],
        [145001, 160000, '$145k-$160k'],
        [160001, 200000, '$160k-$200k'],
    ];
    for (const [min, max, label] of brackets) {
        if (n >= min && n <= max) return label;
    }
    return '$160k-$200k';
}

function findSalaryBracketDropdownMatch(options, amount, localAmount = null) {
    const n = Number(amount) || 85000;
    const local = localAmount != null ? Number(localAmount) : null;
    let best = null;
    let bestSpan = Infinity;
    for (const opt of options) {
        const bounds = parseSalaryBracketBounds(optionText(opt));
        if (!bounds) continue;
        const useLocal = bounds.unit === 'inr' && local != null && Number.isFinite(local);
        const val = useLocal ? local : n;
        if (val >= bounds.min && val <= bounds.max) {
            const span = bounds.max - bounds.min;
            if (span < bestSpan) {
                bestSpan = span;
                best = opt;
            }
        }
    }
    if (best) return best;
    // Closest bracket above amount (prefer not under-asking)
    let closest = null;
    let closestDelta = Infinity;
    for (const opt of options) {
        const bounds = parseSalaryBracketBounds(optionText(opt));
        if (!bounds) continue;
        const useLocal = bounds.unit === 'inr' && local != null && Number.isFinite(local);
        const val = useLocal ? local : n;
        const mid = (bounds.min + bounds.max) / 2;
        const delta = Math.abs(mid - val);
        if (delta < closestDelta) {
            closestDelta = delta;
            closest = opt;
        }
    }
    return closest;
}

function salaryAmountFitsPreviewBracket(preview, amount) {
    const bounds = parseSalaryBracketBounds(preview);
    if (!bounds) return false;
    const n = Number(amount) || 85000;
    return n >= bounds.min && n <= bounds.max;
}

function getSalaryRangeCandidates(amount) {
    const n = Number(amount) || 85000;
    return [...new Set([
        formatWorkdayTenKSalaryBracket(n),
        formatWorkdayKSalaryBracket(n),
        formatWorkdaySalaryRangeEnDash(n),
        formatWorkdaySalaryRange(n),
        formatWorkdayCompensationText(n),
    ])];
}

function formatWorkdayCompensationText(amount) {
    const n = Math.round(Number(amount) || 85000);
    return `$${n.toLocaleString('en-US')}`;
}

/** Free-text "compensation expectations" prompts (Ferguson etc.) — not bare salary digits. */
function isCompensationExpectationsNarrative(label) {
    const l = String(label || '').toLowerCase();
    if (!/compensation expectation|salary expectation|pay expectation|expectations for (this )?role/i.test(l)) return false;
    return /pay range is listed|job posting|what are your compensation|describe|please (provide|enter|share)/i.test(l)
        || l.length > 80;
}

function getCompensationExpectationsNarrativeValue(profile) {
    const amount = getProfileSalaryAmount(profile);
    const formatted = formatWorkdayCompensationText(amount);
    return `I am seeking approximately ${formatted} annually, consistent with the posted pay range.`;
}

function getPreferredLanguageCandidates(profile = null) {
    const langs = [];
    for (const entry of profile?.languages || []) {
        const name = (typeof entry === 'string' ? entry : entry?.language || '').trim();
        if (name) langs.push(name);
    }
    return [...new Set([...langs, 'English', 'Spanish', 'French'])];
}

function isWorkdayGenderIdentityField(label) {
    return /gender identity/i.test(String(label || ''));
}

function isWorkdayDisclosureGenderField(label) {
    const l = String(label || '').toLowerCase();
    if (isWorkdayGenderIdentityField(l)) return false;
    if (isWorkdayVeteranFieldLabel(l)) return false;
    if (/gender-based violence|gender based violence|engaged in gender/i.test(l)) return false;
    if (/government contractor|federal government contractor/i.test(l)
        && /recordkeeping|reporting requirements|voluntary|comply with these requirements/i.test(l)
        && !/section 4212|\bveteran\b|protected veteran/i.test(l)) {
        return true;
    }
    // Trinity Health etc.: "Please select your Sex." (binary sex, not gender identity)
    if (/please select your sex|please indicate your sex|select your sex|^sex\b/i.test(l)
        && !/sexual orientation|sex offender|same.?sex/i.test(l)) {
        return true;
    }
    return /please provide your gender|specify your gender|please select your gender|please indicate your gender|indicate your gender|\bgender\b/i.test(l)
        && !/pay|gap|biological|birth|identity/i.test(l);
}

function getDisclosureSexAtBirthCandidates() {
    return [
        'Decline to Answer',
        'Decline To Answer',
        "I Don't Wish To Answer",
        "I Do Not Wish To Answer",
        'Prefer Not To Say',
        'Undeclared',
    ];
}

function getDisclosureGenderCandidates() {
    return [
        'Choose Not to Disclose',
        'Choose not to disclose',
        'Choose Not To Disclose',
        'Choose not to declare',
        'Choose Not to Declare',
        'Choose Not To Declare',
        'I do not wish to disclose',
        'I Do Not Wish To Disclose',
        'I do not wish to identify',
        'I Do Not Wish To Identify',
        'I do not wish to answer',
        'I Do Not Wish To Answer',
        'I do not wish to self-identify',
        'I Do Not Wish To Self-Identify',
        'I decline to self-identify',
        'I Decline To Self-Identify',
        'I decline to self identify',
        'I do not wish to provide this information',
        'I Do Not Wish To Provide This Information',
        'I do not wish to provide',
        'Prefer not to self-identify',
        'Prefer Not To Self-Identify',
        'Prefer not to self identify',
        'Prefer Not To Self Identify',
        'Not Declared',
        'not declared',
        'Not declared',
        'Decline to Answer',
        'Decline To Answer',
        "I Don't Wish To Answer",
        'Prefer not to answer',
        'Prefer Not to Answer',
        'Prefer Not To Answer',
        'Prefer Not To Say',
        'Prefer Not To Disclose',
        'is not listed',
        'Is Not Listed',
        'Undeclared',
        'Undisclosed',
        'undisclosed',
        // "Not Specified" is a distinct, common decline-option wording missed entirely by every phrase
        // above (observed on exclusivenetworks.wd103: real dropdown options were exactly
        // ["female","male","not specified"], the model's own streamed "Prefer not to answer" never matched,
        // and none of the ~40 existing fallback phrases matched it either, so the required Gender field
        // stayed permanently unfilled and the disclosures step got stuck on repeated retries). Not
        // tenant-specific — any tenant offering this exact decline wording on a binary gender dropdown hits
        // the same dead end.
        'Not Specified',
        'not specified',
        'Not specified',
        // "Unknown" (rosendin.wd1: options exactly ["female","male","unknown"]) — same dead-end when
        // stream returns "Prefer not to answer" and no decline synonym matches "Unknown".
        'Unknown',
        'unknown',
        'UNKNOWN',
    ];
}

function getDisclosureGenderOrIdentityCandidates(label = '') {
    const base = getDisclosureGenderCandidates();
    const regional = [
        'Prefer not to answer (India)',
        'Prefer Not To Answer (India)',
        'No (India)',
        'Is not listed',
        'Is Not Listed',
    ];
    // Gender is never present in profile — only offer a binary Male/Female candidate when a
    // real value is actually known (should not happen today). NEVER guess Male/Female when the
    // profile has no gender (see chrome-extension.mdc "Gender / sex disclosure fields — never
    // choose locally"): a binary-only dropdown (no decline option) must be left to the AI stream.
    const profileGender = String(window.__wdApplyData?.profile?.general?.gender || '').toLowerCase();
    const profileBinary = /female|woman|\bf\b/.test(profileGender) ? ['Female', 'female', 'Male', 'male']
        : /male|man|\bm\b/.test(profileGender) ? ['Male', 'male', 'Female', 'female']
            : [];
    const sexExtras = /please select your sex|please indicate your sex|select your sex|^sex\b|sex at birth|biological sex/i.test(String(label || ''))
        ? [...getDisclosureSexAtBirthCandidates()]
        : [];
    if (!isWorkdayGenderIdentityField(label)) {
        return [...new Set([...profileBinary, ...sexExtras, ...base, ...regional])];
    }
    return [...new Set([...profileBinary, ...base, ...regional, ...WORKDAY_DECLINE_PHRASES])];
}

function isWorkdayDisclosureGenderFilled(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const candidates = getDisclosureGenderOrIdentityCandidates(labelText);
    const comboboxValue = normalizeDisclosureOptionText(
        container.querySelector('input[role="combobox"]')?.value || ''
    );
    const selectionLabel = normalizeDisclosureOptionText(
        container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || ''
    );
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    const fieldLabel = (labelText || '').replace(/\s+/g, ' ').trim();
    let bodyPreview = preview;
    if (fieldLabel && bodyPreview.toLowerCase().startsWith(fieldLabel.toLowerCase())) {
        bodyPreview = bodyPreview.slice(fieldLabel.length).replace(/^\s*\*?\s*/, '').trim();
    }
    // Open listboxes leave option text in the container — require a committed chip/combobox value.
    if (/select one/i.test(preview) && !selectionLabel && !comboboxValue) return false;
    // Only treat as empty when the body (not the field label) still shows Select One / Error.
    if (/error:.*required|(?:^|\s)select one\b/i.test(bodyPreview)
        && (!selectionLabel || /^select one$/i.test(selectionLabel))
        && !comboboxValue) {
        return false;
    }
    if (/error:.*required/i.test(bodyPreview)
        && (!selectionLabel || /^select one$/i.test(selectionLabel))) {
        return false;
    }
    if (/^[a-f0-9-]{16,}$/i.test(comboboxValue)) {
        // Workday stores opaque ids after commit — treat as filled when Select One is gone
        if (!/select one|error:.*required/i.test(bodyPreview.split(selectionLabel || comboboxValue)[0] || bodyPreview)) return true;
    }
    if (isWorkdayDisclosureSelectionFilled(container, candidates)) {
        // Avoid false positives from option labels listed under an empty Select One
        if (/select one/i.test(preview) && !selectionLabel && !comboboxValue) return false;
        return true;
    }
    const selected = normalizeDisclosureOptionText(getWorkdayFieldSelectedText(container) || '');
    if (/^(male|female|non-binary|non binary|other)$/i.test(selected)) return true;
    const hay = `${selectionLabel} ${comboboxValue} ${selected}`.toLowerCase().trim();
    if (!hay || /^select one$/i.test(hay)) return false;
    // Prefer short committed values over full container dumps that include every option
    const committed = `${selectionLabel} ${comboboxValue}`.toLowerCase().trim();
    const checkHay = committed && !/^select one$/i.test(committed) && !/^[a-f0-9-]{16,}$/i.test(committed)
        ? committed
        : (selected || hay);
    if (checkHay.length > 80 && /female|male|non-binary|choose not/i.test(checkHay)
        && /select one/i.test(bodyPreview)) {
        return false;
    }
    if (/^(male|female|non-binary|non binary)$/i.test(checkHay)) return true;
    if (/prefer not to self-?identify|do not wish to self-?identify|choose not to (self-?)?identify|choose not to (disclose|declare|answer|say)|i decline to self-?identify|decline to self-?identify|do not wish to provide|do not wish to disclose|do not wish to answer|prefer not to (answer|say|disclose)|decline to answer|i decline|not declared|undisclosed|undeclared|choose not to disclose/i.test(checkHay)) {
        return true;
    }
    return false;
}

/**
 * Local fill for gender/sex disclosure fields — DECLINE-ONLY, never a guess.
 *
 * The profile never carries a gender value, so this function must never assert Male/Female on
 * its own (see chrome-extension.mdc "Gender / sex disclosure fields — never choose locally").
 * It only clicks a genuine decline/"prefer not to disclose"-style option when one exists in the
 * dropdown. When no such option exists (binary Male/Female-only dropdown) it marks the field for
 * the AI stream and returns false — the generic collect -> stream -> fill pipeline
 * (`collectWorkdayFields` / `workdayStreamVacancyFields` / `fillWorkdayField`) resolves the value
 * from the model's response instead.
 */
async function fillWorkdayDisclosureGenderField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const labelLower = labelText.toLowerCase();
    const candidates = getDisclosureGenderOrIdentityCandidates(labelText);

    if (isWorkdayDisclosureGenderFilled(container)) return true;
    if (isDisclosureLocalFillDone(labelText)) return isWorkdayDisclosureGenderFilled(container);

    const openKey = normalizeDropdownOpenKey(labelLower);
    // Already deferred to the AI stream — never guess Male/Female locally, and never reopen the
    // dropdown again outside the stream-driven fill.
    if (window.__wdDisclosureStreamFallback?.has(openKey)) return false;
    if ((wdDropdownOpenCounts[openKey] || 0) >= 1 && isWorkdayDisclosureGenderFilled(container)) {
        markDisclosureLocalFilled(labelText);
        return true;
    }
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        markDisclosureStreamFallback(labelText);
        return false;
    }

    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    const combobox = container.querySelector('input[role="combobox"]');
    if (/select one/i.test(preview) && combobox?.value
        && /decline|prefer not|undeclared|do not wish|don't wish/i.test(combobox.value)) {
        setNativeValue(combobox, '');
        combobox.dispatchEvent(new Event('input', { bubbles: true }));
        combobox.dispatchEvent(new Event('change', { bubbles: true }));
        await wait(250);
    }

    if (isDisclosureChoiceGroup(container)) {
        const ok = await fillWorkdayDisclosureChoiceGroup(container, candidates);
        if (ok || isWorkdayDisclosureGenderFilled(container)) {
            markDisclosureLocalFilled(labelText);
            return true;
        }
    }

    const control = getContainerControl(container);
    if (!control) {
        markDisclosureStreamFallback(labelText);
        return false;
    }
    const ok = await fillWorkdayDisclosureSingleSelectDropdown(control, candidates, labelLower);
    debugLog(`${WD} disclosure gender fill`, labelText.slice(0, 60), 'ok=', ok);
    await wait(400);
    const filled = isWorkdayDisclosureGenderFilled(container);
    if (filled) {
        markDisclosureLocalFilled(labelText);
    } else {
        // No decline-style option matched (binary Male/Female-only dropdown, or profile has no
        // gender) — never force a guess. Defer to the AI stream.
        debugLog(`${WD} disclosure gender no local decline match — deferring to stream`, labelText.slice(0, 60));
        markDisclosureStreamFallback(labelText);
    }
    return filled;
}

/** Standard yes/no application questions — no profile data, never stream to backend. */
function isWorkdayGovernmentEmploymentQuestion(label) {
    const l = String(label || '').toLowerCase();
    if (/certain federal law may require|inform your federal agency/i.test(l)) return false;
    return /please select your employment status with the united states \(u\.s\.\) federal government/i.test(l)
        || /please select your state, local, non-u\.s\. government/i.test(l)
        || /^5\.\s*u\.s\. federal government employment/i.test(l)
        || /^6\.\s*state, local/i.test(l)
        || (/u\.s\. federal government employment/i.test(l) && /please select your employment status/i.test(l))
        || (/state, local, & non-u\.s\. government employment/i.test(l) && /please select/i.test(l));
}

function isWorkdayNotToMyKnowledgeLabel(label = '') {
    return /to the best of your knowledge/i.test(String(label || ''));
}

function isNotToMyKnowledgeQuestion(container, label = '') {
    if (isWorkdayPrivacyConsentDropdownField(label, container)) return false;
    const text = `${label} ${container?.innerText || ''}`.toLowerCase();
    if (/i agree/i.test(text) && /i do not agree/i.test(text)) return false;
    if (isWorkdayNotToMyKnowledgeLabel(label)) return true;
    if (/to the best of your knowledge.*current or former employee/i.test(text)) return true;
    if (/certain federal law may require/i.test(text)) return true;
    if (/not to my knowledge/i.test(text) && /\byes\b/i.test(text)) return true;
    return false;
}

function isNotToMyKnowledgeFilled(container) {
    const preview = (getWorkdayFieldSelectedText(container) || container?.innerText || '').toLowerCase();
    if (/^select one$/i.test(preview.trim()) || /select one|0 items selected/i.test(preview)) return false;
    if (/not to my knowledge/i.test(preview)) return true;
    // Boeing-style COI: same question shape but options are Yes/No
    if (/\bno\b/i.test(preview) && !/\byes\b/i.test(getWorkdayFieldSelectedText(container) || '')) {
        return isWorkdaySingleSelectFilled(container, ['No', 'no']) || isWorkdayYesNoFilled(container, 'No');
    }
    return false;
}

async function fillWorkdayNotToMyKnowledgeField(container, label) {
    if (isNotToMyKnowledgeFilled(container)) return true;
    if (isWorkdayYesNoFilled(container, 'No') || isWorkdaySingleSelectFilled(container, ['No', 'no'])) return true;
    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!control) return false;
    const fieldRoot = container?.closest?.('[data-automation-id*="formField"]') || container;
    const openKey = normalizeDropdownOpenKey(String(label || 'not-to-my-knowledge'));
    resetWorkdayDropdownOpenCount(openKey);
    await closeWorkdayPopups();
    workdayScrollToTarget(fieldRoot, 120);
    trackWorkdayDropdownOpen(openKey);
    await workdayClick(getWorkdayDropdownTrigger(fieldRoot) || control);
    await wait(1200);
    const popup = findPopupNearField(fieldRoot, label) || findPopupNearField(fieldRoot, 'knowledge');
    if (!popup) {
        // Popup may be a simple Yes/No listbox — try single-select with No fallbacks
        clearWorkdaySingleSelectMissKey(label);
        const fallbackOk = await fillWorkdaySingleSelectDropdown(control, [
            'Not to my knowledge',
            'No',
            'None of the above',
            'I do not',
        ], label);
        debugLog(`${WD} not-to-my-knowledge no-popup fallback`, String(label || '').slice(0, 60), 'ok=', fallbackOk);
        return fallbackOk || isNotToMyKnowledgeFilled(container);
    }
    const options = getSingleSelectDropdownOptions(popup, false);
    let match = options.find(o => /not to my knowledge/i.test(optionText(o)))
        || options.find(o => /^no\b/i.test(optionText(o)))
        || options.find(o => /none of the above|i do not|do not have/i.test(optionText(o)));
    if (!match) {
        debugLog(`${WD} not-to-my-knowledge options miss`, options.slice(0, 12).map(o => optionText(o)));
        await closeWorkdayPopups();
        clearWorkdaySingleSelectMissKey(label);
        const fallbackOk = await fillWorkdaySingleSelectDropdown(control, [
            'Not to my knowledge', 'No', 'None of the above', 'I do not',
        ], label);
        if (fallbackOk || isNotToMyKnowledgeFilled(container) || isWorkdaySingleSelectFilled(container, ['No'])) {
            return true;
        }
        // Last resort: radio Yes/No
        const ynOk = await fillWorkdayYesNoField(container, 'No');
        debugLog(`${WD} not-to-my-knowledge yes/no fallback`, String(label || '').slice(0, 60), 'ok=', ynOk);
        return ynOk;
    }
    const matchText = optionText(match);
    workdayClickElement(match);
    await wait(600);
    await commitWorkdayComboboxSelection(fieldRoot, fieldRoot.querySelector('input[role="combobox"]') || control, match, matchText);
    await closeWorkdayPopups();
    const ok = isNotToMyKnowledgeFilled(container)
        || isWorkdaySingleSelectFilled(container, [matchText, 'No', 'not to my knowledge'])
        || isWorkdayYesNoFilled(container, 'No');
    debugLog(`${WD} not-to-my-knowledge select`, matchText.slice(0, 60), 'ok=', ok);
    return ok;
}

function getGovernmentEmploymentDropdownCandidates(label) {
    const l = String(label || '').toLowerCase();
    if (/u\.s\. federal government|united states.*federal government/i.test(l)) {
        return [
            'I have never been employed by the U.S. Federal Government.',
            'I have never been employed by the U.S. Federal Government',
        ];
    }
    if (/state, local|non-u\.s\. government|government entity|political party|royal family/i.test(l)) {
        return [
            'I have never been employed by a ‘Government Entity’, or political party, a member of a royal family, or a candidate for political office.',
            "I have never been employed by a 'Government Entity', or political party, a member of a royal family, or a candidate for political office.",
            'I have never been employed by a Government Entity',
        ];
    }
    return [
        'I have never been employed',
        'Never employed',
        'Not applicable',
    ];
}

async function fillWorkdayGovernmentEmploymentField(container, label) {
    const candidates = getGovernmentEmploymentDropdownCandidates(label);
    if (isWorkdaySingleSelectFilled(container, candidates)
        || /never been employed/i.test(getWorkdayFieldSelectedText(container) || '')) {
        return true;
    }
    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!control) return false;
    const fieldRoot = container?.closest?.('[data-automation-id*="formField"]') || container;
    clearWorkdaySingleSelectMissKey(label);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(label || '')));
    // Prefer generic single-select (one open, multi-candidate) — custom open/match path
    // burned opens with target=No when miscategorized as Yes/No (bah.wd1).
    if (await fillWorkdaySingleSelectDropdown(control, candidates, label)) {
        debugLog(`${WD} government employment select via single-select`, String(label || '').slice(0, 60), 'ok=', true);
        return true;
    }
    clearWorkdaySingleSelectMissKey(label);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(label || '')));
    await closeWorkdayPopups();
    workdayScrollToTarget(fieldRoot, 120);
    const openKey = normalizeDropdownOpenKey(String(label || ''));
    trackWorkdayDropdownOpen(openKey);
    await workdayClick(getWorkdayDropdownTrigger(fieldRoot) || control);
    await wait(1500);
    const popup = findPopupNearField(fieldRoot, label) || findActiveWorkdayPopup();
    if (!popup) {
        debugLog(`${WD} government employment no popup`, String(label || '').slice(0, 60));
        return false;
    }
    const options = getSingleSelectDropdownOptions(popup, false);
    const match = options.find(o => /i have never been employed/i.test(optionText(o)))
        || options.find(o => candidates.some(c => optionText(o).includes(String(c).toLowerCase().slice(0, 30))));
    if (!match) {
        debugLog(`${WD} government employment options miss`, options.slice(0, 6).map(o => optionText(o)));
        await closeWorkdayPopups();
        return false;
    }
    const matchText = optionText(match);
    workdayClickElement(match);
    await wait(600);
    await commitWorkdayComboboxSelection(fieldRoot, fieldRoot.querySelector('input[role="combobox"]') || control, match, matchText);
    await closeWorkdayPopups();
    const ok = isWorkdaySingleSelectFilled(container, candidates) || /never been employed/i.test(getWorkdayFieldSelectedText(container));
    debugLog(`${WD} government employment select`, matchText.slice(0, 80), 'ok=', ok);
    return ok;
}

const WORKDAY_HARDCODED_YES_NO_QUESTIONS = [
    {
        answer: 'Yes',
        patterns: [
            /personal data processed.*recruitment for other/i,
            /i agree to have my personal data processed/i,
            /data will be removed from the pwc system/i,
            /keep in touch|sharing future career/i,
            /prepared to undertake a wwc check|undertake a wwc check/i,
            /^acknowledgment$|acknowledgment.*i acknowledge|i acknowledge that i will personally|without assistance from generative ai/i,
            /secure remote work location|have a secure remote|dedicated remote work(ing)? (space|location|environment)/i,
            /(?:are you )?(?:at least|over|older than)\s*(?:eighteen|18)|eighteen \(18\) years|are you currently 18|18 years of age or older|18 or older/i,
            /open to relocation|willing to relocate/i,
            /available to join in the posted|available for personal interview|join in the posted job location/i,
            /eligible to work in india|holding an indian passport|indian passport/i,
            /willing to travel in the course of employment/i,
            /by selecting .*yes.*you agree that we may call|consent.*automated technology|text messages? related to your application/i,
            /completed education degree or diploma|do you have a completed education/i,
            /acknowledge and understand.*(?:eligibility|work permit|proof of)|offered a position.*acknowledge/i,
            /by selecting ["']?yes["']?.*(?:certify|acknowledge|confirm)|i certify that all information i provide/i,
            /i confirm that i have read the above statement|information provided is correct to the best of my knowledge/i,
            /select yes to this question.*current job|get information on your current job|additional questions will appear/i,
            /valid driver'?s license|able to obtain a (?:valid )?driver'?s license|do you have.*driver'?s license/i,
            /proof of identity|authorization to work|legally (?:authorized|authorised) to work|eligible to work in (?:the )?(?:united states|u\.?s\.?|australia|this country|the country)|work rights for australia|are you eligible to work in australia/i,
            /do you have the (?:legal )?right to work|legal right to work in (?:the )?(?:uk|united kingdom|u\.?s|united states|australia|this country)/i,
            /meet all minimum qualifications|minimum qualifications.*(?:listed|as listed).*job posting|licenses?, certifications?, and education/i,
            /meet the minimum years of experience|do you meet.*years of experience.*(?:indicated|job posting)/i,
            /currently live in the city where this job|live in the city where this job is located/i,
            // Office / hybrid attendance confirmations (digitalturbine.wd501) — affirm when applying
            /hybrid work model|days in the office|work in the office location|ability to work in the office|come into the office|onsite .{0,20}days per week|in[- ]office .{0,30}(?:days|week)/i,
        ],
    },
    {
        answer: 'No',
        patterns: [
            /related to any of the following/i,
            /share my personal information with its advertising partners|advertising partners to show me|news and updates about .{0,40}careers and roles through online/i,
            /executive officers.*directors of.*board of directors/i,
            /are you related to any.*executive officer/i,
            /are you related to a colleague|related to a colleague at any/i,
            /conflict of interest/i,
            /gender-based violence|gender based violence|investigated for an allegation of gender/i,
            /working with children \(wwc\)|hold a victorian employee working with children/i,
            /felony|convicted|criminal record|crime other than a traffic|been convicted of a crime/i,
            /reasonable.?accommodation.*disability|disability or medical need|need a reasonable accommodation/i,
            /require any adjustments|adjustments for the recruitment process|disability confident scheme|considered under the dcs|\bunder the dcs\b/i,
            /isle of man|born on the island|license enabling you to work in the isle/i,
            /discharged or forced to resign|forced to resign from any position/i,
            /current employee of sysco|current employees of sysco|are you a current employee|are you currently employed|currently employed by|current employee of a state of/i,
            /former .{0,40}(?:team member|employee)|are you a former|previously (?:worked|employed) (?:for|with|at)/i,
            // Prior company affiliation via Employee ID / corporate email (cisco.wd5 information)
            /been issued .{0,80}employee id|employee id or .{0,60}email address|issued a .{0,40}(?:employee|badge) id/i,
            /relatives employed by the state|currently have relatives employed/i,
            /work opportunity tax credit|wotc|tax credit prescreening/i,
            // "Are you a veteran?" is EEO multi-option (isWorkdayVeteranFieldLabel) — not binary No.
            /united states armed (?:forces|services)|served in the (?:u\.?s\.?|united states) armed|military service|have you ever served/i,
            // Government / PEP / related-official Yes-No (Albemarle Ketjen etc.) — never a city/name from profile
            /government official|public official|politically exposed|state[- ]owned|state owned enterprise/i,
            /spouse.*partner.*(?:any )?relative.*(?:government|public official)|relative a government official/i,
            /are you.*(spouse|partner|relative).*(?:government|public) official/i,
            // Guidehouse-style: employed by US Federal / State / Local / Foreign government (not Armed Forces for our profiles)
            /directly employed by any (?:us |u\.?s\.?\s*)?federal|employed by any .{0,40}government|multi-lateral or quasi.?governmental|foreign government/i,
            // procore.wd12: "Are you currently located in the city where this role is based?" —
            // stream often returns profile city ("Jacksonville") instead of Yes/No; default No.
            /currently located in the city where this (?:role|job|position)|located in the city where this (?:role|job|position) is based/i,
            // Apprenticeship / training Yes-No that mention school|university — NOT a school typeahead.
            // Without a local answer, enrich skips on "school/university" keywords, stream gets options:[],
            // and the model invents a school name that never matches Yes|No|Don't know (sanofi.wd3).
            /already identified (?:the )?(?:school|university|training)|identified the school\/university\/training|wish to integrate/i,
            /have you already identified .{0,80}(?:school|university|training center)/i,
            // Study-abroad / experience-abroad Yes/No — answering Yes opens a required follow-up
            // textarea and burns stream budget (hoganlovells.wd3); default No for our profiles.
            /academic\/work experience abroad|academic.?work experience abroad|experience abroad|studied abroad|study abroad/i,
        ],
    },
];

/** True when the label is a Yes/No-style question (not a free-text/typeahead school/city field). */
function isWorkdayYesNoInterrogativeLabel(label) {
    const l = String(label || '').replace(/\u00a0/g, ' ').trim();
    if (!l) return false;
    // Free-text / typeahead school-name fields are not Yes/No even when they contain "school".
    if (/^(name of|which|what|enter|please (?:enter|provide|list)|type (?:the|your))\b/i.test(l)
        && /\b(school|university|college|city|employer|company|location)\b/i.test(l)
        && !/\b(have you|are you|do you|is the|is this|did you)\b/i.test(l)) {
        return false;
    }
    return /^(have you|has the|has your|are you|is the|is this|is your|do you|does the|does your|will you|can you|would you|did you|were you)\b/i.test(l)
        || (/\?\s*$/.test(l) && /^(have|has|are|is|do|does|will|can|would|did|were)\b/i.test(l));
}

function getHardcodedYesNoAnswer(label) {
    const l = String(label || '').toLowerCase().replace(/\u00a0/g, ' ');
    // Age-band selects ("I am under/over 18") are not Yes/No
    if (isWorkdayAgeBand18SelectQuestion(l)) return null;
    // Agree/Disagree policy acknowledgments (Alterra EEO etc.) — never Yes/No
    if (/please read before signing|equal employment opportunities|without regard to an applicant/i.test(l)) {
        return null;
    }
    if (isWorkdayPrivacyConsentDropdownField(label)) return null;
    // EEO veteran multi-option ("Are you a veteran?" → "I am not a veteran") — never bare No
    if (isWorkdayVeteranFieldLabel(label)) return null;
    // BAH-style PGE status dropdowns mention "FORMER federal government employees" in the help
    // text — that must not match the former-employee Yes/No pattern and force target=No
    // (bah.wd1 questions: options are "I have never been employed by the U.S. Federal Government.").
    if (isWorkdayGovernmentEmploymentQuestion(label)) return null;
    for (const { answer, patterns } of WORKDAY_HARDCODED_YES_NO_QUESTIONS) {
        if (patterns.some(p => p.test(l))) return answer;
    }
    return null;
}

/** "Date of graduation (or expected)" and similar — not start-availability dates. */
function isWorkdayGraduationDateLabel(label) {
    const l = String(label || '').toLowerCase().replace(/\u00a0/g, ' ');
    if (!l) return false;
    if (/available|start date|date of birth|dob|when can you start|eligibility/i.test(l)) return false;
    return /date of graduation|graduation date|expected graduation|anticipated graduation|graduat(?:ion|e) .{0,20}date|date .{0,20}graduat/i.test(l);
}

/** Latest education endDate as MM/DD/YYYY for masked Workday date widgets. */
function getWorkdayGraduationDateValue(profile) {
    const eds = profile?.educations || profile?.education || [];
    let best = null;
    for (const e of eds) {
        const raw = e?.endDate ?? e?.end_date ?? e?.graduationDate;
        if (raw == null || raw === '') continue;
        let d = null;
        if (typeof raw === 'number') {
            const ms = raw < 1e12 ? raw * 1000 : raw;
            d = new Date(ms);
        } else if (typeof raw === 'string') {
            const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (iso) {
                return `${iso[2]}/${iso[3]}/${iso[1]}`;
            }
            d = new Date(raw);
        } else if (raw instanceof Date) {
            d = raw;
        }
        if (d && !Number.isNaN(d.getTime())) {
            if (!best || d > best) best = d;
        }
    }
    if (!best) return null;
    const mm = String(best.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(best.getUTCDate()).padStart(2, '0');
    const yyyy = String(best.getUTCFullYear());
    return `${mm}/${dd}/${yyyy}`;
}

function isWorkdayAgeBand18SelectQuestion(label) {
    const l = String(label || '').toLowerCase().replace(/\u00a0/g, ' ');
    if (!l) return false;
    if (/below or over the age of 18|under the age of 18|18\/over the age of 18/i.test(l)) return true;
    if (/indicate if you are (?:below|under) or over/i.test(l) && /\b18\b/.test(l)) return true;
    if (/please indicate.*\b18\b.*(?:years|age)/i.test(l) && /below|under|over/i.test(l)) return true;
    return false;
}

function getWorkdayAgeBand18Candidates() {
    return [
        'I am 18/over the age of 18',
        'I am 18 or over the age of 18',
        'I am over the age of 18',
        'I am 18 or older',
        '18 or older',
        '18+',
        'Over 18',
        'Yes',
    ];
}

async function fillWorkdayAgeBand18Field(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const cands = getWorkdayAgeBand18Candidates();
    if (isWorkdaySingleSelectFilled(container, cands)) return true;
    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!control) return false;
    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(labelText || '')));
    const ok = await fillWorkdaySingleSelectDropdown(control, cands, String(labelText || '').slice(0, 80));
    debugLog(`${WD} age-band 18 fill`, String(labelText || '').slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, cands);
}

function isWorkdayTotalHoursPerWeekField(label) {
    const l = String(label || '').toLowerCase().replace(/\u00a0/g, ' ');
    // Visa-hours band selects (unimelb.wd105) are not free-text "hours available" fields.
    if (/visa/i.test(l) || isWorkdayVisaHoursPerWeekField(label)) return false;
    return /total (?:number of )?hours.*(?:available|per week)|hours you are available.*(?:per|a)\s*week|hours available per week|how many hours.*(?:per|a)\s*week|weekly hours available|hours per week (?:available|desired|preferred)|total number of hours you are available/i.test(l);
}

function getWorkdayTotalHoursPerWeekValue() {
    const hay = `${window.__wdHistoryRole || ''} ${location.href}`.toLowerCase();
    if (/part[\s-]?time|verkäufer|verkauf|retail associate|cashier|warehouse order/i.test(hay)) return '20';
    return '40';
}

async function fillWorkdayTotalHoursPerWeekField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const control = container.querySelector('textarea, input[type="text"], input[type="number"], input[type="tel"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') return false;
    if ((control.value || '').trim()) return true;
    const value = getWorkdayTotalHoursPerWeekValue();
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} total hours/week fill`, String(labelText || '').slice(0, 60), value);
    return Boolean((control.value || '').trim());
}

function getProfileBooleanAnswer(value) {
    if (value === true) return 'Yes';
    if (value === false) return 'No';
    return null;
}

function getProfileVisaSponsorshipAnswer(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    return getProfileBooleanAnswer(
        residency.visaSponsorship
        ?? profile?.visaSponsorship
        ?? profile?.general?.visaSponsorship
        ?? null
    );
}

function getProfileAuthorizedCountryNames(profile) {
    const names = new Set();
    const addCountry = (name) => {
        if (!name) return;
        const normalized = normalizeProfileCountryName(name);
        if (!normalized) return;
        names.add(normalized.toLowerCase());
        names.add((PROFILE_TO_WORKDAY_COUNTRY[normalized] || normalized).toLowerCase());
    };
    for (const name of profile?.authorizedCountries || []) addCountry(name);
    for (const name of profile?.general?.authorizedCountries || []) addCountry(name);
    for (const name of profile?.residencyCountries || []) addCountry(name);
    for (const name of profile?.general?.residencyCountries || []) addCountry(name);
    return names;
}

function getQuestionCountryHints(profile, label) {
    const l = String(label || '').toLowerCase();
    const hints = [];
    const add = (value) => {
        if (!value) return;
        hints.push(String(value).toLowerCase());
    };
    if (/u\.?s\.|united states|united states of america|\busa\b|\bus\b/.test(l)) {
        add('United States');
        add('United States of America');
        add('USA');
        add('US');
    }
    if (/\buk\b|united kingdom|great britain|\bgb\b/.test(l)) {
        add('United Kingdom');
        add('UK');
        add('Great Britain');
        add('England');
    }
    if (/\bjapan\b/.test(l)) {
        add('Japan');
    }
    add(getWorkdayCountryName(profile));
    add(getProfileCountryName(profile));
    return [...new Set(hints)];
}

function getProfileWorkAuthorizationAnswer(profile, label) {
    const countries = getProfileAuthorizedCountryNames(profile);
    if (!countries.size) return null;
    const hints = getQuestionCountryHints(profile, label);
    if (!hints.length) return null;
    return hints.some(hint => countries.has(hint)) ? 'Yes' : 'No';
}

function getProfileDerivedYesNoAnswer(profile, label) {
    profile = getProfileForJobLocation(profile);
    const l = String(label || '').toLowerCase();
    if (isWorkdaySponsorshipRequiredQuestion(l)) {
        return getProfileVisaSponsorshipAnswer(profile);
    }
    if (isWorkAuthorizedWithoutSponsorshipQuestion(l)) {
        const auth = getProfileWorkAuthorizationAnswer(profile, l);
        const sponsorship = getProfileVisaSponsorshipAnswer(profile);
        if (auth === 'No') return 'No';
        if (auth === 'Yes' && sponsorship === 'No') return 'Yes';
        return null;
    }
    // Simple Yes/No "legal right to work" — always Yes (stream previously picked No when
    // authorizedCountries lacked the job country). Status/details fields stay separate.
    if (/do you have the (?:legal )?right to work|legal right to work/i.test(l)
        && !/status|additional details|what is your current/i.test(l)) {
        return 'Yes';
    }
    // Binary "eligible to work in {country}" / "work rights for Australia" — Yes (prompt 10a).
    // Answering No left UniMelb visa-hours follow-ups empty and stuck the questions step.
    if (/eligible to work in|work rights for|are you eligible to work/i.test(l)
        && !/visa type|visa status|sponsorship|hours per week|detail/i.test(l)) {
        return 'Yes';
    }
    if (/legally authorized|legally permitted|authorized to work|right to work|work authorization|permitted to work/i.test(l)) {
        // A bare "Work Authorization" label (no question wording) is typically a CATEGORY selector
        // widget (e.g. "I am authorized to work permanently in the United States" | "I am
        // authorized to work permanently in Canada" | "H1-B" | "Student Visa" | "Other"), not a
        // true Yes/No question. Forcing a literal "Yes" into that dropdown never matches any real
        // option and gets the step permanently stuck (see chrome-extension.mdc — Workday step
        // stuck: questions). Bail out so the field is collected/streamed with its real options
        // instead of being force-answered Yes/No.
        if (/^work auth(?:orization)?(?:\s+status)?\*?$/i.test(l.trim())) return null;
        return getProfileWorkAuthorizationAnswer(profile, l);
    }
    if (/^eligible to work|^are you eligible/i.test(l)) {
        return getProfileWorkAuthorizationAnswer(profile, l) || 'Yes';
    }
    return null;
}

function getWorkdayConsentYesCandidates(label = '') {
    if (isWorkdaySmsConsentDropdownField(label)) return getWorkdaySmsConsentCandidates();
    if (isWorkdayPrivacyConsentDropdownField(label)) return getWorkdayPrivacyConsentCandidates();
    const l = String(label || '').toLowerCase();
    if (/legal right to work|do you have the (?:legal )?right to work|eligible to work|work rights for/i.test(l)) {
        return [
            // UniMelb exact option first — prefer citizen over PR/visa (avoids mandatory visa-hours).
            'I am an Australian / New Zealand Citizen',
            'I am an Australian/New Zealand citizen or Permanent Resident',
            'Yes, I am an Australian Citizen',
            'I am an Australian Citizen',
            'Yes - Australian Citizen',
            'Australian Citizen',
            'Yes, I am an Australian Permanent Resident',
            'I am an Australian Permanent Resident',
            'Yes - Permanent Resident',
            'I am a primary visa holder with work rights',
            'Yes, I have appropriate work rights',
            'Yes, I have the legal right to work',
            'Yes, I have the legal right to work in the UK',
            'Yes I have the legal right to work',
            'Yes - I hold a valid visa',
            'Yes',
            'yes',
        ];
    }
    if (/i confirm that i have read the above statement|information provided is correct to the best of my knowledge|21 o\.s\./i.test(l)) {
        return [
            'I confirm that I have read the above statement, and that all information provided is correct to the best of my knowledge.',
            'I confirm',
            'Yes',
            'yes',
        ];
    }
    // digitalturbine.wd501: hybrid office confirm uses "I confirm" / "I do not confirm" (not Yes/No)
    if (/hybrid work model|days in the office|work in the office location|ability to work in the office|come into the office/i.test(l)) {
        return ['I confirm', 'I Confirm', 'Yes', 'yes'];
    }
    if (/background check|drug test|pre-employment/i.test(l)) {
        return ['Yes, I agree.', 'Yes, I agree', 'I agree', 'Yes', 'yes'];
    }
    return ['Yes', 'yes'];
}

function getWorkdayWorkRegionCandidates() {
    return [
        'Central',
        'North East',
        'North West',
        'South East',
        'South West',
        'Northeast',
        'Northwest',
        'Southeast',
        'Southwest',
        'Statewide',
        'All',
    ];
}

/** AU/NZ/UK Workday "working rights" selects — prefer citizen/PR over visa-assistance answers. */
function getWorkdayWorkingRightsCandidates(profile = null, label = '') {
    const l = String(label || '').toLowerCase();
    const uk = /uk|united kingdom|british|northern ireland/i.test(l) || /lbg\.|lloyds/i.test(location.href);
    const ukCands = [
        'British Citizen',
        'British/Irish citizen',
        'British / Irish Citizen',
        'I am a British Citizen',
        'UK Citizen',
        'British / Irish Citizen',
        'Settled Status',
        'Pre-Settled Status',
        'Indefinite Leave to Remain',
        'I have unlimited right to work in the UK',
        'I have the right to work in the UK without restriction',
        'Yes - I have the right to work in the UK',
        'Yes, I have the legal right to work',
        'Yes',
    ];
    const auCands = [
        'I am an Australian/New Zealand citizen or Permanent Resident',
        'Australian/New Zealand citizen or Permanent Resident',
        'Australian Citizen',
        'Australian Permanent Resident',
        'Permanent Resident',
        'New Zealand Citizen',
        'Citizen',
        'Yes - I am a Citizen',
        'Yes - Australian Citizen',
        'I am an Australian Citizen',
        'Unlimited working rights',
        'Unrestricted working rights',
        'Full working rights',
        'Yes',
    ];
    const base = uk ? [...ukCands, ...auCands] : [...auCands, ...ukCands];
    return [
        ...base,
        ...(profileExpectsUS(profile)
            ? ['No - I will require Visa assistance', 'No - I will require visa assistance', 'No']
            : []),
    ];
}

/** Free-text relatives/conflict prompts ("if yes, who are they…") — not short yes/no dropdowns. */
function isWorkdayRelativeConflictTextField(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (!/if yes, who|what is their role|role with the organization/i.test(l)) return false;
    if (!/conflict of interest|relative|family|affiliate|organization/i.test(l)) return false;
    if (!container) return true;
    if (container.querySelector('button[aria-haspopup="listbox"], [role="combobox"], button[data-automation-id="promptSelectionLabel"]')) {
        return false;
    }
    if (container.querySelector('input[type="radio"]')) return false;
    return Boolean(container.querySelector('textarea, input[type="text"], input[type="search"]'));
}

function getWorkdayRelativeConflictTextValue(label, container = null) {
    const required = container ? isContainerRequired(container) : String(label || '').includes('*');
    return required ? 'No' : '';
}

async function fillWorkdayRelativeConflictTextField(container, label) {
    const value = getWorkdayRelativeConflictTextValue(label, container);
    if (!value) return true;
    const control = container.querySelector('textarea')
        || container.querySelector('input[type="text"], input[type="search"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') {
        return false;
    }
    if ((control.value || '').trim()) return true;
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} filled relative/conflict text`, String(label || '').slice(0, 70), value);
    return Boolean((control.value || '').trim());
}

/** Conditional license/cert follow-up after "Do you have any licenses or certifications?" = Yes. */
function isWorkdayLicenseFollowUpTextField(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (!/^if yes,/.test(l)) return false;
    if (!/license|certification|credential/.test(l)) return false;
    if (!container) return true;
    if (container.querySelector('button[aria-haspopup="listbox"], [role="combobox"], button[data-automation-id="promptSelectionLabel"]')) {
        return false;
    }
    if (container.querySelector('input[type="radio"]')) return false;
    return Boolean(container.querySelector('textarea, input[type="text"], input[type="search"]'));
}

function formatWorkdayLicenseFollowUpText(profile) {
    const certs = (profile?.courseCertificates || []).filter(c => c?.name);
    if (!certs.length) return '';
    return certs.map(c => {
        const parts = [String(c.name).trim()];
        if (c.certificateNumber) parts.push(`#${c.certificateNumber}`);
        if (c.endDate) {
            const d = new Date(c.endDate * 1000);
            if (!Number.isNaN(d.getTime())) {
                const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
                parts.push(`expires ${mm}/${d.getUTCFullYear()}`);
            }
        }
        return parts.join(', ');
    }).join('; ');
}

function getWorkdayLicenseFollowUpTextValue(label, container = null) {
    const profile = window.__wdApplyData?.profile;
    const formatted = formatWorkdayLicenseFollowUpText(profile);
    if (formatted) return formatted;
    const required = container ? isContainerRequired(container) : String(label || '').includes('*');
    return required ? 'N/A' : '';
}

async function fillWorkdayLicenseFollowUpTextField(container, label) {
    const value = getWorkdayLicenseFollowUpTextValue(label, container);
    if (!value) return true;
    const control = container.querySelector('textarea')
        || container.querySelector('input[type="text"], input[type="search"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') {
        return false;
    }
    if ((control.value || '').trim()) return true;
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} filled license follow-up text`, String(label || '').slice(0, 70), value.slice(0, 80));
    return Boolean((control.value || '').trim());
}

/** Employment-conflict questions — always No, never stream to AI. */
function isWorkdayAlwaysNoQuestion(label, container = null) {
    if (container && isNotToMyKnowledgeQuestion(container, label)) return false;
    if (isWorkdayNotToMyKnowledgeLabel(label)) return false;
    if (isWorkdayGovernmentEmploymentQuestion(label)) return false;
    if (isWorkdayRelativeConflictTextField(label, container)) return false;
    if (isWorkdayPrivacyConsentDropdownField(label, container)) return false;
    if (isWorkdaySponsorshipRequiredQuestion(label)) return false;
    // Free-text "enter N/A / Not Applicable if No" — not a Yes/No control (micron.wd1).
    if (isWorkdayNaIfNoTextField(label)) return false;
    if (/please read before signing|equal employment opportunities/i.test(String(label || ''))) return false;
    const l = String(label || '').toLowerCase();
    if (/to the best of your knowledge/i.test(l)) return false;
    if (/certain federal law may require/i.test(l)) return false;
    if (/related to any of the following|executive officers.*directors|conflict of interest/i.test(l)) return true;
    // Non-compete free-text that asks for details / Not Applicable — handled as textarea, not Yes/No.
    if (/non-compete|non-solicit|restraint of trade|outside employment/i.test(l)) {
        if (container?.querySelector?.('textarea')
            && !container.querySelector('input[type="radio"], [role="radio"], [aria-haspopup="listbox"]')) {
            return false;
        }
        if (/please enter not applicable|enter not applicable|please provide details/i.test(l)) {
            return false;
        }
        return true;
    }
    // Relative / friend / vendor COI Yes/No (parsons.wd5 and similar)
    if (/relative or close friend of|relative of (?:a |any )?(?:\w+ )?employee|close friend of (?:a |any )?(?:\w+ )?(?:employee|customer|subcontractor|vendor)/i.test(l)) {
        return true;
    }
    if (/owner or employee of any outside company|currently or formerly doing business with/i.test(l)) return true;
    if (/current or former employee of the (?:us |u\.?s\.?\s*)?government or (?:us |u\.?s\.?\s*)?military/i.test(l)) {
        return true;
    }
    // HP-style Yes/No: past government/public-institution employment (not BAH PGE status dropdowns).
    if (/within the past \d+ years/i.test(l)
        && /employed by .{0,80}(?:federal|state|local).{0,40}government|public institution/i.test(l)) {
        return true;
    }
    if (/have you been employed by the federal or any state or local government/i.test(l)) return true;
    // Cisco-style: family / close personal contact of a government official (Yes/No dropdown).
    // Must be local No — streaming + miss-lock left this empty on cisco.wd5 questions.
    if (/family relationship|close personal contact/i.test(l)
        && /government official|public official|foreign government/i.test(l)) {
        return true;
    }
    if (getHardcodedYesNoAnswer(label) === 'No'
        && /government official|public official|politically exposed|family relationship.*government/i.test(l)) {
        return true;
    }
    return false;
}

async function fillWorkdayAlwaysNoField(container, label) {
    if (!container) return false;
    // Agree/Disagree acknowledgments must never be answered "No"
    if (isWorkdayPrivacyConsentDropdownField(label, container)
        || containerPreviewHasAgreeDisagreePair(container)
        || /please read before signing|equal employment opportunities/i.test(String(label || ''))) {
        return fillWorkdayPrivacyConsentDropdown(container, label);
    }
    if (isWorkdayRelativeConflictTextField(label, container)) {
        return fillWorkdayRelativeConflictTextField(container, label);
    }
    // Free-text non-compete / "enter Not Applicable if No" — never try Yes/No dropdown.
    if (isWorkdayNaIfNoTextField(label)
        || (container.querySelector('textarea')
            && /non-compete|non-solicit|non-disclosure|agreement which prevents/i.test(String(label || '')))) {
        const ok = await fillWorkdayNaIfNoTextField(container, label)
            || await (async () => {
                const ta = container.querySelector('textarea');
                if (!ta || (ta.value || '').trim()) return Boolean((ta?.value || '').trim());
                const text = getProfileFieldValue(window.__wdApplyData?.profile || {}, label || '')
                    || getWorkdayNaIfNoTextValue(label);
                if (!text) return false;
                workdayScrollToTarget(ta, 120);
                await workdayTypeElement(ta, text);
                debugLog(`${WD} always-no non-compete textarea`, String(label || '').slice(0, 70), text.slice(0, 40));
                return Boolean((ta.value || '').trim());
            })();
        if (ok) return true;
    }
    if (isWorkdayYesNoFieldLockedAndFilled(container, label)) return true;
    if (isWorkdayYesNoFilled(container, 'No') || isWorkdaySingleSelectFilled(container, ['No', 'no'])) {
        markWorkdayLockedYesNoFilled(label);
        return true;
    }
    // Prior stream/single-select miss must not block the local No path (cisco.wd5 family/gov official).
    clearWorkdaySingleSelectMissKey(label);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
    let ok = await fillWorkdayYesNoField(container, 'No');
    if (ok) markWorkdayLockedYesNoFilled(label);
    if (!ok && /related to any of the following|executive officers.*directors|conflict of interest|honesty and integrity|family relationship|government official|close personal contact/i.test(String(label || '').toLowerCase())) {
        const ctrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
        clearWorkdaySingleSelectMissKey(label);
        resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
        const noneCands = ['No - I do not have a conflict of interest', 'no - i do not have a conflict of interest',
            'None of the above', 'Neither', 'No', 'I am not related', 'Not related to either',
            'I am not related to either', 'None'];
        if (ctrl && await fillWorkdaySingleSelectDropdown(ctrl, noneCands, label)) {
            markWorkdayLockedYesNoFilled(label);
            debugLog(`${WD} always-no COI dropdown`, String(label || '').slice(0, 70), 'ok=', true);
            return true;
        }
        // Keyboard path when listbox can't be located after click (cisco.wd5): open, ArrowDown to No, Enter.
        if (ctrl && await selectWorkdayYesNoByKeyboard(container, ctrl, 'No')) {
            markWorkdayLockedYesNoFilled(label);
            debugLog(`${WD} always-no keyboard`, String(label || '').slice(0, 70), 'ok=', true);
            return true;
        }
    }
    ok = ok || isWorkdayYesNoFilled(container, 'No') || isWorkdaySingleSelectFilled(container, ['No', 'no']);
    debugLog(`${WD} always-no local fill`, String(label || '').slice(0, 70), 'ok=', ok);
    return ok;
}

/** Open a Yes/No combobox and pick Yes/No via keyboard when option listboxes aren't findable. */
async function selectWorkdayYesNoByKeyboard(container, trigger, answer) {
    const wantNo = /^no$/i.test(String(answer || ''));
    if (!trigger || !container) return false;
    clearWorkdaySingleSelectMissKey(getContainerLabel(container));
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(getContainerLabel(container)));
    await closeWorkdayPopups();
    await wait(300);
    workdayScrollToTarget(trigger, 120);
    await workdayClick(trigger);
    await wait(800);
    trigger.focus?.();
    // Typical Workday Yes/No list: Select One (hidden), Yes, No — two ArrowDown from closed reaches No.
    const downs = wantNo ? 2 : 1;
    for (let i = 0; i < downs; i++) {
        trigger.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
        document.activeElement?.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true,
        }));
        await wait(200);
    }
    trigger.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true, cancelable: true }));
    document.activeElement?.dispatchEvent(new KeyboardEvent('keydown', {
        key: 'Enter', code: 'Enter', bubbles: true, cancelable: true,
    }));
    await wait(600);
    await closeWorkdayPopups();
    await wait(300);
    return isWorkdayYesNoFilled(container, answer)
        || isWorkdaySingleSelectFilled(container, [answer, String(answer).toLowerCase()]);
}

function getWorkdayCurrentCompanyLocationText(profile = null) {
    profile = profile || window.__wdApplyData?.profile || {};
    const exp = (profile?.experiences || [])[0] || {};
    const company = String(exp.companyName || exp.company || '').trim();
    const loc = String(exp.location || exp.city || '').trim()
        || String(profile?.residencyCity || profile?.residency?.city || '').trim();
    const country = String(getProfileCountryName(profile) || '').trim();
    if (company && loc) return `${company}, ${loc}`;
    if (company && country) return `${company}, ${country}`;
    if (company) return company;
    if (loc && country) return `${loc}, ${country}`;
    return loc || country || 'N/A';
}

function getProfileFieldValue(profile, label) {
    profile = getProfileForJobLocation(profile);
    const l = label.toLowerCase();
    if (isWorkdayGenderIdentityField(l) || isWorkdayDisclosureGenderField(l)) return null;
    if (isWorkdaySmsConsentDropdownField(label)) return getWorkdaySmsConsentCandidates()[0];
    if (isWorkdayPrivacyConsentDropdownField(label)) return getWorkdayPrivacyConsentCandidates()[0];
    const profileDerivedYn = getProfileDerivedYesNoAnswer(profile, label);
    if (profileDerivedYn) return profileDerivedYn;
    const hardcodedYn = getHardcodedYesNoAnswer(l);
    if (hardcodedYn) return hardcodedYn;
    const stepKey = typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : '';
    const onQuestionsStep = stepKey === 'questions' || isApplicationQuestionStreamField(l);
    const email = profile?.email || profile?.general?.email;
    const firstName = profile?.firstName || profile?.general?.firstName;
    const lastName = profile?.lastName || profile?.general?.lastName;
    const phone = profile?.phone || profile?.general?.phone;
    const phoneCountry = profile?.phoneCountryCode || profile?.general?.phoneCountryCode;
    const residency = profile?.residency || profile?.general?.residency || {};
    const jobLocation = (window.__wdHistoryLocation || '').toLowerCase();

    if (/what was your work location|previous work location|former work location/i.test(l)
        && !/secure remote|do you have|are you able|remote work location\?/i.test(l)) {
        const exp = (profile?.experiences || [])[0];
        return exp?.location || exp?.city || residency.city || 'Remote';
    }
    // CorroHealth etc.: Yes/No — not a free-text location field
    if (/secure remote work location|have a secure remote|dedicated remote work(ing)? (space|location|environment)/i.test(l)) {
        return 'Yes';
    }
    // Sandvik internal "previous worker" reveal: company + site text (sandvik.wd3 information).
    if (/which company do you belong to|company do you belong to and where|belong to and where are you located/i.test(l)) {
        return getWorkdayCurrentCompanyLocationText(profile);
    }
    if (/who is your manager|what was your manager|name of your manager|manager'?s? name/i.test(l)
        && !/may we|permission|contact your/i.test(l)) {
        return 'N/A';
    }
    // Internal portal gate: reveal current-job follow-ups (sandvik.wd3).
    if (/select yes to this question.*current job|get information on your current job|additional questions will appear/i.test(l)) {
        return 'Yes';
    }
    // Standalone Job Title on questions (references / questionnaires)
    if (/^job title$|^title$/i.test(l.replace(/\*/g, '').trim())
        || (/job title/i.test(l) && l.length < 24 && !/current|previous|former|desired/i.test(l))) {
        const exp = (profile?.experiences || [])[0];
        return exp?.title || exp?.jobTitle || window.__wdHistoryRole || 'Professional';
    }
    if (/number of years (?:of )?full-?time teaching|years full-?time teaching/i.test(l)) {
        const years = Number(profile?.workingExperienceInYears ?? profile?.working_experience_in_years);
        if (Number.isFinite(years) && years >= 0) return String(Math.max(1, Math.round(years)));
        return '5';
    }
    if (/total years of experience|confirm your total years of experience/i.test(l)) {
        const years = Number(profile?.workingExperienceInYears ?? profile?.working_experience_in_years);
        if (Number.isFinite(years) && years > 0) {
            return Number.isInteger(years) ? String(years) : years.toFixed(1);
        }
        return '6';
    }
    if (/\bgpa\b|grade point average|overall result\s*\(gpa\)|overall gpa/i.test(l)) {
        // Band dropdowns need option matching — filled via fillWorkdayGpaField
        return null;
    }
    // Graduation / expected graduation date — profile education endDate as MM/DD/YYYY
    // (hoganlovells.wd3 streamed "N/A" into a masked date and left empty=1 forever).
    if (isWorkdayGraduationDateLabel(l)) {
        return getWorkdayGraduationDateValue(profile);
    }
    // Overseas relocation return date (unimelb.wd105) — MM/YYYY only.
    if (isWorkdayMonthYearReturnDateLabel(l)) {
        return getWorkdayNearTermMonthYear(2);
    }
    if (/graduation mark|expected .{0,20}mark|voto di laurea|final mark|final grade/i.test(l)
        && !/\bgpa\b|grade point/i.test(l)) {
        return '110';
    }
    // Employment bond / RSU / variable payout textareas (micron.wd1) — never stream N/A.
    if (/bonded by your|bond value|are you bonded/i.test(l)) return 'No';
    if (/variable\/bonus|bonus payout|rsus?\/stock|stock options/i.test(l)) return '0';
    if (/current ctc|expected ctc|cost to company/i.test(l)) {
        const amount = getWorkdayNumericSalaryValue(profile, label);
        if (amount) return amount;
    }
    if (/^subject\(s\) taught|^subjects? taught/i.test(l.replace(/\*/g, '').trim())) {
        return 'General / Multiple subjects';
    }
    if (/ages? you have taught/i.test(l)) return 'All ages';
    if (/curriculum\(s\) taught|curriculums? taught/i.test(l)) return 'Other';
    if (/employee email/i.test(l) && /former|previous|work|manager/i.test(l)) return email || '';
    if (/following capacity/i.test(l)) return null;
    if (isWorkdayGovernmentEmploymentQuestion(l)) {
        return getGovernmentEmploymentDropdownCandidates(l)[0] || null;
    }
    if (isWorkdayNotToMyKnowledgeLabel(l)) return null;
    if (isWorkdayClinicalSettingsQuestion(l)) return null;
    if (isWorkdayShiftAvailabilityQuestion(l)) return null;
    if (!onQuestionsStep && /currently employed|speak to your present employer|may we speak to your present employer/i.test(l)) {
        return 'Not currently employed';
    }
    // Office / basecamp site lists — never return residency city (waystar.wd1 streamed
    // "Jacksonville, US" into Atlanta/Duluth/Lehi/Louisville). Force stream+options instead.
    if (/basecamp|working from|which .{0,60}location would you be working|office location associated/i.test(l)) {
        return null;
    }
    if (/preferred location/i.test(l)) {
        const raw = (window.__wdHistoryLocation || '').trim();
        if (!raw) return null;
        const lines = raw.split('\n').map(s => s.trim()).filter(Boolean);
        const cityLine = lines.find(line => !/^locations?$/i.test(line));
        return cityLine || lines[lines.length - 1] || null;
    }
    if (isWorkdayPassportVisaTypeTextField(l)) {
        return getWorkdayPassportVisaTypeTextValue(label, profile);
    }
    if (isWorkdayFormerEmployerAffiliateTextField(l)) {
        return getWorkdayFormerEmployerAffiliateTextValue(label);
    }
    if (isWorkdayFormerEmployerTextFollowUp(l)) {
        return getWorkdayFormerEmployerTextFollowUpValue(label);
    }
    if (isWorkdayNotToMyKnowledgeLabel(l)) return null;
    if (/to the best of your knowledge/i.test(l)) return null;
    if (/certain federal law may require/i.test(l)) return null;
    if (!onQuestionsStep && /previously worked|worked at|worked for|have you worked|currently or have you worked|employed by|ever worked|ever been employed|former employee|former .{0,40}(?:team member|employee)|are you a former|affiliates|previously.*employee|previous employee|are you a previous|currently.*employee|were you.*employee|current.*employee|previously employed|been previously employed|previously been employed|current associates/i.test(l)) return 'No';
    // Guard with a length check: long consent/disclosure questions routinely mention "email" as
    // part of a sentence (e.g. "...contact you by email and by other electronic means...") without
    // being an email-address input at all. Matching on the bare word alone misroutes the question
    // to the candidate's email address instead of the Yes/No/consent value it actually needs,
    // leaving the real dropdown unfilled and the step stuck (see chrome-extension.mdc — Workday
    // step stuck: questions). Real "Email"/"Email Address"/"Personal Email" field labels are short.
    if (/\bemail\b/i.test(l) && l.length < 40 && !/employ|employee|former|johnson/i.test(l)) return email;
    if (/first name|given name/i.test(l) && !/local|furigana|kanji|latin|western/i.test(l)) return firstName;
    if (/last name|family name|surname/i.test(l) && !/local|furigana|kanji|latin|western/i.test(l)) return lastName;
    if (/local given name/i.test(l)) return firstName;
    if (/local family name/i.test(l)) return lastName;
    if (/given name.*latin|latin.*given name/i.test(l)) return firstName;
    if (/family name.*latin|latin.*family name|surname.*latin/i.test(l)) return lastName;
    if (/middle name/i.test(l)) return '';
    if (/georgian given/i.test(l)) return firstName;
    if (/georgian family/i.test(l)) return lastName;
    if (/phone number/i.test(l) && !/code|type|extension|consent|permission|text message|\bsms\b|granting|opt out|message & data|by selecting/i.test(l)
        && l.length < 80) {
        if (jobLocationExpectsJapanResidency()) return getJapanPhoneNumberForJob(profile);
        // Prefer region-safe candidates (India +91 / UK +44) over a stale US national number.
        const regionPhone = getNationalPhoneNumberCandidatesForWorkday(profile)[0];
        return regionPhone || getNationalPhoneNumberForWorkday(profile) || phone;
    }
    if (/phone extension/i.test(l)) return '';
    if (/phone device type/i.test(l)) return getPhoneDeviceTypeCandidates()[0];
    if (/country.*territory phone code|phone code/i.test(l)) {
        if (profileExpectsIndia(profile)) return 'India (+91)';
        return phoneCountry || '+1';
    }
    if (/address line 1|street address/i.test(l)) {
        if (jobLocationExpectsJapanResidency()) {
            if (/kanji/i.test(l)) return getJapanAddressKanji();
            if (/western/i.test(l)) return getJapanAddressWestern(profile, residency);
        }
        return residency.street || profile?.residencyStreet || getDefaultUSStreetForJobLocation();
    }
    if (/address line 2/i.test(l)) {
        // Required Address Line 2 on UK/EU tenants often expects building / flat number.
        return residency.buildingNumber || residency.apartmentNumber
            || profile?.residencyBuildingNumber || '';
    }
    if (/address line 3/i.test(l)) return jobLocationExpectsSaudiResidency() ? '-' : '';
    if (/^neighborhood$/i.test(l.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
        return getSaudiNeighborhoodDefault();
    }
    if (/^province$/i.test(l.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
        return getSaudiProvinceCandidates()[0];
    }
    // Conviction / criminal-history questions often mention "city of X" in legal text —
    // must not fall through to the City address mapping below.
    if (/felony|convicted|criminal record|crime other than a traffic|been convicted of a crime/i.test(l)) {
        return 'No';
    }
    // Yes/No locality check — not a City address field
    if (/live in the city where this job|currently live in (?:the )?city where/i.test(l)) {
        return 'Yes';
    }
    if (/\bcity\b/i.test(l) && !/convicted|crime|felony|applicant|respond \"|respond "|traffic violation|live in the city|where this job/i.test(l)) {
        if (/kanji/i.test(l) && jobLocationExpectsJapanResidency()) return getJapanCityKanji();
        if (/western/i.test(l) && jobLocationExpectsJapanResidency()) return getJapanCityFromJobLocation();
        if (profileExpectsUS(profile)) {
            const jobCity = getUSCityFromJobLocation();
            const jobState = getUSStateFromJobLocation();
            if (jobCity && jobState) {
                const profileZip = residency.zip || profile?.residencyZip;
                const profileState = profileZip ? getUSStateFromZip(profileZip) : deriveUSStateFromProfile(profile);
                if (!profileState || profileState !== jobState) return jobCity;
            }
            if (jobCity) return jobCity;
        }
        return residency.city || profile?.residencyCity || getUSCityFromJobLocation() || 'Boston';
    }
    if (/search address.*postal/i.test(l) && jobLocationExpectsJapanResidency()) return getJapanPostalCodeForJob();
    if (/\bprefecture\b/i.test(l) && jobLocationExpectsJapanResidency()) return getJapanPrefectureFromJob();
    if (/family name.*furigana/i.test(l)) return lastName || '';
    if (/given name.*furigana/i.test(l)) return firstName || '';
    if (/family name.*kanji/i.test(l)) return lastName || '';
    if (/given name.*kanji/i.test(l)) return firstName || '';
    if (/postal|zip/i.test(l)) return getWorkdayPostalCodeValue(profile);
    if (isWorkdayStateFieldLabel(l)) {
        return getConsistentUSStateForProfile(profile);
    }
    if (isWorkdayCountyFieldLabel(l)) {
        // US: county/city. UK: local authority / London borough from postcode — never "Greater London"
        // (not in Workday LA lists; stuck information on domesticandgeneral.wd3 and similar).
        return getCountyForProfile(profile);
    }
    if (/additional nationalit/i.test(l)) {
        // "Additional Nationalities" asks for OTHER nationalities beyond the primary one (isCountryFieldLabel
        // / isNationalityCountryFieldLabel below both match "national..." and would otherwise shadow this
        // check, forcing the SAME country as Primary Nationality into what is semantically a "does the
        // applicant hold any other citizenship" question). We have no profile data for a second
        // nationality, and this is virtually always an optional multi-select where "0 items selected" is
        // itself a valid, already-answered state (see fillWorkdayCountryDropdown's optional-empty-multiselect
        // guard) — returning a knownValue here (the previous 'N/A' never even matched a real dropdown option)
        // just wastes a fill attempt. Returning null instead defers to the required-field/generic-streaming
        // fallback so a genuinely required instance of this field still gets a real, option-matched answer.
        return null;
    }
    if (isCountryFieldLabel(l)) {
        return getWorkdayCountryName(profile);
    }
    if (isCitizenshipFieldLabel(l)) {
        return null;
    }
    if (isNationalityCountryFieldLabel(l)) {
        return getWorkdayCountryName(profile);
    }
    if (/date of birth/i.test(l)) {
        return getProfileDateOfBirth(profile);
    }
    if (/marital status/i.test(l)) {
        return jobLocationExpectsEgyptResidency() ? 'Single (Egypt)' : 'Single';
    }
    if (isGenpactAiMatchingOptInField(l)) return 'Opt In';
    if (/by selecting.*i accept|data protection policy|consent to your data being stored|consent to your data being/i.test(l)) {
        return 'I accept';
    }
    if (/how did you hear/i.test(l)) return null;
    if (isSalaryAlignmentYesNoQuestion(l)) {
        return getSalaryAlignmentYesNoAnswer(profile, label, null);
    }
    if (isCompensationFieldLabel(l)) {
        const amount = getProfileSalaryAmount(profile);
        if (/pay rate type|desired pay rate type/i.test(l)) {
            return 'Annual Salary';
        }
        if (isCompensationExpectationsNarrative(l)) {
            return getCompensationExpectationsNarrativeValue(profile);
        }
        if (/monthly/i.test(l) && !/annual/i.test(l)) {
            return getWorkdayNumericSalaryValue(profile, l);
        }
        if (isNumericCompensationField(l)) {
            return getWorkdayNumericSalaryValue(profile, l);
        }
        if (/desired salary|expected salary|salary expectation|what is your.*salary|pay expectation/i.test(l) && !/total/i.test(l)) {
            // Prefer numeric local amount for text inputs; range string is for $ dropdowns only
            return getWorkdayNumericSalaryValue(profile, l);
        }
        return formatWorkdayCompensationText(amount);
    }
    if (isNonDialysisHealthcareField(l)) {
        return getNonDialysisHealthcareCandidates(profile)[0];
    }
    if (isWorkdayAdditionalDetailsTextField(l)) {
        return getWorkdayAdditionalDetailsValue(profile);
    }
    if (!onQuestionsStep && /previously (worked|employed|work).*organization|have you (worked|been employed).*before|former.*employee|rehire/i.test(l)) return 'No';
    // Sponsorship listing field ("indicate locations or N/A")
    if (!onQuestionsStep && /locations.*require.*sponsorship|countries.*require.*sponsorship|require sponsorship.*for.*employment/i.test(l)) return 'N/A';
    if (!onQuestionsStep && /veteran status|protected veteran|veteran classification|indicate your veteran/i.test(l)) return 'I AM NOT A VETERAN';
    if (!onQuestionsStep && /disability status|disabled/i.test(l) && /self.?identify/i.test(l)) return 'I do not wish to self-identify';
    if (/\brace\b|\bethnicity\b|\bracial\b|select one option below|you may select one option/i.test(l) && !/race.*condition|race.*event/i.test(l)) {
        return mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity)[0];
    }
    if (!onQuestionsStep && /hispanic.*latino|latino.*hispanic/i.test(l)) return 'No';
    if (!onQuestionsStep && /^are you.*hispanic|^do you.*hispanic/i.test(l)) return 'No';
    // (felony/convicted handled earlier — before City address mapping)
    if (!onQuestionsStep && /under 18|below 18|less than 18|younger than 18/i.test(l)) return 'No';
    if (!onQuestionsStep && /at least 18|18 or older|legal age/i.test(l)) return 'Yes';
    if (/family member|relative.*(?:work|employ)/i.test(l)) return 'No';
    // Government/public body service or employment
    if (/government.*public body|public body.*regulatory|served.*government|serving.*government/i.test(l)) return 'No';
    if (/employee.*government|government.*employee|civil service|been.*employed.*government|government.*employ/i.test(l)) return 'No';
    if (/family member.*employed.*government|business partner.*government|government.*family member/i.test(l)) return 'No';
    if (/conflict.*interest|outside employment.*compensation|engage.*activities.*conflict/i.test(l)) return 'No';
    if (isWorkdayYearsExperienceBandQuestion(l)) {
        return getWorkdayYearsExperienceBandAnswer(l, null, profile);
    }
    if (/read carefully before signing|significant matters in connection with your application/i.test(l)) {
        return 'I have read and understand these statements.';
    }
    if (/united states armed (?:forces|services)|served in the (?:u\.?s\.?|united states) armed|military service|have you ever served/i.test(l)) {
        return 'No';
    }
    if (/select all that apply/i.test(l) && !isWorkdayShiftAvailabilityQuestion(l)
        && !/availability|available to work|shifts?\b/i.test(l)) {
        return 'None of the above';
    }
    // Non-competition, non-solicitation agreements
    if (/signed.*accepted.*agreement.*non-comp|non-competition.*non-disclosure|restrictions on competition/i.test(l)) return 'No';
    // Restricted country citizenship (long list of export-controlled countries)
    if (/for any of the countries listed below/i.test(l) || (/citizen.*passport/i.test(l) && /armenia|cuba|iran|north korea/i.test(l))) return 'No';
    if (/willing to relocate|relocate/i.test(l)) return 'Yes';
    if (/background check|drug test|pre-employment/i.test(l)) return 'Yes';
    if (/non-compete|non-solicit|non-disclosure/i.test(l)) {
        // Micron-style free-text: "If no, please enter Not Applicable."
        if (/not applicable/i.test(l) || isWorkdayNaIfNoTextField(label)) {
            return getWorkdayNaIfNoTextValue(label, profile);
        }
        return 'No. I am not subject to any non-compete, non-solicitation, or non-disclosure obligations with a current or former employer.';
    }
    if (isWorkdayFutureResidencyStateQuestion(l)) {
        return getConsistentUSStateForProfile(profile) || 'Florida';
    }
    if (isWorkdayAvailabilityDateLabel(l)) {
        const d = new Date();
        d.setDate(d.getDate() + 14);
        return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}/${d.getFullYear()}`;
    }
    if (/percentage.*travel|travel.*percentage|travel.*working time/i.test(l)) {
        if (/oconus/i.test(l)) return 'None';
        return '20%';
    }
    if (isWorkdayClearanceFieldLabel(l)) {
        return isWorkdayClearanceYesNoQuestion(l) ? 'No' : getWorkdayClearanceCandidates()[0];
    }
    // Marketing / advertising opt-ins often mention LinkedIn as a channel — not a URL field
    if (/share my personal information with its advertising partners|advertising partners|news and updates about .{0,40}careers/i.test(l)) {
        return 'No';
    }
    if (/linkedin/i.test(l)
        && !/advertising|share my personal|partners to show|news and updates|i would like .{0,40}share/i.test(l)) {
        const raw = profile?.linkedinUrl || profile?.general?.linkedinUrl || '';
        return normalizeLinkedInUrl(raw);
    }
    if (/^name$/i.test(l.trim())) {
        const fn = profile?.firstName || profile?.general?.firstName || '';
        const ln = profile?.lastName || profile?.general?.lastName || '';
        return `${fn} ${ln}`.trim();
    }
    if (/^date$/i.test(l.trim())) {
        const d = new Date();
        return `${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}/${d.getFullYear()}`;
    }
    if (/microsoft excel|excel proficiency|proficiency with microsoft excel|level of proficiency with.*excel/i.test(l)) {
        return 'Advanced';
    }
    if (/google workspace|microsoft office|office 365|ms office|proficiency with (?:google|microsoft)/i.test(l)) {
        return 'Advanced';
    }
    if (/hris|human resource information system/i.test(l)) {
        if (/possess|do you|have you/i.test(l)) return 'Yes';
        return 'Advanced';
    }
    if (/my proficiency with|proficiency with/i.test(l)) return 'Advanced';
    if (/proficiency|fluency/i.test(l) && /software|tool|system|technology|workspace|office/i.test(l)) return 'Advanced';
    if (/additional details about your right to work|provide any additional details.*right to work/i.test(l)) {
        return 'I have the unrestricted right to work in the UK.';
    }
    if (/current right to work status in the (?:uk|united kingdom)|right to work status in the uk/i.test(l)) {
        return 'British Citizen';
    }
    if (/sexual orientation|lgbtqia/i.test(l)) return 'Prefer Not to Respond';
    if (/person with a disability|disability act|consider yourself to have a disability|do you have a disability/i.test(l)) {
        return 'No';
    }
    if (/sex at birth|sex.*birth|biological sex|please select your sex|please indicate your sex|select your sex/i.test(l)) return 'Decline to Answer';
    if (/veteran/i.test(l)) return mapProfileVeteranToWorkday(profile?.general?.veteranStatus);
    if (/ethnic|race|hispanic|latino|self.?ident|eeo|ofccp/i.test(l)) {
        return mapProfileRaceToWorkday(profile?.general?.raceEthnicity);
    }
    if (/sex\b/i.test(l)) return WORKDAY_DECLINE_PHRASES[0];
    return null;
}

function getWorkdayProfileDomainSummary(profile) {
    const general = profile?.general || {};
    const headline = String(profile?.headline || general.headline || '').trim();
    const title = String(profile?.title || general.title || '').trim();
    const summary = String(profile?.professionalSummary || general.professionalSummary || '').trim();
    const experiences = Array.isArray(profile?.experiences) ? profile.experiences : [];
    const corpus = [
        headline,
        title,
        summary,
        ...experiences.slice(0, 4).flatMap(exp => [
            exp?.title || '',
            exp?.companyName || '',
            exp?.brief || '',
            exp?.description || '',
        ]),
    ].join(' ').toLowerCase();
    const tags = [];
    if (/(retail|store|merchandise|inventory|sales associate|customer experience associate|walmart|target|cvs|walgreens|footwear|craft)/i.test(corpus)) {
        tags.push('retail operations');
    }
    if (/(bank|credit union|financial|cash|teller|payment|account|transaction)/i.test(corpus)) {
        tags.push('financial services');
    }
    if (/(facilit|documentation|records?|document control|administrative|operations|warehouse|process compliance|data entry)/i.test(corpus)) {
        tags.push('operations support');
    }
    if (/(healthcare|hospital|clinic|dialysis|medical|patient)/i.test(corpus)) {
        tags.push('healthcare support');
    }
    if (tags.length) return [...new Set(tags)].slice(0, 3).join(', ');
    if (headline) return headline.split(/[|,]/).map(s => s.trim()).filter(Boolean).slice(0, 2).join(', ');
    if (title) return title;
    return 'operations and customer support';
}

function isWorkdayAdditionalDetailsTextField(label) {
    const l = String(label || '').toLowerCase();
    return /please provide additional details|additional details to your answer|provide additional details|explain your answer above|details to your answer above/i.test(l);
}

function getWorkdayAdditionalDetailsValue(profile, container = null) {
    const scopeText = [
        container?.innerText || '',
        container?.previousElementSibling?.innerText || '',
        container?.parentElement?.innerText || '',
    ].join(' ').toLowerCase();
    if (/non-?dialysis|hospital|healthcare|place of work/i.test(scopeText)) {
        const exp = (profile?.experiences || [])[0];
        const company = exp?.companyName || 'a healthcare organization';
        const title = exp?.title || profile?.title || 'healthcare operations';
        return `Most recently worked in a hospital / medical-center setting as ${title} at ${company}, supporting clinical and operational healthcare programs.`;
    }
    return getWorkdayOtherSpecifyValue(profile, container);
}

function getWorkdayOtherSpecifyValue(profile, container) {
    const scopeText = [
        container?.innerText || '',
        container?.previousElementSibling?.innerText || '',
        container?.nextElementSibling?.innerText || '',
        container?.parentElement?.innerText || '',
        container?.closest('fieldset,[role="group"],[data-automation-id*="fieldSet"],[data-automation-id*="formField"]')?.innerText || '',
    ].join(' ').toLowerCase();

    if (/how did you hear|referral|source/.test(scopeText)) {
        return 'LinkedIn job search';
    }
    if (/current or most recent place of work|place of work|work environment|employer type|industry|amazon|walmart|target|walgreens|cvs|restaurant\/food service|government services|industrial or trade services|us military|non-?dialysis|additional details/.test(scopeText)) {
        return getWorkdayProfileDomainSummary(profile);
    }
    return getWorkdayProfileDomainSummary(profile);
}

function isNonDialysisHealthcareField(label) {
    return /non-?dialysis healthcare/i.test(String(label || ''));
}

function getNonDialysisHealthcareCandidates(profile) {
    const corpus = [
        profile?.title || '',
        profile?.headline || '',
        ...(profile?.experiences || []).flatMap(e => [e?.title || '', e?.companyName || '', e?.description || '', e?.brief || '']),
    ].join(' ').toLowerCase();
    const ranked = [];
    if (/hospital|medical center|pediatrics|inpatient|acute/i.test(corpus)) {
        ranked.push('Hospital');
    }
    if (/outpatient|ambulatory|infusion|surgery center|clinic/i.test(corpus)) {
        ranked.push('Outpatient Services (Outpatient surgery, ambulatory, infusion, dentistry)');
        ranked.push('Outpatient Services');
    }
    if (/pharma|pharmacy|walgreens|cvs|riteaid/i.test(corpus)) {
        ranked.push('Pharmaceutical Industry (Walgreens, CVS, RiteAid, other)');
        ranked.push('Pharmaceutical Industry');
    }
    if (/nursing|long term|skilled nursing|ltc/i.test(corpus)) {
        ranked.push('Long Term Care/Skilled Nursing Facility');
    }
    if (/ems|emergency medical|fire/i.test(corpus)) {
        ranked.push('Emergency Medical Services (EMS, Fire, other)');
    }
    ranked.push(
        'Hospital',
        'Outpatient Services (Outpatient surgery, ambulatory, infusion, dentistry)',
        'Outpatient Services',
        'Pharmaceutical Industry (Walgreens, CVS, RiteAid, other)',
        'Long Term Care/Skilled Nursing Facility',
        'Emergency Medical Services (EMS, Fire, other)',
    );
    return [...new Set(ranked)];
}

async function fillWorkdayNonDialysisHealthcareField(container, profile, label) {
    if (!container) return false;
    const candidates = getNonDialysisHealthcareCandidates(profile);
    if (isWorkdaySingleSelectFilled(container, candidates)) return true;
    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!control) return false;
    debugLog(`${WD} non-dialysis healthcare fill`, String(label || '').slice(0, 50), candidates[0]);
    return fillWorkdaySingleSelectDropdown(control, candidates, String(label || '').toLowerCase());
}

function normalizeLinkedInUrl(url) {
    if (!url) return 'https://www.linkedin.com/in/profile';
    let u = String(url).trim();
    if (!/^https?:\/\//i.test(u)) u = `https://${u.replace(/^\/\//, '')}`;
    u = u.replace(/^https?:\/\/(?:www\.)?linkedin\.com/i, 'https://www.linkedin.com');
    if (/^https:\/\/www\.linkedin\.com\//i.test(u)) return u;
    const m = u.match(/linkedin\.com\/(.+)/i);
    return m ? `https://www.linkedin.com/${m[1].replace(/^\/+/, '')}` : 'https://www.linkedin.com/in/profile';
}

function getExperienceEndFallback(dates) {
    if (dates?.end) return dates.end;
    if (!dates?.start) {
        const y = String(new Date().getFullYear());
        return { year: y, month: 'December', iso: `${y}-12` };
    }
    const m = (dates.start.iso || '').match(/(\d{4})-(\d{2})/);
    if (!m) return null;
    const year = String(Number(m[1]) + 1);
    return { year, month: dates.start.month, iso: `${year}-${m[2]}` };
}

function isExperienceCurrent(entry) {
    if (!entry) return false;
    if (entry.workingHereNow) return true;
    if (entry.endDate == null || entry.endDate === '') return true;
    if (typeof entry.endDate === 'string' && /^present$/i.test(String(entry.endDate).trim())) return true;
    return false;
}

async function syncExperienceCurrentlyWorking(root, entry) {
    const shouldCheck = isExperienceCurrent(entry);
    for (const container of root.querySelectorAll('[data-automation-id*="formField"]')) {
        const labelLower = getContainerLabel(container).toLowerCase();
        if (!/currently work|work here|present/i.test(labelLower)) continue;
        const cb = container.querySelector('input[type="checkbox"]');
        if (cb && cb.checked !== shouldCheck) {
            debugLog(`${WD} sync currently work here`, shouldCheck);
            await workdayClick(cb);
            await wait(400);
        }
        return;
    }
}

function formatWorkdayMMYYYY(dateStr) {
    if (!dateStr) return null;
    if (typeof dateStr === 'object' && dateStr.iso) {
        const m = dateStr.iso.match(/(\d{4})-(\d{2})/);
        return m ? `${m[2]}/${m[1]}` : null;
    }
    if (typeof dateStr === 'number') {
        const ms = toEpochMillis(dateStr);
        const dt = new Date(ms);
        if (!Number.isNaN(dt.getTime())) {
            return `${String(dt.getUTCMonth() + 1).padStart(2, '0')}/${dt.getUTCFullYear()}`;
        }
    }
    const m = String(dateStr).match(/(\d{4})-(\d{2})/);
    return m ? `${m[2]}/${m[1]}` : null;
}

function formatWorkdayYYYY(dateStr) {
    const m = String(dateStr).match(/(\d{4})/);
    return m ? m[1] : null;
}

function isMMYYYYPreview(preview) {
    return /mm\/yyyy|mm\s*\/\s*yyyy/.test(preview);
}

function isMMDDYYYYPreview(preview) {
    return /mm\/dd\/yyyy|mm\s*\/\s*dd\s*\/\s*yyyy/.test(preview);
}

function normalizeMMDDYYYY(value) {
    const m = String(value || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (!m) return null;
    return `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[3]}`;
}

// Accepts MM/DD/YYYY, M/D/YYYY, ISO YYYY-MM-DD, or MM-DD-YYYY and returns zero-padded
// MM/DD/YYYY (or MM/YYYY passthrough) for fillWorkdayMaskedDate. Returns null if unparsed —
// callers must not force-type an unparsed value into a masked date widget.
function normalizeWorkdayDateForMaskedField(value) {
    const v = String(value || '').trim();
    if (/^\d{2}\/\d{4}$/.test(v)) return v;
    let m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) return `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[3]}`;
    m = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
    if (m) return `${m[2].padStart(2, '0')}/${m[3].padStart(2, '0')}/${m[1]}`;
    m = v.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/);
    if (m) return `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[3]}`;
    return null;
}

function isWorkdayMaskedDateField(container, label = '') {
    const labelLower = String(label || '').toLowerCase();
    const preview = (container?.innerText || '').toLowerCase();
    if (isWorkdayMonthYearReturnDateLabel(labelLower)) return true;
    return /^date$/i.test(labelLower)
        || isMMDDYYYYContainer(container)
        || (/\bdate\b/i.test(labelLower) && (isMMDDYYYYPreview(preview) || isMMYYYYPreview(preview) || /dd\/yyyy|mm\/yyyy/.test(preview)));
}

function isWorkdayDateFieldIncomplete(container) {
    const preview = (container?.innerText || '').replace(/\s+/g, ' ');
    if (/invalid date|error:/i.test(preview)) return true;
    if (/mm\/dd\/yyyy|dd\/yyyy|mm\s*\/\s*dd/i.test(preview)) return true;
    const control = getContainerControl(container);
    const val = (control?.value || '').trim();
    if (val && /dd|yyyy|mm/i.test(val)) return true;
    return false;
}

function areSplitDateInputsFilled(container, mm, dd, yyyy) {
    const monthInput = container.querySelector('input[aria-label="Month"], input[aria-label*="Month" i]');
    const dayInput = container.querySelector('input[aria-label="Day"], input[aria-label*="Day" i]');
    const yearInput = container.querySelector('input[aria-label="Year"], input[aria-label*="Year" i]');
    if (!monthInput || !dayInput || !yearInput) return false;
    return parseInt(monthInput.value, 10) === parseInt(mm, 10)
        && parseInt(dayInput.value, 10) === parseInt(dd, 10)
        && parseInt(yearInput.value, 10) === parseInt(yyyy, 10);
}

/** Workday still rejects Date even when Month/Day/Year inputs show values (belron.wd3 self_identify). */
function dateContainerHasBlockingError(container) {
    if (!container) return false;
    const errEl = container.querySelector?.('[data-automation-id="errorMessage"]');
    const errText = (errEl?.innerText || '').toLowerCase();
    if (/required|invalid date|must end after/i.test(errText)) return true;
    const text = (container.innerText || '').replace(/\s+/g, ' ');
    return /error:\s*the field .{0,40}is require|error:\s*.{0,40}invalid date|must end after/i.test(text);
}

function isDateContainerFilled(container, expectedValue) {
    // Never trust DOM values alone while Workday shows a required/invalid banner —
    // belron.wd3 self_identify: "07 / 25 / 2026" + "Error: The field Date is required".
    if (dateContainerHasBlockingError(container)) return false;
    if (expectedValue && /^\d{2}\/\d{2}\/\d{4}$/.test(expectedValue)) {
        const [mm, dd, yyyy] = expectedValue.split('/');
        if (areSplitDateInputsFilled(container, mm, dd, yyyy)) return true;
    }
    const text = (container.innerText || '').replace(/\s+/g, ' ');
    const errEl = container.querySelector('[data-automation-id="errorMessage"]');
    const errText = (errEl?.innerText || '').toLowerCase();
    if (/invalid date|error:|must end after/i.test(text) || /invalid date|must end after/i.test(errText)) {
        if (expectedValue && /^\d{2}\/\d{4}$/.test(expectedValue)) {
            const [mm, yyyy] = expectedValue.split('/');
            if (!new RegExp(`\\b0?${Number(mm)}\\s*/\\s*${yyyy}\\b`).test(text)) return false;
        } else if (expectedValue && /^\d{2}\/\d{2}\/\d{4}$/.test(expectedValue)) {
            const [mm, dd, yyyy] = expectedValue.split('/');
            if (!text.includes(`${mm}/${dd}/${yyyy}`)
                && !new RegExp(`\\b0?${Number(mm)}\\s*/\\s*0?${Number(dd)}\\s*/\\s*${yyyy}\\b`).test(text)) {
                return false;
            }
        } else {
            return false;
        }
    }
    if (/invalid date|error:/i.test(text) && /invalid date/i.test(errText)) return false;
    if (expectedValue && /^\d{2}\/\d{2}\/\d{4}$/.test(expectedValue)) {
        const [mm, dd, yyyy] = expectedValue.split('/');
        return text.includes(`${mm}/${dd}/${yyyy}`)
            || new RegExp(`\\b0?${Number(mm)}\\s*/\\s*0?${Number(dd)}\\s*/\\s*${yyyy}\\b`).test(text);
    }
    if (expectedValue && /^\d{2}\/\d{4}$/.test(expectedValue)) {
        const [mm, yyyy] = expectedValue.split('/');
        return new RegExp(`\\b0?${Number(mm)}\\s*/\\s*${yyyy}\\b`).test(text)
            || text.includes(`${mm}/${yyyy}`)
            || text.includes(`${mm} / ${yyyy}`);
    }
    if (expectedValue && /^\d{4}$/.test(String(expectedValue))) {
        return new RegExp(`\\b${expectedValue}\\b`).test(text) && !/mm\/yyyy/i.test(text);
    }
    return false;
}

function selectWorkdayInputText(el) {
    if (!el) return;
    try {
        if (typeof el.select === 'function') {
            el.select();
            return;
        }
        if (typeof el.setSelectionRange === 'function') {
            const len = (el.value || '').length;
            el.setSelectionRange(0, len);
        }
    } catch (_) { /* ignore */ }
}

async function typeWorkdayDatePart(el, part) {
    if (!el || part == null) return false;
    el.focus?.();
    selectWorkdayInputText(el);
    setNativeValue(el, '');
    el.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    await wait(100);
    const str = String(part);
    let inserted = false;
    try {
        inserted = document.execCommand('insertText', false, str);
    } catch (_) { /* ignore */ }
    if (!inserted) wdSetInputValue(el, str);
    el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: str, bubbles: true, composed: true }));
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    await wait(200);
    return Boolean((el.value || '').trim());
}

/** Focus-only keystroke fill — never click date inputs (click can stall minutes on WD date widgets). */
async function typeWorkdayDatePartKeystroke(el, part) {
    if (!el || part == null) return false;
    try { el.focus?.(); } catch (_) { /* ignore */ }
    await wait(40);
    selectWorkdayInputText(el);
    setNativeValue(el, '');
    el.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    await wait(60);
    const str = String(part);
    for (const ch of str) {
        el.dispatchEvent(new KeyboardEvent('keydown', { key: ch, bubbles: true, composed: true }));
        setNativeValue(el, (el.value || '') + ch);
        el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: ch, bubbles: true, composed: true }));
        el.dispatchEvent(new KeyboardEvent('keyup', { key: ch, bubbles: true, composed: true }));
        await wait(30);
    }
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(80);
    return Boolean((el.value || '').trim());
}

async function clearWorkdayDateField(container) {
    for (const inp of container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"]):not([type="radio"])')) {
        setNativeValue(inp, '');
        inp.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
        inp.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    }
    await wait(200);
}

function dumpWorkdayDateContainerDom(container, tag = '') {
    if (!container) return;
    try {
        const inputs = [...container.querySelectorAll('input')].map(inp => ({
            type: inp.type || '',
            role: inp.getAttribute('role') || '',
            aria: inp.getAttribute('aria-label') || '',
            name: inp.name || '',
            id: (inp.id || '').slice(0, 40),
            auto: inp.getAttribute('data-automation-id') || '',
            value: (inp.value || '').slice(0, 20),
            ph: (inp.placeholder || '').slice(0, 24),
        }));
        const buttons = [...container.querySelectorAll('button, [role="button"], [data-automation-id*="date" i], [data-automation-id*="calendar" i]')]
            .slice(0, 12)
            .map(b => ({
                tag: b.tagName,
                auto: b.getAttribute('data-automation-id') || '',
                aria: (b.getAttribute('aria-label') || '').slice(0, 60),
                text: (b.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 40),
            }));
        debugLog(`${WD} date DOM ${tag}`, JSON.stringify({ inputs, buttons }).slice(0, 900));
    } catch (e) {
        debugLog(`${WD} date DOM dump failed`, e?.message || e);
    }
}

/** Open date-picker calendar and click today — used when typed values don't commit (belron.wd3). */
async function fillWorkdayDateViaCalendarToday(container) {
    if (!container) return false;
    const openers = [
        ...container.querySelectorAll(
            'button[aria-label*="calendar" i], button[aria-label*="date" i], '
            + '[data-automation-id*="dateIcon" i], [data-automation-id*="calendar" i], '
            + 'button[data-automation-id*="date" i], [aria-haspopup="dialog"]'
        ),
    ].filter(isVisibleElement);
    if (!openers.length) {
        // Sometimes the icon is a sibling of the formField container
        const parent = container.parentElement;
        if (parent) {
            openers.push(...parent.querySelectorAll(
                'button[aria-label*="calendar" i], button[aria-label*="date" i], '
                + '[data-automation-id*="dateIcon" i], [data-automation-id*="calendar" i]'
            ));
        }
    }
    const opener = openers.find(isVisibleElement);
    if (!opener) {
        debugLog(`${WD} date calendar opener not found`);
        return false;
    }
    debugLog(`${WD} date calendar open`, opener.getAttribute('data-automation-id') || opener.getAttribute('aria-label') || opener.tagName);
    // Keyboard-only open — workdayClick/.click() on WD date icons can stall for minutes.
    try { opener.focus?.(); } catch (_) { /* ignore */ }
    for (const key of [' ', 'Enter', 'ArrowDown']) {
        opener.dispatchEvent(new KeyboardEvent('keydown', { key, code: key === ' ' ? 'Space' : key, bubbles: true, composed: true }));
        opener.dispatchEvent(new KeyboardEvent('keyup', { key, code: key === ' ' ? 'Space' : key, bubbles: true, composed: true }));
        await wait(250);
        const popupEarly = document.querySelector(
            '[data-automation-id="datePickerPopup"], [data-automation-id*="datePicker" i], '
            + '[role="dialog"][aria-label*="date" i], [role="dialog"][aria-label*="calendar" i]'
        );
        if (popupEarly) break;
    }
    // Soft pointer events without HTMLElement.click() (avoids the known stall path).
    let popup = document.querySelector(
        '[data-automation-id="datePickerPopup"], [data-automation-id*="datePicker" i], '
        + '[role="dialog"][aria-label*="date" i], [role="dialog"][aria-label*="calendar" i], [role="dialog"]'
    );
    if (!popup) {
        const rect = opener.getBoundingClientRect();
        const x = rect.left + Math.min(rect.width / 2, Math.max(rect.width - 2, 1));
        const y = rect.top + Math.min(rect.height / 2, Math.max(rect.height - 2, 1));
        const opts = { bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y };
        opener.dispatchEvent(new PointerEvent('pointerdown', opts));
        opener.dispatchEvent(new MouseEvent('mousedown', opts));
        opener.dispatchEvent(new MouseEvent('mouseup', opts));
        opener.dispatchEvent(new PointerEvent('pointerup', opts));
        await wait(500);
        popup = document.querySelector(
            '[data-automation-id="datePickerPopup"], [data-automation-id*="datePicker" i], [role="dialog"]'
        );
    }
    if (!popup) {
        dumpWorkdayDateContainerDom(container, 'no-calendar-popup');
        return false;
    }
    const todayBtn = [...popup.querySelectorAll('button, [role="button"], [role="gridcell"], td, div')]
        .find(el => {
            const t = `${el.getAttribute('aria-label') || ''} ${el.innerText || ''}`.toLowerCase();
            return /today/i.test(t) && isVisibleElement(el);
        });
    if (todayBtn) {
        workdayClickElement(todayBtn);
        await wait(400);
        debugLog(`${WD} date calendar clicked Today`);
        await closeWorkdayPopups('date-calendar');
        return true;
    }
    // Fallback: click the gridcell marked current / selected / aria-current
    const cell = popup.querySelector(
        '[aria-current="date"], [aria-selected="true"], '
        + 'button[class*="today" i], [data-automation-id*="today" i], '
        + 'td[aria-selected="true"], [role="gridcell"][aria-selected="true"]'
    );
    if (cell && isVisibleElement(cell)) {
        workdayClickElement(cell);
        await wait(400);
        debugLog(`${WD} date calendar clicked current cell`, (cell.getAttribute('aria-label') || cell.innerText || '').slice(0, 40));
        await closeWorkdayPopups('date-calendar');
        return true;
    }
    dumpWorkdayDateContainerDom(popup, 'calendar-popup');
    await closeWorkdayPopups('date-calendar');
    return false;
}

async function fillWorkdaySplitDateParts(container, mm, dd, yyyy, { force = false } = {}) {
    const monthInput = container.querySelector('input[aria-label="Month"], input[aria-label*="Month" i]');
    const dayInput = container.querySelector('input[aria-label="Day"], input[aria-label*="Day" i]');
    const yearInput = container.querySelector('input[aria-label="Year"], input[aria-label*="Year" i]');
    if (!monthInput || !dayInput || !yearInput) return false;

    if (force) dumpWorkdayDateContainerDom(container, 'force-start');

    const preview = (container.innerText || '').toLowerCase();
    if (force || /invalid date|error:/i.test(preview) || dateContainerHasBlockingError(container)) {
        await clearWorkdayDateField(container);
    }

    debugLog(`${WD} split date fill start`, mm, dd, yyyy, 'force=', force);
    // Prefer focus+type — never click Month/Day/Year (hp.wd5 / belron.wd3: click stalls minutes).
    // Do NOT use per-keystroke setNativeValue here — it freezes the WD date widget for minutes/char.
    for (const [el, part, name] of [[monthInput, mm, 'month'], [dayInput, dd, 'day'], [yearInput, yyyy, 'year']]) {
        try { el.focus?.(); } catch (_) { /* ignore */ }
        await wait(40);
        await typeWorkdayDatePart(el, part);
        debugLog(`${WD} split date part`, name, part, 'value=', (el.value || '').trim());
    }
    // Tab through parts so React controlled state commits (belron.wd3 self_identify Date).
    for (const el of [monthInput, dayInput, yearInput]) {
        try { el.focus?.(); } catch (_) { /* ignore */ }
        el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true, composed: true }));
        el.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(80);
    }
    const footer = document.querySelector('[data-automation-id="applicationFooter"], [data-automation-id="pageFooter"]');
    if (footer) footer.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
    await wait(500);
    const dateValue = `${mm}/${dd}/${yyyy}`;
    let ok = isDateContainerFilled(container, dateValue)
        || (force && areSplitDateInputsFilled(container, mm, dd, yyyy) && !dateContainerHasBlockingError(container));
    // Calendar Today only when typed values still leave a blocking error — opening the picker
    // on every force fill can stall and also wipe sibling Name React state (belron.wd3).
    if (force && (dateContainerHasBlockingError(container) || !areSplitDateInputsFilled(container, mm, dd, yyyy))) {
        const calOk = await fillWorkdayDateViaCalendarToday(container);
        await wait(400);
        ok = calOk || isDateContainerFilled(container, dateValue)
            || areSplitDateInputsFilled(container, mm, dd, yyyy);
        debugLog(`${WD} split date calendar fallback`, 'calOk=', calOk, 'ok=', ok);
    }
    debugLog(`${WD} split date fill done`, dateValue, 'ok=', ok, 'blockingErr=', dateContainerHasBlockingError(container));
    return ok;
}

async function fillWorkdayMMYYYYDate(container, dateValue) {
    if (!container || !/^\d{2}\/\d{4}$/.test(dateValue)) return false;
    const [mm, yyyy] = dateValue.split('/');
    if (isDateContainerFilled(container, dateValue) && !/must end after|invalid date|error:/i.test(container.innerText || '')) {
        return true;
    }
    await clearWorkdayDateField(container);
    await wait(200);
    const monthInput = container.querySelector('input[aria-label="Month"], input[aria-label*="Month" i]');
    const yearInput = container.querySelector('input[aria-label="Year"], input[aria-label*="Year" i]');
    const visibleInputs = [...container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"])')]
        .filter(isVisibleElement);
    const mInp = monthInput || visibleInputs[0];
    const yInp = yearInput || visibleInputs[1];
    if (!mInp || !yInp) return false;
    debugLog(`${WD} filling month/year inputs`, mm, yyyy);
    await workdayClick(mInp);
    await typeWorkdayDatePart(mInp, mm);
    await wait(250);
    await workdayClick(yInp);
    await typeWorkdayDatePart(yInp, yyyy);
    yInp.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(600);
    if (!isDateContainerFilled(container, dateValue)) {
        await clearWorkdayDateField(container);
        await wait(150);
        await typeWorkdayDatePart(mInp, mm);
        await wait(200);
        await typeWorkdayDatePart(yInp, yyyy);
        yInp.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(600);
    }
    return isDateContainerFilled(container, dateValue);
}

async function fillWorkdayMaskedDate(container, control, dateValue, preview, { force = false } = {}) {
    const hasErr = force || dateContainerHasBlockingError(container)
        || /invalid date|error:/i.test(container?.innerText || '')
        || /invalid date|error:/i.test(String(preview || ''));
    if (!hasErr && isDateContainerFilled(container, dateValue)) return true;

    if ((isMMDDYYYYPreview(preview) || isMMDDYYYYContainer(container)) && /^\d{2}\/\d{2}\/\d{4}$/.test(dateValue)) {
        const [mm, dd, yyyy] = dateValue.split('/');
        if (await fillWorkdaySplitDateParts(container, mm, dd, yyyy, { force: hasErr })) return true;
        debugLog(`${WD} split date retry after invalid`, (container.innerText || '').replace(/\s+/g, ' ').slice(0, 80));
        if (await fillWorkdaySplitDateParts(container, mm, dd, yyyy, { force: true })) return true;
        // Unpadded month/day variant (some tenants display 7/25/2026 while inputs want 07).
        const mmAlt = String(Number(mm));
        const ddAlt = String(Number(dd));
        if ((mmAlt !== mm || ddAlt !== dd)
            && await fillWorkdaySplitDateParts(container, mmAlt.padStart(2, '0'), ddAlt.padStart(2, '0'), yyyy, { force: true })) {
            return true;
        }
        return isDateContainerFilled(container, dateValue)
            || areSplitDateInputsFilled(container, mm, dd, yyyy);
    }

    if (/^\d{2}\/\d{4}$/.test(dateValue)) {
        const visibleInputs = [...container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"])')]
            .filter(isVisibleElement);
        if (isMMYYYYPreview(preview) || visibleInputs.length === 2
            || container.querySelector('input[aria-label*="Month" i]')) {
            if (await fillWorkdayMMYYYYDate(container, dateValue)) return true;
        }
    }

    const formats = isMMYYYYPreview(preview) && /^\d{2}\/\d{4}$/.test(dateValue)
        ? [dateValue, dateValue.replace('/', ''), `${dateValue.split('/')[0]}${dateValue.split('/')[1]}`]
        : [dateValue];

    for (const fmt of formats) {
        await workdayClick(control);
        await wait(250);
        await workdayTypeElement(control, fmt);
        await wait(400);
        if (isDateContainerFilled(container, dateValue)) return true;
    }

    setNativeValue(control, dateValue);
    control.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: dateValue, bubbles: true, composed: true }));
    control.dispatchEvent(new Event('change', { bubbles: true }));
    control.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true }));
    await wait(400);
    return isDateContainerFilled(container, dateValue);
}

// Many tenants render degree-level options as abbreviated codes, and formatting of those
// codes varies ("BS" vs "B.S." vs "b.s.") — normalize away periods/whitespace before any
// abbreviation comparison so both forms resolve identically (observed on ryder.wd5 with
// "b.s." / "b.a." / "b.b.a." / "a.s." / "a.a." — not tenant-specific, any Workday tenant
// using dotted degree codes hits this).
function normalizeDegreeAbbrev(text) {
    return String(text || '').toLowerCase().replace(/[.\s]/g, '');
}

const WORKDAY_DEGREE_ABBREVIATIONS = [
    'hs', 'ged', 'aa', 'as', 'aas', 'ba', 'bs', 'bas', 'bba', 'bsc', 'bsba', 'be', 'beng', 'btech',
    // tutorperini.wd12 (and similar) use short codes BACH / MAST instead of BA/BS / MA/MS.
    'bach', 'mast', 'doct', 'assoc', 'cert', 'dipl',
    'ma', 'ms', 'msc', 'mba', 'med', 'meng', 'mtech', 'jd', 'md', 'phd', 'edd', 'dsc',
];

// Resolves a dropdown's degree options against the profile's degree candidates using
// dot/space-normalized abbreviation comparison. Returns the matching option element or null —
// callers fall back to word-based matching (e.g. "Bachelor's Degree") when this misses.
function findDegreeAbbreviationMatch(options, preferredTerms = []) {
    const abbrevPreferred = (preferredTerms || [])
        .map(t => normalizeDegreeAbbrev(t))
        .filter(t => WORKDAY_DEGREE_ABBREVIATIONS.includes(t));
    for (const ab of abbrevPreferred) {
        const m = options.find(o => normalizeDegreeAbbrev(optionText(o)) === ab);
        if (m) return m;
    }
    return null;
}

function findBachelorDegreeOptionIndex(options) {
    const texts = options.map(o => optionText(o));
    const normTexts = texts.map(normalizeDegreeAbbrev);
    // Some tenants use abbreviated codes (e.g. Aero: BS, BA, BAS, BBA), with or without periods.
    const abbrevOrder = ['bs', 'ba', 'bas', 'bba', 'bsc', 'bsba', 'be', 'beng', 'btech', 'bach'];
    for (const ab of abbrevOrder) {
        const idx = normTexts.findIndex(t => t === ab);
        if (idx >= 0) return idx;
    }
    let idx = texts.findIndex(t => /^bachelor'?s?\s*degree$/i.test(t));
    if (idx >= 0) return idx;
    idx = texts.findIndex(t => /^bachelor'?s$/i.test(t));
    if (idx >= 0) return idx;
    idx = texts.findIndex(t => /^bachelor of (science|arts)$/i.test(t));
    if (idx >= 0) return idx;
    return texts.findIndex(t =>
        /^bachelor'?s\b/i.test(t) && !/nursing|science|arts|business|engineering|education|administration/i.test(t));
}

function getDegreeSearchTerms(entry) {
    const fromEntry = normalizeDegreeSearchTerms(entry);
    return [...new Set([
        'bachelor',
        'bachelor degree',
        "bachelor's",
        'bachelor of science',
        'bachelor of arts',
        'BS',
        'BA',
        ...fromEntry,
    ].filter(Boolean))].slice(0, 8);
}

function getWorkdayTypeaheadInput(fieldRoot, popup) {
    return fieldRoot?.querySelector('input[role="combobox"]')
        || fieldRoot?.querySelector('input[placeholder*="Type" i]')
        || fieldRoot?.querySelector('input[placeholder*="Search" i]')
        || popup?.querySelector('[data-automation-id="searchBox"] input')
        || popup?.querySelector('input[type="search"], input[placeholder*="Search" i]')
        || fieldRoot?.querySelector('input:not([type="hidden"]):not([type="checkbox"])');
}

async function tryClickWorkdayPlainDropdownOption(fieldRoot, match, displayText, isFilledFn) {
    if (!match) return false;
    workdayScrollToTarget(match, 120);
    const clickTargets = [
        match,
        match.querySelector('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]'),
        match.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]'),
    ].filter(Boolean);
    for (const clickTarget of clickTargets) {
        debugLog(`${WD} degree click`, optionText(clickTarget));
        workdayClickElement(clickTarget);
        await workdayClick(clickTarget);
        await wait(500);
        if (isFilledFn()) return true;
    }
    const dataValue = match.getAttribute('data-value') || extractWorkdayOptionValue(match);
    if (dataValue) {
        for (const inp of (fieldRoot?.querySelectorAll('input[type="hidden"]') || [])) {
            setNativeValue(inp, dataValue);
            inp.dispatchEvent(new Event('change', { bubbles: true }));
        }
        await wait(400);
        if (isFilledFn()) return true;
    }
    const combobox = fieldRoot?.querySelector('input[role="combobox"]');
    if (combobox) {
        await commitWorkdayComboboxSelection(fieldRoot, combobox, match, displayText);
        if (isFilledFn()) return true;
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await wait(400);
    return isFilledFn();
}

async function fillWorkdayDegreePlainDropdown(element, entry = null) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    if (isDegreeFilled(fieldRoot)) return true;

    const openKey = 'degree';
    resetWorkdayDropdownOpenCount(openKey);
    const preferred = getDegreeSearchTerms(entry);
    const isFilled = () => isDegreeFilled(fieldRoot);
    const openTrigger = fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
        || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
        || getWorkdayDropdownTrigger(fieldRoot)
        || element;

    for (let attempt = 0; attempt < 2; attempt++) {
        if (isFilled()) return true;
        if ((wdDropdownOpenCounts[openKey] || 0) >= 3) {
            debugLog(`${WD} degree open limit reached`);
            break;
        }

        await closeWorkdayPopups('degree-retry');
        await wait(200);
        workdayScrollToTarget(fieldRoot, 120);
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(openTrigger);
        await wait(1200);

        const popup = findPopupNearField(fieldRoot, 'degree') || findActiveWorkdayPopup();
        if (!popup) {
            debugLog(`${WD} degree no popup`);
            trackWorkdayDropdownClose(openKey, 'no-popup');
            continue;
        }

        const options = getSingleSelectDropdownOptions(popup, false);
        const degreeOptions = options.filter(o => isDegreeLevelOption(optionText(o)));
        const pool = degreeOptions.length
            ? degreeOptions
            : options.filter(o => !/^select one$/i.test(optionText(o)));
        debugLog(`${WD} degree options plain`, pool.length, pool.slice(0, 10).map(o => optionText(o)));

        let pick = pickBestDegreeOption(
            pool.map(el => ({ el, text: optionText(el) })),
            preferred,
        );
        if (!pick && pool.length) {
            pick = { el: pool[0], text: optionText(pool[0]) };
        }

        if (pick && await tryClickWorkdayPlainDropdownOption(fieldRoot, pick.el, pick.text, isFilled)) {
            debugLog(`${WD} degree filled`, pick.text?.slice(0, 60));
            trackWorkdayDropdownClose(openKey, 'selected');
            await closeWorkdayPopups('degree-done');
            return true;
        }

        if (await pickDegreeBachelor(fieldRoot, popup, openTrigger)) {
            debugLog(`${WD} degree filled via keyboard`);
            trackWorkdayDropdownClose(openKey, 'keyboard');
            return isFilled();
        }

        trackWorkdayDropdownClose(openKey, 'miss');
        await closeWorkdayPopups('degree-miss');
    }

    return isFilled();
}

function isSchoolFieldFilled(container) {
    if (!container) return false;
    const preview = (getWorkdayFieldSelectedText(container) || container.innerText || '').replace(/\s+/g, ' ');
    if (/0 items selected|select one/i.test(preview)) return false;
    if (/error:.*(?:school|university|college)|required and must have a value/i.test(preview)) return false;
    if (/[1-9]\d*\s+items?\s+selected/i.test(preview)) return true;
    if (container.querySelector('[data-automation-id="selectedItem"], [data-automation-id*="selectedItem"]')) return true;
    const selected = getWorkdayFieldSelectedText(container);
    const labelNorm = getContainerLabel(container).replace(/\*/g, '').trim();
    const stripped = String(selected || '')
        .replace(new RegExp(labelNorm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'), '')
        .replace(/\b(minimized|expanded)\b/gi, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (stripped.length > 4 && !/^select one$/i.test(stripped)) return true;
    const ctrl = getContainerControl(container);
    const isTypeahead = !!container.querySelector('[data-automation-id="multiselectInputContainer"]')
        || ctrl?.getAttribute('role') === 'combobox'
        || ctrl?.getAttribute('aria-haspopup') === 'listbox';
    if (isTypeahead) return false;
    return Boolean((ctrl?.value || '').trim());
}

function isWorkdayMultiSelectContainerFilled(container, labelLower = '') {
    const label = labelLower || getContainerLabel(container).toLowerCase();
    if (/school|university|institution/i.test(label) && !/field of study|major|area of study/i.test(label)) {
        return isSchoolFieldFilled(container);
    }
    if (/type to add skills|\bskills\b/i.test(label)) {
        return isSkillsMultiSelectFilled(container, 1);
    }
    if (/how did you hear/i.test(label)) {
        return hasExplicitHearSelection(container);
    }
    if (isWorkdayShiftAvailabilityQuestion(label)) {
        return isWorkdayShiftAvailabilityFilled(container);
    }
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    return /[1-9]\d*\s+items?\s+selected/i.test(preview) && !/0 items selected/i.test(preview);
}

function shouldCountEmptyRequiredContainer(container) {
    if (!isVisibleElement(container)) return false;
    const labelLower = getContainerLabel(container).toLowerCase();
    if (/school|university|institution/i.test(labelLower) && !/field of study|major|area of study/i.test(labelLower)) {
        const section = findEducationSectionEl() || container.closest('[data-automation-id*="Section"]');
        if (section) {
            const schoolFields = [...section.querySelectorAll('[data-automation-id*="formField"]')]
                .filter((c) => /school|university|institution|college/i.test(getContainerLabel(c))
                    && !/field of study|major|area of study/i.test(getContainerLabel(c)));
            const hasFilledSchool = schoolFields.some((c) => isSchoolFieldFilled(c));
            if (hasFilledSchool && !isSchoolFieldFilled(container)) {
                const openInline = findEmptyInlineFormRoot(section);
                if (countWorkdaySectionEntries(section) > 0 && (!openInline || !openInline.contains(container))) {
                    return false;
                }
            }
        }
    }
    return true;
}

function getSchoolSearchTerms(schoolName) {
    const name = String(schoolName || '').trim();
    if (!name) return [];
    const words = name.split(/\s+/);
    const abbrev = name
        .replace(/\bInstitute of Technology\b/gi, 'Tech')
        .replace(/\bCommunity College\b/gi, 'Community College');
    return [...new Set([
        name,
        abbrev !== name ? abbrev : null,
        words.slice(0, 4).join(' '),
        words.slice(0, 3).join(' '),
        words.slice(0, 2).join(' '),
        words[0],
    ].filter(Boolean))].slice(0, 6);
}

function collectValidSchoolOptions(fieldRoot) {
    const rows = findWorkdaySearchResultRows(fieldRoot).filter(r => r.text && !isFieldOfStudyMetaOption(r.text));
    if (rows.length) return rows;
    const popup = findPopupNearField(fieldRoot, 'school') || findActiveWorkdayPopup();
    const options = popup ? getWorkdaySkillMenuOptions(popup, fieldRoot) : [];
    return options
        .filter(o => !isFieldOfStudyMetaOption(optionText(o)))
        .map(el => ({ el, text: optionText(el), row: el }));
}

async function collectSchoolOptionsAfterSearch(fieldRoot, searchTerm) {
    for (let poll = 0; poll < 8; poll++) {
        const valid = collectValidSchoolOptions(fieldRoot);
        if (valid.length) {
            debugLog(`${WD} school options`, searchTerm, valid.length, valid.slice(0, 3).map(r => r.text));
            return valid;
        }
        await wait(350);
    }
    debugLog(`${WD} school no options`, searchTerm);
    return [];
}

async function fillWorkdaySchoolViaSearch(element, schoolName) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const isFilled = () => isSchoolFieldFilled(fieldRoot);
    if (isFilled()) return true;

    const terms = getSchoolSearchTerms(schoolName);
    if (!terms.length) return false;

    const openKey = 'school';
    resetWorkdayDropdownOpenCount(openKey);

    for (const term of terms) {
        if (isFilled()) return true;
        if ((wdDropdownOpenCounts[openKey] || 0) >= terms.length + 2) {
            debugLog(`${WD} school open limit reached`);
            break;
        }

        await closeWorkdayPopups();
        await wait(200);
        workdayScrollToTarget(fieldRoot, 120);

        const input = fieldRoot.querySelector('input[role="combobox"]')
            || fieldRoot.querySelector('input[placeholder*="Type" i]')
            || fieldRoot.querySelector('input:not([type="hidden"]):not([type="checkbox"])');
        const openTarget = fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
            || getWorkdayDropdownTrigger(fieldRoot)
            || input;
        if (!openTarget) {
            debugLog(`${WD} school no open target`);
            continue;
        }

        trackWorkdayDropdownOpen(openKey);
        await workdayClick(openTarget);
        await wait(350);

        const popup = findPopupNearField(fieldRoot, 'school') || findActiveWorkdayPopup();
        const searchInput = getWorkdayTypeaheadInput(fieldRoot, popup) || input;
        if (!searchInput) {
            debugLog(`${WD} school no search input`);
            continue;
        }

        await workdayClick(searchInput);
        searchInput.focus?.();
        await wait(150);

        const searchTerm = term.length > 40 ? term.slice(0, 40) : term;
        debugLog(`${WD} school search type`, searchTerm);
        await workdayTypeSearchInput(searchInput, searchTerm);
        await wait(400);
        if (!await ensureWorkdayInputFocused(searchInput)) {
            await workdayClick(searchInput);
            await wait(200);
        }
        await submitSkillSearchInput(searchInput);
        await wait(700);

        if (isFilled()) {
            debugLog(`${WD} school committed on enter`, searchTerm);
            trackWorkdayDropdownClose(openKey, 'search-enter');
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            return true;
        }

        const validOptions = await collectSchoolOptionsAfterSearch(fieldRoot, searchTerm);
        const searchOption = validOptions.find(r => textMatchesCandidate(r.text, schoolName))
            || validOptions.find(r => textMatchesCandidate(r.text, term))
            || validOptions[0];

        if (searchOption) {
            debugLog(`${WD} school pick result`, searchOption.text?.slice(0, 60));
            if (await selectSkillSearchResultOption(fieldRoot, searchOption, isFilled)) {
                await wait(500);
            }
            if (!isFilled()) {
                const row = searchOption.row || searchOption.el;
                if (row) {
                    await clickWorkdayOption(row);
                    await wait(500);
                }
            }
            if (isFilled()) {
                debugLog(`${WD} school filled via search result`, searchOption.text?.slice(0, 60));
                trackWorkdayDropdownClose(openKey, 'search-result');
                await dismissWorkdayFieldDropdown(fieldRoot, openKey);
                return true;
            }
        }

        await dismissWorkdayFieldDropdown(fieldRoot, openKey);
        trackWorkdayDropdownClose(openKey, 'miss');
    }

    return isFilled();
}

function getWorkdayDegreeCandidates(entry) {
    const terms = entry ? normalizeDegreeSearchTerms(entry) : [];
    const mapped = [];
    for (const t of terms) {
        mapped.push(t);
        if (/bachelor/i.test(t)) mapped.push("Bachelor's", 'Bachelor', "Bachelor's Degree");
        if (/master/i.test(t)) mapped.push("Master's", "Master's Degree");
        if (/associate/i.test(t)) mapped.push('Associate', "Associate's of Nursing");
        if (/high school|ged/i.test(t)) mapped.push('High School Grad or Equiv');
        if (/technical|vocational/i.test(t)) mapped.push('Technical/Vocational School');
        if (/doctor|phd/i.test(t)) mapped.push('Doctorate', 'Doctorate of Nursing');
    }
    for (const t of WORKDAY_DEGREE_CANDIDATES) {
        if (/bachelor/i.test(t)) mapped.push("Bachelor's", 'Bachelor');
    }
    mapped.push('BS', 'BA', 'BAS', 'BBA', "Bachelor's", 'High School Grad or Equiv', 'Associate', "Master's");
    return [...new Set(mapped.filter(Boolean))];
}

function isDegreeFieldLabel(label) {
    const l = String(label || '').replace(/\*/g, '').trim().split(/\n/)[0].trim();
    return /^degree$/i.test(l);
}

function isDegreeFilled(container) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/select one/i.test(preview) && !isWorkdayOpaqueOptionId(getWorkdayComboboxInputValue(container))) {
        return false;
    }
    if (/error:.*degree|required and must have a value/i.test(preview)) return false;
    // Opaque data-value commit (tutorperini.wd12 "BACH") — closed widget may still paint code text.
    if (isWorkdayOpaqueOptionId(getWorkdayComboboxInputValue(container))) return true;
    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const selected = (selectionLabel?.innerText || getWorkdayFieldSelectedText(container) || '')
        .replace(/\s+/g, ' ').trim();
    if (!selected || /^select one$/i.test(selected) || /select one/i.test(selected)) return false;
    const label = getContainerLabel(container).replace(/\*/g, '').trim();
    if (selected.toLowerCase() === label.toLowerCase()) return false;
    if (/^minimized$|^expanded$/i.test(selected)) return false;
    return isDegreeLevelOption(selected)
        || /bachelor|master|associate|doctor|phd|diploma|certificate|ged|high school|undergraduate|postgraduate|^bach\b|^mast\b/i.test(selected);
}

function getFieldOfStudyCandidates(entry, overrideValue) {
    const raw = String(overrideValue || entry?.fieldOfStudy || '').trim();
    const parts = raw.split(/[,;/]/).map(s => s.trim()).filter(Boolean);
    const wordTokens = raw.split(/\s+/).filter(w => w.length > 3);
    const defaults = [
        'Engineering',
        'Computer Science',
        'Information Systems Management',
        'Management Information Systems',
        'Information Systems',
        'Information Technology',
        'Business',
        'Finance',
        'General Business',
        'Management Studies',
        'General Studies',
    ];
    return [...new Set([...parts.slice().reverse(), ...wordTokens, ...defaults])];
}

function isFieldOfStudyMetaOption(text) {
    const t = String(text || '').trim();
    if (!t) return true;
    if (/^select one$/i.test(t)) return true;
    if (/^partial list/i.test(t)) return true;
    if (/^all$/i.test(t)) return true;
    if (/^(show more|load more|no items|no results|nothing found)/i.test(t)) return true;
    if (/press delete to clear|not checked$/i.test(t)) return true;
    return false;
}

function isFieldOfStudyIrrelevantOption(text, context = {}) {
    const t = String(text || '').trim();
    if (!t || isFieldOfStudyMetaOption(t)) return true;
    const school = String(context.schoolName || '').trim();
    if (school && textMatchesCandidate(t, school)) return true;
    if (school) {
        const schoolWords = school.split(/\s+/).filter(w => w.length > 3);
        const matchedWords = schoolWords.filter(w => new RegExp(`\\b${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(t));
        if (matchedWords.length >= 2) return true;
    }
    if (/\b(community college|state university|gulf coast|mississippi)\b/i.test(t)
        && /\b(college|university|institute)\b/i.test(t)) {
        return true;
    }
    return false;
}

function findFieldOfStudyResultsPopup(fieldRoot) {
    const input = fieldRoot?.querySelector('input[role="combobox"]');
    for (const attr of ['aria-controls', 'aria-owns']) {
        const id = input?.getAttribute(attr);
        if (!id) continue;
        const controlled = document.getElementById(id);
        if (controlled && isVisibleElement(controlled) && !isChipDisplayPopup(controlled)) {
            return controlled;
        }
    }
    const popups = [...document.querySelectorAll(
        '[data-automation-id="activeListContainer"], [data-automation-id="wd-MenuList"], ' +
        '[data-automation-id="promptOptions"], ul[role="listbox"], div[role="listbox"]',
    )].filter(isVisibleElement).filter(p => !isChipDisplayPopup(p));
    if (!fieldRoot || !popups.length) {
        return findPopupNearField(fieldRoot, 'field of study');
    }
    const rect = fieldRoot.getBoundingClientRect();
    let best = null;
    let bestDist = Infinity;
    for (const popup of popups) {
        if (isWrongPopupForField(popup, 'field of study')) continue;
        const pr = popup.getBoundingClientRect();
        const dist = Math.abs(pr.top - rect.bottom) + Math.abs(pr.left - rect.left) * 0.25;
        if (dist < bestDist) {
            bestDist = dist;
            best = popup;
        }
    }
    return best || findPopupNearField(fieldRoot, 'field of study');
}

function findFieldOfStudySearchResultRows(fieldRoot) {
    const pop = findFieldOfStudyResultsPopup(fieldRoot);
    if (!pop) return [];
    const rowSelectors = '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"], li';
    const rows = [];
    for (const row of pop.querySelectorAll(rowSelectors)) {
        if (!isVisibleElement(row)) continue;
        const text = normalizeWorkdayMenuOptionText(
            (row.getAttribute('aria-label') || row.innerText || row.textContent || '').trim(),
        );
        if (!text || /^search results/i.test(text)) continue;
        if (/^select one$/i.test(text)) continue;
        if (/^no items\.?$/i.test(text)) continue;
        const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]');
        const radio = row.querySelector('input[type="radio"], [role="radio"]');
        rows.push({
            el: checkbox || radio || row,
            label: (checkbox?.id && document.querySelector(`label[for="${CSS.escape(checkbox.id)}"]`))
                || (radio?.id && document.querySelector(`label[for="${CSS.escape(radio.id)}"]`))
                || row.querySelector('label')
                || row,
            row,
            text,
            kind: checkbox ? 'checkbox' : (radio ? 'radio' : 'row'),
        });
    }
    return rows;
}

function collectValidFieldOfStudyOptions(fieldRoot, context = {}) {
    const rows = findFieldOfStudySearchResultRows(fieldRoot);
    const fromRows = rows.filter(r => r.text && !isFieldOfStudyIrrelevantOption(r.text, context));
    if (fromRows.length) return fromRows;
    const popup = findFieldOfStudyResultsPopup(fieldRoot);
    const options = popup ? getWorkdaySkillMenuOptions(popup, fieldRoot) : [];
    return options
        .filter(o => !isFieldOfStudyIrrelevantOption(optionText(o), context))
        .map(el => ({ el, text: optionText(el), row: el }));
}

async function expandFieldOfStudyCatalogIfNeeded(fieldRoot, searchTerm) {
    const popup = findFieldOfStudyResultsPopup(fieldRoot);
    if (!popup) return;
    let options = getScopedDropdownOptions(popup);
    const labels = options.map(o => optionText(o).trim()).filter(Boolean);
    const onlyMeta = labels.length > 0 && labels.every(t =>
        /^partial list|^all$|^select one$/i.test(t));
    if (!onlyMeta) return;

    debugLog(`${WD} field of study expand catalog`, searchTerm, labels.slice(0, 3));
    const allOpt = options.find(o => /^all$/i.test(optionText(o).trim()));
    if (allOpt) {
        await clickWorkdayOption(allOpt);
        await wait(2200);
    }
    const popup2 = findFieldOfStudyResultsPopup(fieldRoot) || popup;
    const searchInput = popup2?.querySelector('[data-automation-id="searchBox"] input')
        || popup2?.querySelector('input[type="search"], input[placeholder*="Search" i]')
        || fieldRoot.querySelector('input[role="combobox"]');
    if (searchInput && searchTerm) {
        await workdayClick(searchInput);
        await workdayTypeSearchInput(searchInput, searchTerm);
        await wait(1200);
    }
}

async function collectFieldOfStudyOptionsAfterSearch(fieldRoot, searchTerm, context = {}) {
    await expandFieldOfStudyCatalogIfNeeded(fieldRoot, searchTerm);
    let lastRaw = [];
    for (let poll = 0; poll < 10; poll++) {
        lastRaw = findFieldOfStudySearchResultRows(fieldRoot);
        const valid = collectValidFieldOfStudyOptions(fieldRoot, context);
        if (valid.length) {
            debugLog(`${WD} field of study options`, searchTerm, valid.length,
                'raw=', lastRaw.length, valid.slice(0, 5).map(r => r.text));
            debugLog(`${WD} field of study options full`, searchTerm,
                valid.slice(0, 15).map(r => r.text).join(' | '));
            return valid;
        }
        if (poll === 2) await expandFieldOfStudyCatalogIfNeeded(fieldRoot, searchTerm);
        await wait(350);
    }
    if (lastRaw.length) {
        debugLog(`${WD} field of study options filtered out`, searchTerm,
            lastRaw.slice(0, 8).map(r => r.text));
    } else {
        const popup = findFieldOfStudyResultsPopup(fieldRoot);
        const rawOpts = popup ? getScopedDropdownOptions(popup).slice(0, 8).map(o => optionText(o)) : [];
        if (rawOpts.length) {
            debugLog(`${WD} field of study raw popup options`, searchTerm, rawOpts);
        }
    }
    debugLog(`${WD} field of study no options`, searchTerm);
    return [];
}

function getFieldOfStudySearchTerms(entry, overrideValue) {
    const profileRaw = String(overrideValue || entry?.fieldOfStudy || '').trim();
    const defaults = [
        'Computer Science',
        'Engineering',
        'Information Technology',
        'Information Systems',
        'Business',
    ];
    const profileVariants = [];
    if (profileRaw) {
        profileVariants.push(profileRaw);
        if (profileRaw.length > 24) profileVariants.push(profileRaw.slice(0, 24));
        const words = profileRaw.split(/\s+/);
        if (words.length > 2) profileVariants.push(words.slice(0, 2).join(' '));
        if (words[0]?.length > 3) profileVariants.push(words[0]);
    }
    return [...new Set([...defaults, ...profileVariants])].slice(0, 5);
}

const FIELD_OF_STUDY_NICHE_PENALTY = /aerospace|aero\b|chemical|petroleum|nuclear|biomedical|advanced\s+chemical|marine|ocean|mining|metallurg/i;

function scoreFieldOfStudyOption(optionTextRaw, searchTerm, candidates = []) {
    const t = String(optionTextRaw || '').toLowerCase().trim();
    const term = String(searchTerm || '').toLowerCase().trim();
    if (!t || isFieldOfStudyMetaOption(t)) return -100;
    let score = 0;
    if (t === term) score += 150;
    else if (textMatchesCandidate(t, term)) score += 90;
    for (const c of candidates) {
        if (textMatchesCandidate(t, c)) score += 45;
        if (String(c).toLowerCase().trim() === t) score += 30;
    }
    if (term && t.includes(term)) {
        if (t !== term) {
            score += 20;
            const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const extra = t.replace(new RegExp(escaped, 'i'), '').trim().replace(/^[-–—]\s*/, '');
            if (extra) score -= Math.min(extra.split(/\s+/).length * 18, 70);
        }
    }
    if (FIELD_OF_STUDY_NICHE_PENALTY.test(t) && !FIELD_OF_STUDY_NICHE_PENALTY.test(term)) score -= 55;
    if (/^other$/i.test(t)) score -= 25;
    if (/^general studies$/i.test(t)) score += 5;
    score -= Math.min(t.length / 12, 12);
    return score;
}

function pickBestFieldOfStudyOption(validOptions, searchTerm, candidates = []) {
    if (!validOptions?.length) return null;
    const ranked = validOptions.map(o => ({
        ...o,
        score: scoreFieldOfStudyOption(o.text, searchTerm, candidates),
    })).sort((a, b) => b.score - a.score);
    debugLog(`${WD} field of study ranked`, searchTerm,
        ranked.slice(0, 8).map(x => `${x.text}:${x.score.toFixed(1)}`).join(' | '));
    const best = ranked[0];
    if (!best) return null;
    if (best.score >= 15) return best;
    const viable = ranked.filter(o => o.score > 0 && !/^other$/i.test(o.text));
    if (viable.length >= 2 || (viable.length && validOptions.length >= 3)) {
        debugLog(`${WD} field of study pick relaxed`, viable[0].text, viable[0].score.toFixed(1));
        return viable[0];
    }
    return null;
}

function pickBestDegreeOption(items, preferredTerms = []) {
    const list = (Array.isArray(items) ? items : []).map(o =>
        (o?.el ? o : { el: o, text: optionText(o) }));
    if (!list.length) return null;
    const patterns = [
        /^bachelor'?s?\s*degree$/i,
        /^bachelor of science$/i,
        /^bachelor of arts$/i,
        /^bachelor in business administration$/i,
        /^bachelor'?s$/i,
        /^bachelor/i,
        /^associate/i,
        /^other$/i,
    ];
    for (const re of patterns) {
        const m = list.find(o => re.test(o.text));
        if (m) return m;
    }
    // Dotted/undotted abbreviation codes ("B.S." / "BS") never match the word-based patterns
    // above or textMatchesCandidate's word-boundary check below — resolve them explicitly.
    const abbrevMatch = findDegreeAbbreviationMatch(list.map(o => o.el), preferredTerms);
    if (abbrevMatch) {
        const m = list.find(o => o.el === abbrevMatch);
        if (m) return m;
    }
    for (const term of preferredTerms) {
        const m = list.find(o => textMatchesCandidate(o.text, term));
        if (m) return m;
    }
    return list.find(o => isDegreeLevelOption(o.text)) || list[0];
}

async function commitWorkdayListPick(fieldRoot, pick, isFilledFn, logTag = 'dropdown') {
    if (!pick?.el) return false;
    debugLog(`${WD} ${logTag} commit pick`, pick.text?.slice(0, 60));
    if (await clickWorkdayMenuItem(pick.el, fieldRoot, isFilledFn)) return true;
    if (await clickWorkdayOption(pick.el)) {
        await wait(500);
        if (isFilledFn()) return true;
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await wait(400);
    return isFilledFn();
}

async function fillWorkdayFieldOfStudyViaSearch(element, entry, overrideValue) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const isFilled = () => isFieldOfStudyFilled(fieldRoot, entry, overrideValue);
    if (isFilled()) return true;

    const input = fieldRoot.querySelector('input[role="combobox"]')
        || fieldRoot.querySelector('input[placeholder*="Type" i]')
        || fieldRoot.querySelector('input:not([type="hidden"]):not([type="checkbox"])');
    if (!input) {
        debugLog(`${WD} field of study no search input`);
        return false;
    }

    const candidates = getFieldOfStudyCandidates(entry, overrideValue);
    const terms = getFieldOfStudySearchTerms(entry, overrideValue);
    const optionContext = { schoolName: entry?.school || '' };
    const openKey = 'field of study';
    resetWorkdayDropdownOpenCount(openKey);

    async function tryFieldOfStudySearch(term) {
        if (isFilled()) return true;
        if ((wdDropdownOpenCounts[openKey] || 0) >= 4) {
            debugLog(`${WD} field of study open limit reached`);
            return false;
        }

        await closeWorkdayPopups('field-of-study');
        await wait(250);
        workdayScrollToTarget(fieldRoot, 120);

        const openTarget = fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
            || getWorkdayDropdownTrigger(fieldRoot)
            || input;
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(openTarget);
        await wait(350);
        await workdayClick(input);
        input.focus?.();
        await wait(200);

        const searchTerm = term.length > 30 ? term.slice(0, 30) : term;
        debugLog(`${WD} field of study search type`, searchTerm);
        await workdayTypeSearchInput(input, searchTerm);
        await wait(500);
        if (!await ensureWorkdayInputFocused(input)) {
            await workdayClick(input);
            await wait(200);
            await ensureWorkdayInputFocused(input);
        }
        await submitSkillSearchInput(input);
        debugLog(`${WD} field of study after enter`, searchTerm, 'input=', (input.value || '').slice(0, 40));
        await wait(1000);

        if (isFilled()) {
            debugLog(`${WD} field of study committed on enter`, searchTerm);
            markFieldOfStudyCommitted(fieldRoot);
            trackWorkdayDropdownClose(openKey, 'search-enter');
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            return true;
        }

        const validOptions = await collectFieldOfStudyOptionsAfterSearch(fieldRoot, searchTerm, optionContext);
        if (!validOptions.length) {
            trackWorkdayDropdownClose(openKey, 'no-options');
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            return false;
        }

        const searchOption = pickBestFieldOfStudyOption(validOptions, searchTerm, candidates);
        if (!searchOption) {
            debugLog(`${WD} field of study no good match`, searchTerm);
            trackWorkdayDropdownClose(openKey, 'low-score');
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            return false;
        }

        debugLog(`${WD} field of study pick result`, searchOption.text?.slice(0, 60));
        if (await selectSkillSearchResultOption(fieldRoot, searchOption, isFilled)) {
            await wait(500);
        }
        if (!isFilled()) {
            const row = searchOption.row || searchOption.el;
            if (row) {
                await clickWorkdayOption(row);
                await wait(500);
            }
        }
        if (isFilled()) {
            debugLog(`${WD} field of study filled via search result`, searchOption.text?.slice(0, 60));
            markFieldOfStudyCommitted(fieldRoot);
            trackWorkdayDropdownClose(openKey, 'search-result');
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            return true;
        }

        trackWorkdayDropdownClose(openKey, 'miss');
        await dismissWorkdayFieldDropdown(fieldRoot, openKey);
        return false;
    }

    for (const term of terms) {
        if (await tryFieldOfStudySearch(term)) return true;
    }

    if (!isFilled()) {
        debugLog(`${WD} field of study fallback Other`);
        if (await tryFieldOfStudySearch('Other')) return true;
    }

    return isFilled();
}

function isWorkdayGpaQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /\bgpa\b|grade point average|overall result\s*\(gpa\)|overall gpa/i.test(l);
}

function getWorkdayGpaCandidates() {
    return [
        'Equal or greater than 2', 'Equal or Greater than 2', 'Greater than or equal to 2',
        'At least 2', '2 or above', '2.0 or above', '≥ 2', '>= 2',
        'Less than 2', 'Less than or equal to 1', 'Below 2',
        '3.5 and above', '3.50 and above', '3.5 & above', 'Above 3.5', 'Over 3.5', '3.5+',
        '3.5 - 4.0', '3.50 - 4.00', '3.5-4.0', '3.50-4.00', '3.5 to 4.0',
        '4.0', '4.00', '3.9', '3.8', '3.7', '3.6', '3.5', '3.50',
        '3.00 - 3.49', '3.0 - 3.49', '3.0-3.5', '3.00-3.50',
        'First Class', 'Second Class Upper', 'Second Upper', 'A', 'A-',
        'Not applicable', 'N/A', 'Prefer not to say', 'Prefer not to answer',
    ];
}

function isWorkdayGpaFilled(container) {
    if (!container) return false;
    if (isWorkdaySingleSelectFilled(container, getWorkdayGpaCandidates())) return true;
    const selected = (getWorkdayFieldSelectedText(container) || '').replace(/\s+/g, ' ').trim();
    if (!selected || /^select one$/i.test(selected) || /0 items selected/i.test(selected)) return false;
    if (/error:.*required/i.test(selected) && /select one/i.test(selected)) return false;
    if (/equal or greater|greater than or equal|less than|at least|above|below|\d(?:\.\d+)?/i.test(selected)) {
        return true;
    }
    return false;
}

async function fillWorkdayGpaField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    if (isWorkdayGpaFilled(container)) return true;
    const cands = getWorkdayGpaCandidates();
    const fieldRoot = container?.closest?.('[data-automation-id*="formField"]') || container;
    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (ctrl && (ctrl.tagName === 'INPUT' || ctrl.tagName === 'TEXTAREA')
        && ctrl.type !== 'hidden' && ctrl.type !== 'radio' && ctrl.type !== 'checkbox'
        && !ctrl.getAttribute?.('aria-haspopup') && ctrl.getAttribute?.('role') !== 'combobox') {
        if ((ctrl.value || '').trim()) return true;
        await workdayTypeElement(ctrl, '3.5');
        debugLog(`${WD} gpa text fill`, String(labelText || '').slice(0, 60), '3.5');
        return Boolean((ctrl.value || '').trim());
    }
    if (!ctrl) return false;
    clearWorkdaySingleSelectMissKey(labelText);
    const openKey = normalizeDropdownOpenKey(String(labelText || ''));
    resetWorkdayDropdownOpenCount(openKey);
    wdStreamedLabelsDelete(labelText);

    // Live options first — canned "3.5 and above" misses P&G bands and escape-all reopen undoes fills.
    await closeWorkdayPopups();
    trackWorkdayDropdownOpen(openKey);
    await workdayClick(getWorkdayDropdownTrigger(fieldRoot) || ctrl);
    await wait(900);
    const popup = findPopupNearField(fieldRoot, labelText)
        || document.querySelector('[data-automation-id="promptOption"]')?.closest('[role="listbox"], ul, div');
    const options = popup ? getSingleSelectDropdownOptions(popup, false) : [];
    const texts = options.map(o => optionText(o)).filter(t => t && !/^select one$/i.test(t));
    debugLog(`${WD} gpa live options`, texts.slice(0, 12));
    const score = (t) => {
        const s = String(t || '');
        if (/equal or greater than\s*2|greater than or equal to\s*2|at least\s*2|2\s*or\s*above|≥\s*2|>=\s*2/i.test(s)) return 120;
        if (/3\.5\s*(and|&)?\s*above|above\s*3\.5|3\.5\+|≥\s*3\.5|3\.5\s*[-–]\s*4/i.test(s)) return 100;
        if (/\b4\.0+\b/.test(s)) return 90;
        if (/\b3\.[5-9]\b/.test(s)) return 80;
        if (/first class|second class upper/i.test(s)) return 70;
        if (/less than\s*2|below\s*2|less than or equal to\s*1/i.test(s)) return 20;
        if (/\d/.test(s)) return 30;
        return 0;
    };
    let best = null;
    let bestScore = -1;
    for (const o of options) {
        const t = optionText(o);
        const sc = score(t);
        if (sc > bestScore) {
            best = o;
            bestScore = sc;
        }
    }
    if (best && bestScore > 0) {
        const matchText = optionText(best);
        workdayClickElement(best);
        await wait(600);
        await commitWorkdayComboboxSelection(fieldRoot, fieldRoot.querySelector('input[role="combobox"]') || ctrl, best, matchText);
        await closeWorkdayPopups('gpa');
        await wait(300);
        const ok = isWorkdayGpaFilled(container);
        debugLog(`${WD} gpa live pick`, matchText.slice(0, 40), 'ok=', ok);
        if (ok) {
            markWorkdayLockedYesNoFilled(labelText);
            return true;
        }
    } else {
        await closeWorkdayPopups('gpa');
    }

    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(openKey);
    const ok = await fillWorkdaySingleSelectDropdown(ctrl, cands, String(labelText || '').slice(0, 80));
    const filled = ok || isWorkdayGpaFilled(container);
    debugLog(`${WD} gpa dropdown fill`, String(labelText || '').slice(0, 60), 'ok=', filled);
    if (filled) markWorkdayLockedYesNoFilled(labelText);
    return filled;
}

function isWorkdayFieldOfStudyLabel(label) {
    const l = String(label || '').toLowerCase();
    if (/majority-owned|majority owned/i.test(l)) return false;
    // GPA questions mention "major/area of Study" but are numeric / GPA-band fields
    if (isWorkdayGpaQuestion(l)) return false;
    // Multi-select "major area of study… Mark all that apply" is a checkbox group, not FOS typeahead
    if (/mark all that apply|select all that apply/i.test(l) && /major|area of study|subject/i.test(l)) {
        return false;
    }
    // bcbsaz.wd1 (and similar): "Do you have a high school degree or GED in general field of study?"
    // is a credential Yes/GED/No select — not an education Field of Study typeahead. Matching the
    // bare "field of study" substring left countEmptyRequired stuck forever after a successful fill
    // ("Yes, I have a high school degree.") because isFieldOfStudyFilled expects a school major chip.
    if (/high school(?:\s+degree)?|\bged\b/i.test(l)
        && /^(do you|have you|did you)\b/i.test(l.trim().replace(/^\*+\s*/, ''))) {
        return false;
    }
    return /field of study|area of study/i.test(l) || /^major$/i.test(l.replace(/\*/g, '').trim());
}

function isWorkdayMajorMultiSelectQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /major area of study|what was your major|majors? (?:in school|did you)/i.test(l)
        && /mark all that apply|select all that apply/i.test(l);
}

function getWorkdayMajorMultiSelectCandidates() {
    return [
        'Engineering', 'Business', 'Science', 'Computer Science', 'Information Technology',
        'Health Care', 'Liberal Arts', 'Mathematics', 'Other',
    ];
}

async function fillWorkdayMajorMultiSelectField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const cands = getWorkdayMajorMultiSelectCandidates();
    if (isWorkdayMultiOptionAvailabilityFilled(container, cands)
        || isDisclosureChoiceFilled(container, cands)
        || isMultiSelectFilled(container)) {
        return true;
    }
    let filled = await fillWorkdayDisclosureChoiceGroup(container, cands)
        || await fillWorkdayExclusiveCheckboxGroup(container, cands, { label: labelText });
    if (!filled) {
        // Click any matching visible checkboxes (Engineering preferred for P&G engineering Q)
        const prefer = ['Engineering', 'Business', 'Science', 'Other'];
        let selected = 0;
        for (const want of prefer) {
            for (const input of container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
                const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
                const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
                if (!new RegExp(`^${want}$`, 'i').test(text) && !textMatchesCandidate(text, want)) continue;
                if (!isWorkdayCheckboxChecked(input)) {
                    await workdayClickCheckbox(input, 'major-multi');
                    await wait(200);
                }
                if (isWorkdayCheckboxChecked(input) || input.checked) selected += 1;
            }
            if (selected > 0) break;
        }
        filled = selected > 0;
    }
    if (!filled) {
        const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
        if (control) {
            filled = await fillWorkdayScrollMultiSelect(control, cands, {
                logTag: 'major-multi',
                fieldLabel: labelText,
                isFilledFn: (r) => isMultiSelectFilled(r || container)
                    || isWorkdayMultiOptionAvailabilityFilled(r || container, cands),
            });
        }
    }
    debugLog(`${WD} major multi-select fill`, String(labelText || '').slice(0, 60), 'ok=', filled);
    return filled || isWorkdayMultiOptionAvailabilityFilled(container, cands) || isMultiSelectFilled(container);
}

function isFieldOfStudyFilled(container, entry = null, overrideValue = null) {
    if (!container) return false;
    const ctrl = getContainerControl(container);
    const inputVal = (ctrl?.value || '').replace(/\s+/g, ' ').trim();
    const preview = (getWorkdayFieldSelectedText(container) || container.innerText || '').replace(/\s+/g, ' ');
    const isMultiSelectPrompt = Boolean(
        container.querySelector('[data-automation-id="multiselectInputContainer"], [data-automation-id="multiSelectContainer"]')
        || ctrl?.getAttribute?.('aria-haspopup')
        || ctrl?.getAttribute?.('role') === 'combobox'
    );
    // Multi-select still empty even if search input holds a typed query / "Expanded"
    if (isMultiSelectPrompt) {
        if (/0 items selected/i.test(preview) || (!/[1-9]\d*\s+items?\s+selected/i.test(preview)
            && !container.querySelector('[data-automation-id="promptOption"], [data-automation-id="selectedItem"], [data-automation-id="pill"]'))) {
            // Require an actual selected chip/item — not just typed search text
            const selected = getWorkdayFieldSelectedText(container) || '';
            const candidates = getFieldOfStudyCandidates(entry, overrideValue);
            if (!candidates.some(c => textMatchesCandidate(selected, c))
                || /select one|expanded|type to search|search/i.test(selected)) {
                return false;
            }
        }
    } else if (/0 items selected/i.test(preview) && !/[1-9]\d*\s+items?\s+selected/i.test(preview)) {
        return false;
    }
    // Plain text majors (Sysco Application Questions) — trust a non-empty typed value
    if (inputVal && inputVal.length >= 2 && !/^select one$/i.test(inputVal)
        && ctrl?.tagName === 'INPUT' && ctrl.type !== 'hidden'
        && !isMultiSelectPrompt) {
        return true;
    }
    if (ctrl?.tagName === 'TEXTAREA' && inputVal.length >= 2) return true;
    if (/select one/i.test(preview) && !inputVal) return false;
    if (/error:.*field of study/i.test(preview) && !inputVal) return false;
    const candidates = getFieldOfStudyCandidates(entry, overrideValue);
    if (!isMultiSelectPrompt && inputVal && candidates.some(c => textMatchesCandidate(inputVal, c))) return true;
    if (candidates.some(c => textMatchesCandidate(preview, c))) return true;
    if (/[1-9]\d*\s+items?\s+selected/i.test(preview)) {
        const selected = getWorkdayFieldSelectedText(container) || preview;
        if (selected && !/select one|0 items|expanded/i.test(selected)) return true;
    }
    return false;
}

const wdFieldOfStudyCommitted = new WeakSet();

function getFieldOfStudyContainer(scope) {
    if (!scope) return null;
    if (scope.matches?.('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(scope).toLowerCase();
        if (/field of study|major|area of study/.test(lbl)) return scope;
    }
    return [...(scope.querySelectorAll?.('[data-automation-id*="formField"]') || [])]
        .find(c => /field of study|major|area of study/i.test(getContainerLabel(c))) || null;
}

function isFieldOfStudyCommitted(scope) {
    const field = getFieldOfStudyContainer(scope);
    if (!field) return false;
    return wdFieldOfStudyCommitted.has(field) || field.dataset?.wdStudyCommitted === '1';
}

function markFieldOfStudyCommitted(scope) {
    const field = getFieldOfStudyContainer(scope);
    if (field && isFieldOfStudyFilled(field)) {
        wdFieldOfStudyCommitted.add(field);
        field.dataset.wdStudyCommitted = '1';
        debugLog(`${WD} field of study marked committed`, (getWorkdayFieldSelectedText(field) || '').slice(0, 50));
    }
}

function shouldSkipFieldOfStudyRefill(container, entry) {
    if (isFieldOfStudyFilled(container, entry)) return true;
    // Stale "committed" after false-positive enter — allow another fill attempt
    if (isFieldOfStudyCommitted(container)) {
        const field = getFieldOfStudyContainer(container);
        if (field) {
            wdFieldOfStudyCommitted.delete(field);
            delete field.dataset.wdStudyCommitted;
            debugLog(`${WD} field of study clear stale commit`);
        }
    }
    return false;
}

/** Open inline experience form (empty or resume-prefilled) when section has no Delete buttons yet. */
function findOpenInlineExperienceRoot(section) {
    if (!section) return null;
    let best = null;
    let bestCount = 0;
    for (const ff of section.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(ff).toLowerCase();
        if (!/job title|^title/.test(lbl) && !/company|employer/.test(lbl)) continue;
        let node = ff.parentElement;
        for (let d = 0; d < 10 && node && node !== section; d++) {
            const fields = node.querySelectorAll('[data-automation-id*="formField"]');
            const count = fields.length;
            if (count >= 3 && count >= bestCount) {
                best = node;
                bestCount = count;
            }
            node = node.parentElement;
        }
    }
    if (best) return best;
    const hasTitle = [...section.querySelectorAll('[data-automation-id*="formField"]')].some(c =>
        /job title|^title/.test(getContainerLabel(c).toLowerCase()));
    return hasTitle ? section : null;
}

function experienceRootMatchesEntry(root, entry) {
    if (!root || !entry?.title) return false;
    let titleVal = '';
    let companyVal = '';
    for (const c of root.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(c).toLowerCase();
        const ctrl = getContainerControl(c);
        if (/job title|^title/.test(lbl)) titleVal = (ctrl?.value || '').trim();
        if (/company|employer/.test(lbl)) companyVal = (ctrl?.value || '').trim();
    }
    if (!titleVal || !textMatchesCandidate(titleVal, entry.title)) return false;
    const expectedCompany = (entry.companyName || entry.company || '').trim();
    if (expectedCompany && companyVal && !textMatchesCandidate(companyVal, expectedCompany)) return false;
    return isExperienceEntryReady(findWorkExperienceSection(), entry, root);
}

function isExperienceEntryReady(section, entry, root) {
    const scope = root || findOpenInlineExperienceRoot(section) || section;
    if (!scope || !entry?.title) return false;
    for (const c of scope.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(c).toLowerCase();
        const preview = (c.innerText || '').toLowerCase();
        if (/error:.*required/i.test(preview)) return false;
        if (/job title|^title/.test(lbl) && isContainerRequired(c)) {
            if (!(getContainerControl(c)?.value || '').trim()) return false;
        }
        if (/company|employer/.test(lbl) && isContainerRequired(c)) {
            if (!(getContainerControl(c)?.value || '').trim()) return false;
        }
        if (/\bfrom\b/.test(lbl) && !/from.*to/.test(lbl) && isContainerRequired(c) && isWorkdayDateFieldIncomplete(c)) {
            return false;
        }
        if (/\bto\b/.test(lbl) && isContainerRequired(c) && !isExperienceCurrent(entry) && isWorkdayDateFieldIncomplete(c)) {
            return false;
        }
    }
    return true;
}

/** Open inline education form (empty or resume-prefilled) when section has no Delete buttons yet. */
function findOpenInlineEducationRoot(section) {
    if (!section) return null;
    const empty = findEmptyInlineFormRoot(section);
    if (empty) return empty;
    for (const ff of section.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(ff).toLowerCase();
        if (!/school|university|institution|college|^degree$|field of study|major/.test(lbl)) continue;
        let node = ff.parentElement;
        for (let d = 0; d < 8 && node && node !== section; d++) {
            const fields = node.querySelectorAll('[data-automation-id*="formField"]');
            if (fields.length >= 3) return node;
            node = node.parentElement;
        }
    }
    return null;
}

function isEducationEntryReady(section, entry, root) {
    const scope = root || getFirstEntryRoot(section) || findEmptyInlineFormRoot(section);
    if (!scope || !entry) return false;

    let schoolOk = false;
    let hasRequiredDegree = false;
    let degreeOk = true;
    let hasRequiredStudy = false;
    let studyOk = true;

    for (const c of scope.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(c).replace(/\*/g, '').trim().toLowerCase();
        if (/school|university|institution|college/.test(lbl)) {
            if (isContainerRequired(c) && !isSchoolFieldFilled(c)) return false;
            schoolOk = isSchoolFieldFilled(c);
            continue;
        }
        if (/^degree$/.test(lbl)) {
            if (isContainerRequired(c) || entry.degree) {
                hasRequiredDegree = true;
                degreeOk = isDegreeFilled(c);
            }
            continue;
        }
        if (/field of study|major|area of study/.test(lbl)) {
            if (isContainerRequired(c) || entry.fieldOfStudy) {
                hasRequiredStudy = true;
                studyOk = shouldSkipFieldOfStudyRefill(c, entry);
            }
        }
    }

    if (!schoolOk) return false;
    if (hasRequiredDegree && !degreeOk) return false;
    if (hasRequiredStudy && !studyOk) return false;
    return true;
}

async function clearWorkdayMultiSelectIfWrong(container, entry, overrideValue, logTag = 'multiselect') {
    if (!container || isFieldOfStudyFilled(container, entry, overrideValue)) return;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (!/[1-9]\d*\s+items?\s+selected/i.test(preview)) return;

    for (const btn of container.querySelectorAll(
        'button[aria-label*="Remove" i], button[aria-label*="Delete" i], [data-automation-id*="DELETE"]'
    )) {
        debugLog(`${WD} ${logTag} clearing wrong selection`);
        await workdayClick(btn);
        await wait(400);
    }
    if (isFieldOfStudyFilled(container, entry, overrideValue)) return;

    const trigger = getWorkdayDropdownTrigger(container);
    if (!trigger) return;
    trackWorkdayDropdownOpen(`${logTag} clear`);
    await workdayClick(trigger);
    await wait(1200);
    const popup = findPopupNearField(container) || findActiveWorkdayPopup();
    for (const opt of getScopedDropdownOptions(popup)) {
        const checked = opt.querySelector('input[type="checkbox"]:checked, [aria-checked="true"]')
            || (opt.getAttribute('aria-selected') === 'true' ? opt : null);
        if (checked || opt.querySelector('input[type="checkbox"]:checked')) {
            await clickWorkdayMenuItem(opt, container, () => true);
            await wait(350);
        }
    }
    await dismissWorkdayFieldDropdown(container);
}

async function fillWorkdayFieldOfStudyDropdown(element, entry, overrideValue) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    if (shouldSkipFieldOfStudyRefill(fieldRoot, entry)) return true;
    // Skip if not required — avoid infinite loops on optional fields
    if (!isContainerRequired(fieldRoot)) {
        debugLog(`${WD} field of study optional, skipping`);
        return true;
    }
    // Guard: if already tried too many times without success, skip to avoid infinite loop
    // Use a window flag so it persists across soft retries within the same page load
    window.__wdFieldOfStudyAttempts = (window.__wdFieldOfStudyAttempts || 0) + 1;
    if (window.__wdFieldOfStudyAttempts > 6) {
        debugLog(`${WD} field of study too many attempts (${window.__wdFieldOfStudyAttempts}), skipping`);
        return false;
    }
    await clearWorkdayMultiSelectIfWrong(fieldRoot, entry, overrideValue, 'field of study');

    const ok = await fillWorkdayFieldOfStudyViaSearch(element, entry, overrideValue);
    if (ok) markFieldOfStudyCommitted(fieldRoot);
    return ok;
}

async function fillWorkdayDegreeDropdown(element, entry = null) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    if (isDegreeFilled(fieldRoot)) {
        debugLog(`${WD} degree already filled`, (getWorkdayFieldSelectedText(fieldRoot) || '').slice(0, 40));
        return true;
    }
    if (!isContainerRequired(fieldRoot) && !String(entry?.degree || '').trim()) {
        debugLog(`${WD} degree optional skip`);
        return true;
    }

    debugLog(`${WD} filling degree dropdown`, getContainerLabel(fieldRoot));
    const candidates = getDegreeSearchTerms(entry);
    const trigger = fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
        || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
        || getWorkdayDropdownTrigger(fieldRoot)
        || getContainerControl(fieldRoot)
        || element;
    resetWorkdayDropdownOpenCount('degree');
    const ok = await fillWorkdaySingleSelectDropdown(trigger, candidates, 'degree')
        || await fillWorkdayDegreePlainDropdown(trigger, entry);
    debugLog(`${WD} degree result`, ok || isDegreeFilled(fieldRoot),
        (getWorkdayFieldSelectedText(fieldRoot) || '').slice(0, 40));
    return ok || isDegreeFilled(fieldRoot);
}

async function commitWorkdayNumericInput(input, value, label = '') {
    if (!input || value == null || value === '') return false;
    const rawDigits = String(value).replace(/\D/g, '') || String(value);
    const n = Number(rawDigits);
    const formats = [
        String(value),
        rawDigits,
        Number.isFinite(n) ? n.toLocaleString('en-US') : null,
        Number.isFinite(n) ? `$${n.toLocaleString('en-US')}` : null,
        Number.isFinite(n) ? `$${rawDigits}` : null,
        Number.isFinite(n) ? `${rawDigits} USD` : null,
    ].filter((v, i, arr) => v && arr.indexOf(v) === i);

    workdayScrollToTarget(input, 120);
    const container = input.closest('[data-automation-id*="formField"]')
        || input.closest('[data-automation-id*="FormField"]')
        || input.parentElement;
    const editable = container?.querySelector?.('[contenteditable="true"]');

    for (const str of formats) {
        await workdayTypeElement(input, str);
        if (editable && editable !== input) {
            await workdayTypeElement(editable, str);
        }
        await wait(400);
        // Force React re-validation: focus sibling / blur / re-focus
        input.focus?.();
        input.dispatchEvent(new Event('blur', { bubbles: true, composed: true }));
        await wait(200);
        const preview = (container?.innerText || '').toLowerCase();
        const hasDigits = ((input.value || editable?.innerText || '').replace(/\D/g, '')).length > 0;
        const ok = hasDigits && !/required and must have a value|too large|number entered is too large/i.test(preview);
        debugLog(`${WD} numeric input try`, label.slice(0, 50), str, 'ok=', ok);
        if (ok) {
            debugLog(`${WD} numeric input committed`, label.slice(0, 50), str, 'ok=', true);
            return true;
        }
    }
    // Last resort: clear and type digit-by-digit into the primary control
    const str = rawDigits;
    debugLog(`${WD} numeric input retry char-by-char`, label.slice(0, 50), str);
    workdayClickElement(input);
    await wait(100);
    input.focus?.();
    selectWorkdayInputText(input);
    try { document.execCommand('selectAll', false); document.execCommand('delete', false); } catch (_) { /* ignore */ }
    wdSetInputValue(input, '');
    await wait(100);
    for (const ch of str) {
        try { document.execCommand('insertText', false, ch); } catch (_) { /* ignore */ }
        input.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: ch, bubbles: true, composed: true }));
        await wait(30);
    }
    input.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    input.dispatchEvent(new Event('blur', { bubbles: true, composed: true }));
    await wait(500);
    const ok = Boolean((input.value || '').trim())
        && !/required and must have a value|too large/i.test((container?.innerText || '').toLowerCase());
    debugLog(`${WD} numeric input committed`, label.slice(0, 50), str, 'ok=', ok);
    return ok;
}

function getEnglishProficiencyCandidatesFromProfile(profile) {
    const langs = profile?.languages || [];
    let prof = 'Native';
    for (const entry of langs) {
        const name = (typeof entry === 'string' ? entry : entry?.language || '').trim();
        if (!/english/i.test(name)) continue;
        prof = (typeof entry === 'object' ? (entry.proficiency || entry.level || '') : '') || 'Native';
        break;
    }
    const p = String(prof).toLowerCase();
    if (/native|fluent|bilingual|full professional|advanced|proficient|expert|^5\b/i.test(p)) {
        return ['Native', 'Native Speaker', 'Fluent', 'Full Professional Proficiency', 'Advanced', 'Professional Working Proficiency', '5 - Fluent', '5'];
    }
    if (/intermediate|conversational|limited|working|^3\b|^4\b/i.test(p)) {
        return ['Intermediate', 'Conversational', 'Professional Working Proficiency', 'Limited Working Proficiency', '4', '3'];
    }
    return ['Fluent', 'Native', 'Native Speaker', 'Professional Working Proficiency', 'Advanced'];
}

async function fillStreamPreferredQuestionFallbacks(profile) {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        const onQuestionsStep = (typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : '') === 'questions';
        const preview = (container.innerText || '').replace(/\s+/g, ' ');

        // Local multi-checkbox specialties — do not require "select one"/error preview
        if (isWorkdayShiftAvailabilityQuestion(label)) {
            if (!isWorkdayShiftAvailabilityFilled(container)) {
                await fillWorkdayShiftAvailabilityField(container, label);
            }
            continue;
        }
        if (isWorkdayEmploymentTypeQuestion(label)) {
            if (!(isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayEmploymentTypeCandidates())
                || isWorkdaySingleSelectFilled(container, getWorkdayEmploymentTypeCandidates()))) {
                await fillWorkdayEmploymentTypeField(container, label);
            }
            continue;
        }
        if (isWorkdayBestContactTimeQuestion(label)) {
            if (!isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayBestContactTimeCandidates())) {
                await fillWorkdayBestContactTimeField(container, label);
            }
            continue;
        }
        if (isWorkdayNaIfNoTextField(label)) {
            await fillWorkdayNaIfNoTextField(container, label, profile);
            continue;
        }
        if (isWorkdayPassportVisaTypeTextField(label)) {
            await fillWorkdayPassportVisaTypeTextField(container, label, profile);
            continue;
        }
        if (isWorkdayClinicalSettingsQuestion(label)) {
            if (!isWorkdayClinicalSettingsFilled(container, profile)) {
                await fillWorkdayClinicalSettingsField(container, label, profile);
            }
            continue;
        }

        const stillEmpty = /select one|0 items selected|required and must have a value/i.test(preview);
        if (!stillEmpty) continue;

        if (isGenpactAiMatchingOptInField(label)) {
            if (!isWorkdaySingleSelectFilled(container, getGenpactAiMatchingCandidates())) {
                await fillWorkdayGenpactAiOptInField(container, label);
            }
            continue;
        }

        if (isWorkdayPrivacyConsentDropdownField(label, container)) {
            if (!isWorkdayAgreeDisagreeConsentFilled(container)) {
                const ok = await fillWorkdayPrivacyConsentDropdown(container, label);
                if (ok || isWorkdayAgreeDisagreeConsentFilled(container) || isWorkdayYesNoFilled(container, 'Yes')) {
                    continue;
                }
                // Misclassified — fall through to hardcoded Yes/No / stream fill
            } else {
                continue;
            }
        }
        if (isWorkdayGpaQuestion(label)) {
            if (!isWorkdayGpaFilled(container)) {
                await fillWorkdayGpaField(container, label);
            }
            continue;
        }
        if (isWorkdayMajorMultiSelectQuestion(label)) {
            await fillWorkdayMajorMultiSelectField(container, label);
            continue;
        }
        if (isWorkdaySkillAbilityQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySkillAbilityCandidates())) {
                await fillWorkdaySkillAbilityField(container, label);
            }
            continue;
        }

        if (isWorkdaySmsConsentDropdownField(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySmsConsentCandidates())
                && !isWorkdayYesNoFilled(container, 'Yes')) {
                await fillWorkdaySmsConsentDropdown(container, label);
            }
            continue;
        }

        if (isWorkdayVeteranFieldLabel(label)) {
            if (!isWorkdayVeteranFilled(container)) {
                await fillWorkdayVeteranField(container, label, profile);
            }
            continue;
        }

        const hardcodedYn = getProfileDerivedYesNoAnswer(profile, label) || getHardcodedYesNoAnswer(label);
        if (hardcodedYn) {
            clearWorkdaySingleSelectMissKey(label);
            const yesCands = hardcodedYn === 'Yes' ? getWorkdayConsentYesCandidates(label) : [hardcodedYn, String(hardcodedYn).toLowerCase()];
            if (!isWorkdayYesNoFilled(container, hardcodedYn)
                && !isWorkdaySingleSelectFilled(container, yesCands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                let filled = false;
                if (hardcodedYn === 'No') {
                    filled = await fillWorkdayAlwaysNoField(container, label);
                } else if (ctrl) {
                    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
                    filled = await fillWorkdaySingleSelectDropdown(ctrl, yesCands, label)
                        || await fillWorkdayYesNoField(container, hardcodedYn);
                } else {
                    filled = await fillWorkdayYesNoField(container, hardcodedYn);
                }
                if (filled) debugLog(`${WD} hardcoded yes/no fallback`, label.slice(0, 60), yesCands[0]);
            }
            continue;
        }

        if (isNotToMyKnowledgeQuestion(container, label)) {
            if (!isNotToMyKnowledgeFilled(container)) {
                await fillWorkdayNotToMyKnowledgeField(container, label);
            }
            continue;
        }

        if (isWorkdayGovernmentEmploymentQuestion(label)) {
            // Must fill on questions (bah.wd1 Application Questions) — previously skipped via
            // onQuestionsStep continue, leaving PGE status permanently on Select One.
            if (!isWorkdaySingleSelectFilled(container, getGovernmentEmploymentDropdownCandidates(label))
                && !/never been employed/i.test(getWorkdayFieldSelectedText(container) || '')) {
                await fillWorkdayGovernmentEmploymentField(container, label);
            }
            continue;
        }

        if (isWorkdayAlwaysNoQuestion(label, container)) {
            if (!isWorkdayYesNoFilled(container, 'No')) {
                await fillWorkdayAlwaysNoField(container, label);
            }
            continue;
        }

        if (/proficiency|fluency/i.test(labelLower) && /english|language|indicate your proficiency/i.test(labelLower)) {
            const control = getContainerControl(container);
            if (!control) continue;
            debugLog(`${WD} english proficiency profile fallback after stream`);
            await fillWorkdayProficiencyDropdown(control, getEnglishProficiencyCandidatesFromProfile(profile), label);
            continue;
        }

        if (/select your race|select the race|please select your race|\bethnicity\b/i.test(labelLower) && !isHispanicLatinoOnlyFieldLabel(labelLower)) {
            const control = getContainerControl(container);
            if (!control) continue;
            const ethCandidates = mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity);
            debugLog(`${WD} race/ethnicity profile fallback`, label.slice(0, 50), '->', ethCandidates[0]);
            await fillWorkdayRaceDropdown(control, profile, labelLower);
            continue;
        }

        if (isWorkdayFormerEmployerQuestion(label)) {
            if (!isWorkdayFormerEmployerFilled(container, label)) {
                debugLog(`${WD} former employer fallback`, label.slice(0, 60));
                await fillWorkdayFormerEmployerField(container, label);
            }
            continue;
        }

        if (isSalaryAlignmentYesNoQuestion(labelLower)) {
            if (!isSalaryAlignmentFieldAcceptable(container, label)) {
                clearWorkdaySingleSelectMissKey(labelLower);
                await fillWorkdaySalaryAlignmentField(container, profile, label);
            }
            continue;
        }

        if (isCompensationFieldLabel(labelLower)) {
            const control = getContainerControl(container);
            if (!control) continue;
            if (isCompensationFieldAcceptable(container, label, control)) continue;
            resetWorkdayDropdownOpenCount(labelLower.slice(0, 80));
            await fillWorkdayCompensationField(container, profile, label);
            continue;
        }

        if (isCommuteTimeFieldLabel(labelLower)) {
            const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            const commuteOpts = WORKDAY_COMMUTE_TIME_OPTIONS.slice();
            if (control && !isWorkdaySingleSelectFilled(container, commuteOpts)) {
                clearWorkdaySingleSelectMissKey(labelLower);
                debugLog(`${WD} commute stream fallback`, label.slice(0, 60));
                await fillWorkdaySingleSelectDropdown(control, commuteOpts, labelLower);
            }
            continue;
        }
    }
}

async function workdayTypeElement(el, text) {
    if (!el || text == null || text === '') return false;
    workdayScrollToTarget(el, 120);
    await wait(200);
    workdayClickElement(el);
    await wait(150);
    el.focus?.();
    const str = String(text);
    selectWorkdayInputText(el);
    let inserted = false;
    try {
        inserted = document.execCommand('insertText', false, str);
    } catch (_) { /* ignore */ }
    if (!inserted) {
        // Paste simulation — more reliable for React-controlled inputs
        try {
            const dt = new DataTransfer();
            dt.setData('text/plain', str);
            el.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true, composed: true }));
            await wait(100);
            inserted = Boolean((el.value || '').trim());
        } catch (_) { /* ignore */ }
    }
    if (!inserted) wdSetInputValue(el, str);
    el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: str, bubbles: true, composed: true }));
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(100);
    el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true }));
    await wait(300);
    return Boolean((el.value || '').trim()) || inserted;
}

// Per-character keystroke simulation fallback for text inputs whose React-controlled state doesn't
// pick up a bulk execCommand('insertText')/paste fill (see getWorkdayErrorFieldLabelTokens): the DOM
// control.value ends up correct but Workday's own "Errors Found" validation still reports the field
// as blank on every retry, because the bulk insert never went through the per-keystroke path some
// masked/validated Workday text widgets require to update their internal state. Only used as a
// forced re-fill after a real validation error was observed for this field — not the default path.
async function workdayTypeElementKeystroke(el, text) {
    if (!el || text == null || text === '') return false;
    workdayScrollToTarget(el, 120);
    await wait(150);
    workdayClickElement(el);
    await wait(150);
    el.focus?.();
    selectWorkdayInputText(el);
    setNativeValue(el, '');
    el.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    await wait(80);
    const str = String(text);
    for (const ch of str) {
        el.dispatchEvent(new KeyboardEvent('keydown', { key: ch, bubbles: true, composed: true }));
        const prev = el.value || '';
        setNativeValue(el, prev + ch);
        el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: ch, bubbles: true, composed: true }));
        el.dispatchEvent(new KeyboardEvent('keyup', { key: ch, bubbles: true, composed: true }));
        await wait(35);
    }
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(150);
    el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true }));
    await wait(300);
    return Boolean((el.value || '').trim());
}

// Fills a plain text field, retrying with the per-keystroke fallback when a prior validation pass
// already flagged this field as blank (forceRobust) or the fast path didn't actually commit a value.
async function fillWorkdayTextFieldRobust(el, text, forceRobust = false) {
    if (!el || text == null || text === '') return false;
    let ok = await workdayTypeElement(el, text);
    const committed = (el.value || '').trim() === String(text).trim();
    if (forceRobust || !ok || !committed) {
        ok = await workdayTypeElementKeystroke(el, text) || ok;
    }
    return ok;
}

async function workdayTypeSearchInput(el, text) {
    if (!el || text == null || text === '') return false;
    workdayScrollToTarget(el, 120);
    await wait(150);
    workdayClickElement(el);
    await wait(150);
    if (!await ensureWorkdayInputFocused(el)) {
        el.focus?.();
        await wait(100);
    }
    const str = String(text);
    selectWorkdayInputText(el);
    let inserted = false;
    try {
        inserted = document.execCommand('insertText', false, str);
    } catch (_) { /* ignore */ }
    if (!inserted) setNativeValue(el, str);
    el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: str, bubbles: true, composed: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    await wait(300);
    return Boolean((el.value || '').trim()) || inserted;
}

function parseCertDates(entry) {
    return parseEntryDates({
        startDate: entry?.startDate || entry?.issueDate,
        endDate: entry?.endDate || entry?.expirationDate,
    });
}

async function fillWorkdayDateInputs(section, entry, { education = false, certification = false } = {}) {
    const dates = certification
        ? parseCertDates(entry)
        : (education ? getEducationDateFallbacks(entry) : getExperienceDateFallbacks(entry));
    const containers = [...section.querySelectorAll('[data-automation-id*="formField"]')].sort((a, b) => {
        const la = getContainerLabel(a).toLowerCase().replace(/\*/g, '').trim();
        const lb = getContainerLabel(b).toLowerCase().replace(/\*/g, '').trim();
        const aFrom = /^from\b/.test(la) ? 0 : /\bto\b/.test(la) ? 2 : 1;
        const bFrom = /^from\b/.test(lb) ? 0 : /\bto\b/.test(lb) ? 2 : 1;
        return aFrom - bFrom;
    });
    for (const container of containers) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase().replace(/\*/g, '').trim();
        const preview = (container.innerText || '').toLowerCase();
        const inputs = [...container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"])')];
        const control = inputs[0] || getContainerControl(container);
        if (!control || control.type === 'checkbox') continue;

        if (/currently work|work here|present/i.test(labelLower)) {
            const cb = container.querySelector('input[type="checkbox"]');
            const shouldCheck = isExperienceCurrent(entry);
            if (cb && shouldCheck !== cb.checked) {
                await workdayClick(cb);
                await wait(400);
            }
            continue;
        }

        // Detect MM/YYYY format: either placeholder says "MM/YYYY" or there are exactly 2 visible inputs (month + year)
        const visibleInputsInContainer = [...container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"])')].filter(isVisibleElement);
        const isMMYYYY = /mm\/yyyy|mm\s*\/\s*yyyy/.test(preview) || visibleInputsInContainer.length === 2;

        let dateValue = null;
        if (/^from\b/.test(labelLower) && dates.start) {
            dateValue = isMMYYYY ? formatWorkdayMMYYYY(dates.start.iso || entry.startDate) : dates.start.year;
        } else if ((/^to\b/.test(labelLower) || /expected/.test(labelLower)) && !education) {
            if (isExperienceCurrent(entry)) continue;
            if (dates.end) {
                dateValue = isMMYYYY ? formatWorkdayMMYYYY(dates.end.iso || entry.endDate) : dates.end.year;
            } else {
                const end = getExperienceEndFallback(dates);
                if (end) {
                    dateValue = isMMYYYY ? formatWorkdayMMYYYY(end.iso) : end.year;
                }
            }
        } else if ((/^to\b/.test(labelLower) || /expected/.test(labelLower)) && education && dates.end) {
            dateValue = isMMYYYY ? formatWorkdayMMYYYY(dates.end.iso || entry.endDate) : dates.end.year;
        } else if (certification && dates.start) {
            if (/issued|issue date|date issued|year awarded|year received|certification date|effective|date obtained|date earned/i.test(labelLower)) {
                dateValue = /mm\/yyyy|mm\s*\/\s*yyyy/.test(preview)
                    ? formatWorkdayMMYYYY(dates.start.iso || entry.startDate)
                    : dates.start.year;
            } else if (/expir|expiry|expires|valid until|valid through|renewal/i.test(labelLower) && dates.end) {
                dateValue = /mm\/yyyy|mm\s*\/\s*yyyy/.test(preview)
                    ? formatWorkdayMMYYYY(dates.end.iso || entry.endDate)
                    : dates.end.year;
            }
        }
        if (!dateValue || isDateContainerFilled(container, dateValue)) continue;

        debugLog(`${WD} filling date`, label, dateValue);
        const filled = await fillWorkdayMaskedDate(container, control, dateValue, preview);
        debugLog(`${WD} filled date`, label, dateValue, 'ok=', filled, 'preview=', (container.innerText || '').replace(/\s+/g, ' ').slice(0, 80));
    }
}

async function fillDegreeField(section, entry) {
    for (const container of section.querySelectorAll('[data-automation-id*="formField"]')) {
        const label = getContainerLabel(container).replace(/\*/g, '').trim();
        if (!/^degree$/i.test(label)) continue;
        if (isDegreeFilled(container)) continue;
        const degreeEl = getContainerControl(container) || getWorkdayDropdownTrigger(container) || container;
        await fillWorkdayDegreeDropdown(degreeEl, entry);
        await wait(500);
    }
}

function getExperiencePageFieldContainers() {
    const sections = [
        findWorkExperienceSection(),
        findEducationSectionEl(),
        findCertificationsSectionEl(),
        queryVisible('[data-automation-id="skillsSection"]'),
        queryVisible('[data-automation-id="languageSection"]'),
        queryVisible('[data-automation-id="languagesSection"]'),
        findSectionInForm(/\blanguages?\b/i),
        findSectionInForm(/\bskills\b/i),
    ].filter(Boolean);
    const containers = new Set();
    for (const sec of sections) {
        sec.querySelectorAll('[data-automation-id*="formField"]').forEach(c => containers.add(c));
    }
    return containers.size ? [...containers] : getWorkdayFieldContainers();
}

async function fillWorkdayTypeaheadMultiField(element, values, { logTag = 'typeahead', fieldLabel = '', isFilledFn, maxItems = 5 } = {}) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const popupLabel = fieldLabel || logTag;
    const vals = (Array.isArray(values) ? values : [values]).filter(Boolean).slice(0, maxItems);
    let added = 0;

    for (const val of vals) {
        const valPattern = val.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (new RegExp(valPattern, 'i').test(fieldRoot.innerText || '')) {
            added++;
            continue;
        }
        const input = fieldRoot.querySelector('input[role="combobox"]')
            || fieldRoot.querySelector('input[placeholder*="Type" i]')
            || fieldRoot.querySelector('input:not([type="hidden"]):not([type="checkbox"])');
        if (!input) {
            debugLog(`${WD} ${logTag} no input found`);
            break;
        }

        await closeWorkdayPopups();
        await wait(200);
        workdayScrollToTarget(fieldRoot, 120);

        const trigger = fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
            || fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
            || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
            || input;
        trackWorkdayDropdownOpen(logTag);
        await workdayClick(trigger);
        await wait(400);
        await workdayClick(input);
        input.focus?.();
        await wait(200);

        const searchTerm = val.length > 20 ? val.slice(0, 20) : val;
        debugLog(`${WD} ${logTag} typing`, searchTerm);
        await workdayTypeSearchInput(input, searchTerm);
        input.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
        await wait(1800);

        let popup = findPopupNearField(fieldRoot, popupLabel) || findActiveWorkdayPopup();
        let options = popup ? getScopedDropdownOptions(popup) : [];
        debugLog(`${WD} ${logTag} options after type`, options.length, options.slice(0, 5).map(o => optionText(o)));

        if (!options.length) {
            input.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true }));
            await wait(1200);
            popup = findPopupNearField(fieldRoot, popupLabel) || findActiveWorkdayPopup();
            options = popup ? getScopedDropdownOptions(popup) : [];
            debugLog(`${WD} ${logTag} options after arrow`, options.length);
        }

        const isMetaOption = (t) => /^partial list|^all$|^show more|^load more|^no items|^no results|^nothing found/i.test(t);
        const optionLabel = (o) => String((o?.text ?? optionText(o)) || '').trim();
        const findStudyMatchInItems = (items, term) => {
            const valid = items.filter(o => !isMetaOption(optionLabel(o)));
            return valid.find(o => textMatchesCandidate(optionLabel(o), term))
                || valid.find(o => textMatchesCandidate(optionLabel(o), searchTerm))
                || valid.find(o => {
                    const words = String(term).toLowerCase().split(/\s+/).filter(w => w.length > 2);
                    const ot = optionLabel(o).toLowerCase();
                    return words.length >= 1 && words.every(w => ot.includes(w));
                })
                || valid.find(o => /^(other|engineering|computer science|information technology|general studies)$/i.test(optionLabel(o)));
        };

        // Some tenants only show "Partial List" / "All" until All is clicked
        let validOptions = options.filter(o => !isMetaOption(optionText(o).trim()));
        if (!validOptions.length) {
            const allOpt = options.find(o => /^all$/i.test(optionText(o).trim()));
            if (allOpt) {
                await clickWorkdayOption(allOpt);
                await wait(2500);
                popup = findPopupNearField(fieldRoot, popupLabel) || findActiveWorkdayPopup();
                options = popup ? getScopedDropdownOptions(popup) : [];
                const popupSearch = popup?.querySelector('[data-automation-id="searchBox"] input')
                    || popup?.querySelector('input[type="search"], input[placeholder*="Search" i]');
                if (popupSearch) {
                    await workdayTypeSearchInput(popupSearch, searchTerm);
                    await wait(1500);
                    options = popup ? getScopedDropdownOptions(popup) : [];
                }
                validOptions = options.filter(o => !isMetaOption(optionText(o).trim()));
                debugLog(`${WD} ${logTag} options after All`, options.length, options.slice(0, 5).map(o => optionText(o)));
            }
        }

        const menuItems = validOptions.map(o => ({ el: o, text: optionText(o) }));
        let matchItem = findStudyMatchInItems(menuItems, val);
        if (!matchItem && popup) {
            matchItem = await scrollWorkdayDropdownListForMatch(
                fieldRoot,
                popup,
                (items) => findStudyMatchInItems(items, val),
                logTag,
            );
        }
        const match = matchItem?.el || matchItem;
        if (match && await clickWorkdayOption(match)) {
            added++;
            debugLog(`${WD} ${logTag} added`, val, 'via', optionText(match));
            await wait(500);
            trackWorkdayDropdownClose(logTag, 'selected');
            continue;
        }

        for (const key of ['Enter', 'Tab']) {
            input.dispatchEvent(new KeyboardEvent('keydown', { key, code: key, bubbles: true }));
            await wait(600);
            // Initial check: quick check first
            let nowFilled = isFilledFn ? isFilledFn(fieldRoot) : (
                new RegExp(valPattern, 'i').test(fieldRoot.innerText || '')
                && !/(0\s+items?\s+selected|select one)/i.test(fieldRoot.innerText || '')
            );
            if (nowFilled) {
                // Workday sometimes accepts text temporarily then resets — verify after longer delay
                await wait(1500);
                nowFilled = isFilledFn ? isFilledFn(fieldRoot) : (
                    new RegExp(valPattern, 'i').test(fieldRoot.innerText || '')
                    && !/(0\s+items?\s+selected|select one)/i.test(fieldRoot.innerText || '')
                );
            }
            if (nowFilled) {
                added++;
                debugLog(`${WD} ${logTag} added via ${key}`, val);
                break;
            }
        }
        trackWorkdayDropdownClose(logTag, 'done');
    }
    debugLog(`${WD} ${logTag} result`, 'added=', added, 'filled=', isFilledFn?.(fieldRoot));
    return added > 0 || isFilledFn?.(fieldRoot);
}

function isOptionalNameAffixField(label) {
    const l = String(label || '').replace(/\*/g, '').trim().toLowerCase();
    return /^(prefix|suffix|name prefix|name suffix)$/.test(l);
}

/** Prefix/Suffix are optional unless the visible label includes '*'. Workday often sets aria-required on optional affix controls. */
function shouldSkipOptionalNameAffixField(container, label) {
    if (!isOptionalNameAffixField(label)) return false;
    const labelEl = container?.querySelector?.('label, legend, [data-automation-id="label"]');
    const rawLabel = (labelEl?.innerText || labelEl?.textContent || String(label || '')).trim();
    return !rawLabel.includes('*');
}

function getProfileSkillsList(profile) {
    return (profile?.skills || [])
        .map(s => (typeof s === 'string' ? s : s?.value || s?.name || ''))
        .map(s => String(s || '').trim())
        .filter(Boolean);
}

function findWorkdaySkillsSection(container) {
    const skillsSec = container?.closest?.('[data-automation-id="skillsSection"]');
    if (skillsSec) return skillsSec;
    const sec = container?.closest?.('[data-automation-id*="Section"]');
    if (sec && /\bskills\b/i.test((getSectionHeadingEl(sec)?.innerText || '').trim())) return sec;
    return null;
}

/** Skip optional repeating skills sections; still fill required skills fields outside them. */
function shouldFillSkillsContainer(container) {
    const label = getContainerLabel(container);
    if (!/type to add skills|\bskills\b/i.test(label)) return false;
    if (!isContainerRequired(container)) return false;
    const skillsSec = findWorkdaySkillsSection(container);
    if (skillsSec && !isSectionRequired(skillsSec)) return false;
    return true;
}

function isSkillChipOptionText(text) {
    return /press delete to clear|press delete/i.test(String(text || ''));
}

function isSkillSearchResultsPopupEl(popup, fieldRoot, searchTerm = '') {
    if (!popup || !isVisibleElement(popup)) return false;
    const body = String(popup.innerText || popup.textContent || '').replace(/\s+/g, ' ');
    if (!/search results/i.test(body)) return false;
    if (isChipDisplayPopup(popup)) return false;

    const options = getScopedDropdownOptions(popup)
        .map((o) => normalizeWorkdayMenuOptionText(optionText(o) || o.innerText || ''))
        .filter((t) => t && !/^search results/i.test(t) && !isSkillChipOptionText(t));
    if (!options.length) return false;

    const term = String(searchTerm || '').trim();
    if (term) {
        const hasRelevant = options.some((t) => skillSearchTermMatchesText(t, term) || textMatchesCandidate(t, term));
        if (!hasRelevant) return false;
    } else if (options.every((t) => /community college|college$/i.test(t))) {
        return false;
    }

    if (fieldRoot?.getBoundingClientRect) {
        const rect = fieldRoot.getBoundingClientRect();
        const pr = popup.getBoundingClientRect();
        const dist = Math.abs(pr.top - rect.bottom) + Math.abs(pr.left - rect.left) * 0.25;
        if (dist > 700) return false;
    }
    return true;
}

function isSkillIrrelevantOption(text) {
    const t = String(text || '').trim();
    if (!t || isSkillChipOptionText(t)) return true;
    if (/\b(community college|state university|gulf coast|mississippi)\b/i.test(t)
        && /\b(college|university|institute)\b/i.test(t)) {
        return true;
    }
    return false;
}

function popupHasSkillRelevantOptions(popup, searchTerm = '') {
    if (!popup) return false;
    const rows = buildSearchResultRowsFromPopup(popup, { filterChipOptions: true })
        .filter((r) => !isSkillIrrelevantOption(r.text));
    if (!rows.length) return false;
    const term = String(searchTerm || '').trim();
    if (!term) return true;
    return rows.some((r) => skillSearchTermMatchesText(r.text, term) || textMatchesCandidate(r.text, term));
}

function findSkillSuggestionsPopup(fieldRoot, searchTerm = '', { requireSearchResults = false } = {}) {
    const label = 'type to add skills';
    const input = getWorkdaySkillsInput(fieldRoot);
    for (const attr of ['aria-controls', 'aria-owns']) {
        const id = input?.getAttribute(attr);
        if (!id) continue;
        const el = document.getElementById(id);
        if (!el || !isVisibleElement(el) || isChipDisplayPopup(el)) continue;
        if (isWrongPopupForField(el, label)) continue;
        if (requireSearchResults && !/search results/i.test(String(el.innerText || el.textContent || ''))) continue;
        if (!popupHasSkillRelevantOptions(el, searchTerm)) continue;
        return el;
    }

    const fieldRect = fieldRoot?.getBoundingClientRect?.();
    let best = null;
    let bestDist = Infinity;
    for (const pop of findVisibleWorkdayPopups()) {
        if (isChipDisplayPopup(pop) || isWrongPopupForField(pop, label)) continue;
        if (requireSearchResults && !/search results/i.test(String(pop.innerText || pop.textContent || ''))) continue;
        if (!popupHasSkillRelevantOptions(pop, searchTerm)) continue;
        if (!fieldRect) return pop;
        const pr = pop.getBoundingClientRect();
        const dist = Math.abs(pr.top - fieldRect.bottom) + Math.abs(pr.left - fieldRect.left) * 0.25;
        if (dist < bestDist) {
            bestDist = dist;
            best = pop;
        }
    }
    return best;
}

function getSkillSearchResultsPopup(fieldRoot, searchTerm = '') {
    return findSkillSuggestionsPopup(fieldRoot, searchTerm, { requireSearchResults: true })
        || findSkillSuggestionsPopup(fieldRoot, searchTerm, { requireSearchResults: false });
}

function buildSearchResultRowsFromPopup(pop, { filterChipOptions = false } = {}) {
    if (!pop) return [];

    const rowSelectors = '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"]';
    const candidates = [...pop.querySelectorAll(rowSelectors)].filter(isVisibleElement);

    for (const li of pop.querySelectorAll('li')) {
        if (!isVisibleElement(li)) continue;
        if (li.querySelector(rowSelectors)) continue;
        if (!li.querySelector('input[type="checkbox"], [role="checkbox"]')) continue;
        candidates.push(li);
    }

    const rows = [];
    const seenText = new Set();
    for (const row of candidates) {
        const text = normalizeWorkdayMenuOptionText(
            (row.getAttribute('aria-label') || row.innerText || row.textContent || '').trim(),
        );
        if (!text || /^search results/i.test(text)) continue;
        if (/^select one$/i.test(text)) continue;
        if (/^no items\.?$/i.test(text)) continue;
        if (filterChipOptions && isSkillChipOptionText(text)) continue;
        const textKey = text.toLowerCase();
        if (seenText.has(textKey)) continue;
        seenText.add(textKey);

        const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]');
        const radio = row.querySelector('input[type="radio"], [role="radio"]');
        rows.push({
            el: checkbox || radio || row,
            label: (checkbox?.id && document.querySelector(`label[for="${CSS.escape(checkbox.id)}"]`))
                || (radio?.id && document.querySelector(`label[for="${CSS.escape(radio.id)}"]`))
                || row.querySelector('label')
                || row,
            row,
            text,
            kind: checkbox ? 'checkbox' : (radio ? 'radio' : 'row'),
        });
    }
    return rows;
}

function findWorkdaySearchResultRows(container) {
    const pop = getHearSearchResultsPopup(container)
        || findPopupNearField(container, 'school')
        || findActiveWorkdayPopup();
    return buildSearchResultRowsFromPopup(pop);
}

function findSkillSearchResultRows(container, searchTerm = '') {
    const pop = getSkillSearchResultsPopup(container, searchTerm);
    return buildSearchResultRowsFromPopup(pop, { filterChipOptions: true })
        .filter((r) => !isSkillIrrelevantOption(r.text));
}

function skillSearchTermMatchesText(text, term = '') {
    const t = normalizeWorkdayMenuOptionText(text)
        .replace(/\s+not checked|\s+checked/gi, '')
        .trim();
    if (!t || /^search results/i.test(t)) return false;
    const needle = String(term || '').trim();
    if (!needle) return false;
    if (textMatchesCandidate(t, needle)) return true;
    const tl = t.toLowerCase();
    const nl = needle.toLowerCase();
    return tl === nl || tl.startsWith(`${nl} `) || tl.includes(nl);
}

function findSkillSearchResultOption(container, skill, term) {
    const rows = findSkillSearchResultRows(container, term);
    if (!rows.length) return null;
    return rows.find(r => skillSearchTermMatchesText(r.text, skill))
        || rows.find(r => skillSearchTermMatchesText(r.text, term))
        || rows.find(r => textMatchesCandidate(r.text, skill))
        || rows.find(r => textMatchesCandidate(r.text, term))
        || null;
}

async function commitSkillSearchSelection(fieldRoot, searchInput) {
    const input = searchInput || getWorkdaySkillsInput(fieldRoot);
    const beforeCount = countWorkdaySelectedItems(fieldRoot);

    if (input) {
        await ensureWorkdayInputFocused(input);
        await dispatchWorkdayEnterKey(input, { allowBubble: true });
        await wait(500);
        if (countWorkdaySelectedItems(fieldRoot) > beforeCount) {
            debugLog(`${WD} skill committed via search enter`, beforeCount, '->', countWorkdaySelectedItems(fieldRoot));
            return true;
        }
    }

    await commitWorkdayPopup(fieldRoot);
    await wait(400);
    if (countWorkdaySelectedItems(fieldRoot) > beforeCount) {
        debugLog(`${WD} skill committed via popup dismiss`, beforeCount, '->', countWorkdaySelectedItems(fieldRoot));
        return true;
    }

    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(400);
    }
    await commitWorkdayMultiSelectField(fieldRoot);
    const afterCount = countWorkdaySelectedItems(fieldRoot);
    if (afterCount > beforeCount) {
        debugLog(`${WD} skill committed via multiselect blur`, beforeCount, '->', afterCount);
        return true;
    }
    return false;
}

async function selectSkillSearchResultViaKeyboard(container, option, searchTerm = '') {
    const input = getWorkdaySkillsInput(container);
    if (!input || !option) return false;

    const rows = findSkillSearchResultRows(container, searchTerm);
    const idx = rows.findIndex((r) => r === option || r.text === option.text);
    if (idx < 0) return false;

    const beforeCount = countWorkdaySelectedItems(container);
    debugLog(`${WD} skill keyboard select`, option.text?.slice(0, 60), 'idx=', idx);

    await ensureWorkdayInputFocused(input);
    for (let i = 0; i <= idx; i++) {
        input.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true,
        }));
        await wait(150);
    }
    input.dispatchEvent(new KeyboardEvent('keydown', {
        key: ' ', code: 'Space', bubbles: true, cancelable: true,
    }));
    await wait(300);
    await dispatchWorkdayEnterKey(input, { allowBubble: true });
    await wait(500);

    if (countWorkdaySelectedItems(container) > beforeCount) return true;
    return commitSkillSearchSelection(container, input) && countWorkdaySelectedItems(container) > beforeCount;
}

async function dismissForeignSkillPopups(skillsFieldRoot) {
    const skillsRect = skillsFieldRoot?.getBoundingClientRect?.();
    for (const pop of findVisibleWorkdayPopups()) {
        if (isChipDisplayPopup(pop)) {
            await closeWorkdayPopups('skills-dismiss-chip');
            await wait(250);
            break;
        }
    }
    for (const input of document.querySelectorAll(
        '[data-automation-id="multiselectInputContainer"] input[role="combobox"], input[placeholder*="Type" i]',
    )) {
        const root = input.closest('[data-automation-id*="formField"]');
        if (!root || root === skillsFieldRoot) continue;
        const label = getContainerLabel(root).toLowerCase();
        if (/school|university|college|field of study|major/i.test(label)) {
            input.dispatchEvent(new Event('blur', { bubbles: true }));
            await wait(150);
        }
    }
    if (skillsRect) {
        const title = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
        if (title) {
            const tr = title.getBoundingClientRect();
            if (Math.abs(tr.top - skillsRect.top) > 200) {
                workdayScrollToTarget(skillsFieldRoot, 120);
                await wait(200);
            }
        }
    }
}

async function trySelectSkillFromRows(fieldRoot, skill, term, isAdded) {
    const searchOption = findSkillSearchResultOption(fieldRoot, skill, term);
    if (!searchOption) return false;
    debugLog(`${WD} skill pick`, term, searchOption.text?.slice(0, 60));
    if (await selectSkillSearchResultOption(fieldRoot, searchOption, isAdded, term)) {
        debugLog(`${WD} skill added via suggestion`, skill, searchOption.text?.slice(0, 60));
        return true;
    }
    debugLog(`${WD} skill suggestion select failed`, skill, searchOption.text?.slice(0, 60),
        'count=', countWorkdaySelectedItems(fieldRoot));
    return false;
}

async function toggleSkillSearchCheckbox(option) {
    const row = option?.row || option?.el;
    if (!row) return false;

    const checkbox = option.el?.type === 'checkbox' || option.el?.getAttribute?.('role') === 'checkbox'
        ? option.el
        : row.querySelector('input[type="checkbox"], [role="checkbox"]');
    const label = option.label
        || (checkbox?.id && document.querySelector(`label[for="${CSS.escape(checkbox.id)}"]`))
        || row.querySelector('label');

    row.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
    row.focus?.();
    await wait(100);

    if (checkbox && !isWorkdayCheckboxChecked(checkbox)) {
        if (await workdayClickCheckbox(checkbox, option.text?.slice(0, 60))) return true;
    } else if (checkbox && isWorkdayCheckboxChecked(checkbox)) {
        return true;
    }

    for (const target of [label, row, option.el]) {
        if (!target) continue;
        await workdayClick(target);
        await wait(300);
        if (checkbox && isWorkdayCheckboxChecked(checkbox)) return true;
    }

    for (const key of [' ', 'Enter']) {
        row.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(300);
        if (checkbox && isWorkdayCheckboxChecked(checkbox)) return true;
    }
    return checkbox ? isWorkdayCheckboxChecked(checkbox) : false;
}

async function selectSkillSearchResultOption(container, option, isAddedFn, searchTerm = '') {
    if (!option) return false;
    if (isAddedFn?.()) return true;

    const row = option.row || option.label || option.el;
    const searchInput = getWorkdaySkillsInput(container);
    debugLog(`${WD} skill search result select`, option.kind, option.text?.slice(0, 80));
    workdayScrollToTarget(row, 80);
    await wait(150);

    if (await toggleSkillSearchCheckbox(option)) {
        await wait(300);
        if (isAddedFn?.()) return true;
        if (await commitSkillSearchSelection(container, searchInput) && isAddedFn?.()) {
            return true;
        }
    }

    if (await clickWorkdayOption(row)) {
        await wait(400);
        if (isAddedFn?.()) return true;
        if (await commitSkillSearchSelection(container, searchInput) && isAddedFn?.()) {
            return true;
        }
    }

    const checkbox = option.el?.type === 'checkbox' || option.el?.getAttribute?.('role') === 'checkbox'
        ? option.el
        : row?.querySelector?.('input[type="checkbox"], [role="checkbox"]');
    const radio = option.el?.type === 'radio' || option.el?.getAttribute?.('role') === 'radio'
        ? option.el
        : row?.querySelector?.('input[type="radio"], [role="radio"]');

    if (checkbox) {
        if (await workdayClickCheckbox(checkbox, option.text?.slice(0, 60))) {
            await wait(300);
            if (isAddedFn?.()) return true;
            if (await commitSkillSearchSelection(container, searchInput) && isAddedFn?.()) {
                return true;
            }
        }
    } else if (radio) {
        const target = radio.closest('label') || row || radio;
        await workdayClick(target);
        await wait(400);
        if (radio.checked || isAddedFn?.()) return true;
        if (await commitSkillSearchSelection(container, searchInput) && isAddedFn?.()) {
            return true;
        }
    }

    for (const target of [option.label, row, option.el]) {
        if (!target) continue;
        await workdayClick(target);
        await wait(400);
        if (isAddedFn?.()) return true;
    }

    if (await clickWorkdaySkillOption(row || option.el, container, isAddedFn)) {
        await wait(400);
        if (isAddedFn?.()) return true;
    }

    if (await commitSkillSearchSelection(container, searchInput) && isAddedFn?.()) {
        return true;
    }

    if (await selectSkillSearchResultViaKeyboard(container, option, searchTerm) && isAddedFn?.()) {
        return true;
    }

    return Boolean(isAddedFn?.());
}

function getSkillSearchTerms(skill) {
    const s = String(skill || '').trim();
    if (!s) return [];
    const terms = [s];
    const simplified = s.replace(/[/&().,'\-+]+/g, ' ').replace(/\s+/g, ' ').trim();
    if (simplified && simplified.toLowerCase() !== s.toLowerCase()) terms.push(simplified);
    const words = s.split(/[\s/&,().\-+]+/).filter(w => w.length > 2);
    if (words[0]) terms.push(words[0]);
    if (words.length > 1 && words.slice(0, 2).join(' ').length <= 24) {
        terms.push(words.slice(0, 2).join(' '));
    }
    const aliasMap = {
        python: ['Python'],
        aws: ['AWS', 'Amazon Web Services'],
        azure: ['Azure', 'Microsoft Azure'],
        jira: ['Jira'],
        scrum: ['Scrum'],
        agile: ['Agile'],
        confluence: ['Confluence'],
        asana: ['Asana'],
        notion: ['Notion'],
        figma: ['Figma'],
        'microsoft office': ['Microsoft Office', 'MS Office'],
        'rest apis': ['REST', 'REST API'],
        'api integration': ['API Integration', 'API'],
    };
    const key = s.toLowerCase();
    if (aliasMap[key]) terms.push(...aliasMap[key]);
    return [...new Set(terms.filter(Boolean))].slice(0, 6);
}

function getWorkdaySkillsInput(container) {
    if (!container) return null;
    return container.querySelector('[data-automation-id="multiselectInputContainer"] input[role="combobox"]')
        || container.querySelector('[data-automation-id="multiselectInputContainer"] input:not([type="hidden"])')
        || container.querySelector('input[role="combobox"]')
        || container.querySelector('input[placeholder*="Type" i]')
        || container.querySelector('input[placeholder*="Search" i]');
}

function countWorkdaySelectedItems(container) {
    if (!container) return 0;
    const chips = container.querySelectorAll(
        '[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"] li, [data-automation-id*="selectedItem"]',
    );
    if (chips.length) return chips.length;
    const pill = container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || container.innerText || '';
    const m = pill.match(/([1-9]\d*)\s+items?\s+selected/i);
    return m ? Number(m[1]) : 0;
}

function isSkillPresentInContainer(container, skill) {
    const pattern = String(skill || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (!pattern) return false;
    for (const chip of container.querySelectorAll(
        '[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"] li, [data-automation-id*="selectedItem"]',
    )) {
        const text = (chip.innerText || chip.getAttribute('aria-label') || '').trim();
        if (new RegExp(pattern, 'i').test(text)) return true;
    }
    const preview = (container.innerText || '').replace(/type to add skills/i, '');
    return new RegExp(pattern, 'i').test(preview);
}

function isSkillsMultiSelectFilled(container, minCount = 1) {
    return countWorkdaySelectedItems(container) >= minCount;
}

async function commitWorkdayMultiSelectField(container) {
    const input = getWorkdaySkillsInput(container);
    if (input) {
        input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', code: 'Tab', bubbles: true, cancelable: true }));
        input.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(300);
    }
    await blurAwayFromHearField(container);
    await closeWorkdayPopups();
    await wait(300);
}

async function clickWorkdaySkillOption(opt, fieldRoot, isAddedFn) {
    if (!opt) return false;
    const clickTargets = [
        opt.querySelector('input[type="checkbox"]'),
        opt.querySelector('[role="checkbox"]'),
        opt.querySelector('[data-automation-id="promptLeafNode"]'),
        opt.querySelector('[data-automation-id="promptOption"]'),
        opt.querySelector('label'),
        opt,
    ].filter(Boolean);
    for (const target of clickTargets) {
        await workdayClick(target);
        await wait(350);
        if (isAddedFn?.() || isHearOptionSelected(opt)) return true;
    }
    opt.focus?.();
    for (const key of [' ', 'Enter']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(350);
        if (isAddedFn?.() || isHearOptionSelected(opt)) return true;
    }
    return Boolean(isAddedFn?.());
}

function getWorkdaySkillMenuOptions(popup, fieldRoot) {
    const scope = popup || fieldRoot;
    if (!scope) return [];
    return [...scope.querySelectorAll(
        '[data-automation-id="menuItem"], [data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], li[role="option"], div[role="option"]',
    )].filter(isVisibleElement).filter((o) => {
        const t = optionText(o);
        return t && !/^no items\.?$/i.test(t) && !isSkillChipOptionText(t);
    });
}

async function dismissWorkdaySkillPopup(fieldRoot) {
    const input = getWorkdaySkillsInput(fieldRoot);
    if (input) {
        input.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(200);
    }
    const expSection = findWorkExperienceSection();
    if (expSection && findEmptyInlineFormRoot(expSection)) {
        const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
        if (pageTitle) await workdayClick(pageTitle);
        await wait(300);
        return;
    }
    await closeWorkdayPopups();
}

async function addWorkdaySkillToContainer(container, skill) {
    const fieldRoot = container;
    const beforeCount = countWorkdaySelectedItems(fieldRoot);
    const isAdded = () => isSkillPresentInContainer(fieldRoot, skill) || countWorkdaySelectedItems(fieldRoot) > beforeCount;
    if (isSkillPresentInContainer(fieldRoot, skill)) {
        debugLog(`${WD} skill already present`, skill);
        return true;
    }

    const input = getWorkdaySkillsInput(fieldRoot);
    if (!input) {
        debugLog(`${WD} skill input not found`, getContainerLabel(fieldRoot).slice(0, 50));
        return false;
    }

    for (const term of getSkillSearchTerms(skill)) {
        await closeWorkdayPopups('skills');
        await dismissWorkdaySkillPopup(fieldRoot);
        await dismissForeignSkillPopups(fieldRoot);
        await wait(300);
        workdayScrollToTarget(fieldRoot, 120);

        const openTarget = fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
            || getWorkdayDropdownTrigger(fieldRoot)
            || input;
        trackWorkdayDropdownOpen('skill');
        await workdayClick(openTarget);
        await wait(350);
        await workdayClick(input);
        input.focus?.();
        await wait(200);

        debugLog(`${WD} skill typing`, skill, 'term=', term.slice(0, 30));
        await workdayTypeSearchInput(input, term);
        await wait(400);
        if (!await ensureWorkdayInputFocused(input)) {
            await workdayClick(input);
            await wait(200);
            await ensureWorkdayInputFocused(input);
        }

        // Live suggestions (type + ArrowDown) — often shows PostgreSQL etc. without Enter
        input.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true,
        }));
        await wait(1200);
        let searchRows = [];
        for (let poll = 0; poll < 8; poll++) {
            if (isAdded()) break;
            searchRows = findSkillSearchResultRows(fieldRoot, term);
            if (searchRows.length) break;
            await wait(300);
        }
        if (searchRows.length) {
            debugLog(`${WD} skill live suggestions`, term, searchRows.slice(0, 4).map(r => r.text));
            if (await trySelectSkillFromRows(fieldRoot, skill, term, isAdded)) {
                trackWorkdayDropdownClose('skill', 'live-suggest');
                return true;
            }
        }

        // Search Results popup (type + Enter)
        await submitSkillSearchInput(input);
        await wait(900);

        if (isAdded()) {
            debugLog(`${WD} skill added after search enter`, skill, term.slice(0, 30));
            trackWorkdayDropdownClose('skill', 'search-enter');
            return true;
        }

        searchRows = [];
        for (let poll = 0; poll < 10; poll++) {
            if (isAdded()) break;
            searchRows = findSkillSearchResultRows(fieldRoot, term);
            if (searchRows.length) break;
            await wait(350);
        }
        if (searchRows.length) {
            debugLog(`${WD} skill search results`, term, searchRows.slice(0, 4).map(r => r.text));
            if (await trySelectSkillFromRows(fieldRoot, skill, term, isAdded)) {
                trackWorkdayDropdownClose('skill', 'search-result');
                return true;
            }
        } else {
            debugLog(`${WD} skill search results popup not found`, term);
        }

        const popup = getSkillSearchResultsPopup(fieldRoot, term);
        const options = popup ? getWorkdaySkillMenuOptions(popup, fieldRoot) : [];
        debugLog(`${WD} skill options`, term, 'count=', options.length, options.slice(0, 8).map(o => optionText(o)));

        const match = options.find(o => textMatchesCandidate(optionText(o), skill))
            || options.find(o => textMatchesCandidate(optionText(o), term))
            || options.find(o => /^add\b/i.test(optionText(o)) && textMatchesCandidate(optionText(o).replace(/^add\s+/i, ''), skill));

        if (!match) {
            debugLog(`${WD} skill no match in suggestions`, skill, term);
            trackWorkdayDropdownClose('skill', 'no-match');
            continue;
        }

        if (await clickWorkdayMenuItem(match, fieldRoot, isAdded)) {
            debugLog(`${WD} skill added via menu item`, skill, optionText(match));
            trackWorkdayDropdownClose('skill', 'selected');
            return true;
        }
        if (!isAdded() && await commitSkillSearchSelection(fieldRoot, input) && isAdded()) {
            debugLog(`${WD} skill added via menu item commit`, skill, optionText(match));
            trackWorkdayDropdownClose('skill', 'selected-commit');
            return true;
        }
        if (await clickWorkdaySkillOption(match, fieldRoot, isAdded)) {
            debugLog(`${WD} skill added via option`, skill, optionText(match));
            trackWorkdayDropdownClose('skill', 'selected');
            return true;
        }
        if (!isAdded() && await commitSkillSearchSelection(fieldRoot, input) && isAdded()) {
            debugLog(`${WD} skill added via option commit`, skill, optionText(match));
            trackWorkdayDropdownClose('skill', 'selected-commit');
            return true;
        }
        trackWorkdayDropdownClose('skill', 'miss');
    }

    return isAdded();
}

async function fillWorkdaySkillsMultiSelect(container, skills, { minAdded = 1, maxItems = MAX_WORKDAY_SKILLS } = {}) {
    const vals = (Array.isArray(skills) ? skills : [skills]).filter(Boolean);
    let added = countWorkdaySelectedItems(container);
    debugLog(`${WD} skills multi start`, 'existing=', added, 'target=', minAdded, 'max=', maxItems, 'candidates=', vals.length);

    for (const skill of vals) {
        if (countWorkdaySelectedItems(container) >= maxItems) break;
        if (isSkillPresentInContainer(container, skill)) continue;
        const before = countWorkdaySelectedItems(container);
        const ok = await addWorkdaySkillToContainer(container, skill);
        const after = countWorkdaySelectedItems(container);
        if (ok && after > before) {
            added = after;
            debugLog(`${WD} skills progress`, added, skill);
        }
        await wait(300);
    }

    const count = countWorkdaySelectedItems(container);
    const filled = count >= Math.min(minAdded, 1);
    debugLog(`${WD} skills multi done`, 'count=', count, 'filled=', filled,
        (container.innerText || '').replace(/\s+/g, ' ').slice(0, 120));
    return filled;
}

async function fillSkillsField(profile) {
    const profileSkills = getProfileSkillsList(profile);
    const skills = profileSkills.slice(0, MAX_WORKDAY_SKILLS);
    if (!skills.length) {
        debugLog(`${WD} skills skipped — no skills in profile`);
        return;
    }

    const skillSections = [
        queryVisible('[data-automation-id="skillsSection"]'),
        findSectionInForm(/\bskills\b/i),
    ].filter(Boolean);

    for (const sec of skillSections) {
        if (!isSectionRequired(sec)) await dismissOptionalRepeatingSection(sec, 'skills');
    }

    const containers = getExperiencePageFieldContainers().filter(shouldFillSkillsContainer);
    if (!containers.length) {
        debugLog(`${WD} skills not required — skipping`);
        return;
    }

    for (const container of containers) {
        const label = getContainerLabel(container);

        if (isSkillsMultiSelectFilled(container, 1)) {
            debugLog(`${WD} filled skills already`, countWorkdaySelectedItems(container),
                (container.innerText || '').replace(/\s+/g, ' ').slice(0, 80));
            continue;
        }

        debugLog(`${WD} filling skills`, label.slice(0, 60), 'count=', skills.length,
            'preview=', (container.innerText || '').replace(/\s+/g, ' ').slice(0, 80));

        let ok = await fillWorkdaySkillsMultiSelect(container, skills, { minAdded: 1, maxItems: MAX_WORKDAY_SKILLS });
        if (!ok) {
            ok = await fillWorkdayTypeaheadMultiField(getWorkdaySkillsInput(container) || getContainerControl(container), skills, {
                logTag: 'skill typeahead fallback',
                fieldLabel: 'type to add skills',
                isFilledFn: (root) => isSkillsMultiSelectFilled(root, 1),
                maxItems: MAX_WORKDAY_SKILLS,
            });
        }
        debugLog(`${WD} filled skills`, 'ok=', ok || isSkillsMultiSelectFilled(container, 1),
            'selected=', countWorkdaySelectedItems(container),
            (container.innerText || '').replace(/\s+/g, ' ').slice(0, 120));
    }
}

async function fillLanguagesField(profile) {
    const languages = getProfileLanguages(profile);
    if (!languages.length) return;

    for (const container of getExperiencePageFieldContainers()) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        if (!/\blanguages?\b/i.test(labelLower)) continue;
        if (/proficiency|fluency|level|overall/i.test(labelLower) && !/languages/i.test(labelLower)) continue;

        const control = getContainerControl(container);
        if (!control) continue;
        const previewBefore = container.innerText || '';

        for (const lang of languages) {
            const langPattern = lang.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            await fillWorkdayScrollMultiSelect(control, [lang, lang.split(/\s+/)[0]], {
                logTag: 'language',
                fieldLabel: label,
                isFilledFn: (root) => {
                    const preview = root.innerText || '';
                    return new RegExp(langPattern, 'i').test(preview)
                        || (/[1-9]\d*\s+items?\s+selected/i.test(preview) && preview !== previewBefore);
                },
            });
            await wait(400);
        }
        debugLog(`${WD} filled languages`, (container.innerText || '').replace(/\s+/g, ' ').slice(0, 120));
    }
}

function hasRequiredEmptyLanguageFields() {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).replace(/\*/g, '').trim().toLowerCase();
        if (!isContainerRequired(container)) continue;
        if (!isWorkdayLanguageProficiencyLabel(label) && !/^language$|^languages$/i.test(label)) continue;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        if (/select one|0 items selected/i.test(preview)) return true;
    }
    return false;
}

/** Language skill level widgets: Overall / Overall Ability / Reading / Speaking / … */
function isWorkdayLanguageProficiencyLabel(label) {
    const l = String(label || '').replace(/\*/g, '').trim().toLowerCase();
    if (!l) return false;
    if (/^overall(?:\s+ability)?$/i.test(l)) return true;
    if (/proficiency|fluency|^level$|comprehension|listening|reading|writing|speaking|fluent|foundational/i.test(l)) {
        return true;
    }
    return false;
}

async function fillInlineLanguageProficiencyFields(profile, lang) {
    const isNativeLevel = /english/i.test(lang);
    const profDefault = isNativeLevel
        ? ['Native', 'Native Speaker', 'Fluent', 'Full Professional Proficiency', '5', 'Expert', '4 - Fluent', 'Advanced',
            'Understand enough to be able to provide customer service']
        : ['Fluent', 'Professional', 'Full Professional Proficiency', 'Conversational', 'Intermediate', 'Advanced', '4', '4 - Fluent'];

    for (const container of getWorkdayFieldContainers()) {
        const raw = getContainerLabel(container);
        const label = raw.replace(/\*/g, '').trim().toLowerCase();
        if (!isContainerRequired(container)) continue;
        if (!isWorkdayLanguageProficiencyLabel(label)) continue;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        if (!/select one|0 items selected|error:/i.test(preview)) continue;
        const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
        if (!control) continue;
        debugLog(`${WD} filling inline language proficiency`, raw.slice(0, 40));
        await fillWorkdayProficiencyDropdown(control, profDefault, raw);
    }
}

async function fillInlineLanguageFields(profile) {
    let languages = getProfileLanguages(profile);
    if (!languages.length) languages = ['English'];

    for (const lang of languages.slice(0, 2)) {
        const langPattern = lang.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        for (const container of getWorkdayFieldContainers()) {
            const raw = getContainerLabel(container);
            const label = raw.replace(/\*/g, '').trim().toLowerCase();
            if (label !== 'language' || !isContainerRequired(container)) continue;
            const preview = (container.innerText || '').replace(/\s+/g, ' ');
            if (!/select one|0 items selected/i.test(preview) && new RegExp(langPattern, 'i').test(preview)) {
                break;
            }
            if (!/select one|0 items selected/i.test(preview)) continue;
            const control = getContainerControl(container);
            if (!control) continue;
            debugLog(`${WD} filling inline language`, lang);
            await fillWorkdaySingleSelectDropdown(control, [lang, lang.split(/\s+/)[0], 'English'], raw);
            if (/select one|0 items selected/i.test(container.innerText || '')) {
                await fillWorkdayScrollMultiSelect(control, [lang, lang.split(/\s+/)[0], 'English'], {
                    logTag: 'language-inline',
                    fieldLabel: raw,
                    isFilledFn: (root) => !/select one|0 items selected/i.test(root.innerText || ''),
                });
            }
            await wait(400);
            break;
        }
        await fillInlineLanguageProficiencyFields(profile, lang);
    }
    debugLog(`${WD} filled inline language fields`);
}

/** Pick best option when language ability is modality-based (not CEFR/ILR). */
function pickWorkdayLanguageAbilityFallback(options) {
    const usable = (options || []).filter((o) => {
        const t = optionText(o).trim();
        return t && !/^select one$/i.test(t) && !/^please select/i.test(t) && !/^n\/?a$/i.test(t);
    });
    if (!usable.length) return null;
    const preferred = usable.find((o) =>
        /customer service|all (?:skills|abilities|four)|overall|fluent|proficient|native|full (?:professional|ability)|understand enough/i.test(optionText(o)));
    if (preferred) return preferred;
    const notOnly = usable.filter((o) => !/\bonly\b/i.test(optionText(o)));
    if (notOnly.length) {
        return notOnly.slice().sort((a, b) => optionText(b).length - optionText(a).length)[0];
    }
    return usable.find((o) => /speaking/i.test(optionText(o))) || usable[0];
}

async function fillWorkdayProficiencyDropdown(control, candidates, label = '') {
    const fieldRoot = control.closest('[data-automation-id*="formField"]') || control.parentElement;
    const isFilled = () => !/select one|0 items selected|error:/i.test((fieldRoot.innerText || '').replace(/\s+/g, ' '));
    if (isFilled()) return true;

    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    const openKey = String(label || 'language-proficiency').trim().toLowerCase() || 'language-proficiency';
    const openCount = Number(window.__wdProficiencyOpenCount?.[openKey] || 0);
    if (openCount >= 2) {
        debugLog(`${WD} language proficiency skip — max opens`, openKey, openCount);
        return isFilled();
    }
    window.__wdProficiencyOpenCount = window.__wdProficiencyOpenCount || {};
    window.__wdProficiencyOpenCount[openKey] = openCount + 1;

    // Single-open approach: open dropdown ONCE, find best match from available options
    await closeWorkdayPopups();
    await wait(300);
    // Blur whatever is currently focused to prevent toggle/dismiss behaviour when clicking trigger
    if (document.activeElement && document.activeElement !== document.body) {
        document.activeElement.blur?.();
        await wait(200);
    }
    workdayScrollToTarget(fieldRoot, 120);
    const trigger = getWorkdayDropdownTrigger(fieldRoot) || control;
    trackWorkdayDropdownOpen(label || 'language-proficiency');
    await workdayClick(trigger);
    await wait(1200);

    const isProficiencyPopup = (p) => {
        if (!p) return false;
        const sample = getSingleSelectDropdownOptions(p, false).slice(0, 10).map(o => optionText(o).toLowerCase()).join(' ');
        // If options contain "press delete to clear" or look like subject/field names, wrong popup
        if (/press delete to clear|architectural|engineering|accounting|science|computer|business|biology/i.test(sample)) return false;
        // Classic proficiency OR modality ability ("Reading only", customer-service understanding)
        return /fluent|beginner|native|advanced|intermediate|professional|basic|\b[1-5]\s*[-–]|\bselect one\b|reading only|speaking only|writing only|customer service|understand enough|comprehension/i.test(sample);
    };

    let popup = findPopupNearField(fieldRoot, label) || findActiveWorkdayPopup();
    // If popup found but not proficiency popup, close it and retry with fresh click
    if (popup && !isProficiencyPopup(popup)) {
        debugLog(`${WD} wrong popup for proficiency, closing and retrying`);
        await closeWorkdayPopups();
        await wait(600);
        workdayScrollToTarget(fieldRoot, 80);
        await workdayClick(trigger);
        await wait(1200);
        popup = findPopupNearField(fieldRoot, label) || findActiveWorkdayPopup();
        if (popup && !isProficiencyPopup(popup)) {
            debugLog(`${WD} still wrong popup after retry, skipping proficiency`);
            await closeWorkdayPopups();
            await wait(400);
            trackWorkdayDropdownClose(label || 'language-proficiency', 'no-popup');
            return isFilled();
        }
    }
    if (!popup) {
        // Retry once — close any lingering popups, scroll, and click again
        await closeWorkdayPopups();
        await wait(500);
        workdayScrollToTarget(fieldRoot, 80);
        await workdayClick(trigger);
        await wait(1200);
        popup = findPopupNearField(fieldRoot, label) || findActiveWorkdayPopup();
        if (popup && !isProficiencyPopup(popup)) {
            debugLog(`${WD} still wrong popup after retry, skipping`);
            await closeWorkdayPopups();
            await wait(400);
            popup = null;
        }
    }
    if (!popup) {
        trackWorkdayDropdownClose(label || 'language-proficiency', 'no-popup');
        return isFilled();
    }

    const options = getSingleSelectDropdownOptions(popup, false);
    const optTexts = options.map(o => optionText(o).toLowerCase());
    debugLog(`${WD} single-select options`, optTexts.slice(0, 10), 'target=', vals[0]?.toLowerCase());

    // Candidate match → classic proficiency term → modality/ability fallback (Reading only / customer service)
    const match = options.find(o => vals.some(c => textMatchesCandidate(optionText(o), c)))
        || options.find(o => /fluent|5\s*[\-–]|full professional|advanced|professional|native|expert/i.test(optionText(o)))
        || pickWorkdayLanguageAbilityFallback(options);

    if (match) {
        debugLog(`${WD} language proficiency selecting`, optionText(match));
        workdayClickElement(match);
        await wait(400);
        const combobox = fieldRoot.querySelector('input[role="combobox"]') || control;
        await commitWorkdayComboboxSelection(fieldRoot, combobox, match, optionText(match));
        await wait(400);
        debugLog(`${WD} language proficiency filled`, optionText(match));
    }
    await dismissWorkdayFieldDropdown(fieldRoot, label || 'language-proficiency');
    trackWorkdayDropdownClose(label || 'language-proficiency', isFilled() ? 'selected' : 'miss');
    return isFilled();
}

async function fillLanguagesSection(profile) {
    let languages = getProfileLanguages(profile);
    const needsInline = hasRequiredEmptyLanguageFields();
    if (!languages.length) {
        if (!needsInline) return;
        languages = ['English'];
    }

    const section = queryVisible('[data-automation-id="languageSection"]')
        || queryVisible('[data-automation-id="languagesSection"]')
        || findSectionInForm(/^languages/i);
    if (!section) {
        await fillLanguagesField(profile);
        await fillInlineLanguageFields(profile);
        return;
    }

    if (!isSectionRequired(section) && countWorkdaySectionEntries(section) === 0) {
        if (!needsInline) {
            debugLog(`${WD} languages section not required and empty — skipping`);
            return;
        }
        debugLog(`${WD} languages section has required inline fields — filling`);
        await fillInlineLanguageFields(profile);
        return;
    }

    // Helper to fill proficiency dropdowns in a language entry root
    const fillLangProficiency = async (root, lang) => {
        for (const container of root.querySelectorAll('[data-automation-id*="formField"]')) {
            const rawLabel = getContainerLabel(container);
            const label = rawLabel.replace(/\*/g, '').trim().toLowerCase();
            if (!isWorkdayLanguageProficiencyLabel(label)
                && !/native|\bread\b|\bwrite\b|\bspeak\b|\bfoundational\b|\badvanced\b|\bexpert\b/i.test(label)) {
                continue;
            }
            const preview = container.innerText || '';
            if (!/select one|0 items selected|error:/i.test(preview)) continue;
            const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            if (!control) continue;
            const isNativeLevel = /english/i.test(lang);
            const profDefault = isNativeLevel
                ? ['Native', 'Native Speaker', 'Fluent', 'Full Professional Proficiency', 'Understand enough to be able to provide customer service']
                : ['Fluent', 'Professional', 'Full Professional Proficiency', 'Conversational', 'Intermediate', 'Advanced'];
            const labelBasedPref = /fluent/i.test(label) ? ['Fluent', 'Proficient', ...profDefault]
                : /foundational/i.test(label) ? ['Foundational', 'Basic', 'Elementary', 'Beginner', ...profDefault]
                : /overall/i.test(label) ? ['Understand enough to be able to provide customer service', ...profDefault]
                : profDefault;
            debugLog(`${WD} filling language proficiency`, label.slice(0, 40));
            await fillWorkdayProficiencyDropdown(control, labelBasedPref, rawLabel);
        }
    };

    for (const lang of languages) {
        const langPattern = lang.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const deleteBtns = getWorkdaySectionDeleteButtons(section);
        const existingRoot = deleteBtns.length > 0
            ? [...deleteBtns].map(btn => getEntryRootFromDeleteBtn(btn, section))
                .find(r => r && new RegExp(langPattern, 'i').test(r.innerText || ''))
            : null;

        if (existingRoot) {
            // Language already added — just fill missing proficiency dropdowns
            debugLog(`${WD} language already in section, filling proficiency`, lang);
            await fillLangProficiency(existingRoot, lang);
            await saveWorkdayEntryModal() || await saveWorkdaySectionEntry(section, existingRoot);
            await wait(400);
            continue;
        }

        const addBtn = findAddButton(section);
        if (addBtn) {
            debugLog(`${WD} adding language entry`, lang);
            await workdayClick(addBtn);
            await wait(2000);
        }

        const root = resolveWorkdayEntryRoot(section, { useLatestEntry: true });
        for (const container of root.querySelectorAll('[data-automation-id*="formField"]')) {
            const label = getContainerLabel(container).toLowerCase();
            if (!/^language/i.test(label) || /proficiency|fluency|comprehension|reading|writing|speaking|overall/i.test(label)) {
                continue;
            }
            const control = getContainerControl(container);
            if (!control) continue;
            const preview = container.innerText || '';
            if (/select one|0 items selected/i.test(preview) || !new RegExp(langPattern, 'i').test(preview)) {
                await fillWorkdaySingleSelectDropdown(control, [lang, lang.split(/\s+/)[0], 'English'], 'Language');
                if (!/select one|0 items selected/i.test(container.innerText || '')) continue;
                await fillWorkdayScrollMultiSelect(control, [lang, lang.split(/\s+/)[0]], {
                    logTag: 'language',
                    fieldLabel: 'language',
                    isFilledFn: (r) => new RegExp(langPattern, 'i').test(r.innerText || ''),
                });
            }
        }

        await fillLangProficiency(root, lang);
        await saveWorkdayEntryModal() || await saveWorkdaySectionEntry(section, root);
        await wait(400);
    }
    debugLog(`${WD} filled languages section`);
}

async function fillApplicationQuestions(profile) {
    await fillKnownYesNoRadioFields(profile);
    await fillDisclosureCheckboxes();
    async function clickYesNoInContainer(container, answer) {
        const target = String(answer).toLowerCase();
        const fieldRoot = container.closest('[data-automation-id*="formField"]') || container;
        for (const radio of fieldRoot.querySelectorAll('input[type="radio"]')) {
            const optLabel = (document.querySelector(`label[for="${radio.id}"]`)?.innerText
                || radio.closest('label')?.innerText || '').trim().toLowerCase();
            if (optLabel === target && !radio.checked) {
                await workdayClick(document.querySelector(`label[for="${radio.id}"]`) || radio);
                return radio.checked;
            }
        }
        for (const labelEl of fieldRoot.querySelectorAll('label')) {
            if ((labelEl.innerText || '').trim().toLowerCase() !== target) continue;
            const input = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
            await workdayClick(labelEl);
            if (input?.type === 'radio' && !input.checked) {
                input.checked = true;
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }
            return Boolean(input?.checked || input?.type === 'checkbox');
        }
        const btn = [...fieldRoot.querySelectorAll('button, [role="button"], span')]
            .find(el => (el.innerText || '').trim().toLowerCase() === target);
        if (btn) {
            await workdayClick(btn);
            return true;
        }
        return false;
    }

    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (shouldSkipOptionalNameAffixField(container, label)) continue;
        const labelLower = label.toLowerCase();
        const onQuestionsStep = (typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : '') === 'questions';

        if (isNotToMyKnowledgeQuestion(container, label)) {
            if (!isNotToMyKnowledgeFilled(container)) {
                const ok = await fillWorkdayNotToMyKnowledgeField(container, label);
                debugLog(`${WD} filled not-to-my-knowledge`, label.slice(0, 80), 'ok=', ok);
            }
            continue;
        }

        if (isGenpactAiMatchingOptInField(label)) {
            if (!isWorkdaySingleSelectFilled(container, getGenpactAiMatchingCandidates())) {
                await fillWorkdayGenpactAiOptInField(container, label);
            }
            continue;
        }

        if (isWorkdayPrivacyConsentDropdownField(label, container)) {
            if (!isWorkdayAgreeDisagreeConsentFilled(container)) {
                const ok = await fillWorkdayPrivacyConsentDropdown(container, label);
                if (ok || isWorkdayAgreeDisagreeConsentFilled(container) || isWorkdayYesNoFilled(container, 'Yes')) {
                    continue;
                }
                // Misclassified — fall through to hardcoded Yes/No / stream fill
            } else {
                continue;
            }
        }
        if (isWorkdayGpaQuestion(label)) {
            if (!isWorkdayGpaFilled(container)) {
                await fillWorkdayGpaField(container, label);
            }
            continue;
        }
        if (isWorkdayMajorMultiSelectQuestion(label)) {
            await fillWorkdayMajorMultiSelectField(container, label);
            continue;
        }
        if (isWorkdaySkillAbilityQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySkillAbilityCandidates())) {
                await fillWorkdaySkillAbilityField(container, label);
            }
            continue;
        }

        if (isWorkdaySmsConsentDropdownField(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySmsConsentCandidates())
                && !isWorkdayYesNoFilled(container, 'Yes')) {
                await fillWorkdaySmsConsentDropdown(container, label);
            }
            continue;
        }

        const hardcodedYn = getProfileDerivedYesNoAnswer(profile, label) || getHardcodedYesNoAnswer(label);
        if (hardcodedYn) {
            clearWorkdaySingleSelectMissKey(label);
            if (isWorkdayYesNoFilled(container, hardcodedYn)
                || isWorkdaySingleSelectFilled(container, [hardcodedYn, hardcodedYn.toLowerCase()])) {
                markWorkdayLockedYesNoFilled(label);
                continue;
            }
            let filled = hardcodedYn === 'No'
                ? await fillWorkdayAlwaysNoField(container, label)
                : await fillWorkdayYesNoField(container, hardcodedYn);
            if (!filled && isGdprRecruitmentConsentField(label)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                if (ctrl) {
                    filled = await fillWorkdaySingleSelectDropdown(ctrl, ['Yes', 'I agree', 'I Agree'], labelLower.slice(0, 80));
                    if (filled) debugLog(`${WD} filled GDPR consent dropdown`, label.slice(0, 60), hardcodedYn);
                }
            } else if (filled) {
                debugLog(`${WD} filled hardcoded yes/no`, label.slice(0, 60), hardcodedYn);
            }
            continue;
        }
        if (isWorkdayYearsExperienceBandQuestion(label)) {
            const years = Number(profile?.workingExperienceInYears ?? profile?.working_experience_in_years);
            const yearsVal = Number.isFinite(years) && years > 0
                ? (Number.isInteger(years) ? String(years) : years.toFixed(1))
                : '6';
            const textCtrl = container.querySelector('input[type="text"], input[type="number"], textarea')
                || ((getContainerControl(container)?.tagName === 'INPUT'
                    || getContainerControl(container)?.tagName === 'TEXTAREA')
                    && !getContainerControl(container)?.getAttribute?.('role')
                    && !getContainerControl(container)?.getAttribute?.('aria-haspopup')
                    ? getContainerControl(container) : null);
            const hasDropdown = !!(container.querySelector(
                'button[aria-haspopup="listbox"], [role="combobox"], [data-automation-id="promptSelectionLabel"], [data-automation-id="promptArrow"]',
            ));
            // ovationhealthcare.wd5: plain text input (not a band dropdown).
            if (textCtrl && !hasDropdown) {
                if (!(textCtrl.value || '').trim()) {
                    const ok = await commitWorkdayNumericInput(textCtrl, yearsVal, label);
                    debugLog(`${WD} filled years-experience text`, label.slice(0, 60), yearsVal, 'ok=', ok);
                }
                continue;
            }
            const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            const previewOpts = [...container.querySelectorAll('label, [role="option"], [data-automation-id="promptOption"]')]
                .map(el => (el.innerText || '').trim()).filter(t => t && t.length < 80);
            const band = getWorkdayYearsExperienceBandAnswer(label, previewOpts, profile);
            const bandCands = [
                band,
                '6+ years', '5+ years', '5 years or more', '3-6 years', '1-3 years',
                "Over 5 years' experience", 'Over 5 years experience', 'Over 5 years',
                'Between 3-5 years', 'Between 1-3 years', '3 years or more',
                'Less than 1 year', 'No experience',
                ...previewOpts.filter(o => /year|none|over|between|less|\+/i.test(o)),
            ].filter(Boolean);
            if (ctrl && !isWorkdaySingleSelectFilled(container, bandCands)) {
                clearWorkdaySingleSelectMissKey(label);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
                const ok = await fillWorkdaySingleSelectDropdown(ctrl, bandCands, labelLower);
                debugLog(`${WD} filled years-experience band`, label.slice(0, 60), band, 'ok=', ok);
            }
            continue;
        }
        // Geographic preference checkboxes (ovationhealthcare.wd5) — not a single-select listbox.
        if (/geographic preferences|open to relocation.*select your|select your geographic/i.test(labelLower)) {
            const ok = await fillWorkdayGeographicPreferenceCheckboxes(container, label);
            debugLog(`${WD} filled geographic preference checkboxes`, label.slice(0, 60), 'ok=', ok);
            continue;
        }
        if (/notice period/i.test(labelLower)) {
            const noticeText = '2 weeks';
            const textCtrl = container.querySelector('textarea, input[type="text"]')
                || ((getContainerControl(container)?.tagName === 'TEXTAREA'
                    || (getContainerControl(container)?.tagName === 'INPUT'
                        && !getContainerControl(container)?.getAttribute?.('role')))
                    ? getContainerControl(container) : null);
            const hasDropdown = !!(container.querySelector(
                'button[aria-haspopup="listbox"], [role="combobox"], [data-automation-id="promptSelectionLabel"], [data-automation-id="promptArrow"]',
            ));
            // ovationhealthcare.wd5: free-text / textarea notice period.
            if (textCtrl && !hasDropdown) {
                if (!(textCtrl.value || '').trim()) {
                    await workdayTypeElement(textCtrl, noticeText);
                    await wait(300);
                    debugLog(`${WD} filled notice period text`, label.slice(0, 60), noticeText,
                        'ok=', Boolean((textCtrl.value || '').trim()));
                }
                continue;
            }
            const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            const noticeCands = [
                '2 Weeks Notice', '2 Weeks', '2 weeks', '14 days',
                '1 Month Notice', '1 Month', '1 month', '30 days', '4 Weeks', '4 weeks',
                '2 Months Notice', '2 Months', '2 months', '60 days',
                '3 Months', '3 months', '90 days',
                'Immediately', 'Immediate', 'None', 'N/A',
            ];
            // Already committed (e.g. stream "2 Months") — do not reopen / miss-lock.
            if (/\d+\s*months?|\d+\s*weeks?|immediate/i.test(getWorkdayFieldSelectedText(container) || '')
                || isWorkdayOpaqueOptionId(getWorkdayComboboxInputValue(container))) {
                continue;
            }
            if (ctrl && !isWorkdaySingleSelectFilled(container, noticeCands)) {
                clearWorkdaySingleSelectMissKey(label);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
                const ok = await fillWorkdaySingleSelectDropdown(ctrl, noticeCands, labelLower);
                debugLog(`${WD} filled notice period`, label.slice(0, 60), 'ok=', ok);
            }
            continue;
        }
        if (isWorkdayGovernmentEmploymentQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getGovernmentEmploymentDropdownCandidates(label))
                && !/never been employed/i.test(getWorkdayFieldSelectedText(container) || '')) {
                const ok = await fillWorkdayGovernmentEmploymentField(container, label);
                debugLog(`${WD} filled government employment`, label.slice(0, 80), 'ok=', ok);
            }
            continue;
        }
        if (isWorkdayClinicalSettingsQuestion(label)) {
            if (!isWorkdayClinicalSettingsFilled(container, profile)) {
                await fillWorkdayClinicalSettingsField(container, label, profile);
            }
            continue;
        }

        if (isWorkdayShiftAvailabilityQuestion(label)) {
            if (!isWorkdayShiftAvailabilityFilled(container)) {
                await fillWorkdayShiftAvailabilityField(container, label);
            }
            continue;
        }
        if (isWorkdayAgeBand18SelectQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdayAgeBand18Candidates())) {
                await fillWorkdayAgeBand18Field(container, label);
            }
            continue;
        }
        if (isWorkdayTotalHoursPerWeekField(label)) {
            await fillWorkdayTotalHoursPerWeekField(container, label);
            continue;
        }

        if (isWorkdayEmploymentTypeQuestion(label)) {
            if (!(isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayEmploymentTypeCandidates())
                || isWorkdaySingleSelectFilled(container, getWorkdayEmploymentTypeCandidates()))) {
                await fillWorkdayEmploymentTypeField(container, label);
            }
            continue;
        }
        if (isWorkdayBestContactTimeQuestion(label)) {
            if (!isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayBestContactTimeCandidates())) {
                await fillWorkdayBestContactTimeField(container, label);
            }
            continue;
        }
        if (isWorkdayNaIfNoTextField(label)) {
            await fillWorkdayNaIfNoTextField(container, label, profile);
            continue;
        }
        if (isWorkdayPassportVisaTypeTextField(label)) {
            await fillWorkdayPassportVisaTypeTextField(container, label, profile);
            continue;
        }

        if (isWorkdayAlwaysNoQuestion(label, container)) {
            if (!isWorkdayYesNoFieldLockedAndFilled(container, label)) {
                await fillWorkdayAlwaysNoField(container, label);
            }
            continue;
        }

        if (/by selecting.*i accept|data protection policy|consent to your data being stored/i.test(labelLower)) {
            const acceptCandidates = ['I accept', 'I Accept', 'Accept', 'Yes'];
            if (!isWorkdaySingleSelectFilled(container, acceptCandidates)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                if (ctrl) {
                    const ok = await fillWorkdaySingleSelectDropdown(ctrl, acceptCandidates, labelLower.slice(0, 80));
                    debugLog(`${WD} filled data protection accept`, label.slice(0, 70), 'ok=', ok);
                }
            }
            continue;
        }

        if (isWorkdaySmsConsentDropdownField(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySmsConsentCandidates())
                && !isWorkdayYesNoFilled(container, 'Yes')) {
                await fillWorkdaySmsConsentDropdown(container, label);
            }
            continue;
        }

        if (/preferred location/i.test(labelLower)) {
            if (!isMultiSelectFilled(container)) {
                const locAnswer = getProfileFieldValue(profile, label);
                const candidates = [locAnswer, 'Colorado', 'Louisville, CO', 'Louisville', 'CO'].filter(Boolean);
                const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                if (control) {
                    const filled = await fillWorkdayScrollMultiSelect(control, candidates, {
                        logTag: 'preferred-location',
                        fieldLabel: label,
                        isFilledFn: (r) => isMultiSelectFilled(r),
                    }) || await fillWorkdaySingleSelectDropdown(control, candidates, labelLower);
                    debugLog(`${WD} filled preferred location`, label.slice(0, 50), candidates[0], 'ok=', filled);
                }
            }
            continue;
        }

        if (/select all that apply/i.test(labelLower)) {
            const noneCandidates = [
                'None of the above',
                'None apply',
                'Not applicable',
                'I have not served',
                'I have not',
                'None',
                'N/A',
            ];
            const availabilityCandidates = [
                'Any',
                'Any time',
                'Anytime',
                'Open availability',
                'All shifts',
                'Weekdays',
                'Weekends',
                'Mornings',
                'Afternoons',
                'Evenings',
                'Days',
                'Nights',
                'Flexible',
            ];
            if (/availability|available to work|indicate your availability|what days|which days|shifts?/i.test(labelLower)) {
                if (!(isWorkdayMultiOptionAvailabilityFilled(container, availabilityCandidates)
                    || isDisclosureChoiceFilled(container, availabilityCandidates)
                    || isWorkdayShiftAvailabilityFilled(container))) {
                    const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                    const filled = await fillWorkdayShiftAvailabilityField(container, label)
                        || await fillWorkdayDisclosureChoiceGroup(container, availabilityCandidates)
                        || await fillWorkdayExclusiveCheckboxGroup(container, availabilityCandidates, { label })
                        || (control && await fillWorkdayScrollMultiSelect(control, availabilityCandidates, {
                            logTag: 'availability-select-all',
                            fieldLabel: label,
                            isFilledFn: (r) => isWorkdayShiftAvailabilityFilled(r || container)
                                || isMultiSelectFilled(r || container),
                        }));
                    debugLog(`${WD} filled availability select-all`, label.slice(0, 60), 'ok=', filled);
                }
                continue;
            }
            if (!isDisclosureChoiceFilled(container, noneCandidates)) {
                const filled = await fillWorkdayExclusiveCheckboxGroup(container, noneCandidates, { label });
                debugLog(`${WD} filled select-all-that-apply none`, label.slice(0, 60), 'ok=', filled);
            }
            continue;
        }

        if (shouldStreamWorkdayQuestionField(label, container)) {
            continue;
        }
        if (isNonDialysisHealthcareField(label)) {
            await fillWorkdayNonDialysisHealthcareField(container, profile, label);
            continue;
        }
        const preview = (container.innerText || '').toLowerCase();
        const value = getProfileFieldValue(profile, label);

        if (isWorkdayAvailabilityDateLabel(labelLower)) {
            const control = getContainerControl(container);
            const dateValue = getProfileFieldValue(profile, label);
            const fieldPreview = (container.innerText || '').toLowerCase();
            if (!control || !dateValue) continue;
            if (/invalid date|error:/i.test(fieldPreview)) {
                for (const inp of container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"])')) {
                    setNativeValue(inp, '');
                    inp.dispatchEvent(new Event('input', { bubbles: true }));
                    inp.dispatchEvent(new Event('change', { bubbles: true }));
                }
                await wait(300);
            } else if (isDateContainerFilled(container, dateValue)) {
                continue;
            }
            debugLog(`${WD} filling availability date`, dateValue, 'preview=', fieldPreview.slice(0, 60));
            const filled = await fillWorkdayMaskedDate(container, control, dateValue, fieldPreview);
            debugLog(`${WD} filled availability date`, dateValue, 'ok=', filled);
            await wait(400);
            continue;
        }

        if (isWorkdayGenderIdentityField(label) || isWorkdayDisclosureGenderField(labelLower)) {
            // Never fill locally — profile has no gender; always resolved via the AI stream in
            // fillWorkdayFields (see chrome-extension.mdc "Gender / sex disclosure fields").
            continue;
        }

        if (isWorkdayVeteranFieldLabel(label)) {
            if (!isWorkdayVeteranFilled(container)) {
                await fillWorkdayVeteranField(container, label, profile);
            }
            continue;
        }

        if (/please indicate your veteran|select the veteran status|protected veteran/i.test(labelLower)
            && !isWorkdayPrivacyConsentDropdownField(label, container)
            && !/please read before signing|equal employment opportunities/i.test(labelLower)) {
            if (!isWorkdayVeteranFilled(container)) {
                await fillWorkdayVeteranField(container, label, profile);
            }
            continue;
        }

        if (/race\/ethnicity|what is your race|\brace\b|select the race|select your race|please select your race|most accurately describes how you identify|please indicate your ethnicity|indicate your ethnicity|select the ethnicity|\bethnicity\b/i.test(labelLower) && !isHispanicLatinoOnlyFieldLabel(labelLower)) {
            if (!isWorkdayEeoCheckboxGroupFilled(container, label, profile)) {
                await fillWorkdayEthnicityDisclosureField(container, label, profile);
            }
            continue;
        }

        if (/hispanic or latino|are you hispanic|hispanic.*latino.*descent|latino descent/i.test(labelLower)) {
            if (onQuestionsStep) continue;
            if (isWorkdayYesNoFilled(container, 'No')) continue;
            await fillWorkdayYesNoField(container, 'No');
            continue;
        }

        if (/pay rate type|desired pay rate/i.test(labelLower)) {
            if (isWorkdaySingleSelectFilled(container, ['Annual Salary', 'annual salary', 'Annual'])) continue;
            const control = getContainerControl(container);
            if (control) {
                await fillWorkdaySingleSelectDropdown(control, ['Annual Salary', 'annual salary', 'Annual', 'Yearly'], labelLower);
            }
            continue;
        }

        if (isCompensationFieldLabel(labelLower)) {
            const control = getContainerControl(container);
            if (isCompensationFieldAcceptable(container, label, control)) continue;
            await fillWorkdayCompensationField(container, profile, label);
            continue;
        }

        if (isWorkdaySponsorshipRequiredQuestion(label)) {
            const profileAnswer = getProfileDerivedYesNoAnswer(profile, label);
            if (!/^(yes|no)$/i.test(String(profileAnswer))) continue;
            if (isWorkdayYesNoFieldLockedAndFilled(container, label)) {
                debugLog(`${WD} skip locked sponsorship field`, label.slice(0, 60));
                continue;
            }
            if (isWorkdayYesNoFilled(container, profileAnswer)) {
                markWorkdayLockedYesNoFilled(label);
                continue;
            }
            const control = getContainerControl(container);
            const filled = await fillWorkdayYesNoField(container, profileAnswer)
                || (control && await fillWorkdaySingleSelectDropdown(control, [profileAnswer, profileAnswer.toLowerCase()], labelLower));
            if (filled) {
                debugLog(`${WD} filled sponsorship from profile`, label.slice(0, 60), profileAnswer);
                markWorkdayLockedYesNoFilled(label);
            }
            continue;
        }

        if (isWorkAuthorizedWithoutSponsorshipQuestion(label)) {
            const profileAnswer = getProfileDerivedYesNoAnswer(profile, label);
            if (!/^(yes|no)$/i.test(String(profileAnswer))) continue;
            if (!isWorkdayYesNoFilled(container, profileAnswer)) {
                const control = getContainerControl(container);
                const filled = await fillWorkdayYesNoField(container, profileAnswer)
                    || (control && await fillWorkdaySingleSelectDropdown(control, [profileAnswer, profileAnswer.toLowerCase()], labelLower));
                if (filled) debugLog(`${WD} filled work authorization from profile`, label.slice(0, 60), profileAnswer);
            }
            continue;
        }

        if (/require.*sponsorship|visa sponsorship|need sponsorship|future require sponsorship/i.test(labelLower)) {
            continue;
        }

        if (/under 18|below 18|less than 18/i.test(labelLower)) {
            continue;
        }

        if (/at least age 18|18 or older|at least 18|legal age/i.test(labelLower)) {
            continue;
        }

        if (isWorkdayFormerEmployerQuestion(label)) {
            if (!isWorkdayFormerEmployerFilled(container, label) && !isWorkdayYesNoFilled(container, 'No')) {
                await fillWorkdayFormerEmployerField(container, label);
            }
            continue;
        }

        if (isWorkdayFormerEmployerAffiliateTextField(label)) {
            await fillWorkdayFormerEmployerAffiliateTextField(container, label);
            continue;
        }
        if (isWorkdayFormerEmployerTextFollowUp(label, container)) {
            await fillWorkdayFormerEmployerTextFollowUp(container, label);
            continue;
        }

        if (isWorkdayRelativeConflictTextField(label, container)) {
            await fillWorkdayRelativeConflictTextField(container, label);
            continue;
        }

        if (isWorkdayLicenseFollowUpTextField(label, container)) {
            await fillWorkdayLicenseFollowUpTextField(container, label);
            continue;
        }

        if (isWorkdayRelativeEmployerEntityQuestion(label)) {
            if (!/do not have any relatives|no relatives/i.test(getWorkdayFieldSelectedText(container) || '')
                && !isWorkdaySingleSelectFilled(container, getWorkdayRelativeEmployerEntityCandidates(label))) {
                await fillWorkdayRelativeEmployerEntityField(container, label);
            }
            continue;
        }
        if (/family member|relative.*(?:work|employ)/i.test(labelLower)) {
            // Free-text follow-ups only — entity dropdowns handled above.
            if (isWorkdayRelativeConflictTextField(label, container)) {
                await fillWorkdayRelativeConflictTextField(container, label);
            }
            continue;
        }

        if (/percentage.*travel|travel.*percentage|travel.*working time|oconus/i.test(labelLower)) {
            if (isTravelFilled(container)) continue;
            const travelCtrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
            const bandCands = /oconus/i.test(labelLower)
                ? ['None', 'Up to 25%', 'up to 25%', '0%', '20%']
                : [
                    'up to 25%', 'Up to 25%', 'up to 50%', 'Up to 50%',
                    value || '20%', '20%', '25%', '0%', 'None', 'Less than 25%',
                ];
            let filled = false;
            // Dropdown first (hrone.wd1 / guidehouse.wd1) — radio-only path left free-text "20%" empty.
            if (travelCtrl && (travelCtrl.getAttribute?.('role') === 'combobox'
                || travelCtrl.getAttribute?.('aria-haspopup')
                || container.querySelector('input[role="combobox"], [data-automation-id="promptSelectionLabel"], button[aria-haspopup="listbox"]'))) {
                clearWorkdaySingleSelectMissKey(label);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                filled = await fillWorkdaySingleSelectDropdown(travelCtrl, bandCands, labelLower);
                debugLog(`${WD} filled travel dropdown`, label.slice(0, 50), 'ok=', filled);
            }
            if (!filled) {
                for (const travelValue of bandCands) {
                    filled = await fillWorkdayRadioGroup(container, travelValue);
                    if (filled) {
                        debugLog(`${WD} filled travel`, travelValue, 'ok=', filled);
                        break;
                    }
                }
            }
            continue;
        }

        if (isWorkdayClearanceFieldLabel(label)) {
            await fillWorkdayClearanceField(container, label);
            continue;
        }

        if (/microsoft excel|hris|human resource information system|google workspace|microsoft office|office 365|my proficiency with|proficiency with/i.test(labelLower)) {
            const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            const profValue = getProfileFieldValue(profile, label) || 'Advanced';
            if (control && profValue) {
                clearWorkdaySingleSelectMissKey(label);
                const candidates = [profValue, 'Advanced', 'Expert', 'Proficient', 'Intermediate', 'High', 'Yes', 'No'];
                const filled = await fillWorkdaySingleSelectDropdown(control, candidates, labelLower)
                    || await fillWorkdayYesNoField(container, profValue);
                debugLog(`${WD} filled skill proficiency`, label.slice(0, 60), profValue, 'ok=', filled);
            }
            continue;
        }

        if (/non-compete|non-solicit|non-disclosure/i.test(labelLower)) {
            const textarea = container.querySelector('textarea')
                || (getContainerControl(container)?.tagName === 'TEXTAREA' ? getContainerControl(container) : null);
            const text = getProfileFieldValue(profile, label);
            if (textarea && text && !(textarea.value || '').trim()) {
                workdayScrollToTarget(textarea, 120);
                await workdayTypeElement(textarea, text);
                debugLog(`${WD} filled non-compete textarea`, text.slice(0, 80));
            } else if (!textarea) {
                // Non-compete is a Yes/No dropdown — default to "No"
                const control = getContainerControl(container);
                if (control && !isWorkdayYesNoFilled(container, 'No')) {
                    const filled = await fillWorkdayYesNoField(container, 'No')
                        || await fillWorkdaySingleSelectDropdown(control, ['No'], labelLower);
                    if (filled) debugLog(`${WD} filled non-compete dropdown default No`, label.slice(0, 60));
                }
            }
            continue;
        }

        if (value === null || value === undefined || value === '') continue;
        if (/^(yes|no)$/i.test(String(value))) {
            if (!shouldUseBareYesNoForContainer(container, value, label)) {
                debugLog(`${WD} skip bare yes/no on multi-checkbox`, label.slice(0, 60), value);
                continue;
            }
            if (isWorkdayYesNoFilled(container, value)) continue;
            const filled = await fillWorkdayYesNoField(container, value);
            if (filled) debugLog(`${WD} filled yes/no field`, label.slice(0, 60), value);
            continue;
        }

        const radios = [...container.querySelectorAll('input[type="radio"]')];
        if (radios.length) {
            if (container.querySelector('input[type="radio"]:checked')) continue;
            const target = String(value).toLowerCase();
            for (const radio of radios) {
                const optLabel = (document.querySelector(`label[for="${radio.id}"]`)?.innerText
                    || radio.closest('label')?.innerText || '').trim().toLowerCase();
                if (optLabel === target || optLabel.startsWith(`${target} `)) {
                    if (!radio.checked) await workdayClick(radio);
                    debugLog(`${WD} filled radio`, label.slice(0, 60), optLabel);
                    break;
                }
            }
            continue;
        }

        // Text input or textarea fields
        const control = getContainerControl(container);
        const numCtrl = control?.type === 'number' ? control : container.querySelector('input[type="number"]');
        const textCtrl = container.querySelector('textarea') || (() => {
            const c = control;
            return (c && (c.tagName === 'TEXTAREA' || (c.tagName === 'INPUT' && (c.type === 'text' || c.type === '')))) ? c : null;
        })();
        if (numCtrl && isCompensationFieldLabel(labelLower)) {
            const numVal = getWorkdayNumericSalaryValue(profile, label, numCtrl);
            const preview = (container.innerText || '').toLowerCase();
            if (!(numCtrl.value || '').trim() || /too large|number entered is too large|required and must have a value/i.test(preview)) {
                if (/too large/i.test(preview)) {
                    wdSetInputValue(numCtrl, '');
                    await wait(200);
                }
                workdayScrollToTarget(numCtrl, 120);
                await commitWorkdayNumericInput(numCtrl, numVal, label);
                debugLog(`${WD} filled salary number input`, label.slice(0, 60), numVal);
            }
            continue;
        }
        if (textCtrl && isCompensationFieldLabel(labelLower) && shouldUseNumericCompensation(labelLower, textCtrl)) {
            const numVal = getWorkdayNumericSalaryValue(profile, label, textCtrl);
            const current = (textCtrl.value || '').replace(/\D/g, '');
            const expected = numVal.replace(/\D/g, '');
            const preview = (container.innerText || '').toLowerCase();
            if (!current || current !== expected || /required and must have a value|too large/i.test(preview)) {
                if (/too large/i.test(preview)) {
                    wdSetInputValue(textCtrl, '');
                    await wait(200);
                }
                await commitWorkdayNumericInput(textCtrl, numVal, label);
                debugLog(`${WD} filled compensation text input`, label.slice(0, 60), numVal);
            }
            continue;
        }
        if (textCtrl && !(textCtrl.value || '').trim()) {
            let textValue = value;
            if ((textValue === null || textValue === undefined || textValue === '')
                && /if other please specify|other.*specify/i.test(labelLower)) {
                textValue = getWorkdayOtherSpecifyValue(profile, container);
            }
            if ((textValue === null || textValue === undefined || textValue === '')
                && isWorkdayAdditionalDetailsTextField(label)) {
                textValue = getWorkdayAdditionalDetailsValue(profile, container);
            }
            if (textValue === null || textValue === undefined || textValue === '') continue;
            textValue = normalizeWorkdaySalaryInputValue(textValue, profile, label, textCtrl);
            workdayScrollToTarget(textCtrl, 120);
            await workdayTypeElement(textCtrl, String(textValue));
            debugLog(`${WD} filled question text input`, label.slice(0, 60), String(textValue).slice(0, 40));
            continue;
        }

        if (/select one|0 items selected/i.test(container.innerText || '')) {
            const control = getContainerControl(container);
            if (!control) continue;
            if (isWorkdayPrivacyConsentDropdownField(label, container)) {
                if (!isWorkdayAgreeDisagreeConsentFilled(container)) {
                    await fillWorkdayPrivacyConsentDropdown(container, label);
                }
                continue;
            }
            if (isWorkdaySkillAbilityQuestion(label)) {
                if (!isWorkdaySingleSelectFilled(container, getWorkdaySkillAbilityCandidates())) {
                    await fillWorkdaySkillAbilityField(container, label);
                }
                continue;
            }
            if (isWorkdayAlwaysNoQuestion(label)) {
                await fillWorkdayAlwaysNoField(container, label);
                continue;
            }
            if (isWorkdayYesNoFieldLockedAndFilled(container, label)) {
                debugLog(`${WD} skip question dropdown locked`, label.slice(0, 60));
                continue;
            }
            if (isWorkdaySingleSelectFilled(container, [value]) || isWorkdayYesNoFilled(container, value)) {
                if (isWorkdayLockedYesNoField(label)) markWorkdayLockedYesNoFilled(label);
                continue;
            }

            if (isWorkdayPlaceOfResidenceField(label)) {
                if (!isWorkdaySingleSelectFilled(container, getWorkdayPlaceOfResidenceCandidates(profile))) {
                    await fillWorkdayPlaceOfResidenceField(container, label, profile);
                }
                continue;
            }
            if (isWorkdayVisaHoursPerWeekField(label)) {
                await fillWorkdayVisaHoursPerWeekField(container, label);
                continue;
            }
            if (isWorkdayVisaExpiryDateLabel(label)) {
                await fillWorkdayVisaExpiryDateField(container, label);
                continue;
            }
            if (isCountryOrCitizenshipFieldLabel(label)) {
                // "0 items selected" on a plural/"additional" nationality-style multi-select (e.g.
                // "Additional Nationalities") is a legitimate, already-answered empty state when the
                // profile has no second nationality to report — unlike a single-select stuck on "Select
                // One", an unrequired multi-select left at zero items is not itself invalid. Without this
                // check the code force-filled it with the SAME country as Primary Nationality on every
                // profile (observed on pwc.wd3: multi-select "Additional Nationalities" combobox never
                // actually matched "United States of America" against its own typeahead filter — same
                // country already set as Primary Nationality moments earlier — burning 10+ opens via
                // fillWorkdayCountryDropdown's popup-attempt retry loop before the whole step timed out).
                // Not tenant-specific: any tenant with an optional "additional/other nationalities" field
                // hits this whenever the applicant has only one nationality.
                if (!isContainerRequired(container) && /0 items selected/i.test(container.innerText || '')) {
                    debugLog(`${WD} skip optional empty multi-select country`, label.slice(0, 60));
                    continue;
                }
                if (!isCountryFilled(container, profile)) {
                    debugLog(`${WD} filling citizenship/country in questions`, label.slice(0, 60));
                    await fillWorkdayCountryDropdown(control, profile);
                }
                continue;
            }

            if (isWorkdayEeoDisclosureField(label)) {
                markDisclosureStreamFallback(label);
                continue;
            }

            // Hard per-field limit: if this dropdown was already opened 2+ times, skip entirely
            const openKey = labelLower.slice(0, 80);
            if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
                debugLog(`${WD} questions: skip field already opened ${wdDropdownOpenCounts[openKey]}x`, label.slice(0, 60));
                continue;
            }

            // Track attempt count (persists across step retries, reset only on step change)
            window.__wdQuestionsAttempted = window.__wdQuestionsAttempted || {};
            const qKey = label.slice(0, 80);
            if ((window.__wdQuestionsAttempted[qKey] || 0) >= 2) {
                continue; // Already failed twice — skip
            }
            window.__wdQuestionsAttempted[qKey] = (window.__wdQuestionsAttempted[qKey] || 0) + 1;

            const values = Array.isArray(value) ? value : [value];
            // Try with the provided value first (one dropdown open)
            let filled = await fillWorkdaySingleSelectDropdown(control, values, labelLower)
                || await fillWorkdayDropdown(control, value);
            if (filled) {
                debugLog(`${WD} filled question dropdown`, label.slice(0, 60), value);
            } else if (isWorkdayGpaQuestion(label)) {
                clearWorkdaySingleSelectMissKey(label);
                filled = await fillWorkdayGpaField(container, label);
                if (filled) debugLog(`${WD} filled question gpa`, label.slice(0, 60));
            } else {
                // Value didn't match — apply smart default WITHOUT opening popup to inspect options.
                let smartCandidates;
                if (isCompensationFieldLabel(labelLower)) {
                    smartCandidates = [formatWorkdaySalaryRange(getProfileSalaryAmount(profile))];
                } else if (isWorkdayGpaQuestion(labelLower)) {
                    smartCandidates = getWorkdayGpaCandidates();
                } else {
                    const smartDefault = getWorkdayYesNoSmartDefault(labelLower);
                    smartCandidates = smartDefault === 'Yes'
                        ? ['Yes', 'yes']
                        : ['No', 'no', 'Not Applicable', 'N/A', 'None'];
                }
                debugLog(`${WD} question no match, smart default`, label.slice(0, 60), '->', smartCandidates[0]);
                filled = await fillWorkdaySingleSelectDropdown(control, smartCandidates, labelLower);
                if (filled) {
                    debugLog(`${WD} filled question smart default`, label.slice(0, 60), smartCandidates[0]);
                    if (isWorkdayLockedYesNoField(label)) markWorkdayLockedYesNoFilled(label);
                }
            }
        }
    }
}

async function fillExperiencePageExtras(profile) {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const value = getProfileFieldValue(profile, label);
        if (value === null || value === undefined || value === '') continue;
        const element = getContainerControl(container);
        if (!element || element.type === 'file') continue;
        if (/linkedin/i.test(label)) {
            const linkedIn = normalizeLinkedInUrl(value);
            workdayScrollToTarget(element, 120);
            setNativeValue(element, linkedIn);
            element.dispatchEvent(new Event('change', { bubbles: true }));
            debugLog(`${WD} filled linkedin url`, linkedIn);
        } else if (element.value && element.type !== 'checkbox') {
            continue;
        }
    }
    // Skills only when required (section or field marked with *)
    await fillSkillsField(profile);
    await fillLanguagesSection(profile);
}

function logEmptyRequiredFields() {
    const profile = window.__wdApplyData?.profile;
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        const element = getContainerControl(container);
        if (!element) continue;
        const required = element.required
            || labelText.includes('*')
            || container.querySelector('[aria-required="true"]');
        if (!required) continue;
        if (!shouldCountEmptyRequiredContainer(container)) continue;

        let empty = false;
        if (/percentage.*travel|travel.*percentage|travel.*working time/i.test(labelText)) {
            empty = !isTravelFilled(container);
        } else if (/non-compete|non-solicit|non-disclosure/i.test(labelText)) {
            const ta = container.querySelector('textarea');
            empty = ta ? !(ta.value || '').trim() : !isWorkdaySingleSelectFilled(container, ['No']);
        } else if (isWorkdayFormerEmployerQuestion(labelText)) {
            // Before element.type===radio — Yes/No radios often have value="true" on the Yes input
            empty = !isWorkdayFormerEmployerFilled(container, labelText) && !isWorkdayYesNoFilled(container, 'No');
        } else if (isWorkdayClinicalSettingsQuestion(labelText)) {
            empty = !isWorkdayClinicalSettingsFilled(container, profile);
        } else if (isWorkdayShiftAvailabilityQuestion(labelText)) {
            empty = !isWorkdayShiftAvailabilityFilled(container);
        } else if (isWorkdayEmploymentTypeQuestion(labelText)) {
            empty = !(isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayEmploymentTypeCandidates())
                || isWorkdaySingleSelectFilled(container, getWorkdayEmploymentTypeCandidates()));
        } else if (isWorkdayBestContactTimeQuestion(labelText)) {
            empty = !isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayBestContactTimeCandidates());
        } else if (isWorkdayNaIfNoTextField(labelText)) {
            const ctrl = getContainerControl(container);
            empty = !(ctrl?.value || '').trim();
        } else if (isWorkdayYesNoCheckboxGroup(container)) {
            empty = isWorkdayYesNoCheckboxConflict(container)
                || (!isWorkdayYesNoFilled(container, 'Yes') && !isWorkdayYesNoFilled(container, 'No'));
        } else if (element.type === 'radio') {
            empty = !container.querySelector('input[type="radio"]:checked');
        } else if (/how did you hear/i.test(labelText)) {
            empty = !hasExplicitHearSelection(container);
        } else if (isCountryFieldLabel(labelText)) {
            empty = profile ? !isCountryFilled(container, profile) : !isWorkdaySingleSelectFilled(container, ['United States']);
        } else if (/phone code/i.test(labelText)) {
            empty = profile ? !isPhoneCodeFilledForProfile(container, profile) : !isPhoneCodeFilled(container);
        } else if (isWorkdayStateFieldLabel(labelText)) {
            empty = !isWorkdayStateFieldFilled(container);
        } else if (isCountryOrCitizenshipFieldLabel(labelText)) {
            empty = !isCountryFilled(container, profile);
        } else if (isWorkdayFieldOfStudyLabel(labelText)) {
            empty = !isFieldOfStudyFilled(container);
        } else if (element.type === 'radio' || container.querySelector('input[type="radio"]')) {
            empty = !container.querySelector('input[type="radio"]:checked')
                && !isWorkdayYesNoFilled(container, 'Yes')
                && !isWorkdayYesNoFilled(container, 'No');
        } else if (isWorkdayMultiSelectContainerFilled(container, labelText.toLowerCase())) {
            empty = false;
        } else if (element.tagName === 'BUTTON' || element.getAttribute('role') === 'combobox') {
            const selected = (container.innerText || '').includes('Select One') || (container.innerText || '').includes('Required');
            empty = selected;
        } else {
            empty = !(element.value || '').trim();
        }
        if (empty) debugLog(`${WD} empty required`, labelText);
    }
}

function logWorkdayValidationErrors() {
    dumpWorkdayErrorsFoundBlock();
    const errors = [...document.querySelectorAll('[data-automation-id*="errorText"], [data-automation-id*="validationError"], [role="alert"]')];
    errors.map(el => (el.innerText || el.textContent || '').trim()).filter(Boolean).forEach(text => {
        if (/successfully uploaded|uploaded successfully|file uploaded/i.test(text)) return;
        debugLog(`${WD} validation error`, text);
    });
    const invalid = [...document.querySelectorAll('input:invalid, textarea:invalid')];
    invalid.forEach(el => {
        const label = el.closest('[data-automation-id*="formField"]')?.innerText?.split('\n')[0]?.trim() || el.name || el.id;
        debugLog(`${WD} invalid field`, label, el.validationMessage);
    });
}

function dumpWorkdayErrorsFoundBlock(silent = false) {
    const candidates = [
        ...document.querySelectorAll('[data-automation-id*="errorBanner"], [data-automation-id*="validationErrors"], [data-automation-id*="errorPanel"]'),
        ...document.querySelectorAll('[role="alert"], [role="region"]'),
        ...document.querySelectorAll('div, section, aside'),
    ];
    let block = null;
    for (const el of candidates) {
        if (!isVisibleElement(el)) continue;
        const text = (el.innerText || '').replace(/\r/g, '');
        if (/errors found/i.test(text) && /error\s*-\s*\w/i.test(text)) {
            if (!block || text.length < (block.innerText || '').length) block = el;
        }
    }
    if (!block) {
        const body = document.body?.innerText || '';
        const idx = body.search(/errors found/i);
        if (idx >= 0) {
            const chunk = body.slice(Math.max(0, idx - 20), idx + 3500);
            if (!silent) debugLog(`${WD} errors found dump (body)`, chunk);
            return chunk;
        }
        return '';
    }
    const text = (block.innerText || '').replace(/\r/g, '');
    if (!silent) {
        debugLog(`${WD} errors found dump start`, 'chars=', text.length);
        for (let i = 0; i < text.length; i += 3500) {
            debugLog(`${WD} errors found dump`, text.slice(i, i + 3500));
        }
        debugLog(`${WD} errors found dump end`);
    }
    return text;
}

// Parses a Workday "Errors Found" block (format: "Error-<Label>\n<message>" repeated) into a
// lowercase set of field-label tokens, e.g. {"name", "date"}. Used to force a re-fill of a field
// on retry even when its raw DOM control.value already looks populated — Workday's client-side
// validation reads its own React-controlled state, which can diverge from the DOM .value attribute
// after a synthetic fill (the field visually/DOM-wise looks filled but Next keeps rejecting it as
// blank). Relying only on control.value for the "already filled, skip" check then gets these fields
// stuck forever across every retry (MAX_STEP_TRIES exhausted -> "Workday step stuck: ..."), since the
// retry logic never realizes the previous fill didn't actually commit. Silent — does not re-log the
// block (the caller step's own logWorkdayValidationErrors() already dumps it for debugging).
function getWorkdayErrorFieldLabelTokens() {
    const text = dumpWorkdayErrorsFoundBlock(true);
    const tokens = new Set();
    if (!text || !/errors found/i.test(text)) return tokens;
    const re = /Error-([A-Za-z0-9 /&'-]+?)(?:\r?\n|$)/g;
    let m;
    while ((m = re.exec(text))) {
        const label = m[1].trim().toLowerCase();
        if (label) tokens.add(label);
    }
    return tokens;
}

async function fixCountryForJobLocation(profile) {
    return fixCountryForProfile(getProfileForJobLocation(profile));
}

// Profile country names (application/src/main/resources/dictionaries/countries.json)
// -> Workday myworkdayjobs dropdown labels.
// Workday list extracted via debugLog "country dump" on AdventHealth wd12 (250 options).
// Profiles may store informal names (e.g. "USA") — normalize before Workday lookup.
const PROFILE_COUNTRY_SYNONYMS = {
    usa: 'United States',
    us: 'United States',
    'u.s.': 'United States',
    'u.s.a.': 'United States',
    'united states of america': 'United States',
    uk: 'United Kingdom',
    'u.k.': 'United Kingdom',
    'great britain': 'United Kingdom',
    england: 'United Kingdom',
    uae: 'United Arab Emirates',
    'u.a.e.': 'United Arab Emirates',
};

function normalizeProfileCountryName(name) {
    const raw = String(name || '').trim();
    if (!raw) return raw;
    const key = raw.toLowerCase().replace(/\s+/g, ' ').trim();
    if (PROFILE_COUNTRY_SYNONYMS[key]) return PROFILE_COUNTRY_SYNONYMS[key];
    const keyNoDots = key.replace(/\./g, '');
    if (PROFILE_COUNTRY_SYNONYMS[keyNoDots]) return PROFILE_COUNTRY_SYNONYMS[keyNoDots];
    return raw;
}

const PROFILE_TO_WORKDAY_COUNTRY = {
    'Antigua And Barbuda': 'Antigua and Barbuda',
    'Bonaire, Sint Eustatius and Saba': 'Bonaire, Sint Eustatius, and Saba',
    'Cape Verde': 'Cabo Verde',
    "Cote D'Ivoire (Ivory Coast)": "Côte d'Ivoire",
    'Czech Republic': 'Czechia',
    'Democratic Republic of the Congo': 'Congo, Democratic Republic of the',
    'East Timor': 'Timor-Leste',
    'Fiji Islands': 'Fiji',
    'Gambia The': 'Gambia',
    'Hong Kong S.A.R.': 'Hong Kong',
    'Micronesia': 'Micronesia, Federated States of',
    'North Korea': "Korea, Democratic People's Republic of",
    'Papua new Guinea': 'Papua New Guinea',
    'Russia': 'Russian Federation',
    'Saint Kitts And Nevis': 'Saint Kitts and Nevis',
    'Saint Vincent And The Grenadines': 'Saint Vincent and the Grenadines',
    'South Korea': 'Korea, Republic of',
    'Swaziland': 'Eswatini',
    'The Bahamas': 'Bahamas',
    'Trinidad And Tobago': 'Trinidad and Tobago',
    'Turkey': 'Türkiye',
    'United States': 'United States of America',
    'Virgin Islands (US)': 'U. S. Virgin Islands',
};

function getProfileCountryName(profile) {
    const residency = profile?.residency || profile?.general?.residency || {};
    const raw = residency.country || profile?.residencyCountry || 'United States';
    return normalizeProfileCountryName(raw);
}

function getWorkdayCountryName(profile) {
    const profileName = getProfileCountryName(profile);
    return PROFILE_TO_WORKDAY_COUNTRY[profileName] || profileName;
}

function getExpectedCountryCandidates(profile) {
    profile = getProfileForJobLocation(profile);
    const profileName = getProfileCountryName(profile);
    const workdayName = getWorkdayCountryName(profile);
    const candidates = [workdayName, profileName];
    if (jobLocationExpectsJapanResidency()) {
        candidates.push('Japan', 'JP');
    }
    if (profileExpectsUS(profile)) {
        // Full names first — never lead with "US"/"USA" for substring matchers (australia contains "us").
        candidates.push(
            'United States of America',
            'United States',
            'USA',
            'U.S.A.',
            'U.S.',
            'US',
        );
    }
    if (/united kingdom/i.test(profileName)) {
        candidates.push('United Kingdom', 'UK', 'Great Britain', 'England');
    }
    if (/united arab emirates/i.test(profileName)) {
        candidates.push('United Arab Emirates', 'UAE', 'U.A.E.');
    }
    if (jobLocationExpectsEgyptResidency()) {
        const base = [...candidates];
        for (const name of base) {
            if (name) candidates.push(`${name} (Egypt)`);
        }
    }
    return [...new Set(candidates.filter(Boolean))];
}

function getExpectedPhoneCodeCandidates(profile) {
    profile = getProfileForJobLocation(profile);
    // India residency with a stale US phoneCountryCode must still target India (+91).
    if (profileExpectsIndia(profile)) {
        return [
            'India (+91)',
            'India (91)',
            'India (+9 1)',
            '+91',
            '91',
            'India',
        ];
    }
    if (profileExpectsUS(profile)) {
        return [
            'United States of America (+1)',
            'United States (+1)',
            'USA (+1)',
            '+1',
            'United States of America',
            'United States',
        ];
    }
    const code = profile?.phoneCountryCode || profile?.general?.phoneCountryCode || '';
    const dialDigits = getProfilePhoneDialDigits(profile);
    const country = getProfileCountryName(profile);
    const workdayCountry = getWorkdayCountryName(profile);
    const candidates = [];
    if (country && code) {
        candidates.push(`${country} (${code})`, `${country} (${dialDigits})`, country, code);
    }
    if (workdayCountry && workdayCountry !== country && code) {
        candidates.push(`${workdayCountry} (${code})`, workdayCountry);
    }
    if (dialDigits) {
        candidates.push(`(+${dialDigits})`, `+${dialDigits}`);
    }
    return [...new Set(candidates.filter(Boolean))];
}

function profileExpectsIndia(profile) {
    return /\bindia\b/i.test(String(getProfileCountryName(profile) || ''));
}

function getProfilePhoneDialDigits(profile) {
    const raw = String(profile?.phoneCountryCode || profile?.general?.phoneCountryCode || '').trim();
    const digits = raw.replace(/\D/g, '');
    // Residency country wins over a stale US (+1) phoneCountryCode (solenis.wd1: India + US digits
    // → Workday "not valid for this region" forever). Same class as UK/Japan dial sync.
    if (profileExpectsIndia(profile) && (!digits || digits === '1')) return '91';
    if (digits) return digits;
    if (profileExpectsIndia(profile)) return '91';
    return profileExpectsUS(profile) ? '1' : '';
}

/**
 * Workday phone fields use a separate Country Phone Code dropdown, so the number
 * input must be national digits only. Profiles often store dial+national together
 * (e.g. 33625555384 with +33) which fails "number length does not match".
 */
function getNationalPhoneNumberForWorkday(profile) {
    const raw = String(profile?.phone || profile?.general?.phone || '').trim();
    if (!raw) return '';
    let digits = raw.replace(/\D/g, '');
    if (!digits) return raw;
    const dial = getProfilePhoneDialDigits(profile);
    if (dial && digits.startsWith(dial) && digits.length - dial.length >= 6) {
        digits = digits.slice(dial.length);
    }
    // Trunk prefix 0 is common in national format; drop it when dial code is selected.
    if (dial && dial !== '1' && /^0\d{6,}$/.test(digits)) {
        digits = digits.replace(/^0+/, '');
    }
    return digits || raw.replace(/\D/g, '') || raw;
}

/** UK mobiles that pass common libphonenumber checks used by Workday region validation. */
const WORKDAY_SAFE_UK_MOBILE = '7911123456';
/** India mobiles: 10 digits starting with 6–9 (libphonenumber / Workday region checks). */
const WORKDAY_SAFE_INDIA_MOBILE = '9876543210';

/**
 * Candidate national numbers to try when Workday rejects "not valid for this region".
 * UK: without trunk 0 (with +44 dropdown), with 0, then a known-valid mobile fallback.
 * India: 10-digit mobiles starting 6–9 when Country Phone Code is +91 (or residency is India).
 */
function getNationalPhoneNumberCandidatesForWorkday(profile) {
    const primary = getNationalPhoneNumberForWorkday(profile);
    const out = [];
    const add = (v) => {
        const s = String(v || '').replace(/\D/g, '');
        if (!s || out.includes(s)) return;
        out.push(s);
    };
    const dial = getProfilePhoneDialDigits(profile);
    const formDial = getSelectedWorkdayPhoneDialDigits();
    const indiaDial = dial === '91' || formDial === '91' || profileExpectsIndia(profile);
    if (indiaDial) {
        // US-looking 10-digit area codes are invalid under +91 — India mobiles first.
        if (/^[6-9]\d{9}$/.test(primary)) add(primary);
        add(WORKDAY_SAFE_INDIA_MOBILE);
        add('9123456789');
        add('9812345678');
        // Keep primary last only if it wasn't already added (diagnostics / odd local formats).
        add(primary);
    } else {
        add(primary);
    }
    if (profileExpectsUK(profile) || dial === '44' || formDial === '44') {
        if (primary && !primary.startsWith('0')) add(`0${primary}`);
        if (primary && primary.startsWith('0')) add(primary.replace(/^0+/, ''));
        // Fake/random 77xx ranges often fail Workday libphonenumber — fall back to a safe mobile.
        add(WORKDAY_SAFE_UK_MOBILE);
        add(`0${WORKDAY_SAFE_UK_MOBILE}`);
    }
    return out.length ? out : (primary ? [primary] : []);
}

/** Dial digits currently shown on Country Phone Code (e.g. India (+91) → "91"). */
function getSelectedWorkdayPhoneDialDigits() {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).toLowerCase();
        if (!/phone code|country.*territory phone code/i.test(label)) continue;
        const text = `${getWorkdayFieldSelectedText(container) || ''} ${container.innerText || ''}`;
        const m = text.match(/\(\+(\d{1,4})\)|\+(\d{1,4})\b/);
        if (m) return m[1] || m[2] || '';
    }
    return '';
}

function extractDialDigitsFromPhoneText(text) {
    const paren = String(text || '').match(/\(\+(\d{1,4})\)/);
    if (paren) return paren[1];
    const plus = String(text || '').match(/(?:^|\s)\+(\d{1,4})\b/);
    return plus ? plus[1] : '';
}

function previewContainsProfileDialCode(preview, profile) {
    const dialDigits = getProfilePhoneDialDigits(profile);
    if (!dialDigits || !preview) return false;
    if (profileExpectsUS(profile) && isUSPhoneCodeTerritoryOption(preview)) return false;
    const p = normalizeWorkdayDropdownSelectedText(preview).toLowerCase();
    return new RegExp(`\\(\\+${dialDigits}\\)|\\+${dialDigits}\\b`).test(p);
}

function previewContainsProfileCountryName(preview, profile) {
    const p = normalizeWorkdayDropdownSelectedText(preview).toLowerCase();
    if (!p) return false;
    for (const name of getExpectedCountryCandidates(profile)) {
        const n = String(name || '').toLowerCase().trim();
        if (!n || n.length < 3) continue;
        if (p.includes(n)) return true;
        const stem = n.split(/[\s,()]+/).filter(w => w.length >= 4)[0];
        if (stem && p.includes(stem)) return true;
    }
    return false;
}

function getWorkdayFieldSelectedText(container) {
    if (!container) return '';
    // Button listboxes (unimelb.wd105): the closed button label is the selection.
    const listBtn = container.querySelector('button[aria-haspopup="listbox"]');
    if (listBtn) {
        const btnText = String(listBtn.innerText || '').replace(/\s+/g, ' ').trim();
        if (btnText && !/^(minimized|expanded|select one)$/i.test(btnText)) {
            return dropSelectedTextIfLeakedQuestion(normalizeWorkdayDropdownSelectedText(btnText));
        }
        const aria = String(listBtn.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        // aria-label is often "FieldLabel SelectedValue" or " Select One Required"
        if (aria && !/select one/i.test(aria)) {
            const label = getContainerLabel(container).replace(/\*/g, '').trim();
            let rest = aria;
            if (label && rest.toLowerCase().startsWith(label.toLowerCase())) {
                rest = rest.slice(label.length).replace(/^\s*\*?\s*/, '').trim();
            }
            if (rest && !/select one/i.test(rest)) {
                return dropSelectedTextIfLeakedQuestion(normalizeWorkdayDropdownSelectedText(rest));
            }
        }
    }
    const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').trim();
    const multi = (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').trim();
    const promptText = normalizeWorkdayDropdownSelectedText([selectionLabel, multi].filter(Boolean).join(' '));
    if (promptText && !/^(minimized|expanded|select one)$/i.test(promptText)) {
        return promptText;
    }
    const label = getContainerLabel(container).replace(/\*/g, '').trim();
    const raw = (container.innerText || '').replace(/\s+/g, ' ').trim();
    let text = raw;
    if (label && text.toLowerCase().startsWith(label.toLowerCase())) {
        text = text.slice(label.length).replace(/^\s*\*?\s*/, '').trim();
    }
    text = normalizeWorkdayDropdownSelectedText(text);
    if (/introduce yourself page is loaded|join our talent community/i.test(text.toLowerCase())) {
        const countryMatch = (container.innerText || '').match(/Country\s*\*?\s*([^\n*]+)/i);
        if (countryMatch) return countryMatch[1].trim();
        return promptText || '';
    }
    if (text && !/^(minimized|expanded|select one)$/i.test(text)) return dropSelectedTextIfLeakedQuestion(text);
    const lines = raw.split(/\n/).map(l => l.trim()).filter(Boolean);
    const selected = lines.filter(l => !/^select one$/i.test(l) && !/^minimized$/i.test(l) && !/^expanded$/i.test(l)
        && (!label || l.toLowerCase() !== label.toLowerCase())).slice(-2).join(' ');
    return dropSelectedTextIfLeakedQuestion(normalizeWorkdayDropdownSelectedText(selected));
}

// A "selected text" containing "?" means the label-stripping above failed to remove the field's own
// question text (e.g. getContainerLabel() not exactly matching container.innerText's prefix for a given
// tenant's DOM, or — for the lines-based fallback — the whole container rendering as a single line with
// no newline separating the question from "Select One", so the label-equality filter never excludes it)
// — the returned value is then the WHOLE unfilled question, never a real dropdown option's text (no
// genuine Workday option text ends in "?"). Returning it as the "selected value" let every downstream
// caller (isWorkdayFormerEmployerFilled/isWorkdayYesNoFilled's isWorkdayExplicitNoSelectionText check,
// textMatchesCandidate's word-boundary match for short candidates like "No", etc.) treat the field as
// already answered whenever the question's own prose happens to start with or contain "no"/"yes" as an
// ordinary English word ("...to ensure NO conflict of interest exists...") — so a genuinely empty
// required dropdown got silently skipped forever and the step stayed permanently stuck (observed on
// slihrms.wd3's Deloitte/AtkinsRéalis conflict-of-interest question). Not tenant-specific: any long
// question wording containing "no"/"yes" hits this whenever the label-strip fails for any DOM-structure
// reason, on either extraction path above.
function dropSelectedTextIfLeakedQuestion(text) {
    return text && text.includes('?') ? '' : text;
}

function normalizeWorkdayDropdownSelectedText(text) {
    return String(text || '')
        .replace(/\s+/g, ' ')
        .replace(/^minimized\s+/i, '')
        .replace(/^expanded\s+/i, '')
        .trim();
}

function isCountryFieldLabel(label) {
    const l = String(label || '').toLowerCase();
    if (/phone/i.test(l) || /\bcode\b/i.test(l)) return false;
    // Place-of-residence is handled by fillWorkdayPlaceOfResidenceField (not country citizenship flow).
    if (isWorkdayPlaceOfResidenceField(label)) return false;
    if (l.length > 50) return false;
    // Yes/no questions that mention "country" are not address-country dropdowns
    if (/\?/.test(l) || /are you|do you|also a citizen|citizen of another|another country|dual citizen/i.test(l)) return false;
    if (isNationalityCountryFieldLabel(label)) return true;
    return /\bcountry\b/i.test(l);
}

/** "Please confirm your current location / place of residence" (unimelb.wd105) — country/city select. */
function isWorkdayPlaceOfResidenceField(label) {
    const l = String(label || '').toLowerCase();
    if (/office location|work location|job location|basecamp|working from|relocati/i.test(l)) return false;
    return /place of residence|confirm your current location|current location\s*\/\s*place/i.test(l);
}

function getWorkdayPlaceOfResidenceCandidates(profile = null) {
    profile = profile || window.__wdApplyData?.profile || {};
    const city = String(profile.residencyCity || profile.residency?.city || '').trim();
    const area = String(profile.residencyArea || profile.residency?.area || '').trim();
    const country = String(getProfileCountryName(profile) || '').trim();
    const out = [];
    // UniMelb-style relocation status selects (not city/country typeaheads).
    if (/australia/i.test(country)) {
        out.push('I currently reside in Australia');
    } else {
        out.push('I currently reside overseas but am self relocating to Australia');
        out.push('I currently reside overseas and would seek assistance to relocate to Australia');
        out.push('I currently reside in Australia');
    }
    out.push(
        'I currently reside overseas but am self relocating to Australia',
        'I currently reside in Australia',
        'I currently reside overseas and would seek assistance to relocate to Australia',
    );
    if (city && country) {
        out.push(`${city}, ${country}`);
        if (/^united kingdom$/i.test(country)) out.push(`${city}, UK`);
    }
    if (city) out.push(city);
    if (area) out.push(area);
    for (const c of getExpectedCountryCandidates(profile)) out.push(c);
    return [...new Set(out.filter(Boolean))];
}

async function fillWorkdayPlaceOfResidenceField(container, label = '', profile = null) {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const cands = getWorkdayPlaceOfResidenceCandidates(profile || window.__wdApplyData?.profile);
    if (!cands.length) return false;
    if (isWorkdaySingleSelectFilled(container, cands)) return true;
    const control = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!control) return false;
    const openKey = normalizeDropdownOpenKey(labelText);
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        debugLog(`${WD} place of residence skip excess opens`, labelText.slice(0, 60));
        return isWorkdaySingleSelectFilled(container, cands);
    }
    // Static listbox (unimelb.wd105) — never use typeahead multi (leaks into nearby textareas).
    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(openKey);
    const ok = await fillWorkdaySingleSelectDropdown(control, cands, labelText);
    debugLog(`${WD} place of residence fill`, labelText.slice(0, 60), cands[0], 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, cands);
}

function isWorkdayVisaHoursPerWeekField(label) {
    const l = String(label || '').toLowerCase();
    return /hours per week.*visa|visa enable you to work|visa holders only/i.test(l);
}

function isWorkdayVisaExpiryDateLabel(label) {
    const l = String(label || '').toLowerCase();
    return /visa expiry|expiry date.*visa|visa.*expir/i.test(l);
}

/** True when Application Questions eligibility already selected a citizen option. */
function workdayQuestionnaireIndicatesCitizen() {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!/eligible to work|work rights for|are you eligible to work/i.test(label)) continue;
        const selected = `${getWorkdayFieldSelectedText(container)} ${container.innerText || ''}`.toLowerCase();
        if (/citizen/i.test(selected) && !/visa holder|require visa sponsorship|permanent resident/i.test(
            getWorkdayFieldSelectedText(container) || '',
        )) {
            return true;
        }
        const btn = container.querySelector('button[aria-haspopup="listbox"]');
        const btnText = String(btn?.innerText || '').toLowerCase();
        if (/citizen/i.test(btnText) && !/visa holder|sponsorship/i.test(btnText)) return true;
    }
    return false;
}

function getWorkdayVisaHoursPerWeekCandidates() {
    return [
        // UniMelb hour bands (unimelb.wd105) — prefer maximum.
        '30+ hours',
        '30+',
        '21-30 hours',
        '21-30',
        '11-20 hours',
        '0-10 hours',
        'Unrestricted',
        'No restriction',
        'Unlimited',
        'Full time',
        'Full-time',
        '40',
        '38',
        '37.5',
        '35',
        'As per visa conditions',
    ];
}

async function fillWorkdayVisaHoursPerWeekField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    // Citizen eligibility: leave visa-hours on Select One — answering reveals Visa expiry
    // and blocks Next when that date is excluded/unfilled (unimelb.wd105).
    if (workdayQuestionnaireIndicatesCitizen()) {
        debugLog(`${WD} visa hours skip — citizen eligibility`, labelText.slice(0, 50));
        return true;
    }
    const cands = getWorkdayVisaHoursPerWeekCandidates();
    if (isWorkdaySingleSelectFilled(container, cands)) return true;
    const control = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!control) return false;
    const openKey = normalizeDropdownOpenKey(labelText);
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) return isWorkdaySingleSelectFilled(container, cands);
    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(openKey);
    const ok = await fillWorkdaySingleSelectDropdown(control, cands, labelText);
    debugLog(`${WD} visa hours fill`, labelText.slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, cands);
}

async function fillWorkdayVisaExpiryDateField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    if (workdayQuestionnaireIndicatesCitizen()) {
        debugLog(`${WD} visa expiry skip — citizen eligibility`, labelText.slice(0, 50));
        return true;
    }
    const control = getContainerControl(container)
        || container.querySelector('input[aria-label*="Year" i]')
        || container.querySelector('input');
    if (!control) return false;
    // Far-future expiry so long-stay / work visas validate.
    const d = new Date();
    d.setFullYear(d.getFullYear() + 3);
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(Math.min(28, d.getDate())).padStart(2, '0');
    const dateValue = `${mm}/${dd}/${d.getFullYear()}`;
    if (isDateContainerFilled(container, dateValue)) return true;
    debugLog(`${WD} visa expiry fill`, labelText.slice(0, 50), dateValue);
    const ok = await fillWorkdayMaskedDate(container, control, dateValue, (container.innerText || '').toLowerCase(), { force: true });
    return ok || isDateContainerFilled(container, dateValue);
}

/** Re-commit UniMelb-style questionnaire selects before Next — UI label alone is not enough. */
async function ensureWorkdayQuestionnaireSelectsCommitted() {
    let fixed = 0;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!label) continue;
        const isElig = /eligible to work|work rights for|are you eligible to work/i.test(label);
        const isRes = isWorkdayPlaceOfResidenceField(label);
        const isVisaHrs = isWorkdayVisaHoursPerWeekField(label);
        const isAvail = /availability to start|available to start|when can you start/i.test(label)
            && !isWorkdayMonthYearReturnDateLabel(label);
        const isReturnDate = isWorkdayMonthYearReturnDateLabel(label);
        const isGender = /gender option|how you identify|select the gender/i.test(label);
        const isAborig = /aboriginal|torres strait/i.test(label);
        const isEmployer = /current or most recent employer|company name of your current/i.test(label);
        if (!isElig && !isRes && !isVisaHrs && !isAvail && !isGender && !isAborig
            && !isReturnDate && !isEmployer) continue;
        const listBtn = container.querySelector('button[aria-haspopup="listbox"]');
        const hasOpaque = Boolean(getWorkdayButtonListboxOpaqueValue(container));
        const selected = getWorkdayFieldSelectedText(container) || '';
        const looksEmpty = !selected || /^select one$/i.test(selected) || /no response/i.test(selected);
        if (isReturnDate) {
            const ctrl = getContainerControl(container) || container.querySelector('input');
            const dateVal = getWorkdayNearTermMonthYear(2);
            if (ctrl && (!/^\d{1,2}\/\d{4}$/.test(String(ctrl.value || '')) || /n\/?a/i.test(String(ctrl.value || '')))) {
                debugLog(`${WD} questionnaire re-commit return date`, dateVal);
                const okDate = await fillWorkdayMaskedDate(container, ctrl, dateVal, (container.innerText || '').toLowerCase(), { force: true });
                if (okDate) fixed += 1;
            }
            continue;
        }
        if (isEmployer) {
            const ta = container.querySelector('textarea, input[type="text"], input:not([type])');
            const company = String((window.__wdApplyData?.profile?.experiences || [])[0]?.companyName
                || (window.__wdApplyData?.profile?.experiences || [])[0]?.company || '').trim();
            if (ta && company && !(ta.value || '').trim()) {
                if (typeof wdCommitReactTextInput === 'function') wdCommitReactTextInput(ta, company);
                else await workdayTypeElement(ta, company);
                fixed += 1;
            } else if (ta && (ta.value || '').trim() && typeof wdCommitReactTextInput === 'function') {
                wdCommitReactTextInput(ta, ta.value.trim());
            }
            continue;
        }
        // Button listboxes must have opaque id even when label looks filled.
        if (listBtn && hasOpaque && !looksEmpty) continue;
        if (!listBtn && !looksEmpty && hasOpaque) continue;
        if (!listBtn && !looksEmpty && !isWorkdayButtonListboxField(container)) {
            // Non-button widgets: selected text is enough.
            if (selected && !/^select one$/i.test(selected)) continue;
        }
        debugLog(`${WD} questionnaire re-commit`, label.slice(0, 60),
            'selected=', selected.slice(0, 40), 'opaque=', hasOpaque);
        clearWorkdaySingleSelectMissKey(label);
        resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
        let ok = false;
        if (isElig) {
            ok = await fillWorkdaySingleSelectDropdown(
                getWorkdayDropdownTrigger(container) || getContainerControl(container),
                getWorkdayConsentYesCandidates(label),
                label,
            );
        } else if (isRes) {
            ok = await fillWorkdayPlaceOfResidenceField(container, label);
        } else if (isVisaHrs) {
            ok = await fillWorkdayVisaHoursPerWeekField(container, label);
        } else if (isAvail) {
            ok = await fillWorkdaySingleSelectDropdown(
                getWorkdayDropdownTrigger(container) || getContainerControl(container),
                [
                    'I am available within 4 weeks or less',
                    'I am immediately available',
                    'Immediately',
                    'As soon as possible',
                    '2 weeks',
                    '1 month',
                    '2 months',
                    '3 months',
                    'Available now',
                ],
                label,
            );
        } else if (isGender) {
            ok = await fillWorkdaySingleSelectDropdown(
                getWorkdayDropdownTrigger(container) || getContainerControl(container),
                ['Prefer not to say', 'Prefer not to answer', 'Decline', 'Male', 'Female', 'Non-binary'],
                label,
            );
        } else if (isAborig) {
            ok = await fillWorkdaySingleSelectDropdown(
                getWorkdayDropdownTrigger(container) || getContainerControl(container),
                ['No', 'Prefer not to say', 'Prefer not to answer', 'Decline'],
                label,
            );
        }
        if (ok || getWorkdayButtonListboxOpaqueValue(container)) fixed += 1;
        await wait(400);
    }
    if (fixed) debugLog(`${WD} questionnaire re-commit done`, 'fixed=', fixed);
    return fixed;
}

function isNationalityCountryFieldLabel(label) {
    const l = String(label || '').toLowerCase();
    return /\bprimary nationality\b|\badditional nationalit/i.test(l)
        || (/\bnationality\b/i.test(l) && !/\bcitizenship status\b/i.test(l));
}

function isCitizenshipFieldLabel(label) {
    const l = String(label || '').toLowerCase();
    if (l.length > 60) return false;
    if (isNationalityCountryFieldLabel(label)) return false;
    if (/for any of the countries listed below|countries listed below/i.test(l)) return false;
    if (/are you a citizen|hold.*passport|dual citizen|citizen of any/i.test(l) && !/citizenship status/i.test(l)) return false;
    return /\bcitizenship status\b|\bnationality\b|^citizenship$|\bcitizenship\b/i.test(l)
        && !/visa|sponsorship|authorization|work permit|require sponsorship/i.test(l);
}

function isCountryOrCitizenshipFieldLabel(label) {
    return isCountryFieldLabel(label) || isCitizenshipFieldLabel(label);
}

function profileExpectsUS(profile) {
    const raw = getProfileCountryName(profile).toLowerCase();
    return /united states|usa|\bus\b|u\.s\./.test(raw);
}

function getJobLocationText() {
    return String(window.__wdHistoryLocation || '').trim();
}

function jobLocationExpectsJapanResidency() {
    const loc = getJobLocationText().toLowerCase();
    return /\bjapan\b|, jp\b|,\s*jp,|tokyo|osaka|kyoto|nagoya|yokohama|fukuoka|sapporo|kobe|hiroshima|sendai|chiba|saitama|kawasaki|hokkaido|okinawa/i.test(loc);
}

function jobLocationExpectsUSResidency() {
    if (jobLocationExpectsJapanResidency() || jobLocationExpectsEgyptResidency() || jobLocationExpectsSaudiResidency()) {
        return false;
    }
    const locRaw = getJobLocationText();
    const loc = locRaw.toLowerCase();
    if (!loc) return false;
    if (/\bunited states\b|\busa\b|u\.s\.a\.?|\bu\.s\.\b/.test(loc)) return true;
    if (/,\s*us\b|\/\s*us\b|\bus\s*-/.test(loc)) return true;
    if (getUSStateFromJobLocation()) return true;
    // "City, ST" or "City, ST, USA" patterns common on Workday US postings
    if (/,\s*[A-Z]{2}(?:\s*,|\s*$)/.test(locRaw)) return true;
    return false;
}

function getUSPhoneNumberForJob(profile) {
    const raw = String(profile?.phone || profile?.general?.phone || '').replace(/\D/g, '');
    if (raw.length === 10 && !/^0/.test(raw) && !/^91/.test(raw)) return raw;
    if (raw.length === 11 && raw.startsWith('1')) return raw.slice(1);
    // Stable fake US mobile for non-US profiles applying to US jobs
    return '4045551287';
}

function jobLocationExpectsEgyptResidency() {
    const loc = getJobLocationText().toLowerCase();
    return /\begypt\b|\bcairo\b|\balexandria\b|\bgiza\b/i.test(loc);
}

function jobLocationExpectsSaudiResidency() {
    const loc = getJobLocationText().toLowerCase();
    if (/\bsaudi\b|\briyadh\b|\bjeddah\b|\bdammam\b|\bmecca\b|\bmedina\b|\bkhobar\b/i.test(loc)) return true;
    const profile = window.__wdApplyData?.profile;
    const general = profile?.general || profile || {};
    const country = String(general.country || profile?.residencyCountry || '').toLowerCase();
    const phoneCode = String(general.phoneCountryCode || profile?.phoneCountryCode || '');
    return /\bsaudi\b/i.test(country) || phoneCode === '+966';
}

function getSaudiProvinceCandidates() {
    const loc = getJobLocationText().toLowerCase();
    if (/jeddah|makkah|mecca/i.test(loc)) return ['Makkah', 'Mecca', 'Makkah Province', 'Western Province'];
    if (/dammam|khobar|dhahran/i.test(loc)) return ['Eastern Province', 'Ash Sharqiyah', 'Eastern'];
    return ['Riyadh', 'Ar Riyad', 'Riyadh Province', 'Central Region'];
}

function getSaudiNeighborhoodDefault() {
    const loc = getJobLocationText().toLowerCase();
    if (/jeddah/i.test(loc)) return 'Al Hamra';
    if (/dammam|khobar/i.test(loc)) return 'Al Faisaliyah';
    return 'Al Olaya';
}

async function fillSaudiProvinceField(container, label = '') {
    if (!container || !jobLocationExpectsSaudiResidency()) return false;
    const labelText = label || getContainerLabel(container);
    const candidates = getSaudiProvinceCandidates();
    if (isWorkdaySingleSelectFilled(container, candidates)) return true;

    const openKey = normalizeDropdownOpenKey('saudi-province');
    clearWorkdaySingleSelectMissKey('province');
    clearWorkdaySingleSelectMissKey(labelText);
    resetWorkdayDropdownOpenCount(openKey);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelText));

    const control = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!control) return false;

    await closeWorkdayPopups();
    await wait(200);
    workdayScrollToTarget(container, 120);
    trackWorkdayDropdownOpen(openKey);
    await workdayClick(getWorkdayDropdownTrigger(container) || control);
    await wait(1200);

    const popup = findPopupNearField(container, 'province') || findActiveWorkdayPopup();
    if (!popup) {
        trackWorkdayDropdownClose(openKey, 'no-popup');
        return false;
    }

    const options = getSingleSelectDropdownOptions(popup, false);
    debugLog(`${WD} saudi province options`, options.map(o => optionText(o)).slice(0, 20));

    const needles = [...candidates, 'riyadh', 'ar riyad', 'central', 'makkah', 'eastern'].map(v => v.toLowerCase());
    let match = options.find(o => {
        const ot = optionText(o).toLowerCase();
        return needles.some(n => n && (ot === n || ot.includes(n) || n.includes(ot)));
    });
    if (!match) {
        match = options.find(o => !/^select one$/i.test(optionText(o)));
    }
    if (!match) {
        await closeWorkdayPopups();
        trackWorkdayDropdownClose(openKey, 'miss');
        return false;
    }

    const matchText = optionText(match);
    const combobox = container.querySelector('input[role="combobox"]') || control;
    if (match.getAttribute('data-value')) {
        workdayClickElement(match);
        await wait(600);
        await commitWorkdayComboboxSelection(container, combobox, match, matchText);
    } else {
        await selectWorkdayDisclosureListboxOption(container, combobox, match, [matchText, ...candidates], matchText);
    }
    await closeWorkdayPopups();
    trackWorkdayDropdownClose(openKey, 'selected');
    const filled = isWorkdaySingleSelectFilled(container, [matchText, ...candidates]);
    debugLog(`${WD} saudi province filled`, matchText, 'ok=', filled);
    return filled;
}

function getProfileDateOfBirth(profile) {
    const years = Number(profile?.workingExperienceInYears || profile?.working_experience_in_years || 10);
    const birthYear = new Date().getFullYear() - Math.max(22, years + 22);
    return `06/15/${birthYear}`;
}

function getJapanCityFromJobLocation() {
    const loc = getJobLocationText();
    const cities = ['Tokyo', 'Osaka', 'Kyoto', 'Nagoya', 'Yokohama', 'Fukuoka', 'Sapporo', 'Kobe', 'Hiroshima', 'Sendai'];
    for (const city of cities) {
        if (new RegExp(city, 'i').test(loc)) return city;
    }
    return 'Tokyo';
}

function getJapanPostalCodeForJob() {
    const city = getJapanCityFromJobLocation().toLowerCase();
    const byCity = {
        tokyo: '100-0001',
        osaka: '530-0001',
        kyoto: '600-0001',
        nagoya: '450-0001',
        yokohama: '220-0001',
        fukuoka: '812-0001',
        sapporo: '060-0001',
        kobe: '650-0001',
        hiroshima: '730-0001',
        sendai: '980-0001',
    };
    return byCity[city] || '100-0001';
}

function getJapanPrefectureFromJob() {
    const city = getJapanCityFromJobLocation().toLowerCase();
    const byCity = {
        tokyo: 'Tokyo',
        osaka: 'Osaka',
        kyoto: 'Kyoto',
        nagoya: 'Aichi',
        yokohama: 'Kanagawa',
        fukuoka: 'Fukuoka',
        sapporo: 'Hokkaido',
        kobe: 'Hyogo',
        hiroshima: 'Hiroshima',
        sendai: 'Miyagi',
    };
    return byCity[city] || 'Tokyo';
}

function getJapanCityKanji() {
    const city = getJapanCityFromJobLocation().toLowerCase();
    const byCity = {
        tokyo: '千代田区',
        osaka: '大阪市',
        kyoto: '京都市',
        nagoya: '名古屋市',
        yokohama: '横浜市',
        fukuoka: '福岡市',
        sapporo: '札幌市',
        kobe: '神戸市',
    };
    return byCity[city] || '千代田区';
}

function getJapanAddressKanji() {
    return '丸の内1-1';
}

function getJapanAddressWestern(profile, residency) {
    const street = residency?.street || profile?.residencyStreet;
    if (street && !/^n\/a$/i.test(String(street))) return street;
    return '1-1 Marunouchi';
}

function isWorkdayJapanPostalSearchField(label) {
    return jobLocationExpectsJapanResidency() && /search address.*postal/i.test(String(label || '').toLowerCase());
}

function isValidJapanPostalValue(value) {
    const digits = String(value || '').replace(/\D/g, '');
    return digits.length === 7;
}

function normalizeJapanPostalValue(value) {
    const digits = String(value || '').replace(/\D/g, '');
    if (digits.length === 7) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
    return getJapanPostalCodeForJob();
}

function getJapanPhoneNumberForJob(profile) {
    const raw = String(profile?.phone || profile?.general?.phone || '').replace(/\D/g, '');
    if (/^0[789]0\d{8}$/.test(raw)) return raw.slice(1);
    if (/^[789]0\d{8}$/.test(raw)) return raw;
    return '9012345678';
}

function getWorkdayPostalCodeValue(profile) {
    if (jobLocationExpectsJapanResidency()) {
        const zip = String(profile?.residency?.zip || profile?.residencyZip || profile?.general?.residency?.zip || '').replace(/\D/g, '');
        if (/^\d{7}$/.test(zip)) return normalizeJapanPostalValue(zip);
        return getJapanPostalCodeForJob();
    }
    const residency = profile?.residency || profile?.general?.residency || {};
    const zip = String(residency.zip || profile?.residencyZip || '').trim();
    if (zip && !/^n\/a$/i.test(zip)) return zip;
    if (profileExpectsUS(profile)) {
        const fromJob = getDefaultUSZipForJobLocation();
        if (fromJob) return fromJob;
        return '20001';
    }
    return zip;
}

function getProfileForJobLocation(profile) {
    if (!profile) return profile;
    if (jobLocationExpectsJapanResidency()) {
        const city = getJapanCityFromJobLocation();
        const postal = getJapanPostalCodeForJob();
        const residency = profile?.residency || profile?.general?.residency || {};
        return {
            ...profile,
            residency: { ...residency, country: 'Japan', city, zip: postal },
            residencyCountry: 'Japan',
            residencyCity: city,
            residencyZip: postal,
            phoneCountryCode: '+81',
            phone: getJapanPhoneNumberForJob(profile),
            general: profile?.general ? {
                ...profile.general,
                phoneCountryCode: '+81',
                phone: getJapanPhoneNumberForJob(profile),
                residency: { ...(profile.general.residency || {}), country: 'Japan', city, zip: postal },
            } : profile.general,
        };
    }
    // US Workday forms use US state lists — keep non-US profiles from typing foreign states
    // into US State / phone-code fields (e.g. India Telangana on Wells Fargo).
    if (jobLocationExpectsUSResidency() && !profileExpectsUS(profile)) {
        const city = getUSCityFromJobLocation() || 'Charlotte';
        const state = getUSStateFromJobLocation() || 'North Carolina';
        const zip = getDefaultUSZipForJobLocation() || '28202';
        const street = getDefaultUSStreetForJobLocation();
        const phone = getUSPhoneNumberForJob(profile);
        const residency = profile?.residency || profile?.general?.residency || {};
        debugLog(`${WD} profile override US for job location`, city, state, zip);
        return {
            ...profile,
            residency: {
                ...residency,
                country: 'United States',
                city,
                area: state,
                state,
                zip,
                street: residency.street && !/^n\/a$/i.test(String(residency.street))
                    ? residency.street
                    : street,
            },
            residencyCountry: 'United States',
            residencyCity: city,
            residencyZip: zip,
            residencyArea: state,
            phoneCountryCode: '+1',
            phone,
            general: profile?.general ? {
                ...profile.general,
                phoneCountryCode: '+1',
                phone,
                residency: {
                    ...(profile.general.residency || {}),
                    country: 'United States',
                    city,
                    area: state,
                    state,
                    zip,
                    street: (profile.general.residency || {}).street || street,
                },
            } : profile.general,
        };
    }
    return profile;
}

function normalizeWorkdayMenuOptionText(text) {
    return String(text || '')
        .replace(/\s+not checked/i, '')
        .replace(/\s+checked/i, '')
        .replace(/\s+/g, ' ')
        .trim();
}

/** Strip chip/listbox noise and regional suffixes for disclosure dropdown matching. */
function normalizeDisclosureOptionText(text) {
    return normalizeWorkdayMenuOptionText(text)
        .replace(/,?\s*press delete to clear(?:\s+value)?\.?/gi, '')
        .replace(/\s*\([^)]+\)\s*$/i, '')
        .replace(/\s+/g, ' ')
        .trim();
}

function disclosureOptionText(optionEl) {
    const raw = optionEl?.getAttribute?.('aria-label') || optionEl?.innerText || optionEl?.textContent || '';
    return normalizeDisclosureOptionText(raw).toLowerCase();
}

function isWorkdayDisclosureChipOptionText(text) {
    return /press delete to clear/i.test(String(text || ''));
}

function filterDisclosureListboxOptions(options) {
    const seen = new Set();
    const filtered = [];
    for (const opt of options) {
        const raw = opt?.getAttribute?.('aria-label') || opt?.innerText || '';
        if (isWorkdayDisclosureChipOptionText(raw)) continue;
        const key = disclosureOptionText(opt);
        if (!key || /^select one$/i.test(key)) continue;
        if (seen.has(key)) continue;
        seen.add(key);
        filtered.push(opt);
    }
    return filtered.length ? filtered : options.filter(o => !isWorkdayDisclosureChipOptionText(o.getAttribute?.('aria-label') || ''));
}

function isWorkdayDisclosureSelectionFilled(container, candidates) {
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    if (!container || !vals.length) return false;
    if (isDisclosureChoiceFilled(container, vals)) return true;
    const combobox = container.querySelector('input[role="combobox"]');
    const comboboxValue = normalizeDisclosureOptionText(combobox?.value || '');
    const selectionLabel = normalizeDisclosureOptionText(
        container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || ''
    );
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    const fieldLabel = (getContainerLabel(container) || '').replace(/\s+/g, ' ').trim();
    let bodyPreview = preview;
    if (fieldLabel && bodyPreview.toLowerCase().startsWith(fieldLabel.toLowerCase())) {
        bodyPreview = bodyPreview.slice(fieldLabel.length).replace(/^\s*\*?\s*/, '').trim();
    }
    // Option labels stay visible under an empty Select One — do not treat them as a selection.
    if (/select one/i.test(preview) && !selectionLabel && !comboboxValue) return false;
    // Workday error / empty prompt after the label means React did not commit (DOM value may be stale).
    if (/error:.*required|(?:^|\s)select one\b/i.test(bodyPreview)
        && (!selectionLabel || /^select one$/i.test(selectionLabel))
        && !comboboxValue) {
        return false;
    }
    if (/error:.*required/i.test(bodyPreview)
        && (!selectionLabel || /^select one$/i.test(selectionLabel))) {
        return false;
    }
    if (/^[a-f0-9-]{16,}$/i.test(comboboxValue) && !/select one/i.test(selectionLabel || '')
        && !/error:.*required/i.test(bodyPreview)) return true;
    if (selectionLabel && !/^select one$/i.test(selectionLabel) && vals.some(c => textMatchesCandidate(selectionLabel, c))) return true;
    if (comboboxValue && !/^select one$/i.test(comboboxValue) && vals.some(c => textMatchesCandidate(comboboxValue, c))
        && !/error:.*required/i.test(bodyPreview)) return true;
    const selected = normalizeDisclosureOptionText(getWorkdayFieldSelectedText(container));
    if (selected && !/^select one$/i.test(selected) && selected.length < 80
        && vals.some(c => textMatchesCandidate(selected, c))
        && !/error:.*required/i.test(bodyPreview)) return true;
    return false;
}

function isDisclosureListboxOptionSelected(opt) {
    return isHearOptionSelected(opt);
}

async function selectWorkdayDisclosureListboxOption(fieldRoot, combobox, optionEl, candidates, displayText = '') {
    if (!optionEl || !fieldRoot) return false;
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    const label = displayText || disclosureOptionText(optionEl);
    const filledCheck = () => isWorkdayDisclosureSelectionFilled(fieldRoot, vals)
        || isWorkdaySingleSelectFilled(fieldRoot, vals)
        || isWorkdaySingleSelectFilled(fieldRoot, [label]);

    if (filledCheck()) return true;

    workdayScrollToTarget(optionEl, 120);
    await wait(150);

    if (await clickWorkdayOption(optionEl)) {
        await wait(450);
        if (filledCheck()) return true;
    }

    const clickTargets = [
        optionEl.querySelector('input[type="radio"]'),
        optionEl.querySelector('[role="radio"]'),
        optionEl.querySelector('input[type="checkbox"]'),
        optionEl.querySelector('[role="checkbox"]'),
        optionEl.querySelector('[data-automation-id="promptLeafNode"]'),
        optionEl.querySelector('[data-automation-id="promptOption"]'),
        optionEl.querySelector('label'),
        optionEl,
    ].filter(Boolean);

    for (const clickTarget of clickTargets) {
        await workdayClick(clickTarget);
        await wait(400);
        if (isDisclosureListboxOptionSelected(optionEl) || filledCheck()) return true;
    }

    if (combobox) {
        await commitWorkdayComboboxSelection(fieldRoot, combobox, optionEl, label);
        await wait(450);
        if (filledCheck()) return true;
    }

    optionEl.focus?.();
    for (const key of [' ', 'Enter']) {
        optionEl.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(400);
        if (isDisclosureListboxOptionSelected(optionEl) || filledCheck()) return true;
    }

    return filledCheck();
}

function isUsTerritoryCountryOptionText(text) {
    return /minor outlying|virgin islands|american samoa|guam|puerto rico|northern mariana|micronesia|palau|marshall islands/i
        .test(String(text || ''));
}

function countryOptionMatches(text, candidates) {
    const t = normalizeWorkdayMenuOptionText(text);
    if (!t || /^select one$/i.test(t) || isPhoneCodeOptionText(t)) return false;
    const fold = (s) => String(s || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();
    const tf = fold(t);
    return (Array.isArray(candidates) ? candidates : [candidates]).some((c) => {
        const cf = fold(normalizeWorkdayMenuOptionText(c));
        if (!cf) return false;
        if (tf === cf) return true;
        // "United States" / "United States of America" must NOT match US territories
        // ("United States Minor Outlying Islands") — observed on sggovterp.wd102 Citizenship Status
        // where countryOptionMatches falsely treated the territory as a US citizen leaf.
        if (/^united states\b/.test(cf) && !isUsTerritoryCountryOptionText(cf)) {
            if (isUsTerritoryCountryOptionText(tf)) return false;
            if (/^united states of america$/.test(tf) || /^united states$/.test(tf)) return true;
            // Allow "United States of America" ↔ "United States" only (exact / of-america pair).
            if (/^united states$/.test(cf) && /^united states of america$/.test(tf)) return true;
            if (/^united states of america$/.test(cf) && /^united states$/.test(tf)) return true;
            return false;
        }
        // Allow "United Kingdom" ↔ longer UK labels; same for UAE / Korea / Congo.
        if (/^(united kingdom|united arab emirates|korea|congo)\b/.test(cf)
            || /^(united kingdom|united arab emirates|korea|congo)\b/.test(tf)) {
            if (tf.startsWith(cf) || cf.startsWith(tf)) return true;
        }
        // Word-boundary only — "India" must NOT match "British Indian Ocean Territory"
        // (substring includes() would match "india" inside "indian").
        const escaped = cf.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        return new RegExp(`(^|[^a-z0-9])${escaped}([^a-z0-9]|$)`, 'i').test(tf);
    });
}

let wdCountryTimingStart = 0;
function logCountryPhase(phase, ...rest) {
    const elapsed = wdCountryTimingStart ? Date.now() - wdCountryTimingStart : 0;
    debugLog(`${WD} country timing`, phase, 'elapsedMs=', elapsed, ...rest);
}

function findCountryInSingleSelectOptions(popup, profile) {
    if (!popup) return null;
    const candidates = getExpectedCountryCandidates(profile);
    for (const opt of getSingleSelectDropdownOptions(popup, false)) {
        const text = optionText(opt);
        if (text && countryOptionMatches(text, candidates)) {
            return { el: opt, text };
        }
    }
    return null;
}

async function tryCountryComboboxFilter(fieldRoot, profile, popup) {
    const searchInput = getCountryPopupSearchInput(fieldRoot, popup);
    if (!searchInput) return null;
    for (const term of getExpectedCountryCandidates(profile)) {
        logCountryPhase('combobox-filter', term.slice(0, 36));
        await workdayClick(searchInput);
        await wait(150);
        await workdayTypeSearchInput(searchInput, term);
        await wait(400);
        await submitWorkdaySearchInput(searchInput);
        await wait(900);
        const match = findCountryMatchInItems(getCountryMenuItems(fieldRoot, popup), profile);
        if (match) {
            logCountryPhase('combobox-filter-hit', match.text);
            return match;
        }
        const pop = findCountryPopup(fieldRoot) || popup;
        const ssMatch = findCountryInSingleSelectOptions(pop, profile);
        if (ssMatch) return ssMatch;
    }
    return null;
}

async function tryCountryKeyboardTypeahead(fieldRoot, profile, popup) {
    const candidates = getExpectedCountryCandidates(profile);
    const target = candidates[0];
    if (!target) return null;
    const combobox = fieldRoot?.querySelector('input[role="combobox"]');
    const prefix = target.split(/\s+/).slice(0, 2).join(' ');
    if (combobox) {
        logCountryPhase('typeahead', prefix.slice(0, 20));
        combobox.focus();
        await workdayTypeSearchInput(combobox, prefix);
        await wait(700);
        const match = findCountryMatchInItems(getCountryMenuItems(fieldRoot, popup))
            || findCountryInSingleSelectOptions(findCountryPopup(fieldRoot) || popup, profile);
        if (match) {
            logCountryPhase('typeahead-hit', match.text);
            return match;
        }
    }
    const firstItem = popup?.querySelector('[data-automation-id="menuItem"], [role="option"]');
    if (firstItem) {
        firstItem.focus();
        await wait(100);
        const key = target.charAt(0).toUpperCase();
        firstItem.dispatchEvent(new KeyboardEvent('keydown', { key, code: `Key${key}`, bubbles: true, cancelable: true }));
        await wait(500);
        const match = findCountryMatchInItems(getCountryMenuItems(fieldRoot, popup));
        if (match) {
            logCountryPhase('typeahead-first-letter', match.text);
            return match;
        }
    }
    return null;
}

function findCountryMatchInItems(items, profile) {
    const candidates = getExpectedCountryCandidates(profile);
    const matches = items.filter(o => countryOptionMatches(o.text, candidates));
    if (!matches.length) return null;
    const fold = (s) => String(s || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();
    // Prefer exact country name over longer names that only share a token
    for (const c of candidates) {
        const cf = fold(c);
        const exact = matches.find(o => fold(o.text) === cf);
        if (exact) return exact;
    }
    if (profileExpectsUS(profile)) {
        const preferred = matches.find(o => /^united states of america$/i.test(o.text))
            || matches.find(o => /^united states$/i.test(o.text) && !/minor|virgin|samoa|guam|puerto|mariana|micronesia/i.test(o.text))
            || matches.find(o => /united states of america/i.test(o.text) && !/minor|virgin|samoa|guam|puerto|mariana|micronesia/i.test(o.text));
        if (preferred) return preferred;
    }
    // Prefer shortest match (India over British Indian Ocean Territory if both somehow matched)
    matches.sort((a, b) => a.text.length - b.text.length);
    return matches[0];
}

function getCountryMenuItems(fieldRoot, popup = null) {
    const seen = new Set();
    const result = [];
    const add = (el, text) => {
        const normalized = normalizeWorkdayMenuOptionText(text);
        if (!normalized || seen.has(normalized) || isPhoneCodeOptionText(normalized)) return;
        seen.add(normalized);
        result.push({ el, text: normalized });
    };

    for (const o of getAllHearMenuItems(fieldRoot)) add(o.el, o.text);

    const pop = popup || findCountryPopup(fieldRoot) || findActiveWorkdayPopup();
    if (pop) {
        for (const el of pop.querySelectorAll(
            '[data-automation-id="promptLeafNode"], [data-automation-id="promptOption"], [data-automation-id="menuItem"], [role="option"], [role="treeitem"]'
        )) {
            if (!isVisibleElement(el)) continue;
            add(el, el.getAttribute('aria-label') || el.innerText || el.textContent || '');
        }
    }
    return result;
}

function getCountryPopupSearchInput(fieldRoot, popup = null) {
    const pop = popup || findCountryPopup(fieldRoot) || findActiveWorkdayPopup();
    // Workday multiselect Citizenship Status (sggovterp.wd102) puts data-automation-id="searchBox"
    // ON the <input> itself (inside multiselectInputContainer), not on a wrapper that contains an input.
    // Prefer that field-level search before popup descendants — typing there filters the prompt list.
    return fieldRoot?.querySelector('input[data-automation-id="searchBox"]')
        || fieldRoot?.querySelector('[data-automation-id="multiselectInputContainer"] input[data-uxi-widget-type="selectinput"]')
        || fieldRoot?.querySelector('[data-automation-id="multiselectInputContainer"] input')
        || pop?.querySelector('input[data-automation-id="searchBox"]')
        || pop?.querySelector('[data-automation-id="searchBox"] input')
        || pop?.querySelector('input[placeholder*="Search" i], input[type="search"]')
        || fieldRoot?.querySelector('input[role="combobox"]')
        || fieldRoot?.querySelector('input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"])');
}

function getCitizenshipSearchTerms(profile) {
    const country = getWorkdayCountryName(profile);
    const profileName = getProfileCountryName(profile);
    const terms = [];
    if (profileExpectsUS(profile)) {
        terms.push('Citizen', 'United States', 'United States of America', country, profileName, 'USA', 'US');
    } else {
        terms.push('Citizen', country, profileName);
    }
    if (/united kingdom/i.test(profileName)) {
        terms.push('United Kingdom', 'UK', 'Great Britain');
    }
    return [...new Set(terms.filter(Boolean))];
}

function getCitizenshipRadioCandidates(profile) {
    const country = getWorkdayCountryName(profile);
    const profileName = getProfileCountryName(profile);
    const out = [];
    for (const c of [country, profileName, ...getExpectedCountryCandidates(profile)]) {
        if (!c) continue;
        out.push(`Citizen (${c})`, `Citizen(${c})`);
    }
    return [...new Set(out)];
}

function citizenshipStatusMatchesText(text, profile) {
    const t = normalizeWorkdayMenuOptionText(text).replace(/\.{2,}$/, '').trim();
    if (!t || /^select one$/i.test(t)) return false;
    if (/^us citizen|^u\.s\. citizen|united states citizen|a citizen of the united states|citizen of the united states/i.test(t)) {
        return profileExpectsUS(profile);
    }
    if (/^i am a (u\.s\. |us )?citizen/i.test(t)) {
        return profileExpectsUS(profile);
    }
    if (/^citizen\s*\(/i.test(t)) {
        if (/visitor|naturalized|permanent resident|temporary resident|non-citizen|not a citizen/i.test(t)) return false;
        const inner = t.replace(/^citizen\s*\(|\)\s*$/gi, '').trim();
        if (inner && countryOptionMatches(inner, getExpectedCountryCandidates(profile))) return true;
        return getCitizenshipRadioCandidates(profile).some(c => textMatchesCandidate(t, c));
    }
    if (profileExpectsUS(profile) && /^citizen$/i.test(t)) return true;
    if (profileExpectsUS(profile) && countryOptionMatches(t, getExpectedCountryCandidates(profile))) return true;
    return false;
}

function isLooseUsCitizenOptionText(text) {
    const t = normalizeWorkdayMenuOptionText(text).replace(/\.{2,}$/, '').trim();
    if (!t) return false;
    if (/visitor|naturalized|permanent resident|temporary resident|non-citizen|not a citizen|lawful permanent/i.test(t)) {
        return false;
    }
    return /^citizen\s*\(/i.test(t) && /united states|u\.s\.|usa|\bus\b/i.test(t);
}

function logCitizenshipPopupOptions(fieldRoot, popup, tag) {
    const scopes = [];
    if (popup) scopes.push(popup);
    if (fieldRoot) scopes.push(fieldRoot);
    const active = getCitizenshipPopup(fieldRoot) || findActiveWorkdayPopup();
    if (active && !scopes.includes(active)) scopes.push(active);

    const texts = [];
    const rowSelectors = '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"], li';
    for (const scope of scopes) {
        for (const row of scope.querySelectorAll(rowSelectors)) {
            const text = normalizeWorkdayMenuOptionText((row.innerText || row.textContent || '').trim());
            if (text && text.length < 140 && !/^search results$/i.test(text)) texts.push(text);
        }
    }
    debugLog(`${WD} citizenship options dump`, tag, [...new Set(texts)].slice(0, 30).join(' | '));
}

function isCitizenshipFilled(container, profile) {
    if (!container) return false;

    const scopes = [container];
    let node = container.parentElement;
    for (let d = 0; d < 6 && node; d++) {
        scopes.push(node);
        node = node.parentElement;
    }
    const popup = getCitizenshipPopup(container) || findCountryPopup(container) || findActiveWorkdayPopup();
    if (popup) scopes.push(popup);

    for (const scope of scopes) {
        for (const input of scope.querySelectorAll(
            'input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"]'
        )) {
            const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`))
                || input.closest('label');
            const row = input.closest(
                '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"], li'
            );
            const text = (labelEl?.innerText || row?.innerText || input.getAttribute('aria-label') || '').trim();
            if (citizenshipStatusMatchesText(text, profile)) return true;
            if (countryOptionMatches(text, getExpectedCountryCandidates(profile))) return true;
        }
    }

    const preview = (getWorkdayFieldSelectedText(container) || container.innerText || '').replace(/\s+/g, ' ');
    if (/^citizen\s*\(/i.test(preview) && countryOptionMatches(preview, getExpectedCountryCandidates(profile))) {
        return true;
    }
    const selected = getWorkdayFieldSelectedText(container).toLowerCase();
    if (profileExpectsUS(profile) && selected && /united states( of america)?|u\.?s\.?\s*citizen/.test(selected)) return true;
    const selectedRaw = getWorkdayFieldSelectedText(container);
    if (countryOptionMatches(selectedRaw, getExpectedCountryCandidates(profile))) return true;
    if (/select one|0 items selected|is required and must have a value/i.test(preview)) return false;
    if (container.querySelector('[data-automation-id="errorMessage"], [data-automation-id*="validationError"]')) return false;
    return false;
}

function findCitizenshipStatusOption(fieldRoot, popup, profile) {
    const scopes = [];
    const activePopup = popup || getCitizenshipPopup(fieldRoot) || findCountryPopup(fieldRoot) || findActiveWorkdayPopup();
    if (activePopup) scopes.push(activePopup);
    if (fieldRoot) {
        scopes.push(fieldRoot);
        let node = fieldRoot.parentElement;
        for (let d = 0; d < 8 && node; d++) {
            scopes.push(node);
            node = node.parentElement;
        }
    }

    const rowSelectors = [
        '[data-automation-id="promptOption"]',
        '[data-automation-id="promptLeafNode"]',
        '[data-automation-id="menuItem"]',
        '[role="option"]',
        'li',
    ].join(', ');

    for (const scope of scopes) {
        for (const row of scope.querySelectorAll(rowSelectors)) {
            const text = (row.innerText || row.textContent || row.getAttribute('aria-label') || '').trim();
            if (!citizenshipStatusMatchesText(text, profile)) continue;
            const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]');
            const radio = row.querySelector('input[type="radio"]');
            const input = checkbox || radio;
            const labelEl = input
                ? (document.querySelector(`label[for="${CSS.escape(input.id)}"]`) || input.closest('label') || row)
                : row;
            return {
                el: input || row,
                label: labelEl,
                row,
                text: normalizeWorkdayMenuOptionText(text),
                kind: checkbox ? 'checkbox' : (radio ? 'radio' : 'row'),
            };
        }
        for (const input of scope.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"]')) {
            const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`))
                || input.closest('label');
            const row = input.closest(rowSelectors) || labelEl;
            const text = (labelEl?.innerText || row?.innerText || input.getAttribute('aria-label') || '').trim();
            if (!citizenshipStatusMatchesText(text, profile)) continue;
            return {
                el: input,
                label: labelEl || row || input,
                row: row || labelEl,
                text: normalizeWorkdayMenuOptionText(text),
                kind: input.type === 'checkbox' || input.getAttribute('role') === 'checkbox' ? 'checkbox' : 'radio',
            };
        }
    }
    if (profileExpectsUS(profile)) {
        for (const scope of scopes) {
            for (const row of scope.querySelectorAll(rowSelectors)) {
                const text = (row.innerText || row.textContent || row.getAttribute('aria-label') || '').trim();
                if (!isLooseUsCitizenOptionText(text)) continue;
                const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]');
                const radio = row.querySelector('input[type="radio"]');
                const input = checkbox || radio;
                const labelEl = input
                    ? (document.querySelector(`label[for="${CSS.escape(input.id)}"]`) || input.closest('label') || row)
                    : row;
                return {
                    el: input || row,
                    label: labelEl,
                    row,
                    text: normalizeWorkdayMenuOptionText(text),
                    kind: checkbox ? 'checkbox' : (radio ? 'radio' : 'row'),
                };
            }
        }
    }
    return null;
}

async function submitWorkdaySearchInput(el) {
    if (!el) return;
    await dispatchWorkdayEnterKey(el);
    await wait(1200);
}

async function selectCitizenshipStatusOption(fieldRoot, profile, option) {
    if (!option) return false;
    const filledCheck = () => isCitizenshipFilled(fieldRoot, profile);
    if (filledCheck()) return true;

    debugLog(`${WD} citizenship select`, option.kind, option.text?.slice(0, 80));
    const row = option.row || option.label || option.el;
    workdayScrollToTarget(row, 80);
    await wait(150);

    const checkbox = option.el?.type === 'checkbox' || option.el?.getAttribute?.('role') === 'checkbox'
        ? option.el
        : row?.querySelector?.('input[type="checkbox"], [role="checkbox"]');
    if (checkbox) {
        const ok = await workdayClickCheckbox(checkbox);
        debugLog(`${WD} citizenship checkbox click`, ok, option.text?.slice(0, 60));
        if (ok) return true;
        await wait(400);
        if (filledCheck()) return true;
    }

    for (const target of [option.label, row, option.el]) {
        if (!target) continue;
        await workdayClick(target);
        await wait(400);
        if (filledCheck()) return true;
    }

    if (await clickWorkdayMenuItem(row || option.el, fieldRoot, filledCheck)) {
        await wait(400);
        if (filledCheck()) return true;
    }

    return filledCheck();
}

function getCitizenshipPopup(fieldRoot) {
    const fromCountry = findCountryPopup(fieldRoot);
    if (fromCountry && /search results|citizen\s*\(|citizenship status|permanent resident/i.test(fromCountry.innerText || '')) {
        return fromCountry;
    }
    for (const pop of findVisibleWorkdayPopups()) {
        const text = pop.innerText || '';
        if (/search results/i.test(text) && (/citizen\s*\(/i.test(text) || /permanent resident/i.test(text))) return pop;
    }
    return fromCountry || findActiveWorkdayPopup();
}

async function trySelectCitizenshipFromResults(fieldRoot, profile, popup) {
    const activePopup = getCitizenshipPopup(fieldRoot) || popup;
    const option = findCitizenshipStatusOption(fieldRoot, activePopup, profile);
    if (!option) {
        logCitizenshipPopupOptions(fieldRoot, activePopup, 'no-match');
        debugLog(`${WD} citizenship option not found in results`);
        return false;
    }
    if (!await selectCitizenshipStatusOption(fieldRoot, profile, option)) return false;
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await wait(500);
    for (let i = 0; i < 4; i++) {
        if (isCitizenshipFilled(fieldRoot, profile)) return true;
        await wait(300);
    }
    return isCitizenshipFilled(fieldRoot, profile);
}

function citizenshipPopupLooksLikeCountryPicker(popup) {
    if (!popup) return false;
    const texts = [];
    for (const row of popup.querySelectorAll(
        '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"], li',
    )) {
        const text = normalizeWorkdayMenuOptionText((row.innerText || row.textContent || '').trim());
        if (text && !/^search results$/i.test(text)) texts.push(text);
    }
    if (!texts.length) return false;
    if (texts.some(t => /^citizen\s*\(/i.test(t))) return false;
    return texts.some(t => /^afghanistan$/i.test(t) || countryOptionMatches(t, [t]));
}

async function fillWorkdayCitizenshipCountryPicker(fieldRoot, profile, popup) {
    debugLog(`${WD} citizenship country-picker flow`);
    const trigger = getWorkdayDropdownTrigger(fieldRoot) || getContainerControl(fieldRoot);
    const openKey = getCountryDropdownOpenKey(fieldRoot);
    if (!trigger) return false;
    if (isCitizenshipFilled(fieldRoot, profile)) return true;
    wdCountryTimingStart = Date.now();
    const candidates = getExpectedCountryCandidates(profile);

    async function openPopup() {
        await closeWorkdayPopups();
        await wait(200);
        workdayScrollToTarget(fieldRoot, 120);
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(trigger);
        await wait(1200);
        return findCountryPopup(fieldRoot) || findPopupNearField(fieldRoot, openKey) || findActiveWorkdayPopup();
    }

    async function citizenshipLooksFilled() {
        if (isCitizenshipFilled(fieldRoot, profile)) return true;
        const selected = getWorkdayFieldSelectedText(fieldRoot);
        if (countryOptionMatches(selected, candidates)) return true;
        if (/[1-9]\d*\s+items?\s+selected/i.test(selected) && /united states/i.test(selected)) return true;
        const chips = [...fieldRoot.querySelectorAll(
            '[data-automation-id="promptSelectionLabel"], [data-automation-id="promptOption"], [data-automation-id="selectedItem"]',
        )].map(el => (el.innerText || el.textContent || '').trim()).filter(Boolean);
        if (chips.some(t => countryOptionMatches(t, candidates) || /united states/i.test(t))) return true;
        // Open popup: multiselectlistitem toggled to "checked" before chips commit.
        const pop = getCitizenshipPopup(fieldRoot) || findCountryPopup(fieldRoot) || findActiveWorkdayPopup();
        for (const item of getCountryMenuItems(fieldRoot, pop)) {
            if (!countryOptionMatches(item.text, candidates) && !/^united states( of america)?$/i.test(item.text)) continue;
            if (isUsTerritoryCountryOptionText(item.text)) continue;
            if (isCitizenshipMenuItemChecked(item.el)) return true;
        }
        return false;
    }

    async function dumpCitizenshipOptionRow(row, tag) {
        if (!row) return;
        const attrs = {
            tag: row.tagName,
            id: (row.id || '').slice(0, 60),
            role: row.getAttribute?.('role'),
            autoId: row.getAttribute?.('data-automation-id') || '',
            autoLabel: (row.getAttribute?.('data-automation-label') || '').slice(0, 80),
            ariaSelected: row.getAttribute?.('aria-selected'),
            ariaExpanded: row.getAttribute?.('aria-expanded'),
            ariaLabel: (row.getAttribute?.('aria-label') || '').slice(0, 80),
            dataValue: (row.getAttribute?.('data-value') || '').slice(0, 40),
            tabIndex: row.getAttribute?.('tabindex'),
            checks: row.querySelectorAll('input[type="checkbox"], [role="checkbox"]').length,
            text: normalizeWorkdayMenuOptionText((row.innerText || '').trim()).slice(0, 80),
            childTexts: [...row.querySelectorAll('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"], label, p, span')]
                .map(el => ({
                    t: el.tagName,
                    a: el.getAttribute?.('data-automation-id') || '',
                    l: (el.getAttribute?.('data-automation-label') || '').slice(0, 60),
                    id: (el.id || '').slice(0, 40),
                    text: normalizeWorkdayMenuOptionText((el.innerText || '').trim()).slice(0, 60),
                }))
                .filter(c => c.text)
                .slice(0, 8),
            html: (row.outerHTML || '').replace(/\s+/g, ' ').slice(0, 500),
            parentAuto: row.parentElement?.getAttribute?.('data-automation-id') || row.parentElement?.tagName || '',
        };
        debugLog(`${WD} citizenship option dump`, tag, JSON.stringify(attrs));
    }

    function dumpCitizenshipFieldChrome(tag) {
        const inputs = [...fieldRoot.querySelectorAll('input, button, [data-automation-id]')].slice(0, 40).map(el => ({
            t: el.tagName,
            type: el.getAttribute('type') || '',
            role: el.getAttribute('role') || '',
            auto: el.getAttribute('data-automation-id') || '',
            uxi: el.getAttribute('data-uxi-widget-type') || '',
            ph: el.getAttribute('placeholder') || '',
            hiddenSearch: el.getAttribute('data-automation-hiddensearch') || '',
            val: (el.value || '').slice(0, 40),
            text: (el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 40),
        }));
        debugLog(`${WD} citizenship field chrome`, tag, JSON.stringify(inputs).slice(0, 1800));
        debugLog(`${WD} citizenship field preview`, tag,
            (fieldRoot.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 200));
    }

    function isCitizenshipMenuItemChecked(el) {
        if (!el) return false;
        if (typeof isHearMenuItemChecked === 'function' && isHearMenuItemChecked(el)) return true;
        const leaf = el.querySelector?.('[data-automation-id="promptLeafNode"]') || el;
        const checked = leaf.getAttribute?.('data-automation-checked') || '';
        if (/^checked$/i.test(checked) && !/not checked/i.test(checked)) return true;
        const aria = el.getAttribute?.('aria-label') || '';
        return /\bchecked\b/i.test(aria) && !/\bnot checked\b/i.test(aria);
    }

    async function scrollCitizenshipVirtualItemIntoView(popup, row) {
        const scroller = getPhoneCodeListScroller(popup);
        if (!row) return null;
        // react-window style: items use position:absolute; top: Npx. scrollIntoView on the node
        // does not move the list scroller — set scrollTop from style.top, then re-query.
        const absTop = parseInt(String(row.style?.top || '').replace('px', ''), 10);
        if (scroller && Number.isFinite(absTop)) {
            scroller.scrollTop = Math.max(0, absTop - Math.floor((scroller.clientHeight || 200) / 3));
            await wait(350);
        } else {
            workdayScrollToTarget(row, 40);
            await wait(200);
        }
        return row;
    }

    function invokeWorkdayReactMouseHandlers(el, tag = '') {
        if (!el) return false;
        let invoked = 0;
        const fakeEvent = (type) => ({
            preventDefault() {},
            stopPropagation() {},
            persist() {},
            target: el,
            currentTarget: el,
            type,
            button: 0,
            buttons: 1,
            bubbles: true,
            cancelable: true,
            nativeEvent: { isTrusted: true, button: 0, buttons: 1 },
            isTrusted: true,
        });
        try {
            const propKey = Object.keys(el).find(k =>
                k.startsWith('__reactProps$') || k.startsWith('__reactEventHandlers$'));
            const props = propKey ? el[propKey] : null;
            if (props) {
                for (const name of ['onPointerDown', 'onMouseDown', 'onClick', 'onPointerUp', 'onMouseUp', 'onChange']) {
                    if (typeof props[name] === 'function') {
                        props[name](fakeEvent(name.slice(2).toLowerCase()));
                        invoked += 1;
                    }
                }
            }
            const fiberKey = Object.keys(el).find(k =>
                k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
            let fiber = fiberKey ? el[fiberKey] : null;
            let walked = 0;
            while (fiber && walked < 16) {
                const fp = fiber.memoizedProps || fiber.pendingProps;
                if (fp) {
                    for (const name of ['onClick', 'onMouseDown', 'onPointerDown', 'onChange', 'onSelect']) {
                        if (typeof fp[name] === 'function') {
                            fp[name](fakeEvent(name.slice(2).toLowerCase()));
                            invoked += 1;
                            debugLog(`${WD} citizenship react handler`, tag, name, 'depth=', walked);
                        }
                    }
                }
                fiber = fiber.return;
                walked += 1;
            }
        } catch (e) {
            debugLog(`${WD} citizenship react invoke failed`, tag, e?.message || e);
        }
        return invoked > 0;
    }

    async function expandCitizenshipCountryParent(el, activePopup) {
        const leaf = el.querySelector?.('[data-automation-id="promptLeafNode"]') || el;
        const hasCharm = leaf.getAttribute?.('data-uxi-multiselectlistitem-hassidecharm') === 'true';
        const instanceId = leaf.getAttribute?.('data-uxi-multiselectlistitem-instanceid') || '';
        const itemType = leaf.getAttribute?.('data-uxi-multiselectlistitem-type') || '';
        // type=2 + NO_METADATA_ID + side charm = country folder; must expand to Citizen/PR leaves.
        if (!hasCharm && instanceId !== 'NO_METADATA_ID' && itemType !== '2') return false;

        const charm = leaf.querySelector('[data-automation-id="promptExpansionButton"], [data-automation-id="promptSideCharm"], button[aria-expanded], [aria-label*="expand" i], [aria-label*="open" i]')
            || [...leaf.children].find(c => c.getAttribute?.('data-automation-id') !== 'promptOption')
            || leaf.lastElementChild;
        const charmHtml = (charm?.outerHTML || '').replace(/\s+/g, ' ').slice(0, 400);
        debugLog(`${WD} citizenship expand parent`, 'type=', itemType, 'instance=', instanceId.slice(0, 24),
            'charm=', charm?.tagName, charm?.getAttribute?.('data-automation-id') || '', charmHtml);

        const targets = [charm, leaf, el].filter(Boolean);
        for (const target of targets) {
            const r = target.getBoundingClientRect();
            // Side charm sits on the RIGHT of the row (hassidecharm).
            for (const x of [r.right - 12, r.right - 24, r.left + r.width * 0.9, r.left + r.width / 2]) {
                if (x < r.left || x > r.right) continue;
                const y = r.top + r.height / 2;
                const hit = document.elementFromPoint(x, y) || target;
                debugLog(`${WD} citizenship expand click`, Math.round(x - r.left), hit?.tagName,
                    hit?.getAttribute?.('data-automation-id') || '',
                    (hit?.getAttribute?.('aria-label') || '').slice(0, 40));
                workdayClickElement(hit);
                await wait(500);
                // Children appear as Citizen (Country) / Permanent Resident (Country).
                if (await trySelectCitizenChild(activePopup)) return true;
                const items = getCountryMenuItems(fieldRoot, activePopup || getCitizenshipPopup(fieldRoot) || findActiveWorkdayPopup());
                if (items.some(i => /^citizen\s*\(/i.test(i.text) || /^permanent resident\s*\(/i.test(i.text))) {
                    debugLog(`${WD} citizenship children after expand`,
                        items.filter(i => /citizen|resident/i.test(i.text)).slice(0, 8).map(i => i.text).join(' | '));
                    if (await trySelectCitizenChild(activePopup)) return true;
                }
            }
        }
        // ArrowRight commonly expands tree parents in Workday lists.
        el.focus?.();
        leaf.focus?.();
        for (const key of ['ArrowRight', 'Enter', ' ']) {
            (document.activeElement || el).dispatchEvent(new KeyboardEvent('keydown', {
                key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
            }));
            await wait(400);
            if (await trySelectCitizenChild(activePopup)) return true;
            const items = getCountryMenuItems(fieldRoot, activePopup || findActiveWorkdayPopup());
            if (items.some(i => /^citizen\s*\(/i.test(i.text))) {
                if (await trySelectCitizenChild(activePopup)) return true;
            }
        }
        return false;
    }

    async function toggleCitizenshipMultiselectItem(row, activePopup) {
        if (!row) return false;
        await scrollCitizenshipVirtualItemIntoView(activePopup, row);
        // Re-query after scroll — virtualization recycles nodes.
        const want = normalizeWorkdayMenuOptionText((row.innerText || row.getAttribute?.('aria-label') || '').trim())
            .replace(/\s+not checked$/i, '').replace(/\s+checked$/i, '');
        const live = getCountryMenuItems(fieldRoot, activePopup || getCitizenshipPopup(fieldRoot) || findActiveWorkdayPopup())
            .find(i => i.text === want || normalizeWorkdayMenuOptionText(i.el.getAttribute?.('aria-label') || '')
                .replace(/\s+not checked$/i, '') === want);
        const el = live?.el || row;
        await scrollCitizenshipVirtualItemIntoView(activePopup, el);
        const leaf = el.querySelector('[data-automation-id="promptLeafNode"]') || el;
        const prompt = el.querySelector('[data-automation-id="promptOption"]') || el;
        const rect = el.getBoundingClientRect();
        const hitProbe = document.elementFromPoint(rect.left + 14, rect.top + rect.height / 2);
        debugLog(`${WD} citizenship multiselect toggle`, want.slice(0, 60),
            'top=', el.style?.top, 'rectTop=', Math.round(rect.top), 'h=', Math.round(rect.height),
            'checked=', isCitizenshipMenuItemChecked(el),
            'type=', leaf.getAttribute?.('data-uxi-multiselectlistitem-type'),
            'charm=', leaf.getAttribute?.('data-uxi-multiselectlistitem-hassidecharm'),
            'instance=', (leaf.getAttribute?.('data-uxi-multiselectlistitem-instanceid') || '').slice(0, 24),
            'hit=', hitProbe?.tagName, hitProbe?.getAttribute?.('data-automation-id') || '');
        debugLog(`${WD} citizenship leaf html`, (leaf.outerHTML || '').replace(/\s+/g, ' ').slice(0, 900));

        // Country folders (side charm / NO_METADATA_ID) are not themselves selectable — expand first.
        if (await expandCitizenshipCountryParent(el, activePopup)) {
            debugLog(`${WD} citizenship filled via country expand`, want.slice(0, 60));
            return true;
        }

        // React synthetic handlers — some Workday multiselectlistitems ignore untrusted DOM clicks.
        for (const target of [prompt, leaf, el]) {
            if (invokeWorkdayReactMouseHandlers(target, want.slice(0, 40))) {
                await wait(350);
                if (isCitizenshipMenuItemChecked(el) || await citizenshipLooksFilled()) {
                    debugLog(`${WD} citizenship multiselect via react`, want.slice(0, 60));
                    return true;
                }
            }
        }

        // Same left-column checkbox hit target as How-did-you-hear multiselectlistitem rows.
        if (typeof clickHearCheckboxTarget === 'function') {
            if (await clickHearCheckboxTarget(el)) {
                debugLog(`${WD} citizenship multiselect via hear-checkbox`, want.slice(0, 60));
                return true;
            }
        }
        for (const target of [leaf, prompt, el]) {
            const r = target.getBoundingClientRect();
            for (const xOff of [12, 24, r.width / 2]) {
                const x = r.left + Math.min(xOff, Math.max(6, r.width - 4));
                const y = r.top + r.height / 2;
                const hit = document.elementFromPoint(x, y) || target;
                const opts = {
                    bubbles: true, cancelable: true, composed: true, view: window,
                    clientX: x, clientY: y, button: 0, buttons: 1,
                };
                hit.dispatchEvent(new PointerEvent('pointerdown', { ...opts, pointerType: 'mouse', isPrimary: true }));
                hit.dispatchEvent(new MouseEvent('mousedown', opts));
                if (typeof hit.click === 'function') hit.click();
                hit.dispatchEvent(new MouseEvent('mouseup', opts));
                hit.dispatchEvent(new PointerEvent('pointerup', { ...opts, pointerType: 'mouse', isPrimary: true }));
                hit.dispatchEvent(new MouseEvent('click', opts));
                await wait(300);
                if (isCitizenshipMenuItemChecked(el) || await citizenshipLooksFilled()) return true;
            }
        }

        // Activedescendant + Space on the field selectinput (multiselect toggle contract).
        const searchInput = getCountryPopupSearchInput(fieldRoot, activePopup);
        if (searchInput && el.id) {
            await workdayClick(searchInput);
            searchInput.focus?.();
            await wait(100);
            el.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
            el.dispatchEvent(new MouseEvent('mousemove', { bubbles: true }));
            searchInput.setAttribute('aria-activedescendant', el.id);
            for (const key of [' ', 'Enter']) {
                searchInput.dispatchEvent(new KeyboardEvent('keydown', {
                    key, code: key === ' ' ? 'Space' : 'Enter', keyCode: key === ' ' ? 32 : 13,
                    which: key === ' ' ? 32 : 13, bubbles: true, cancelable: true,
                }));
                await wait(350);
                if (isCitizenshipMenuItemChecked(el) || await citizenshipLooksFilled()) return true;
            }
        }

        el.focus?.();
        leaf.focus?.();
        try { el.setAttribute('tabindex', '0'); } catch (_) { /* ignore */ }
        for (const key of [' ', 'Enter']) {
            const ev = {
                key, code: key === ' ' ? 'Space' : 'Enter', keyCode: key === ' ' ? 32 : 13,
                which: key === ' ' ? 32 : 13, bubbles: true, cancelable: true,
            };
            (document.activeElement || el).dispatchEvent(new KeyboardEvent('keydown', ev));
            (document.activeElement || el).dispatchEvent(new KeyboardEvent('keyup', ev));
            await wait(350);
            if (isCitizenshipMenuItemChecked(el) || await citizenshipLooksFilled()) return true;
        }
        return isCitizenshipMenuItemChecked(el) || await citizenshipLooksFilled();
    }

    async function trySelectCitizenChild(activePopup) {
        // After picking a country, Workday often expands to Citizen / Permanent Resident leaves
        // (cabrini.wd3 / sggovterp.wd102). Prefer the Citizen leaf for the profile country.
        // Never treat a bare country row ("United States of America" / territories) as the leaf.
        const isCitizenLeafText = (t) => /^citizen\s*\(/i.test(String(t || ''))
            || /^permanent resident\s*\(/i.test(String(t || ''));
        for (let i = 0; i < 6; i++) {
            const pop = getCitizenshipPopup(fieldRoot) || findCountryPopup(fieldRoot) || activePopup
                || findActiveWorkdayPopup();
            const citizenOpt = findCitizenshipStatusOption(fieldRoot, pop, profile);
            if (citizenOpt && isCitizenLeafText(citizenOpt.text)
                && !isUsTerritoryCountryOptionText(citizenOpt.text)) {
                debugLog(`${WD} citizenship country-picker citizen leaf`, citizenOpt.text?.slice(0, 80));
                if (await selectCitizenshipStatusOption(fieldRoot, profile, citizenOpt)) return true;
            }
            const items = getCountryMenuItems(fieldRoot, pop);
            const leaf = items.find(it => isCitizenLeafText(it.text)
                && !isUsTerritoryCountryOptionText(it.text)
                && countryOptionMatches(it.text.replace(/^(citizen|permanent resident)\s*\(|\)\s*$/gi, ''), candidates));
            if (leaf) {
                debugLog(`${WD} citizenship country-picker citizen leaf click`, leaf.text);
                if (await toggleCitizenshipMultiselectItem(leaf.el, pop) || await citizenshipLooksFilled()) {
                    return true;
                }
                workdayClickElement(leaf.el);
                await wait(400);
                if (await citizenshipLooksFilled()) return true;
            }
            await wait(350);
        }
        return false;
    }

    async function trySelectMatch(match, activePopup) {
        if (!match?.el) return false;
        debugLog(`${WD} citizenship country-picker select`, match.text);
        // Re-query by text — virtualized lists recycle nodes between scroll-find and click.
        const fresh = getCountryMenuItems(fieldRoot, activePopup || getCitizenshipPopup(fieldRoot) || findActiveWorkdayPopup())
            .find(i => i.text === match.text)
            || match;
        const row = fresh.el.closest(
            '[data-automation-id="menuItem"], [data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"], li',
        ) || fresh.el;
        await dumpCitizenshipOptionRow(row, 'before-click');

        // Expand parent country nodes when the list is a tree (aria-expanded=false).
        if (row.getAttribute?.('aria-expanded') === 'false') {
            const expander = row.querySelector('[data-automation-id="promptExpansionButton"], button[aria-expanded="false"], [aria-label*="expand" i]')
                || row;
            workdayClickElement(expander);
            await wait(500);
            await dumpCitizenshipOptionRow(row, 'after-expand');
            if (await trySelectCitizenChild(activePopup)) {
                await dismissWorkdayFieldDropdown(fieldRoot, openKey);
                return citizenshipLooksFilled();
            }
        }

        // sggovterp.wd102: multiselectlistitem with aria-label="… not checked" — toggle like hear checkboxes.
        const ariaLabel = row.getAttribute?.('aria-label') || '';
        const isMsItem = /not checked|checked/i.test(ariaLabel)
            || row.querySelector?.('[data-uxi-widget-type="multiselectlistitem"], [data-automation-checked]');
        if (isMsItem) {
            const toggled = await toggleCitizenshipMultiselectItem(row, activePopup);
            debugLog(`${WD} citizenship country-picker multiselect toggle`, toggled, match.text);
            await dumpCitizenshipOptionRow(
                getCountryMenuItems(fieldRoot, activePopup).find(i => i.text === match.text)?.el || row,
                'after-multiselect-toggle',
            );
            if (toggled || await citizenshipLooksFilled()) {
                // fall through to citizen-leaf / confirm
            } else {
                // continue with legacy click paths below
            }
        }

        if (!(await citizenshipLooksFilled()) && !isCitizenshipMenuItemChecked(row)) {
        const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]')
            || row.closest('[data-automation-id="promptOption"]')?.querySelector('input[type="checkbox"], [role="checkbox"]');
        if (checkbox) {
            const ok = await workdayClickCheckbox(checkbox);
            debugLog(`${WD} citizenship country-picker checkbox`, ok, match.text);
            await wait(400);
        } else if (!isMsItem) {
            const textNode = [...row.querySelectorAll('div, span, p')]
                .reverse()
                .find(el => normalizeWorkdayMenuOptionText((el.innerText || '').trim()) === match.text)
                || row;
            workdayClickElement(textNode);
            await wait(300);
            workdayClickElement(row);
            await wait(400);
        }
        }
        await dumpCitizenshipOptionRow(
            getCountryMenuItems(fieldRoot, activePopup).find(i => i.text === match.text)?.el || row,
            'after-click',
        );

        // Country click may reveal Citizen (<Country>) — select that before closing.
        if (await trySelectCitizenChild(activePopup)) {
            const confirmBtn = [...(activePopup || document).querySelectorAll('button, [role="button"]')]
                .find(b => /^(done|ok|apply|confirm|save)$/i.test((b.innerText || b.textContent || '').trim())
                    && isVisibleElement(b));
            if (confirmBtn) {
                debugLog(`${WD} citizenship country-picker confirm`, (confirmBtn.innerText || '').trim());
                await workdayClick(confirmBtn);
                await wait(600);
            } else {
                await dismissWorkdayFieldDropdown(fieldRoot, openKey);
                await wait(500);
            }
            const filled = await citizenshipLooksFilled();
            debugLog(`${WD} citizenship country-picker after citizen leaf`, 'filled=', filled,
                'selected=', getWorkdayFieldSelectedText(fieldRoot).slice(0, 60));
            return filled;
        }

        // Multi-select prompts often only commit after Done/OK or closing the popup
        // (sggovterp.wd102 Citizenship Status). Do not call commitCountryMenuSelection —
        // it waits on isCountryFilled and burns ~70s without committing citizenship chips.
        const confirmBtn = [...(activePopup || document).querySelectorAll('button, [role="button"]')]
            .find(b => /^(done|ok|apply|confirm|save)$/i.test((b.innerText || b.textContent || '').trim())
                && isVisibleElement(b));
        if (confirmBtn) {
            debugLog(`${WD} citizenship country-picker confirm`, (confirmBtn.innerText || '').trim());
            await workdayClick(confirmBtn);
            await wait(600);
        } else {
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            await wait(500);
        }
        const filled = await citizenshipLooksFilled();
        debugLog(`${WD} citizenship country-picker after select`, match.text, 'filled=', filled,
            'selected=', getWorkdayFieldSelectedText(fieldRoot).slice(0, 60));
        return filled;
    }

    dumpCitizenshipFieldChrome('closed');
    for (let attempt = 0; attempt < 2; attempt++) {
        const activePopup = attempt === 0 && popup ? popup : await openPopup();
        if (!activePopup) continue;
        dumpCitizenshipFieldChrome(`opened-${attempt}`);

        // Search on this tenant does not filter (value sets, list stays A*). Scroll + checkbox toggle.
        const scrollMatch = await scrollWorkdayMenuListForMatch(
            fieldRoot,
            activePopup,
            (root) => getCountryMenuItems(root, activePopup),
            (items) => findCountryMatchInItems(items, profile)
                || items.find(i => profileExpectsUS(profile) && /^united states( of america)?$/i.test(i.text)
                    && !isUsTerritoryCountryOptionText(i.text)),
            'citizenship-country',
            100,
        );
        if (scrollMatch && await trySelectMatch(scrollMatch, activePopup)) {
            debugLog(`${WD} citizenship country-picker filled via scroll`, scrollMatch.text);
            return true;
        }
        if (scrollMatch) {
            debugLog(`${WD} citizenship country-picker scroll matched but not filled`, scrollMatch.text);
        }

        await dismissWorkdayFieldDropdown(fieldRoot, openKey);
    }

    // Prefer long country labels only — abbreviations like "US" substring-match "Australia".
    const longCountryCandidates = candidates.filter(c => String(c).trim().length >= 4);
    if (await fillWorkdaySingleSelectDropdown(trigger, longCountryCandidates.length ? longCountryCandidates : candidates, openKey)
        && isCitizenshipFilled(fieldRoot, profile)) {
        debugLog(`${WD} citizenship country-picker filled via single-select`);
        return true;
    }
    return isCitizenshipFilled(fieldRoot, profile);
}

async function fillWorkdayCitizenshipDropdown(fieldRoot, profile, popup) {
    if (isCitizenshipFilled(fieldRoot, profile)) return true;
    clearWorkdaySingleSelectMissKey('citizenship status');
    resetWorkdayDropdownOpenCount('citizenship status');

    const inlineCandidates = [
        ...getCitizenshipRadioCandidates(profile),
        'US Citizen', 'U.S. Citizen', 'United States Citizen', 'A citizen of the United States',
        ...getCitizenshipSearchTerms(profile),
    ];
    if (await fillWorkdayExclusiveCheckboxGroup(fieldRoot, inlineCandidates, { label: 'citizenship status' })) {
        if (isCitizenshipFilled(fieldRoot, profile)) {
            debugLog(`${WD} citizenship filled via inline checkbox group`);
            return true;
        }
    }

    const activePopup = getCitizenshipPopup(fieldRoot) || popup;
    const resultsVisible = /search results/i.test(activePopup?.innerText || '');

    if (resultsVisible) {
        debugLog(`${WD} citizenship results visible, select only`);
        if (await trySelectCitizenshipFromResults(fieldRoot, profile, activePopup)) {
            debugLog(`${WD} citizenship filled from existing results`);
            return true;
        }
        return isCitizenshipFilled(fieldRoot, profile);
    }

    if (await trySelectCitizenshipFromResults(fieldRoot, profile, activePopup)) {
        debugLog(`${WD} citizenship filled from existing results`);
        return true;
    }

    const trigger = getWorkdayDropdownTrigger(fieldRoot) || getContainerControl(fieldRoot);
    if (trigger) {
        await closeWorkdayPopups();
        await wait(200);
        trackWorkdayDropdownOpen(getCountryDropdownOpenKey(fieldRoot));
        await workdayClick(trigger);
        await wait(1200);
        let openedPopup = getCitizenshipPopup(fieldRoot) || findPopupNearField(fieldRoot, 'citizenship status') || findActiveWorkdayPopup();
        logCitizenshipPopupOptions(fieldRoot, openedPopup, 'opened');
        if (citizenshipPopupLooksLikeCountryPicker(openedPopup)) {
            return fillWorkdayCitizenshipCountryPicker(fieldRoot, profile, openedPopup);
        }
        if (await trySelectCitizenshipFromResults(fieldRoot, profile, openedPopup)) {
            debugLog(`${WD} citizenship filled from opened popup`);
            return true;
        }

        const searchInput = getCountryPopupSearchInput(fieldRoot, openedPopup);
        if (searchInput) {
            for (const term of getCitizenshipSearchTerms(profile)) {
                debugLog(`${WD} citizenship search type`, term);
                await workdayClick(searchInput);
                await wait(150);
                await workdayTypeSearchInput(searchInput, term);
                await wait(500);
                await submitWorkdaySearchInput(searchInput);
                openedPopup = getCitizenshipPopup(fieldRoot) || findActiveWorkdayPopup();
                logCitizenshipPopupOptions(fieldRoot, openedPopup, `search:${term}`);
                if (await trySelectCitizenshipFromResults(fieldRoot, profile, openedPopup)) {
                    debugLog(`${WD} citizenship filled after search`, term);
                    return true;
                }
            }
            debugLog(`${WD} citizenship select failed after all search terms`);
        } else {
            debugLog(`${WD} citizenship search input not found`);
        }
    }

    if (trigger && await fillWorkdayCitizenshipSingleSelectFallback(trigger, fieldRoot, profile, inlineCandidates)) {
        debugLog(`${WD} citizenship filled via single-select fallback`);
        return isCitizenshipFilled(fieldRoot, profile);
    }
    return isCitizenshipFilled(fieldRoot, profile);
}

async function fillWorkdayCitizenshipSingleSelectFallback(trigger, fieldRoot, profile, candidates) {
    await closeWorkdayPopups();
    await wait(300);
    trackWorkdayDropdownOpen('citizenship status');
    await workdayClick(trigger);
    await wait(1200);
    const popup = getCitizenshipPopup(fieldRoot) || findPopupNearField(fieldRoot, 'citizenship status') || findActiveWorkdayPopup();
    logCitizenshipPopupOptions(fieldRoot, popup, 'single-select-fallback');
    if (await trySelectCitizenshipFromResults(fieldRoot, profile, popup)) return true;

    for (const candidate of candidates) {
        const searchInput = getCountryPopupSearchInput(fieldRoot, popup);
        if (searchInput) {
            await workdayClick(searchInput);
            await wait(150);
            await workdayTypeSearchInput(searchInput, candidate);
            await wait(500);
            await submitWorkdaySearchInput(searchInput);
        }
        if (await trySelectCitizenshipFromResults(fieldRoot, profile, getCitizenshipPopup(fieldRoot) || popup)) {
            return true;
        }
    }
    return isCitizenshipFilled(fieldRoot, profile);
}

function getCountryDropdownOpenKey(fieldRoot) {
    const label = getContainerLabel(fieldRoot);
    return isCitizenshipFieldLabel(label) ? normalizeDropdownOpenKey(label) : 'country';
}

async function commitCountryMenuSelection(fieldRoot, profile, popup, match) {
    if (!match?.el) return false;
    const filledCheck = () => isCountryFilled(fieldRoot, profile);
    if (filledCheck()) return true;

    const combobox = getCountryPopupSearchInput(fieldRoot, popup);
    workdayScrollToTarget(match.el, 80);
    await wait(150);
    match.el.focus?.();
    await wait(100);

    const optionEl = match.el.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"], [data-automation-id="menuItem"]')
        || match.el;
    const displayText = match.text || normalizeWorkdayMenuOptionText(optionText(optionEl));

    if (optionEl.getAttribute?.('data-value') || extractWorkdayOptionValue(optionEl)) {
        workdayClickElement(optionEl);
        await wait(400);
        if (combobox) await commitWorkdayComboboxSelection(fieldRoot, combobox, optionEl, displayText);
        if (filledCheck()) return true;
    }

    const clickTargets = [
        optionEl.querySelector('[data-automation-id="promptLeafNode"] div'),
        optionEl.querySelector('[data-automation-id="promptLeafNode"]'),
        optionEl.querySelector('[data-automation-id="promptOption"]'),
        optionEl.querySelector('label'),
        optionEl,
        match.el,
    ].filter(Boolean);

    for (const target of clickTargets) {
        await workdayClick(target);
        await wait(350);
        if (combobox) await commitWorkdayComboboxSelection(fieldRoot, combobox, optionEl, displayText);
        if (filledCheck()) return true;
    }

    for (const key of ['Enter', ' ']) {
        optionEl.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(400);
        if (combobox) await commitWorkdayComboboxSelection(fieldRoot, combobox, optionEl, displayText);
        if (filledCheck()) return true;
    }

    return filledCheck();
}

function findCountryPopup(fieldRoot) {
    const rect = fieldRoot?.getBoundingClientRect();
    return findVisibleWorkdayPopups()
        .filter(p => !isPhoneCodePopup(p))
        .filter(p => {
            const sample = getUniqueHearOptions(p).slice(0, 6).map(o => o.text).join(' ');
            if (isPhoneCodePopup(p) || /\(\+\d{1,4}\)/.test(sample)) return false;
            return true;
        })
        .filter(p => {
            if (!rect) return true;
            const pr = p.getBoundingClientRect();
            return pr.top >= rect.top - 120
                && pr.top <= rect.bottom + 800
                && pr.left >= rect.left - 160
                && pr.left <= rect.right + 1000;
        })[0] || null;
}

async function walkWorkdayMenuListForMatch(fieldRoot, popup, matchFn, logTag = 'menu') {
    const firstItem = popup.querySelector('[data-automation-id="menuItem"], [role="option"]');
    if (!firstItem) return null;

    firstItem.focus();
    await wait(200);

    let lastText = '';
    for (let i = 0; i < 280; i++) {
        const active = document.activeElement;
        if (active && (active.getAttribute('data-automation-id') === 'menuItem' || active.getAttribute('role') === 'option')) {
            const text = normalizeWorkdayMenuOptionText(active.getAttribute('aria-label') || active.innerText || '');
            if (text && text !== lastText) {
                lastText = text;
                if (matchFn(text, active)) {
                    debugLog(`${WD} ${logTag} found by arrow`, text, 'step=', i);
                    return { el: active, text };
                }
            }
        }

        const keyTarget = document.activeElement || firstItem;
        keyTarget.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
        keyTarget.dispatchEvent(new KeyboardEvent('keyup', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true }));
        await wait(60);
    }
    return null;
}

async function scrollWorkdayMenuListForMatch(fieldRoot, popup, getItems, findMatch, logTag = 'menu', maxSteps = 50) {
    let match = findMatch(getItems(fieldRoot));
    if (match) return match;

    const scroller = getPhoneCodeListScroller(popup);
    if (!scroller) return null;

    scroller.scrollTop = 0;
    await wait(250);
    let lastTop = -1;

    for (let step = 0; step < maxSteps; step++) {
        match = findMatch(getItems(fieldRoot));
        if (match) {
            debugLog(`${WD} ${logTag} found by scroll`, match.text, 'step=', step);
            return match;
        }

        const nextTop = Math.min(
            scroller.scrollTop + Math.max(scroller.clientHeight * 0.8, 100),
            scroller.scrollHeight,
        );
        if (nextTop === lastTop) break;
        scroller.scrollTop = nextTop;
        lastTop = nextTop;
        await wait(250);
    }
    return findMatch(getItems(fieldRoot));
}

function normalizeMenuOptionText(text) {
    return normalizeWorkdayMenuOptionText(text);
}

function textMatchesCandidate(text, candidate) {
    const fold = (s) => String(s || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/['’`]/g, '')
        .replace(/\bdon t\b/gi, 'do not')
        .replace(/\bdont\b/gi, 'do not')
        .toLowerCase();
    const t = fold(normalizeMenuOptionText(text));
    const c = fold(normalizeMenuOptionText(candidate));
    if (!t || !c || t === 'select one') return false;
    if (t === c) return true;
    // Short candidates (Yes/No) must match whole words — avoids "No" → "Non-Speaker"
    if (c.length <= 3) {
        return new RegExp(`\\b${c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(t);
    }
    if (t.includes(c) || c.includes(t)) return true;
    const words = c.split(/\s+/).filter(w => w.length > 2);
    return words.length >= 2 && words.every(w => t.includes(w));
}

function getGenericMenuItems(fieldRoot) {
    return getAllHearMenuItems(fieldRoot)
        .filter(o => !isPhoneCodeOptionText(o.text))
        .map(o => ({ el: o.el, text: normalizeMenuOptionText(o.text) }))
        .filter(o => o.text && o.text.length < 120);
}

function findMenuMatchInItems(items, candidates) {
    for (const candidate of candidates) {
        for (const item of items) {
            if (textMatchesCandidate(item.text, candidate)) {
                return { el: item.el, text: item.text, candidate };
            }
        }
    }
    return null;
}

async function findScrollMenuOption(fieldRoot, popup, candidates, logTag) {
    const findMatch = (items) => findMenuMatchInItems(items, candidates);
    let match = findMatch(getGenericMenuItems(fieldRoot));
    if (match) {
        debugLog(`${WD} ${logTag} visible`, match.text);
        return match;
    }
    match = await walkWorkdayMenuListForMatch(fieldRoot, popup, (text) =>
        candidates.some(c => textMatchesCandidate(text, c)), logTag);
    if (match) return match;
    return scrollWorkdayMenuListForMatch(fieldRoot, popup, getGenericMenuItems, findMatch, logTag);
}

async function selectWorkdayMenuOptionByKeyboard(fieldRoot, popup, candidates, logTag) {
    const firstItem = popup?.querySelector('[data-automation-id="menuItem"], [role="option"]');
    if (!firstItem) return false;
    firstItem.focus();
    await wait(200);
    let lastText = '';
    for (let i = 0; i < 320; i++) {
        const active = document.activeElement;
        if (active && (active.getAttribute('data-automation-id') === 'menuItem' || active.getAttribute('role') === 'option')) {
            const text = normalizeWorkdayMenuOptionText(active.getAttribute('aria-label') || active.innerText || '');
            if (text && text !== lastText) {
                lastText = text;
                if (candidates.some(c => textMatchesCandidate(text, c))) {
                    debugLog(`${WD} ${logTag} found by arrow`, text);
                    for (const key of [' ', 'Enter']) {
                        active.dispatchEvent(new KeyboardEvent('keydown', {
                            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
                        }));
                        await wait(450);
                    }
                    return true;
                }
            }
        }
        const keyTarget = document.activeElement || firstItem;
        keyTarget.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
        await wait(55);
    }
    return false;
}

async function fillWorkdayScrollMultiSelect(element, candidates, { isFilledFn, logTag, fieldLabel = '' } = {}) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    if (isFilledFn?.(fieldRoot)) return true;
    const trigger = getWorkdayDropdownTrigger(fieldRoot) || element;
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    if (!vals.length) return false;

    for (let attempt = 0; attempt < 2; attempt++) {
        await closeWorkdayPopups();
        await wait(300);
        workdayScrollToTarget(fieldRoot, 120);
        trackWorkdayDropdownOpen(fieldLabel || logTag);
        await workdayClick(trigger);
        await wait(1500);

        const popup = findPopupNearField(fieldRoot, fieldLabel || logTag) || findActiveWorkdayPopup();
        if (!popup) continue;

        const match = await findScrollMenuOption(fieldRoot, popup, vals, logTag);
        if (!match) {
            await dismissWorkdayFieldDropdown(fieldRoot);
            continue;
        }

        debugLog(`${WD} ${logTag} selecting`, match.text);
        match.el.focus?.();
        await wait(200);
        for (const key of [' ', 'Enter']) {
            match.el.dispatchEvent(new KeyboardEvent('keydown', {
                key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
            }));
            await wait(450);
            if (isFilledFn(fieldRoot)) {
                debugLog(`${WD} ${logTag} filled via keyboard on match`, match.text);
                await dismissWorkdayFieldDropdown(fieldRoot);
                return true;
            }
        }
        if (await clickWorkdayMenuItem(match.el, fieldRoot, () => isFilledFn(fieldRoot))) {
            await wait(800);
            await dismissWorkdayFieldDropdown(fieldRoot);
            if (isFilledFn(fieldRoot)) {
                debugLog(`${WD} ${logTag} filled`, match.text);
                return true;
            }
        }
        if (await selectWorkdayMenuOptionByKeyboard(fieldRoot, popup, vals, logTag)) {
            await wait(800);
            await dismissWorkdayFieldDropdown(fieldRoot);
            if (isFilledFn(fieldRoot)) {
                debugLog(`${WD} ${logTag} filled via keyboard`, match.text);
                return true;
            }
        }
        await dismissWorkdayFieldDropdown(fieldRoot);
    }
    return false;
}

async function findCountryOption(fieldRoot, profile, popup, { allowCitizenshipCountryPicker = false } = {}) {
    const findMatch = (items) => findCountryMatchInItems(items, profile);
    const findStart = Date.now();

    if (!allowCitizenshipCountryPicker && isCitizenshipFieldLabel(getContainerLabel(fieldRoot))) {
        return null;
    }

    let match = findMatch(getCountryMenuItems(fieldRoot, popup));
    if (match) {
        logCountryPhase('find-visible', match.text, 'findMs=', Date.now() - findStart);
        return match;
    }

    match = findCountryInSingleSelectOptions(popup, profile);
    if (match) {
        logCountryPhase('find-prompt-option', match.text, 'findMs=', Date.now() - findStart);
        return match;
    }

    match = await tryCountryComboboxFilter(fieldRoot, profile, popup);
    if (match) {
        logCountryPhase('find-combobox-filter', match.text, 'findMs=', Date.now() - findStart);
        return match;
    }

    for (const term of getExpectedCountryCandidates(profile)) {
        match = await tryWorkdayDropdownSearch(popup, fieldRoot, term, (root) => getCountryMenuItems(root, popup), findMatch, 'country');
        if (match) {
            logCountryPhase('find-search-box', match.text, 'findMs=', Date.now() - findStart);
            return match;
        }
        match = findCountryInSingleSelectOptions(findCountryPopup(fieldRoot) || popup, profile);
        if (match) {
            logCountryPhase('find-search-prompt', match.text, 'findMs=', Date.now() - findStart);
            return match;
        }
    }

    match = await tryCountryKeyboardTypeahead(fieldRoot, profile, popup);
    if (match) {
        logCountryPhase('find-typeahead', match.text, 'findMs=', Date.now() - findStart);
        return match;
    }

    if (allowCitizenshipCountryPicker || (wdDropdownOpenCounts.country || 0) <= 2) {
        const scrollSteps = allowCitizenshipCountryPicker ? 100 : 6;
        match = await scrollWorkdayMenuListForMatch(
            fieldRoot, popup, (root) => getCountryMenuItems(root, popup), findMatch, 'country', scrollSteps,
        );
        if (match) {
            logCountryPhase('find-scroll-limited', match.text, 'findMs=', Date.now() - findStart, 'steps=', scrollSteps);
            return match;
        }
    }

    logCountryPhase('find-not-found', getCountryMenuItems(fieldRoot, popup).slice(0, 6).map(o => o.text).join('|'), 'findMs=', Date.now() - findStart);
    return null;
}

async function clickWorkdayMenuItem(opt, fieldRoot, isFilledFn) {
    if (!opt) return false;
    const pillBefore = getWorkdayFieldSelectedText(fieldRoot);
    const clickTargets = [
        opt.querySelector('input[type="checkbox"]'),
        opt.querySelector('[role="checkbox"]'),
        opt.querySelector('[data-automation-id="promptLeafNode"]'),
        opt.querySelector('[data-automation-id="promptOption"]'),
        opt.querySelector('label'),
        opt,
    ].filter(Boolean);

    for (const target of clickTargets) {
        await workdayClick(target);
        await wait(450);
        if (isFilledFn()) return true;
        if (getWorkdayFieldSelectedText(fieldRoot) !== pillBefore && isFilledFn()) return true;
    }

    opt.focus();
    for (const key of [' ', 'Enter']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(450);
        if (isFilledFn()) return true;
    }
    return isFilledFn();
}

async function dismissWorkdayFieldDropdown(fieldRoot, fieldKey = 'unknown') {
    trackWorkdayDropdownClose(fieldKey, 'dismiss-field', getContainerLabel(fieldRoot).slice(0, 40));
    const combobox = fieldRoot?.querySelector('input[role="combobox"]');
    if (combobox) {
        combobox.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(300);
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2, [data-automation-id="applicationHeader"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(300);
    }
}

async function dumpWorkdayCountryDropdownOptions(fieldRoot) {
    if (window.__wdCountryDumpDone) return window.__wdCountryDumpList || [];
    window.__wdCountryDumpDone = true;

    const trigger = getWorkdayDropdownTrigger(fieldRoot);
    if (!trigger) {
        debugLog(`${WD} country dump skipped`, 'no trigger');
        return [];
    }

    const seen = new Set();
    const addItems = () => {
        for (const item of getCountryMenuItems(fieldRoot, popup)) {
            if (!item.text || seen.has(item.text)) continue;
            seen.add(item.text);
            debugLog(`${WD} country dump item`, item.text);
        }
    };

    await closeWorkdayPopups();
    await wait(300);
    workdayScrollToTarget(fieldRoot, 120);
    await workdayClick(trigger);
    await wait(1500);

    const popup = findCountryPopup(fieldRoot) || findPopupNearField(fieldRoot, 'country');
    if (!popup) {
        debugLog(`${WD} country dump skipped`, 'no popup');
        return [];
    }

    addItems();

    const scroller = getPhoneCodeListScroller(popup);
    if (scroller) {
        scroller.scrollTop = 0;
        await wait(250);
        let lastTop = -1;
        for (let step = 0; step < 60; step++) {
            addItems();
            const nextTop = Math.min(
                scroller.scrollTop + Math.max(scroller.clientHeight * 0.85, 120),
                scroller.scrollHeight,
            );
            if (nextTop === lastTop) break;
            scroller.scrollTop = nextTop;
            lastTop = nextTop;
            await wait(200);
        }
        addItems();
    }

    const firstItem = popup.querySelector('[data-automation-id="menuItem"], [role="option"]');
    if (firstItem) {
        firstItem.focus();
        await wait(200);
        let lastText = '';
        for (let i = 0; i < 300; i++) {
            const active = document.activeElement;
            if (active && (active.getAttribute('data-automation-id') === 'menuItem' || active.getAttribute('role') === 'option')) {
                const text = normalizeWorkdayMenuOptionText(active.getAttribute('aria-label') || active.innerText || '');
                if (text && !isPhoneCodeOptionText(text) && text !== lastText) {
                    lastText = text;
                    if (!seen.has(text)) {
                        seen.add(text);
                        debugLog(`${WD} country dump item`, text);
                    }
                }
            }
            const keyTarget = document.activeElement || firstItem;
            keyTarget.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
            await wait(50);
        }
    }

    const list = [...seen].sort();
    window.__wdCountryDumpList = list;
    debugLog(`${WD} country dump complete`, list.length);
    for (const name of list) {
        debugLog(`${WD} country dump all`, name);
    }
    await dismissWorkdayFieldDropdown(fieldRoot);
    return list;
}

async function fillWorkdayCountryDropdown(element, profile) {
    wdCountryTimingStart = Date.now();
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const candidates = getExpectedCountryCandidates(profile);
    logCountryPhase('start', 'target=', candidates[0], 'current=', getWorkdayFieldSelectedText(fieldRoot).slice(0, 60));

    if (isCountryFilled(fieldRoot, profile)) {
        logCountryPhase('already-filled', getWorkdayFieldSelectedText(fieldRoot).slice(0, 40));
        return true;
    }

    // "0 items selected" on an optional country/nationality multi-select (e.g. "Additional
    // Nationalities" — for OTHER nationalities beyond the primary one) is itself a valid, already-answered
    // empty state, not a miss to retry. Every caller of fillWorkdayCountryDropdown (generic
    // fillWorkdayDropdownOnce dispatch, fillApplicationQuestions local fallback, etc.) funnels through
    // here, so guarding centrally covers all of them at once. Without this, the multi-select combobox's
    // own typeahead never actually matches "United States of America" (its filtered results kept showing
    // the SAME default list regardless of typed text — observed on pwc.wd3), so every attempt failed and
    // retried up to the tracked-open cap, burning ~20s per open across 10+ opens and timing out the whole
    // disclosures/questions step. Not tenant-specific: any tenant with an optional multi-select
    // country/nationality field the model streams the primary country into hits this.
    if (!isContainerRequired(fieldRoot) && /0 items selected/i.test(fieldRoot?.innerText || '')) {
        logCountryPhase('skip-optional-empty-multiselect');
        return true;
    }

    if (window.__wdDumpCountries) {
        await dumpWorkdayCountryDropdownOptions(fieldRoot);
    }

    const trigger = getWorkdayDropdownTrigger(fieldRoot) || element;
    const openKey = getCountryDropdownOpenKey(fieldRoot);
    const isCitizenship = isCitizenshipFieldLabel(getContainerLabel(fieldRoot));

    if (isCitizenship) {
        logCountryPhase('citizenship-flow-start');
        workdayScrollToTarget(fieldRoot, 120);
        let popup = getCitizenshipPopup(fieldRoot) || findPopupNearField(fieldRoot, openKey);
        if (!popup) {
            await closeWorkdayPopups();
            await wait(200);
            trackWorkdayDropdownOpen(openKey);
            await workdayClick(trigger);
            await wait(1200);
            popup = getCitizenshipPopup(fieldRoot) || findPopupNearField(fieldRoot, openKey);
        }
        if (await fillWorkdayCitizenshipDropdown(fieldRoot, profile, popup)) {
            logCountryPhase('citizenship-flow-done', getWorkdayFieldSelectedText(fieldRoot).slice(0, 60));
            return true;
        }
        return isCitizenshipFilled(fieldRoot, profile);
    }

    logCountryPhase('try-single-select-fast');
    const fastStart = Date.now();
    if (await fillWorkdaySingleSelectDropdown(trigger, candidates, openKey) && isCountryFilled(fieldRoot, profile)) {
        logCountryPhase('done-single-select-fast', getWorkdayFieldSelectedText(fieldRoot).slice(0, 40), 'phaseMs=', Date.now() - fastStart);
        return true;
    }
    logCountryPhase('single-select-fast-miss', 'phaseMs=', Date.now() - fastStart);

    for (let attempt = 0; attempt < 2; attempt++) {
        logCountryPhase('popup-attempt', attempt + 1);
        const openStart = Date.now();
        await closeWorkdayPopups();
        await wait(200);
        workdayScrollToTarget(fieldRoot, 120);
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(trigger);
        await wait(1200);
        logCountryPhase('popup-opened', 'openMs=', Date.now() - openStart);

        const popup = findCountryPopup(fieldRoot) || findPopupNearField(fieldRoot, openKey);
        if (!popup) {
            logCountryPhase('popup-missing', attempt + 1);
            continue;
        }

        const findStart = Date.now();
        const match = await findCountryOption(fieldRoot, profile, popup);
        logCountryPhase('find-done', match?.text || 'none', 'findMs=', Date.now() - findStart);
        if (!match) {
            await dismissWorkdayFieldDropdown(fieldRoot, openKey);
            continue;
        }

        logCountryPhase('selecting', match.text);
        const clickStart = Date.now();
        if (await commitCountryMenuSelection(fieldRoot, profile, popup, match)) {
            await wait(600);
            const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
            if (pageTitle) await workdayClick(pageTitle);
            await wait(400);
            if (isCountryFilled(fieldRoot, profile)) {
                logCountryPhase('done-popup-click', match.text, 'clickMs=', Date.now() - clickStart);
                return true;
            }
        }
        logCountryPhase('click-not-committed', getWorkdayFieldSelectedText(fieldRoot).slice(0, 40), 'clickMs=', Date.now() - clickStart);
        await dismissWorkdayFieldDropdown(fieldRoot, openKey);
    }

    logCountryPhase('fallback-single-select');
    const fallbackStart = Date.now();
    const fallback = await fillWorkdaySingleSelectDropdown(trigger, candidates, openKey)
        || await fillWorkdayDropdown(trigger, candidates);
    const ok = fallback && isCountryFilled(fieldRoot, profile);
    logCountryPhase('done', ok ? 'success' : 'failed', getWorkdayFieldSelectedText(fieldRoot).slice(0, 40), 'fallbackMs=', Date.now() - fallbackStart);
    return ok;
}

function isWrongCountryPreview(preview, profile) {
    const p = String(preview || '').replace(/\s+/g, ' ');
    if (jobLocationExpectsJapanResidency() && /\bjapan\b/i.test(p)) return false;
    if (profileExpectsUS(profile) && /united states/i.test(p)) return false;
    if (/\bgeorgia\b/i.test(p) && !/\bcalifornia\b/i.test(p) && !/united states/i.test(p)) return true;
    if (/\+995/.test(p)) return true;
    if (profileExpectsUS(profile)) {
        if (/\b(china|afghanistan|armenia|india|ukraine|belgium|netherlands|georgia)\b/i.test(p) && !/united states/i.test(p)) {
            return true;
        }
    }
    return false;
}

function isCountryFilled(container, profile) {
    if (!container) return false;
    profile = getProfileForJobLocation(profile);
    if (isCitizenshipFieldLabel(getContainerLabel(container))) {
        return isCitizenshipFilled(container, profile);
    }
    const preview = getWorkdayFieldSelectedText(container) || container.innerText || '';
    if (/select one|0 items selected|is required and must have a value/i.test(preview)) return false;
    if (container.querySelector('[data-automation-id="errorMessage"], [data-automation-id*="validationError"]')) return false;
    const workdayName = getWorkdayCountryName(profile).toLowerCase();
    const fieldOnly = (container.innerText || '').replace(/\s+/g, ' ');
    if (new RegExp(`Country\\s*\\*?\\s*${workdayName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i').test(fieldOnly)) {
        return true;
    }
    if (isWrongCountryPreview(preview, profile)) return false;
    const selected = getWorkdayFieldSelectedText(container).toLowerCase();
    if (selected && (selected === workdayName || selected.includes(workdayName))) {
        return true;
    }
    return countryOptionMatches(selected, getExpectedCountryCandidates(profile));
}

function isPhoneCodeFilledForProfile(container, profile) {
    if (!container) return false;
    const preview = normalizeWorkdayDropdownSelectedText(
        getWorkdayFieldSelectedText(container) || (container.innerText || '').replace(/\s+/g, ' '),
    );
    if (/^select one$/i.test(preview) || !preview) return false;
    if (/georgia \(\+995\)/i.test(preview)) return false;
    if (/\+995/.test(preview) && !/\+1\b/.test(preview)) return false;
    if (profileExpectsUS(profile)) {
        return isUSMainlandPhoneCodeOption(preview);
    }
    if (jobLocationExpectsJapanResidency()) {
        return /japan.*\(\+81\)/i.test(preview) || (/\(\+81\)/.test(preview) && /japan/i.test(preview));
    }
    // Universal: committed value shows the profile dial code (works for any country).
    if (previewContainsProfileDialCode(preview, profile)) return true;
    if (phoneCodeOptionMatches(preview, profile)) return true;
    return getExpectedPhoneCodeCandidates(profile).some(c => textMatchesCandidate(preview, c));
}

function findCountryFieldContainer() {
    return getWorkdayFieldContainers().find(c => isCountryFieldLabel(getContainerLabel(c))) || null;
}

function findPhoneCodeFieldContainer() {
    return getWorkdayFieldContainers().find(c => /phone code/i.test(getContainerLabel(c).toLowerCase())) || null;
}

function findStateFieldContainer() {
    return getWorkdayFieldContainers().find(c => isWorkdayStateFieldLabel(getContainerLabel(c))) || null;
}

function getExpectedStateForProfile(profile) {
    return getConsistentUSStateForProfile(profile);
}

async function fillWorkdayJapanPostalSearchField(container, postalCode) {
    const fieldRoot = container?.closest?.('[data-automation-id*="formField"]') || container;
    const combobox = fieldRoot?.querySelector('input[role="combobox"]') || getContainerControl(container);
    if (!combobox) return false;
    const postal = normalizeJapanPostalValue(postalCode || getJapanPostalCodeForJob());
    const digits = postal.replace(/\D/g, '');
    const preview = fieldRoot.innerText || '';
    if (!/0 items selected|select one/i.test(preview) && (preview.includes(postal) || preview.includes(digits))) {
        return true;
    }
    await closeWorkdayPopups();
    workdayScrollToTarget(combobox, 120);
    combobox.focus?.();
    await workdayClick(combobox);
    await wait(500);
    await workdayTypeElement(combobox, postal);
    await wait(2200);
    let popup = findPopupNearField(fieldRoot, 'postal') || findPopupNearField(fieldRoot, 'search address');
    let options = popup ? getSingleSelectDropdownOptions(popup, false) : [];
    if (!options.length) {
        options = [...document.querySelectorAll('[role="listbox"] [role="option"], [data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]')]
            .filter(isVisibleElement);
    }
    const searchTerms = [postal, digits, `${digits.slice(0, 3)}-${digits.slice(3)}`];
    let match = options.find(o => searchTerms.some(t => optionText(o).includes(t.replace('-', '')) || optionText(o).includes(t)));
    if (!match && options.length) match = options[0];
    if (match) {
        workdayClickElement(match);
        await wait(900);
        await commitWorkdayComboboxSelection(fieldRoot, combobox, match, postal);
        const updated = fieldRoot.innerText || '';
        if (!/0 items selected/i.test(updated)) {
            debugLog(`${WD} japan postal search filled`, postal, optionText(match).slice(0, 60));
            await closeWorkdayPopups();
            return true;
        }
    }
    await workdayTypeElement(combobox, digits);
    await wait(1500);
    popup = findPopupNearField(fieldRoot, 'postal') || findPopupNearField(fieldRoot, 'search address');
    options = popup ? getSingleSelectDropdownOptions(popup, false) : options;
    match = options.find(o => optionText(o).includes(digits.slice(0, 3))) || options[0];
    if (match) {
        workdayClickElement(match);
        await wait(900);
        debugLog(`${WD} japan postal search filled digits`, digits, optionText(match).slice(0, 60));
        await closeWorkdayPopups();
        return true;
    }
    await closeWorkdayPopups();
    return false;
}

async function fixJapanPhoneForJob(profile) {
    if (!jobLocationExpectsJapanResidency()) return false;
    const phone = getJapanPhoneNumberForJob(profile);
    let fixed = false;
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        const labelLower = labelText.toLowerCase();
        if (!/phone number/i.test(labelLower) || /code|type|extension/i.test(labelLower)) continue;
        const element = getContainerControl(container);
        if (!element || element.tagName !== 'INPUT') continue;
        const current = (element.value || '').replace(/\D/g, '');
        const containerErr = /not valid for this region|valid format/i.test(container.innerText || '');
        if (!containerErr && current === phone) continue;
        resetWorkdayDropdownOpenCount('phone number');
        debugLog(`${WD} fix japan phone`, phone, 'was=', current.slice(0, 20));
        workdayScrollToTarget(element, 120);
        await workdayTypeElement(element, phone);
        fixed = true;
        await wait(400);
    }
    return fixed;
}

async function fixPhoneNumberForRegion(profile) {
    if (jobLocationExpectsJapanResidency()) return fixJapanPhoneForJob(profile);
    profile = getProfileForJobLocation(profile);
    const candidates = getNationalPhoneNumberCandidatesForWorkday(profile);
    if (!candidates.length) return false;
    let fixed = false;
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        const labelLower = labelText.toLowerCase();
        if (!/phone number/i.test(labelLower) || /code|type|extension/i.test(labelLower)) continue;
        const element = getContainerControl(container);
        if (!element || element.tagName !== 'INPUT') continue;
        const current = (element.value || '').replace(/\D/g, '');
        const preview = container.innerText || '';
        const containerErr = /not valid for this region|valid format|number length does not match/i.test(preview);
        if (!containerErr && current && candidates.includes(current)) continue;
        resetWorkdayDropdownOpenCount('phone number');
        clearWorkdaySingleSelectMissKey(labelText);
        workdayScrollToTarget(element, 120);
        // When region validation fails, retyping the same digits never clears the error —
        // walk format candidates (UK 0 / no-0 / safe mobile) until the error disappears.
        const tryList = containerErr
            ? candidates.filter((c) => c !== current).concat(candidates.filter((c) => c === current))
            : candidates;
        for (const phone of tryList) {
            debugLog(`${WD} fix phone number for region`, phone, 'was=', current.slice(0, 20));
            await workdayTypeElement(element, phone);
            fixed = true;
            await wait(500);
            const after = container.innerText || '';
            if (!/not valid for this region|valid format|number length does not match/i.test(after)) break;
        }
    }
    return fixed;
}

async function fixJapanAddressFields(profile) {
    if (!jobLocationExpectsJapanResidency()) return false;
    profile = getProfileForJobLocation(profile);
    let fixed = false;
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        const labelLower = labelText.toLowerCase();
        if (isWorkdayJapanPostalSearchField(labelText)) {
            const preview = container.innerText || '';
            if (/0 items selected|select one|must be 7 digits|valid format/i.test(preview)) {
                resetWorkdayDropdownOpenCount('search address postal');
                const ok = await fillWorkdayJapanPostalSearchField(container, getJapanPostalCodeForJob());
                if (ok) fixed = true;
            }
            continue;
        }
        if (/\bprefecture\b/i.test(labelLower)) {
            const preview = getWorkdayFieldSelectedText(container) || container.innerText || '';
            if (/select one|0 items selected/i.test(preview)) {
                resetWorkdayDropdownOpenCount('prefecture');
                const element = getWorkdayDropdownTrigger(container) || getContainerControl(container);
                const prefecture = getJapanPrefectureFromJob();
                if (element && (
                    await fillWorkdayDropdown(element, [prefecture, getJapanCityFromJobLocation(), 'Tokyo-to', 'Tokyo Metropolis'])
                    || await fillWorkdaySingleSelectDropdown(element, [prefecture, getJapanCityFromJobLocation()], 'prefecture')
                )) {
                    fixed = true;
                    await wait(600);
                }
            }
            continue;
        }
        const value = getProfileFieldValue(profile, labelText);
        if (value === null || value === undefined || value === '') continue;
        const element = getContainerControl(container);
        if (!element || element.type === 'file') continue;
        if (element.tagName === 'INPUT' && element.type !== 'radio' && element.type !== 'checkbox') {
            const current = (element.value || '').trim();
            if (!current || /^n\/a$/i.test(current)) {
                wdSetInputValue(element, String(value));
                fixed = true;
                await wait(250);
            }
        }
    }
    const phoneFixed = await fixJapanPhoneForJob(profile);
    return fixed || phoneFixed;
}

async function fixPostalCodeForJobLocation(profile) {
    if (profileExpectsUS(profile) && !jobLocationExpectsJapanResidency()) {
        const postalValue = getWorkdayPostalCodeValue(profile);
        if (!postalValue) return false;
        let fixed = false;
        for (const container of getWorkdayFieldContainers()) {
            const labelText = getContainerLabel(container);
            if (!/postal|zip/i.test(labelText.toLowerCase())) continue;
            if (isWorkdayJapanPostalSearchField(labelText)) continue;
            const element = getContainerControl(container);
            if (!element || element.tagName !== 'INPUT') continue;
            const current = (element.value || '').trim();
            const preview = container.innerText || '';
            const empty = !current || /^n\/a$/i.test(current);
            const hasErr = /required and must have a value|not a valid postal/i.test(preview);
            if (!empty && !hasErr) continue;
            debugLog(`${WD} fix US postal for job location`, postalValue, 'was=', current.slice(0, 20));
            workdayScrollToTarget(element, 120);
            await workdayTypeElement(element, postalValue);
            fixed = true;
            await wait(400);
        }
        return fixed;
    }

    const errText = (document.body?.innerText || '').replace(/\s+/g, ' ');
    const needsJapan = jobLocationExpectsJapanResidency()
        || /postal code must be (6|7) digits|valid format.*postal/i.test(errText);
    if (!needsJapan) return false;

    const postalValue = getWorkdayPostalCodeValue(profile);
    if (!postalValue) return false;

    let fixed = false;
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!/postal|zip/i.test(labelText.toLowerCase())) continue;
        if (isWorkdayJapanPostalSearchField(labelText)) {
            const preview = container.innerText || '';
            if (/0 items selected|select one|must be 7 digits|valid format/i.test(preview)) {
                const ok = await fillWorkdayJapanPostalSearchField(container, postalValue);
                if (ok) fixed = true;
            }
            continue;
        }
        const element = getContainerControl(container);
        if (!element || element.tagName !== 'INPUT') continue;
        const current = (element.value || '').trim();
        const containerErr = /must be (6|7) digits|valid format|error:/i.test(container.innerText || '');
        if (current === postalValue && !containerErr && !/^n\/a$/i.test(current) && isValidJapanPostalValue(current)) continue;
        debugLog(`${WD} fix postal for job location`, postalValue, labelText.slice(0, 40), 'was=', current.slice(0, 20));
        workdayScrollToTarget(element, 120);
        await workdayTypeElement(element, postalValue);
        fixed = true;
        await wait(400);
    }
    return fixed;
}

async function fixPostalCodeStateMismatch(profile) {
    const errText = (document.body?.innerText || '').replace(/\s+/g, ' ');
    const m = errText.match(/(\d{5})\s+is not a valid postal code for\s+([A-Za-z][A-Za-z\s]+?)(?:\.|$)/i);
    if (!m) return false;
    const zip = m[1];
    const stateFromZip = getUSStateFromZip(zip) || getConsistentUSStateForProfile(profile);
    if (!stateFromZip) return false;
    debugLog(`${WD} fix postal/state mismatch`, zip, 'invalid for', m[2].trim(), '->', stateFromZip);
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!isWorkdayStateFieldLabel(labelText)) continue;
        if (isStateDropdownFilled(container, stateFromZip)) return true;
        const trigger = getWorkdayDropdownTrigger(container);
        const element = getContainerControl(container);
        if (!trigger && !element) continue;
        const fixed = await fillWorkdayStateDropdown(trigger || element, stateFromZip);
        if (fixed) {
            await wait(WD_PROFILE_FIELD_SETTLE_MS);
            return true;
        }
    }
    return false;
}

function isStateFilledForProfile(container, profile) {
    const expected = getExpectedStateForProfile(profile);
    if (!expected) return true;
    return isStateDropdownFilled(container, expected);
}

function hasWorkdayAddressCityRequiredError() {
    for (const container of getWorkdayFieldContainers()) {
        if (!isWorkdayAddressCityFieldLabel(getContainerLabel(container))) continue;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        if (/error:.*required and must have a value/i.test(preview)) return true;
    }
    return false;
}

async function clearWorkdayPromptFieldSelection(container) {
    if (!container) return false;
    const deleteBtn = container.querySelector(
        '[data-automation-id="deleteSelectedItem"], [data-automation-id="selectedItem"] button,'
        + ' button[title*="delete" i], button[aria-label*="delete" i], button[aria-label*="clear" i]',
    );
    if (deleteBtn && isVisibleElement(deleteBtn)) {
        debugLog(`${WD} clear prompt selection via delete`);
        await workdayClick(deleteBtn);
        await wait(450);
        return true;
    }
    const trigger = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (trigger) {
        await closeWorkdayPopups();
        await wait(250);
        await workdayClick(trigger);
        await wait(600);
        let popup = findPopupNearField(container, getContainerLabel(container).toLowerCase())
            || findActiveWorkdayPopup();
        if (popup && !isChipDisplayPopup(popup)) {
            const selectOne = getSingleSelectDropdownOptions(popup, false)
                .find((o) => /^select one$/i.test(optionText(o)));
            if (selectOne) {
                debugLog(`${WD} clear prompt selection via Select One`);
                workdayClickElement(selectOne);
                await wait(450);
                await closeWorkdayPopups();
                return true;
            }
        }
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await wait(300);
    }
    const input = container.querySelector('input[role="combobox"], input:not([type="hidden"])');
    if (input && (input.value || '').trim()) {
        wdSetInputValue(input, '');
        input.dispatchEvent(new Event('input', { bubbles: true }));
        await wait(200);
        return true;
    }
    return false;
}

async function fixStateForProfile(profile) {
    const expected = getExpectedStateForProfile(profile);
    if (!expected) return false;
    // bah.wd1: State can paint "Florida" from candidate profile while City stays
    // "Error: required and must have a value". Re-committing State (Select One → Florida)
    // clears the City error — typed city text then validates without a city listbox.
    const cityNeedsStateCommit = hasWorkdayAddressCityRequiredError();
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!isWorkdayStateFieldLabel(labelText)) continue;
        const looksFilled = isStateFilledForProfile(container, profile);
        if (looksFilled && !cityNeedsStateCommit) return false;
        if (looksFilled && cityNeedsStateCommit) {
            // Only force-clear once per apply session — otherwise a successful Florida
            // commit is wiped again while City's error is still settling (bah.wd1).
            if (window.__wdForcedStateReselectForCity) {
                debugLog(`${WD} skip repeat state reselect — City still settling`);
                return false;
            }
            window.__wdForcedStateReselectForCity = true;
            debugLog(`${WD} force state reselect — City required error with State display`,
                getWorkdayFieldSelectedText(container).slice(0, 40), '->', expected);
            await clearWorkdayPromptFieldSelection(container);
            clearWorkdaySingleSelectMissKey('state');
            clearWorkdaySingleSelectMissKey(normalizeDropdownOpenKey(labelText));
            resetWorkdayDropdownOpenCount('state');
            window.__wdSingleSelectMissKeys?.delete('state');
            await wait(400);
        }
        const trigger = getWorkdayDropdownTrigger(container);
        const element = getContainerControl(container);
        if (!trigger && !element) continue;
        debugLog(`${WD} fixing state to profile`, getWorkdayFieldSelectedText(container).slice(0, 80), '->', expected);
        const fixed = await fillWorkdayStateDropdown(trigger || element, expected);
        if (fixed) {
            await wait(WD_PROFILE_FIELD_SETTLE_MS);
            return true;
        }
    }
    return false;
}

async function fixCountryForProfile(profile) {
    profile = getProfileForJobLocation(profile);
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!isCountryOrCitizenshipFieldLabel(labelText)) continue;
        if (isCountryFilled(container, profile)) continue;
        const trigger = getWorkdayDropdownTrigger(container);
        const element = getContainerControl(container);
        if (!trigger && !element) continue;
        debugLog(`${WD} fixing country to profile`, labelText.slice(0, 40), getWorkdayFieldSelectedText(container).slice(0, 80), '->', getExpectedCountryCandidates(profile)[0]);
        const fixed = await fillWorkdayCountryDropdown(trigger || element, profile);
        if (fixed && isCountryFilled(container, profile)) {
            await wait(WD_PROFILE_FIELD_SETTLE_MS);
            return true;
        }
    }
    return false;
}

async function fixPhoneCodeForProfile(profile) {
    profile = getProfileForJobLocation(profile);
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!/phone code/i.test(labelText)) continue;
        if (isPhoneCodeFilledForProfile(container, profile)) return false;
        const element = getContainerControl(container);
        if (!element) continue;
        debugLog(`${WD} fixing phone code to profile`, getWorkdayFieldSelectedText(container).slice(0, 80));
        const fixed = await fillWorkdayPhoneCodeDropdown(element, profile);
        if (fixed && isPhoneCodeFilledForProfile(container, profile)) {
            await wait(WD_PROFILE_FIELD_SETTLE_MS);
            return true;
        }
    }
    return false;
}

function validateProfileLocationFields(profile) {
    const countryContainer = findCountryFieldContainer();
    const phoneContainer = findPhoneCodeFieldContainer();
    let ok = true;
    if (countryContainer && !isCountryFilled(countryContainer, profile)) {
        debugLog(`${WD} profile country mismatch`, (countryContainer.innerText || '').replace(/\s+/g, ' ').slice(0, 120));
        ok = false;
    }
    if (phoneContainer && !isPhoneCodeFilledForProfile(phoneContainer, profile)) {
        debugLog(`${WD} profile phone code mismatch`, (phoneContainer.innerText || '').replace(/\s+/g, ' ').slice(0, 120));
        ok = false;
    }
    return ok;
}

async function ensureProfileLocationFields(profile) {
    profile = getProfileForJobLocation(profile);
    for (let attempt = 0; attempt < 5; attempt++) {
        const countryFixed = await fixCountryForProfile(profile);
        const phoneFixed = await fixPhoneCodeForProfile(profile);
        const stateFixed = await fixStateForProfile(profile);
        const postalFixed = await fixPostalCodeForJobLocation(profile);
        const japanFixed = await fixJapanAddressFields(profile);
        if (validateProfileLocationFields(profile)) {
            debugLog(`${WD} profile location validation ok`, 'attempt=', attempt + 1);
            return true;
        }
        if (!countryFixed && !phoneFixed && !stateFixed && !postalFixed && !japanFixed) break;
        await wait(500);
    }
    const phoneContainer = findPhoneCodeFieldContainer();
    const countryContainer = findCountryFieldContainer();
    debugLog(`${WD} profile location validation FAILED`,
        'phone=', getWorkdayFieldSelectedText(phoneContainer).slice(0, 60),
        'dial=', getProfilePhoneDialDigits(profile),
        'country=', getWorkdayFieldSelectedText(countryContainer).slice(0, 40));
    return false;
}

function isWorkdayComboboxCommitted(container) {
    const val = getWorkdayComboboxInputValue(container);
    if (!val) return false;
    if (isWorkdayOpaqueOptionId(val)) return true;
    if (/^(yes|no|true|false)$/i.test(val)) return true;
    const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').trim();
    return Boolean(selectionLabel && !/^select one$/i.test(selectionLabel));
}

function getWorkdayYesNoCheckboxInputs(container) {
    const scope = container?.closest?.('[data-automation-id*="formField"]') || container;
    if (!scope || scope.querySelector('input[type="radio"]')) return null;
    let yes = null;
    let no = null;
    for (const input of scope.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`))
            || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').trim().toLowerCase();
        if (!text || text.length > 20) continue;
        if (text === 'yes' || text.startsWith('yes ')) yes = { input, label: labelEl };
        else if (text === 'no' || text.startsWith('no ')) no = { input, label: labelEl };
    }
    if (!yes || !no) return null;
    return { scope, yes, no };
}

function isWorkdayYesNoCheckboxGroup(container) {
    return Boolean(getWorkdayYesNoCheckboxInputs(container));
}

function getWorkdayYesNoCheckboxChecked(container) {
    const pair = getWorkdayYesNoCheckboxInputs(container);
    if (!pair) return null;
    return {
        yes: isWorkdayCheckboxChecked(pair.yes.input),
        no: isWorkdayCheckboxChecked(pair.no.input),
        pair,
    };
}

function isWorkdayYesNoCheckboxConflict(container) {
    const state = getWorkdayYesNoCheckboxChecked(container);
    return Boolean(state?.yes && state?.no);
}

function isWorkdayYesNoCheckboxFilled(container, expected) {
    const state = getWorkdayYesNoCheckboxChecked(container);
    if (!state) return false;
    if (state.yes && state.no) return false;
    const target = String(expected || '').toLowerCase();
    if (!target) return state.yes || state.no;
    if (target === 'yes') return state.yes && !state.no;
    if (target === 'no') return state.no && !state.yes;
    return false;
}

async function clickWorkdayYesNoCheckboxGroup(container, answer) {
    const pair = getWorkdayYesNoCheckboxInputs(container);
    if (!pair) return false;
    const target = String(answer).toLowerCase();
    const desired = target === 'yes' ? pair.yes : target === 'no' ? pair.no : null;
    const opposite = target === 'yes' ? pair.no : target === 'no' ? pair.yes : null;
    if (!desired) return false;
    if (opposite && isWorkdayCheckboxChecked(opposite.input)) {
        debugLog(`${WD} yes/no uncheck opposite`, target === 'yes' ? 'No' : 'Yes');
        await workdayUncheckCheckbox(opposite.input);
        await wait(200);
    }
    if (!isWorkdayCheckboxChecked(desired.input)) {
        debugLog(`${WD} yes/no check`, target);
        if (!await workdayClickCheckbox(desired.input)) {
            await workdayClick(desired.label || desired.input);
            await wait(250);
        }
    }
    return isWorkdayYesNoCheckboxFilled(container, answer);
}

function isWorkdayYesNoFilled(container, expected) {
    if (!container) return false;
    const fieldLabel = getContainerLabel(container);
    if (isWorkdayFormerEmployerQuestion(fieldLabel)) {
        if (isWorkdayYesNoCheckboxGroup(container)) {
            return isWorkdayYesNoCheckboxFilled(container, expected);
        }
        const target = String(expected || '').toLowerCase();
        const checkedRadio = container.querySelector('input[type="radio"]:checked');
        if (checkedRadio) {
            if (!target) return true;
            const labelEl = document.querySelector(`label[for="${checkedRadio.id}"]`) || checkedRadio.closest('label');
            const label = (labelEl?.innerText || '').trim().toLowerCase();
            return label === target || label.startsWith(`${target} `);
        }
        const boolCheckbox = getWorkdayBooleanYesCheckbox(container);
        if (boolCheckbox) {
            const checked = isWorkdayCheckboxChecked(boolCheckbox);
            if (target === 'yes') return checked;
            if (target === 'no') {
                if (checked) return false;
                const checkedRadio = container.querySelector('input[type="radio"]:checked');
                if (checkedRadio) {
                    const labelEl = document.querySelector(`label[for="${checkedRadio.id}"]`) || checkedRadio.closest('label');
                    const radioLabel = (labelEl?.innerText || '').trim().toLowerCase();
                    if (radioLabel === 'no' || radioLabel.startsWith('no ')) return true;
                }
                return isDisclosureChoiceFilled(container, getWorkdayFormerEmployerCheckboxCandidates(fieldLabel));
            }
            return checked;
        }
        if (target === 'no') {
            if (isDisclosureChoiceFilled(container, getWorkdayFormerEmployerCheckboxCandidates(fieldLabel))) return true;
            // A genuine multi-option checkbox group (Employee/Intern/.../"I have not worked for X in
            // the past.") always has every option label present in container.innerText regardless of
            // which (if any) is checked. getWorkdayFieldSelectedText()+isWorkdayExplicitNoSelectionText()
            // below are built for dropdown/combobox/radio controls whose preview text reflects only the
            // current selection; for a checkbox list they read the concatenation of ALL option labels,
            // which always contains phrases like "have not worked" / "I have not" because that IS one of
            // the option labels — so this falsely reports the field filled even when nothing is checked.
            // isDisclosureChoiceFilled() above is the correct (checked-state) check for this control type.
            if (isWorkdayMultiOptionCheckboxGroup(container)) return false;
            // Check single-select / opaque id BEFORE ComboboxCommitted gating — data-value fills leave
            // a hex id on the combobox while closed chrome still says "Select One".
            if (isWorkdaySingleSelectFilled(container, ['No', 'no'])) return true;
            if (isWorkdayComboboxCommitted(container)) {
                const comboboxVal = getWorkdayComboboxInputValue(container).toLowerCase();
                if (comboboxVal === 'no' || comboboxVal === 'false' || isWorkdayOpaqueOptionId(comboboxVal)) return true;
                const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').trim().toLowerCase();
                if (selectionLabel === 'no' || (/^no\b/.test(selectionLabel) && !/\byes\b/.test(selectionLabel))) return true;
            }
            const selected = getWorkdayFieldSelectedText(container).toLowerCase();
            if (isWorkdayExplicitNoSelectionText(selected)) return true;
            return false;
        }
        return false;
    }
    if (isWorkdayYesNoCheckboxGroup(container)) {
        return isWorkdayYesNoCheckboxFilled(container, expected);
    }
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:/i.test(preview)) return false;
    const target = String(expected || '').toLowerCase();
    const checkedRadio = container.querySelector('input[type="radio"]:checked');
    if (checkedRadio) {
        if (!target) return true;
        const labelEl = document.querySelector(`label[for="${checkedRadio.id}"]`) || checkedRadio.closest('label');
        const label = (labelEl?.innerText || '').trim().toLowerCase();
        return label === target || label.startsWith(`${target} `);
    }
    if (isWorkdayComboboxCommitted(container)) {
        if (!target) return true;
        const comboboxVal = (container.querySelector('input[role="combobox"]')?.value || '').trim().toLowerCase();
        if (comboboxVal === target) return true;
        if (target === 'no' && comboboxVal === 'false') return true;
        if (target === 'yes' && comboboxVal === 'true') return true;
        const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').toLowerCase();
        if (selectionLabel === target) return true;
        if (new RegExp(`\\*\\s*${target}\\b`, 'i').test(preview)) return true;
        return isWorkdaySingleSelectFilled(container, [expected]);
    }
    if (!target) return false;
    const comboboxVal = (container.querySelector('input[role="combobox"]')?.value || '').trim().toLowerCase();
    if (comboboxVal === target) return true;
    if (target === 'no' && comboboxVal === 'false') return true;
    if (target === 'yes' && comboboxVal === 'true') return true;
    const selectionLabel = (container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText || '').toLowerCase();
    if (selectionLabel === target) return true;
    if (new RegExp(`\\*\\s*${target}\\b`, 'i').test(preview)) return true;
    return isWorkdaySingleSelectFilled(container, [expected]);
}

function isWorkdayOpaqueOptionId(value) {
    // Workday prompt dropdowns often store the committed choice as an opaque option id
    // (32-char hex, sometimes dashed). Must be recognized before "Select One" placeholder
    // text / stale Error banners, or Yes/No fills look empty forever and block Next.
    return /^[a-f0-9-]{16,}$/i.test(String(value || '').trim());
}

/** Canvas Kit button+sibling-input selects (unimelb.wd105 questionnaire, trimble veteran). */
function isWorkdayButtonListboxField(container) {
    return Boolean(container?.querySelector?.('button[aria-haspopup="listbox"]'));
}

/** Opaque id on button.value or sibling text input — the only durable commit for button listboxes. */
function getWorkdayButtonListboxOpaqueValue(container) {
    if (!container) return '';
    const btn = container.querySelector('button[aria-haspopup="listbox"]');
    if (btn) {
        const bv = String(btn.value || btn.getAttribute('value') || '').trim();
        if (isWorkdayOpaqueOptionId(bv)) return bv;
    }
    for (const input of container.querySelectorAll('input')) {
        if (input.type === 'file' || input.type === 'checkbox' || input.type === 'radio') continue;
        const v = String(input.value || '').trim();
        if (isWorkdayOpaqueOptionId(v)) return v;
    }
    return '';
}

/** Combobox / prompt value — role=combobox first, then any input holding an opaque option id. */
function getWorkdayComboboxInputValue(container) {
    if (!container) return '';
    const byRole = container.querySelector('input[role="combobox"]');
    const fromRole = (byRole?.value || '').trim();
    if (fromRole) return fromRole;
    // BUTTON listboxes (trimble.wd1 veteran/ethnicity; unimelb.wd105 questionnaire) commit the
    // choice on button.value (opaque id). Never treat human-readable button.value ("40") as committed.
    const btn = container.querySelector('button[aria-haspopup="listbox"]')
        || (typeof getContainerControl === 'function' ? getContainerControl(container) : null);
    if (btn && btn.tagName === 'BUTTON') {
        const bv = (btn.value || btn.getAttribute('value') || '').trim();
        if (isWorkdayOpaqueOptionId(bv) || /^(yes|no|true|false)$/i.test(bv)) return bv;
        // aria-label often becomes "Veteran Status I am not a protected veteran" after commit
        const aria = (btn.getAttribute('aria-label') || '').trim();
        if (aria && !/select one/i.test(aria) && isWorkdayOpaqueOptionId(getWorkdayButtonListboxOpaqueValue(container))) {
            return aria;
        }
    }
    for (const input of container.querySelectorAll('input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]):not([type="file"])')) {
        const v = (input.value || '').trim();
        if (isWorkdayOpaqueOptionId(v) || /^(yes|no|true|false)$/i.test(v)) return v;
    }
    const ctrl = typeof getContainerControl === 'function' ? getContainerControl(container) : null;
    if (ctrl && ctrl.tagName === 'INPUT' && ctrl.type !== 'checkbox' && ctrl.type !== 'radio' && ctrl.type !== 'file') {
        return (ctrl.value || '').trim();
    }
    return '';
}

function isWorkdaySingleSelectFilled(container, expected) {
    if (!container) return false;
    const targets = (Array.isArray(expected) ? expected : [expected]).map(v => String(v).toLowerCase()).filter(Boolean);
    if (!targets.length) return false;
    let preview = (container?.innerText || '').replace(/\s+/g, ' ');
    const fieldLabel = (getContainerLabel(container) || '').replace(/\s+/g, ' ').trim();
    if (fieldLabel && preview.toLowerCase().startsWith(fieldLabel.toLowerCase())) {
        preview = preview.slice(fieldLabel.length).replace(/^\s*\*?\s*/, '').trim();
    }
    const combobox = container.querySelector('input[role="combobox"]');
    const comboboxValue = getWorkdayComboboxInputValue(container);
    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const selectedText = (selectionLabel?.innerText || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const selectedFromField = getWorkdayFieldSelectedText(container).toLowerCase();
    const listBtn = container.querySelector('button[aria-haspopup="listbox"]');
    const btnOpaque = getWorkdayButtonListboxOpaqueValue(container);
    // UniMelb-style button listboxes: visible label alone is NOT a commit. Writing displayText
    // ("40", "Australian Citizen") onto button.value left Review "No Response". Require opaque id.
    if (listBtn) {
        if (!btnOpaque && !isWorkdayOpaqueOptionId(comboboxValue)) return false;
        if (btnOpaque || isWorkdayOpaqueOptionId(comboboxValue)) {
            if (targets.some(t => /^(yes|no)$/i.test(t))) return true;
            const btnLabel = String(listBtn.innerText || listBtn.getAttribute('aria-label') || '')
                .replace(/\s+/g, ' ').trim().toLowerCase();
            if (btnLabel && !/^select one/i.test(btnLabel)
                && targets.some(t => textMatchesCandidate(btnLabel, t)
                    || new RegExp(`\\b${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(btnLabel))) {
                return true;
            }
            // Opaque present but label still "Select One" — accept for short Yes/No / EEO only
            // (trimble). Questionnaire multi-option needs a non-placeholder label too.
            if (targets.some(t => /veteran|self-identify|self identify|decline|prefer not|choose not|not a protected/i.test(t))) {
                return true;
            }
            if (btnLabel && !/^select one/i.test(btnLabel)) return true;
            return false;
        }
    }
    // Opaque commit: fillWorkdaySingleSelectDropdown often succeeds via data-value while the
    // closed widget still paints "Select One" / option-list chrome. Returning false here made
    // countWorkdayStepEmptyRequired keep former-employer / veteran (and similar) required forever —
    // Next stayed blocked with empty=1/errors=0 (carrier.wd5; trimble.wd1 veteran BUTTON listbox).
    if (isWorkdayOpaqueOptionId(comboboxValue)) {
        if (targets.some(t => /^(yes|no)$/i.test(t))) return true;
        // Veteran / EEO multi-option: opaque id means a real option was committed even when the
        // visible button text hasn't refreshed yet.
        if (targets.some(t => /veteran|self-identify|self identify|decline|prefer not|choose not|not a protected/i.test(t))) {
            return true;
        }
    }
    if (/\(\+\d\)/.test(preview)) return false;
    if (/error:/i.test(preview) && !isWorkdayOpaqueOptionId(comboboxValue)) return false;
    if ((/^select one$/i.test(selectedText) || /^select one$/i.test(selectedFromField))
        && !isWorkdayOpaqueOptionId(comboboxValue)) {
        return false;
    }
    if (!selectedText && !comboboxValue && /select one|0 items selected/i.test(preview)) return false;
    if (isWorkdayClinicalSettingsQuestion(fieldLabel) && /for example, hospital/i.test(preview) && !selectedText && !comboboxValue) {
        return false;
    }
    if (isWorkdayShiftAvailabilityQuestion(fieldLabel) && /select one|0 items selected/i.test(preview) && !selectedText && !comboboxValue) {
        return false;
    }
    if (combobox && !comboboxValue && !selectedText) return false;
    const hasSelection = Boolean(
        (selectedText && !/^select one$/i.test(selectedText))
        || (comboboxValue && !/^select one$/i.test(comboboxValue))
    );
    const haystack = hasSelection
        ? `${selectedText} ${comboboxValue.toLowerCase()}`
        : `${selectedText} ${comboboxValue.toLowerCase()} ${preview.toLowerCase()}`;
    const normalizedHaystack = normalizeDisclosureOptionText(haystack).toLowerCase();
    return targets.some(t => {
        if (/^(yes|no)$/i.test(t)) {
            if (isWorkdayOpaqueOptionId(comboboxValue)) return true;
            if (comboboxValue.toLowerCase() === t) return true;
            if (t === 'no' && comboboxValue.toLowerCase() === 'false') return true;
            if (t === 'yes' && comboboxValue.toLowerCase() === 'true') return true;
            if (isWorkdayYesNoOptionListText(selectedText) || isWorkdayYesNoOptionListText(selectedFromField)) {
                return false;
            }
            if (selectedText === t.toLowerCase()) return true;
            const normalizedSelected = normalizeDisclosureOptionText(selectedText).toLowerCase();
            if (isWorkdayYesNoOptionListText(normalizedSelected)) return false;
            if (/\byes\b/.test(normalizedSelected) && /\bno\b/.test(normalizedSelected)) return false;
            return textMatchesCandidate(normalizedSelected, t);
        }
        const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (new RegExp(`\\b${escaped}\\b`, 'i').test(haystack)) return true;
        const normalizedTarget = normalizeDisclosureOptionText(t).toLowerCase();
        return textMatchesCandidate(normalizedHaystack, normalizedTarget);
    });
}

function isStateDropdownFilled(container, expectedState) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/\(\+\d\)/.test(preview)) return false;
    if (/\bwyoming\b|\bamerican samoa\b/i.test(preview) && !/\bcalifornia\b/i.test(preview)) return false;
    return isWorkdaySingleSelectFilled(container, expectedState || 'California');
}

function isPhoneCodeFilled(container, profile) {
    if (profile) return isPhoneCodeFilledForProfile(container, profile);
    if (!container) return false;
    const preview = normalizeWorkdayDropdownSelectedText(container.innerText || '');
    return /\(\+\d{1,4}\)/.test(preview) && !/^select one$/i.test(preview);
}

function filterDropdownOptionsForField(options, labelLower, profile) {
    if (isWorkdayStateFieldLabel(labelLower)) {
        return options.filter(o => !/\(\+\d\)/.test(optionText(o)));
    }
    if (/phone code/i.test(labelLower) && profile) {
        const dialDigits = getProfilePhoneDialDigits(profile);
        if (!dialDigits) return options;
        const matched = options.filter(o => {
            const t = optionText(o);
            return extractDialDigitsFromPhoneText(t) === dialDigits
                || phoneCodeOptionMatches(t, profile);
        });
        return matched.length ? matched : options;
    }
    return options;
}

function getSingleSelectDropdownOptions(popup, allowFallback = true) {
    const scope = popup || (allowFallback ? findActiveWorkdayPopup() : null) || (allowFallback ? document : null);
    if (!scope) return [];
    return [...scope.querySelectorAll('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], li[role="option"], div[role="option"]')]
        .filter(isVisibleElement)
        .filter(o => optionText(o));
}

function extractWorkdayOptionValue(optionEl) {
    if (!optionEl) return null;
    const candidates = [
        optionEl.getAttribute('data-value'),
        optionEl.getAttribute('data-automation-value'),
        optionEl.getAttribute('data-id'),
        optionEl.id,
        optionEl.querySelector('[id]')?.id,
        optionEl.closest('[data-automation-id="promptOption"]')?.id,
        optionEl.closest('[role="option"]')?.id,
        optionEl.closest('[data-value]')?.getAttribute('data-value'),
    ].filter(v => v && String(v).length > 4 && !/^select/i.test(v));
    // Prefer opaque hex ids (unimelb questionnaire options) over short chrome ids.
    const opaque = candidates.find(v => isWorkdayOpaqueOptionId(v));
    return opaque || candidates[0] || null;
}

async function commitWorkdayComboboxSelection(fieldRoot, combobox, optionEl, displayText) {
    if (!combobox && !fieldRoot) return;
    const listBtn = fieldRoot?.querySelector?.('button[aria-haspopup="listbox"]');
    const internalValue = optionEl?.getAttribute('data-value') || extractWorkdayOptionValue(optionEl);
    const opaqueInternal = isWorkdayOpaqueOptionId(internalValue) ? String(internalValue).trim() : '';
    debugLog(`${WD} option value`, internalValue, displayText, (optionEl?.outerHTML || '').slice(0, 160));

    // UniMelb button+sibling-input listboxes: ONLY opaque option ids are valid. Writing
    // displayText ("40", "Australian Citizen") made Review show "No Response".
    if (listBtn) {
        const existing = getWorkdayButtonListboxOpaqueValue(fieldRoot);
        const oid = opaqueInternal || existing;
        if (!oid) {
            debugLog(`${WD} commit skip displayText for button listbox`, String(displayText || '').slice(0, 40));
            listBtn.setAttribute('aria-expanded', 'false');
            await wait(200);
            return;
        }
        for (const input of fieldRoot.querySelectorAll('input')) {
            if (input.type === 'file' || input.type === 'checkbox' || input.type === 'radio') continue;
            if (typeof wdCommitReactTextInput === 'function') wdCommitReactTextInput(input, oid);
            else {
                setNativeValue(input, oid);
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }
        try { listBtn.value = oid; } catch (_) { /* ignore */ }
        if (optionEl?.id) listBtn.setAttribute('aria-activedescendant', optionEl.id);
        listBtn.setAttribute('aria-expanded', 'false');
        listBtn.dispatchEvent(new Event('change', { bubbles: true }));
        listBtn.dispatchEvent(new Event('blur', { bubbles: true }));
        combobox?.setAttribute('aria-expanded', 'false');
        combobox?.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(500);
        return;
    }

    if (!combobox) return;
    if (!internalValue && !displayText) return;
    if (!internalValue && /^(yes|no)$/i.test(String(displayText).trim())) {
        setNativeValue(combobox, displayText);
        combobox.dispatchEvent(new Event('change', { bubbles: true }));
        combobox.setAttribute('aria-expanded', 'false');
        combobox.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(500);
        return;
    }

    for (const input of fieldRoot.querySelectorAll('input')) {
        if (input.type === 'file') continue;
        const cur = String(input.value || '').trim();
        if (!internalValue && isWorkdayOpaqueOptionId(cur)) {
            debugLog(`${WD} commit keep opaque id`, cur.slice(0, 28));
            input.dispatchEvent(new Event('change', { bubbles: true }));
            continue;
        }
        const nextVal = internalValue || displayText;
        if (!nextVal) continue;
        if (cur !== String(nextVal)) {
            setNativeValue(input, nextVal);
            input.dispatchEvent(new Event('input', { bubbles: true }));
        }
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    if (optionEl?.id) {
        combobox.setAttribute('aria-activedescendant', optionEl.id);
        optionEl.setAttribute('aria-selected', 'true');
    }
    combobox.setAttribute('aria-expanded', 'false');

    const listbox = optionEl?.closest('[role="listbox"]');
    listbox?.dispatchEvent(new Event('change', { bubbles: true }));

    combobox.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(500);
}

function normalizeRadioOptionText(text) {
    return String(text || '').replace(/\s+/g, '').toLowerCase();
}

function getWorkdayRadioGroupScope(container) {
    return container.querySelector('[role="radiogroup"]') || container;
}

function isTravelFilled(container) {
    const scope = getWorkdayRadioGroupScope(container);
    if (scope.querySelector('input[type="radio"]:checked')) return true;
    if (scope.querySelector('[role="radio"][aria-checked="true"]')) return true;
    if (scope.querySelector('[data-automation-id="radioButton"][aria-checked="true"], [aria-pressed="true"]')) return true;
    for (const el of scope.querySelectorAll('label, span, button, [role="radio"]')) {
        const text = normalizeRadioOptionText(el.innerText || el.getAttribute('aria-label') || '');
        if (!/^(none|0|20|50|80)%?$|up to \d+%$/i.test(text)) continue;
        if (el.getAttribute('aria-checked') === 'true'
            || el.closest('[aria-checked="true"]')
            || el.querySelector('input:checked')) {
            return true;
        }
    }
    // Dropdown travel % (guidehouse.wd1 "up to 25%") — opaque id or selected band text.
    if (isWorkdayOpaqueOptionId(getWorkdayComboboxInputValue(container))) return true;
    if (isWorkdaySingleSelectFilled(container, [
        'up to 25%', 'up to 50%', 'up to 75%', 'up to 100%',
        'unwilling to travel', '20%', '25%', '50%', '75%', '100%',
    ])) return true;
    return false;
}

function isDisclosureChoiceGroup(container) {
    if (!container) return false;
    return container.querySelectorAll('input[type="checkbox"], input[type="radio"]').length >= 2;
}

function isWorkdayMultiOptionCheckboxGroup(container) {
    if (!container) return false;
    if (container.querySelector('input[type="radio"]')) return false;
    const checkboxes = container.querySelectorAll('input[type="checkbox"], [role="checkbox"]');
    if (checkboxes.length < 2) return false;
    return !isWorkdayYesNoCheckboxGroup(container);
}

function isWorkdayShiftAvailabilityQuestion(label) {
    const l = String(label || '').toLowerCase();
    if (!l) return false;
    // "What is your shift/schedule availability?" — not skill/ability rating
    if (/\b(?:shift|schedule)\s+availability\b/i.test(l)) return true;
    if (/what is your .{0,40}availability/i.test(l) && /shift|schedule|work|hours?/i.test(l)) return true;
    if (/what shifts? are you available|shifts? (are you|you are) available|available (to work|for) .{0,40}shift/i.test(l)) {
        return true;
    }
    if (/other than time off.*(?:religion|disability|medical).*shift/i.test(l)) return true;
    if (/days?\/?evenings?\/?nights?|which shifts can you work/i.test(l)) return true;
    if (/select all that apply/i.test(l) && /availability|available to work|shifts?\b/i.test(l)) return true;
    return false;
}

function isWorkdayEmploymentTypeQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /what type of employment|type of employment are you looking for|employment type\b/i.test(l);
}

function getWorkdayEmploymentTypeCandidates(profile = null) {
    const role = String(window.__wdHistoryRole || window.__wdApplyData?.role || '').toLowerCase();
    const preferPart = /part[\s-]?time/i.test(role) || /part[\s-]?time/i.test(location.href);
    const preferSeasonal = /season|summer|winter|resort/i.test(role) || /season|summer|winter/i.test(location.href);
    const base = preferSeasonal
        ? ['Seasonal', 'Part-Time', 'Part Time', 'Part-time', 'Full-Time', 'Full Time', 'Contract', 'Temporary', 'Intern']
        : preferPart
            ? ['Part-Time', 'Part Time', 'Part-time', 'Seasonal', 'Full-Time', 'Full Time', 'Contract', 'Temporary', 'Intern']
            : ['Full-Time', 'Full Time', 'Full-time', 'Part-Time', 'Part Time', 'Contract', 'Temporary', 'Seasonal', 'Intern'];
    return base;
}

function isWorkdayBestContactTimeQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /best time to contact|best time.*(call|reach|contact)|when.*best.*(contact|call)/i.test(l);
}

function getWorkdayBestContactTimeCandidates() {
    return [
        'Morning', 'Morning (8:00 am to 12:00 pm)', 'Morning (8:00 am - 12:00 pm)',
        'Afternoon', 'Afternoon (12:00 pm to 04:00 pm)', 'Afternoon (12:00 pm - 4:00 pm)',
        'Evening', 'Evening (04:00 pm to 08:00 pm)', 'Evening (4:00 pm - 8:00 pm)',
        'Anytime', 'Any time', 'Flexible',
    ];
}

function isWorkdayNaIfNoTextField(label) {
    const l = String(label || '').toLowerCase();
    // Micron-style: "If no, please enter Not Applicable." — free-text, not Yes/No.
    return /please enter n\/?a if|enter n\/?a if|n\/?a if [''"]?no[''"]? is selected|if no[,.]?\s*(enter|type|write|please enter)?\s*n\/?a\b|please enter not applicable|if no[,.]?\s*please enter not applicable|enter not applicable|if no[,.]?\s*please enter not applicable/i.test(l)
        || (/if no[,.]?\s*please enter/i.test(l) && /not applicable|n\/?a\b/i.test(l));
}

function getWorkdayNaIfNoTextValue(label, profile = null) {
    const l = String(label || '').toLowerCase();
    if (/school|institution|university|college/i.test(l)
        && !/non-compete|non-solicit|non-disclosure|agreement which prevents/i.test(l)) {
        const school = profile?.educations?.[0]?.school || profile?.educations?.[0]?.institution;
        if (school) return String(school).trim();
    }
    // Prefer the exact phrase the questionnaire asks for (micron.wd1 non-compete).
    if (/not applicable/i.test(l)) return 'Not Applicable';
    return 'N/A';
}

/** Free-text UK right-to-work / passport-type questions (not file uploads). */
function isWorkdayPassportVisaTypeTextField(label) {
    const l = String(label || '').toLowerCase();
    if (!l || /upload|attach|scan|copy of|photo of|drop files/i.test(l)) return false;
    return /type of passport|passport\s*\/\s*visa|visa valid for|confirm the type of passport|passport.*visa.*expir|visa.*passport.*expir/i.test(l);
}

function getWorkdayPassportVisaTypeTextValue(label, profile = null) {
    profile = profile || window.__wdApplyData?.profile || {};
    const residency = profile?.residency || profile?.general?.residency || {};
    const country = String(
        residency.country || profile?.residencyCountry || profile?.citizenship || 'India'
    ).trim() || 'India';
    // Stable free-text answer for "type … and the expiry date" textareas (brenntag.wd3 UK).
    return `${country} Passport, expires 31/12/2030`;
}

async function fillWorkdayPassportVisaTypeTextField(container, label = '', profile = null) {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const value = getWorkdayPassportVisaTypeTextValue(labelText, profile || window.__wdApplyData?.profile);
    const control = container.querySelector('textarea')
        || container.querySelector('input[type="text"], input[type="search"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') {
        return false;
    }
    if ((control.value || '').trim()) return true;
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} filled passport/visa type text`, String(labelText || '').slice(0, 70), value.slice(0, 80));
    return Boolean((control.value || '').trim());
}

async function fillWorkdayNaIfNoTextField(container, label = '', profile = null) {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    const value = getWorkdayNaIfNoTextValue(labelText, profile || window.__wdApplyData?.profile);
    const control = container.querySelector('textarea')
        || container.querySelector('input[type="text"], input[type="search"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') {
        return false;
    }
    if ((control.value || '').trim()) return true;
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} filled N/A-if-No text`, String(labelText || '').slice(0, 70), value.slice(0, 60));
    return Boolean((control.value || '').trim());
}

function isWorkdayMultiOptionAvailabilityFilled(container, candidates) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:.*required and must have a value/i.test(preview)) {
        const checked = container.querySelectorAll(
            'input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"]'
        );
        if (!checked.length) return false;
    }
    for (const input of container.querySelectorAll(
        'input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"], [role="radio"][aria-checked="true"]'
    )) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (!text || text.length > 80) continue;
        if (candidates.some(c => textMatchesCandidate(text, c))) return true;
    }
    return false;
}

async function fillWorkdayMultiOptionCheckboxField(container, candidates, { label = '', logTag = 'multi-option' } = {}) {
    if (!container || !candidates?.length) return false;
    if (isWorkdayMultiOptionAvailabilityFilled(container, candidates)) return true;
    debugLog(`${WD} fill ${logTag}`, String(label || getContainerLabel(container) || '').slice(0, 70));
    let selected = 0;
    for (const input of container.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (!text || text.length > 80) continue;
        if (!candidates.some(c => textMatchesCandidate(text, c))) continue;
        if (!isWorkdayCheckboxChecked(input)) {
            if (input.type === 'radio' || input.getAttribute('role') === 'radio') {
                await workdayClick(labelEl || input);
            } else {
                await workdayClickCheckbox(input, logTag);
            }
            await wait(200);
        }
        if (isWorkdayCheckboxChecked(input) || input.checked) {
            selected += 1;
            // Prefer first matching option for employment type; for contact time one is enough
            if (logTag !== 'shift-availability') break;
        }
    }
    debugLog(`${WD} ${logTag} checkboxes`, 'selected=', selected);
    return selected > 0 || isWorkdayMultiOptionAvailabilityFilled(container, candidates);
}

async function fillWorkdayEmploymentTypeField(container, label = '') {
    const labelText = label || getContainerLabel(container);
    const candidates = getWorkdayEmploymentTypeCandidates();
    if (isWorkdayMultiOptionAvailabilityFilled(container, candidates)
        || isWorkdaySingleSelectFilled(container, candidates)) {
        return true;
    }
    const checkboxOk = await fillWorkdayMultiOptionCheckboxField(container, candidates, {
        label: labelText, logTag: 'employment-type',
    });
    if (checkboxOk) return true;
    // Alterra-style: single-select dropdown ("Select One") instead of checkboxes
    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!ctrl) return false;
    const openKey = normalizeDropdownOpenKey(String(labelText || ''));
    resetWorkdayDropdownOpenCount(openKey);
    clearWorkdaySingleSelectMissKey(labelText);
    const ok = await fillWorkdaySingleSelectDropdown(ctrl, candidates, String(labelText || '').slice(0, 80));
    debugLog(`${WD} employment-type dropdown`, String(labelText || '').slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, candidates);
}

async function fillWorkdayBestContactTimeField(container, label = '') {
    return fillWorkdayMultiOptionCheckboxField(container, getWorkdayBestContactTimeCandidates(), {
        label, logTag: 'contact-time',
    });
}

/** Skill / ability selects (mountain biking, skiing, etc.) — pick a safe mid/none option locally. */
function isWorkdaySkillAbilityQuestion(label) {
    const l = String(label || '').toLowerCase();
    if (!l) return false;
    if (/please read before signing|i certify|privacy notice/i.test(l)) return false;
    // "availability" / "disability" contain "ability" — never treat those as skill ratings
    if (/\bavailability\b/i.test(l) || isWorkdayShiftAvailabilityQuestion(l)) return false;
    if (/disability|reasonable adjustment|require any adjustments|adjustments that are reasonable/i.test(l)) {
        return false;
    }
    return /what is your .{0,40}\bability\b|mountain biking ability|skiing ability|snowboarding ability|skill level|rate your .{0,30}(skill|\bability\b)/i.test(l);
}

function getWorkdaySkillAbilityCandidates() {
    return [
        'Intermediate', 'Beginner', 'Novice', 'Basic',
        'None', 'No experience', 'Not applicable', 'N/A',
        'Advanced', 'Expert', 'Proficient',
    ];
}

async function fillWorkdaySkillAbilityField(container, label = '') {
    const labelText = label || getContainerLabel(container);
    const candidates = getWorkdaySkillAbilityCandidates();
    if (isWorkdaySingleSelectFilled(container, candidates)) return true;
    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
    if (!ctrl) return false;
    const openKey = normalizeDropdownOpenKey(String(labelText || ''));
    resetWorkdayDropdownOpenCount(openKey);
    clearWorkdaySingleSelectMissKey(labelText);
    const ok = await fillWorkdaySingleSelectDropdown(ctrl, candidates, String(labelText || '').slice(0, 80));
    debugLog(`${WD} skill-ability dropdown`, String(labelText || '').slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, candidates);
}

function getWorkdayShiftAvailabilityCandidates() {
    return [
        'Days', 'Day', 'Day Shift', 'Days (1st shift)',
        'Evenings', 'Evening', 'Evening Shift', 'Evenings (2nd shift)',
        'Nights', 'Night', 'Night Shift', 'Nights (3rd shift)',
        'Weekends', 'Weekend',
        'Early Morning', 'Overnight',
        'All shifts', 'Any', 'Any shift', 'Flexible',
        'Morning', 'Afternoon',
        // Schedule / employment-style multi-selects (Four Seasons etc.)
        'Full Time', 'Full-Time', 'Fulltime', 'Full-time',
        'Part Time', 'Part-Time', 'Parttime', 'Part-time',
        'Seasonal', 'Seasonal/ Casual', 'Seasonal/Casual', 'Casual',
    ];
}

function isWorkdayShiftAvailabilityFilled(container) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    // Stale option labels appear in the container even when nothing is checked — never
    // treat bare preview text (or isDisclosureChoiceFilled) as evidence of a selection.
    if (/error:.*required and must have a value/i.test(preview)) return false;

    const checked = container.querySelectorAll(
        'input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"], [role="radio"][aria-checked="true"]'
    );
    for (const input of checked) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (!text || text.length > 80) continue;
        if (getWorkdayShiftAvailabilityCandidates().some(c => textMatchesCandidate(text, c))) return true;
        if (/^(days?|evenings?|nights?|weekends?|all shifts?|any(?:\s+shift)?|flexible|morning|afternoon|early\s+morning|overnight|full[\s-]?time|part[\s-]?time|seasonal|casual|\d(?:st|nd|rd) shift)\b/i.test(text)) {
            return true;
        }
        if (/\b(day|evening|night|weekend)\b.*\bshift\b|\bshift\b.*\b(day|evening|night|weekend)\b/i.test(text)) {
            return true;
        }
    }

    const selectedItems = container.querySelectorAll(
        '[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"] li, [data-automation-id="promptSelection"]'
    );
    for (const item of selectedItems) {
        const text = (item.innerText || '').replace(/\s+/g, ' ').trim();
        if (!text || text.length > 80 || /select one|0 items selected/i.test(text)) continue;
        if (/day|evening|night|weekend|morning|afternoon|flexible|any|shift|full[\s-]?time|part[\s-]?time|seasonal|casual|overnight/i.test(text)) return true;
    }

    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const multi = container.querySelector('[data-automation-id="multiselectInputContainer"]');
    const selectedRaw = (selectionLabel?.innerText || multi?.innerText || '').replace(/\s+/g, ' ').trim();
    if (!selectedRaw || /^select one$/i.test(selectedRaw) || /0 items selected/i.test(selectedRaw)) return false;
    if (/other than time off|what shifts are you available|available to work/i.test(selectedRaw) && selectedRaw.length > 80) {
        return false;
    }
    if (/[1-9]\d*\s+items?\s+selected/i.test(selectedRaw)
        && /day|evening|night|weekend|morning|afternoon|flexible|any|shift|full[\s-]?time|part[\s-]?time|seasonal/i.test(selectedRaw)) {
        return true;
    }
    return false;
}

async function fillWorkdayShiftAvailabilityField(container, label = '') {
    if (!container) return false;
    const labelText = label || getContainerLabel(container);
    if (isWorkdayShiftAvailabilityFilled(container)) return true;
    const cands = getWorkdayShiftAvailabilityCandidates();
    debugLog(`${WD} fill shift availability`, String(labelText || '').slice(0, 70));

    const looksLikeShiftOption = (text) => {
        const t = String(text || '').replace(/\s+/g, ' ').trim();
        if (!t || t.length > 80) return false;
        if (cands.some(c => textMatchesCandidate(t, c))) return true;
        if (/^(days?|evenings?|nights?|weekends?|all(?:\s+shifts?)?|any(?:\s+shift)?|flexible|morning|afternoon|early\s+morning|overnight|full[\s-]?time|part[\s-]?time|seasonal(?:\s*\/\s*casual)?|casual)\b/i.test(t)) return true;
        if (/\b\d(?:st|nd|rd)\s*shift\b/i.test(t)) return true;
        if (/\b(day|evening|night|weekend)\b.*\bshift\b|\bshift\b.*\b(day|evening|night|weekend)\b/i.test(t)) return true;
        return false;
    };

    // Prefer selecting Days + Evenings + Nights when present (max availability)
    let selected = 0;
    const inputs = [...container.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')];
    if (inputs.length) {
        debugLog(`${WD} shift availability options`, inputs.slice(0, 12).map((input) => {
            const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
            return (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim().slice(0, 40);
        }).filter(Boolean));
    }
    for (const input of inputs) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (!looksLikeShiftOption(text)) continue;
        if (!isWorkdayCheckboxChecked(input)) {
            if (input.type === 'radio' || input.getAttribute('role') === 'radio') {
                await workdayClick(labelEl || input);
            } else {
                await workdayClickCheckbox(input, 'shift-availability');
            }
            await wait(200);
        }
        if (isWorkdayCheckboxChecked(input) || input.checked) selected += 1;
        if ((input.type === 'radio' || input.getAttribute('role') === 'radio') && selected) break;
    }
    if (selected > 0 || isWorkdayShiftAvailabilityFilled(container)) {
        debugLog(`${WD} shift availability checkboxes`, 'selected=', selected);
        return true;
    }

    const trigger = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (trigger && trigger.type !== 'checkbox' && trigger.type !== 'radio') {
        clearWorkdaySingleSelectMissKey(labelText);
        resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(labelText || '')));
        const ok = await fillWorkdayScrollMultiSelect(trigger, cands, {
            logTag: 'shift-availability',
            fieldLabel: labelText,
            isFilledFn: (root) => isWorkdayShiftAvailabilityFilled(root || container),
        }) || await fillWorkdaySingleSelectDropdown(trigger, cands, String(labelText || '').slice(0, 80));
        debugLog(`${WD} shift availability dropdown`, 'ok=', ok);
        return ok || isWorkdayShiftAvailabilityFilled(container);
    }
    debugLog(`${WD} shift availability fill failed`, String(labelText || '').slice(0, 70),
        'inputs=', inputs.length, 'preview=', previewSlice(container));
    return false;
}

/** TJX / retail "My Work Availability" grids are often outside formField collection. */
function isWorkdayAvailabilityStepActive() {
    const info = getStepInfo();
    const hay = `${info.stepName || ''} ${info.stepLine || ''} ${document.body?.innerText?.slice(0, 1200) || ''}`.toLowerCase();
    return /my work availability|work availability|availability calendar|verfügbarkeit|arbeitsverf(?:ü|u)gbarkeit|select (?:your )?availability|time slots?/i.test(hay);
}

function pageHasWorkdayTimeSlotRequirementError() {
    const text = document.body?.innerText || '';
    return /select at least 1 checkbox or any time slot|at least (?:one|1) (?:checkbox or )?time slot|must select.*time slot|mindestens .*zeitschlitz|mindestens .*zeitfenster/i.test(text);
}

function pageHasWorkdayAvailabilityConflictError() {
    const text = document.body?.innerText || '';
    return /select only 1 checkbox or select only time slots|only 1 checkbox or select only time slots|cannot select both|checkbox or select only time/i.test(text);
}

function getWorkdayCheckboxAccessibleLabel(el) {
    if (!el) return '';
    const labelledBy = el.getAttribute?.('aria-labelledby');
    let fromIds = '';
    if (labelledBy) {
        fromIds = labelledBy.split(/\s+/).map(id => document.getElementById(id)?.innerText || '').join(' ');
    }
    const labelEl = (el.id && document.querySelector(`label[for="${CSS.escape(el.id)}"]`)) || el.closest('label');
    return (el.getAttribute?.('aria-label')
        || fromIds
        || labelEl?.innerText
        || el.getAttribute?.('title')
        || el.getAttribute?.('data-automation-label')
        || '').replace(/\s+/g, ' ').trim();
}

function isWorkdayConsentOrLegalCheckboxLabel(text) {
    return /agree|consent|privacy|terms|i accept|sms|email|newsletter|marketing|data protection|datenschutz|einwilligung|agb|bedingungen/i.test(String(text || ''));
}

function isWorkdayDayOrTimeSlotLabel(text) {
    const t = String(text || '').replace(/\s+/g, ' ').trim();
    if (!t || t.length > 120) return false;
    if (isWorkdayConsentOrLegalCheckboxLabel(t)) return false;
    if (/^(select all|all day|any time|anytime|available|available all|i('?| a)m available|jederzeit|ganzt(?:ä|a)gig|ganzer tag)$/i.test(t)) {
        return true;
    }
    if (/\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|mon|tue|wed|thu|fri|sat|sun)\b/i.test(t)) {
        return true;
    }
    if (/\b(montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag)\b/i.test(t)) {
        return true;
    }
    if (/\b(morning|afternoon|evening|night|overnight|early|late|shift|vormittag|nachmittag|abend|nacht)\b/i.test(t)) {
        return true;
    }
    // Time ranges: 9:00 AM - 12:00 PM, 08:00-16:00, 9am-5pm
    if (/\d{1,2}(?::\d{2})?\s*(?:am|pm)?\s*[-–—tobis]+\s*\d{1,2}/i.test(t)) return true;
    if (/\d{1,2}:\d{2}/.test(t) && /am|pm|uhr/i.test(t)) return true;
    return false;
}

function dumpWorkdayAvailabilityTimeSlotDom() {
    const widgets = [...document.querySelectorAll(
        '[data-automation-id*="availability"], [data-automation-id*="Availability"], '
        + '[data-automation-id*="timeSlot"], [data-automation-id*="TimeSlot"], '
        + '[data-automation-id*="schedule"], [data-automation-id*="Schedule"], '
        + '[data-automation-id*="calendar"], [data-automation-id*="Calendar"], '
        + 'table, [role="grid"], [role="table"]'
    )].slice(0, 12);
    debugLog(`${WD} availability widgets`, widgets.map(w => ({
        id: w.getAttribute('data-automation-id') || w.getAttribute('role') || w.tagName,
        text: (w.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 160),
        checks: w.querySelectorAll('input[type="checkbox"], [role="checkbox"]').length,
        buttons: w.querySelectorAll('button').length,
    })));

    const boxes = [...document.querySelectorAll('input[type="checkbox"], [role="checkbox"]')]
        .filter(el => {
            const r = el.getBoundingClientRect?.();
            return !r || (r.width > 0 && r.height > 0);
        })
        .slice(0, 40)
        .map(el => ({
            checked: isWorkdayCheckboxChecked(el),
            label: getWorkdayCheckboxAccessibleLabel(el).slice(0, 80),
            auto: el.getAttribute('data-automation-id') || '',
            role: el.getAttribute('role') || el.type || el.tagName,
        }));
    debugLog(`${WD} availability checkboxes dump`, boxes);

    const toggles = [...document.querySelectorAll('button, [role="button"], [aria-pressed]')]
        .map(el => ({
            text: (el.getAttribute('aria-label') || el.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 80),
            pressed: el.getAttribute('aria-pressed'),
            auto: el.getAttribute('data-automation-id') || '',
        }))
        .filter(t => t.text && isWorkdayDayOrTimeSlotLabel(t.text))
        .slice(0, 30);
    debugLog(`${WD} availability day/time toggles`, toggles);
}

function findWorkdayAvailabilityTimeSlotCheckboxes() {
    const rootCandidates = [
        ...document.querySelectorAll(
            '[data-automation-id*="availability"], [data-automation-id*="Availability"], '
            + '[data-automation-id*="timeSlot"], [data-automation-id*="TimeSlot"], '
            + '[data-automation-id*="schedule"], [data-automation-id*="Schedule"], '
            + '[data-automation-id*="calendar"], [data-automation-id*="Calendar"], '
            + '[role="grid"], [role="table"], table'
        ),
    ];
    const scopes = rootCandidates.length ? rootCandidates : [document];
    const found = [];
    const seen = new Set();
    for (const scope of scopes) {
        for (const el of scope.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
            if (seen.has(el)) continue;
            const rect = el.getBoundingClientRect?.();
            if (rect && (rect.width <= 0 || rect.height <= 0)) continue;
            const label = getWorkdayCheckboxAccessibleLabel(el);
            if (isWorkdayConsentOrLegalCheckboxLabel(label)) continue;
            // Inside availability widget → accept even unlabeled cells
            const inWidget = rootCandidates.some(r => r.contains(el));
            if (!inWidget && !isWorkdayDayOrTimeSlotLabel(label) && label) continue;
            if (!inWidget && !label) continue;
            seen.add(el);
            found.push({ el, label, prefer: /select all|any time|anytime|available all|jederzeit|ganzt/i.test(label)
                || isWorkdayDayOrTimeSlotLabel(label) });
        }
    }
    // Page-wide fallback when step is availability but widgets weren't found
    if (!found.length && (isWorkdayAvailabilityStepActive() || pageHasWorkdayTimeSlotRequirementError())) {
        for (const el of document.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
            if (seen.has(el)) continue;
            const rect = el.getBoundingClientRect?.();
            if (rect && (rect.width <= 0 || rect.height <= 0)) continue;
            const label = getWorkdayCheckboxAccessibleLabel(el);
            if (isWorkdayConsentOrLegalCheckboxLabel(label)) continue;
            if (!isWorkdayDayOrTimeSlotLabel(label) && label) continue;
            // Unlabeled checkboxes on availability step (grid cells)
            if (!label && !isWorkdayAvailabilityStepActive() && !pageHasWorkdayTimeSlotRequirementError()) continue;
            seen.add(el);
            found.push({ el, label, prefer: true });
        }
    }
    return found;
}

function getWorkdayAvailabilityPageRoot() {
    return document.querySelector('[data-automation-id="applyFlowMyAvailabilityPage"]') || document.body;
}

function getWorkdayAvailabilityPressedTimeToggles(root = getWorkdayAvailabilityPageRoot()) {
    return [...root.querySelectorAll('button[aria-pressed="true"], [role="button"][aria-pressed="true"]')]
        .filter(el => {
            const t = (el.getAttribute('aria-label') || el.innerText || '').replace(/\s+/g, ' ').trim();
            return /\d{1,2}(?::\d{2})?\s*(?:am|pm)?\s*[-–—]/i.test(t) || /select all/i.test(t);
        });
}

function getWorkdayAvailabilityUnpressedTimeToggles(root = getWorkdayAvailabilityPageRoot()) {
    return [...root.querySelectorAll('button[aria-pressed="false"], [role="button"][aria-pressed="false"]')]
        .filter(el => {
            const t = (el.getAttribute('aria-label') || el.innerText || '').replace(/\s+/g, ' ').trim();
            return /\d{1,2}(?::\d{2})?\s*(?:am|pm)?\s*[-–—]/i.test(t) || /select all/i.test(t);
        });
}

function getWorkdayAvailabilityCheckedBoxes(root = getWorkdayAvailabilityPageRoot()) {
    return [...root.querySelectorAll('input[type="checkbox"], [role="checkbox"]')]
        .filter(el => {
            const rect = el.getBoundingClientRect?.();
            if (rect && (rect.width <= 0 || rect.height <= 0)) return false;
            const label = getWorkdayCheckboxAccessibleLabel(el);
            if (isWorkdayConsentOrLegalCheckboxLabel(label)) return false;
            return isWorkdayCheckboxChecked(el);
        });
}

function isWorkdayAvailabilityTimeSlotFilled() {
    if (pageHasWorkdayAvailabilityConflictError()) return false;
    const root = getWorkdayAvailabilityPageRoot();
    const pressed = getWorkdayAvailabilityPressedTimeToggles(root);
    const checked = getWorkdayAvailabilityCheckedBoxes(root);
    const hasToggleUi = pressed.length > 0
        || getWorkdayAvailabilityUnpressedTimeToggles(root).length > 0
        || !!document.querySelector('[data-automation-id="applyFlowMyAvailabilityPage"]');

    // My Availability page: checkbox mode XOR time-slot mode
    if (hasToggleUi) {
        if (pressed.length && checked.length) return false;
        if (pressed.length > 0) return true;
        if (checked.length === 1) return true; // e.g. I'm flexible alone
        if (checked.length > 1) return false;
        return !pageHasWorkdayTimeSlotRequirementError();
    }

    // Checkbox-only grids (overnight / day parts): any selection is enough
    if (checked.length > 0) return true;
    const labeledSlots = findWorkdayAvailabilityTimeSlotCheckboxes().filter(s => s.label);
    if (labeledSlots.some(({ el }) => isWorkdayCheckboxChecked(el))) return true;
    return !pageHasWorkdayTimeSlotRequirementError();
}

async function clearWorkdayAvailabilityCheckboxes(root = getWorkdayAvailabilityPageRoot()) {
    let cleared = 0;
    for (const el of root.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
        if (!isWorkdayCheckboxChecked(el)) continue;
        const label = getWorkdayCheckboxAccessibleLabel(el);
        if (isWorkdayConsentOrLegalCheckboxLabel(label)) continue;
        await workdayUncheckCheckbox(el, 'availability-clear-checkbox');
        cleared += 1;
    }
    // Also click "I'm flexible" if it stays selected as a button
    for (const el of root.querySelectorAll('button, [role="button"], label')) {
        const t = (el.getAttribute('aria-label') || el.innerText || '').replace(/\s+/g, ' ').trim();
        if (!/^i('?| a)m flexible$/i.test(t) && !/^i('?| a)m flexible\b/i.test(t)) continue;
        if (el.getAttribute('aria-pressed') === 'true' || el.getAttribute('aria-checked') === 'true') {
            await workdayClick(el);
            await wait(150);
            cleared += 1;
        }
    }
    debugLog(`${WD} availability cleared checkboxes`, cleared);
    return cleared;
}

async function fillWorkdayAvailabilityTimeSlotGrid() {
    const root = getWorkdayAvailabilityPageRoot();
    const hasToggleUi = getWorkdayAvailabilityUnpressedTimeToggles(root).length > 0
        || getWorkdayAvailabilityPressedTimeToggles(root).length > 0;
    const needed = isWorkdayAvailabilityStepActive()
        || pageHasWorkdayTimeSlotRequirementError()
        || pageHasWorkdayAvailabilityConflictError()
        || /availability|verfügbarkeit|time slot/i.test(getStepInfo().stepName || '')
        || !!document.querySelector('[data-automation-id="applyFlowMyAvailabilityPage"]');
    if (!needed && !hasToggleUi && !findWorkdayAvailabilityTimeSlotCheckboxes().length) {
        return false;
    }

    if (pageHasWorkdayAvailabilityConflictError()
        || (getWorkdayAvailabilityPressedTimeToggles(root).length
            && getWorkdayAvailabilityCheckedBoxes(root).length)) {
        dumpWorkdayAvailabilityTimeSlotDom();
        await clearWorkdayAvailabilityCheckboxes(root);
        await wait(300);
    }

    if (isWorkdayAvailabilityTimeSlotFilled() && !pageHasWorkdayTimeSlotRequirementError()
        && !pageHasWorkdayAvailabilityConflictError()) {
        debugLog(`${WD} availability time slots already filled`);
        return true;
    }

    dumpWorkdayAvailabilityTimeSlotDom();
    let selected = 0;

    // Prefer time-slot toggles when present — never mix with "I'm flexible" checkboxes
    if (hasToggleUi || getWorkdayAvailabilityUnpressedTimeToggles(root).length) {
        await clearWorkdayAvailabilityCheckboxes(root);

        const selectAllBtns = [...root.querySelectorAll('button, [role="button"]')]
            .filter(el => /^select all$/i.test((el.getAttribute('aria-label') || el.innerText || '').replace(/\s+/g, ' ').trim()));
        for (const btn of selectAllBtns) {
            await workdayClick(btn);
            await wait(120);
            selected += 1;
            debugLog(`${WD} availability Select All day`);
        }

        // Ensure individual ranges are pressed if Select All didn't cover them
        for (const btn of getWorkdayAvailabilityUnpressedTimeToggles(root)) {
            const text = (btn.getAttribute('aria-label') || btn.innerText || '').replace(/\s+/g, ' ').trim();
            if (/select all/i.test(text)) continue;
            await workdayClick(btn);
            await wait(80);
            if (btn.getAttribute('aria-pressed') === 'true') {
                selected += 1;
                debugLog(`${WD} availability toggle pressed`, text.slice(0, 60));
            }
            if (selected >= 30) break;
        }

        const ok = isWorkdayAvailabilityTimeSlotFilled();
        debugLog(`${WD} availability time slots fill (toggles)`, 'selected=', selected, 'ok=', ok,
            'pressed=', getWorkdayAvailabilityPressedTimeToggles(root).length);
        return ok;
    }

    // Checkbox-only grids (e.g. overnight days) — check labeled day slots, not flexible+others mix
    let slots = findWorkdayAvailabilityTimeSlotCheckboxes().filter(s => s.label);
    debugLog(`${WD} availability time slots found`, slots.length,
        slots.slice(0, 15).map(s => s.label.slice(0, 50) || '(unlabeled)'));
    for (const { el, label } of slots) {
        if (isWorkdayCheckboxChecked(el)) {
            selected += 1;
            continue;
        }
        await workdayClickCheckbox(el, 'availability-timeslot');
        await wait(120);
        if (isWorkdayCheckboxChecked(el)) {
            selected += 1;
            debugLog(`${WD} availability slot checked`, label.slice(0, 60));
        }
        if (selected >= 24) break;
    }

    const ok = isWorkdayAvailabilityTimeSlotFilled() || selected > 0;
    debugLog(`${WD} availability time slots fill`, 'selected=', selected, 'ok=', ok,
        'filled=', isWorkdayAvailabilityTimeSlotFilled());
    return ok;
}

function previewSlice(container) {
    return String(container?.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 120);
}

function isWorkdayFormerEmployerAffiliateTextField(label) {
    const l = String(label || '').toLowerCase();
    if (/^(yes|no|n\/a)$/i.test(l.trim())) return false;
    // jdpa.wd501 (and similar): "Have you ever been employed by or provided services as a
    // contractor to … or any of its … affiliates?" is a Yes/No — the old /provide.*affiliate/
    // pattern matched "provided … affiliates" and misrouted it to a free-text filler that wrote
    // nothing (optional '') / N/A into a checkbox group, leaving information stuck.
    if (/^\s*(have you|are you|were you|did you)\b/i.test(l)
        && /(?:been )?employed|provided services as a contractor|worked (?:at|for)|previously employed/i.test(l)
        && !/(?:provide|enter|specify|list)\s+(?:the\s+)?(?:name\s+of\s+)?(?:company|affiliate)/i.test(l)) {
        return false;
    }
    // Require an explicit "provide/enter/specify/list … company/affiliate" ask — not "provided services".
    return /(?:provide|enter|specify|list)\s+(?:the\s+)?(?:name\s+of\s+)?(?:company|affiliate)|most recent (?:company|affiliate)|company\/affiliate|affiliate name|name of (?:the )?(?:company|affiliate)/i.test(l)
        && /(?:employed at|worked at|worked for|our company|this company|ever been employed|affiliate below|if yes)/i.test(l);
}

/** Free-text "If yes, give dates/position" follow-ups — not Yes/No dropdowns. */
function isWorkdayFormerEmployerTextFollowUp(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (!/previously (?:employed|applied)|ever (?:been )?employed|worked for|affiliate/i.test(l)) return false;
    if (!/if yes|please give dates|when and for what|format:\s*mm\/dd/i.test(l)) return false;
    if (!container) return true;
    const hasText = Boolean(container.querySelector('textarea, input[type="text"], input[type="search"]'));
    const hasDropdown = Boolean(container.querySelector(
        'button[aria-haspopup="listbox"], [data-automation-id="promptSelectionLabel"], [role="combobox"], input[type="radio"]'
    ));
    return hasText && !hasDropdown;
}

function getWorkdayFormerEmployerTextFollowUpValue(label) {
    const l = String(label || '').toLowerCase();
    if (/format:\s*mm\/dd|please give dates/i.test(l)) {
        return 'N/A';
    }
    if (/when and for what|previously applied/i.test(l)) {
        return 'N/A — I have not previously applied.';
    }
    return 'N/A';
}

async function fillWorkdayFormerEmployerTextFollowUp(container, label) {
    const control = container?.querySelector('textarea')
        || container?.querySelector('input[type="text"], input[type="search"]')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') {
        return false;
    }
    const value = getWorkdayFormerEmployerTextFollowUpValue(label);
    const current = (control.value || '').trim();
    const preview = (container?.innerText || '').toLowerCase();
    if (current && !/required and must have a value/i.test(preview)
        && (/^n\/a\b/i.test(current) || /^no\b/i.test(current))) {
        return true;
    }
    workdayScrollToTarget(control, 120);
    // Prefer short N/A — long "No, I have not..." often fails Workday date-format validation
    await workdayTypeElement(control, value);
    await wait(300);
    control.dispatchEvent(new Event('blur', { bubbles: true, composed: true }));
    await wait(300);
    let ok = Boolean((control.value || '').trim())
        && !/required and must have a value/i.test((container?.innerText || '').toLowerCase());
    if (!ok) {
        // Same React-commit path used for salary textareas
        await commitWorkdayNumericInput(control, value, label);
        ok = Boolean((control.value || '').trim())
            && !/required and must have a value/i.test((container?.innerText || '').toLowerCase());
    }
    debugLog(`${WD} former employer text follow-up`, String(label || '').slice(0, 70), value, 'ok=', ok);
    return ok || Boolean((control.value || '').trim());
}

function getWorkdayFormerEmployerAffiliateTextValue(label, container = null) {
    const required = container ? isContainerRequired(container) : String(label || '').includes('*');
    return required ? 'N/A' : '';
}

async function fillWorkdayFormerEmployerAffiliateTextField(container, label) {
    const value = getWorkdayFormerEmployerAffiliateTextValue(label, container);
    if (!value) {
        debugLog(`${WD} skip optional former-employer affiliate text`, String(label || '').slice(0, 70));
        return true;
    }
    const control = container.querySelector('textarea')
        || getContainerControl(container);
    if (!control || control.type === 'radio' || control.type === 'checkbox' || control.type === 'file') return false;
    if ((control.value || '').trim()) return true;
    workdayScrollToTarget(control, 120);
    await workdayTypeElement(control, value);
    debugLog(`${WD} filled former-employer affiliate text`, String(label || '').slice(0, 70), value);
    return Boolean((control.value || '').trim());
}

function isWorkdayFormerEmployerQuestion(label) {
    if (isWorkdayFormerEmployerAffiliateTextField(label)) return false;
    if (isWorkdayFormerEmployerTextFollowUp(label)) return false;
    if (isWorkdayGovernmentEmploymentQuestion(label)) return false;
    if (isWorkdayClinicalSettingsQuestion(label)) return false;
    const l = String(label || '').toLowerCase();
    if (isWorkdayNotToMyKnowledgeLabel(l)) return false;
    if (/to the best of your knowledge/i.test(l)) return false;
    if (/certain federal law may require/i.test(l)) return false;
    if (/please select your employment status/i.test(l)) return false;
    // Guidehouse / BAH-style "employed by any US Federal/State/Local Government" is a Yes/No
    // disclosure — not a former-employer-at-this-company question (misrouting left it empty).
    if (/federal.*government|state.*local government|quasi.?governmental|foreign government|multi-lateral/i.test(l)
        && /employed|employment|service in the .{0,20}armed/i.test(l)) {
        return false;
    }
    // cisco.wd5 (and similar): "Have you ever been issued a … Employee ID or … email address?"
    // is a prior-affiliation Yes/No — not a free-text Employee ID field. Without this, information
    // stays empty (Error-Have you ever been issued…) while other profile fields look filled.
    if (/been issued .{0,80}employee id|employee id or .{0,60}email address|issued a .{0,40}(?:employee|badge) id/i.test(l)) {
        return true;
    }
    return /worked at|worked for|have you worked (?:at|for)|ever worked (?:at|for)|previously worked (?:at|for)|former employee|previously employed|previously been employed|been employed by|ever been employed|engaged as a contingent|contingent resource|following capacity|current .{0,40}contractor|are you a current/i.test(l);
}

function isWorkdayClinicalSettingsQuestion(label) {
    const l = String(label || '').toLowerCase();
    return /clinical settings.*previously worked|settings have you previously worked|hospital, skilled nursing, home health/i.test(l);
}

function getClinicalSettingsCandidates(profile) {
    const chunks = [];
    const add = (v) => { if (v) chunks.push(String(v).toLowerCase()); };
    add(profile?.headline);
    add(profile?.summary);
    add(profile?.professionalSummary);
    add(profile?.general?.professionalSummary);
    add(profile?.general?.summary);
    for (const j of profile?.experience || profile?.workExperience || []) {
        add(j?.title);
        add(j?.company);
        add(j?.description);
    }
    const text = chunks.join(' ');
    const out = [];
    const push = (...vals) => vals.forEach(v => { if (!out.includes(v)) out.push(v); });
    if (/home health|homehealth|field rn|visit nurse/i.test(text)) push('Home Health', 'Home health');
    if (/hospice|palliative/i.test(text)) push('Hospice');
    if (/hospital|medical center|acute care|emergency|icu|\ber\b/i.test(text)) push('Hospital', 'Acute Care');
    if (/skilled nursing|snf|nursing facility|long.?term care|rehabilitation/i.test(text)) push('Skilled Nursing', 'Skilled nursing');
    if (!out.length) push('Home Health', 'Hospital');
    return out;
}

function isWorkdayClinicalSettingsFilled(container, profile = null) {
    if (!container) return false;
    const fullPreview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/select one|0 items selected|error:.*required/i.test(fullPreview)) return false;

    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const multi = container.querySelector('[data-automation-id="multiselectInputContainer"]');
    const selectedRaw = (selectionLabel?.innerText || multi?.innerText || getWorkdayFieldSelectedText(container) || '')
        .replace(/\s+/g, ' ').trim();
    const label = (getContainerLabel(container) || '').replace(/\s+/g, ' ').trim();
    let selected = selectedRaw;
    if (label && selected.toLowerCase().startsWith(label.toLowerCase())) {
        selected = selected.slice(label.length).replace(/^\s*\*?\s*/, '').trim();
    }
    if (selected && !/^select one$/i.test(selected) && !/0 items selected/i.test(selected)
        && /home health|hospital|skilled nursing|hospice|acute care/i.test(selected)
        && !/for example/i.test(selected)) {
        return true;
    }
    const cands = getClinicalSettingsCandidates(profile || window.__wdApplyData?.profile || {});
    return isDisclosureChoiceFilled(container, cands);
}

async function fillWorkdayClinicalSettingsCheckboxGroup(container, cands, label) {
    let selected = 0;
    for (const input of container.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')) {
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').trim();
        if (!text || !cands.some(c => textMatchesCandidate(text, c))) continue;
        if (!isWorkdayCheckboxChecked(input) && await workdayClickCheckbox(input, 'clinical-settings')) {
            selected += 1;
            await wait(250);
        } else if (input.type === 'radio' && !input.checked) {
            await workdayClick(labelEl || input);
            selected += 1;
            await wait(250);
        }
    }
    for (const opt of container.querySelectorAll('[role="menuitemcheckbox"], [data-automation-id="menuItem"], [role="option"]')) {
        const text = (opt.getAttribute('aria-label') || opt.innerText || '').replace(/\s+/g, ' ').trim();
        if (!text || !cands.some(c => textMatchesCandidate(text, c))) continue;
        debugLog(`${WD} clinical settings option`, label.slice(0, 50), text.slice(0, 70));
        if (await clickWorkdayOption(opt)) selected += 1;
        await wait(250);
    }
    return selected;
}

async function fillWorkdayClinicalSettingsField(container, label, profile) {
    if (!container) return false;
    if (isWorkdayClinicalSettingsFilled(container, profile)) {
        debugLog(`${WD} clinical settings already filled`, label.slice(0, 60));
        return true;
    }
    const cands = getClinicalSettingsCandidates(profile);
    const dropdownCands = [...new Set([
        ...cands,
        'Home Health', 'Hospital', 'Skilled Nursing', 'Skilled nursing', 'Hospice', 'Acute Care',
    ])];
    const ctrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (ctrl) {
        clearWorkdaySingleSelectMissKey(label);
        const dropdownOk = await fillWorkdaySingleSelectDropdown(ctrl, dropdownCands, label);
        if (dropdownOk || isWorkdayClinicalSettingsFilled(container, profile)) {
            debugLog(`${WD} clinical settings dropdown`, label.slice(0, 60), 'ok=', dropdownOk);
            return true;
        }
    }

    if (isWorkdayMultiOptionCheckboxGroup(container)) {
        const selected = await fillWorkdayClinicalSettingsCheckboxGroup(container, cands, label);
        const ok = selected > 0 || isWorkdayClinicalSettingsFilled(container, profile);
        debugLog(`${WD} clinical settings inline`, label.slice(0, 60), 'selected=', selected, 'ok=', ok);
        if (ok) return true;
    }

    const trigger = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (trigger) {
        debugLog(`${WD} clinical settings popup open`, label.slice(0, 60), 'cands=', cands.slice(0, 3).join('|'));
        await closeWorkdayPopups();
        await wait(200);
        await workdayClick(trigger);
        await wait(1200);
        const controlsId = trigger.getAttribute('aria-controls');
        let popup = controlsId ? document.getElementById(controlsId) : null;
        if (!popup || !isVisibleElement(popup) || isWrongPopupForField(popup, label.toLowerCase())) {
            popup = findPopupNearField(container, 'home health');
        }
        const scope = (popup && !isWrongPopupForField(popup, label.toLowerCase())) ? popup : null;
        if (scope) {
            const optionPreview = getSingleSelectDropdownOptions(scope, false).slice(0, 12).map(o => optionText(o));
            debugLog(`${WD} clinical settings popup options`, optionPreview.join(' | '));
            let selected = await fillWorkdayClinicalSettingsCheckboxGroup(scope, dropdownCands, label);
            if (!selected) {
                for (const opt of getSingleSelectDropdownOptions(scope, false)) {
                    const text = optionText(opt);
                    if (!text || !dropdownCands.some(c => textMatchesCandidate(text, c))) continue;
                    debugLog(`${WD} clinical settings popup option`, text.slice(0, 70));
                    if (await clickWorkdayOption(opt)) selected += 1;
                    await wait(400);
                    if (isWorkdayClinicalSettingsFilled(container, profile)) break;
                }
            }
            await closeWorkdayPopups();
            await wait(400);
            if (selected > 0 || isWorkdayClinicalSettingsFilled(container, profile)) {
                debugLog(`${WD} clinical settings popup fill`, label.slice(0, 60), 'selected=', selected);
                return true;
            }
        } else {
            await closeWorkdayPopups();
        }
    }

    const textAnswer = dropdownCands.filter((v, i, a) => a.findIndex(x => x.toLowerCase() === v.toLowerCase()) === i).slice(0, 2).join(', ');
    const textarea = container.querySelector('textarea');
    const plainInput = container.querySelector('input[type="text"], input:not([type])');
    const textEl = textarea || (plainInput && plainInput.getAttribute('role') !== 'combobox' && !plainInput.getAttribute('aria-haspopup') ? plainInput : null);
    if (textEl) {
        await workdayTypeElement(textEl, textAnswer);
        const ok = Boolean((textEl.value || '').trim());
        debugLog(`${WD} clinical settings text`, label.slice(0, 60), textAnswer, 'ok=', ok);
        return ok;
    }

    const selected = await fillWorkdayClinicalSettingsCheckboxGroup(container, cands, label);
    const ok = selected > 0 || isWorkdayClinicalSettingsFilled(container, profile);
    debugLog(`${WD} clinical settings fill`, label.slice(0, 60), 'selected=', selected, 'ok=', ok);
    return ok;
}

function getWorkdayFormerEmployerCheckboxCandidates(label) {
    const candidates = [
        'No',
        // montefiore.wd12 entity list: "I have never worked for Montefiore or any of its entities"
        'I have never worked for',
        'I have never worked',
        'never worked for',
        'never worked',
        'I have not worked for Adobe in the past',
        'I have not worked for Adobe in the past.',
        'I have not worked for',
        'have not worked for',
        'I have not worked',
        'have not worked',
        'not worked for',
        'No, I have not',
        'None of the above',
        'Not applicable',
        'N/A',
    ];
    const l = String(label || '');
    const companyMatch = l.match(/(?:worked|work)\s+(?:at\s+or\s+for|at|for)\s+(?:a\s+)?([A-Za-z0-9&.' -]+?)(?:\s+or\s+(?:any of )?its|\s+or\s+any of the following|\s+in\s+the\s+following|\?|$)/i);
    if (companyMatch) {
        const company = companyMatch[1].trim();
        if (company) {
            candidates.unshift(`I have never worked for ${company} or any of its entities`);
            candidates.unshift(`I have never worked for ${company}`);
            candidates.unshift(`I have not worked for ${company} in the past.`);
            candidates.unshift(`I have not worked for ${company} in the past`);
            candidates.unshift(`I have not worked for ${company}`);
        }
    }
    return candidates;
}

/** Relatives-at-employer entity dropdown (montefiore.wd12) — not bare Yes/No. */
function isWorkdayRelativeEmployerEntityQuestion(label) {
    const l = String(label || '').toLowerCase();
    if (!/relative|family member/i.test(l)) return false;
    if (/if yes, who|what is their role/i.test(l)) return false;
    return /work for|employed by|work at|its entities/i.test(l);
}

function getWorkdayRelativeEmployerEntityCandidates(label = '') {
    return [
        'I do not have any relatives who work for',
        'I do not have any relatives',
        'do not have any relatives',
        'no relatives',
        'None of the above',
        'Not applicable',
        'N/A',
        'No',
    ];
}

async function fillWorkdayRelativeEmployerEntityField(container, label) {
    if (!container) return false;
    const cands = getWorkdayRelativeEmployerEntityCandidates(label);
    if (isWorkdaySingleSelectFilled(container, cands)
        || /do not have any relatives|no relatives|none of the above/i.test(getWorkdayFieldSelectedText(container) || '')) {
        return true;
    }
    const ctrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!ctrl) return false;
    clearWorkdaySingleSelectMissKey(label);
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(String(label || '')));
    const ok = await fillWorkdaySingleSelectDropdown(ctrl, cands, String(label || '').toLowerCase());
    debugLog(`${WD} relative-employer entity`, String(label || '').slice(0, 60), 'ok=', ok);
    return ok || isWorkdaySingleSelectFilled(container, cands)
        || /do not have any relatives/i.test(getWorkdayFieldSelectedText(container) || '');
}

function shouldUseBareYesNoForContainer(container, value, label = '') {
    if (!/^(yes|no)$/i.test(String(value))) return true;
    const lbl = label || getContainerLabel(container);
    if (isWorkdayFormerEmployerQuestion(lbl)) return false;
    if (isWorkdayMultiOptionCheckboxGroup(container)) return false;
    return true;
}

/** True when selected text is just the Yes/No option labels, not a committed answer. */
function isWorkdayYesNoOptionListText(text) {
    const t = String(text || '').replace(/\s+/g, ' ').trim().toLowerCase();
    if (!t) return false;
    if (/^(yes|no)(\s*\/\s*|\s+)(yes|no)$/i.test(t)) return true;
    if (/^(yes|no)(\s+(yes|no))+$/i.test(t)) return true;
    return false;
}

/** Explicit No selection — not the unselected "Yes No" option list. */
function isWorkdayExplicitNoSelectionText(text) {
    const t = String(text || '').replace(/\s+/g, ' ').trim().toLowerCase();
    if (!t || isWorkdayYesNoOptionListText(t)) return false;
    if (/\byes\b/.test(t) && /\bno\b/.test(t)) return false;
    return /^no$/i.test(t)
        || /^no\b/.test(t)
        || /have not worked|never worked|not worked for|not previously|i have not/i.test(t);
}

function isWorkdayFormerEmployerFilled(container, label) {
    // Opaque prompt id / Yes-No commit must win over a stale boolean "yes" checkbox that can
    // linger in the same formField after a successful data-value No fill (carrier.wd5).
    const comboboxVal = getWorkdayComboboxInputValue(container);
    if (isWorkdayOpaqueOptionId(comboboxVal)) return true;
    if (isWorkdayYesNoFilled(container, 'No')) return true;
    const boolCheckbox = getWorkdayBooleanYesCheckbox(container);
    if (boolCheckbox && isWorkdayCheckboxChecked(boolCheckbox)) return false;
    const hasYesNoRadios = containerHasWorkdayYesNoRadios(container);
    const hasYesNoCheckboxes = isWorkdayYesNoCheckboxGroup(container);
    if (hasYesNoRadios || hasYesNoCheckboxes) {
        return isWorkdayYesNoFilled(container, 'No');
    }
    const preview = (container?.innerText || '').replace(/\s+/g, ' ');
    if (/select one|0 items selected|error:.*required/i.test(preview) && !isWorkdayOpaqueOptionId(comboboxVal)) {
        // Combobox may show typed "No" without a committed selection — still empty
        const sel = getWorkdayFieldSelectedText(container);
        if (!sel || /^select one$/i.test(sel) || /0 items selected/i.test(sel) || isWorkdayYesNoOptionListText(sel)) {
            return false;
        }
    }
    const cands = getWorkdayFormerEmployerCheckboxCandidates(label);
    // For a genuine multi-option checkbox group (Employee/Intern/.../"I have not worked for X in
    // the past.") the container's own innerText always lists every option label regardless of which
    // (if any) is actually checked. getWorkdayFieldSelectedText() is built for dropdown/combobox
    // controls whose preview text reflects only the current selection — for a checkbox list it
    // returns the concatenation of ALL option labels, and textMatchesCandidate()'s substring check
    // then makes any candidate (e.g. "I have not worked for Adobe in the past.") look like a "match"
    // even though nothing is checked yet. isDisclosureChoiceFilled(container, cands) right below has
    // the exact same "scan container.innerText for a candidate substring" shape, so it is just as
    // vulnerable to this false positive — this guard MUST run before that call, not after (it
    // previously sat below the isDisclosureChoiceFilled check, so the false positive fired first on
    // every genuine multi-option checkbox group and the guard never got a chance to run). That false
    // positive reported the field as already filled, skipped the click entirely, and Workday's own
    // validation kept rejecting Next ("is required and must have a value") — an infinite re-stream
    // loop and "Workday step stuck: questions" on every tenant using this two-part former-employer
    // pattern (Yes/No question + checkbox-group follow-up), not just one employer (observed on
    // slihrms.wd3's Deloitte/AtkinsRéalis conflict-of-interest question).
    if (isWorkdayMultiOptionCheckboxGroup(container)) return false;
    if (isDisclosureChoiceFilled(container, cands)) return true;
    const selected = getWorkdayFieldSelectedText(container);
    if (selected && !/^select one$/i.test(selected) && !/0 items selected/i.test(selected)
        && !isWorkdayYesNoOptionListText(selected)) {
        if (cands.some(c => textMatchesCandidate(selected, c) || textMatchesCandidate(c, selected))) return true;
        if (isWorkdayExplicitNoSelectionText(selected)) {
            return !/select one|error:.*required/i.test(preview);
        }
    }
    return false;
}

function getWorkdayBooleanYesCheckbox(container) {
    if (!container) return null;
    const checkboxes = [...container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')];
    const boolByValue = checkboxes.find((input) => /^(true|yes|1)$/i.test(String(input.value || '').trim()));
    if (boolByValue) return boolByValue;
    const yesNoPair = getWorkdayYesNoCheckboxInputs(container);
    if (yesNoPair) return null;
    if (checkboxes.length === 1 && container.querySelector('input[type="radio"]')) {
        if (containerHasWorkdayYesNoRadios(container)) return null;
        return checkboxes[0];
    }
    return null;
}

async function clearWorkdayFormerEmployerYesCheckboxes(container) {
    if (!container) return false;
    let cleared = false;
    for (const input of container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
        if (!isWorkdayCheckboxChecked(input)) continue;
        const labelEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`))
            || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').trim().toLowerCase();
        const value = String(input.value || '').toLowerCase();
        const isNoChoice = text === 'no' || text.startsWith('no ') || /have not worked|never worked|not worked/i.test(text);
        if (isNoChoice) continue;
        const isYesChoice = text === 'yes' || text.startsWith('yes ') || value === 'true' || value === 'yes';
        if (!isYesChoice && !value) continue;
        debugLog(`${WD} former employer uncheck yes checkbox`, text.slice(0, 50) || value);
        if (await workdayUncheckCheckbox(input)) cleared = true;
        await wait(150);
    }
    return cleared;
}

function containerHasWorkdayYesNoRadios(container) {
    if (!container) return false;
    return [...container.querySelectorAll('input[type="radio"]')].some(radio => {
        const labelEl = document.querySelector(`label[for="${CSS.escape(radio.id)}"]`) || radio.closest('label');
        const t = (labelEl?.innerText || radio.getAttribute('aria-label') || '').trim().toLowerCase();
        return t === 'yes' || t === 'no' || t.startsWith('yes ') || t.startsWith('no ');
    });
}

async function fillWorkdayFormerEmployerField(container, label, extraCandidates = []) {
    if (!container) return false;
    const boolCheckbox = getWorkdayBooleanYesCheckbox(container);
    if (boolCheckbox && isWorkdayCheckboxChecked(boolCheckbox)) {
        debugLog(`${WD} former employer uncheck boolean yes`, label.slice(0, 60));
        await workdayUncheckCheckbox(boolCheckbox, 'former-employer-boolean');
        await wait(250);
    }
    if (isWorkdayFormerEmployerFilled(container, label)) {
        debugLog(`${WD} former employer already filled`, label.slice(0, 60));
        return true;
    }
    if (boolCheckbox && !containerHasWorkdayYesNoRadios(container) && !isWorkdayMultiOptionCheckboxGroup(container)) {
        const ok = !isWorkdayCheckboxChecked(boolCheckbox);
        if (ok) markWorkdayLockedYesNoFilled(label);
        debugLog(`${WD} former employer boolean No`, label.slice(0, 60), 'ok=', ok);
        return ok;
    }
    // Simple Yes/No radio or dropdown — No immediately, no popup/AI.
    if (!isWorkdayMultiOptionCheckboxGroup(container)) {
        if (container.querySelector('input[type="radio"]')) {
            await clearWorkdayFormerEmployerYesCheckboxes(container);
            const ok = await fillWorkdayYesNo(container, 'No');
            await clearWorkdayFormerEmployerYesCheckboxes(container);
            const boolCb = getWorkdayBooleanYesCheckbox(container);
            if (boolCb && isWorkdayCheckboxChecked(boolCb)) {
                debugLog(`${WD} former employer force uncheck boolean`, label.slice(0, 60));
                await workdayUncheckCheckbox(boolCb);
                await wait(200);
            }
            if (ok) markWorkdayLockedYesNoFilled(label);
            const verified = isWorkdayYesNoFilled(container, 'No');
            debugLog(`${WD} former employer radio No`, label.slice(0, 60), 'ok=', ok, 'verified=', verified);
            return verified || ok;
        }
        const ctrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
        if (ctrl) {
            // Always try Yes/No first for former-employer (labels often say "If yes, give dates"
            // without showing No in the closed preview, so isLikelyYesNoDropdown is false).
            clearWorkdaySingleSelectMissKey(label);
            const openKey = normalizeDropdownOpenKey(String(label || ''));
            resetWorkdayDropdownOpenCount(openKey);
            const ynOk = await fillWorkdaySingleSelectDropdown(ctrl, [
                'I have never worked for', 'I have never worked', 'never worked',
                'I have not worked for', 'I have not worked', 'have not worked',
                'No', 'no', 'I have not', 'Never', 'Not applicable', 'N/A', 'None of the above',
            ], label);
            if (ynOk || isWorkdayFormerEmployerFilled(container, label) || isWorkdayYesNoFilled(container, 'No')) {
                markWorkdayLockedYesNoFilled(label);
                debugLog(`${WD} former employer yes/no dropdown No`, label.slice(0, 60), 'ok=', true);
                return true;
            }
        }
    }
    const extras = (Array.isArray(extraCandidates) ? extraCandidates : [extraCandidates])
        .filter(v => v !== null && v !== undefined && String(v).trim())
        .map(String);
    const cands = [...extras, ...getWorkdayFormerEmployerCheckboxCandidates(label)];
    if (!cands.length) return false;
    // A genuine multi-option checkbox group (Employee/Intern/.../"I have not worked for X in the
    // past.") is never a dropdown — getWorkdayDropdownTrigger()/getContainerControl() can still
    // return a truthy "control" here (e.g. the first checkbox input in the list), which sent this
    // exclusive-checkbox question through fillWorkdaySingleSelectDropdown() as if it were a
    // combobox. That path can report a false "ok=true" without ever checking the right option,
    // leaving the group empty while Workday's own validation kept rejecting Next — go straight to
    // the dedicated exclusive-checkbox fill below instead.
    const trigger = getWorkdayDropdownTrigger(container) || getContainerControl(container);
    if (!isWorkdayMultiOptionCheckboxGroup(container)) {
        if (trigger) {
            const singleOk = await fillWorkdaySingleSelectDropdown(trigger, cands, label);
            if (singleOk || isWorkdayFormerEmployerFilled(container, label)) {
                markWorkdayLockedYesNoFilled(label);
                debugLog(`${WD} former employer single-select`, label.slice(0, 60), 'ok=', true);
                return true;
            }
        }
    }
    if (isWorkdayMultiOptionCheckboxGroup(container)) {
        const ok = await fillWorkdayExclusiveCheckboxGroup(container, cands, { label });
        debugLog(`${WD} former employer inline`, label.slice(0, 60), 'ok=', ok);
        return ok || isWorkdayFormerEmployerFilled(container, label);
    }
    const isFilled = () => isWorkdayFormerEmployerFilled(container, label);
    if (trigger) {
        const msOk = await fillWorkdayScrollMultiSelect(trigger, cands, {
            logTag: 'former-employer',
            fieldLabel: label,
            isFilledFn: (root) => isWorkdayFormerEmployerFilled(root || container, label),
        });
        if (msOk || isFilled()) {
            markWorkdayLockedYesNoFilled(label);
            debugLog(`${WD} former employer multiselect`, label.slice(0, 60), 'ok=', true);
            return true;
        }

        debugLog(`${WD} former employer popup open`, label.slice(0, 60));
        await closeWorkdayPopups();
        await wait(200);
        await workdayClick(trigger);
        await wait(1200);
        const popup = findPopupNearField(container, label.toLowerCase()) || findActiveWorkdayPopup();
        const scope = popup || document;
        const popupOptions = getScopedDropdownOptions(scope);
        debugLog(`${WD} former employer popup options`,
            popupOptions.map(o => optionText(o)).filter(Boolean).slice(0, 12).join(' | '));

        if (scope.querySelector('input[type="radio"]') && await fillWorkdayYesNo(scope, 'No') && isFilled()) {
            await dismissWorkdayFieldDropdown(container, label);
            markWorkdayLockedYesNoFilled(label);
            debugLog(`${WD} former employer popup radio No`, label.slice(0, 60), 'ok=', true);
            return true;
        }
        const checkboxScope = scope.querySelectorAll('input[type="checkbox"], [role="checkbox"]').length >= 2
            ? scope : container;
        if (checkboxScope.querySelectorAll('input[type="checkbox"], [role="checkbox"]').length >= 2) {
            const ok = await fillWorkdayExclusiveCheckboxGroup(checkboxScope, cands, { label });
            await dismissWorkdayFieldDropdown(container, label);
            if (ok || isFilled()) {
                debugLog(`${WD} former employer popup checkboxes`, label.slice(0, 60), 'ok=', ok);
                markWorkdayLockedYesNoFilled(label);
                return true;
            }
        }
        const optionNodes = popupOptions.length
            ? popupOptions
            : [...scope.querySelectorAll('[role="option"], [data-automation-id="menuItem"]')];
        for (const opt of optionNodes) {
            const text = normalizeMenuOptionText(opt.getAttribute('aria-label') || opt.innerText || opt.textContent || '');
            if (!text || /^select one$/i.test(text)) continue;
            const relevant = cands.some(c => textMatchesCandidate(text, c) || textMatchesCandidate(c, text))
                || /^no$/i.test(text) || /have not worked|never worked|not worked for/i.test(text);
            if (!relevant) continue;
            debugLog(`${WD} former employer popup try`, text.slice(0, 70));
            const combobox = container.querySelector('input[role="combobox"]');
            if (await clickWorkdayMenuItem(opt, container, isFilled)) {
                if (combobox) {
                    await commitWorkdayComboboxSelection(container, combobox, opt, text);
                    await wait(400);
                }
                await dismissWorkdayFieldDropdown(container, label);
                await wait(500);
                if (isFilled()) {
                    markWorkdayLockedYesNoFilled(label);
                    debugLog(`${WD} former employer popup filled`, text.slice(0, 70));
                    return true;
                }
            }
        }
        await closeWorkdayPopups();
    }
    const fallback = await fillWorkdayExclusiveCheckboxGroup(container, cands, { label });
    debugLog(`${WD} former employer fallback`, label.slice(0, 60), 'ok=', fallback);
    const boolCb = getWorkdayBooleanYesCheckbox(container);
    if (boolCb && isWorkdayCheckboxChecked(boolCb)) {
        await workdayUncheckCheckbox(boolCb, 'former-employer-fallback');
        await wait(200);
    }
    return fallback || isWorkdayFormerEmployerFilled(container, label);
}

async function uncheckOtherWorkdayCheckboxes(container, keepInput, groupLabel = '') {
    for (const input of container.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')) {
        if (input === keepInput) continue;
        const isChecked = input.type === 'radio' ? input.checked : isWorkdayCheckboxChecked(input);
        if (!isChecked) continue;
        const labelEl = document.querySelector(`label[for="${input.id}"]`) || input.closest('label');
        const text = (labelEl?.innerText || '').trim().slice(0, 70);
        debugLog(`${WD} exclusive checkbox uncheck`, groupLabel.slice(0, 50), text);
        await workdayUncheckCheckbox(input, `${groupLabel} uncheck-other`);
        await wait(150);
    }
}

async function fillWorkdayExclusiveCheckboxGroup(container, candidates, { label = '' } = {}) {
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    if (!container || !vals.length) return false;
    if (isDisclosureChoiceFilled(container, vals)) {
        debugLog(`${WD} exclusive checkbox already filled`, label.slice(0, 60));
        return true;
    }
    for (const input of container.querySelectorAll('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')) {
        const labelEl = document.querySelector(`label[for="${input.id}"]`) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').trim();
        const match = vals.find(c => textMatchesCandidate(text, c) || textMatchesCandidate(c, text));
        if (!match) continue;
        debugLog(`${WD} exclusive checkbox select`, label.slice(0, 50), text.slice(0, 70));
        await uncheckOtherWorkdayCheckboxes(container, input, label);
        if (!isWorkdayCheckboxChecked(input) && input.type !== 'radio') {
            await workdayClickCheckbox(input, `${label} select`);
            await wait(200);
        } else if (input.type === 'radio' && !input.checked) {
            await workdayClick(labelEl || input);
            await wait(200);
        }
        if (isDisclosureChoiceFilled(container, vals)) return true;
    }
    for (const c of vals) {
        for (const labelEl of container.querySelectorAll('label')) {
            const text = (labelEl.innerText || '').trim();
            if (!text || text.length > 160) continue;
            if (!textMatchesCandidate(text, c) && !textMatchesCandidate(c, text)) continue;
            const input = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
            debugLog(`${WD} exclusive checkbox via label`, label.slice(0, 50), text.slice(0, 70));
            if (input) await uncheckOtherWorkdayCheckboxes(container, input, label);
            if (input) {
                await workdayClickCheckbox(input, `${label} via-label`);
            } else {
                await workdayClick(labelEl);
            }
            await wait(200);
            if (isDisclosureChoiceFilled(container, vals)) return true;
        }
    }
    // "Undisclosed" is a common standalone EEO decline label (distinct from "unspecified") — several
    // Workday tenants (e.g. slihrms.wd3) use it as the only non-disclosing Race/Ethnicity option, and
    // missing it here made the exclusive-checkbox fallback give up entirely, leaving the required
    // field empty and causing "Workday step stuck: disclosures" on every tenant using that label.
    const declineRe = /decline|prefer not|do not wish|not wish|choose not|do not want|unspecified|undisclosed|not specified|not to disclose/i;
    for (const labelEl of container.querySelectorAll('label')) {
        const text = (labelEl.innerText || '').trim();
        if (!text || text.length > 160 || !declineRe.test(text.toLowerCase())) continue;
        const input = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
        debugLog(`${WD} exclusive checkbox decline fallback`, label.slice(0, 50), text.slice(0, 70));
        if (input) await uncheckOtherWorkdayCheckboxes(container, input, label);
        if (input?.type === 'radio' && !input.checked) {
            await workdayClick(labelEl || input);
        } else if (input) {
            await workdayClickCheckbox(input, `${label} decline-fallback`);
        } else {
            await workdayClick(labelEl);
        }
        await wait(200);
        if (isDisclosureChoiceFilled(container, vals) || container.querySelector('input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"], [role="radio"][aria-checked="true"]')) {
            return true;
        }
    }
    const optionPreview = [...container.querySelectorAll('label')].map(l => (l.innerText || '').trim().slice(0, 40)).filter(Boolean).slice(0, 12);
    debugLog(`${WD} exclusive checkbox fill failed`, label.slice(0, 60), 'options=', optionPreview.join(' | '));
    return isDisclosureChoiceFilled(container, vals);
}

function isDisclosureChoiceFilled(container, candidates) {
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    const checked = container.querySelectorAll(
        'input[type="checkbox"]:checked, input[type="radio"]:checked, [role="checkbox"][aria-checked="true"], [role="radio"][aria-checked="true"]'
    );
    for (const input of checked) {
        const labelEl = document.querySelector(`label[for="${input.id}"]`) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || input.value || '').trim();
        if (vals.some(c => textMatchesCandidate(text, c) || textMatchesCandidate(c, text))) return true;
    }
    return false;
}

function getVeteranStatusCandidates() {
    return [
        // Prefer exact Trimble/OFCCP wording before shorter "I am not a veteran" (substring match
        // otherwise clicks the right option but verifies against the shorter phrase and loops).
        'I am not a protected veteran',
        'I AM NOT A PROTECTED VETERAN',
        'I am not a veteran',
        'I AM NOT A VETERAN',
        "I'm not a veteran",
        "I'm Not A Veteran",
        'Not a veteran',
        'Non-Veteran',
        'I choose not to self-identify',
        'I Choose Not To Self-Identify',
        "I don't wish to answer",
        'I DON\'T WISH TO ANSWER',
        'I do not wish to answer',
        'I DO NOT WISH TO ANSWER',
        'I do not wish to self-identify',
        'I DO NOT WISH TO SELF-IDENTIFY',
        'I don\'t wish to self-identify',
        'Decline to Self-Identify',
        'Decline to answer',
        'Prefer not to answer',
        'Choose not to disclose',
    ];
}

/** Geographic region checkboxes — labels may sit beside inputs without for= linkage. */
async function fillWorkdayGeographicPreferenceCheckboxes(container, label = '') {
    const scope = container?.querySelectorAll?.('input[type="checkbox"]').length >= 2
        ? container
        : (container?.closest?.('[data-automation-id*="formField"]') || container?.parentElement || container);
    if (!scope) return false;
    const regionCands = [
        'Southeast Region', 'Northeast Region', 'Midwest Region', 'Southwest Region',
        'Northwest Region', 'West Region', 'East Region', 'South Region', 'Any', 'Nationwide',
        'Southeast', 'Northeast', 'Midwest', 'Southwest', 'Northwest',
    ];
    if (scope.querySelectorAll('input[type="checkbox"]:checked').length > 0) return true;
    let ok = await fillWorkdayMultiOptionCheckboxField(scope, regionCands, {
        label: label || getContainerLabel(scope), logTag: 'geographic-pref',
    });
    if (ok) return true;
    ok = await fillWorkdayDisclosureChoiceGroup(scope, regionCands);
    if (ok) return true;
    // Fallback: click first checkbox whose nearby text looks like a US region.
    for (const input of scope.querySelectorAll('input[type="checkbox"]')) {
        const nearby = (
            (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`)?.innerText)
            || input.closest('label')?.innerText
            || input.getAttribute('aria-label')
            || input.parentElement?.innerText
            || input.nextElementSibling?.innerText
            || ''
        ).replace(/\s+/g, ' ').trim();
        if (!/region|northeast|southeast|midwest|southwest|northwest|nationwide|\bany\b/i.test(nearby)) continue;
        if (nearby.length > 100) continue;
        debugLog(`${WD} geographic-pref nearby click`, nearby.slice(0, 60));
        await workdayClickCheckbox(input, 'geographic-pref');
        await wait(300);
        if (input.checked || isWorkdayCheckboxChecked(input)) return true;
        const clickEl = (input.id && document.querySelector(`label[for="${CSS.escape(input.id)}"]`))
            || input.closest('label')
            || input.parentElement;
        if (clickEl) {
            await workdayClick(clickEl);
            await wait(300);
        }
        if (input.checked || isWorkdayCheckboxChecked(input)) return true;
    }
    // Last resort: check the first unchecked box in the group.
    const first = [...scope.querySelectorAll('input[type="checkbox"]')].find(i => !i.checked);
    if (first) {
        debugLog(`${WD} geographic-pref first-checkbox fallback`);
        await workdayClickCheckbox(first, 'geographic-pref');
        await wait(300);
        return first.checked || isWorkdayCheckboxChecked(first)
            || scope.querySelectorAll('input[type="checkbox"]:checked').length > 0;
    }
    return scope.querySelectorAll('input[type="checkbox"]:checked').length > 0;
}

async function fillWorkdayDisclosureChoiceGroup(container, candidates) {
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    if (!container || !vals.length) return false;
    if (isDisclosureChoiceFilled(container, vals)) return true;

    for (const input of container.querySelectorAll('input[type="checkbox"], input[type="radio"]')) {
        const labelEl = document.querySelector(`label[for="${input.id}"]`) || input.closest('label');
        const text = (labelEl?.innerText || input.getAttribute('aria-label') || '').trim();
        const match = vals.find(c => textMatchesCandidate(text, c) || textMatchesCandidate(c, text));
        if (!match) continue;
        if (!input.checked) {
            debugLog(`${WD} disclosure choice click`, text.slice(0, 70));
            await workdayClick(labelEl || input);
            await wait(400);
        }
        if (input.checked || isDisclosureChoiceFilled(container, vals)) return true;
    }

    for (const c of vals) {
        for (const labelEl of container.querySelectorAll('label')) {
            const text = (labelEl.innerText || '').trim();
            if (!text || text.length > 120) continue;
            if (!textMatchesCandidate(text, c) && !textMatchesCandidate(c, text)) continue;
            const input = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
            await workdayClick(labelEl);
            await wait(400);
            if (input?.checked || isDisclosureChoiceFilled(container, vals)) {
                debugLog(`${WD} disclosure choice filled via label`, text.slice(0, 70));
                return true;
            }
        }
    }
    return isDisclosureChoiceFilled(container, vals);
}

function findDisclosureDropdownMatch(options, candidates, labelLower = '') {
    const vals = (Array.isArray(candidates) ? candidates : [candidates]).filter(Boolean);
    const filtered = filterDisclosureListboxOptions(options);
    const pool = filtered.length ? filtered : options;
    for (const candidate of vals) {
        const match = findDropdownMatch(pool, candidate, labelLower);
        if (match) return { match, label: disclosureOptionText(match) };
    }
    const l = String(labelLower || '').toLowerCase();
    const declineRe = /veteran/i.test(l)
        ? /not a veteran|non-veteran|do not wish|decline|not protected|i'm not|i am not a/i
        : /choose not|not to disclose|not declared|decline|do not wish|don't wish|prefer not|undeclared|no response|is not listed|not specified|^unknown$/i;
    const fallback = pool.find(o => declineRe.test(disclosureOptionText(o)));
    if (fallback) return { match: fallback, label: disclosureOptionText(fallback) };
    if (/disability/i.test(l)) {
        const noOpt = pool.find(o => /^no\b/i.test(disclosureOptionText(o)) && !/^yes\b/i.test(disclosureOptionText(o)));
        if (noOpt) return { match: noOpt, label: disclosureOptionText(noOpt) };
    }
    // Binary gender + Unknown (rosendin.wd1) when stream said Prefer not / decline.
    if ((/gender|\bsex\b/i.test(l) || vals.some(v => /prefer not|decline|not to (answer|disclose)|choose not/i.test(String(v))))
        && vals.some(v => /prefer not|decline|not to (answer|disclose)|choose not|not specified|unknown/i.test(String(v)))) {
        const unknown = pool.find(o => /^unknown$/i.test(disclosureOptionText(o))
            || /^not specified$/i.test(disclosureOptionText(o)));
        if (unknown) return { match: unknown, label: disclosureOptionText(unknown) };
    }
    return null;
}

async function fillWorkdayDisclosureSingleSelectDropdown(element, candidates, popupLabel = '') {
    const values = (Array.isArray(candidates) ? candidates : [candidates]).filter(v => v != null && v !== '');
    const fieldRoot = element?.closest?.('[data-automation-id*="formField"]') || element?.parentElement;
    if (!element || !fieldRoot || !values.length) return false;

    const labelLower = String(popupLabel || getContainerLabel(fieldRoot)).toLowerCase();
    const openKey = normalizeDropdownOpenKey(labelLower);

    if (isWorkdaySingleSelectFilled(fieldRoot, values) || isWorkdayDisclosureSelectionFilled(fieldRoot, values)) return true;
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        debugLog(`${WD} disclosure single-select skip reopen`, openKey.slice(0, 60), 'cnt=', wdDropdownOpenCounts[openKey]);
        return isWorkdaySingleSelectFilled(fieldRoot, values) || isWorkdayDisclosureSelectionFilled(fieldRoot, values);
    }

    const combobox = fieldRoot.querySelector('input[role="combobox"]') || element;
    const openTrigger = fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
        || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
        || combobox;

    await closeWorkdayPopups();
    await wait(300);
    workdayScrollToTarget(openTrigger, 120);
    trackWorkdayDropdownOpen(openKey);
    await workdayClick(openTrigger);
    await wait(1200);

    let popup = findPopupNearField(fieldRoot, labelLower);
    if (!popup || isWrongPopupForField(popup, labelLower)) {
        await closeWorkdayPopups();
        await wait(300);
        await workdayClick(combobox);
        await wait(1200);
        popup = findPopupNearField(fieldRoot, labelLower);
    }
    if (!popup || isWrongPopupForField(popup, labelLower)) {
        await closeWorkdayPopups();
        trackWorkdayDropdownClose(openKey, 'no-popup');
        return false;
    }

    const options = getSingleSelectDropdownOptions(popup, false);
    const matched = findDisclosureDropdownMatch(options, values, labelLower);
    debugLog(`${WD} disclosure single-select`, labelLower.slice(0, 50),
        'options=', filterDisclosureListboxOptions(options).slice(0, 10).map(disclosureOptionText), 'match=', matched?.label);

    let ok = false;
    if (matched?.match) {
        const match = matched.match;
        const targetLabel = matched.label;
        ok = await selectWorkdayDisclosureListboxOption(fieldRoot, combobox, match, values, targetLabel);
        if (!ok) {
            workdayScrollToTarget(match, 120);
            const clickTargets = [
                match,
                match.querySelector('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]'),
                match.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]'),
            ].filter(Boolean);
            for (const clickTarget of clickTargets) {
                workdayClickElement(clickTarget);
                await wait(400);
                if (typeof clickTarget.click === 'function') clickTarget.click();
                await wait(400);
                await commitWorkdayComboboxSelection(fieldRoot, combobox, match, targetLabel);
                if (isWorkdayDisclosureSelectionFilled(fieldRoot, values)
                    || isWorkdaySingleSelectFilled(fieldRoot, values)
                    || isWorkdaySingleSelectFilled(fieldRoot, [targetLabel])) {
                    ok = true;
                    break;
                }
            }
        }
        if (!ok && match.getAttribute('data-value')) {
            ok = await selectWorkdayDisclosureListboxOption(fieldRoot, combobox, match, values, targetLabel);
        }
    }

    // Escape cancels an in-flight React commit — soft-close after a successful pick.
    if (ok) {
        await closeOtherWorkdayPopupsWithoutEscape();
        await wait(350);
        ok = isWorkdayDisclosureSelectionFilled(fieldRoot, values) || isWorkdaySingleSelectFilled(fieldRoot, values);
        if (!ok) {
            await closeWorkdayPopups('disclosure-reverify');
            await wait(200);
            ok = isWorkdayDisclosureSelectionFilled(fieldRoot, values) || isWorkdaySingleSelectFilled(fieldRoot, values);
        }
    } else {
        await closeWorkdayPopups();
    }
    trackWorkdayDropdownClose(openKey, ok ? 'selected' : 'miss');
    return ok || isWorkdayDisclosureSelectionFilled(fieldRoot, values) || isWorkdaySingleSelectFilled(fieldRoot, values);
}

async function fillWorkdayRadioGroup(container, value) {
    const target = normalizeRadioOptionText(value);
    const targetNum = target.replace('%', '');

    function optionMatches(text) {
        const normalized = normalizeRadioOptionText(text);
        if (/^none$/i.test(target) && /^none$/i.test(normalized)) return true;
        if (/^up to /i.test(target) && normalized.toLowerCase().includes(target.toLowerCase())) return true;
        return normalized === target || normalized === `${targetNum}%` || normalized.startsWith(targetNum);
    }

    function findExactTextElements(scope) {
        const matches = [];
        const walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT);
        let node;
        while (node = walker.nextNode()) {
            const text = (node.textContent || '').trim();
            if (!optionMatches(text)) continue;
            const el = node.parentElement;
            if (el && !matches.includes(el)) matches.push(el);
        }
        return matches;
    }

    const scope = getWorkdayRadioGroupScope(container);
    const textMatches = findExactTextElements(scope);
    debugLog(`${WD} travel candidates`, textMatches.length, scope.querySelectorAll('[role="radio"], input[type="radio"]').length);

    for (const el of textMatches) {
        const clickTargets = [el, el.parentElement, el.closest('label'), el.closest('[role="radio"]'), el.closest('button')]
            .filter(Boolean);
        for (const clickTarget of clickTargets) {
            await workdayClick(clickTarget);
            const hiddenInput = clickTarget.querySelector?.('input[type="radio"]')
                || clickTarget.closest('label')?.control;
            if (hiddenInput && !hiddenInput.checked) {
                hiddenInput.checked = true;
                hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));
            }
            clickTarget.setAttribute?.('aria-checked', 'true');
            await wait(500);
            if (isTravelFilled(container)) {
                debugLog(`${WD} travel selected via text`, value);
                return true;
            }
        }
    }

    const clickables = [...scope.querySelectorAll('label, button, [role="radio"], [role="button"], span, div, input[type="radio"]')]
        .filter(el => {
            const text = (el.getAttribute('aria-label') || el.innerText || '').trim();
            if (!text || text.length > 24) return false;
            return optionMatches(text);
        })
        .sort((a, b) => (a.innerText?.length || 999) - (b.innerText?.length || 999));

    for (const el of clickables) {
        const clickTarget = el.tagName === 'INPUT'
            ? (document.querySelector(`label[for="${el.id}"]`) || el.closest('label') || el)
            : (el.querySelector('[data-automation-id="radioButton"]') || el);
        await workdayClick(clickTarget);
        await wait(500);
        if (isTravelFilled(container)) {
            debugLog(`${WD} travel selected`, (el.innerText || el.getAttribute('aria-label') || '').trim());
            return true;
        }
    }

    for (const el of scope.querySelectorAll('[data-automation-id*="radio"], [data-automation-id*="option"]')) {
        const text = el.getAttribute('aria-label') || el.innerText || '';
        if (!optionMatches(text)) continue;
        await workdayClick(el);
        await wait(500);
        if (isTravelFilled(container)) return true;
    }

    return isTravelFilled(container);
}

function raceOptionMatchesProfile(text, profileValue) {
    const t = String(text || '').toLowerCase().trim();
    if (!t || /^select one$/i.test(t)) return false;
    const v = String(profileValue || '').toLowerCase();
    if (!v || /do not want|don't want|prefer not|decline|wish.*answer|not want to answer|do not wish/i.test(v)) {
        // "I prefer not to provide this information." is a common EEO race/ethnicity decline
        // option text across Workday tenants (observed verbatim on ryan.wd1) but was not matched
        // by any prior pattern here — only "prefer not to say/answer/disclose" and "do not wish to
        // provide" were covered. That silently failed every local decline fill on tenants using this
        // exact phrasing, forcing a stream re-try loop and eventually "Workday step stuck:
        // disclosures" — not a tenant-specific issue, fix the generic decline pattern instead.
        // "Decline to Self-Identify" (verbatim on qvc.wd5 and other tenants) was likewise missing —
        // add the "self-identify" family so any decline-shaped profile/stream value matches it too.
        // "Not Declaring (United Kingdom)" is the UK decline label on mearsgroup.wd3 and similar
        // tenants — without it, empty-profile race fills open the list then escape-all forever.
        // Canada lists often use "I prefer not to answer" / "I prefer not to provide this information. (Canada)"
        // (mckesson.wd3) — keep "prefer not to answer" and "i prefer not to answer" covered.
        return /declined? to state|declined? to answer|decline to answer|decline to specify|decline to self[- ]identify|not to self[- ]identify|do not wish|i decline|not specified|undisclosed|do not wish to disclose|choose not to (disclose|answer|self)|unspecified|i do not wish to answer|prefer not to say|prefer not to answer|i prefer not to answer|prefer not to disclose|prefer not to provide|information refused|not known|do not wish to provide|not declaring|blank \(united kingdom\)|i choose not|do not want to answer/i.test(t);
    }
    if (/white|european|caucasian/i.test(v)) {
        if (!/\bwhite\b|\bcaucasian\b/.test(t)) return false;
        // UK "White - English/..." is fine; exclude other race categories
        if (/hispanic|latino|american indian|alaskan|alaska|native hawaiian|pacific islander|black|african|asian|two or more|mixed -/i.test(t)
            && !/\bwhite\b/.test(t)) return false;
        if (/\bwhite\b/.test(t) && /black|asian|mixed|arab/i.test(t) && !/white and/i.test(t)) return false;
        return /\bwhite\b|\bcaucasian\b/.test(t);
    }
    // Standard EEOC race labels append a "(Not Hispanic or Latino)" qualifier to every non-Hispanic
    // race option (e.g. "Asian (Not Hispanic or Latino)", "Black or African American (Not Hispanic or
    // Latino)") — this is the most common Workday race/ethnicity option format across US tenants. The
    // cross-category exclusion checks below must strip that negation clause first, otherwise they
    // reject the correct option just because it contains the word "hispanic" inside its own qualifier,
    // silently failing the race dropdown fill and causing "Workday step stuck: disclosures" for every
    // Asian/Black candidate on any tenant using this label format — not a tenant-specific issue.
    const tWithoutHispanicQualifier = t.replace(/\(?\s*not\s+hispanic\s+or\s+latino\s*\)?/gi, '');
    if (/black|african/i.test(v)) {
        return (/\bblack\b|\bafrican american\b/.test(t)) && !/hispanic|latino/i.test(tWithoutHispanicQualifier);
    }
    if (/asian|pacific/i.test(v) && !/islander|hawaiian/i.test(v)) {
        return /\basian\b/.test(t) && !/hispanic|latino|pacific islander|hawaiian/i.test(tWithoutHispanicQualifier);
    }
    if (/hispanic|latino|latin american/i.test(v)) {
        // Canada lists "Latin American (Canada)" instead of US "Hispanic or Latino"
        return /hispanic|latino|latin american|latin america/.test(t);
    }
    if (/native american|american indian/i.test(v)) {
        return /american indian|alaska native|alaskan native/.test(t);
    }
    if (/hawaiian|pacific islander/i.test(v)) {
        return /native hawaiian|pacific islander/.test(t);
    }
    if (/two or more/i.test(v)) {
        return /two or more|mixed -/.test(t);
    }
    return textMatchesCandidate(t, v) || t.includes(v);
}

function isWorkdayRaceFilled(container, profileValue) {
    if (!container) return false;
    const selectionLabel = container.querySelector('[data-automation-id="promptSelectionLabel"]');
    const combobox = container.querySelector('input[role="combobox"]');
    const preview = [
        selectionLabel?.innerText || '',
        combobox?.value || '',
        container.innerText || '',
    ].join(' ').replace(/\s+/g, ' ').trim();
    if (/select one/i.test(preview)) return false;
    if (/error:/i.test(preview)) return false;
    return raceOptionMatchesProfile(preview, profileValue);
}

function isCanadaWorkdayRaceOptionList(items) {
    return (items || []).some(o => /\(canada\)/i.test(String(o?.text || o || '')));
}

function getRaceSearchTermsFromProfile(profileValue, { canadaList = false } = {}) {
    const v = String(profileValue || '').toLowerCase();
    if (!v || /do not want|decline|prefer not|not want to answer|do not wish|not declaring|^n\/?a$/i.test(v)) {
        // Canada lettered lists (mckesson.wd3): US phrases like "Declined to State" / "Blank" never
        // match and each search burns ~1.2s — keep a short Canada-first set.
        if (canadaList) {
            return [
                'I prefer not to provide this information',
                'Prefer not to answer',
                'Prefer not to say',
                'I prefer not to answer',
            ];
        }
        return [
            'I prefer not to provide this information',
            'Prefer not to answer',
            'Prefer not to say',
            'Prefer not to provide',
            'Prefer not',
            'Not Declaring',
            'Declined to State',
            'Not Specified',
        ];
    }
    if (/white|european|caucasian/i.test(v)) return ['White', 'White (Canada)', 'British', 'English'];
    if (/black|african/i.test(v)) return ['Black', 'Black (Canada)', 'African American', 'African'];
    if (/asian/i.test(v) && !/pacific|hawaiian/i.test(v)) return ['Asian', 'Chinese (Canada)', 'South Asian'];
    if (/hispanic|latino/i.test(v)) return ['Hispanic', 'Latino', 'Latin American', 'Latin American (Canada)', 'Latin'];
    if (/native american|american indian/i.test(v)) return ['American Indian', 'Alaskan', 'Aboriginal', 'Indigenous'];
    if (/hawaiian|pacific islander/i.test(v)) return ['Pacific Islander', 'Hawaiian'];
    if (/two or more/i.test(v)) return ['Two or More', 'Mixed'];
    return [];
}

function findRaceOptionInItems(items, profileValue) {
    return items.find(o => raceOptionMatchesProfile(o.text, profileValue)) || null;
}

function getWorkdayDropdownMenuItems(fieldRoot, popup) {
    const scope = popup || fieldRoot;
    return getScopedDropdownOptions(scope)
        .map(el => ({ el, text: optionText(el) }))
        .filter(o => o.text && !/^select one$/.test(o.text));
}

async function scrollWorkdayDropdownListForMatch(fieldRoot, popup, findMatch, logTag) {
    let items = getWorkdayDropdownMenuItems(fieldRoot, popup);
    let match = findMatch(items);
    if (match) return match;

    const scroller = getPhoneCodeListScroller(popup);
    if (!scroller) return null;

    scroller.scrollTop = 0;
    await wait(250);
    let lastTop = -1;

    for (let step = 0; step < 55; step++) {
        items = getWorkdayDropdownMenuItems(fieldRoot, popup);
        match = findMatch(items);
        if (match) {
            debugLog(`${WD} ${logTag} found by scroll`, match.text, 'step=', step);
            return match;
        }
        const nextTop = Math.min(
            scroller.scrollTop + Math.max(scroller.clientHeight * 0.85, 80),
            scroller.scrollHeight,
        );
        if (nextTop <= lastTop) break;
        scroller.scrollTop = nextTop;
        lastTop = nextTop;
        await wait(200);
    }
    items = getWorkdayDropdownMenuItems(fieldRoot, popup);
    return findMatch(items);
}

async function clearWorkdayDropdownSearch(popup, fieldRoot) {
    const searchInput = popup?.querySelector('[data-automation-id="searchBox"] input')
        || fieldRoot?.querySelector('[data-automation-id="multiselectInputContainer"] input')
        || fieldRoot?.querySelector('[data-uxi-widget-type="selectinput"]')
        || fieldRoot?.querySelector('input[placeholder*="Search" i]')
        || popup?.querySelector('input[type="search"], input[placeholder*="Search" i], input[role="combobox"]');
    if (!searchInput) return;
    try {
        selectWorkdayInputText(searchInput);
        document.execCommand('insertText', false, '');
    } catch (_) { /* ignore */ }
    setNativeValue(searchInput, '');
    searchInput.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    searchInput.dispatchEvent(new Event('change', { bubbles: true }));
    await wait(300);
}

/**
 * Virtualized Workday race lists (Canada lettered a/b/c… on mckesson.wd3) often keep
 * scrollHeight≈clientHeight so plain scrollTop loops stop mid-alphabet. Walk by focusing
 * the last visible option + ArrowDown while collecting unique labels, then re-hunt.
 */
async function walkRaceListWithKeys(fieldRoot, popup, findMatch) {
    const scroller = getPhoneCodeListScroller(popup);
    if (scroller) {
        scroller.scrollTop = 0;
        await wait(200);
    }
    const seen = new Set();
    let stagnant = 0;
    for (let i = 0; i < 140; i++) {
        const items = getWorkdayDropdownMenuItems(fieldRoot, popup);
        const seenBefore = seen.size;
        for (const o of items) {
            if (o.text) seen.add(o.text);
        }
        const liveMatch = findMatch(items);
        if (liveMatch) {
            debugLog(`${WD} race found by arrow`, liveMatch.text, 'step=', i, 'seen=', seen.size);
            return liveMatch;
        }
        const last = items[items.length - 1]?.el;
        if (last) {
            workdayScrollToTarget(last, 40);
            last.focus?.();
            last.dispatchEvent(new KeyboardEvent('keydown', {
                key: 'ArrowDown', code: 'ArrowDown', keyCode: 40, which: 40, bubbles: true, cancelable: true,
            }));
            last.dispatchEvent(new KeyboardEvent('keyup', {
                key: 'ArrowDown', code: 'ArrowDown', keyCode: 40, which: 40, bubbles: true,
            }));
        }
        if (scroller) {
            scroller.scrollTop = Math.min(scroller.scrollTop + 72, scroller.scrollHeight);
            try {
                scroller.dispatchEvent(new WheelEvent('wheel', { deltaY: 320, bubbles: true, cancelable: true }));
            } catch (_) { /* ignore */ }
        }
        await wait(100);
        if (seen.size === seenBefore) stagnant += 1;
        else stagnant = 0;
        if (stagnant >= 10) break;
    }
    const seenList = [...seen];
    debugLog(`${WD} race walk seen`, seenList.slice(0, 30), 'total=', seenList.length);
    const wantText = seenList.find(t => findMatch([{ el: null, text: t }]));
    if (!wantText) return findMatch(getWorkdayDropdownMenuItems(fieldRoot, popup));

    if (scroller) scroller.scrollTop = 0;
    await wait(200);
    stagnant = 0;
    let prevSeenAt = '';
    for (let i = 0; i < 140; i++) {
        const hit = getWorkdayDropdownMenuItems(fieldRoot, popup).find(o => o.text === wantText);
        if (hit) {
            debugLog(`${WD} race re-found after walk`, hit.text);
            return hit;
        }
        const items = getWorkdayDropdownMenuItems(fieldRoot, popup);
        const last = items[items.length - 1]?.el;
        const marker = items.map(o => o.text).join('|');
        if (marker === prevSeenAt) stagnant += 1;
        else stagnant = 0;
        prevSeenAt = marker;
        last?.focus?.();
        last?.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowDown', code: 'ArrowDown', keyCode: 40, which: 40, bubbles: true, cancelable: true,
        }));
        if (scroller) scroller.scrollTop = Math.min(scroller.scrollTop + 72, scroller.scrollHeight);
        await wait(90);
        if (stagnant >= 10) break;
    }
    return findMatch(getWorkdayDropdownMenuItems(fieldRoot, popup));
}

async function findRaceOption(fieldRoot, effectiveValue, popup) {
    const findMatch = (items) => findRaceOptionInItems(items, effectiveValue);
    const findDecline = (items) => items.find(o =>
        /prefer not to say|prefer not to answer|i prefer not to answer|prefer not to disclose|prefer not to provide|declined? to state|decline to (answer|specify)|decline to self[- ]identify|do not wish|not specified|undisclosed|choose not to (disclose|answer|self)|information refused|not known|unspecified|not declaring|blank \(united kingdom\)|i prefer not to provide|i choose not|do not want to answer/i.test(o.text)
    ) || null;
    const findMatchOrDecline = (items) => findMatch(items) || findDecline(items);

    let items = getWorkdayDropdownMenuItems(fieldRoot, popup);
    let match = findMatch(items);
    if (match) {
        debugLog(`${WD} race option visible`, match.text);
        return match;
    }

    const canadaList = isCanadaWorkdayRaceOptionList(items);
    if (canadaList) debugLog(`${WD} race canada list detected`, items.slice(0, 4).map(o => o.text));

    // Canada ethnicity prompt lists (mckesson.wd3): Search often does not filter — skip the
    // multi-term search thrash and walk the virtualized lettered list (a…n) first.
    if (canadaList) {
        match = await walkRaceListWithKeys(fieldRoot, popup, findMatchOrDecline);
        if (match) return match;
        match = await scrollWorkdayDropdownListForMatch(fieldRoot, popup, findMatchOrDecline, 'race-canada');
        if (match) return match;
    }

    for (const term of getRaceSearchTermsFromProfile(effectiveValue, { canadaList })) {
        match = await tryWorkdayDropdownSearch(
            popup,
            fieldRoot,
            term,
            () => getWorkdayDropdownMenuItems(fieldRoot, popup),
            findMatchOrDecline,
            'race',
        );
        if (match) return match;
    }

    // Clear any failed search filter so scroll/arrow can see the full list.
    await clearWorkdayDropdownSearch(popup, fieldRoot);

    match = await scrollWorkdayDropdownListForMatch(fieldRoot, popup, findMatch, 'race');
    if (match) return match;

    // UK / regional lists — pick decline when profile has no race
    match = await scrollWorkdayDropdownListForMatch(fieldRoot, popup, findDecline, 'race-decline');
    if (match) {
        debugLog(`${WD} race decline fallback`, match.text);
        return match;
    }
    match = findDecline(getWorkdayDropdownMenuItems(fieldRoot, popup));
    if (match) {
        debugLog(`${WD} race decline visible`, match.text);
        return match;
    }

    if (!canadaList) {
        match = await walkRaceListWithKeys(fieldRoot, popup, findMatchOrDecline);
        if (match) return match;
    }

    debugLog(`${WD} race option not found`, getWorkdayDropdownMenuItems(fieldRoot, popup).slice(0, 12).map(o => o.text));
    return null;
}

async function fillWorkdayRaceDropdown(element, profile, popupLabel = '', streamValue = null) {
    const profileValue = profile?.general?.raceEthnicity;
    const rawStream = streamValue != null && streamValue !== ''
        ? (Array.isArray(streamValue) ? streamValue[0] : streamValue)
        : null;
    // AI often returns "N/A" when Gender had empty options in the same payload — treat as no
    // stream answer so UK "Not Declaring" / profile decline matching still runs.
    const hasUsableStream = rawStream != null && !/^n\/?a$/i.test(String(rawStream).trim());
    const effectiveValue = hasUsableStream ? rawStream : profileValue;
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const labelLower = String(popupLabel || getContainerLabel(fieldRoot)).toLowerCase();
    if (isWorkdayRaceFilled(fieldRoot, effectiveValue)) return true;

    // Long EEO "Select Race: DEFINITIONS..." labels share one open-key so retries aren't blocked.
    const openKey = (labelLower.length > 80 || /select race|definitions:/i.test(labelLower))
        ? 'race-ethnicity-select'
        : normalizeDropdownOpenKey(popupLabel || labelLower || 'race');
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        // Local attempts often burn the budget before stream returns a Canada/UK option label —
        // allow one more open when we have a concrete streamed value to match.
        if (hasUsableStream) {
            debugLog(`${WD} race open-count reset for stream value`, String(rawStream).slice(0, 60));
            resetWorkdayDropdownOpenCount(openKey);
        } else {
            markDisclosureStreamFallback(popupLabel || labelLower);
            return false;
        }
    }

    const ethCandidates = mapProfileRaceToWorkdayCandidates(effectiveValue);
    const combobox = fieldRoot.querySelector('input[role="combobox"]') || element;
    const openTrigger = fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
        || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
        || combobox;

    async function tryClickRaceOption(raceMatch) {
        if (!raceMatch?.el) return false;
        workdayScrollToTarget(raceMatch.el, 120);
        const clickTargets = [
            raceMatch.el,
            raceMatch.el.querySelector('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]'),
            raceMatch.el.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]'),
        ].filter(Boolean);
        for (const clickTarget of clickTargets) {
            debugLog(`${WD} race click`, raceMatch.text);
            workdayClickElement(clickTarget);
            await wait(400);
            if (typeof clickTarget.click === 'function') clickTarget.click();
            await wait(400);
            await commitWorkdayComboboxSelection(fieldRoot, combobox, raceMatch.el, raceMatch.text);
            if (isWorkdayRaceFilled(fieldRoot, effectiveValue)) return true;
        }
        return false;
    }

    // BUTTON listboxes (trimble.wd1) often fail findRaceOption (empty popup / 21s scroll) while
    // fillWorkdaySingleSelectDropdown matches Hispanic/decline candidates in one open — try first.
    if (openTrigger?.tagName === 'BUTTON' || openTrigger?.getAttribute?.('aria-haspopup') === 'listbox') {
        clearWorkdaySingleSelectMissKey(openKey);
        clearWorkdaySingleSelectMissKey(popupLabel || labelLower);
        const viaSelect = await fillWorkdaySingleSelectDropdown(openTrigger, ethCandidates, popupLabel || labelLower);
        if (viaSelect || isWorkdayRaceFilled(fieldRoot, effectiveValue)) {
            debugLog(`${WD} race filled via single-select`, String(ethCandidates[0] || '').slice(0, 60));
            return true;
        }
    }

    for (let attempt = 0; attempt < 2; attempt++) {
        if (isWorkdayRaceFilled(fieldRoot, effectiveValue)) return true;
        await closeWorkdayPopups();
        await wait(400);
        workdayScrollToTarget(openTrigger, 120);
        trackWorkdayDropdownOpen(popupLabel || labelLower || 'race');
        await workdayClick(openTrigger);
        await wait(1200);
        let popup = findPopupNearField(fieldRoot, labelLower);
        if (!popup || isWrongPopupForField(popup, labelLower)) {
            await workdayClick(combobox);
            await wait(1200);
            popup = findPopupNearField(fieldRoot, labelLower);
        }
        if (!popup) continue;

        const visibleItems = getWorkdayDropdownMenuItems(fieldRoot, popup);
        if (!visibleItems.length) {
            // Empty popup — do not burn 20s+ scrolling a phantom list (trimble.wd1 ethnicity).
            debugLog(`${WD} race popup empty — retry open`, labelLower.slice(0, 50));
            await closeWorkdayPopups();
            await wait(300);
            continue;
        }

        let raceMatch = await findRaceOption(fieldRoot, effectiveValue, popup);
        if (!raceMatch) {
            const options = getSingleSelectDropdownOptions(popup, false);
            for (const candidate of ethCandidates) {
                const target = String(candidate).toLowerCase();
                const el = options.find(o => optionText(o) === target)
                    || options.find(o => optionText(o).includes(target) || target.includes(optionText(o)));
                if (el) {
                    raceMatch = { el, text: optionText(el) };
                    break;
                }
            }
        }

        if (raceMatch && await tryClickRaceOption(raceMatch)) {
            debugLog(`${WD} race filled`, raceMatch.text);
            await closeWorkdayPopups();
            return true;
        }
        await closeWorkdayPopups();
        await wait(400);
    }

    const filled = isWorkdayRaceFilled(fieldRoot, effectiveValue);
    if (!filled) markDisclosureStreamFallback(popupLabel || labelLower);
    return filled;
}

async function fillWorkdayAddressCityDropdown(fieldRoot, combobox, openTrigger, candidates) {
    const values = (Array.isArray(candidates) ? candidates : [candidates])
        .map((v) => String(v || '').trim())
        .filter(Boolean);
    if (!fieldRoot || !values.length) return false;
    if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
    const openKey = 'city';
    clearWorkdaySingleSelectMissKey('city');
    clearWorkdaySingleSelectMissKey(normalizeDropdownOpenKey(getContainerLabel(fieldRoot) || 'city'));
    resetWorkdayDropdownOpenCount(openKey);

    async function forceDismissStaleHearChrome() {
        // closeWorkdayPopups skips Escape while hear is filled; City still needs Escape so the
        // Indeed selectedItem chip is not the only "visible listbox" candidate.
        const hearContainer = findHearAboutContainer();
        if (hearContainer) await blurAwayFromHearField(hearContainer);
        await closeOtherWorkdayPopupsWithoutEscape();
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await wait(250);
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await wait(250);
    }

    async function findCityMatch(popup, cands) {
        if (!popup || isChipDisplayPopup(popup) || isWrongPopupForField(popup, 'city')) return null;
        const options = getSingleSelectDropdownOptions(popup, false)
            .filter((o) => o.getAttribute('data-automation-id') !== 'selectedItem'
                && !/press delete to clear/i.test(optionText(o)));
        if (!options.length) return null;
        for (const candidate of cands) {
            const cTarget = candidate.toLowerCase();
            const cityOnly = cTarget.split(',')[0].trim();
            const found = options.find((o) => optionText(o) === cTarget)
                || options.find((o) => optionText(o) === cityOnly)
                || options.find((o) => {
                    const ot = optionText(o);
                    return ot.startsWith(`${cityOnly},`) || ot.startsWith(`${cityOnly} `) || ot.includes(cityOnly);
                });
            if (found) return { match: found, label: candidate };
        }
        return null;
    }

    async function resolveCityPopup() {
        let popup = findPopupNearField(fieldRoot, 'city');
        if (popup && (isChipDisplayPopup(popup) || isWrongPopupForField(popup, 'city'))) popup = null;
        if (!popup) {
            const active = findActiveWorkdayPopup();
            if (active && !isChipDisplayPopup(active) && !isWrongPopupForField(active, 'city')) popup = active;
        }
        return popup;
    }

    for (const candidate of values.slice(0, 3)) {
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
        await forceDismissStaleHearChrome();
        await closeWorkdayPopups();
        await wait(350);
        const trigger = openTrigger || combobox
            || fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
            || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
            || fieldRoot.querySelector('input[role="combobox"]')
            || fieldRoot.querySelector('input');
        if (!trigger) return false;
        workdayScrollToTarget(trigger, 120);
        trackWorkdayDropdownOpen(openKey, 'city-typeahead');
        await workdayClick(trigger);
        await wait(500);
        const input = fieldRoot.querySelector('input[role="combobox"]')
            || fieldRoot.querySelector('input[data-uxi-widget-type="selectinput"]')
            || fieldRoot.querySelector('input:not([type="hidden"])')
            || (trigger.tagName === 'INPUT' ? trigger : null)
            || combobox;
        const cityOnly = candidate.split(',')[0].trim();
        if (input) {
            input.focus?.();
            await workdayTypeElement(input, cityOnly);
            await wait(1500);
        }
        let popup = null;
        let hit = null;
        for (let poll = 0; poll < 6 && !hit; poll++) {
            popup = await resolveCityPopup();
            if (popup) hit = await findCityMatch(popup, [candidate, cityOnly, ...values]);
            if (!hit) {
                // Document-level city options (list rendered outside field aria-controls).
                const orphans = [...document.querySelectorAll(
                    '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]',
                )].filter((el) => {
                    if (!isVisibleElement(el)) return false;
                    if (el.getAttribute('data-automation-id') === 'selectedItem') return false;
                    if (el.closest('[data-automation-id="selectedItemList"], [data-automation-id="selectedItem"]')) return false;
                    const ot = optionText(el);
                    return ot.includes(cityOnly.toLowerCase()) && !/press delete|indeed|linkedin/i.test(ot);
                });
                if (orphans.length) hit = { match: orphans[0], label: candidate };
            }
            if (!hit) await wait(400);
        }
        if (!hit) {
            const searchInput = popup?.querySelector?.('[data-automation-id="searchBox"] input')
                || popup?.querySelector?.('input[type="search"], input[placeholder*="Search" i]')
                || input;
            if (searchInput) {
                await workdayTypeSearchInput(searchInput, cityOnly);
                await wait(1200);
                popup = await resolveCityPopup();
                hit = await findCityMatch(popup, [candidate, cityOnly, ...values]);
            }
        }
        // Keyboard commit: Workday city typeahead often highlights the first filtered row.
        if (!hit?.match && input) {
            debugLog(`${WD} city typeahead keyboard commit`, cityOnly.slice(0, 40));
            await dispatchListKey('ArrowDown', input);
            await wait(350);
            await dispatchListKey('Enter', input);
            await wait(600);
            await closeWorkdayPopups();
            if (isWorkdaySingleSelectFilled(fieldRoot, values)
                || (!/error:.*required and must have a value|select one|0 items selected/i.test(fieldRoot.innerText || '')
                    && new RegExp(cityOnly.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(fieldRoot.innerText || ''))) {
                debugLog(`${WD} city typeahead filled via keyboard`, cityOnly.slice(0, 40));
                return true;
            }
        }
        if (!hit?.match) {
            debugLog(`${WD} city typeahead wrong/missing popup`, candidate.slice(0, 40),
                'visibleLists=', getWorkdayVisiblePopupCandidates().length);
            if (wdDropdownOpenCounts[openKey] > 0) wdDropdownOpenCounts[openKey] -= 1;
            await forceDismissStaleHearChrome();
            continue;
        }
        workdayScrollToTarget(hit.match, 120);
        workdayClickElement(hit.match);
        await wait(500);
        if (typeof hit.match.click === 'function') hit.match.click();
        await wait(400);
        await commitWorkdayComboboxSelection(fieldRoot, input || combobox, hit.match, hit.label);
        await wait(500);
        await closeWorkdayPopups();
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) {
            debugLog(`${WD} city typeahead filled`, hit.label.slice(0, 40));
            return true;
        }
        const preview = (fieldRoot.innerText || '').replace(/\s+/g, ' ');
        const esc = cityOnly.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (cityOnly && new RegExp(esc, 'i').test(preview)
            && !/error:.*required and must have a value|select one|0 items selected/i.test(preview)) {
            debugLog(`${WD} city typeahead filled (preview)`, hit.label.slice(0, 40));
            return true;
        }
    }
    return isWorkdaySingleSelectFilled(fieldRoot, values);
}

async function fillWorkdaySingleSelectDropdown(element, candidates, popupLabel = '') {
    const values = (Array.isArray(candidates) ? candidates : [candidates]).filter(v => v !== null && v !== undefined && v !== '');
    let fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const affixLabel = getContainerLabel(fieldRoot) || popupLabel;
    const labelLower = String(popupLabel || getContainerLabel(fieldRoot)).toLowerCase();
    if (/phone device type/i.test(labelLower) || /phone device type/i.test(String(popupLabel || ''))) {
        const deviceContainer = getWorkdayFieldContainers().find(c => /phone device type/i.test(getContainerLabel(c)));
        if (deviceContainer) fieldRoot = deviceContainer;
    }
    if (values.some(isKnownCommuteTimeOption) || isCommuteTimeFieldLabel(labelLower)) {
        clearWorkdaySingleSelectMissKey(popupLabel || labelLower);
    }
    if (!window.__wdHearDirectFill && (/how did you hear/i.test(labelLower) || /how did you hear/i.test(affixLabel.toLowerCase()))) {
        if (isHearFillDone(fieldRoot) || hasExplicitHearSelection(fieldRoot)) {
            markHearFilled(fieldRoot);
            return true;
        }
        if (window.__wdHearFillInProgress) return false;
        return ensureHowDidYouHearFilled();
    }
    if (shouldSkipOptionalNameAffixField(fieldRoot, affixLabel)) {
        debugLog(`${WD} single-select skip optional affix`, affixLabel.slice(0, 40));
        return true;
    }
    if (isWorkdaySingleSelectFilled(fieldRoot, values)) {
        return true;
    }
    // Inline checkbox groups (geographic preferences) must not go through listbox open/miss-lock.
    if (/geographic preferences|open to relocation.*select your|select your geographic/i.test(labelLower)
        && fieldRoot.querySelectorAll('input[type="checkbox"]').length >= 2) {
        const ok = await fillWorkdayGeographicPreferenceCheckboxes(fieldRoot, popupLabel || labelLower);
        debugLog(`${WD} single-select → geographic checkboxes`, labelLower.slice(0, 50), 'ok=', ok);
        return ok;
    }
    // Plain text/textarea fields misrouted as single-select (ovationhealthcare.wd5 YOE / notice).
    if ((element?.tagName === 'TEXTAREA'
        || (element?.tagName === 'INPUT' && !element.getAttribute('role') && !element.getAttribute('aria-haspopup')))
        && !fieldRoot.querySelector('button[aria-haspopup="listbox"], [role="combobox"], [data-automation-id="promptSelectionLabel"]')) {
        if (/how many years|years of experience|experience in the healthcare/i.test(labelLower)) {
            const years = Number(window.__wdApplyData?.profile?.workingExperienceInYears
                ?? window.__wdApplyData?.profile?.working_experience_in_years);
            const yearsVal = Number.isFinite(years) && years > 0
                ? (Number.isInteger(years) ? String(years) : years.toFixed(1))
                : '6';
            const ok = await commitWorkdayNumericInput(element, yearsVal, labelLower);
            debugLog(`${WD} single-select → years text`, labelLower.slice(0, 50), yearsVal, 'ok=', ok);
            return ok;
        }
        if (/notice period/i.test(labelLower)) {
            const noticeText = String(values[0] || '2 weeks');
            await workdayTypeElement(element, noticeText);
            await wait(300);
            const ok = Boolean((element.value || '').trim());
            debugLog(`${WD} single-select → notice text`, labelLower.slice(0, 50), noticeText, 'ok=', ok);
            return ok;
        }
    }
    const combobox = fieldRoot.querySelector('input[role="combobox"]')
        || (fieldRoot.contains(element) ? element : null)
        || element;
    // Phone Device Type: never pick the first prompt* in a shared phone-group ancestor — that is
    // usually Country Phone Code (entegris.wd1 / icf.wd5). Prefer this field's own arrow/label.
    let openTrigger;
    if (/phone device type/i.test(labelLower) || /phone device type/i.test(String(popupLabel || ''))) {
        openTrigger = getWorkdayDropdownTrigger(fieldRoot)
            || fieldRoot.querySelector('[data-automation-id="promptArrow"]')
            || fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
            || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
            || fieldRoot.querySelector('[role="combobox"]')
            || combobox;
    } else if (isCompensationFieldLabel(popupLabel || labelLower)) {
        openTrigger = getWorkdayCompensationOpenTrigger(fieldRoot, combobox);
    } else {
        openTrigger = fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]')
            || fieldRoot.querySelector('[data-automation-id="promptArrow"]')
            || fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || fieldRoot.querySelector('[data-automation-id="multiselectInputContainer"]')
            || fieldRoot.querySelector('button[aria-haspopup="listbox"]')
            || fieldRoot.querySelector('[aria-haspopup="listbox"]')
            || combobox;
    }

    // Address City searchable selects (bah.wd1 / guidehouse.wd1): typeahead + reject stale
    // hear-about listboxes before the generic 2-open single-select path burns its budget on
    // options like ["Indeed"] while the combobox still shows typed text without a committed option.
    if (isWorkdayAddressCityFieldLabel(labelLower)
        || /^city$/i.test(String(labelLower || '').replace(/\*/g, '').trim())) {
        const cityOk = await fillWorkdayAddressCityDropdown(fieldRoot, combobox, openTrigger, values);
        if (cityOk) return true;
    }

    async function tryClickOption(match, targetLabel) {
        if (!match) return false;
        workdayScrollToTarget(match, 120);
        const clickTargets = [
            match,
            match.querySelector('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]'),
            match.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]'),
        ].filter(Boolean);
        for (const clickTarget of clickTargets) {
            debugLog(`${WD} single-select click`, optionText(clickTarget));
            workdayClickElement(clickTarget);
            await wait(500);
            if (typeof clickTarget.click === 'function') clickTarget.click();
            await wait(700);
            const btnAfter = fieldRoot.querySelector('button[aria-haspopup="listbox"]');
            const oid = match.getAttribute('data-value')
                || match.getAttribute('data-automation-id')
                || extractWorkdayOptionValue(match);
            // Button listboxes: success = opaque id on button/input (never displayText).
            if (btnAfter) {
                let committed = getWorkdayButtonListboxOpaqueValue(fieldRoot);
                if (!committed && isWorkdayOpaqueOptionId(oid)) {
                    await commitWorkdayComboboxSelection(fieldRoot, combobox || btnAfter, match, targetLabel);
                    await wait(400);
                    committed = getWorkdayButtonListboxOpaqueValue(fieldRoot);
                }
                if (committed) {
                    const btnLabel = String(btnAfter.innerText || '').replace(/\s+/g, ' ').trim();
                    debugLog(`${WD} single-select button-listbox opaque`, committed.slice(0, 28), btnLabel.slice(0, 40));
                    // If label still "Select One", click again once then accept opaque for Yes/No/EEO.
                    if (/^select one$/i.test(btnLabel)) {
                        workdayClickElement(clickTarget);
                        await wait(600);
                    }
                    await closeWorkdayPopups();
                    if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
                    // Opaque + non-placeholder label, or opaque alone for Yes/No targets
                    const refreshed = String(btnAfter.innerText || '').replace(/\s+/g, ' ').trim();
                    if (getWorkdayButtonListboxOpaqueValue(fieldRoot)
                        && refreshed && !/^select one$/i.test(refreshed)) {
                        return true;
                    }
                    if (getWorkdayButtonListboxOpaqueValue(fieldRoot)
                        && values.some(v => /^(yes|no)$/i.test(String(v)))) {
                        return true;
                    }
                } else {
                    debugLog(`${WD} single-select button-listbox no opaque after click`,
                        'oid=', String(oid || '').slice(0, 40),
                        'opt=', (match.outerHTML || '').slice(0, 180));
                }
                // Never fall through to displayText commit for button listboxes.
                continue;
            }
            const hiddenAfter = [...fieldRoot.querySelectorAll('input')].find(i => i.type !== 'file');
            if (hiddenAfter && isWorkdayOpaqueOptionId(hiddenAfter.value)
                && getWorkdayFieldSelectedText(fieldRoot)
                && !/^select one$/i.test(getWorkdayFieldSelectedText(fieldRoot))) {
                debugLog(`${WD} single-select opaque committed by click`, hiddenAfter.value.slice(0, 28));
                await closeWorkdayPopups();
                return true;
            }
            if (oid && isWorkdayOpaqueOptionId(oid) && hiddenAfter && typeof wdCommitReactTextInput === 'function') {
                wdCommitReactTextInput(hiddenAfter, oid);
                await wait(400);
                if (isWorkdayOpaqueOptionId(hiddenAfter.value)
                    && getWorkdayFieldSelectedText(fieldRoot)
                    && !/^select one$/i.test(getWorkdayFieldSelectedText(fieldRoot))) {
                    await closeWorkdayPopups();
                    return true;
                }
            }
            await commitWorkdayComboboxSelection(fieldRoot, combobox, match, targetLabel);
            await wait(400);
            if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
            const hidden = [...fieldRoot.querySelectorAll('input')].find(i => i.type !== 'file');
            const btnText = getWorkdayFieldSelectedText(fieldRoot);
            if (btnText && !/^select one$/i.test(btnText) && hidden && isWorkdayOpaqueOptionId(hidden.value)) {
                return true;
            }
        }
        return false;
    }

    async function openFieldPopup() {
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) return null;
        // Hard limit: stop opening if this dropdown has been opened too many times.
        // Normal flow: 1 open for options collection + 1 open for fill = 2 total.
        // Anything beyond 3 is a bug/loop.
        const openKey = normalizeDropdownOpenKey(popupLabel || labelLower || 'single-select');
        if (window.__wdSingleSelectMissKeys?.has(openKey)) {
            debugLog(`${WD} single-select skip repeat miss`, openKey.slice(0, 60));
            return null;
        }
        if (/how did you hear/i.test(openKey)) {
            if (isHearFillDone(fieldRoot) || hasExplicitHearSelection(fieldRoot)) return null;
            if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
                debugLog(`${WD} hear single-select abort excess opens`, openKey.slice(0, 60));
                return null;
            }
        }
        if (isCompensationFieldLabel(popupLabel || labelLower) && (wdDropdownOpenCounts[openKey] || 0) >= 3) {
            debugLog(`${WD} compensation single-select reset open count`, openKey.slice(0, 60));
            delete wdDropdownOpenCounts[openKey];
            window.__wdSingleSelectMissKeys?.delete(openKey);
        }
        if (/citizenship/i.test(openKey) && (wdDropdownOpenCounts[openKey] || 0) >= 3) {
            debugLog(`${WD} citizenship single-select reset open count`, openKey.slice(0, 60));
            delete wdDropdownOpenCounts[openKey];
            window.__wdSingleSelectMissKeys?.delete(openKey);
        }
        if (/phone device/i.test(openKey) && (wdDropdownOpenCounts[openKey] || 0) >= 3) {
            debugLog(`${WD} phone device single-select reset open count`, openKey.slice(0, 60));
            delete wdDropdownOpenCounts[openKey];
            window.__wdSingleSelectMissKeys?.delete(openKey);
        }
        // Address City dropdowns (guidehouse.wd1) — prior text-typed miss must not block option select.
        if (/^city$/i.test(openKey) && (wdDropdownOpenCounts[openKey] || 0) >= 2) {
            debugLog(`${WD} city single-select reset open count`, openKey.slice(0, 60));
            delete wdDropdownOpenCounts[openKey];
            window.__wdSingleSelectMissKeys?.delete(openKey);
        }
        // Years/notice dropdowns (ovationhealthcare.wd5) — miss-lock after popup lag blocks forever.
        if (/years of experience|notice period|how many years/i.test(openKey)
            && (wdDropdownOpenCounts[openKey] || 0) >= 2) {
            debugLog(`${WD} years/notice single-select reset open count`, openKey.slice(0, 60));
            delete wdDropdownOpenCounts[openKey];
            window.__wdSingleSelectMissKeys?.delete(openKey);
        }
        if (/privacy notice|privacy consent|i have received|identity verification|background check|if i am extended|please read before signing|equal employment opportunities/i.test(openKey)
            && (wdDropdownOpenCounts[openKey] || 0) >= 2) {
            // Do NOT reset open count — that caused infinite Agree/Disagree open/close loops.
            debugLog(`${WD} privacy/agree-disagree single-select abort excess opens`, openKey.slice(0, 60));
            return null;
        }
        if ((wdDropdownOpenCounts[openKey] || 0) >= 3) {
            debugLog(`${WD} single-select skip open excess`, openKey.slice(0, 60));
            return null;
        }
        await closeWorkdayPopups();
        await wait(400);
        workdayScrollToTarget(openTrigger, 120);
        trackWorkdayDropdownOpen(openKey);
        await workdayClick(openTrigger);
        // Long COI / government-official labels (cisco.wd5) often need >1.2s before the listbox is
        // addressable via aria-controls; a short wait left findPopupNearField null → permanent miss.
        // Years/notice (ovationhealthcare.wd5) similarly lag — poll instead of a single sleep.
        const slowYesNo = /family relationship|government official|close personal contact|conflict of interest|politically exposed/i.test(openKey)
            || getHardcodedYesNoAnswer(popupLabel || labelLower);
        const slowOpen = slowYesNo
            || /years of experience|notice period|how many years|annualized salary|desired compensation|^city$|phone device/i.test(openKey);
        let popup = null;
        for (let poll = 0; poll < (slowOpen ? 8 : 4) && !popup; poll++) {
            await wait(slowOpen ? 400 : 300);
            popup = findPopupNearField(fieldRoot, labelLower);
            if (popup && isWrongPopupForField(popup, labelLower)) popup = null;
            if (!popup) {
                const active = findActiveWorkdayPopup();
                if (active && !isWrongPopupForField(active, labelLower)) popup = active;
            }
        }
        if (!popup || isWrongPopupForField(popup, labelLower)) {
            await closeWorkdayPopups();
            await wait(300);
            // Phone Device Type: after Phone Code fill, a plain button click often no-ops — retry
            // via promptArrow then combobox (entegris.wd1).
            const retryTriggers = /phone device/i.test(openKey)
                ? [
                    fieldRoot.querySelector('[data-automation-id="promptArrow"]'),
                    fieldRoot.querySelector('[data-automation-id="promptSelectionLabel"]'),
                    combobox,
                    openTrigger,
                ].filter(Boolean)
                : [combobox];
            for (const trig of retryTriggers) {
                await workdayClick(trig);
                popup = null;
                for (let poll = 0; poll < (slowOpen ? 6 : 3) && !popup; poll++) {
                    await wait(slowOpen ? 400 : 300);
                    popup = findPopupNearField(fieldRoot, labelLower);
                    if (popup && isWrongPopupForField(popup, labelLower)) popup = null;
                    if (!popup) {
                        const active = findActiveWorkdayPopup();
                        if (active && !isWrongPopupForField(active, labelLower)) popup = active;
                    }
                }
                if (popup && !isWrongPopupForField(popup, labelLower)) break;
                await closeWorkdayPopups();
                await wait(200);
            }
        }
        // Last resort for Yes/No: any visible listbox whose options look like Yes/No (field-scoped
        // find can miss when aria-controls id is stale after Workday re-render).
        if ((!popup || isWrongPopupForField(popup, labelLower)) && slowYesNo) {
            const active = findActiveWorkdayPopup();
            if (active && !isWrongPopupForField(active, labelLower)) {
                const optLabels = getSingleSelectDropdownOptions(active, false).map(optionText);
                const sample = optLabels.join(' ');
                if (isWorkdayYesNoOptionList(optLabels)
                    || (/\byes\b/i.test(sample) && /\bno\b/i.test(sample))) {
                    debugLog(`${WD} single-select yes/no popup fallback`, openKey.slice(0, 50));
                    popup = active;
                }
            }
        }
        // Years/notice/salary: accept any active option list after slow poll (promptContainer etc.).
        if ((!popup || isWrongPopupForField(popup, labelLower)) && slowOpen) {
            const active = findActiveWorkdayPopup();
            if (active && !isWrongPopupForField(active, labelLower)
                && getSingleSelectDropdownOptions(active, false).length) {
                debugLog(`${WD} single-select slowOpen popup fallback`, openKey.slice(0, 50));
                popup = active;
            }
        }
        if (!popup || isWrongPopupForField(popup, labelLower)) {
            // Undo open budget when City/State/Phone Device only saw a stale sibling listbox / no popup.
            if (/^city$/i.test(openKey) || isWorkdayStateFieldLabel(openKey) || isWorkdayCountyFieldLabel(openKey)
                || /phone device/i.test(openKey)) {
                if ((wdDropdownOpenCounts[openKey] || 0) > 0) wdDropdownOpenCounts[openKey] -= 1;
                debugLog(`${WD} single-select undo open after wrong popup`, openKey.slice(0, 50));
            }
            // DOM dump — cisco.wd5 family/gov-official; ovationhealthcare.wd5 years/notice.
            const radios = [...(fieldRoot?.querySelectorAll('input[type="radio"]') || [])].length;
            const checks = [...(fieldRoot?.querySelectorAll('input[type="checkbox"]') || [])].length;
            const ariaControls = openTrigger?.getAttribute?.('aria-controls') || '';
            const controlled = ariaControls ? document.getElementById(ariaControls) : null;
            const visibleLists = getWorkdayVisiblePopupCandidates();
            const orphanOpts = [...document.querySelectorAll(
                '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]',
            )].filter(isVisibleElement).slice(0, 8).map(o => optionText(o));
            debugLog(
                `${WD} single-select popup miss dump`,
                openKey.slice(0, 50),
                'trigger=', openTrigger?.tagName, openTrigger?.getAttribute?.('role'),
                'aria-expanded=', openTrigger?.getAttribute?.('aria-expanded'),
                'aria-controls=', ariaControls.slice(0, 40),
                'controlledVisible=', !!(controlled && isVisibleElement(controlled)),
                'radios=', radios, 'checks=', checks,
                'visibleLists=', visibleLists.length,
                visibleLists.slice(0, 3).map((el) => ({
                    id: el.id?.slice(0, 30),
                    auto: el.getAttribute('data-automation-id'),
                    role: el.getAttribute('role'),
                    text: (el.innerText || '').replace(/\s+/g, ' ').slice(0, 80),
                })),
                'orphanOpts=', orphanOpts,
                'fieldPreview=', (fieldRoot?.innerText || '').replace(/\s+/g, ' ').slice(0, 120),
            );
        }
        return popup;
    }

    // Resolve ALL candidates against ONE dropdown open, instead of opening a fresh popup per
    // candidate. The previous structure looped `for (const candidate of values) { open(); ... }` —
    // multi-candidate fallback lists here (skill-proficiency levels, salary brackets, decline
    // phrasings, etc.) can hold 5-8 entries, so a field whose real options never matched any single
    // candidate burned 5-8 tracked opens before giving up, on ANY tenant using such a fallback list
    // (observed on humana.wd5 with a plain Yes/No field routed through the skill-proficiency
    // candidate list ['Advanced','Expert','Proficient',...,'Yes','No']) — this is the actual
    // mechanism behind "dropdown open EXCESS", not a per-field bug. Open once, fetch options once,
    // try every candidate (generic substring/word-overlap + every special-case matcher) against
    // that same option set, and only reopen (max 2 total attempts) if the popup itself was missing
    // or wrong for this field.
    let match = null;
    let targetLabel = String(values[0] ?? '');
    let target = targetLabel.toLowerCase();
    let sawValidPopup = false;

    for (let attempt = 0; attempt < 2; attempt++) {
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
        const popup = await openFieldPopup();
        if (!popup || isWrongPopupForField(popup, labelLower)) continue;
        sawValidPopup = true;

        let options = getSingleSelectDropdownOptions(popup, false);
        match = null;
        for (const candidate of values) {
            const cTarget = String(candidate).toLowerCase();
            // Normalize I'm/I am so "I'm not a veteran" matches "I am not a veteran" (albemarle.wd5).
            const cNorm = cTarget.replace(/\bi'?m\b/g, 'i am').replace(/\bdon'?t\b/g, 'do not');
            const _wordOverlapMatch = (opt) => {
                const ot = optionText(opt).replace(/\bi'?m\b/g, 'i am').replace(/\bdon'?t\b/g, 'do not');
                const words = cNorm.split(/\s+/).filter(w => w.length > 2);
                return words.length >= 2 && words.every(w => ot.includes(w));
            };
            const _substringMatch = (opt) => {
                const ot = optionText(opt).toLowerCase().replace(/\bi'?m\b/g, 'i am').replace(/\bdon'?t\b/g, 'do not');
                if (ot === cTarget || ot === cNorm) return true;
                if (/^(yes|no)$/i.test(cTarget)) {
                    return new RegExp(`^${cTarget}\\b`, 'i').test(ot)
                        || ot.startsWith(`${cTarget} -`)
                        || ot.startsWith(`${cTarget},`);
                }
                // Short / country-abbrev candidates must be whole tokens — "us" must NOT match
                // "australia" (sggovterp.wd102 Citizenship Status country list).
                if (cNorm.length <= 3 || /^(u\.?s\.?a?|uk|u\.?a\.?e\.?|jp)$/i.test(cNorm)) {
                    const esc = cNorm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                    return new RegExp(`(^|[^a-z0-9])${esc}([^a-z0-9]|$)`, 'i').test(ot);
                }
                return ot.includes(cNorm) || cNorm.includes(ot) || ot.includes(cTarget) || cTarget.includes(ot);
            };
            const found = options.find(o => {
                const ot = optionText(o);
                return ot === cTarget || ot === cNorm
                    || ot.replace(/\bi'?m\b/g, 'i am') === cNorm;
            })
                || options.find(o => _substringMatch(o))
                || options.find(o => _wordOverlapMatch(o));
            if (found) {
                match = found;
                targetLabel = String(candidate);
                target = cTarget;
                break;
            }
        }
        if (!match && /not to my knowledge/i.test(values.join(' '))) {
            match = options.find(o => /not to my knowledge/i.test(optionText(o)));
            if (match) targetLabel = optionText(match);
        }
        if (!match && values.some(v => /decline|prefer not|do not wish|don't wish|dont wish|choose not|not to disclose|wish to answer/i.test(String(v)))) {
            match = options.find(o => /prefer not|decline|do not wish|don't wish|dont wish|choose not|not to disclose|wish to answer|is not listed/i.test(optionText(o))
                && !/identify as (a |one or more|protected)/i.test(optionText(o)));
        }
        if (!match && /consent|acknowledge|understand and consent/i.test(values.join(' '))) {
            match = options.find(o => {
                const ot = optionText(o);
                if (/^select one$/i.test(ot)) return false;
                if (/do not consent|don't consent|i do not|i don't/i.test(ot)) return false;
                return /understand and consent|i consent|i agree|i acknowledge/i.test(ot);
            });
            if (match) targetLabel = optionText(match);
        }
        if (!match && (isWorkdayEeoDisclosureField(labelLower) || isWorkdayGenderIdentityField(labelLower)
            || isWorkdayDisclosureGenderField(labelLower) || /disability/i.test(labelLower))) {
            const dm = findDisclosureDropdownMatch(options, values, labelLower);
            if (dm?.match) {
                match = dm.match;
                targetLabel = dm.label;
                const disclosureOk = await selectWorkdayDisclosureListboxOption(fieldRoot, combobox, match, values, targetLabel);
                if (disclosureOk) {
                    await closeWorkdayPopups();
                    return true;
                }
            }
        }
        // Gender Female/Male/Unknown (rosendin.wd1) — stream "Prefer not to answer" → Unknown.
        if (!match && (isWorkdayDisclosureGenderField(labelLower) || isWorkdayGenderIdentityField(labelLower)
            || /please select your gender|please indicate your gender|\bgender\b/i.test(labelLower))
            && values.some(v => /prefer not|decline|not to (answer|disclose)|choose not|unknown|not specified/i.test(String(v)))) {
            const unknownOpt = options.find(o => /^unknown$/i.test(optionText(o)) || /^not specified$/i.test(optionText(o)));
            if (unknownOpt) {
                match = unknownOpt;
                targetLabel = optionText(unknownOpt);
                debugLog(`${WD} single-select gender decline→unknown`, targetLabel);
            }
        }
        // Entity lists: stream No/N/A → "I have never worked…" / "I do not have any relatives…"
        // (montefiore.wd12 — bare No never matches the long exclusive option).
        if (!match && values.some(v => /^(no|n\/a|na|none|not applicable|never)$/i.test(String(v || '').trim())
            || /never worked|have not worked|do not have any relatives|no relatives/i.test(String(v || '')))) {
            const neverWorked = options.find(o => /i have never worked|never worked for|have not worked for|i have not worked/i.test(optionText(o)));
            const noRelatives = options.find(o => /do not have any relatives|no relatives who work/i.test(optionText(o)));
            if ((/worked for|previously (?:worked|employed)|former|entities/i.test(labelLower) || isWorkdayFormerEmployerQuestion(labelLower))
                && neverWorked) {
                match = neverWorked;
                targetLabel = optionText(neverWorked);
                debugLog(`${WD} single-select never-worked entity`, targetLabel.slice(0, 60));
            } else if ((/relative|family/i.test(labelLower) || isWorkdayRelativeEmployerEntityQuestion(labelLower))
                && noRelatives) {
                match = noRelatives;
                targetLabel = optionText(noRelatives);
                debugLog(`${WD} single-select no-relatives entity`, targetLabel.slice(0, 60));
            } else if (neverWorked && !noRelatives) {
                match = neverWorked;
                targetLabel = optionText(neverWorked);
            } else if (noRelatives) {
                match = noRelatives;
                targetLabel = optionText(noRelatives);
            }
        }
        if (!match && isCompensationFieldLabel(labelLower)) {
            match = findSalaryBracketDropdownMatch(
                options,
                getProfileSalaryAmount(window.__wdApplyData?.profile || {}),
                getProfileSalaryAmountLocal(window.__wdApplyData?.profile || {}),
            );
            if (match) {
                debugLog(`${WD} single-select salary bracket match`, optionText(match), 'amount=', getProfileSalaryAmount(window.__wdApplyData?.profile || {}));
            }
        }
        if (!match && isDegreeFieldLabel(labelLower)) {
            // Degree options are frequently rendered as abbreviation codes ("B.S.", "BBA")
            // rather than the spelled-out candidate text, which the substring/word-overlap
            // matchers above never resolve — check the dot-normalized abbreviation, then
            // fall back to the bachelor-tier index heuristic (observed on ryder.wd5;
            // resolving here — instead of only in the fillWorkdayDegreePlainDropdown
            // fallback engine — keeps this field inside its 2-open budget).
            match = findDegreeAbbreviationMatch(options, values);
            if (!match) {
                const idx = findBachelorDegreeOptionIndex(options);
                if (idx >= 0) match = options[idx];
            }
            if (match) {
                targetLabel = optionText(match);
                debugLog(`${WD} single-select degree abbrev match`, targetLabel, 'from=', target);
            }
        }
        if (!match && isWorkdayYearsExperienceBandQuestion(labelLower)) {
            const optTexts = options.map((o) => optionText(o));
            const band = getWorkdayYearsExperienceBandAnswer(
                labelLower,
                optTexts,
                window.__wdApplyData?.profile,
            );
            if (band) {
                match = options.find((o) => optionText(o).toLowerCase() === String(band).toLowerCase())
                    || options.find((o) => textMatchesCandidate(optionText(o), band));
                if (match) {
                    targetLabel = optionText(match);
                    debugLog(`${WD} single-select YOE band rematch`, targetLabel.slice(0, 40),
                        'from=', target.slice(0, 30));
                }
            }
        }
        if (!match && /phone device/i.test(labelLower)) {
            const phoneMatch = findPhoneDeviceTypeOption(options, values);
            if (phoneMatch) {
                match = phoneMatch;
                targetLabel = optionText(match);
                debugLog(`${WD} single-select phone device match`, targetLabel, 'from=', target);
            }
        }
        if (!match && (values.some(v => /^i agree$/i.test(String(v)))
            || isWorkdayPrivacyConsentDropdownField(labelLower, fieldRoot)
            || isWorkdaySmsConsentDropdownField(labelLower, fieldRoot)
            || values.some(v => /consent to receive text/i.test(String(v))))) {
            match = options.find(o => /consent to receive text|consent to receive sms/i.test(optionText(o)) && !/do not consent|don't consent/i.test(optionText(o)))
                || options.find(o => /^i agree$/i.test(optionText(o)))
                || options.find(o => /i have received|received/i.test(optionText(o)) && !/not received/i.test(optionText(o)))
                || options.find(o => /i agree/i.test(optionText(o)) && !/do not agree/i.test(optionText(o)))
                || options.find(o => /^yes\b/i.test(optionText(o)) && !/do not|don't/i.test(optionText(o)));
            if (match) targetLabel = optionText(match);
        }
        // Stream sometimes returns profile free-text (city, name) for a Yes/No prompt. Resolve
        // locally before marking a permanent miss — otherwise the field is stuck for the step.
        if (!match && isWorkdayYesNoOptionList(options.map(o => optionText(o)))) {
            const streamLooksLikeYn = values.some(v => /^(yes|no)\b/i.test(String(v || '').trim()));
            const ynAnswer = getWorkdayYesNoSmartDefault(popupLabel || labelLower)
                || getHardcodedYesNoAnswer(popupLabel || labelLower)
                || getProfileDerivedYesNoAnswer(window.__wdApplyData?.profile || {}, popupLabel || labelLower)
                // Garbage stream (city/name) on a pure Yes/No list → No (procore.wd12 located-in-city).
                || (!streamLooksLikeYn ? 'No' : null);
            if (ynAnswer) {
                const ynMatch = options.find(o => new RegExp(`^${String(ynAnswer).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(optionText(o)));
                if (ynMatch) {
                    match = ynMatch;
                    targetLabel = optionText(ynMatch);
                    target = targetLabel.toLowerCase();
                    clearWorkdaySingleSelectMissKey(popupLabel || labelLower);
                    debugLog(`${WD} single-select yes/no local after stream-miss`,
                        String(values[0] || '').slice(0, 40), '->', targetLabel);
                }
            }
        }
        // Travel % dropdowns: stream "20%" → "up to 25%" (guidehouse.wd1) before miss-lock.
        if (!match && /percentage.*travel|travel.*percentage|willing to travel|how much.*travel/i.test(labelLower)) {
            const optTexts = options.map(o => optionText(o));
            for (const candidate of values) {
                const travelHit = resolveTravelPercentageOption(candidate, optTexts);
                if (!travelHit) continue;
                const tMatch = options.find(o => optionText(o) === travelHit.toLowerCase())
                    || options.find(o => optionText(o).includes(travelHit.toLowerCase()));
                if (tMatch) {
                    match = tMatch;
                    targetLabel = optionText(tMatch);
                    target = targetLabel.toLowerCase();
                    debugLog(`${WD} single-select travel% resolved`, String(candidate).slice(0, 20), '->', targetLabel);
                    break;
                }
            }
        }
        // County: profile area "Greater London" is not a UK LA option — rematch via postcode/borough
        // against the open list before miss-lock (domesticandgeneral.wd3 and any UK County tenant).
        if (!match && isWorkdayCountyFieldLabel(popupLabel || labelLower)) {
            const countyMatch = resolveCountyOptionAgainstList(
                options,
                window.__wdApplyData?.profile || {},
            );
            if (countyMatch) {
                match = countyMatch;
                targetLabel = optionText(countyMatch);
                target = targetLabel.toLowerCase();
                debugLog(`${WD} single-select county resolved`, String(values[0] || '').slice(0, 40), '->', targetLabel);
            }
        }
        // PGE / government employment status (bah.wd1): stream or Yes/No "No" → "I have never been employed…"
        if (!match && (isWorkdayGovernmentEmploymentQuestion(popupLabel || labelLower)
            || options.some(o => /i have never been employed/i.test(optionText(o))))) {
            const neverOpt = options.find(o => /i have never been employed/i.test(optionText(o)));
            if (neverOpt) {
                match = neverOpt;
                targetLabel = optionText(neverOpt);
                target = targetLabel.toLowerCase();
                debugLog(`${WD} single-select government employment resolved`, String(values[0] || '').slice(0, 20), '->', targetLabel.slice(0, 60));
            }
        }

        debugLog(`${WD} single-select options`, options.slice(0, 10).map(o => optionText(o)), 'target=', target, 'match=', !!match);

        if (match?.getAttribute('data-value')) {
            workdayClickElement(match);
            await wait(500);
            if (typeof match.click === 'function') match.click();
            await wait(700);
            const btnList = fieldRoot.querySelector('button[aria-haspopup="listbox"]');
            const optLabel = optionText(match) || targetLabel;
            await commitWorkdayComboboxSelection(fieldRoot, combobox || btnList, match, optLabel);
            await wait(700);
            const filledCands = [optLabel, targetLabel, ...values].filter(Boolean);
            if (isWorkdaySingleSelectFilled(fieldRoot, filledCands)) {
                debugLog(`${WD} single-select filled via data-value`, optLabel,
                    getWorkdayButtonListboxOpaqueValue(fieldRoot) || combobox?.value || '');
                await closeWorkdayPopups();
                return true;
            }
            // Button listboxes: never treat popup-close alone as success — that left Review
            // "No Response" when only button.value was painted (unimelb.wd105).
            if (!btnList) {
                const popupGone = !document.contains(popup) || !isVisibleElement(popup);
                if (popupGone) {
                    debugLog(`${WD} single-select filled via data-value`, targetLabel, combobox?.value);
                    await closeWorkdayPopups();
                    return true;
                }
            } else {
                debugLog(`${WD} single-select data-value not durable`, optLabel.slice(0, 40),
                    'opaque=', getWorkdayButtonListboxOpaqueValue(fieldRoot).slice(0, 28),
                    'btn=', String(btnList.innerText || '').slice(0, 40));
            }
        }

        if (await tryClickOption(match, targetLabel)) {
            debugLog(`${WD} single-select filled via click`, targetLabel);
            await closeWorkdayPopups();
            return true;
        }

        // After any click attempt, wait for React to commit before trying search or next attempt
        await wait(600);
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) {
            await closeWorkdayPopups();
            return true;
        }

        // Try every remaining candidate through the search box WITHOUT reopening the popup — the
        // search input stays available in the same open popup, so retyping costs no extra tracked
        // open (unlike the old per-candidate loop, which reopened the whole popup for this).
        const searchInput = popup.querySelector('[data-automation-id="searchBox"] input') || popup.querySelector('input');
        if (searchInput) {
            for (const candidate of values) {
                const cLabel = String(candidate);
                const cTarget = cLabel.toLowerCase();
                await workdayTypeElement(searchInput, cLabel);
                await wait(1200);
                const searchOptions = getSingleSelectDropdownOptions(popup, false);
                const searchMatch = searchOptions.find(o => optionText(o) === cTarget)
                    || searchOptions.find(o => {
                        const ot = optionText(o);
                        if (cTarget.length <= 3 || /^(u\.?s\.?a?|uk|u\.?a\.?e\.?|jp)$/i.test(cTarget)) {
                            const esc = cTarget.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                            return new RegExp(`(^|[^a-z0-9])${esc}([^a-z0-9]|$)`, 'i').test(ot);
                        }
                        return ot.includes(cTarget);
                    });
                if (await tryClickOption(searchMatch, cLabel)) {
                    debugLog(`${WD} single-select filled via search`, cLabel);
                    await closeWorkdayPopups();
                    return true;
                }
            }
        }

        await closeWorkdayPopups();
        // Check after closing before deciding to retry
        await wait(400);
        if (isWorkdaySingleSelectFilled(fieldRoot, values)) return true;
    }
    const missKey = normalizeDropdownOpenKey(popupLabel || labelLower || 'single-select');
    // Phone Device Type: a null/wrong sibling popup must NOT permanent-miss-lock — retries and
    // typeahead need another chance after Country Phone Code finishes (entegris.wd1 / icf.wd5).
    if (/phone device/i.test(missKey) && !sawValidPopup) {
        clearWorkdaySingleSelectMissKey(popupLabel || labelLower);
        debugLog(`${WD} single-select no miss-lock — phone device popup never opened`);
        // Typeahead fallback: click + type first token + Enter (Workday often filters then commits).
        for (const cand of values.slice(0, 5)) {
            await closeWorkdayPopups();
            await wait(250);
            const trig = openTrigger || getWorkdayDropdownTrigger(fieldRoot) || combobox;
            if (!trig) break;
            workdayScrollToTarget(trig, 120);
            await workdayClick(trig);
            await wait(700);
            const input = fieldRoot.querySelector('input[role="combobox"]')
                || (trig.tagName === 'INPUT' ? trig : null);
            const token = String(cand).trim().split(/\s+/)[0];
            if (input && token) {
                await workdayTypeElement(input, token);
                await wait(900);
                let popup = findPopupNearField(fieldRoot, labelLower) || findActiveWorkdayPopup();
                if (popup && isWrongPopupForField(popup, labelLower)) popup = null;
                if (popup) {
                    const opts = getSingleSelectDropdownOptions(popup, false);
                    const phoneMatch = findPhoneDeviceTypeOption(opts, values);
                    if (phoneMatch && await tryClickOption(phoneMatch, optionText(phoneMatch))) {
                        debugLog(`${WD} phone device typeahead click`, optionText(phoneMatch));
                        await closeWorkdayPopups();
                        return true;
                    }
                }
                input.focus?.();
                await dispatchListKey('ArrowDown', input);
                await wait(200);
                await dispatchListKey('Enter', input);
                await wait(500);
                await closeWorkdayPopups();
                if (isWorkdaySingleSelectFilled(fieldRoot, values)
                    || isWorkdaySingleSelectFilled(fieldRoot, getPhoneDeviceTypeCandidates())
                    || isWorkdayComboboxCommitted(fieldRoot)) {
                    debugLog(`${WD} phone device typeahead keyboard`, token);
                    return true;
                }
            }
        }
        return false;
    }
    window.__wdSingleSelectMissKeys = window.__wdSingleSelectMissKeys || new Set();
    window.__wdSingleSelectMissKeys.add(missKey);
    return false;
}

async function fillWorkdayStateDropdown(element, stateName) {
    const name = String(stateName || '').trim();
    if (!name) return false;
    const fieldRoot = element?.closest?.('[data-automation-id*="formField"]') || element?.parentElement;
    if (!fieldRoot) return false;
    const fieldLabel = getContainerLabel(fieldRoot);
    if (/phone code|country phone/i.test(fieldLabel)) {
        debugLog(`${WD} state fill refused — control is phone code`, fieldLabel.slice(0, 40));
        return false;
    }
    if (fieldLabel && !isWorkdayStateFieldLabel(fieldLabel) && !/state|province|region/i.test(fieldLabel)) {
        debugLog(`${WD} state fill refused — not a state field`, fieldLabel.slice(0, 40));
        return false;
    }
    // AI streaming sometimes returns a bare 2-letter US state code (e.g. "NY") instead of the full
    // dropdown-option text ("New York") — observed on uline.wd1 information step, where the model
    // streamed "NY" for a non-US profile applying to a NY-based US job (see the "non-US profile" stream
    // fallback above) and every dropdown match against options like "new york" failed on a plain
    // substring/word check against "ny", burning repeated opens with zero chance of ever matching. Not
    // tenant-specific — any Workday tenant with a required US State field hits this whenever the model
    // answers with the abbreviation. Expand to the full name so the existing matcher can succeed.
    const abbrevExpansion = /^[A-Za-z]{2}$/.test(name) ? US_STATE_BY_ABBREV[name.toUpperCase()] : null;
    const candidates = [...new Set([
        name,
        name.replace(/\s+state$/i, ''),
        ...(abbrevExpansion ? [abbrevExpansion] : []),
        // Common India / alternate spellings (diacritics folded in textMatchesCandidate)
        ...( /telangana/i.test(name) ? ['Telangana', 'Telangāna', 'TG', 'TS', 'Telangana State'] : []),
        ...( /andhra/i.test(name) ? ['Andhra Pradesh', 'AP'] : []),
        ...( /karnataka/i.test(name) ? ['Karnataka', 'KA'] : []),
        ...( /maharashtra/i.test(name) ? ['Maharashtra', 'MH'] : []),
        ...( /tamil nadu/i.test(name) ? ['Tamil Nadu', 'TN'] : []),
        ...( /bengaluru|bangalore|karnataka/i.test(name) ? ['Karnataka', 'KA'] : []),
    ].filter(Boolean))];
    if (isStateDropdownFilled(fieldRoot, candidates)) return true;

    clearWorkdaySingleSelectMissKey('state');
    clearWorkdaySingleSelectMissKey(name);
    resetWorkdayDropdownOpenCount('state');
    resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(name));

    const trigger = getWorkdayDropdownTrigger(fieldRoot) || element;
    const combobox = fieldRoot.querySelector('input[role="combobox"]') || element;

    // Virtualized India/US state lists: open once, search or scroll — do not burn opens on TG/TS.
    for (let attempt = 0; attempt < 2; attempt++) {
        if (isStateDropdownFilled(fieldRoot, candidates)) return true;
        await closeWorkdayPopups();
        await wait(300);
        workdayScrollToTarget(trigger, 120);
        trackWorkdayDropdownOpen('state');
        await workdayClick(trigger);
        // Poll — guidehouse.wd1 / slow tenants often need >1.2s before listbox is addressable.
        let popup = null;
        for (let poll = 0; poll < 8 && !popup; poll++) {
            await wait(400);
            popup = findPopupNearField(fieldRoot, 'state') || findActiveWorkdayPopup();
            if (popup && isWrongPopupForField(popup, 'state')) popup = null;
        }
        if (!popup) {
            await workdayClick(combobox);
            for (let poll = 0; poll < 6 && !popup; poll++) {
                await wait(400);
                popup = findPopupNearField(fieldRoot, 'state') || findActiveWorkdayPopup();
                if (popup && isWrongPopupForField(popup, 'state')) popup = null;
            }
        }
        if (!popup) {
            debugLog(`${WD} state popup missing`, name);
            // Stale painted State value can block reopen — clear then retry (bah.wd1 City unlock).
            if (attempt === 0) {
                await clearWorkdayPromptFieldSelection(fieldRoot);
                await wait(400);
            }
            continue;
        }

        const searchInput = popup.querySelector('[data-automation-id="searchBox"] input')
            || popup.querySelector('input[type="text"], input[type="search"], input:not([type="hidden"])');
        if (searchInput && searchInput !== document.body) {
            // Search by the full state name when we expanded an abbreviation — tenants' typeahead
            // filters generally match the visible option text ("new york"), not "ny".
            const searchTerm = abbrevExpansion || name;
            debugLog(`${WD} state popup search`, searchTerm);
            await workdayTypeElement(searchInput, searchTerm);
            await wait(1200);
        }

        let options = getSingleSelectDropdownOptions(popup, false);
        debugLog(`${WD} state options`, name, options.slice(0, 14).map(o => optionText(o)));
        let match = options.find(o => candidates.some(c => textMatchesCandidate(optionText(o), c)));
        if (!match) {
            const scrolled = await findScrollMenuOption(fieldRoot, popup, candidates, 'state');
            if (scrolled?.el) match = scrolled.el;
        }
        if (!match) {
            if (await selectWorkdayMenuOptionByKeyboard(fieldRoot, popup, candidates, 'state')) {
                await wait(500);
                await closeWorkdayPopups();
                if (isStateDropdownFilled(fieldRoot, candidates)) {
                    debugLog(`${WD} state filled via keyboard`, name);
                    return true;
                }
            }
            await closeWorkdayPopups();
            continue;
        }

        const label = optionText(match);
        debugLog(`${WD} state selecting`, label.slice(0, 60));
        workdayScrollToTarget(match, 120);
        workdayClickElement(match);
        await wait(500);
        if (typeof match.click === 'function') match.click();
        await wait(400);
        await commitWorkdayComboboxSelection(fieldRoot, combobox, match, label);
        await closeWorkdayPopups();
        await wait(400);
        if (isStateDropdownFilled(fieldRoot, candidates)
            || isWorkdayOpaqueOptionId(getWorkdayComboboxInputValue(fieldRoot))) {
            debugLog(`${WD} state filled`, label.slice(0, 40));
            return true;
        }
    }

    // Last resort: single-select with the primary name only (avoid TG/TS burning opens)
    resetWorkdayDropdownOpenCount('state');
    clearWorkdaySingleSelectMissKey('state');
    const lastResortNames = abbrevExpansion
        ? [abbrevExpansion, name]
        : [name, name.replace(/\s+state$/i, '')];
    if (await fillWorkdaySingleSelectDropdown(element, lastResortNames, 'state')) {
        return true;
    }
    debugLog(`${WD} state fill failed`, name);
    return false;
}

function normalizePhoneCodeOptionText(text) {
    return String(text || '')
        .replace(/\s+not checked/i, '')
        .replace(/\s+checked/i, '')
        .replace(/\s+/g, ' ')
        .trim();
}

function phoneCodeOptionMatches(text, profile) {
    const t = normalizePhoneCodeOptionText(text).toLowerCase();
    if (!t) return false;
    if (profileExpectsUS(profile)) {
        return isUSMainlandPhoneCodeOption(t);
    }
    const dialDigits = getProfilePhoneDialDigits(profile);
    if (dialDigits && extractDialDigitsFromPhoneText(t) === dialDigits) return true;
    if (dialDigits && t.includes(`(+${dialDigits})`)) return true;
    const code = String(profile?.phoneCountryCode || profile?.general?.phoneCountryCode || '').trim();
    if (code && t.includes(code.toLowerCase())) return true;
    if (previewContainsProfileCountryName(t, profile) && dialDigits && t.includes(`+${dialDigits}`)) {
        return true;
    }
    return isPhoneCodeOptionText(t) && getExpectedPhoneCodeCandidates(profile).some(c => textMatchesCandidate(t, c));
}

function isUSMainlandPhoneCodeOption(text) {
    const t = normalizeWorkdayDropdownSelectedText(text).toLowerCase();
    if (!/\(\+1\)/.test(t)) return false;
    if (/minor outlying|samoa|guam|puerto rico|virgin islands|mariana|micronesia|palau|marshall|anguilla|antigua|barbuda|bermuda|bahamas|dominica|grenada|jamaica|montserrat|kitts|nevis|lucia|vincent|tobago|trinidad|turks|caicos|cayman|aruba|curacao|bonaire|sint|martin|barbados|belize|haiti|dominican/i.test(t)) {
        return false;
    }
    if (/united states of america/i.test(t)) return true;
    if (/^united states \(\+1\)$/i.test(t.trim())) return true;
    return /^\(\+1\)$/.test(t.trim());
}

function isUSPhoneCodeTerritoryOption(text) {
    const t = normalizeWorkdayDropdownSelectedText(text).toLowerCase();
    return /\(\+1\)/.test(t) && !isUSMainlandPhoneCodeOption(t);
}

function findPhoneCodeMatchInItems(items, profile) {
    let match = items.find(o => phoneCodeOptionMatches(o.text, profile));
    if (match) return match;

    if (profileExpectsUS(profile)) {
        return items.find(o => isUSMainlandPhoneCodeOption(o.text)) || null;
    }

    const dialDigits = getProfilePhoneDialDigits(profile);
    if (dialDigits) {
        match = items.find(o => extractDialDigitsFromPhoneText(o.text) === dialDigits);
        if (match) return match;
    }

    if (!profileExpectsUS(profile)) {
        for (const name of [getWorkdayCountryName(profile), getProfileCountryName(profile)]) {
            const n = String(name || '').toLowerCase();
            if (!n) continue;
            match = items.find(o => {
                const t = o.text.toLowerCase();
                return t.includes(n) && (!dialDigits || t.includes(`+${dialDigits}`));
            });
            if (match) return match;
        }
        return match || null;
    }

    return items.find(o => {
        const t = o.text.toLowerCase();
        return /united states/i.test(t) && /\(\+1\)/.test(t)
            && !/samoa|guam|puerto|virgin|minor|mariana|micronesia|palau|marshall/i.test(t);
    }) || null;
}

function getPhoneCodeListScroller(popup) {
    if (!popup) return null;
    const candidates = [
        popup.querySelector('[data-automation-id="promptOptions"]'),
        popup.querySelector('[role="listbox"]'),
        popup.querySelector('[data-automation-id="activeListContainer"]'),
        popup.querySelector('[data-automation-id="wd-MenuList"]'),
        popup,
    ].filter(Boolean);
    // Virtualized Canada race lists (mckesson.wd3) often put overflow on an ancestor, not the listbox.
    for (const start of candidates) {
        let el = start;
        for (let depth = 0; el && depth < 6; depth++) {
            if (el.scrollHeight > el.clientHeight + 4) return el;
            el = el.parentElement;
        }
    }
    return candidates.find(el => el.scrollHeight > el.clientHeight + 4) || candidates[0] || null;
}

async function walkPhoneCodeListWithKeys(fieldRoot, profile, popup) {
    const firstItem = popup.querySelector('[data-automation-id="menuItem"], [role="option"]');
    if (!firstItem) return null;

    firstItem.focus();
    await wait(200);

    let lastText = '';
    for (let i = 0; i < 280; i++) {
        const active = document.activeElement;
        if (active && (active.getAttribute('data-automation-id') === 'menuItem' || active.getAttribute('role') === 'option')) {
            const text = normalizePhoneCodeOptionText(active.getAttribute('aria-label') || active.innerText || '');
            if (text && text !== lastText) {
                lastText = text;
                if (phoneCodeOptionMatches(text, profile)) {
                    debugLog(`${WD} phone code found by arrow`, text, 'step=', i);
                    return { el: active, text };
                }
                if (profileExpectsUS(profile) && /united states/i.test(text.toLowerCase()) && /\(\+1\)/.test(text)
                    && !/samoa|guam|puerto|virgin|minor|mariana|micronesia|palau|marshall/i.test(text.toLowerCase())) {
                    debugLog(`${WD} phone code found by arrow`, text, 'step=', i);
                    return { el: active, text };
                }
            }
        }

        const keyTarget = document.activeElement || firstItem;
        keyTarget.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true }));
        keyTarget.dispatchEvent(new KeyboardEvent('keyup', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true }));
        await wait(60);
    }
    return null;
}

async function scrollPhoneCodeListForMatch(fieldRoot, profile, popup) {
    let match = findPhoneCodeMatchInItems(getPhoneCodeMenuItems(fieldRoot), profile);
    if (match) return match;

    const scroller = getPhoneCodeListScroller(popup);
    if (!scroller) return null;

    scroller.scrollTop = 0;
    await wait(250);
    let lastTop = -1;

    for (let step = 0; step < 50; step++) {
        match = findPhoneCodeMatchInItems(getPhoneCodeMenuItems(fieldRoot), profile);
        if (match) {
            debugLog(`${WD} phone code found by scroll`, match.text, 'step=', step);
            return match;
        }

        const nextTop = Math.min(
            scroller.scrollTop + Math.max(scroller.clientHeight * 0.8, 100),
            scroller.scrollHeight,
        );
        if (nextTop === lastTop) break;
        scroller.scrollTop = nextTop;
        lastTop = nextTop;
        await wait(250);
    }
    return findPhoneCodeMatchInItems(getPhoneCodeMenuItems(fieldRoot), profile);
}

async function findPhoneCodeOption(fieldRoot, profile, popup) {
    if (profileExpectsUS(profile)) {
        const findMatch = (items) => findPhoneCodeMatchInItems(items, profile);
        for (const term of ['United States of America (+1)', 'United States of America', 'United States', 'USA', '+1']) {
            const searched = await tryWorkdayDropdownSearch(popup, fieldRoot, term, getPhoneCodeMenuItems, findMatch, 'phone code');
            if (searched) return searched;
        }
    }

    let match = findPhoneCodeMatchInItems(getPhoneCodeMenuItems(fieldRoot), profile);
    if (match) {
        debugLog(`${WD} phone code visible`, match.text);
        return match;
    }

    const searchTerms = profileExpectsUS(profile)
        ? ['United States of America (+1)', 'United States of America', 'United States', 'USA']
        : [String(profile?.phoneCountryCode || '+1')];
    const findMatch = (items) => findPhoneCodeMatchInItems(items, profile);
    for (const term of searchTerms) {
        match = await tryWorkdayDropdownSearch(popup, fieldRoot, term, getPhoneCodeMenuItems, findMatch, 'phone code');
        if (match) return match;
    }

    match = await walkPhoneCodeListWithKeys(fieldRoot, profile, popup);
    if (match) return match;

    // Always allow scroll even after excess opens — virtualized lists need it when search
    // fails to filter (kyndryl.wd5 left Albania visible after "United States" search).
    match = await scrollPhoneCodeListForMatch(fieldRoot, profile, popup);
    if (match) return match;

    debugLog(`${WD} phone code option not found`, getPhoneCodeMenuItems(fieldRoot).slice(0, 8).map(o => o.text));
    return null;
}

function getPhoneCodeMenuItems(fieldRoot) {
    return getAllHearMenuItems(fieldRoot)
        .map(o => ({ el: o.el, text: normalizePhoneCodeOptionText(o.text) }))
        .filter(o => isPhoneCodeOptionText(o.text));
}

function findPhoneCodePopup(fieldRoot) {
    const rect = fieldRoot?.getBoundingClientRect();
    return findVisibleWorkdayPopups()
        .filter(p => isPhoneCodePopup(p))
        .filter(p => {
            if (!rect) return true;
            const pr = p.getBoundingClientRect();
            return pr.top >= rect.top - 120
                && pr.top <= rect.bottom + 800
                && pr.left >= rect.left - 160
                && pr.left <= rect.right + 1000;
        })[0] || null;
}

function isPhoneCodeOptionSelected(opt) {
    return opt?.getAttribute('aria-selected') === 'true'
        || opt?.getAttribute('aria-checked') === 'true'
        || !!opt?.querySelector('input[type="checkbox"]:checked');
}

async function clickPhoneCodeMenuItem(opt, fieldRoot, profile, displayText) {
    if (!opt) return false;
    const pillBefore = getWorkdayFieldSelectedText(fieldRoot);
    const label = displayText || normalizePhoneCodeOptionText(opt.getAttribute('aria-label') || opt.innerText || '');
    const combobox = fieldRoot.querySelector('input[role="combobox"]');
    if (combobox) {
        await commitWorkdayComboboxSelection(fieldRoot, combobox, opt, label);
        await wait(500);
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;
    }

    const clickTargets = [
        opt.querySelector('input[type="checkbox"]'),
        opt.querySelector('[role="checkbox"]'),
        opt.querySelector('[data-automation-id="promptLeafNode"]'),
        opt.querySelector('[data-automation-id="promptOption"]'),
        opt.querySelector('label'),
        opt,
    ].filter(Boolean);

    for (const target of clickTargets) {
        debugLog(`${WD} phone code item click`, normalizePhoneCodeOptionText(opt.getAttribute('aria-label') || ''));
        await workdayClick(target);
        await wait(450);
        if (isPhoneCodeOptionSelected(opt) || isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;
        if (getWorkdayFieldSelectedText(fieldRoot) !== pillBefore && isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;
    }

    opt.focus();
    for (const key of [' ', 'Enter']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
        }));
        await wait(450);
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;
    }

    return isPhoneCodeFilledForProfile(fieldRoot, profile);
}

async function dismissPhoneCodeDropdown(fieldRoot) {
    const combobox = fieldRoot?.querySelector('input[role="combobox"]');
    if (combobox) {
        combobox.dispatchEvent(new Event('blur', { bubbles: true }));
        await wait(300);
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2, [data-automation-id="applicationHeader"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(300);
    }
}

async function clearInvalidUSPhoneCode(fieldRoot, profile) {
    if (!fieldRoot || !profileExpectsUS(profile)) return false;
    const preview = getWorkdayFieldSelectedText(fieldRoot);
    if (!preview || !isUSPhoneCodeTerritoryOption(preview)) return false;
    debugLog(`${WD} clearing invalid US territory phone code`, preview.slice(0, 60));
    for (const btn of fieldRoot.querySelectorAll(
        'button[aria-label*="Remove" i], button[aria-label*="Delete" i], [data-automation-id*="DELETE"]',
    )) {
        await workdayClick(btn);
        await wait(400);
    }
    if (!isUSPhoneCodeTerritoryOption(getWorkdayFieldSelectedText(fieldRoot))) return true;
    const trigger = getWorkdayDropdownTrigger(fieldRoot) || fieldRoot.querySelector('input[role="combobox"]');
    if (!trigger) return false;
    await workdayClick(trigger);
    await wait(1200);
    const popup = findPhoneCodePopup(fieldRoot) || findPopupNearField(fieldRoot, 'phone code');
    for (const opt of getPhoneCodeMenuItems(fieldRoot).map(o => o.el)) {
        if (isPhoneCodeOptionSelected(opt)) {
            await clickPhoneCodeMenuItem(opt, fieldRoot, profile, '');
            await wait(350);
        }
    }
    await dismissPhoneCodeDropdown(fieldRoot);
    return !isUSPhoneCodeTerritoryOption(getWorkdayFieldSelectedText(fieldRoot));
}

/** Clear a committed wrong dial (e.g. Albania +355) before searching for the profile code (kyndryl.wd5). */
async function clearWrongPhoneCodeForProfile(fieldRoot, profile) {
    if (!fieldRoot || isPhoneCodeFilledForProfile(fieldRoot, profile)) return false;
    const preview = getWorkdayFieldSelectedText(fieldRoot) || '';
    if (!preview || /^select one|0 items selected/i.test(preview)) return false;
    if (!/\(\+\d/i.test(preview) && !/\+\d{1,4}/.test(preview)) return false;
    debugLog(`${WD} clearing wrong phone code`, preview.slice(0, 60));

    const stillWrong = () => {
        const p = getWorkdayFieldSelectedText(fieldRoot) || '';
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) return false;
        if (!/\(\+\d/i.test(p) && !/\+\d{1,4}/.test(p)) return false;
        if (/^select one|0 items selected/i.test(p)) return false;
        return true;
    };

    // Multiselect chips: delete/remove on each selectedItem.
    const chipDeletes = [...fieldRoot.querySelectorAll(
        '[data-automation-id="selectedItem"] button,'
        + ' [data-automation-id="deleteSelectedItem"],'
        + ' [data-automation-id="selectedItemList"] button,'
        + ' button[aria-label*="Remove" i], button[aria-label*="Delete" i], button[aria-label*="Clear" i],'
        + ' button[title*="Remove" i], button[title*="Delete" i],'
        + ' [data-automation-id="selectedItem"] [data-automation-id*="delete" i]',
    )].filter(isVisibleElement);
    for (const btn of chipDeletes) {
        await workdayClick(btn);
        await wait(350);
        if (!stillWrong()) break;
    }

    // Focus chip / combobox and Backspace/Delete — Workday multiselect clears this way
    // when the visible "X" is an icon without a reliable button selector (kyndryl.wd5).
    if (stillWrong()) {
        const chip = fieldRoot.querySelector('[data-automation-id="selectedItem"], [data-automation-id="promptSelection"]');
        const input = fieldRoot.querySelector('input[role="combobox"], input[data-uxi-widget-type="selectinput"], input:not([type="hidden"])');
        if (chip) {
            await workdayClick(chip);
            await wait(200);
        } else if (input) {
            await workdayClick(input);
            await wait(200);
        }
        for (const key of ['Backspace', 'Delete']) {
            if (!stillWrong()) break;
            const target = document.activeElement || input || fieldRoot;
            target.dispatchEvent(new KeyboardEvent('keydown', { key, code: key, bubbles: true, cancelable: true }));
            target.dispatchEvent(new KeyboardEvent('keyup', { key, code: key, bubbles: true }));
            await wait(300);
        }
    }

    // Open list and toggle off the selected wrong option (checkbox/aria-selected).
    if (stillWrong()) {
        const trigger = getWorkdayDropdownTrigger(fieldRoot) || fieldRoot.querySelector('input[role="combobox"]');
        if (trigger) {
            await workdayClick(trigger);
            await wait(900);
            for (const item of getPhoneCodeMenuItems(fieldRoot)) {
                if (!isPhoneCodeOptionSelected(item.el) && !/albania|selected/i.test(item.text)) continue;
                if (phoneCodeOptionMatches(item.text, profile)) continue;
                if (!/\(\+\d/i.test(item.text)) continue;
                debugLog(`${WD} deselect wrong phone code option`, item.text.slice(0, 40));
                // Prefer unchecking checkbox for multiselect phone codes.
                const check = item.el.querySelector('input[type="checkbox"]');
                if (check?.checked) {
                    await workdayClick(check);
                    await wait(400);
                } else {
                    await clickPhoneCodeMenuItem(item.el, fieldRoot, profile, item.text);
                    await wait(400);
                }
            }
            await dismissPhoneCodeDropdown(fieldRoot);
        }
    }

    if (stillWrong()) await clearWorkdayPromptFieldSelection(fieldRoot);
    resetWorkdayDropdownOpenCount('phone code');
    const ok = !stillWrong();
    debugLog(`${WD} clear wrong phone code done`, ok, (getWorkdayFieldSelectedText(fieldRoot) || '').slice(0, 50));
    return ok;
}

async function fillWorkdayPhoneCodeDropdown(element, profile) {
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    if (isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;

    await clearInvalidUSPhoneCode(fieldRoot, profile);
    await clearWrongPhoneCodeForProfile(fieldRoot, profile);
    resetWorkdayDropdownOpenCount('phone code');

    const trigger = getWorkdayDropdownTrigger(fieldRoot) || element;

    for (let attempt = 0; attempt < 4; attempt++) {
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) return true;
        await closeWorkdayPopups();
        await wait(300);
        workdayScrollToTarget(fieldRoot, 120);
        trackWorkdayDropdownOpen('phone code');
        await workdayClick(trigger);
        await wait(1500);

        const popup = findPhoneCodePopup(fieldRoot) || findPopupNearField(fieldRoot, 'phone code');
        if (!popup) {
            debugLog(`${WD} phone code popup missing`, attempt + 1);
            continue;
        }

        // Same open session: toggle off wrong selected dials before picking the profile code.
        // Selecting US while Albania stays checked leaves Albania as the committed pill (kyndryl.wd5).
        for (const item of getPhoneCodeMenuItems(fieldRoot)) {
            if (!isPhoneCodeOptionSelected(item.el)) continue;
            if (phoneCodeOptionMatches(item.text, profile)) continue;
            debugLog(`${WD} phone code uncheck before select`, item.text.slice(0, 40));
            const check = item.el.querySelector('input[type="checkbox"]');
            if (check?.checked) await workdayClick(check);
            else await workdayClick(item.el);
            await wait(400);
        }

        const match = await findPhoneCodeOption(fieldRoot, profile, popup);
        if (!match) {
            await dismissPhoneCodeDropdown(fieldRoot);
            await clearWrongPhoneCodeForProfile(fieldRoot, profile);
            continue;
        }

        // Re-resolve after virtualized scroll — stale node clicks no-op.
        const fresh = findPhoneCodeMatchInItems(getPhoneCodeMenuItems(fieldRoot), profile) || match;
        debugLog(`${WD} phone code selecting`, fresh.text);
        workdayScrollToTarget(fresh.el, 80);
        await wait(200);
        const check = fresh.el.querySelector('input[type="checkbox"]');
        if (check && !check.checked) {
            await workdayClick(check);
            await wait(450);
        }
        if (await clickPhoneCodeMenuItem(fresh.el, fieldRoot, profile, fresh.text)) {
            await wait(800);
            await dismissPhoneCodeDropdown(fieldRoot);
            if (isPhoneCodeFilledForProfile(fieldRoot, profile)) {
                debugLog(`${WD} phone code filled`, fresh.text);
                return true;
            }
        }
        // Keyboard commit fallback on the highlighted option.
        fresh.el.focus?.();
        await wait(150);
        await dispatchListKey('Enter', fresh.el);
        await wait(500);
        await dismissPhoneCodeDropdown(fieldRoot);
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) {
            debugLog(`${WD} phone code filled via enter`, fresh.text);
            return true;
        }
        const preview = getWorkdayFieldSelectedText(fieldRoot);
        if (isPhoneCodeFilledForProfile(fieldRoot, profile)) {
            debugLog(`${WD} phone code filled after click`, preview);
            return true;
        }
        debugLog(`${WD} phone code click did not commit`, preview);
        await dismissPhoneCodeDropdown(fieldRoot);
        await clearWrongPhoneCodeForProfile(fieldRoot, profile);
    }

    debugLog(`${WD} phone code fill failed`, getWorkdayFieldSelectedText(fieldRoot));
    return false;
}

async function fixStateForJobLocation() {
    const jobLocation = (window.__wdHistoryLocation || '').toLowerCase();
    const needsCA = jobLocation.includes('fontana') || /,\s*ca,|\bcalifornia\b/.test(jobLocation);
    if (!needsCA) return false;

    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!/\bstate\b/i.test(labelText)) continue;
        if (isStateDropdownFilled(container, 'California')) return false;
        const element = getContainerControl(container);
        if (!element) continue;
        debugLog(`${WD} fixing state from`, (container.innerText || '').slice(0, 80));
        const fixed = await fillWorkdayStateDropdown(element, 'California');
        if (fixed) await wait(1500);
        return fixed;
    }
    return false;
}

async function fixPhoneCodeForUS() {
    const profile = window.__wdApplyData?.profile;
    if (profile) return fixPhoneCodeForProfile(profile);
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!/phone code/i.test(labelText)) continue;
        if (isPhoneCodeFilled(container)) return false;
        const element = getContainerControl(container);
        if (!element) continue;
        debugLog(`${WD} fixing phone code from`, (container.innerText || '').slice(0, 80));
        const fixed = await fillWorkdayPhoneCodeDropdown(element, profile || {});
        if (fixed) await wait(1500);
        return fixed;
    }
    return false;
}

function getHearSelectedLabel(pill) {
    const text = String(pill || '').trim();
    if (!text) return '';
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    for (const line of lines) {
        if (/^(expanded|minimized)$/i.test(line)) continue;
        if (/^0 items selected|select one$/i.test(line)) continue;
        const fromCount = line.replace(/^[1-9]\d*\s+items?\s+selected,?\s*/i, '').trim();
        if (/^[1-9]\d*\s+items?\s+selected/i.test(line) && fromCount) return fromCount;
        if (line.length > 2 && !/^(expanded|minimized)$/i.test(line)) return line;
    }
    return '';
}

function isMultiSelectFilled(container) {
    const pillText = (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').trim();
    const selected = getHearSelectedLabel(pillText);
    if (selected && !/0 items selected|select one/i.test(selected.toLowerCase())) return true;
    if (/0 items selected/i.test(pillText)) return false;
    if (/[1-9]\d*\s+items?\s+selected/i.test(pillText)) return true;
    if (/social media|referral|recruiter|internet|job board|agency|advertisement|military|employee|contractor|linkedin|indeed|glassdoor|careerbuilder|company web site|company website|website|monster|ziprecruiter/i.test(pillText.toLowerCase())) {
        return true;
    }
    const selectedItems = container.querySelectorAll('[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"] li');
    return selectedItems.length > 0;
}

function isMMDDYYYYContainer(container) {
    const text = (container?.innerText || '').toLowerCase();
    if (isMMDDYYYYPreview(text)) return true;
    return Boolean(
        container?.querySelector('input[aria-label="Month"], input[aria-label*="Month" i]')
        && container?.querySelector('input[aria-label="Day"], input[aria-label*="Day" i]')
        && container?.querySelector('input[aria-label="Year"], input[aria-label*="Year" i]')
    );
}

async function fillWorkdayYesNo(container, answer) {
    let scope = container;
    for (let i = 0; i < 5 && scope; i++) {
        if (await clickWorkdayYesNo(scope, answer)) return true;
        scope = scope.parentElement;
    }
    return false;
}

async function fillKnownYesNoRadioFields(profile) {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const onQuestionsStep = (typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : '') === 'questions';
        if (isGenpactAiMatchingOptInField(label)) {
            if (!isWorkdaySingleSelectFilled(container, getGenpactAiMatchingCandidates())) {
                await fillWorkdayGenpactAiOptInField(container, label);
            }
            continue;
        }

        if (isWorkdayPrivacyConsentDropdownField(label, container)) {
            if (!isWorkdayAgreeDisagreeConsentFilled(container)) {
                const ok = await fillWorkdayPrivacyConsentDropdown(container, label);
                if (ok || isWorkdayAgreeDisagreeConsentFilled(container) || isWorkdayYesNoFilled(container, 'Yes')) {
                    continue;
                }
                // Misclassified — fall through to hardcoded Yes/No / stream fill
            } else {
                continue;
            }
        }
        if (isWorkdayGpaQuestion(label)) {
            if (!isWorkdayGpaFilled(container)) {
                await fillWorkdayGpaField(container, label);
            }
            continue;
        }
        if (isWorkdayMajorMultiSelectQuestion(label)) {
            await fillWorkdayMajorMultiSelectField(container, label);
            continue;
        }
        if (isWorkdaySkillAbilityQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySkillAbilityCandidates())) {
                await fillWorkdaySkillAbilityField(container, label);
            }
            continue;
        }
        if (isWorkdaySmsConsentDropdownField(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySmsConsentCandidates())
                && !isWorkdayYesNoFilled(container, 'Yes')) {
                await fillWorkdaySmsConsentDropdown(container, label);
            }
            continue;
        }
        if (isNotToMyKnowledgeQuestion(container, label)) {
            if (!isNotToMyKnowledgeFilled(container)) {
                await fillWorkdayNotToMyKnowledgeField(container, label);
            }
            continue;
        }
        if (isWorkdayClinicalSettingsQuestion(label)) {
            if (!isWorkdayClinicalSettingsFilled(container, profile)) {
                await fillWorkdayClinicalSettingsField(container, label, profile);
            }
            continue;
        }
        if (isWorkdayShiftAvailabilityQuestion(label)) {
            if (!isWorkdayShiftAvailabilityFilled(container)) {
                await fillWorkdayShiftAvailabilityField(container, label);
            }
            continue;
        }
        if (isWorkdayEmploymentTypeQuestion(label)) {
            if (!(isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayEmploymentTypeCandidates())
                || isWorkdaySingleSelectFilled(container, getWorkdayEmploymentTypeCandidates()))) {
                await fillWorkdayEmploymentTypeField(container, label);
            }
            continue;
        }
        if (isWorkdayBestContactTimeQuestion(label)) {
            if (!isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayBestContactTimeCandidates())) {
                await fillWorkdayBestContactTimeField(container, label);
            }
            continue;
        }
        if (isWorkdayNaIfNoTextField(label)) {
            await fillWorkdayNaIfNoTextField(container, label, profile);
            continue;
        }
        if (isWorkdayPassportVisaTypeTextField(label)) {
            await fillWorkdayPassportVisaTypeTextField(container, label, profile);
            continue;
        }

        if (isWorkdayAlwaysNoQuestion(label, container)) {
            if (!isWorkdayYesNoFieldLockedAndFilled(container, label)) {
                await fillWorkdayAlwaysNoField(container, label);
            }
            continue;
        }
        if (isWorkdayFormerEmployerQuestion(label)) {
            if (!isWorkdayFormerEmployerFilled(container, label) && !isWorkdayYesNoFilled(container, 'No')) {
                debugLog(`${WD} fill former employer`, label.slice(0, 70));
                await fillWorkdayFormerEmployerField(container, label);
            }
            continue;
        }
        const hasRadio = container.querySelector('input[type="radio"]');
        const hasYesNoCheckbox = isWorkdayYesNoCheckboxGroup(container);
        if (!hasRadio && !hasYesNoCheckbox) continue;
        const value = getProfileFieldValue(profile, label);
        if (!/^(yes|no)$/i.test(String(value))) continue;
        if (!shouldUseBareYesNoForContainer(container, value, label)) {
            debugLog(`${WD} skip bare yes/no on multi-checkbox`, label.slice(0, 70), value);
            continue;
        }
        if (isWorkdayYesNoFilled(container, value)) continue;
        debugLog(`${WD} fill known yes/no radio`, label.slice(0, 70), value);
        await fillWorkdayYesNoField(container, value);
        await wait(300);
    }
}

async function fixPreferredNameCheckbox(profile) {
    const hasPreferredName = Boolean(
        String(profile?.middleName || profile?.general?.middleName || '').trim()
        || String(getProfileFieldValue(profile, 'Preferred First Name') || '').trim()
    );
    if (hasPreferredName) return false;
    let fixed = false;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!/preferred name/i.test(label)) continue;
        for (const checkbox of container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
            if (!isWorkdayCheckboxChecked(checkbox)) continue;
            debugLog(`${WD} unchecking preferred name checkbox (no preferred name in profile)`);
            if (await workdayUncheckCheckbox(checkbox)) fixed = true;
        }
    }
    for (const labelEl of document.querySelectorAll('label')) {
        const text = (labelEl.innerText || '').trim();
        if (!/i have a preferred name/i.test(text)) continue;
        const checkbox = labelEl.control
            || (labelEl.getAttribute('for') && document.getElementById(labelEl.getAttribute('for')));
        if (checkbox && isWorkdayCheckboxChecked(checkbox)) {
            debugLog(`${WD} unchecking I have a preferred name`);
            if (await workdayUncheckCheckbox(checkbox)) fixed = true;
        }
    }
    return fixed;
}

function workdayClickElement(el) {
    if (!el) return false;
    if (agentStatus?.paused) return false;
    if (isHearInteractionBlocked(el)) {
        debugLog(`${WD} hear locked, skip click`);
        return false;
    }
    // Consent labels often wrap Privacy/Terms/Arbitration <a href> (safelite.com). Clicking the
    // label via elementFromPoint hits the nested link and opens a third-party tab — retarget to
    // the associated input / the label itself while the capture guard blocks the link default.
    let clickEl = el;
    const label = el.tagName === 'LABEL' ? el : el.closest?.('label');
    if (label && [...label.querySelectorAll('a[href]')].some(isWorkdayExternalNavigationLink)) {
        const input = label.control
            || (label.getAttribute('for') ? document.getElementById(label.getAttribute('for')) : null)
            || label.querySelector('input[type="checkbox"], input[type="radio"]');
        if (input) {
            debugLog(`${WD} click via input — label has external policy links`);
            clickEl = input;
        }
    }
    workdayScrollToTarget(clickEl, 120);
    const rect = clickEl.getBoundingClientRect();
    const x = rect.left + Math.min(rect.width / 2, Math.max(rect.width - 2, 1));
    const y = rect.top + Math.min(rect.height / 2, Math.max(rect.height - 2, 1));
    let target = document.elementFromPoint(x, y) || clickEl;
    const hitLink = target.closest?.('a[href]');
    if (hitLink && isWorkdayExternalNavigationLink(hitLink)) {
        debugLog(`${WD} click retarget — elementFromPoint hit external link`, (hitLink.href || '').slice(0, 80));
        target = clickEl;
    }
    if (target.tagName === 'A' && isWorkdayExternalNavigationLink(target)) {
        reportWorkdayExternalNavBlocked('workdayClickElement', target.href);
        return false;
    }
    const opts = { bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y };
    target.dispatchEvent(new PointerEvent('pointerover', opts));
    target.dispatchEvent(new PointerEvent('pointerenter', { bubbles: false, composed: true, clientX: x, clientY: y }));
    target.dispatchEvent(new PointerEvent('pointerdown', opts));
    target.dispatchEvent(new MouseEvent('mouseover', opts));
    target.dispatchEvent(new MouseEvent('mouseenter', { bubbles: false, composed: true, clientX: x, clientY: y }));
    target.dispatchEvent(new MouseEvent('mousedown', opts));
    if (typeof target.click === 'function') target.click();
    target.dispatchEvent(new MouseEvent('mouseup', opts));
    target.dispatchEvent(new PointerEvent('pointerup', opts));
    return true;
}

async function workdayClick(el) {
    if (!el) return false;
    await pause();
    if (agentStatus?.paused) return false;
    await wait(200);
    return workdayClickElement(el);
}

async function clickWorkdayYesNo(container, answer) {
    if (isWorkdayYesNoCheckboxGroup(container)) {
        return clickWorkdayYesNoCheckboxGroup(container, answer);
    }
    const target = String(answer).toLowerCase();
    const scope = container.closest?.('[data-automation-id*="formField"]') || container;
    for (const radio of scope.querySelectorAll('input[type="radio"]')) {
        const labelEl = document.querySelector(`label[for="${radio.id}"]`) || radio.closest('label');
        const label = (labelEl?.innerText || '').trim().toLowerCase();
        if (label === target || label.startsWith(`${target} `)) {
            if (!radio.checked) {
                await workdayClick(labelEl || radio);
                if (!radio.checked) {
                    radio.checked = true;
                    radio.dispatchEvent(new Event('change', { bubbles: true }));
                    radio.dispatchEvent(new Event('input', { bubbles: true }));
                }
            }
            return radio.checked;
        }
    }
    for (const labelEl of scope.querySelectorAll('label')) {
        const text = (labelEl.innerText || '').trim().toLowerCase();
        if (text !== target && !text.startsWith(`${target} `)) continue;
        const radio = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
        if (radio?.type === 'radio') {
            if (!radio.checked) await workdayClick(labelEl);
            if (!radio.checked) {
                radio.checked = true;
                radio.dispatchEvent(new Event('change', { bubbles: true }));
            }
            return radio.checked;
        }
        if (radio?.type === 'checkbox' || radio?.getAttribute?.('role') === 'checkbox') {
            const text = (labelEl.innerText || '').trim().toLowerCase();
            if (text === target || text.startsWith(`${target} `)) {
                return clickWorkdayYesNoCheckboxGroup(scope, answer);
            }
        }
    }
    for (const el of scope.querySelectorAll('button, [role="button"], [role="radio"], span, div')) {
        const text = (el.innerText || el.getAttribute('aria-label') || '').trim();
        if (text.toLowerCase() !== target || text.length > 6) continue;
        if (!isVisibleElement(el)) continue;
        await workdayClick(el);
        return scope.querySelector('input[type="radio"]:checked') !== null || true;
    }
    return false;
}

async function fillWorkdayYesNoField(container, answer) {
    if (!container || answer == null) return false;
    const label = getContainerLabel(container);
    if (isNotToMyKnowledgeQuestion(container, label)) {
        return fillWorkdayNotToMyKnowledgeField(container, label);
    }
    if (isWorkdayFormerEmployerQuestion(label)) {
        return fillWorkdayFormerEmployerField(container, label);
    }
    if (isWorkdayYesNoCheckboxConflict(container)) {
        debugLog(`${WD} yes/no conflict, normalizing`, getContainerLabel(container).slice(0, 60), answer);
        await clickWorkdayYesNoCheckboxGroup(container, answer);
        await wait(300);
        if (isWorkdayYesNoFilled(container, answer)) return true;
    }
    if (isWorkdayYesNoFilled(container, answer)) return true;
    if (await fillWorkdayYesNo(container, answer)) {
        await wait(400);
        if (isWorkdayYesNoFilled(container, answer)) return true;
    }
    const control = getContainerControl(container);
    if (control) {
        const candidates = String(answer).toLowerCase() === 'no'
            ? ['No', 'no', 'I do not confirm', 'No - I do not have a conflict of interest', 'no, i have nothing to declare']
            : [...getWorkdayConsentYesCandidates(label), 'Yes', 'yes', 'I consent', 'I Consent', 'I confirm'];
        if (await fillWorkdaySingleSelectDropdown(control, candidates, getContainerLabel(container))) {
            await wait(400);
            return isWorkdayYesNoFilled(container, answer)
                || isWorkdaySingleSelectFilled(container, candidates);
        }
    }
    return isWorkdayYesNoFilled(container, answer)
        || isWorkdaySingleSelectFilled(container, getWorkdayConsentYesCandidates(label));
}

async function clickWorkdayOption(opt) {
    if (!opt) return false;
    if (opt.getAttribute('data-automation-id') === 'menuItem' || opt.getAttribute('role') === 'option') {
        const ariaLabel = opt.getAttribute('aria-label') || '';
        const checkbox = opt.querySelector('input[type="checkbox"]')
            || opt.querySelector('[role="checkbox"]')
            || opt.querySelector('[data-automation-id="checkbox"]')
            || (opt.getAttribute('role') === 'checkbox' ? opt : null);
        if (checkbox || /\bnot checked\b/i.test(ariaLabel)) {
            debugLog(`${WD} menuItem checkbox try`, ariaLabel.slice(0, 60));
            if (checkbox && await workdayClickCheckbox(checkbox)) {
                await wait(350);
                if (isHearMenuItemChecked(opt)) {
                    debugLog(`${WD} menuItem checkbox selected`, ariaLabel.slice(0, 60));
                    return true;
                }
            }
            opt.focus();
            for (const key of [' ', 'Enter']) {
                opt.dispatchEvent(new KeyboardEvent('keydown', {
                    key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
                }));
                await wait(400);
                if (isHearMenuItemChecked(opt)) {
                    debugLog(`${WD} menuItem checkbox via keyboard`, ariaLabel.slice(0, 60));
                    return true;
                }
            }
        }
        debugLog(`${WD} menuItem click`, opt.getAttribute('aria-label'));
        const clickTargets = [
            opt.querySelector('input[type="radio"]'),
            opt.querySelector('[role="radio"]'),
            opt.querySelector('input[type="checkbox"]'),
            opt.querySelector('[role="checkbox"]'),
            opt.querySelector('[data-automation-id="promptLeafNode"]'),
            opt.querySelector('div'),
            opt,
        ].filter(Boolean);

        for (const target of clickTargets) {
            await workdayClick(target);
            await wait(350);
            if (isHearOptionSelected(opt)) {
                debugLog(`${WD} menuItem selected`, opt.getAttribute('aria-label'));
                return true;
            }
        }

        opt.focus();
        for (const key of [' ', 'Enter']) {
            opt.dispatchEvent(new KeyboardEvent('keydown', {
                key, code: key === ' ' ? 'Space' : 'Enter', bubbles: true, cancelable: true,
            }));
            await wait(400);
            if (isHearOptionSelected(opt)) {
                debugLog(`${WD} menuItem selected via keyboard`, opt.getAttribute('aria-label'));
                return true;
            }
        }

        debugLog(`${WD} menuItem after`, opt.getAttribute('aria-label'), opt.getAttribute('aria-selected'));
        // If the popup/listbox is no longer visible, the selection likely succeeded even without aria-selected update
        const anyListbox = document.querySelector('[role="listbox"][aria-expanded="true"], ul[role="listbox"]');
        if (!anyListbox || !document.body.contains(anyListbox)) {
            debugLog(`${WD} menuItem popup closed after click, treating as selected`);
            return true;
        }
        return isHearOptionSelected(opt);
    }

    await workdayClick(opt);
    return true;
}

async function selectHearOptionByKeyboard(trigger, steps) {
    trigger.click();
    await wait(1200);
    for (let i = 0; i < steps; i++) {
        document.activeElement?.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true }));
        await wait(150);
    }
    document.activeElement?.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', code: 'Space', bubbles: true }));
    await wait(500);
    await closeWorkdayPopups();
}

async function blurAwayFromHearField(container) {
    const blurTarget = [...document.querySelectorAll('[data-automation-id*="formField"] input, [data-automation-id*="formField"] textarea')]
        .find(el => isVisibleElement(el) && !container?.contains(el));
    if (blurTarget) {
        await workdayClick(blurTarget);
        await wait(400);
        return true;
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2, [data-automation-id="applicationHeader"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(400);
        return true;
    }
    return false;
}

async function commitHearSelection(container) {
    const pill = container.querySelector('[data-automation-id="multiselectInputContainer"]');
    const popup = findHearAboutPopup(container);
    const hasPopupSelection = !!popup?.querySelector('input[type="radio"]:checked')
        || !!container.querySelector('[data-automation-id="menuItem"][aria-selected="true"]')
        || !!document.querySelector('[data-automation-id="menuItem"][aria-selected="true"]');

    lockHearIfUsable(container);
    if (hasPopupSelection) {
        await blurAwayFromHearField(container);
    } else if (findVisibleWorkdayPopups().length) {
        await commitWorkdayPopup(container);
        await blurAwayFromHearField(container);
    }
    debugLog(`${WD} hear commit pill=`, pill?.innerText?.slice(0, 80), 'filled=', isMultiSelectFilled(container));
}

async function commitWorkdayPopup(container) {
    const footer = document.querySelector('[data-automation-id="applicationFooter"], [data-automation-id="pageFooter"]');
    if (footer) {
        await workdayClick(footer);
        await wait(400);
    }
    const isHear = /how did you hear/i.test(getContainerLabel(container || {}));
    const label = container?.querySelector('label');
    if (label && !(window.__wdHearFilled && isHear)) {
        await workdayClick(label);
        await wait(400);
    }
    if (findVisibleWorkdayPopups().length) {
        document.body.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
        await wait(400);
    }
}

const HEAR_BLOCKED_TOP_LEVEL = new Set([
    'campus event',
    'temp to regular',
    'professional event',
    'job fair',
    'military',
    'recruitment agency',
    'university',
]);

async function dismissHearDropdown(container) {
    if (window.__wdHearFilled) {
        await blurAwayFromHearField(container);
        return;
    }
    await commitWorkdayPopup(container);
    await wait(300);
    const label = container?.querySelector('label');
    if (label) {
        await workdayClick(label);
        await wait(300);
    }
    if (findHearPopups(container).length) {
        await blurAwayFromHearField(container);
        await wait(300);
        if (findHearPopups(container).length) {
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            await wait(350);
        }
    }
}

async function closeOtherWorkdayPopupsWithoutEscape() {
    const footer = document.querySelector('[data-automation-id="applicationFooter"], [data-automation-id="pageFooter"]');
    if (footer) {
        await workdayClick(footer);
        await wait(300);
    }
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2, [data-automation-id="applicationHeader"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(300);
    }
}

function isWorkdayEntryEditModal(modal = getVisibleModal()) {
    if (!modal || !isVisibleElement(modal)) return false;
    const fields = modal.querySelectorAll('[data-automation-id*="formField"]');
    if (fields.length >= 2) return true;
    const text = (modal.innerText || '').slice(0, 500);
    return /job title|work experience|education|certification|language|school|university|employer|company/i.test(text);
}

async function saveWorkdayEntryModal() {
    const modal = getVisibleModal();
    if (!modal || !isWorkdayEntryEditModal(modal)) return false;
    const saved = await clickModalActionButton(/^save$|^done$|^ok$|^apply$|^continue$/i);
    if (saved) {
        debugLog(`${WD} saved entry modal`);
        await wait(2500);
        return true;
    }
    const primary = [...modal.querySelectorAll('button, [role="button"]')].find(b => {
        const text = (b.innerText || '').trim();
        return /^(save|done|ok|apply|continue)$/i.test(text) && isVisibleElement(b) && !b.disabled;
    });
    if (primary) {
        debugLog(`${WD} saved entry modal via primary`, (primary.innerText || '').trim());
        await workdayClick(primary);
        await wait(2500);
        return true;
    }
    return false;
}

async function closeWorkdayPopups(reason = 'escape-all') {
    if (isWorkdayEntryEditModal()) return;
    const hearContainer = findHearAboutContainer();
    if (window.__wdHearFilled && hearContainer) {
        await blurAwayFromHearField(hearContainer);
        await closeOtherWorkdayPopupsWithoutEscape();
        // Hear selection is already committed as a pill — if the hear listbox is still
        // globally visible, Escape once so City/State opens do not scan ["Indeed"] as
        // their option list (bah.wd1 information City).
        if (findHearPopups(hearContainer).length
            || [...document.querySelectorAll('[role="listbox"]:not([hidden]), [data-automation-id*="promptContainer"]')]
                .some((el) => isVisibleElement(el) && /indeed|linkedin|job board|how did you hear/i.test(el.innerText || ''))) {
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            await wait(300);
        }
        return;
    }
    const openKeys = Object.keys(wdDropdownOpenAt);
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await wait(300);
    // If a listbox is still open, click the page title to force-close it
    if (document.querySelector('[role="listbox"]:not([hidden]), [data-automation-id*="promptContainer"]')) {
        const title = document.querySelector('[data-automation-id="applyFlowPageTitle"], h1, h2');
        if (title) title.click();
        await wait(300);
    }
    for (const key of openKeys) {
        trackWorkdayDropdownClose(key, reason);
    }
}

function isVisibleElement(el) {
    if (!el) return false;
    const style = window.getComputedStyle(el);
    if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
    const rect = el.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
}

function findHearAboutContainer() {
    return getWorkdayFieldContainers().find(c => /how did you hear/i.test(getContainerLabel(c))) || null;
}

function isHearFieldElement(el) {
    if (!el) return false;
    const container = el.closest?.('[data-automation-id*="formField"]');
    if (!container) return false;
    return /how did you hear/i.test(getContainerLabel(container));
}

function isHearInteractionBlocked(el) {
    if (!isHearFieldElement(el)) return false;
    const container = el?.closest?.('[data-automation-id*="formField"]') || findHearAboutContainer();
    if (!isHearFillDone(container)) return false;
    return true;
}

function lockHearIfUsable(container) {
    if (container && hasExplicitHearSelection(container)) {
        markHearFilled(container);
        return true;
    }
    return window.__wdHearFilled;
}

function isPhoneCodeOptionText(text) {
    const t = String(text || '').trim();
    return /\(\+\d{1,4}\)\s*$/.test(t) || /^\d+\.\s*.+\(\+\d{1,4}\)/.test(t);
}

function isPhoneCodePopup(popup) {
    if (!popup) return false;
    const options = getUniqueHearOptions(popup).slice(0, 6);
    if (!options.length) return false;
    const phoneLike = options.filter(o => isPhoneCodeOptionText(o.text)).length;
    return phoneLike >= Math.max(2, Math.ceil(options.length * 0.5));
}

function findHearAboutPopup(container) {
    if (!container) return null;
    const popups = findHearPopups(container);
    return popups[0] || null;
}

function findVisibleWorkdayPopups() {
    return [...document.querySelectorAll('[data-automation-id="activeListContainer"], [data-automation-id="wd-MenuList"], [data-automation-id="promptOptions"], ul[role="listbox"], div[role="listbox"]')]
        .filter(isVisibleElement);
}

function findHearPopups(container) {
    const label = 'how did you hear';
    const rect = container?.getBoundingClientRect();
    return findVisibleWorkdayPopups()
        .filter(p => !isPhoneCodePopup(p) && !isWrongPopupForField(p, label))
        .filter(p => {
            if (!rect) return true;
            const pr = p.getBoundingClientRect();
            return pr.top >= rect.top - 80
                && pr.top <= rect.bottom + 700
                && pr.left >= rect.left - 120
                && pr.left <= rect.right + 900;
        });
}

function getAllHearMenuItems(container) {
    const rect = container?.getBoundingClientRect();
    const seen = new Set();
    const result = [];
    for (const el of document.querySelectorAll('[data-automation-id="menuItem"], [role="option"], [role="treeitem"]')) {
        if (!isVisibleElement(el)) continue;
        const text = (el.getAttribute('aria-label') || el.innerText || el.textContent || '').trim().replace(/\s+/g, ' ');
        if (!text || text.length > 120 || seen.has(text)) continue;
        if (rect) {
            const r = el.getBoundingClientRect();
            if (r.top < rect.top - 80 || r.top > rect.bottom + 700) continue;
            if (r.left < rect.left - 120 || r.left > rect.right + 900) continue;
        }
        seen.add(text);
        result.push({ el, text });
    }
    return result;
}

function isHearAboutPopup(popup) {
    const text = (popup.innerText || popup.textContent || '').toLowerCase();
    if (/campus event|company web site|job board|professional association|social network|temp to regular/i.test(text)) return true;
    if (/linkedin|indeed|glassdoor|monster|careerbuilder|job board|internet|social media|employee referral|career fair|website/i.test(text)) return true;
    if (/united states.*\(\+\d\)|\(\+\d{3}\)/i.test(text) && !/linkedin|internet|job|indeed/i.test(text)) return false;
    return /referral|newspaper|agency|other|hire veterans/i.test(text);
}

const HEAR_OPTION_PREFERRED = [
    'Company Web Site',
    'Job Board',
    'Social Network',
    'Professional Association',
    'Other',
    'Internet',
    'LinkedIn',
];

const HEAR_SUB_OPTION_PREFERRED = [
    'Indeed',
    'Glassdoor',
    'Another online job board',
    'Monster',
    'CareerBuilder',
    'Career Builder',
    'ZipRecruiter',
    'SimplyHired',
    'Other',
    'Google',
    'Company Website',
    'Johnson',
    'J&J',
    'Website',
    'Internet',
    'Xing',
    'LinkedIn',
];

function isHearParentCategory(text) {
    const t = normalizeHearOptionText(text);
    return /^(company web site|company website|job board|job boards|social network|social media|campus event|professional association|professional event)$/.test(t);
}

function isHearExpandableParent(text) {
    return isHearParentCategory(text) || isHearTreeParentOption(text);
}

function isHearTreeParentOption(text) {
    const t = normalizeHearOptionText(text);
    if (!t || isNeverHearOption(t)) return false;
    if (HEAR_BLOCKED_TOP_LEVEL.has(t)) return false;
    if (isHearParentCategory(text)) return true;
    if (/^(linkedin|indeed|glassdoor|monster|careerbuilder|career builder|ziprecruiter|simplyhired)$/i.test(t)) return false;
    return /college|university|alumni|disability|military|veteran|job board|referral|agency|campus|fair|newspaper|internet|social|website|web site|employee|source|event|network|media|other|professional|organization|contingent|external|internal|career|corporate|advertising|headhunt|broadcast|sites?$/i.test(t);
}

function isHearMenuItemCheckboxLeaf(optEl) {
    if (!optEl || optEl.getAttribute('data-automation-id') !== 'menuItem') return false;
    if (optEl.querySelector('[data-automation-id="promptIcon"]')) return false;
    if (optEl.querySelector('[aria-haspopup="true"]')) return false;
    if (optEl.getAttribute('aria-expanded') === 'false') return false;
    if (optEl.querySelector('input[type="checkbox"], input[type="radio"], [role="checkbox"], [role="radio"]')) return true;
    const label = optEl.getAttribute('aria-label') || '';
    return /\bnot checked\b/i.test(label) || /\bchecked\b/i.test(label);
}

function isHearMenuItemChecked(el) {
    if (!el) return false;
    const label = el.getAttribute('aria-label') || '';
    if (/\bnot checked\b/i.test(label)) return false;
    if (/\bchecked\b/i.test(label)) return true;
    if (el.getAttribute('aria-checked') === 'true') return true;
    return isHearOptionSelected(el);
}

function isHearCheckboxTreeDropdown(popup) {
    if (!popup) return false;
    const items = [...popup.querySelectorAll('[data-automation-id="menuItem"]')].filter(isVisibleElement);
    const withState = items.filter(i => /\b(not )?checked\b/i.test(i.getAttribute('aria-label') || ''));
    return withState.length >= 2;
}

function getHearCheckboxRows(container) {
    const byKey = new Map();
    for (const item of getAllHearMenuItems(container)) {
        const el = item.el;
        if (el.getAttribute('data-automation-id') !== 'menuItem' && el.getAttribute('role') !== 'treeitem') continue;
        const ariaLabel = el.getAttribute('aria-label') || item.text || '';
        const text = hearOptionBaseName(ariaLabel || item.text);
        if (!text) continue;
        const checkbox = el.querySelector('input[type="checkbox"], [role="checkbox"], [data-automation-id="checkbox"]')
            || (el.getAttribute('role') === 'checkbox' ? el : null);
        const row = { el, checkbox, text };
        const existing = byKey.get(text);
        const preferNew = /\bnot checked\b/i.test(ariaLabel)
            && !/\bnot checked\b/i.test(existing?.el?.getAttribute('aria-label') || '');
        if (!existing || preferNew) byKey.set(text, row);
    }
    return [...byKey.values()];
}

async function clickHearCheckboxTarget(el) {
    if (!el) return false;
    workdayScrollToTarget(el, 120);
    const rect = el.getBoundingClientRect();
    for (const xOff of [14, 28, rect.width / 2]) {
        const x = rect.left + Math.min(xOff, Math.max(8, rect.width - 4));
        const y = rect.top + rect.height / 2;
        const target = document.elementFromPoint(x, y);
        if (!target) continue;
        const opts = { bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y };
        target.dispatchEvent(new PointerEvent('pointerdown', opts));
        target.dispatchEvent(new MouseEvent('mousedown', opts));
        if (typeof target.click === 'function') target.click();
        target.dispatchEvent(new MouseEvent('mouseup', opts));
        target.dispatchEvent(new PointerEvent('pointerup', opts));
        await wait(250);
        if (isHearMenuItemChecked(el)) return true;
    }
    el.click();
    await wait(250);
    return isHearMenuItemChecked(el);
}

async function selectHearCheckboxViaKeyboard(container, preferredText) {
    const pillBefore = getHearPillText(container);
    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const rows = getHearCheckboxRows(container);
    if (!rows.length) return false;
    const idx = Math.max(0, rows.findIndex(r => hearOptionMatchesPreferred(r.text, preferredText)));
    const row = rows[idx];
    if (!row) return false;
    debugLog(`${WD} hear checkbox keyboard`, preferredText, '->', row.text);
    row.el.focus();
    await wait(200);
    for (const key of [' ', 'Enter']) {
        row.el.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        row.el.dispatchEvent(new KeyboardEvent('keyup', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(500);
        if (isHearMenuItemChecked(row.el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    return false;
}

async function activateHearCheckboxRow(container, row) {
    if (!row?.el) return false;
    const pillBefore = getHearPillText(container);
    const { el, checkbox } = row;
    debugLog(`${WD} hear checkbox activate`, row.text);

    if (await clickHearCheckboxTarget(el)) {
        if (hasHearSelectionChanged(container, pillBefore)) return true;
    }

    if (checkbox && await workdayClickCheckbox(checkbox)) {
        await wait(350);
        if (isHearMenuItemChecked(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }

    const targets = [
        el.querySelector('[data-automation-id="checkbox"]'),
        el.querySelector('[role="checkbox"]'),
        el.querySelector('label'),
        el.querySelector('[data-automation-id="promptOption"]'),
        el,
    ].filter(Boolean);

    for (const target of targets) {
        await workdayClick(target);
        await wait(350);
        if (isHearMenuItemChecked(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }

    el.focus();
    await wait(150);
    for (const key of [' ', 'Enter']) {
        el.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        el.dispatchEvent(new KeyboardEvent('keyup', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(400);
        if (isHearMenuItemChecked(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    const popup = findHearAboutPopup(container);
    if (popup && [...popup.querySelectorAll('[data-automation-id="menuItem"]')].some(isHearMenuItemChecked)) {
        return true;
    }
    return isHearMenuItemChecked(el) || hasHearSelectionChanged(container, pillBefore);
}

async function ensureHearDropdownExpanded(container) {
    if (!container) return false;
    const head = getHearPillText(container).split('\n')[0].trim().toLowerCase();
    if (findHearAboutPopup(container)) return true;
    if (!/^(expanded|minimized)$/i.test(head) && !/0 items selected/i.test(head)) return Boolean(findHearAboutPopup(container));
    const trigger = getWorkdayDropdownTrigger(container);
    const ms = container.querySelector('[data-automation-id="multiselectInputContainer"]');
    if (ms) await workdayClick(ms);
    else if (trigger) await workdayClick(trigger);
    await wait(1000);
    return Boolean(findHearAboutPopup(container));
}

async function fillHearCheckboxTreeDropdown(container) {
    await ensureHearDropdownExpanded(container);
    const popup = findHearAboutPopup(container);
    if (!popup) return false;

    for (const term of ['Catalent Website', 'LinkedIn', 'Indeed', 'Internet', 'Other']) {
        if (await tryHearSearchInOpenDropdown(container, term)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }

    const rows = getHearCheckboxRows(container);
    if (!rows.length) return false;
    debugLog(`${WD} hear checkbox rows`, rows.map(r => r.text).slice(0, 8));

    const preferred = [
        'Catalent Website', 'Company Website', 'Company Web Site', 'Internet', 'LinkedIn',
        'Indeed', 'Other', 'Advertisement', 'Career Fairs and Events', 'Internet Job Site',
    ];
    for (const pref of preferred) {
        if (await selectHearCheckboxViaKeyboard(container, pref)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }
    for (const pref of preferred) {
        const row = rows.find(r => hearOptionMatchesPreferred(r.text, pref) && !isHearMenuItemChecked(r.el));
        if (row && await activateHearCheckboxRow(container, row)) {
            await finalizeHearSelection(container);
            return isHearSelectionUsable(container);
        }
    }
    for (const row of rows) {
        if (HEAR_BLOCKED_TOP_LEVEL.has(row.text) || isHearMenuItemChecked(row.el)) continue;
        if (hearOptionHasSubmenu(row.el) || isHearTreeParentOption(row.text)) {
            if (await expandHearParentByOption(container, { el: row.el, text: row.text })) {
                const leaves = getHearCheckboxRows(container)
                    .filter(r => !isHearMenuItemChecked(r.el) && !hearOptionHasSubmenu(r.el));
                for (const leaf of leaves.slice(0, 6)) {
                    if (await activateHearCheckboxRow(container, leaf)) {
                        await finalizeHearSelection(container);
                        if (isHearSelectionUsable(container)) return true;
                    }
                }
                await navigateHearBackToTop(container);
            }
            continue;
        }
        if (await activateHearCheckboxRow(container, row)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }
    return false;
}

function hearRootPriority(opt) {
    const t = hearOptionBaseName(opt?.text || opt?.el?.innerText || '');
    if (/website|internet|linkedin|indeed|glassdoor/i.test(t)) return 10;
    if (/catalent|company web/i.test(t)) return 9;
    if (/other/i.test(t)) return 5;
    if (/advertisement|career fair/i.test(t)) return 1;
    return 3;
}

function isLikelyHearTreeRootParent(opt) {
    if (!opt?.text) return false;
    if (isHearLeafStyleOption(opt)) return false;
    if (isHearMenuItemCheckboxLeaf(opt.el)) return false;
    const t = hearOptionBaseName(opt.text);
    if (!t || /^select one$/i.test(t)) return false;
    if (hearOptionHasSubmenu(opt.el)) return true;
    if (isHearTreeParentOption(opt.text) || HEAR_TOP_LEVEL_OPTIONS.has(t)) return true;
    if (/\bnot checked\b/i.test(opt.text) && isHearTreeParentOption(opt.text.replace(/\s+not checked/i, ''))) return true;
    return false;
}

function isClearlyHearRootLeaf(opt) {
    if (!opt?.text || isLikelyHearTreeRootParent(opt)) return false;
    const t = hearOptionBaseName(opt.text);
    return /^(linkedin|indeed|glassdoor|employee referral|company web site|company website|internet|other|referral|agency|newspaper)$/i.test(t)
        || isRecognizedHearSubOption(opt.text);
}

function isHearTreeStyleDropdown(popup) {
    if (!popup) return false;
    const menuItems = [...popup.querySelectorAll('[data-automation-id="menuItem"]')].filter(isVisibleElement);
    if (menuItems.length >= 2) return true;
    const options = getSingleSelectDropdownOptions(popup, false);
    if (!options.length) return false;
    const withDataValue = options.filter(o => o.getAttribute?.('data-value')).length;
    if (withDataValue >= Math.max(2, Math.ceil(options.length * 0.4))) return false;
    const texts = options.map(o => normalizeHearOptionText(optionText(o))).filter(Boolean);
    if (texts.length >= 3 && texts.length !== new Set(texts).size) return true;
    const parentLike = texts.filter(t => isHearTreeParentOption(t) || HEAR_TOP_LEVEL_OPTIONS.has(t)).length;
    return parentLike >= 3;
}

function isHearLeafStyleOption(opt) {
    if (!opt?.el) return false;
    if (opt.el.getAttribute?.('data-value')) return true;
    if (opt.el.closest?.('li[data-value]')) return true;
    const t = hearOptionBaseName(opt.text);
    return /^(linkedin|indeed|glassdoor|monster|careerbuilder|career builder|ziprecruiter|simplyhired)\b/i.test(t)
        || /\b(linkedin|indeed|glassdoor)\b/i.test(t);
}

function isHearFieldStuckOpen(container) {
    if (!container) return false;
    const head = getHearPillText(container).split('\n')[0].trim().toLowerCase();
    if (/^(expanded|minimized)$/.test(head) && !findHearAboutPopup(container)) return true;
    if (/0 items selected/i.test(head) && /expanded|minimized/i.test(getHearPillText(container).toLowerCase())) return true;
    return false;
}

async function recoverStuckHearField(container, trigger) {
    if (!container || !isHearFieldStuckOpen(container)) return !isHearFieldStuckOpen(container);
    debugLog(`${WD} hear recover stuck`, getHearPillText(container).slice(0, 80));
    for (let i = 0; i < 4; i++) {
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await wait(250);
    }
    await blurAwayFromHearField(container);
    await wait(400);
    if (trigger) {
        await workdayClick(trigger);
        await wait(500);
    }
    const label = container.querySelector('label');
    if (label) {
        await workdayClick(label);
        await wait(400);
    }
    resetWorkdayDropdownOpenCount('how did you hear about us?');
    resetWorkdayDropdownOpenCount('how did you hear');
    await wait(400);
    return !isHearFieldStuckOpen(container);
}

function isHearSelectableLeaf(text) {
    const t = normalizeHearOptionText(text);
    if (isHearExpandableParent(text)) return false;
    if (isRecognizedHearSubOption(text)) return true;
    if (/^(linkedin|indeed|glassdoor|other|internet|xing|google|monster|careerbuilder|employee referral|referral|newspaper|agency)$/i.test(t)) return true;
    return !HEAR_TOP_LEVEL_OPTIONS.has(t);
}

function countVisibleHearRootCategories(container) {
    const popup = findHearAboutPopup(container);
    if (!popup) return 0;
    const seen = new Set();
    let count = 0;
    for (const o of getUniqueHearOptions(popup)) {
        if (isPhoneCodeOptionText(o.text)) continue;
        const t = normalizeHearOptionText(o.text);
        if (seen.has(t)) continue;
        const isRoot = HEAR_TOP_LEVEL_OPTIONS.has(t)
            || isHearParentCategory(o.text)
            || /^(job fair|military|recruitment agency|referral|university)$/.test(t);
        if (!isRoot) continue;
        seen.add(t);
        count += 1;
    }
    return count;
}

function getHearSubmenuContext(container) {
    const popup = findHearAboutPopup(container);
    if (!popup) return null;

    // Several root categories visible (Company Website + Job Boards + …) = top level, not a submenu.
    if (countVisibleHearRootCategories(container) >= 2) return null;

    const text = (popup.innerText || popup.textContent || '').replace(/\s+/g, ' ').toLowerCase();
    if (/indeed|glassdoor|linkedin|xing|another online job board/i.test(text)) return 'job_board';

    if (findHearBackButton(container)) {
        if (/job boards?/i.test(text)) return 'job_board';
        if (/company website/i.test(text)) return 'company_website';
    }

    return null;
}

function isInsideHearJobBoardSubmenu(container) {
    return getHearSubmenuContext(container) === 'job_board';
}

function findHearBackButton(container) {
    const popup = findHearAboutPopup(container);
    if (!popup) return null;
    return popup.querySelector('[data-automation-id="promptBackButton"], [data-automation-id*="backButton"], button[aria-label*="back" i]')
        || [...popup.querySelectorAll('button, [role="button"]')].find(el => {
            const label = (el.getAttribute('aria-label') || el.innerText || '').trim();
            return /^back$/i.test(label) || label === '←' || label === '‹';
        })
        || null;
}

async function navigateHearBackToTop(container) {
    for (let i = 0; i < 3; i++) {
        if (!getHearSubmenuContext(container)) return true;
        debugLog(`${WD} hear navigate back`, getHearSubmenuContext(container), 'try=', i + 1);
        const back = findHearBackButton(container);
        if (back) {
            await workdayClick(back);
            await wait(500);
            continue;
        }
        await resetHearToTopLevel(container);
        await wait(300);
    }
    return !getHearSubmenuContext(container);
}

async function ensureHearAtTopLevel(container) {
    const ctx = getHearSubmenuContext(container);
    if (!ctx) return true;
    if (ctx === 'company_website') {
        debugLog(`${WD} hear wrong submenu — company website, going back`);
        return navigateHearBackToTop(container);
    }
    return true;
}

function getHearSubmenuLeafCandidates(container) {
    return getAllHearMenuItems(container).filter(o => {
        if (isHearBackRow(o.el)) return false;
        const t = normalizeHearOptionText(o.text);
        if (isHearExpandableParent(o.text)) return false;
        if (/^company web/.test(t)) return false;
        return isHearSelectableLeaf(o.text)
            || /^another online/i.test(t)
            || HEAR_SUB_OPTION_PREFERRED.some(name => hearOptionMatchesPreferred(o.text, name));
    });
}

async function selectHearSubmenuLeaf(container, leafCandidates = HEAR_SUB_OPTION_PREFERRED) {
    if (await tryForcePickAnyHearOption(container)) return true;

    const subs = getHearSubmenuLeafCandidates(container);
    if (!subs.length) {
        debugLog(`${WD} hear submenu no leaf candidates`);
        return false;
    }
    debugLog(`${WD} hear submenu leaves`, subs.map(o => o.text).slice(0, 10));

    for (const pref of leafCandidates) {
        const leaf = subs.find(o => hearOptionMatchesPreferred(o.text, pref) && !isUnwantedHearSubOption(o.text))
            || (pref === 'Indeed' ? subs.find(o => /indeed/i.test(normalizeHearOptionText(o.text))) : null)
            || (pref === 'LinkedIn' ? subs.find(o => /linkedin/i.test(normalizeHearOptionText(o.text)) && !isHearBackRow(o.el)) : null);
        if (!leaf) continue;

        const pillBefore = getHearPillText(container);
        debugLog(`${WD} hear submenu pick`, pref, '->', leaf.text.slice(0, 60));
        if (await clickHearRadioOrLeaf(container, leaf)) {
            await wait(500);
            if (isHearOptionSelected(leaf.el) || hasHearSelectionChanged(container, pillBefore) || isHearSelectionUsable(container)) {
                return true;
            }
        }
    }

    const fallback = subs.find(o => isRecognizedHearSubOption(o.text)) || subs[0];
    if (fallback) {
        debugLog(`${WD} hear submenu fallback`, fallback.text.slice(0, 60));
        return clickHearRadioOrLeaf(container, fallback);
    }
    return false;
}

const HEAR_SUBMENU_PARENTS = [
    'LinkedIn',
    'Indeed',
    'Glassdoor',
    'Job Boards',
    'Job Board',
    'Social Media',
    'Social Network',
    'Internet',
    'Company Web Site',
    'Company Website',
];

function isHearBackRow(el) {
    if (!el) return false;
    if (el.matches?.('[data-automation-id="promptBackButton"], [data-automation-id*="backButton"]')) return true;
    if (el.closest?.('[data-automation-id="promptBackButton"], [data-automation-id*="backButton"]')) return true;
    const automationId = el.getAttribute?.('data-automation-id') || '';
    if (/back/i.test(automationId)) return true;
    const hasInput = el.querySelector?.('input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"]');
    if (hasInput) return false;
    const label = (el.getAttribute('aria-label') || el.innerText || el.textContent || '').trim();
    if (/^[←‹]|^back$/i.test(label)) return true;
    if (el.querySelector?.('[data-automation-id="promptIcon"]') && !hasInput) return true;
    return false;
}

function getHearRadioRows(root) {
    const scope = root || document;
    const seen = new Set();
    const rows = [];
    for (const radio of scope.querySelectorAll('input[type="radio"], [role="radio"]')) {
        if (!isVisibleElement(radio)) continue;
        const el = radio.closest('[data-automation-id="menuItem"], [role="option"], [role="treeitem"], li, label')
            || radio.parentElement;
        if (!el || isHearBackRow(el)) continue;
        let text = radio.getAttribute('aria-label') || el?.getAttribute?.('aria-label') || el?.innerText || '';
        text = text.replace(/\s+not checked$/i, '').replace(/\s+checked$/i, '').trim();
        const key = normalizeHearOptionText(text);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        rows.push({ el, radio, text: key });
    }
    return rows;
}

function isHearRadioDropdown(container) {
    const popup = findHearAboutPopup(container);
    return Boolean(popup?.querySelector('input[type="radio"], [role="radio"]'));
}

function isHearRadioRowSelected(container, row) {
    if (row?.radio?.checked) return true;
    if (row?.radio?.getAttribute?.('aria-checked') === 'true') return true;
    const label = row?.el?.getAttribute('aria-label') || row?.radio?.getAttribute?.('aria-label') || '';
    return /\bchecked\b/i.test(label) && !/\bnot checked\b/i.test(label);
}

async function activateHearRadioRow(container, row) {
    if (!row?.radio) return false;
    const pillBefore = getHearPillText(container);
    const { el, radio } = row;
    debugLog(`${WD} hear radio activate`, row.text);

    const labelFor = radio.id ? document.querySelector(`label[for="${radio.id}"]`) : null;
    for (const target of [radio, labelFor, el?.querySelector('label'), el?.querySelector('[data-automation-id="promptOption"]'), el, el?.querySelector('[data-automation-id="promptLeafNode"]')]) {
        if (!target) continue;
        await workdayClick(target);
        await wait(350);
        if (isHearRadioRowSelected(container, row) || hasHearSelectionChanged(container, pillBefore)) return true;
    }

    (el || radio).focus?.();
    await wait(150);
    for (const key of [' ', 'Enter']) {
        (document.activeElement || radio).dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(300);
        if (isHearRadioRowSelected(container, row) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    return isHearRadioRowSelected(container, row) || hasHearSelectionChanged(container, pillBefore);
}

async function selectHearRadioInPopup(container, preferred = ['LinkedIn', 'Indeed', 'Glassdoor', 'Other', 'Internet', 'Job Board']) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const rows = getHearRadioRows(popup);
    debugLog(`${WD} hear radio rows`, rows.map(r => `${r.text}${r.radio.checked ? ' (checked)' : ''}`));
    if (!rows.length) return false;

    for (const pref of preferred) {
        const row = rows.find(r => hearOptionMatchesPreferred(r.text, pref) && !r.radio.checked);
        if (row && await activateHearRadioRow(container, row)) return true;
    }
    const any = rows.find(r => !r.radio.checked);
    return Boolean(any && await activateHearRadioRow(container, any));
}

async function enterHearCategoryForRadio(container, name) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const options = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    const match = options.find(o => hearOptionMatchesCategory(o.text, name));
    if (!match) return false;
    debugLog(`${WD} hear radio enter category`, name, match.text.slice(0, 60));
    const row = match.el.querySelector('[data-automation-id="promptLeafNode"]')
        || match.el.querySelector('[data-automation-id="promptOption"]')
        || match.el;
    await workdayClick(row);
    await wait(700);
    const nextPopup = findHearAboutPopup(container);
    return Boolean(nextPopup?.querySelector('input[type="radio"], [role="radio"]') || findHearBackButton(container));
}

async function ensureHearRadioCommitted(container) {
    await commitHearSelection(container);
    await wait(500);
    if (isHearSelectionUsable(container)) return true;
    const pill = getHearPillText(container);
    const sel = getHearSelectedLabel(pill);
    if (sel && !/^select one$/i.test(sel)) return true;
    const prompt = container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText?.trim();
    if (prompt && !/^select one$/i.test(prompt)) return true;
    return false;
}

async function fillHearRadioDropdown(container) {
    const popup = findHearAboutPopup(container);
    if (popup && (findHearBackButton(container) || countVisibleHearRootCategories(container) < 2)) {
        if (await pickAnyHearLeafInSubmenu(container)) {
            debugLog(`${WD} hear radio filled pick-any in submenu`, getHearPillText(container).slice(0, 60));
            return true;
        }
    }

    const categories = [
        'LinkedIn', 'Indeed', 'Job Board', 'Job Boards', 'Social Media',
        'Social Network', 'Internet', 'Other', 'Company Web Site', 'Glassdoor',
    ];

    if (await selectHearRadioInPopup(container)) {
        await finalizeHearSelection(container);
        if (await ensureHearRadioCommitted(container)) {
            debugLog(`${WD} hear radio filled in open popup`, getHearPillText(container).slice(0, 60));
            return true;
        }
    }

    for (const cat of categories) {
        if (!findHearAboutPopup(container)) break;

        if (findHearBackButton(container)) {
            if (await pickAnyHearLeafInSubmenu(container)) {
                await finalizeHearSelection(container);
                if (await ensureHearRadioCommitted(container)) return true;
            }
            await navigateHearBackToTop(container);
        }

        const hasRadios = findHearAboutPopup(container)?.querySelector('input[type="radio"], [role="radio"]');
        if (!hasRadios || !findHearBackButton(container)) {
            if (!await enterHearCategoryForRadio(container, cat)) continue;
            if (await pickAnyHearLeafInSubmenu(container)) {
                await finalizeHearSelection(container);
                if (await ensureHearRadioCommitted(container)) {
                    debugLog(`${WD} hear radio filled pick-any after category`, cat, getHearPillText(container).slice(0, 60));
                    return true;
                }
            }
        }
        if (await selectHearRadioInPopup(container)) {
            await finalizeHearSelection(container);
            if (await ensureHearRadioCommitted(container)) {
                debugLog(`${WD} hear radio filled via category`, cat, getHearPillText(container).slice(0, 60));
                return true;
            }
        }
        if (findHearBackButton(container)) {
            await navigateHearBackToTop(container);
        }
    }

    const popupEnd = findHearAboutPopup(container);
    if (popupEnd) {
        for (const row of getHearRadioRows(popupEnd)) {
            if (await activateHearRadioRow(container, row)) {
                await finalizeHearSelection(container);
                if (await ensureHearRadioCommitted(container)) return true;
            }
        }
    }
    return false;
}

async function tryPickAnyHearFromTopLevel(container, { maxCategories = HEAR_FILL_MAX_PARENT_TRIES } = {}) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const tops = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    let entered = 0;
    for (const opt of tops) {
        if (isHearFillTimedOut() || entered >= maxCategories) break;
        const name = hearOptionBaseName(opt.text);
        if (!name || HEAR_BLOCKED_TOP_LEVEL.has(name)) continue;
        if (!hearOptionHasSubmenu(opt.el) && !isHearParentCategory(opt.text)) {
            if (await clickHearRadioOrLeaf(container, opt)) {
                await finalizeHearSelection(container);
                if (isHearSelectionUsable(container)) return true;
            }
            continue;
        }
        entered += 1;
        debugLog(`${WD} hear top-level enter for pick-any`, opt.text.slice(0, 60));
        const row = opt.el.querySelector('[data-automation-id="promptLeafNode"]')
            || opt.el.querySelector('[data-automation-id="promptOption"]')
            || opt.el;
        await workdayClick(row);
        await wait(700);
        if (await pickAnyHearLeafInSubmenu(container)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
        if (findHearBackButton(container)) {
            await navigateHearBackToTop(container);
        }
    }
    return false;
}

function getHearPickableLeaves(container, { allowUnknown = false } = {}) {
    const atTopLevel = countVisibleHearRootCategories(container) >= 2;
    return getAllHearMenuItems(container)
        .filter(o => {
            if (isHearBackRow(o.el)) return false;
            if (atTopLevel && (isHearExpandableParent(o.text) || hearOptionHasSubmenu(o.el) || isHearParentCategory(o.text))) {
                return false;
            }
            if (!allowUnknown && (isNeverHearOption(o.text) || isBlockedHearSubOption(o.text))) return false;
            if (isHearExpandableParent(o.text) && hearOptionHasSubmenu(o.el)) return false;
            const hasInput = o.el.querySelector('input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"]');
            if (hasInput) return true;
            if (allowUnknown && !isHearExpandableParent(o.text)) return true;
            return isHearSelectableLeaf(o.text) || isFallbackHearOption(o.text) || isRecognizedHearSubOption(o.text);
        })
        .sort((a, b) => {
            const score = (o) => {
                if (o.el.querySelector('input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"]')) return 0;
                if (isRecognizedHearSubOption(o.text)) return 1;
                return 2;
            };
            return score(a) - score(b);
        });
}

async function pickAnyHearLeafInSubmenu(container) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;

    const radioRows = getHearRadioRows(popup);
    debugLog(`${WD} hear pick-any radios`, radioRows.map(r => r.text).slice(0, 8));
    for (const row of radioRows) {
        if (isHearFillTimedOut()) break;
        if (await activateHearRadioRow(container, row)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }

    const leaves = getHearPickableLeaves(container, { allowUnknown: true });
    debugLog(`${WD} hear pick-any leaves`, leaves.map(o => o.text).slice(0, 8));
    for (const leaf of leaves) {
        if (isHearFillTimedOut()) break;
        debugLog(`${WD} hear pick-any try`, leaf.text.slice(0, 60));
        if (await clickHearRadioOrLeaf(container, leaf)) {
            await wait(500);
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }
    return false;
}

async function clickHearRadioOrLeaf(container, opt) {
    const el = opt?.el || opt;
    if (!el) return false;
    const pillBefore = getHearPillText(container);
    const checkbox = el.querySelector('input[type="checkbox"]');
    if (checkbox) {
        await workdayClick(checkbox);
        await wait(400);
        if (checkbox.checked || isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
        checkbox.click();
        await wait(400);
        if (checkbox.checked || isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    const roleCheckbox = el.querySelector('[role="checkbox"]');
    if (roleCheckbox) {
        await workdayClick(roleCheckbox);
        await wait(400);
        if (isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    const radio = el.querySelector('input[type="radio"]');
    if (radio) {
        await workdayClick(radio);
        await wait(400);
        if (radio.checked || isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
        radio.click();
        await wait(400);
        if (radio.checked || isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    const roleRadio = el.querySelector('[role="radio"]');
    if (roleRadio) {
        await workdayClick(roleRadio);
        await wait(400);
        if (isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }
    if (await clickHearMenuItem(el, container)) return true;
    return clickWorkdayOption(el);
}

async function tryForcePickAnyHearOption(container) {
    const leaves = getHearPickableLeaves(container, { allowUnknown: true });
    debugLog(`${WD} hear force pick`, leaves.map(o => o.text).slice(0, 10));
    if (!leaves.length) return false;

    for (const leaf of leaves) {
        debugLog(`${WD} hear force try`, leaf.text.slice(0, 60));
        if (await clickHearRadioOrLeaf(container, leaf)) {
            await wait(500);
            if (isHearSelectionUsable(container)) {
                await finalizeHearSelection(container);
                return true;
            }
        }
    }

    for (const leaf of leaves) {
        debugLog(`${WD} hear force last resort`, leaf.text.slice(0, 60));
        if (await clickHearRadioOrLeaf(container, leaf)) {
            await wait(500);
            await finalizeHearSelection(container);
            return isHearSelectionUsable(container);
        }
    }
    return false;
}

async function trySelectHearSubmenuPath(container) {
    if (isInsideHearJobBoardSubmenu(container) || findHearBackButton(container)) {
        debugLog(`${WD} hear already inside submenu`);
        if (await pickAnyHearLeafInSubmenu(container)) {
            return isHearSelectionUsable(container);
        }
        if (await tryForcePickAnyHearOption(container)) {
            return isHearSelectionUsable(container);
        }
        if (await selectHearSubmenuLeaf(container)) {
            await finalizeHearSelection(container);
            return isHearSelectionUsable(container);
        }
        return false;
    }

    for (const parentName of HEAR_SUBMENU_PARENTS) {
        if (!await expandHearParent(container, parentName)) continue;

        if (await tryForcePickAnyHearOption(container)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) {
                debugLog(`${WD} hear submenu force pick ok`, parentName);
                return true;
            }
        }

        if (await selectHearSubmenuLeaf(container)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) {
                debugLog(`${WD} hear submenu path ok`, parentName);
                return true;
            }
        }
        await navigateHearBackToTop(container);
    }
    return false;
}

const HEAR_SUB_OPTION_PATTERN = /linkedin|indeed|glassdoor|google|monster|careerbuilder|career builder|ziprecruiter|simplyhired|other|website|internet|johnson|xing|another online/i;

function isRecognizedHearSubOption(text) {
    const t = normalizeHearOptionText(text);
    if (!t) return false;
    if (/^other$/i.test(t)) return true;
    if (/^(linkedin|indeed|glassdoor|xing|google|monster|careerbuilder|internet|website|employee referral|referral|newspaper|agency)$/i.test(t)) return true;
    return HEAR_SUB_OPTION_PATTERN.test(t)
        || HEAR_SUB_OPTION_PREFERRED.some(name => hearOptionMatchesPreferred(text, name));
}

function isUnwantedHearSubOption(text) {
    const t = normalizeHearOptionText(text);
    if (!t || HEAR_TOP_LEVEL_OPTIONS.has(t)) return false;
    if (/hire veterans|aerotek|randstad|manpower|adecco|kelly|robert half|staffing/i.test(t)) return true;
    if (/job fair|career fair|recruitment fair|job hair|recruiting event/i.test(t)) return true;
    if (/flex recruiter|flex employee|print advertisement|military|veteran|referral|agency/i.test(t)) return true;
    if (isRecognizedHearSubOption(text)) return false;
    return true;
}

function getHearPillText(container) {
    if (!container || typeof container.querySelector !== 'function') return '';
    return (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').trim();
}

function isNeverHearOption(text) {
    const t = normalizeHearOptionText(text);
    return /aerotek|randstad|manpower|adecco|temp to regular|staffing agency/i.test(t);
}

function isBlockedHearSubOption(text) {
    const t = normalizeHearOptionText(text);
    return /university|college|business school|consortium|apprentice|hec paris|iese/i.test(t);
}

function isFallbackHearOption(text) {
    const t = normalizeHearOptionText(text);
    if (!t || isPhoneCodeOptionText(text) || isNeverHearOption(text)) return false;
    if (HEAR_BLOCKED_TOP_LEVEL.has(t)) return false;
    if (isBlockedHearSubOption(text)) return false;
    return true;
}

function hasHearSelectionChanged(container, pillBefore) {
    const pill = getHearPillText(container);
    if (!pill || pill === pillBefore) return false;
    if (/0 items selected|select one|expanded|minimized/i.test(pill.toLowerCase())) return false;
    if (/error:/i.test(pill)) return false;
    return true;
}

function stripHearFieldLabelFromText(text, container) {
    let t = String(text || '').replace(/\s+/g, ' ').trim();
    const label = getContainerLabel(container).replace(/\*/g, '').trim();
    if (label) {
        const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        t = t.replace(new RegExp(`^${escaped}\\s*`, 'i'), '').trim();
    }
    return t.replace(/^how did you hear[^?]*\??\s*/i, '').trim();
}

function extractHearSingleSelectValue(container) {
    if (!container) return '';
    const promptSel = container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText?.trim();
    if (promptSel && !/^select one$/i.test(promptSel) && promptSel.length > 1 && promptSel !== '...') {
        const stripped = stripHearFieldLabelFromText(promptSel, container);
        if (stripped && !/^how did you hear/i.test(stripped.toLowerCase())) return stripped;
    }
    const stripped = stripHearFieldLabelFromText(getWorkdayFieldSelectedText(container), container);
    if (!stripped || /^select one$/i.test(stripped) || stripped === '...') return '';
    if (/0 items selected/i.test(stripped.toLowerCase())) return '';
    return stripped;
}

function isKnownHearOptionText(text) {
    const t = hearOptionBaseName(text);
    if (!t || /^select one$/i.test(t) || /^how did you hear/i.test(t)) return false;
    if (isNeverHearOption(text)) return false;
    if (HEAR_TOP_LEVEL_OPTIONS.has(t)) return true;
    return /indeed|glassdoor|career builder|corporate website|company web|linkedin|monster|ziprecruiter|employee referral|internet|social media|recruitment agency|referral|job fair|campus|university|military|newspaper|other|facebook|twitter|careers page|job board|google|hkm store/i.test(t);
}

function hasExplicitHearSelection(container) {
    if (!container) return false;
    const pill = getHearPillText(container);
    const pillLower = pill.toLowerCase();
    if (/error:/i.test(pill)) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:.*required|select one.*error:/i.test(preview)) return false;
    const hasMultiselect = !!container.querySelector('[data-automation-id="multiselectInputContainer"]');
    if (hasMultiselect) {
        if (/0 items selected/i.test(pillLower)) return false;
        const selected = getHearSelectedLabel(pill);
        if (selected && !isNeverHearOption(selected)) return true;
        if (/^[1-9]\d*\s+items?\s+selected/i.test(pill.split('\n')[0])) return true;
        const selectedItems = container.querySelectorAll('[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"] li');
        if (selectedItems.length > 0) return true;
        return false;
    }
    const singleSelectValue = extractHearSingleSelectValue(container);
    if (singleSelectValue && isKnownHearOptionText(singleSelectValue)) return true;
    const promptSel = container.querySelector('[data-automation-id="promptSelectionLabel"]')?.innerText?.trim();
    if (promptSel && !/^select one$/i.test(promptSel) && promptSel.length > 1 && promptSel !== '...'
        && !/^how did you hear/i.test(promptSel.toLowerCase())
        && !/error:/i.test(promptSel)) {
        return true;
    }
    const singleSelectText = getWorkdayFieldSelectedText(container);
    if (singleSelectText && !/^select one$/i.test(singleSelectText) && singleSelectText !== '...'
        && !/^how did you hear/i.test(singleSelectText.toLowerCase())
        && !/0 items selected/i.test(singleSelectText.toLowerCase())
        && !/error:/i.test(singleSelectText)
        && !/required and must have a value/i.test(singleSelectText)) {
        return true;
    }
    return false;
}

function isHearFillDone(container) {
    const c = container || findHearAboutContainer();
    if (!c) return Boolean(window.__wdHearFilled);
    if (hasExplicitHearSelection(c)) {
        if (!window.__wdHearFilled) markHearFilled(c);
        return true;
    }
    if (window.__wdHearFilled) {
        window.__wdHearFilled = false;
        window.__wdHearSelectedLabel = '';
    }
    return false;
}

function markHearFilled(container) {
    if (!container) return;
    window.__wdHearFilled = true;
    window.__wdHearSelectedLabel = getHearSelectedLabel(getHearPillText(container))
        || extractHearSingleSelectValue(container)
        || getWorkdayFieldSelectedText(container) || '';
}

function isHearSelectionUsable(container) {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:/i.test(preview)) return false;
    return hasExplicitHearSelection(container);
}

function isAcceptableHearSelection(container) {
    if (!isHearSelectionUsable(container)) return false;
    const pill = getHearPillText(container);
    if (/hire veterans|staffing|recruiting firm/i.test(pill.toLowerCase())) return false;
    return true;
}

const HEAR_TOP_LEVEL_OPTIONS = new Set([
    'campus event',
    'company web site',
    'company website',
    'job board',
    'job boards',
    'job fair',
    'military',
    'recruitment agency',
    'referral',
    'university',
    'professional association',
    'professional event',
    'social network',
    'temp to regular',
    'employee referral',
    'internet',
    'social media',
    'linkedin',
    'other',
    'agency',
    'newspaper',
]);

const HEAR_OPTION_ALIASES = {
    'job board': ['job boards'],
    'job boards': ['job board'],
    'company web site': ['company website'],
    'company website': ['company web site'],
    'social network': ['social media', 'linkedin'],
    'social media': ['social network', 'linkedin'],
    'linkedin': ['social network', 'social media'],
};

/** Synonyms for parent-category matching only (no LinkedIn ↔ Social Media). */
const HEAR_CATEGORY_ALIASES = {
    'job board': ['job boards'],
    'job boards': ['job board'],
    'company web site': ['company website'],
    'company website': ['company web site'],
    'social network': ['social media'],
    'social media': ['social network'],
};

function normalizeHearOptionText(text) {
    return String(text || '')
        .replace(/^(?:\d+\.\d+|\d+\.)\s*/, '')
        .replace(/\s+(not )?checked\b/i, '')
        .trim()
        .toLowerCase();
}

function hearOptionBaseName(optionText) {
    return normalizeHearOptionText(optionText)
        .replace(/\s+not checked$/, '')
        .replace(/\s+checked$/, '')
        .trim();
}

/** Strict match for expandable parent categories (avoids LinkedIn → Social Media false positives). */
function hearOptionMatchesCategory(optionText, categoryName) {
    const option = hearOptionBaseName(optionText);
    const category = normalizeHearOptionText(categoryName);
    if (!option || !category) return false;
    if (option === category) return true;
    const aliases = HEAR_CATEGORY_ALIASES[category] || [];
    return aliases.some(alias => option === alias);
}

function hearOptionMatchesPreferred(optionText, preferredName) {
    const option = hearOptionBaseName(optionText);
    const preferred = normalizeHearOptionText(preferredName);
    if (!option || !preferred) return false;
    if (option === preferred) return true;
    const aliases = HEAR_OPTION_ALIASES[preferred] || [];
    if (aliases.some(alias => option === alias || option.startsWith(`${alias} `))) return true;
    if (option.includes(preferred)) return true;
    return aliases.some(alias => option.includes(alias));
}

function isHearAboutComplete(container) {
    if (!container) return false;
    const pill = (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').trim();
    const pillFirstLine = pill.split('\n')[0].trim();
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:/i.test(preview)) return false;
    if (!pill && hasExplicitHearSelection(container)) return true;
    if (/0 items selected|select one/i.test(pillFirstLine)) return false;
    if (/^(expanded|minimized)$/i.test(pillFirstLine)) return false;
    if (/^[1-9]\d*\s+items?\s+selected/i.test(pillFirstLine)) return true;
    if (/company web site|indeed|linkedin|glassdoor|job board|social network|internet|other/i.test(pill.toLowerCase())
        && !/0 items selected|select one|expanded|minimized/i.test(pill.toLowerCase())) {
        return true;
    }
    return isMultiSelectFilled(container) && !/error:/i.test(preview);
}

async function activateFocusedHearOption(el, container) {
    if (!el) return false;
    const pillBefore = getHearPillText(container);
    el.focus();
    await wait(200);

    const clickTargets = [
        el.querySelector('input[type="radio"]'),
        el.querySelector('[role="radio"]'),
        el.querySelector('input[type="checkbox"]'),
        el.querySelector('[role="checkbox"]'),
        el.querySelector('[data-automation-id="promptLeafNode"]'),
        el.querySelector('[data-automation-id="promptOption"]'),
        el,
    ].filter(Boolean);

    for (const target of clickTargets) {
        if (typeof target.click === 'function') target.click();
        else await workdayClick(target);
        await wait(450);
        if (isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }

    for (const key of [' ', 'Enter']) {
        el.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        el.dispatchEvent(new KeyboardEvent('keyup', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(500);
        if (isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore)) return true;
    }

    await clickWorkdayOption(el);
    await wait(500);
    return isHearOptionSelected(el) || hasHearSelectionChanged(container, pillBefore);
}

async function tryActivateHearOption(container, opt) {
    if (!opt?.el) return false;
    const pillBefore = getHearPillText(container);

    if (isHearMenuItemCheckboxLeaf(opt.el)) {
        if (await clickHearRadioOrLeaf(container, opt)) {
            await wait(400);
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) return true;
        }
    }

    if (await activateFocusedHearOption(opt.el, container)) {
        await wait(400);
        if (isHearSelectionUsable(container)) return true;
    }
    if (await clickHearMenuItem(opt.el, container)) {
        await wait(400);
        if (isHearOptionSelected(opt.el) || isHearMenuItemChecked(opt.el) || hasHearSelectionChanged(container, pillBefore)) {
            if (await commitHearSelectionIfReady(container) && isHearSelectionUsable(container)) return true;
        }
    }
    if (await clickWorkdayOption(opt.el)) {
        await wait(400);
        if (isHearOptionSelected(opt.el) || isHearMenuItemChecked(opt.el) || hasHearSelectionChanged(container, pillBefore)) {
            if (await commitHearSelectionIfReady(container) && isHearSelectionUsable(container)) return true;
        }
    }

    return isHearSelectionUsable(container);
}

async function commitHearSelectionIfReady(container) {
    const pill = (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').trim();
    if (!/^[1-9]\d*\s+items?\s+selected/i.test(pill.split('\n')[0].trim())) {
        return false;
    }
    await closeWorkdayPopups();
    await wait(600);
    await commitHearSelection(container);
    await closeWorkdayPopups();
    await wait(400);
    const ok = isHearAboutComplete(container);
    if (ok) debugLog(`${WD} hear selection committed`, pill.split('\n')[0].slice(0, 80));
    return ok;
}

function hearOptionHasSubmenu(opt) {
    if (!opt) return false;
    if (isHearMenuItemCheckboxLeaf(opt)) return false;
    if (opt.querySelector('[data-automation-id="promptIcon"]')) return true;
    if (opt.getAttribute('aria-expanded') === 'false') return true;
    if (opt.querySelector('[aria-haspopup="true"]')) return true;
    const label = hearOptionBaseName(opt.getAttribute('aria-label') || opt.innerText || opt.textContent || '');
    if (!label) return false;
    if (HEAR_TOP_LEVEL_OPTIONS.has(label) || isHearTreeParentOption(label)) return true;
    return false;
}

async function expandHearOption(opt) {
    if (!opt) return;
    opt.focus();
    await wait(200);
    for (const key of ['ArrowRight', 'Enter']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key, bubbles: true, cancelable: true,
        }));
        await wait(500);
    }
}

async function selectHearPathViaKeyboard(container, pathNames) {
    const trigger = container.querySelector('[data-automation-id="multiselectInputContainer"]')
        || container.querySelector('[data-automation-id="promptArrow"]')
        || container.querySelector('[aria-haspopup="listbox"]');
    if (!trigger || !pathNames?.length) return false;

    await closeWorkdayPopups();
    await wait(400);
    workdayScrollToTarget(container, 120);
    await workdayClick(trigger);
    await wait(1500);

    for (let depth = 0; depth < pathNames.length; depth++) {
        const name = pathNames[depth];
        const popup = findHearAboutPopup(container);
        if (!popup) {
            debugLog(`${WD} hear path no popup at`, name);
            return false;
        }

        const allOptions = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
        const options = depth > 0
            ? allOptions.filter(o => !HEAR_TOP_LEVEL_OPTIONS.has(normalizeHearOptionText(o.text)) && !isUnwantedHearSubOption(o.text))
            : allOptions.filter(o => HEAR_TOP_LEVEL_OPTIONS.has(normalizeHearOptionText(o.text)) || hearOptionMatchesPreferred(o.text, name));
        const match = options.find(o => hearOptionMatchesPreferred(o.text, name));
        if (!match) {
            debugLog(`${WD} hear path option not found`, name, options.map(o => o.text).slice(0, 10));
            return false;
        }

        const isLeaf = depth === pathNames.length - 1;
        if (isLeaf) {
            if (!await clickHearMenuItem(match.el, container)) {
                await clickWorkdayOption(match.el);
            }
            await wait(700);
        } else {
            await clickHearMenuItem(match.el, container);
            await wait(900);
        }
        debugLog(`${WD} hear path step`, pathNames.slice(0, depth + 1).join(' > '));
    }

    await commitHearSelection(container);
    await closeWorkdayPopups();
    await wait(400);
    const ok = isAcceptableHearSelection(container);
    const pill = (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').slice(0, 80);
    debugLog(`${WD} hear path result`, pathNames.join(' > '), 'ok=', ok, 'pill=', pill);
    return ok;
}

async function clickHearMenuItem(opt, container) {
    if (!opt || typeof opt.getAttribute !== 'function' || !document.body.contains(opt)) return false;

    const clickTargets = [
        opt.querySelector('input[type="radio"]'),
        opt.querySelector('[role="radio"]'),
        opt.querySelector('input[type="checkbox"]'),
        opt.querySelector('[role="checkbox"]'),
        opt.querySelector('[data-automation-id="promptLeafNode"]'),
        opt.querySelector('[data-automation-id="promptOption"]'),
        opt.querySelector('label'),
        opt,
    ].filter(Boolean);

    for (const target of clickTargets) {
        debugLog(`${WD} hear item click`, opt.getAttribute('aria-label') || target.getAttribute?.('data-automation-id'));
        await workdayClick(target);
        await wait(400);
        if (isHearOptionSelected(opt)) {
            debugLog(`${WD} hear item selected`, opt.getAttribute('aria-label'));
            return true;
        }
    }

    if (hearOptionHasSubmenu(opt)) {
        await expandHearOption(opt);
        await wait(400);
        return false;
    }

    opt.focus();
    for (const key of ['ArrowRight', 'Enter', ' ']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(400);
        if (isHearOptionSelected(opt)) {
            debugLog(`${WD} hear item selected via keyboard`, opt.getAttribute('aria-label'));
            return true;
        }
    }

    return isHearOptionSelected(opt) || isHearMenuItemChecked(opt);
}

async function completeHearAboutSubSelection(container) {
    for (let depth = 0; depth < 4; depth++) {
        await wait(depth === 0 ? 600 : 900);
        if (await commitHearSelectionIfReady(container) && isAcceptableHearSelection(container)) return true;
        if (isAcceptableHearSelection(container)) return true;

        const popup = findHearAboutPopup(container);
        if (!popup) break;

        const options = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
        let candidates = options.filter(o =>
            !HEAR_TOP_LEVEL_OPTIONS.has(normalizeHearOptionText(o.text))
            && !isUnwantedHearSubOption(o.text));

        let picked = null;
        for (const name of HEAR_SUB_OPTION_PREFERRED) {
            picked = candidates.find(o => hearOptionMatchesPreferred(o.text, name));
            if (picked) break;
        }
        if (!picked) {
            picked = candidates.find(o => isRecognizedHearSubOption(o.text));
        }
        if (!picked) {
            debugLog(`${WD} hear sub-select no recognized option`, candidates.map(c => c.text).slice(0, 8));
            break;
        }

        debugLog(`${WD} hear sub-select`, picked.text.slice(0, 80), 'depth=', depth);
        if (await clickWorkdayOption(picked.el)) {
            debugLog(`${WD} hear sub-option selected`, picked.text.slice(0, 60));
        } else {
            await clickHearMenuItem(picked.el, container);
        }
        await wait(900);
        if (await commitHearSelectionIfReady(container) && isAcceptableHearSelection(container)) return true;
    }

    await closeWorkdayPopups();
    await wait(500);
    return isAcceptableHearSelection(container);
}

async function selectHearTopLevelOption(container, popup, name) {
    if (isHearFillTimedOut()) return false;
    const options = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    const match = options.find(o => hearOptionMatchesPreferred(o.text, name));
    if (!match) return false;

    debugLog(`${WD} hear select top level`, name, 'option=', match.text.slice(0, 80));
    const isLeaf = !hearOptionHasSubmenu(match.el) && !isLikelyHearTreeRootParent(match);
    await clickHearMenuItem(match.el, container);
    await wait(isLeaf ? 500 : 700);

    if (!isLeaf && isAcceptableHearSelection(container)) {
        return true;
    }

    if (isLeaf) {
        if (!isHearOptionSelected(match.el)) {
            await clickWorkdayOption(match.el);
            await wait(400);
        }
        if (await commitHearSelectionIfReady(container) && isAcceptableHearSelection(container)) return true;
        await commitHearSelection(container);
        await wait(400);
        if (isAcceptableHearSelection(container)) return true;
        if (!isHearFillTimedOut() && await selectHearPathViaKeyboard(container, [name])) return true;
    } else if (await commitHearSelectionIfReady(container) && isAcceptableHearSelection(container)) {
        return true;
    }

    if (isHearFillTimedOut()) return false;
    const ok = await completeHearAboutSubSelection(container);
    debugLog(`${WD} hear top level result`, name, 'ok=', ok, 'pill=', (container.querySelector('[data-automation-id="multiselectInputContainer"]')?.innerText || '').slice(0, 80));
    return ok;
}

function getUniqueHearOptions(popup) {
    const seen = new Set();
    const result = [];
    const scope = popup || document;
    const selector = [
        '[data-automation-id="menuItem"]',
        '[data-automation-id="promptOption"]',
        '[data-automation-id="promptLeafNode"]',
        '[role="option"]',
        '[role="treeitem"]',
    ].join(', ');
    for (const el of scope.querySelectorAll(selector)) {
        const text = (el.getAttribute('aria-label') || el.innerText || el.textContent || '').trim().replace(/\s+/g, ' ');
        if (!text || text.length > 120 || seen.has(text)) continue;
        seen.add(text);
        result.push({ el, text });
    }
    return result;
}

function getAllHearOptions(container) {
    const seen = new Set();
    const result = [];
    for (const item of getAllHearMenuItems(container)) {
        const key = normalizeHearOptionText(item.text);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        result.push(item);
    }
    for (const popup of findHearPopups(container)) {
        for (const item of getUniqueHearOptions(popup)) {
            const key = normalizeHearOptionText(item.text);
            if (!key || seen.has(key)) continue;
            seen.add(key);
            result.push(item);
        }
    }
    return result;
}

function getHearTopLevelOptions(container, popup) {
    return getUniqueHearOptions(popup || findHearAboutPopup(container))
        .filter(o => !isPhoneCodeOptionText(o.text))
        .filter(o => HEAR_TOP_LEVEL_OPTIONS.has(normalizeHearOptionText(o.text)))
        .filter(o => !HEAR_BLOCKED_TOP_LEVEL.has(normalizeHearOptionText(o.text)));
}

async function expandHearParentByOption(container, parentOpt) {
    if (!parentOpt?.el) return false;
    const parentName = parentOpt.text;
    debugLog(`${WD} hear expand parent`, parentName.slice(0, 60));
    const row = parentOpt.el.querySelector('[data-automation-id="promptLeafNode"]')
        || parentOpt.el.querySelector('[data-automation-id="promptOption"]')
        || parentOpt.el;
    await workdayClick(row);
    await wait(250);
    parentOpt.el.focus();

    const icon = parentOpt.el.querySelector('[data-automation-id="promptIcon"]');
    if (icon) {
        await workdayClick(icon);
    } else if (hearOptionHasSubmenu(parentOpt.el)) {
        parentOpt.el.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowRight', code: 'ArrowRight', bubbles: true, cancelable: true,
        }));
        await wait(300);
        parentOpt.el.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'Enter', code: 'Enter', bubbles: true, cancelable: true,
        }));
    }
    await wait(1000);

    const subItems = getAllHearMenuItems(container).filter(o => isHearSelectableLeaf(o.text));
    debugLog(`${WD} hear items after expand`, parentName.slice(0, 40), subItems.map(o => o.text).slice(0, 16));

    if (isWrongSubmenuForParent(parentName, subItems)) {
        debugLog(`${WD} hear expand wrong submenu`, parentName.slice(0, 40));
        await navigateHearBackToTop(container);
        return false;
    }
    return subItems.length > 0;
}

async function expandHearParent(container, parentName) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;

    if (getHearSubmenuContext(container)) {
        const pickable = getHearPickableLeaves(container);
        if (pickable.length > 0) {
            debugLog(`${WD} hear submenu already open`, parentName, pickable.map(o => o.text).slice(0, 4));
            return true;
        }
        await navigateHearBackToTop(container);
    }

    const allOptions = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    const parent = allOptions.find(o => hearOptionMatchesCategory(o.text, parentName)
        || hearOptionMatchesPreferred(o.text, parentName));
    if (!parent) {
        debugLog(`${WD} hear parent not found`, parentName, allOptions.map(o => o.text).slice(0, 12));
        return false;
    }

    return expandHearParentByOption(container, parent);
}

async function trySelectHearTopLevelLeaf(container, preferredNames) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const topOptions = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    for (const name of preferredNames) {
        const match = topOptions.find(o => hearOptionMatchesCategory(o.text, name)
            || hearOptionMatchesPreferred(o.text, name));
        if (!match) continue;
        if (hearOptionHasSubmenu(match.el) || isHearParentCategory(match.text)) {
            debugLog(`${WD} hear expand top-level parent`, name, match.text.slice(0, 60));
            if (await expandHearParent(container, name) && await tryForcePickAnyHearOption(container)) {
                return isHearSelectionUsable(container);
            }
            continue;
        }
        if (!isAcceptableHearTopLevelLeaf(match.text)) continue;
        debugLog(`${WD} hear top-level leaf try`, name, match.text.slice(0, 60));
        if (await tryActivateHearOption(container, match)) {
            if (findHearBackButton(container) || isHearRadioDropdown(container)) {
                if (await fillHearRadioDropdown(container)) return isHearSelectionUsable(container);
            }
            return isHearSelectionUsable(container);
        }
        if (findHearBackButton(container) || isHearRadioDropdown(container)) {
            if (await fillHearRadioDropdown(container)) return isHearSelectionUsable(container);
        }
    }
    return false;
}

function getHearSubOptions(container) {
    return getAllHearOptions(container).filter(o => {
        const t = normalizeHearOptionText(o.text);
        return !HEAR_TOP_LEVEL_OPTIONS.has(t)
            && !HEAR_BLOCKED_TOP_LEVEL.has(t)
            && !isPhoneCodeOptionText(o.text)
            && !isUnwantedHearSubOption(o.text);
    });
}

async function openHearDropdown(container) {
    const trigger = getWorkdayDropdownTrigger(container);
    if (!trigger) return null;
    await dismissHearDropdown(container);
    await wait(300);
    workdayScrollToTarget(container, 120);
    await workdayClick(trigger);
    await wait(1500);
    return findHearAboutPopup(container);
}

async function toggleHearOption(opt, container) {
    if (!opt) return false;
    if (isHearOptionSelected(opt)) return true;

    opt.focus();
    await wait(200);

    const checkbox = opt.querySelector('input[type="checkbox"], [role="checkbox"]');
    if (checkbox) {
        await workdayClick(checkbox);
        await wait(500);
        if (isHearOptionSelected(opt)) return true;
    }

    if (await clickWorkdayOption(opt)) {
        if (isHearOptionSelected(opt)) return true;
    }

    for (const key of [' ', 'Enter']) {
        opt.dispatchEvent(new KeyboardEvent('keydown', {
            key, code: key === ' ' ? 'Space' : key, bubbles: true, cancelable: true,
        }));
        await wait(500);
        if (isHearOptionSelected(opt)) return true;
    }

    await workdayClick(opt);
    await wait(400);
    return isHearOptionSelected(opt);
}

const HEAR_LEAF_TRIES = [
    { leaf: 'Indeed', parent: 'Job Board' },
    { leaf: 'Glassdoor', parent: 'Job Board' },
    { leaf: 'Company Web Site', parent: null },
    { leaf: 'Other', parent: 'Job Board' },
    { leaf: 'LinkedIn', parent: 'Social Network' },
];

const HEAR_SEARCH_TERMS = [
    'Indeed',
    'Glassdoor',
    'Monster',
    'CareerBuilder',
    'ZipRecruiter',
    'LinkedIn',
    'Other',
    'Internet',
    'Company Web Site',
];

function isWrongSubmenuForParent(parentName, subItems) {
    const texts = subItems.map(o => normalizeHearOptionText(o.text));
    if (!texts.length) return true;
    if (hearOptionMatchesPreferred(parentName, 'Job Board') || hearOptionMatchesPreferred(parentName, 'Job Boards')) {
        if (texts.length === 1 && /company web/.test(texts[0])) return true;
        if (texts.every(t => /company web/.test(t))) return true;
        return !isJobBoardSubmenuOptions(subItems);
    }
    if (hearOptionMatchesPreferred(parentName, 'Company Web Site') || hearOptionMatchesPreferred(parentName, 'Company Website')) {
        return texts.every(t => /job board/.test(t));
    }
    return false;
}

function isJobBoardSubmenuOptions(options) {
    const texts = options.map(o => normalizeHearOptionText(o.text));
    return texts.some(t => /indeed|glassdoor|monster|careerbuilder|ziprecruiter|simplyhired|other|linkedin|xing|another online/i.test(t));
}

function isAcceptableHearTopLevelLeaf(text) {
    const t = normalizeHearOptionText(text);
    return /job board|company web|linkedin|indeed|glassdoor|internet|other|social network|employee referral|professional/i.test(t);
}

function isCampusSubmenuOptions(options) {
    const texts = options.map(o => normalizeHearOptionText(o.text));
    return texts.filter(t => /university|college|school|consortium|apprentice|hec paris|iese/i.test(t)).length >= 3;
}

async function focusHearList(container) {
    const popup = findHearAboutPopup(container);
    const first = popup?.querySelector('[data-automation-id="menuItem"], [role="option"], [role="treeitem"]');
    if (first) {
        first.focus();
        await wait(200);
        return first;
    }
    const trigger = getWorkdayDropdownTrigger(container);
    const input = trigger?.querySelector('input') || trigger;
    input?.focus();
    await wait(200);
    return input;
}

async function finalizeHearSelection(container) {
    lockHearIfUsable(container);
    await commitWorkdayPopup(container);
    await commitHearSelection(container);
    await wait(400);
    if (findHearPopups(container).length) {
        await blurAwayFromHearField(container);
        await wait(300);
    }
    lockHearIfUsable(container);
    if (window.__wdHearFilled) {
        debugLog(`${WD} hear finalized`, getHearSelectedLabel(getHearPillText(container)).slice(0, 60));
    }
}

async function resetHearToTopLevel(container) {
    const keyTarget = await focusHearList(container);
    if (!keyTarget) return;
    for (let i = 0; i < 3; i++) {
        keyTarget.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowLeft', code: 'ArrowLeft', bubbles: true, cancelable: true,
        }));
        await wait(150);
    }
    for (let i = 0; i < 8; i++) {
        keyTarget.dispatchEvent(new KeyboardEvent('keydown', {
            key: 'ArrowUp', code: 'ArrowUp', bubbles: true, cancelable: true,
        }));
        await wait(80);
    }
    await wait(200);
}

async function selectHearPathInOpenDropdown(container, leafName, parentName) {
    const popup = findHearAboutPopup(container);
    if (!popup) return false;

    if (!parentName) {
        const top = getUniqueHearOptions(popup)
            .filter(o => !isPhoneCodeOptionText(o.text))
            .find(o => hearOptionMatchesPreferred(o.text, leafName) && !isUnwantedHearSubOption(o.text));
        if (top) {
            debugLog(`${WD} hear path top-level`, leafName, top.text.slice(0, 60));
            if (await tryActivateHearOption(container, top)) {
                await wait(400);
                return isHearSelectionUsable(container);
            }
        }
        return false;
    }

    const allTop = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    const parentOpt = allTop.find(o => hearOptionMatchesCategory(o.text, parentName));
    if (!parentOpt) {
        debugLog(`${WD} hear path parent missing`, parentName, allTop.map(o => o.text));
        return false;
    }

    if (!hearOptionHasSubmenu(parentOpt.el) || hearOptionMatchesPreferred(leafName, parentName)) {
        debugLog(`${WD} hear path direct parent`, parentName);
        if (await tryActivateHearOption(container, parentOpt)) {
            await wait(400);
            return isHearSelectionUsable(container);
        }
        return false;
    }

    if (!await expandHearParent(container, parentName)) {
        return false;
    }

    if (await selectHearSubmenuLeaf(container, [leafName, ...HEAR_SUB_OPTION_PREFERRED])) {
        await wait(400);
        return isHearSelectionUsable(container);
    }

    const subItems = getAllHearMenuItems(container).filter(o => isHearSelectableLeaf(o.text));

    let leaf = subItems.find(o =>
        hearOptionMatchesPreferred(o.text, leafName) && !isUnwantedHearSubOption(o.text));

    if (!leaf) {
        const keyTarget = await focusHearList(container);
        if (keyTarget) {
            for (let i = 0; i < 15; i++) {
                const active = document.activeElement;
                const label = active?.getAttribute?.('aria-label') || active?.innerText || '';
                if (hearOptionMatchesPreferred(label, leafName) && !isUnwantedHearSubOption(label)) {
                    leaf = { el: active, text: label };
                    break;
                }
                keyTarget.dispatchEvent(new KeyboardEvent('keydown', {
                    key: 'ArrowDown', code: 'ArrowDown', bubbles: true, cancelable: true,
                }));
                await wait(200);
            }
        }
    }

    if (!leaf) {
        const subs = subItems.filter(o => isFallbackHearOption(o.text));
        if (subs.length && !isCampusSubmenuOptions(subs)) {
            leaf = subs.find(o => isRecognizedHearSubOption(o.text))
                || subs.find(o => /^other$/i.test(normalizeHearOptionText(o.text)))
                || subs[0];
            debugLog(`${WD} hear path substitute`, parentName, '->', leaf.text.slice(0, 60));
        }
    }

    if (!leaf) {
        debugLog(`${WD} hear path miss`, `${parentName} > ${leafName}`);
        await resetHearToTopLevel(container);
        return false;
    }

    debugLog(`${WD} hear path select`, `${parentName} > ${leafName}`, leaf.text.slice(0, 60));
    if (!await tryActivateHearOption(container, leaf)) {
        await resetHearToTopLevel(container);
        return false;
    }
    await wait(400);
    return isHearSelectionUsable(container);
}

const HEAR_FALLBACK_PARENTS = [
    'Company Web Site',
    'Company Website',
    'Job Board',
    'Social Network',
    'Professional Association',
    'Internet',
    'Other',
];

async function selectAnyHearFallback(container) {
    let popup = findHearAboutPopup(container);
    if (!popup) return false;

    debugLog(`${WD} hear fallback start`);

    const roots = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text))
        .sort((a, b) => hearRootPriority(b) - hearRootPriority(a));

    for (const opt of roots) {
        if (isHearFillTimedOut()) break;
        const label = hearOptionBaseName(opt.text);
        if (!label || /^select one$/i.test(label)) continue;
        if (HEAR_BLOCKED_TOP_LEVEL.has(label)) continue;
        if (!isHearCheckboxTreeDropdown(findHearAboutPopup(container))) {
            await resetHearToTopLevel(container);
        }
        if (!findHearAboutPopup(container)) break;
        if (isHearMenuItemCheckboxLeaf(opt.el) && await clickHearRadioOrLeaf(container, opt)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) {
                debugLog(`${WD} hear fallback checkbox`, opt.text.slice(0, 60));
                return true;
            }
        }
        if (await tryActivateHearOption(container, opt)) {
            debugLog(`${WD} hear fallback direct`, opt.text.slice(0, 60));
            return true;
        }
    }

    const parentNames = [];
    const seenParents = new Set();
    for (const name of [...HEAR_FALLBACK_PARENTS, ...roots.map(o => hearOptionBaseName(o.text))]) {
        const key = normalizeHearOptionText(name);
        if (!key || seenParents.has(key) || HEAR_BLOCKED_TOP_LEVEL.has(key)) continue;
        seenParents.add(key);
        parentNames.push(name);
    }

    for (const parentName of parentNames) {
        if (isHearFillTimedOut()) break;
        await resetHearToTopLevel(container);
        popup = findHearAboutPopup(container);
        if (!popup) break;
        const parentOpt = getUniqueHearOptions(popup)
            .filter(o => !isPhoneCodeOptionText(o.text))
            .find(o => hearOptionMatchesCategory(o.text, parentName)
                || (hearOptionMatchesPreferred(o.text, parentName) && hearOptionBaseName(o.text) === hearOptionBaseName(parentName)));
        if (!parentOpt) continue;
        if (!isLikelyHearTreeRootParent(parentOpt)) {
            if (await tryActivateHearOption(container, parentOpt)) return true;
            continue;
        }
        const expanded = await expandHearParentByOption(container, parentOpt);
        if (!expanded) {
            if (await tryActivateHearOption(container, parentOpt)) return true;
            continue;
        }

        const subs = getHearPickableLeaves(container, { allowUnknown: true });
        if (!subs.length || isCampusSubmenuOptions(subs)) {
            if (await tryActivateHearOption(container, parentOpt)) return true;
            continue;
        }

        const pick = subs.find(o => isRecognizedHearSubOption(o.text))
            || subs.find(o => /^other$/i.test(normalizeHearOptionText(o.text)))
            || subs[0];

        debugLog(`${WD} hear fallback submenu`, parentName, '->', pick.text.slice(0, 60));
        if (await tryActivateHearOption(container, pick)) return true;
    }

    for (const opt of roots) {
        if (isHearFillTimedOut()) break;
        if (!isClearlyHearRootLeaf(opt)) continue;
        await resetHearToTopLevel(container);
        const currentPopup = findHearAboutPopup(container);
        if (!currentPopup) break;
        if (await selectHearTopLevelOption(container, currentPopup, hearOptionBaseName(opt.text))) {
            debugLog(`${WD} hear fallback top-level`, opt.text.slice(0, 60));
            return true;
        }
    }

    if (!isHearTreeStyleDropdown(popup)) {
        for (const opt of roots) {
            if (isHearFillTimedOut()) break;
            const label = hearOptionBaseName(opt.text);
            if (!label || /^select one$/i.test(label)) continue;
            if (isLikelyHearTreeRootParent(opt)) continue;
            debugLog(`${WD} hear fallback flat pick`, opt.text.slice(0, 60));
            if (await tryActivateHearOption(container, opt)) return true;
        }
    }

    const any = getAllHearMenuItems(container).filter(o =>
        !isHearBackRow(o.el) && !isPhoneCodeOptionText(o.text));
    if (any.length && !isHearFillTimedOut()) {
        debugLog(`${WD} hear fallback last resort`, any[0].text.slice(0, 60));
        if (await tryActivateHearOption(container, any[0])) return true;
    }

    return false;
}

function findHearDropdownSearchInput(container) {
    if (!container) return null;
    const rect = container.getBoundingClientRect();
    const near = (el) => {
        if (!el || !isVisibleElement(el)) return false;
        const r = el.getBoundingClientRect();
        return r.top >= rect.top - 120
            && r.top <= rect.bottom + 900
            && r.left >= rect.left - 200
            && r.left <= rect.right + 1100;
    };
    const isHearScopedInput = (el) => {
        if (!el || !near(el)) return false;
        const field = el.closest('[data-automation-id*="formField"]');
        if (field && field !== container && !container.contains(field)) return false;
        const fieldLabel = getContainerLabel(field || container).toLowerCase();
        if (/phone code|country phone|phone device/i.test(fieldLabel)) return false;
        return true;
    };

    const candidates = [];
    const add = (el) => {
        if (!el || el.tagName !== 'INPUT' || !isHearScopedInput(el)) return;
        if (el.type === 'checkbox' || el.type === 'radio' || el.type === 'hidden') return;
        if (!candidates.includes(el)) candidates.push(el);
    };

    for (const el of container.querySelectorAll(
        '[data-automation-id="multiselectInputContainer"] input[role="combobox"], [data-automation-id="multiselectInputContainer"] input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"])',
    )) add(el);

    for (const pop of findHearPopups(container)) {
        for (const el of pop.querySelectorAll(
            '[data-automation-id="searchBox"] input, [data-automation-id*="search"] input, input[type="search"], input[placeholder*="Search" i], input[aria-label*="Search" i]',
        )) add(el);
        for (const el of pop.querySelectorAll('input[type="text"], input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"])')) {
            if (!el.closest('[data-automation-id="menuItem"]')) add(el);
        }
    }

    return candidates.find(el => el.closest('[data-automation-id="searchBox"]') && container.contains(el))
        || candidates.find(el => el.closest('[data-automation-id="searchBox"]'))
        || candidates.find(el => /search/i.test(`${el.placeholder || ''} ${el.getAttribute('aria-label') || ''}`))
        || candidates.find(el => container.contains(el))
        || null;
}

function hasHearDropdownSearchInput(container) {
    return Boolean(findHearDropdownSearchInput(container));
}

function getHearPopupSearchInput(container, popup = null) {
    return findHearDropdownSearchInput(container);
}

function hasHearPopupSearchBox(container) {
    return hasHearDropdownSearchInput(container);
}

function getHearSearchInput(container, popup = null) {
    return findHearDropdownSearchInput(container);
}

function getHearSearchResultsPopup(container) {
    for (const pop of findHearPopups(container)) {
        if (/search results/i.test(pop.innerText || '')) return pop;
    }
    const rect = container?.getBoundingClientRect();
    for (const pop of findVisibleWorkdayPopups()) {
        const text = pop.innerText || '';
        if (!/search results/i.test(text)) continue;
        if (rect) {
            const pr = pop.getBoundingClientRect();
            if (pr.top < rect.top - 120 || pr.top > rect.bottom + 900) continue;
            if (pr.left < rect.left - 200 || pr.left > rect.right + 1100) continue;
        }
        return pop;
    }
    return null;
}

function hasHearSearchResultsVisible(container) {
    return Boolean(getHearSearchResultsPopup(container));
}

function hearSearchTermMatchesText(text, term = '') {
    const t = normalizeWorkdayMenuOptionText(text)
        .replace(/\s+not checked|\s+checked/gi, '')
        .trim();
    if (!t || /^search results/i.test(t)) return false;
    const needle = String(term || '').trim();
    if (!needle) return false;
    if (textMatchesCandidate(t, needle)) return true;
    const tl = t.toLowerCase();
    const nl = needle.toLowerCase();
    return tl === nl || tl.startsWith(`${nl} `) || tl.includes(nl);
}

function findHearSearchResultRows(container) {
    const pop = getHearSearchResultsPopup(container) || findHearAboutPopup(container);
    if (!pop) return [];
    const rowSelectors = '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [data-automation-id="menuItem"], [role="option"], li';
    const rows = [];
    for (const row of pop.querySelectorAll(rowSelectors)) {
        if (!isVisibleElement(row)) continue;
        const text = normalizeWorkdayMenuOptionText(
            (row.getAttribute('aria-label') || row.innerText || row.textContent || '').trim(),
        );
        if (!text || /^search results/i.test(text)) continue;
        if (/^select one$/i.test(text)) continue;
        const checkbox = row.querySelector('input[type="checkbox"], [role="checkbox"]');
        const radio = row.querySelector('input[type="radio"], [role="radio"]');
        rows.push({
            el: checkbox || radio || row,
            label: (checkbox?.id && document.querySelector(`label[for="${CSS.escape(checkbox.id)}"]`))
                || (radio?.id && document.querySelector(`label[for="${CSS.escape(radio.id)}"]`))
                || row.querySelector('label')
                || row,
            row,
            text,
            kind: checkbox ? 'checkbox' : (radio ? 'radio' : 'row'),
        });
    }
    return rows;
}

function findHearSearchResultOption(container, searchTerm = '') {
    const rows = findHearSearchResultRows(container);
    if (!rows.length) return null;
    const term = String(searchTerm || '').trim();
    if (term) {
        const exact = rows.find(r => hearSearchTermMatchesText(r.text, term));
        if (exact) return exact;
    }
    const recognized = rows.find(r => isRecognizedHearSubOption(r.text));
    if (recognized) return recognized;
    return rows[0];
}

async function selectHearSearchResultOption(container, option) {
    if (!option) return false;
    const filledCheck = () => isHearSelectionUsable(container);
    if (filledCheck()) return true;

    debugLog(`${WD} hear search result select`, option.kind, option.text?.slice(0, 80));
    const row = option.row || option.label || option.el;
    workdayScrollToTarget(row, 80);
    await wait(150);

    const checkbox = option.el?.type === 'checkbox' || option.el?.getAttribute?.('role') === 'checkbox'
        ? option.el
        : row?.querySelector?.('input[type="checkbox"], [role="checkbox"]');
    const radio = option.el?.type === 'radio' || option.el?.getAttribute?.('role') === 'radio'
        ? option.el
        : row?.querySelector?.('input[type="radio"], [role="radio"]');

    if (checkbox) {
        if (await workdayClickCheckbox(checkbox)) return true;
        await wait(400);
        if (filledCheck()) return true;
    } else if (radio) {
        const target = radio.closest('label') || row || radio;
        await workdayClick(target);
        await wait(400);
        if (radio.checked || filledCheck()) return true;
    }

    for (const target of [option.label, row, option.el]) {
        if (!target) continue;
        await workdayClick(target);
        await wait(400);
        if (filledCheck()) return true;
    }

    if (await clickWorkdayMenuItem(row || option.el, container, filledCheck)) {
        await wait(400);
        if (filledCheck()) return true;
    }
    return filledCheck();
}

async function trySelectHearFromSearchResults(container, searchTerm = 'linkedin') {
    const option = findHearSearchResultOption(container, searchTerm);
    if (!option) {
        debugLog(`${WD} hear search results option not found`);
        return false;
    }
    if (!await selectHearSearchResultOption(container, option)) return false;
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await wait(500);
    for (let i = 0; i < 4; i++) {
        if (isHearSelectionUsable(container)) return true;
        await wait(300);
    }
    return isHearSelectionUsable(container);
}

async function clearHearSearchInput(searchInput) {
    if (!searchInput) return;
    selectWorkdayInputText(searchInput);
    setNativeValue(searchInput, '');
    searchInput.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    searchInput.dispatchEvent(new Event('change', { bubbles: true }));
    await wait(200);
}

async function fillHearSearchWithTerms(container, searchInput, terms = HEAR_SEARCH_TERMS) {
    if (!searchInput || !container) return false;
    window.__wdHearRejectedTerms = window.__wdHearRejectedTerms || new Set();
    const list = (Array.isArray(terms) ? terms : [terms]).filter(Boolean);

    for (const term of list) {
        const key = String(term).toLowerCase();
        if (window.__wdHearRejectedTerms.has(key)) continue;
        if (isHearFillTimedOut()) break;

        if (!await ensureWorkdayInputFocused(searchInput)) {
            await workdayClick(searchInput);
            await wait(250);
            if (!await ensureWorkdayInputFocused(searchInput)) {
                debugLog(`${WD} hear search focus failed`, term);
                window.__wdHearRejectedTerms.add(key);
                continue;
            }
        }
        await clearHearSearchInput(searchInput);
        await workdayTypeSearchInput(searchInput, term);
        await wait(700);
        if (!await ensureWorkdayInputFocused(searchInput)) {
            await workdayClick(searchInput);
            await wait(200);
            await ensureWorkdayInputFocused(searchInput);
        }
        debugLog(`${WD} hear search enter`, term, 'focused=', document.activeElement === searchInput);
        await submitHearSearchInput(searchInput);
        await wait(800);

        if (isHearSelectionUsable(container) || hasExplicitHearSelection(container)) {
            debugLog(`${WD} hear filled via search+enter`, term);
            return true;
        }

        if (hasHearSearchResultsVisible(container) || findHearSearchResultRows(container).length) {
            debugLog(`${WD} hear search results`, term, findHearSearchResultRows(container).map(r => r.text).slice(0, 4));
            if (await trySelectHearFromSearchResults(container, term)) {
                debugLog(`${WD} hear filled via search result`, term);
                return true;
            }
        }
        window.__wdHearRejectedTerms.add(key);
        debugLog(`${WD} hear search term miss`, term);
    }
    return isHearSelectionUsable(container) || hasExplicitHearSelection(container);
}

async function fillHearLinkedInSearch(container, searchInput) {
    return fillHearSearchWithTerms(container, searchInput, HEAR_SEARCH_TERMS);
}

async function fillHearPickAnySimple(container, trigger) {
    if (isHearFillDone(container) || hasExplicitHearSelection(container)) return true;
    if (!findHearAboutPopup(container)) {
        resetWorkdayDropdownOpenCount('how did you hear about us?');
        resetWorkdayDropdownOpenCount('how did you hear');
        await workdayClick(trigger);
        await wait(1200);
    }
    if (!findHearAboutPopup(container)) return false;

    debugLog(`${WD} hear pick-any single-open`);
    startHearFillTimer();

    if (await selectAnyHearFallback(container)) {
        await finalizeHearSelection(container);
        if (isHearSelectionUsable(container)) {
            markHearFilled(container);
            debugLog(`${WD} filled how did you hear via fallback`, getHearPillText(container).slice(0, 80));
            return true;
        }
    }
    if (await tryPickAnyHearFromTopLevel(container)) {
        await finalizeHearSelection(container);
        if (isHearSelectionUsable(container)) {
            markHearFilled(container);
            return true;
        }
    }

    const popup = findHearAboutPopup(container);
    if (!popup) return false;
    const options = getUniqueHearOptions(popup).filter(o => !isPhoneCodeOptionText(o.text));
    for (const opt of options) {
        const label = hearOptionBaseName(opt.text);
        if (!label || /^select one$/i.test(label) || HEAR_BLOCKED_TOP_LEVEL.has(label)) continue;
        if (isLikelyHearTreeRootParent(opt) && !isHearMenuItemCheckboxLeaf(opt.el)) continue;
        if (await clickHearRadioOrLeaf(container, opt) || await tryActivateHearOption(container, opt)) {
            await finalizeHearSelection(container);
            if (isHearSelectionUsable(container)) {
                markHearFilled(container);
                debugLog(`${WD} filled how did you hear pick-any`, opt.text.slice(0, 60));
                return true;
            }
        }
    }
    return false;
}

async function tryHearSearchInOpenDropdown(container, searchTerm) {
    const searchInput = findHearDropdownSearchInput(container);
    if (!searchInput) return false;
    return fillHearLinkedInSearch(container, searchInput);
}

async function fillHearViaSearchInput(container, { popupAlreadyOpen = false } = {}) {
    if (!container || isHearFillDone(container)) {
        return isHearSelectionUsable(container);
    }
    const searchInput = findHearDropdownSearchInput(container);
    if (!searchInput) return false;
    debugLog(`${WD} hear search-only`, searchInput.placeholder || searchInput.getAttribute('aria-label') || 'input');
    const ok = await fillHearLinkedInSearch(container, searchInput);
    if (ok) markHearFilled(container);
    return ok;
}

function isHearOptionSelected(opt) {
    if (!opt) return false;
    if (opt.getAttribute('aria-selected') === 'true') return true;
    if (opt.getAttribute('data-automation-selected') === 'true') return true;
    const label = opt.getAttribute('aria-label') || '';
    if (/\bnot checked\b/i.test(label)) return false;
    if (/\bchecked\b/i.test(label)) return true;
    const checkbox = opt.querySelector('input[type="checkbox"], [role="checkbox"]');
    if (checkbox?.checked || checkbox?.getAttribute('aria-checked') === 'true') return true;
    const radio = opt.querySelector('input[type="radio"], [role="radio"]');
    if (radio?.checked || radio?.getAttribute('aria-checked') === 'true') return true;
    return false;
}

async function ensureHowDidYouHearFilled() {
    let container = findHearAboutContainer();
    if (!container) {
        for (let i = 0; i < 4; i++) {
            await wait(300);
            container = findHearAboutContainer();
            if (container) break;
        }
    }
    if (!container) return true;
    if (isHearFillDone(container)) {
        debugLog(`${WD} how did you hear locked, skip re-fill`);
        return true;
    }
    if (window.__wdHearFilled) {
        window.__wdHearFilled = false;
        debugLog(`${WD} how did you hear lock cleared — selection not usable`);
    }
    if (hasExplicitHearSelection(container)) {
        markHearFilled(container);
        return true;
    }
    if (window.__wdHearFillInProgress) return false;
    window.__wdHearAttempted = false;
    const ok = await fillHowDidYouHearField(container);
    await blurAwayFromHearField(container);
    await wait(400);
    if (isHearFillDone(container)) return true;
    return ok;
}

function startHearFillTimer() {
    window.__wdHearFillStartedAt = Date.now();
}

function resetHearFillTimer() {
    window.__wdHearFillStartedAt = 0;
}

function isHearFillTimedOut() {
    const t = window.__wdHearFillStartedAt;
    return Boolean(t && Date.now() - t > HEAR_FILL_MAX_MS);
}

async function finishHearFill(container, label) {
    await finalizeHearSelection(container);
    const ok = isHearSelectionUsable(container);
    if (ok) {
        markHearFilled(container);
        debugLog(`${WD} filled how did you hear`, label, getHearPillText(container).slice(0, 80));
    }
    return ok;
}

async function abortHearFill(container, reason = 'timeout') {
    debugLog(`${WD} hear fill abort`, reason, getHearPillText(container).slice(0, 80));
    const trigger = getWorkdayDropdownTrigger(container);
    await recoverStuckHearField(container, trigger);
    await dismissHearDropdown(container);
    if (isHearSelectionUsable(container)) {
        markHearFilled(container);
        return true;
    }
    return false;
}

async function reopenHearDropdown(container, trigger, reason = 'retry') {
    debugLog(`${WD} hear reopen`, reason, getHearPillText(container).slice(0, 80));
    await recoverStuckHearField(container, trigger);
    await dismissHearDropdown(container);
    await blurAwayFromHearField(container);
    await wait(400);
    resetWorkdayDropdownOpenCount('how did you hear about us?');
    resetWorkdayDropdownOpenCount('how did you hear');
    workdayScrollToTarget(container, 120);
    await workdayClick(trigger);
    await wait(800);
    let popup = findHearAboutPopup(container);
    if (!popup && isHearFieldStuckOpen(container)) {
        await recoverStuckHearField(container, trigger);
        await workdayClick(trigger);
        await wait(800);
        popup = findHearAboutPopup(container);
    }
    return popup;
}

async function fillHowDidYouHearField(container) {
    if (!container) return false;
    if (isHearFillDone(container)) {
        debugLog(`${WD} how did you hear already filled (flag)`);
        return true;
    }
    if (window.__wdHearFilled && !hasExplicitHearSelection(container)) {
        window.__wdHearFilled = false;
        debugLog(`${WD} how did you hear flag cleared — selection not usable`);
    }
    if (hasExplicitHearSelection(container)) {
        debugLog(`${WD} how did you hear already selected`);
        markHearFilled(container);
        return true;
    }
    if (window.__wdHearFillInProgress) return false;
    window.__wdHearFillInProgress = true;
    window.__wdHearAttempted = true;

    const isHearMultiselect = !!container.querySelector('[data-automation-id="multiselectInputContainer"]');

    try {
        const trigger = getWorkdayDropdownTrigger(container);
        if (!trigger) return false;

        await recoverStuckHearField(container, trigger);
        if (findHearPopups(container).length) {
            await dismissHearDropdown(container);
            await wait(300);
        }

        workdayScrollToTarget(container, 120);
        await workdayClick(trigger);
        await wait(800);

        const msInput = container.querySelector('[data-automation-id="multiselectInputContainer"] input');
        if (msInput) {
            await workdayClick(msInput);
            await wait(400);
        }

        const searchInput = findHearDropdownSearchInput(container);
        const previewLower = (container.innerText || '').replace(/\s+/g, ' ').toLowerCase();
        const isSimpleHearSingleSelect = !isHearMultiselect && !searchInput && !msInput
            && (/career builder|corporate website|facebook careers|former employee|glassdoor|indeed|job board|social media|google|hkm store/i.test(previewLower)
                || container.querySelector('button[aria-haspopup="listbox"]'));
        if (isSimpleHearSingleSelect && !isHearFillDone(container)) {
            await closeWorkdayPopups();
            await wait(300);
            const hearDirectCandidates = [
                'Job Board', 'Indeed', 'Google', 'Social Media', 'Career Builder',
                'Corporate Website', 'Company Website', 'Glassdoor', 'LinkedIn', 'Employee Referral', 'Other',
            ];
            debugLog(`${WD} hear simple single-select direct fill`);
            const directOk = await withHearDirectFill(async () =>
                await fillWorkdaySingleSelectDropdown(trigger, hearDirectCandidates, 'hear-direct-fill')
                || await fillWorkdayDropdownOnce(trigger, 'Job Board')
                || await fillWorkdayDropdownOnce(trigger, 'Indeed'));
            if (directOk && (isHearSelectionUsable(container) || hasExplicitHearSelection(container))) {
                await blurAwayFromHearField(container);
                markHearFilled(container);
                debugLog(`${WD} filled how did you hear simple single-select`, getWorkdayFieldSelectedText(container).slice(0, 60));
                return true;
            }
        }

        startHearFillTimer();
        if (!searchInput && msInput) {
            debugLog(`${WD} hear msInput direct type fallback`);
            for (const term of HEAR_SEARCH_TERMS.slice(0, 6)) {
                await workdayClick(msInput);
                await wait(300);
                await clearHearSearchInput(msInput);
                await workdayTypeSearchInput(msInput, term);
                await wait(600);
                await submitHearSearchInput(msInput);
                await wait(800);
                if (await trySelectHearFromSearchResults(container, term) || isHearSelectionUsable(container)) {
                    await finalizeHearSelection(container);
                    await blurAwayFromHearField(container);
                    markHearFilled(container);
                    debugLog(`${WD} filled how did you hear msInput`, term);
                    return true;
                }
            }
        }
        if (searchInput) {
            debugLog(`${WD} hear searchable — terms`, HEAR_SEARCH_TERMS.slice(0, 6).join(', '));
            if (await fillHearSearchWithTerms(container, searchInput, HEAR_SEARCH_TERMS)) {
                await finalizeHearSelection(container);
                await blurAwayFromHearField(container);
                markHearFilled(container);
                debugLog(`${WD} filled how did you hear`, 'search', getHearPillText(container).slice(0, 80));
                return true;
            }
            debugLog(`${WD} hear search exhausted — tree fallback (keep popup open)`);
            if (await selectAnyHearFallback(container)) {
                await finalizeHearSelection(container);
                if (isHearSelectionUsable(container)) {
                    await blurAwayFromHearField(container);
                    markHearFilled(container);
                    debugLog(`${WD} filled how did you hear`, 'fallback', getHearPillText(container).slice(0, 80));
                    return true;
                }
            }
        }

        if (isHearFillDone(container) || hasExplicitHearSelection(container)) {
            markHearFilled(container);
            await blurAwayFromHearField(container);
            return true;
        }

        debugLog(`${WD} hear pick-any final`);
        if (await fillHearPickAnySimple(container, trigger)) {
            await blurAwayFromHearField(container);
            markHearFilled(container);
            return true;
        }

        if (!isHearMultiselect) {
        const hearLabel = getContainerLabel(container);
        const singleSelectTrigger = getWorkdayDropdownTrigger(container);
        if (singleSelectTrigger && !isHearFillDone(container)) {
            await closeWorkdayPopups();
            await wait(300);
            resetWorkdayDropdownOpenCount('how did you hear about us?');
            resetWorkdayDropdownOpenCount('how did you hear');
            debugLog(`${WD} hear single-select fallback`);
            const hearCandidates = [
                'Indeed', 'Career Builder', 'Corporate Website', 'Company Website',
                'Glassdoor', 'LinkedIn', 'Job Board', 'Internet', 'Social Media', 'Other', 'Employee Referral',
            ];
            let ok = await withHearDirectFill(async () =>
                await fillWorkdaySingleSelectDropdown(singleSelectTrigger, hearCandidates, 'hear-direct-fill')
                || await fillWorkdayDropdownOnce(singleSelectTrigger, 'Indeed'));
            debugLog(`${WD} hear single-select fallback result`, ok, getWorkdayFieldSelectedText(container).slice(0, 60));
            if (ok) {
                await wait(500);
                if (isHearSelectionUsable(container)) {
                    await blurAwayFromHearField(container);
                    markHearFilled(container);
                    debugLog(`${WD} filled how did you hear single-select`, getWorkdayFieldSelectedText(container).slice(0, 60));
                    return true;
                }
            }
        }
        }

        if (isHearFillDone(container) || hasExplicitHearSelection(container)) {
            markHearFilled(container);
            await blurAwayFromHearField(container);
            return true;
        }

        if (!findHearAboutPopup(container) && trigger && !isHearFillDone(container)) {
            await workdayClick(trigger);
            await wait(1200);
        }
        const allItems = getAllHearMenuItems(container).filter(o => isFallbackHearOption(o.text));
        debugLog(`${WD} hear allItems fallback`, allItems.length, allItems.map(o => o.text.slice(0, 35)).slice(0, 8));
        for (const item of allItems) {
            if (await tryActivateHearOption(container, item)) {
                await finalizeHearSelection(container);
                if (isHearSelectionUsable(container) || isHearAboutComplete(container)) {
                    await blurAwayFromHearField(container);
                    markHearFilled(container);
                    debugLog(`${WD} filled how did you hear allItems`, item.text.slice(0, 50));
                    return true;
                }
            }
        }

        if (hasExplicitHearSelection(container)) {
            markHearFilled(container);
            await blurAwayFromHearField(container);
            return true;
        }

        await dismissHearDropdown(container);
        return false;
    } finally {
        window.__wdHearFillInProgress = false;
        resetHearFillTimer();
    }
}

function getWorkdayDropdownTrigger(container) {
    const label = getContainerLabel(container).toLowerCase();
    if (/how did you hear/i.test(label)) {
        return container.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || container.querySelector('[data-automation-id="multiselectInputContainer"]')
            || container.querySelector('[data-automation-id="promptSelectionLabel"]')
            || container.querySelector('[data-automation-id="promptArrow"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[aria-haspopup="listbox"]');
    }
    if (/phone code/i.test(label)) {
        return container.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || container.querySelector('[data-automation-id="multiselectInputContainer"]')
            || container.querySelector('[data-automation-id="promptArrow"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[aria-haspopup="listbox"]')
            || container.querySelector('button');
    }
    // Phone Device Type sits next to Phone Code — prefer this field's own arrow/label, never a
    // sibling's first button from a shared ancestor (entegris.wd1 / icf.wd5).
    if (/phone device type/i.test(label)) {
        return container.querySelector('[data-automation-id="promptArrow"]')
            || container.querySelector('[data-automation-id="promptSelectionLabel"]')
            || container.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || container.querySelector('[data-automation-id="multiselectInputContainer"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[aria-haspopup="listbox"]')
            || container.querySelector('[role="combobox"]')
            || container.querySelector('button');
    }
    if (isCountryOrCitizenshipFieldLabel(label)) {
        return container.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || container.querySelector('[data-automation-id="multiselectInputContainer"]')
            || container.querySelector('[data-automation-id="promptSelectionLabel"]')
            || container.querySelector('[data-automation-id="promptArrow"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[aria-haspopup="listbox"]')
            || container.querySelector('button');
    }
    if (isWorkdayStateFieldLabel(label)) {
        return container.querySelector('[data-automation-id="promptSelectionLabel"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[data-automation-id="promptIcon"]')
            || container.querySelector('button')
            || container.querySelector('[role="combobox"]');
    }
    if (isCompensationFieldLabel(label)) {
        return container.querySelector('[data-automation-id="multiselectInputContainer"] button')
            || container.querySelector('[data-automation-id="multiselectInputContainer"]')
            || container.querySelector('[data-automation-id="promptSelectionLabel"]')
            || container.querySelector('[data-automation-id="promptArrow"]')
            || container.querySelector('button[aria-haspopup="listbox"]')
            || container.querySelector('[aria-haspopup="listbox"]')
            || container.querySelector('[role="combobox"]')
            || container.querySelector('button');
    }
    return container.querySelector('button, [role="combobox"], [aria-haspopup="listbox"], [data-automation-id*="multiSelect"], [data-automation-id="promptSelectionLabel"]')
        || container.querySelector('[data-automation-id*="prompt"]');
}

async function fillEmptyRequiredDropdowns(profile) {
    if (isWorkdayAvailabilityStepActive() || pageHasWorkdayTimeSlotRequirementError()
        || pageHasWorkdayAvailabilityConflictError()) {
        await fillWorkdayAvailabilityTimeSlotGrid();
    }
    for (const container of getWorkdayFieldContainers()) {
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        const label = getContainerLabel(container);
        if (shouldSkipOptionalNameAffixField(container, label)) continue;
        const labelLower = label.toLowerCase();
        if (/how did you hear/i.test(labelLower)) {
            if (isHearFillDone(container)) continue;
            if (window.__wdHearFillInProgress) continue;
            await ensureHowDidYouHearFilled();
            continue;
        }
        // Agree/Disagree policy acknowledgments before always-no / veteran heuristics
        // (EEO text mentions "veteran status" / "disability" and can misroute).
        if (isWorkdayPrivacyConsentDropdownField(label, container)) {
            if (!isWorkdayAgreeDisagreeConsentFilled(container)) {
                const ok = await fillWorkdayPrivacyConsentDropdown(container, label);
                if (ok || isWorkdayAgreeDisagreeConsentFilled(container) || isWorkdayYesNoFilled(container, 'Yes')) {
                    continue;
                }
                // Misclassified — fall through to hardcoded Yes/No / stream fill
            } else {
                continue;
            }
        }
        if (isWorkdayGpaQuestion(label)) {
            if (!isWorkdayGpaFilled(container)) {
                await fillWorkdayGpaField(container, label);
            }
            continue;
        }
        if (isWorkdayMajorMultiSelectQuestion(label)) {
            await fillWorkdayMajorMultiSelectField(container, label);
            continue;
        }
        if (isWorkdaySkillAbilityQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySkillAbilityCandidates())) {
                await fillWorkdaySkillAbilityField(container, label);
            }
            continue;
        }
        if (isWorkdayAlwaysNoQuestion(label)) {
            if (!isWorkdayYesNoFieldLockedAndFilled(container, label)
                && !isWorkdayYesNoFilled(container, 'No')
                && !isWorkdaySingleSelectFilled(container, ['No', 'no'])) {
                await fillWorkdayAlwaysNoField(container, label);
            }
            continue;
        }
        // UK/global Yes/No "legal right to work" — correct stream "No" answers
        if (/do you have the (?:legal )?right to work|legal right to work/i.test(labelLower)
            && !/status|additional details|what is your current/i.test(labelLower)) {
            const yesCands = getWorkdayConsentYesCandidates(label);
            if (!isWorkdaySingleSelectFilled(container, yesCands) && !isWorkdayYesNoFilled(container, 'Yes')) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} legal right to work local Yes`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, yesCands, labelLower);
                else await fillWorkdayYesNoField(container, 'Yes');
                markWorkdayLockedYesNoFilled(label);
            }
            continue;
        }
        // India eligibility / join location / interview availability — correct stream No
        if (/eligible to work in india|holding an indian passport|available to join in the posted|available for personal interview/i.test(labelLower)) {
            const yesCands = ['Yes', 'yes'];
            if (!isWorkdayYesNoFilled(container, 'Yes') && !isWorkdaySingleSelectFilled(container, yesCands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} india/join/interview local Yes`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, yesCands, labelLower);
                else await fillWorkdayYesNoField(container, 'Yes');
                markWorkdayLockedYesNoFilled(label);
            }
            continue;
        }
        // LBG disability adjustments / Disability Confident Scheme — always No
        if (/require any adjustments|adjustments for the recruitment process|disability confident scheme|considered under the dcs|\bunder the dcs\b/i.test(labelLower)) {
            const noCands = ['No', 'no', 'No, I do not', 'I do not require adjustments'];
            if (!isWorkdayYesNoFilled(container, 'No') && !isWorkdaySingleSelectFilled(container, noCands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} adjustments/DCS local No`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, noCands, labelLower);
                else await fillWorkdayYesNoField(container, 'No');
                markWorkdayLockedYesNoFilled(label);
            }
            continue;
        }
        // Isle of Man residency / license — No; duration band if still shown
        if (/isle of man|born on the island|license enabling you to work in the isle/i.test(labelLower)) {
            if (!isWorkdayYesNoFilled(container, 'No') && !isWorkdaySingleSelectFilled(container, ['No', 'no'])) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} isle of man local No`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, ['No', 'no'], labelLower);
                else await fillWorkdayYesNoField(container, 'No');
                markWorkdayLockedYesNoFilled(label);
            }
            continue;
        }
        if (/how long have you lived there/i.test(labelLower)) {
            const cands = ['Over 5 years', 'Under 5 years', '5 years or more', 'Less than 5 years'];
            if (!isWorkdaySingleSelectFilled(container, cands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} how long lived local`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
            }
            continue;
        }
        if (/which region are you willing to work|region are you willing to work in/i.test(labelLower)) {
            const cands = getWorkdayWorkRegionCandidates();
            if (!isWorkdaySingleSelectFilled(container, cands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} work region local`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
            }
            continue;
        }
        if (/i confirm that i have read the above statement|21 o\.s\.|information provided is correct to the best of my knowledge/i.test(labelLower)) {
            const cands = getWorkdayConsentYesCandidates(label);
            if (!isWorkdaySingleSelectFilled(container, cands)) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                debugLog(`${WD} attestation confirm local`, label.slice(0, 60));
                if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
            }
            continue;
        }
        if (/total years of experience|confirm your total years of experience/i.test(labelLower)) {
            const ctrl = container.querySelector('textarea, input[type="text"], input[type="number"]')
                || getContainerControl(container);
            if (ctrl && !(ctrl.value || '').trim()) {
                const years = Number(profile?.workingExperienceInYears ?? profile?.working_experience_in_years);
                if (Number.isFinite(years) && years > 0) {
                    const val = Number.isInteger(years) ? String(years) : years.toFixed(1);
                    await workdayTypeElement(ctrl, val);
                    debugLog(`${WD} total years experience fill`, val);
                }
            }
            continue;
        }
        if (isWorkdayFormerEmployerAffiliateTextField(label)) {
            await fillWorkdayFormerEmployerAffiliateTextField(container, label);
            continue;
        }
        if (isWorkdayFormerEmployerTextFollowUp(label, container)) {
            await fillWorkdayFormerEmployerTextFollowUp(container, label);
            continue;
        }
        if (isWorkdaySmsConsentDropdownField(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdaySmsConsentCandidates())
                && !isWorkdayYesNoFilled(container, 'Yes')) {
                debugLog(`${WD} sms consent local fill`, label.slice(0, 60));
                await fillWorkdaySmsConsentDropdown(container, label);
            }
            continue;
        }
        if (isWorkdayShiftAvailabilityQuestion(label)) {
            if (!isWorkdayShiftAvailabilityFilled(container)) {
                debugLog(`${WD} shift availability local fill`, label.slice(0, 60));
                await fillWorkdayShiftAvailabilityField(container, label);
            }
            continue;
        }
        if (isWorkdayAgeBand18SelectQuestion(label)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdayAgeBand18Candidates())) {
                await fillWorkdayAgeBand18Field(container, label);
            }
            continue;
        }
        if (isWorkdayStartAvailabilityBandQuestion(label, container)) {
            if (!isWorkdaySingleSelectFilled(container, getWorkdayStartAvailabilityBandCandidates())) {
                await fillWorkdayStartAvailabilityBandField(container, label);
            }
            continue;
        }
        if (isWorkdayTotalHoursPerWeekField(label)) {
            await fillWorkdayTotalHoursPerWeekField(container, label);
            continue;
        }
        if (isWorkdayEmploymentTypeQuestion(label)) {
            if (!(isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayEmploymentTypeCandidates())
                || isWorkdaySingleSelectFilled(container, getWorkdayEmploymentTypeCandidates()))) {
                await fillWorkdayEmploymentTypeField(container, label);
            }
            continue;
        }
        if (isWorkdayBestContactTimeQuestion(label)) {
            if (!isWorkdayMultiOptionAvailabilityFilled(container, getWorkdayBestContactTimeCandidates())) {
                await fillWorkdayBestContactTimeField(container, label);
            }
            continue;
        }
        if (isWorkdayNaIfNoTextField(label)) {
            await fillWorkdayNaIfNoTextField(container, label, profile);
            continue;
        }
        if (isWorkdayPassportVisaTypeTextField(label)) {
            await fillWorkdayPassportVisaTypeTextField(container, label, profile);
            continue;
        }
        if (isWorkdayClinicalSettingsQuestion(label)) {
            if (!isWorkdayClinicalSettingsFilled(container, profile)) {
                await fillWorkdayClinicalSettingsField(container, label, profile);
            }
            continue;
        }
        if (isWorkdayStateFieldLabel(label)) continue;
        const value = getProfileFieldValue(profile, label);
        // If AI/profile has no value, try smart defaults for known required Yes/No fields
        if ((value === null || value === undefined || value === '') && isContainerRequired(container)) {
            const ctrl0 = getContainerControl(container);
            const isEmptyDropdown = (/select one|0 items selected|error:/i.test(preview)
                || (ctrl0 && (ctrl0.tagName === 'BUTTON' || ctrl0.getAttribute('aria-haspopup') === 'listbox') && !(ctrl0.value || ctrl0.innerText?.replace(/▾|▼|⌄/g,'').trim())))
                && !container.querySelector('textarea')
                && !container.querySelector('input[type="radio"]');
            if (isEmptyDropdown) {
                if (isGenpactAiMatchingOptInField(label)) {
            if (!isWorkdaySingleSelectFilled(container, getGenpactAiMatchingCandidates())) {
                await fillWorkdayGenpactAiOptInField(container, label);
            }
            continue;
        }

        if (isWorkdayPrivacyConsentDropdownField(label, container)) {
                    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                    if (ctrl && !isWorkdaySingleSelectFilled(container, getWorkdayPrivacyConsentCandidates())) {
                        debugLog(`${WD} privacy consent local fill`, label.slice(0, 60));
                        await fillWorkdayPrivacyConsentDropdown(container, label);
                    }
                    continue;
                }
                if (isGdprRecruitmentConsentField(labelLower)) {
                    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                    if (ctrl && !isWorkdaySingleSelectFilled(container, ['Yes', 'I agree'])) {
                        debugLog(`${WD} filling GDPR recruitment consent dropdown`, label.slice(0, 60));
                        await fillWorkdaySingleSelectDropdown(ctrl, ['Yes', 'I agree', 'I Agree'], labelLower.slice(0, 80));
                    }
                    continue;
                }
                if (isWorkdayDisclosureGenderField(labelLower)) {
                    // Never fill locally — profile has no gender; always resolved via the AI
                    // stream in fillWorkdayFields (see chrome-extension.mdc "Gender / sex
                    // disclosure fields — never choose locally").
                    continue;
                }
                if (/marital status/i.test(labelLower)) {
                    const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                    const maritalCandidates = jobLocationExpectsEgyptResidency()
                        ? ['Single (Egypt)', 'Single', 'Married (Egypt)', 'Married']
                        : ['Single', 'Married', 'Divorced', 'Widowed'];
                    if (ctrl && !isWorkdaySingleSelectFilled(container, maritalCandidates)) {
                        debugLog(`${WD} marital status local fill`, label.slice(0, 60));
                        await fillWorkdaySingleSelectDropdown(ctrl, maritalCandidates, labelLower);
                    }
                    continue;
                }
                if (/^province$/i.test(labelLower.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
                    if (!isWorkdaySingleSelectFilled(container, getSaudiProvinceCandidates())) {
                        await fillSaudiProvinceField(container, label);
                    }
                    continue;
                }
                if (/date of birth/i.test(labelLower)) {
                    const ctrl = getContainerControl(container);
                    const dob = getProfileDateOfBirth(profile);
                    if (ctrl && dob && !isDateContainerFilled(container, dob)) {
                        debugLog(`${WD} date of birth local fill`, dob);
                        await fillWorkdayMaskedDate(container, ctrl, dob, preview);
                    }
                    continue;
                }
                if (/ethnicity|\brace\b|what is your race|select one option below|you may select|select your race|select the race|please select your race/i.test(labelLower)
                    && !isHispanicLatinoOnlyFieldLabel(labelLower)) {
                    const ctrl = getContainerControl(container);
                    if (ctrl) {
                        if (isDisclosureChoiceGroup(container)) {
                            await fillWorkdayDisclosureChoiceGroup(container, mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity));
                        } else {
                            await fillWorkdayRaceDropdown(ctrl, profile, labelLower);
                        }
                    }
                    continue;
                }
                if (shouldStreamWorkdayQuestionField(label, container) || isApplicationQuestionStreamField(label)) {
                    if (/commute time/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        const commuteOpts = WORKDAY_COMMUTE_TIME_OPTIONS.slice();
                        if (ctrl && !isWorkdaySingleSelectFilled(container, commuteOpts)) {
                            clearWorkdaySingleSelectMissKey(labelLower);
                            debugLog(`${WD} commute local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, commuteOpts, labelLower);
                        }
                    } else if (isNonDialysisHealthcareField(label) && isContainerRequired(container)) {
                        await fillWorkdayNonDialysisHealthcareField(container, profile, label);
                    } else if (/keep in touch|sharing future career/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        if (ctrl && !isWorkdaySingleSelectFilled(container, ['I consent', 'Yes', 'No'])) {
                            debugLog(`${WD} keep in touch local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, ['I consent', 'I Consent', "I don't consent", 'Yes', 'No'], labelLower);
                        }
                    } else if (/undertake a wwc check|working with children \(wwc\)/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        const cands = /undertake a wwc/i.test(labelLower) ? ['Yes', 'yes'] : ['No', 'no'];
                        if (ctrl && !isWorkdaySingleSelectFilled(container, cands)) {
                            debugLog(`${WD} wwc local fallback`, label.slice(0, 60), cands[0]);
                            await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
                        }
                    } else if (/working rights|right to work status/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        const cands = getWorkdayWorkingRightsCandidates(profile, label);
                        if (ctrl && !isWorkdaySingleSelectFilled(container, cands)) {
                            clearWorkdaySingleSelectMissKey(labelLower);
                            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                            debugLog(`${WD} working rights local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
                        }
                    } else if (/do you have the (?:legal )?right to work|legal right to work/i.test(labelLower)
                        && !/status|additional details/i.test(labelLower)
                        && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        const yesCands = getWorkdayConsentYesCandidates(label);
                        if (ctrl && !isWorkdaySingleSelectFilled(container, yesCands)) {
                            clearWorkdaySingleSelectMissKey(labelLower);
                            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                            debugLog(`${WD} legal right local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, yesCands, labelLower);
                        }
                    } else if (/require any adjustments|disability confident scheme|considered under the dcs|\bunder the dcs\b/i.test(labelLower)
                        && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        if (ctrl && !isWorkdaySingleSelectFilled(container, ['No', 'no'])) {
                            clearWorkdaySingleSelectMissKey(labelLower);
                            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                            debugLog(`${WD} adjustments/DCS local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, ['No', 'no'], labelLower);
                        }
                    } else if (/additional details about your right to work/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = container.querySelector('textarea')
                            || getContainerControl(container);
                        const val = getProfileFieldValue(profile, label) || 'I have the unrestricted right to work in the UK.';
                        if (ctrl && !(ctrl.value || '').trim()) {
                            await workdayTypeElement(ctrl, val);
                            debugLog(`${WD} right-to-work details fill`, label.slice(0, 60));
                        }
                    } else if (/preferred language/i.test(labelLower) && isContainerRequired(container)) {
                        const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                        const cands = getPreferredLanguageCandidates(profile);
                        if (ctrl && !isWorkdaySingleSelectFilled(container, cands)) {
                            clearWorkdaySingleSelectMissKey(labelLower);
                            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                            debugLog(`${WD} preferred language local fallback`, label.slice(0, 60));
                            await fillWorkdaySingleSelectDropdown(ctrl, cands, labelLower);
                        }
                    } else if (isLikelyYesNoDropdown(container, labelLower)) {
                        // Stream preferred but collection/stream may have missed — fill locally
                        const smartDefault = getWorkdayYesNoSmartDefault(labelLower)
                            || getHardcodedYesNoAnswer(label)
                            || getProfileDerivedYesNoAnswer(profile, label);
                        if (smartDefault) {
                            const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container);
                            const smartCandidates = smartDefault === 'Yes'
                                ? getWorkdayConsentYesCandidates(label)
                                : ['No', 'no'];
                            // Invalid stream values mark __wdSingleSelectMissKeys — clear so local
                            // Yes/No can still open once (otherwise government-official etc. stick forever).
                            clearWorkdaySingleSelectMissKey(label);
                            clearWorkdaySingleSelectMissKey(labelLower);
                            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                            debugLog(`${WD} stream-miss yes/no local fallback`, label.slice(0, 60), '->', smartCandidates[0]);
                            if (ctrl) await fillWorkdaySingleSelectDropdown(ctrl, smartCandidates, labelLower);
                            else await fillWorkdayYesNoField(container, smartDefault);
                        } else {
                            debugLog(`${WD} skip local dropdown default — prefer streamVacancyFields`, label.slice(0, 60));
                        }
                    } else {
                        debugLog(`${WD} skip local dropdown default — prefer streamVacancyFields`, label.slice(0, 60));
                    }
                    continue;
                }
                if (isNonDialysisHealthcareField(label) && isContainerRequired(container)) {
                    await fillWorkdayNonDialysisHealthcareField(container, profile, label);
                    continue;
                }
                if (!isLikelyYesNoDropdown(container, labelLower)) {
                    debugLog(`${WD} skip local dropdown default — not yes/no`, label.slice(0, 60));
                    continue;
                }
                const ctrl = getContainerControl(container);
                if (ctrl) {
                    if (isCompensationFieldLabel(labelLower)) {
                        await fillWorkdayCompensationField(container, profile, label);
                        continue;
                    }
                    if (/sex at birth|sex.*birth|biological sex/i.test(labelLower)) {
                        await fillWorkdaySingleSelectDropdown(ctrl, getDisclosureSexAtBirthCandidates(), labelLower);
                        continue;
                    }
                    if (/ethnicity|\brace\b|what is your race|select one option below|you may select|select your race|select the race|please select your race/i.test(labelLower)) {
                        await fillWorkdayRaceDropdown(ctrl, profile, labelLower);
                        continue;
                    }
                    // Detect what kind of field
                    const smartDefault = getWorkdayYesNoSmartDefault(labelLower);
                    if (!smartDefault) {
                        debugLog(`${WD} required dropdown no deterministic default`, label.slice(0, 60));
                        continue;
                    }
                    const smartCandidates = smartDefault === 'Yes'
                        ? getWorkdayConsentYesCandidates(label)
                        : ['No', 'no', 'Not Applicable', 'Not applicable', 'N/A', 'None'];
                    debugLog(`${WD} required dropdown no value, using smart default`, label.slice(0, 60), '->', smartCandidates[0]);
                    const filled = await fillWorkdaySingleSelectDropdown(ctrl, smartCandidates, labelLower)
                        || await fillWorkdayYesNoField(container, smartDefault);
                    if (filled && isWorkdayLockedYesNoField(label)) markWorkdayLockedYesNoFilled(label);
                }
            }
            continue;
        }

        if (value === null || value === undefined || value === '') continue;

        // Phone number is a text input; format errors must be typed, not treated as dropdowns.
        if (/phone number/i.test(labelLower) && !/code|type|extension/i.test(labelLower)) {
            const element = getContainerControl(container);
            if (element && element.tagName === 'INPUT' && element.type !== 'radio' && element.type !== 'checkbox') {
                const phone = String(value).replace(/\D/g, '') || String(value);
                const current = (element.value || '').replace(/\D/g, '');
                const needsPhoneFix = /error:|valid format|number length|not valid for this region/i.test(preview)
                    || !current
                    || current !== phone;
                if (needsPhoneFix) {
                    resetWorkdayDropdownOpenCount('phone number');
                    clearWorkdaySingleSelectMissKey(label);
                    debugLog(`${WD} filling phone number text`, phone, 'was=', current.slice(0, 20));
                    workdayScrollToTarget(element, 120);
                    await workdayTypeElement(element, phone);
                    await wait(400);
                }
            }
            continue;
        }

        const needsFill = /select one|0 items selected|error:/i.test(preview)
            || isWorkdayDateFieldIncomplete(container)
            || (/^(yes|no)$/i.test(String(value)) && !isWorkdayYesNoFilled(container, value))
            || (/non-compete|non-solicit|non-disclosure/i.test(labelLower) && !(container.querySelector('textarea')?.value || '').trim())
            || (/percentage.*travel|travel.*percentage/i.test(labelLower) && !isTravelFilled(container));
        if (!needsFill) continue;

        if (/non-compete|non-solicit|non-disclosure/i.test(labelLower)) {
            const textarea = container.querySelector('textarea');
            const text = getProfileFieldValue(profile, label);
            if (textarea && text && !(textarea.value || '').trim()) {
                debugLog(`${WD} filling non-compete textarea`, label.slice(0, 60));
                workdayScrollToTarget(textarea, 120);
                await workdayTypeElement(textarea, text);
            } else if (!textarea && !isWorkdayYesNoFilled(container, 'No')) {
                // Non-compete as dropdown — default to "No"
                const ctrl = getContainerControl(container);
                if (ctrl) {
                    const filled = await fillWorkdaySingleSelectDropdown(ctrl, ['No'], labelLower)
                        || await fillWorkdayYesNoField(container, 'No');
                    if (filled) debugLog(`${WD} filled non-compete dropdown No`, label.slice(0, 60));
                }
            }
            await wait(500);
            continue;
        }

        if (/percentage.*travel|travel.*percentage|willing to travel/i.test(labelLower)) {
            debugLog(`${WD} filling empty travel`, value);
            const travelCtrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
            // Guidehouse etc. use a Yes/No-style prompt dropdown ("up to 25%"), not radios.
            if (travelCtrl && (travelCtrl.getAttribute?.('role') === 'combobox'
                || travelCtrl.getAttribute?.('aria-haspopup')
                || container.querySelector('input[role="combobox"], [data-automation-id="promptSelectionLabel"]'))) {
                clearWorkdaySingleSelectMissKey(label);
                clearWorkdaySingleSelectMissKey(labelLower);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelLower));
                const bands = ['up to 25%', 'Up to 25%', 'up to 50%', '20%', '25%', String(value)];
                await fillWorkdaySingleSelectDropdown(travelCtrl, bands, labelLower);
            } else {
                await fillWorkdayRadioGroup(container, value);
            }
            await wait(500);
            continue;
        }

        if (/^(yes|no)$/i.test(String(value))) {
            if (isWorkdayFormerEmployerQuestion(label)) {
                if (!isWorkdayFormerEmployerFilled(container, label) && !isWorkdayYesNoFilled(container, 'No')) {
                    await fillWorkdayAlwaysNoField(container, label);
                }
                await wait(300);
                continue;
            }
            if (!shouldUseBareYesNoForContainer(container, value, label)) {
                debugLog(`${WD} skip bare yes/no on multi-checkbox`, label.slice(0, 60), value);
                continue;
            }
            if (isWorkdayYesNoFilled(container, value)) continue;
            const filled = await fillWorkdayYesNoField(container, value);
            if (filled) debugLog(`${WD} filled empty yes/no`, label.slice(0, 60), value);
            await wait(500);
            continue;
        }

        if (isCompensationFieldLabel(labelLower)) {
            await fillWorkdayCompensationField(container, profile, label);
            await wait(500);
            continue;
        }

        if (isCountryOrCitizenshipFieldLabel(labelLower)) {
            const control = getContainerControl(container);
            if (control && !isCountryFilled(container, profile)) {
                debugLog(`${WD} filling citizenship/country dropdown`, label.slice(0, 60));
                await fillWorkdayCountryDropdown(control, profile);
            }
            await wait(500);
            continue;
        }

        if (/sex at birth|sex.*birth|biological sex/i.test(labelLower)) {
            const control = getContainerControl(container);
            if (control) {
                await fillWorkdaySingleSelectDropdown(control, getDisclosureSexAtBirthCandidates(), labelLower);
            }
            await wait(500);
            continue;
        }

        if (isWorkdayGenderIdentityField(label) || isWorkdayDisclosureGenderField(labelLower)) {
            // Never fill locally — profile has no gender; always resolved via the AI stream in
            // fillWorkdayFields (see chrome-extension.mdc "Gender / sex disclosure fields").
            continue;
        }

        if (isWorkdayVeteranFieldLabel(label)
            || /veteran status|protected veteran|select the veteran|identify as a veteran|\bare you a veteran\b/i.test(labelLower)) {
            if (!isWorkdayVeteranFilled(container)) {
                await fillWorkdayVeteranField(container, label, profile);
            }
            await wait(500);
            continue;
        }

        if (/ethnicity|\brace\b|what is your race|select one option below|you may select|select your race|select the race|please select your race/i.test(labelLower) && !isHispanicLatinoOnlyFieldLabel(labelLower)) {
            const ethCandidates = mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity);
            if (isDisclosureChoiceGroup(container)) {
                await fillWorkdayDisclosureChoiceGroup(container, ethCandidates);
            } else {
                const control = getContainerControl(container);
                if (control) await fillWorkdayRaceDropdown(control, profile, labelLower);
            }
            await wait(500);
            continue;
        }

        const control = getContainerControl(container);
        if (!control) continue;

        if (isWorkdayMaskedDateField(container, label)) {
            const dateVal = normalizeMMDDYYYY(value) || normalizeMMDDYYYY(getProfileFieldValue(profile, label));
            if (dateVal && (!isDateContainerFilled(container, dateVal) || isWorkdayDateFieldIncomplete(container))) {
                const ok = await fillWorkdayMaskedDate(container, control, dateVal, preview);
                debugLog(`${WD} filling empty date`, label.slice(0, 60), dateVal, 'ok=', ok);
            }
            await wait(500);
            continue;
        }

        if (isWorkdayClearanceFieldLabel(label)) {
            await fillWorkdayClearanceField(container, label);
            await wait(300);
            continue;
        }

        debugLog(`${WD} filling empty dropdown`, label.slice(0, 60), value);
        let candidates = /^(yes|no)$/i.test(String(value))
            ? (String(value).toLowerCase() === 'no' ? ['No', 'no'] : ['Yes', 'yes'])
            : (Array.isArray(value) ? value : [value]);
        if (/phone device type/i.test(label)) {
            clearWorkdaySingleSelectMissKey(label);
            candidates = getPhoneDeviceTypeCandidates();
        }
        if (isWorkdayAddressCityFieldLabel(label) || isWorkdayCityDropdownContainer(container, label)) {
            clearWorkdaySingleSelectMissKey(label);
            clearWorkdaySingleSelectMissKey('city');
            resetWorkdayDropdownOpenCount('city');
            resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
            const cityCands = getWorkdayCityDropdownCandidates(profile);
            if (cityCands.length) candidates = cityCands;
        }
        if (!await fillWorkdaySingleSelectDropdown(control, candidates, label)) {
            await fillWorkdayDropdown(control, candidates);
        }
        await wait(500);
    }
}

async function fillBasicProfileFields(profile, started) {
    return runWorkdayPhase('fillBasicProfileFields', async () => {
    if (isWorkdayAuthStepActive() || isWorkdayCreateAccountVisible()) {
        debugLog(`${WD} skip basic profile on auth/create account step`);
        return;
    }
    await pause();
    if (started && started != agentStatus.applyStarted) return;

    await closeWorkdayPopups();
    window.__wdHistoryLocation = window.__wdHistoryLocation || await getWorkdayJobLocation();
    const jobProfile = getProfileForJobLocation(profile);

    // Country first — Workday may reload the form after country change; fill before other fields.
    const countryChanged = await fixCountryForProfile(jobProfile);
    if (countryChanged) {
        debugLog(`${WD} country changed — waiting for form reload`);
        await waitForWorkdayFormReady();
        await wait(1000);
        window.__wdHearFilled = false;
        window.__wdHearAttempted = false;
        window.__wdHearSelectedLabel = '';
    }

    await fillKnownYesNoRadioFields(profile);
    await fixPhoneCodeForProfile(jobProfile);
    await fixStateForProfile(jobProfile);
    await fixPostalCodeForJobLocation(jobProfile);
    await fixPhoneNumberForRegion(jobProfile);

    await ensureHowDidYouHearFilled();
    const hearContainer = findHearAboutContainer();
    if (hearContainer) await blurAwayFromHearField(hearContainer);
    debugLog(`${WD} basic profile continue after hear`, 'hearOk=', isHearFillDone(hearContainer), 'selected=', getHearSelectedLabel(getHearPillText(hearContainer || {})).slice(0, 40));

    window.__wdHistoryLocation = window.__wdHistoryLocation || await getWorkdayJobLocation();
    const jobLocation = (window.__wdHistoryLocation || '').toLowerCase();

    const containers = getWorkdayFieldContainers().sort((a, b) => {
        const topDiff = a.getBoundingClientRect().top - b.getBoundingClientRect().top;
        if (Math.abs(topDiff) > 8) return topDiff;
        const la = getContainerLabel(a).toLowerCase();
        const lb = getContainerLabel(b).toLowerCase();
        const score = (label) => {
            if (isCountryFieldLabel(label)) return 0;
            if (isWorkdayStateFieldLabel(label)) return 2;
            if (/phone code/i.test(label)) return 4;
            if (/phone device type/i.test(label)) return 5;
            return 10;
        };
        return score(la) - score(lb);
    });

    let filled = 0;
    debugLog(`${WD} basic profile loop start`, containers.length, 'hearFilled=', window.__wdHearFilled);
    for (const container of containers) {
        const labelText = getContainerLabel(container);
        if (!labelText || SKIP_FIELD_LABELS.test(labelText) || shouldSkipConsentFieldForCollection(labelText, container)) continue;
        if (/preferred name/i.test(labelText)) continue;
        if (shouldSkipOptionalNameAffixField(container, labelText)) continue;
        if (/password|verify.*password|email address/i.test(labelText)) continue;
        if (/how did you hear/i.test(labelText)) continue;
        if (isWorkdayAvailabilityDateLabel(labelText)) continue;

        const value = getProfileFieldValue(profile, labelText);
        if (value === null || value === undefined) continue;
        if (value === '' && !isContainerRequired(container)) continue;

        try {
        debugLog(`${WD} basic profile fill`, labelText.slice(0, 60), '=', String(value).slice(0, 40));

        if (/^(yes|no)$/i.test(String(value))) {
            if (isWorkdayFormerEmployerQuestion(labelText)) {
                if (!isWorkdayFormerEmployerFilled(container, labelText)) {
                    const ok = await fillWorkdayFormerEmployerField(container, labelText);
                    debugLog(`${WD} basic profile former employer`, labelText.slice(0, 60), 'ok=', ok);
                    if (ok) filled += 1;
                }
                continue;
            }
            if (isWorkdayFormerEmployerAffiliateTextField(labelText)) {
                const ok = await fillWorkdayFormerEmployerAffiliateTextField(container, labelText);
                debugLog(`${WD} basic profile former-employer affiliate text`, labelText.slice(0, 60), 'ok=', ok);
                if (ok) filled += 1;
                continue;
            }
            if (!shouldUseBareYesNoForContainer(container, value, labelText)) {
                debugLog(`${WD} skip bare yes/no on multi-checkbox`, labelText.slice(0, 60), value);
                continue;
            }
            if (!isWorkdayYesNoFilled(container, value)) {
                const ok = await fillWorkdayYesNoField(container, value);
                debugLog(`${WD} basic profile yes/no`, labelText.slice(0, 60), value, 'ok=', ok);
                if (ok) filled += 1;
            }
            continue;
        }

        const radios = [...container.querySelectorAll('input[type="radio"]')];
        if (radios.length) {
            const target = String(value).toLowerCase();
            const optionLabel = [...container.querySelectorAll('label')].find(l => (l.innerText || '').trim().toLowerCase() === target);
            const radio = optionLabel ? document.getElementById(optionLabel.getAttribute('for')) : null;
            if (radio && !radio.checked) {
                radio.click();
                filled += 1;
            }
            continue;
        }

        const element = getContainerControl(container);
        if (!element || element.type === 'file') continue;
        const preview = container.innerText || '';
        const labelLower = labelText.toLowerCase();

        if (isWorkdayMaskedDateField(container, labelText) && /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(String(value))) {
            const dateVal = normalizeMMDDYYYY(value);
            if (dateVal && (!isDateContainerFilled(container, dateVal) || isWorkdayDateFieldIncomplete(container))) {
                const ok = await fillWorkdayMaskedDate(container, element, dateVal, preview);
                debugLog(`${WD} basic profile date`, labelText.slice(0, 60), dateVal, 'ok=', ok);
                if (ok) filled += 1;
            }
            continue;
        }

        if (isCompensationFieldLabel(labelLower)) {
            const needsRefill = !isCompensationFieldAcceptable(container, labelText, element)
                || /–|—/.test(element.value || '');
            if (needsRefill) {
                const ok = await fillWorkdayCompensationField(container, profile, labelText);
                debugLog(`${WD} basic profile compensation`, labelText.slice(0, 60), 'ok=', ok);
                if (ok) filled += 1;
            }
            continue;
        }

        const dropdownStillEmpty = /select one|0 items selected/i.test(preview) || /error:/i.test(preview);
        const dropdownTrigger = getWorkdayDropdownTrigger(container);
        // Address City is a searchable dropdown on some tenants (guidehouse.wd1) — typing
        // into the combobox without selecting an option leaves "required and must have a value".
        // Only treat City as plain text when there is no dropdown chrome.
        const cityIsDropdown = isWorkdayCityDropdownContainer(container, labelText);
        // Name, address and contact fields are usually text fills — never dropdowns,
        // even if the element has role="combobox" (Workday's autocomplete wrapper).
        // Exception: City when it is a real listbox/select-one widget.
        const isPlainTextField = element.tagName === 'INPUT' && element.type !== 'radio' && element.type !== 'checkbox'
            && (/first name|last name|middle name|given name|family name|suffix|address line|postal|zip|email/i.test(labelText)
                || (/^city$/i.test(labelText.replace(/\*/g, '').trim()) && !cityIsDropdown)
                || (/phone number/i.test(labelText) && !/code|type|extension/i.test(labelText)))
            && !isWorkdayJapanPostalSearchField(labelText);
        const isDropdownField = !isPlainTextField && (
            cityIsDropdown
            || dropdownTrigger
            || dropdownStillEmpty
            || element.getAttribute('aria-haspopup') === 'listbox'
            || element.getAttribute('role') === 'combobox'
            || element.tagName === 'BUTTON'
        );

        const isCountryField = isCountryOrCitizenshipFieldLabel(labelText);
        const isPhoneCodeField = /phone code/i.test(labelText);
        if (isCountryField && isCountryFilled(container, profile)) continue;
        if (isPhoneCodeField && isPhoneCodeFilledForProfile(container, profile)) continue;
        if (isWorkdayJapanPostalSearchField(labelText)) {
            const preview = container.innerText || '';
            if (/0 items selected|select one|must be 7 digits|valid format/i.test(preview)) {
                const ok = await fillWorkdayJapanPostalSearchField(container, getWorkdayPostalCodeValue(profile));
                if (ok) filled += 1;
            }
            continue;
        }

        if (/postal|zip/i.test(labelLower) && jobLocationExpectsJapanResidency()) {
            const postalValue = getWorkdayPostalCodeValue(profile);
            const current = (element.value || '').trim();
            if (postalValue && (current !== postalValue || /^n\/a$/i.test(current) || !isValidJapanPostalValue(current))) {
                workdayScrollToTarget(element, 120);
                wdSetInputValue(element, postalValue);
                filled += 1;
                await wait(300);
                continue;
            }
        }

        if (/^province$/i.test(labelLower.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
            if (!isWorkdaySingleSelectFilled(container, getSaudiProvinceCandidates())) {
                debugLog(`${WD} saudi province local fill`, labelText.slice(0, 60));
                if (await fillSaudiProvinceField(container, labelText)) filled += 1;
            }
            continue;
        }
        if (/^neighborhood$/i.test(labelLower.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
            const neighborhood = getSaudiNeighborhoodDefault();
            if (neighborhood && !(element.value || '').trim()) {
                await workdayTypeElement(element, neighborhood);
                debugLog(`${WD} saudi neighborhood local fill`, neighborhood);
                filled += 1;
            }
            continue;
        }

        if (!isCountryField && !isPhoneCodeField && element.value && element.type !== 'checkbox' && value !== '' && !dropdownStillEmpty
            && !/error:.*required and must have a value/i.test(preview)) continue;

        if (isDropdownField) {
            let dropdownValue = value;
            if (/how did you hear/i.test(labelText)) {
                dropdownValue = ['Job Board', 'Company Web Site', 'Social Network', 'LinkedIn', 'Internet', 'Social Media', 'Other'];
            } else if (isCountryField) {
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), isCitizenshipFieldLabel(labelText) ? 'citizenship' : 'country');
                if (await fillWorkdayCountryDropdown(dropdownTrigger || element, profile)) filled += 1;
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), isCitizenshipFieldLabel(labelText) ? 'citizenship' : 'country');
                continue;
            } else if (isWorkdayStateFieldLabel(labelText)) {
                continue;
            } else if (isWorkdayAddressCityFieldLabel(labelText) || cityIsDropdown) {
                // guidehouse.wd1: City is a searchable select — must commit an option, not type text.
                clearWorkdaySingleSelectMissKey(labelText);
                clearWorkdaySingleSelectMissKey('city');
                resetWorkdayDropdownOpenCount('city');
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelText));
                const cityCandidates = getWorkdayCityDropdownCandidates(profile);
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), cityCandidates[0]);
                const cityOk = await fillWorkdaySingleSelectDropdown(
                    dropdownTrigger || element,
                    cityCandidates.length ? cityCandidates : [value],
                    labelText,
                );
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'ok=', cityOk);
                if (cityOk) filled += 1;
                continue;
            } else if (/phone device type/i.test(labelText)) {
                clearWorkdaySingleSelectMissKey(labelText);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(labelText));
                const deviceCands = getPhoneDeviceTypeCandidates();
                const deviceTrigger = getWorkdayDropdownTrigger(container) || dropdownTrigger || element;
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), deviceCands[0]);
                const deviceOk = await fillWorkdaySingleSelectDropdown(deviceTrigger, deviceCands, labelText);
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'ok=', deviceOk);
                if (deviceOk) filled += 1;
                continue;
            } else if (isWorkdayCountyFieldLabel(labelText)) {
                // One open + multi-candidate match (UK borough from postcode). Avoid burning the
                // fillWorkdayDropdown 2-open budget on a non-matching meta-region like "Greater London".
                clearWorkdaySingleSelectMissKey(labelText);
                const countyCandidates = getCountyFillCandidates(profile);
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), countyCandidates[0]);
                const countyOk = await fillWorkdaySingleSelectDropdown(
                    dropdownTrigger || element,
                    countyCandidates,
                    labelText,
                );
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'ok=', countyOk);
                if (countyOk) filled += 1;
                continue;
            } else if (/ethnicity|\brace\b|what is your race|select one option below|you may select|select your race|select the race|please select your race/i.test(labelLower)
                && !isHispanicLatinoOnlyFieldLabel(labelLower)) {
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), 'race');
                if (isDisclosureChoiceGroup(container)) {
                    if (await fillWorkdayDisclosureChoiceGroup(container, mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity))) filled += 1;
                } else if (await fillWorkdayRaceDropdown(element, profile, labelLower)) {
                    filled += 1;
                }
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'race');
                continue;
            } else if (isWorkdayGenderIdentityField(labelText) || isWorkdayDisclosureGenderField(labelLower)) {
                // Never fill locally — profile has no gender; always resolved via the AI stream
                // in fillWorkdayFields (see chrome-extension.mdc "Gender / sex disclosure fields").
                continue;
            } else if (isPhoneCodeField) {
                debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), 'phone code');
                if (await fillWorkdayPhoneCodeDropdown(dropdownTrigger || element, profile)) filled += 1;
                debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'phone code');
                continue;
            }
            debugLog(`${WD} basic profile dropdown start`, labelText.slice(0, 60), dropdownValue);
            const dropdownOk = await fillWorkdayDropdown(dropdownTrigger || element, dropdownValue);
            debugLog(`${WD} basic profile dropdown done`, labelText.slice(0, 60), 'ok=', dropdownOk);
            if (dropdownOk) filled += 1;
            continue;
        }

        workdayScrollToTarget(element, 120);
        await workdayTypeElement(element, value);
        filled += 1;
        await wait(300);
        } catch (e) {
            logWorkdayException(`basic profile field: ${labelText.slice(0, 60)}`, e);
            throw e;
        }
    }
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!isWorkdayFormerEmployerQuestion(labelText)) continue;
        if (!isWorkdayFormerEmployerFilled(container, labelText)) {
            const ok = await fillWorkdayFormerEmployerField(container, labelText);
            debugLog(`${WD} basic profile former employer sweep`, labelText.slice(0, 60), 'ok=', ok);
            if (ok) filled += 1;
        }
    }
    debugLog(`${WD} basic profile fields filled:`, filled);
    await fixPreferredNameCheckbox(profile);
    if (!isWorkdayIntroduceYourselfPage() || !validateProfileLocationFields(jobProfile)) {
        await fillEmptyRequiredDropdowns(profile);
    }
    if (jobLocationExpectsJapanResidency()) {
        await fixJapanAddressFields(profile);
    }
    if (!validateProfileLocationFields(jobProfile) && !await ensureProfileLocationFields(profile)) {
        if (isWorkdayIntroduceYourselfPage()) {
            debugLog(`${WD} introduceYourself location retry`);
            await fixCountryForJobLocation(profile);
            await fixPhoneCodeForProfile(jobProfile);
            await ensureProfileLocationFields(profile);
        } else {
            throw new SendCvError('Country or phone code does not match profile');
        }
    }
    logEmptyRequiredFields();
    logFieldValues();
    });
}

function logFieldValues() {
    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!labelText) continue;
        const element = getContainerControl(container);
        const value = element?.value || (container.querySelector('input[type="radio"]:checked')?.value ?? '');
        const preview = (container.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 120);
        debugLog(`${WD} field value`, labelText, 'input=', value, 'preview=', preview);
    }
}

function getFormRoot() {
    return queryVisible('[data-automation-id="applyFlowPage"]')
        || queryVisible('[data-automation-id="jobApplicationPage"]')
        || document.querySelector('main')
        || document.body;
}

function getWorkdayFieldContainers() {
    const roots = [
        getFormRoot(),
        queryVisible('[data-automation-id="applyFlowPrimaryPage"]'),
        queryVisible('[data-automation-id="applicationBody"]'),
        document.body,
    ].filter(Boolean);
    const seen = new Set();
    const containers = [];
    for (const root of roots) {
        for (const el of root.querySelectorAll('[data-automation-id*="formField"]')) {
            if (seen.has(el)) continue;
            seen.add(el);
            containers.push(el);
        }
        if (containers.length) break;
    }
    return containers;
}

function getContainerLabel(container) {
    const labelEl = container.querySelector('label, legend, [data-automation-id="label"]');
    let labelText = (labelEl?.innerText || labelEl?.textContent || container.getAttribute('aria-label') || '').trim();
    if (!labelText) {
        const titleEl = container.querySelector('[data-automation-id*="formLabel"], p, span');
        labelText = (titleEl?.innerText || '').trim();
    }
    return labelText.replace(/\*/g, '').trim();
}

function getContainerControl(container) {
    return container.querySelector(
        'input:not([type="hidden"]), textarea, select, ' +
        'button[aria-haspopup="listbox"], button[aria-haspopup="true"], ' +
        '[role="combobox"], ' +
        '[data-automation-id="promptSelectionLabel"], ' +
        'button[data-automation-id="promptSelectionLabel"], ' +
        'button[data-automation-id="promptArrow"], ' +
        'button[data-automation-id="promptIcon"], ' +
        // Multi-select "checklist" widgets (rendered as "N items selected") use this trigger instead of
        // any combobox/button role — already relied on elsewhere for skills/major fields via dedicated
        // helpers, but this SHARED control resolver never included it. Any inline-entry field of this
        // widget type (e.g. a "Certification" or "Field of Study" multi-select inside an experience/
        // education/certification panel) hit `if (!control) continue;` in the generic fill loop and was
        // silently skipped forever — leaving a required field permanently empty and blocking Next
        // ("Workday step stuck: experience"/"disclosures") on every tenant using this widget, not one.
        '[data-automation-id="multiselectInputContainer"]'
    );
}

async function waitForWorkdayAuthFormReady(timeoutMs = 15000) {
    for (let i = 0; i < Math.ceil(timeoutMs / 200); i++) {
        if (isWorkdayCreateAccountVisible()) {
            notifyWorkdayCreateAccountAutofill();
        }
        if (isWorkdaySocialSignInGate() || isWorkdayEmailSignInGateway()) {
            debugLog(`${WD} auth form ready — SSO gate, opening email`, 'poll=', i + 1);
            await openWorkdayEmailSignInForm();
            if (getWorkdayAuthEmailInput()) return true;
        }
        if (getWorkdayAuthEmailInput()) {
            debugLog(`${WD} auth form ready`, 'poll=', i + 1);
            return true;
        }
        if (queryVisible('[data-automation-id="createAccountSubmitButton"]') && isWorkdayCreateAccountVisible()) {
            await wait(200);
            continue;
        }
        if (queryVisible('[data-automation-id="signInSubmitButton"]')) {
            debugLog(`${WD} auth form ready (sign-in submit)`, 'poll=', i + 1);
            return true;
        }
        await wait(200);
    }
    debugLog(`${WD} auth form ready (timeout)`);
    return false;
}

async function waitForWorkdayFormReady() {
    if (isWorkdayApplicationReviewStep()) {
        debugLog(`${WD} form ready — review step, skip field wait`);
        return true;
    }
    let lastCount = 0;
    let stable = 0;
    for (let i = 0; i < 50; i++) {
        if (isWorkdayAuthStepShell() || isWorkdayEmailSignInGateway()) {
            debugLog(`${WD} form ready — auth shell, skip field wait`, 'poll=', i + 1);
            return false;
        }
        if (isWorkdaySomethingWentWrongPage()) {
            await recoverWorkdaySomethingWentWrongPage();
            await wait(2000);
            continue;
        }
        const containers = getWorkdayFieldContainers();
        const controls = containers.map(getContainerControl).filter(Boolean);
        const count = controls.length;
        if (count === lastCount && count > 0) {
            stable += 1;
            // Require count stable ~1s (2 checks) with 2+ controls; single-control pages need ~2s.
            if (stable >= 2 && count >= 2) {
                debugLog(`${WD} form ready`, count, 'controls');
                return true;
            }
            if (stable >= 4 && count >= 1) {
                debugLog(`${WD} form ready (single control stable)`, count, 'controls');
                return true;
            }
        } else {
            stable = 0;
            lastCount = count;
        }
        await wait(500);
    }
    const controls = getWorkdayFieldContainers().map(getContainerControl).filter(Boolean);
    debugLog(`${WD} form ready (timeout)`, controls.length, 'controls');
    return controls.length > 0;
}

function collectWorkdayFields() {
    const fields = [];
    const excludedSection = [];
    const seen = new Set();

    getWorkdayFieldContainers().forEach(el => delete el.dataset.wdCollected);

    for (const container of getWorkdayFieldContainers()) {
        const labelText = getContainerLabel(container);
        if (!labelText || SKIP_FIELD_LABELS.test(labelText) || shouldSkipConsentFieldForCollection(labelText, container)) continue;
        if (/preferred name/i.test(labelText)) continue;
        if (shouldSkipOptionalNameAffixField(container, labelText)) continue;
        // Before always-no skip: free-text "enter N/A / Not Applicable if No" (micron.wd1 non-compete).
        if (isWorkdayNaIfNoTextField(labelText)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: getWorkdayNaIfNoTextValue(labelText, window.__wdApplyData?.profile),
            });
            continue;
        }
        if (isWorkdayPlaceOfResidenceField(labelText)) {
            const cands = getWorkdayPlaceOfResidenceCandidates(window.__wdApplyData?.profile);
            fields.push({
                element: getContainerControl(container) || getWorkdayDropdownTrigger(container) || container,
                type: 'select',
                label: labelText,
                required: isContainerRequired(container),
                options: cands.slice(0, 3),
                knownValue: cands[0],
            });
            continue;
        }
        if (isWorkdayVisaHoursPerWeekField(labelText)) {
            // Citizen path: do not push knownValue — answering triggers Visa expiry follow-up.
            if (workdayQuestionnaireIndicatesCitizen()) continue;
            fields.push({
                element: getContainerControl(container) || getWorkdayDropdownTrigger(container) || container,
                type: 'select',
                label: labelText,
                required: isContainerRequired(container),
                options: [],
                knownValue: getWorkdayVisaHoursPerWeekCandidates()[0],
            });
            continue;
        }
        if (isWorkdayVisaExpiryDateLabel(labelText)) {
            if (workdayQuestionnaireIndicatesCitizen()) continue;
            const d = new Date();
            d.setFullYear(d.getFullYear() + 3);
            const mm = String(d.getMonth() + 1).padStart(2, '0');
            const dd = String(Math.min(28, d.getDate())).padStart(2, '0');
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: `${mm}/${dd}/${d.getFullYear()}`,
            });
            continue;
        }
        if (isWorkdayAlwaysNoQuestion(labelText, container)) continue;
        if (isWorkdayClinicalSettingsQuestion(labelText)) continue;
        if (isWorkdayShiftAvailabilityQuestion(labelText)) continue;
        if (isWorkdayEmploymentTypeQuestion(labelText)) continue;
        if (isWorkdaySkillAbilityQuestion(labelText)) continue;
        if (isWorkdayBestContactTimeQuestion(labelText)) continue;
        if (isWorkdayAgeBand18SelectQuestion(labelText)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'select',
                label: labelText,
                required: isContainerRequired(container),
                options: getWorkdayAgeBand18Candidates(),
                knownValue: getWorkdayAgeBand18Candidates()[0],
            });
            continue;
        }
        if (isWorkdayTotalHoursPerWeekField(labelText)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: getWorkdayTotalHoursPerWeekValue(),
            });
            continue;
        }
        if (isWorkdayYearsExperienceBandQuestion(labelText)) {
            const band = getWorkdayYearsExperienceBandAnswer(labelText, null, window.__wdApplyData?.profile);
            if (band) {
                const ctrl = getContainerControl(container) || getWorkdayDropdownTrigger(container) || container;
                fields.push({
                    element: ctrl,
                    type: 'select',
                    label: labelText,
                    required: isContainerRequired(container),
                    options: [],
                    knownValue: band,
                });
                continue;
            }
        }
        if (isWorkdayPassportVisaTypeTextField(labelText)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: getWorkdayPassportVisaTypeTextValue(labelText, window.__wdApplyData?.profile),
            });
            continue;
        }
        if (isWorkdayRelativeConflictTextField(labelText, container)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: getWorkdayRelativeConflictTextValue(labelText, container),
            });
            continue;
        }
        if (isWorkdayLicenseFollowUpTextField(labelText, container)) {
            fields.push({
                element: getContainerControl(container) || container,
                type: 'text',
                label: labelText,
                required: isContainerRequired(container),
                knownValue: getWorkdayLicenseFollowUpTextValue(labelText, container),
            });
            continue;
        }
        if (isWorkdaySectionOnlyField(container, labelText)) {
            excludedSection.push(labelText);
            continue;
        }
        if (/^degree$/i.test(labelText.replace(/\*/g, '').trim()) && isDegreeFilled(container)) continue;
        if (/field of study|major|area of study/i.test(labelText) && shouldSkipFieldOfStudyRefill(container)) continue;
        if (/type to add skills|\bskills\b/i.test(labelText) && isSkillsMultiSelectFilled(container, 1)) continue;
        if (/\blanguages?\b/i.test(labelText) && isMultiSelectFilled(container)) continue;
        if (isWorkdayLockedYesNoField(labelText) && isWorkdayYesNoFieldLockedAndFilled(container, labelText)) continue;

        const element = getContainerControl(container);
        if (!element) continue;

        const key = `${labelText}::${element.id || element.name || element.tagName}`;
        if (seen.has(key)) continue;
        seen.add(key);

        if (element.type === 'file' || element.type === 'hidden') continue;

        if (isSelfIdentifyLocalField(labelText) || (getCurrentStepKey() === 'self_identify' && isSelfIdentifyLocalField(labelText))) {
            continue;
        }

        const labelLowerCollectEarly = labelText.toLowerCase();
        if (/by selecting.*i accept|data protection policy|consent to your data being stored/i.test(labelLowerCollectEarly)) {
            continue;
        }
        if (isWorkdayPrivacyConsentDropdownField(labelText, container)) {
            continue;
        }
        if (isWorkdaySmsConsentDropdownField(labelText, container)) {
            continue;
        }
        // Citizenship Status is a compound country-picker + "Citizen (<Country>)" checkbox widget
        // (fillWorkdayCitizenshipDropdown / fillVoluntaryDisclosures), not a plain select — its real
        // options are dynamic ("Citizen (United States of America)", "Citizen (India)", ...) so it can
        // never be usefully streamed as a flat options[] list. Worse, when it was ALREADY filled by that
        // local handler moments earlier in the same disclosures pass, collectWorkdayFields still re-added
        // it here with no options (falls through to the generic type detector as plain "text" once the
        // popup closes), the model correctly answered "N/A" for a required text field per its own
        // instructions, and that "N/A" then risked re-triggering a fill attempt against an
        // already-correctly-filled field — observed on cabrini.wd3, not tenant-specific (any tenant
        // rendering this Workday-standard citizenship-status widget on the disclosures/questions step).
        // Always rely on the dedicated local handler, same rationale as the consent-field skips above.
        if (isCitizenshipFieldLabel(labelText)) {
            continue;
        }

        if (/how did you hear/i.test(labelText)) {
            continue;
        }
        if (/^province$/i.test(labelLowerCollectEarly.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
            continue;
        }
        if (/^neighborhood$/i.test(labelLowerCollectEarly.replace(/\*/g, '').trim()) && jobLocationExpectsSaudiResidency()) {
            continue;
        }

        const required = isContainerRequired(container);
        const profile = window.__wdApplyData?.profile;

        if (isWorkdayGenderIdentityField(labelText) || isWorkdayDisclosureGenderField(labelText)) {
            if (isWorkdayDisclosureGenderFilled(container, labelText) || isDisclosureLocalFillDone(labelText)) continue;
            // Gender is never in the profile — always stream it, never guess Male/Female locally
            // (see chrome-extension.mdc "Gender / sex disclosure fields — never choose locally").
            fields.push({
                element,
                type: 'select',
                label: labelText,
                required,
                options: [],
            });
            continue;
        }
        // Ethnicity/Race multiSelects expose a plain Search <input> (no combobox/listbox role) —
        // without this, collect typed them as text and streamed without options (autodesk.wd1 Canada).
        if (isWorkdayRaceEthnicityFieldLabel(labelText) || /^ethnicity$/i.test(labelText.replace(/\*/g, '').trim())) {
            if (isWorkdayRaceFilled(container, profile?.general?.raceEthnicity) || isDisclosureLocalFillDone(labelText)) {
                continue;
            }
            const raceEl = container.querySelector('[data-automation-id="multiSelectContainer"] input')
                || container.querySelector('input[role="combobox"]')
                || getWorkdayDropdownTrigger(container)
                || element;
            fields.push({
                element: raceEl,
                type: 'select',
                label: labelText,
                required,
                options: [],
            });
            continue;
        }

        const labelLowerCollect = labelText.toLowerCase();
        if (/disability/i.test(labelLowerCollect) && /consider yourself|do you have a disability|select.*yes.*option/i.test(labelLowerCollect)) {
            const disabilityCandidates = ['No', 'No (India)', 'No, I Do Not Have A Disability', "No, I Don't Have A Disability", ...WORKDAY_DECLINE_PHRASES];
            if (isWorkdayDisclosureSelectionFilled(container, disabilityCandidates) || isDisclosureLocalFillDone(labelText)) continue;
            if (shouldFallbackDisclosureToStream(labelText, container, profile)) {
                fields.push({ element, type: 'select', label: labelText, required, options: [] });
            }
            continue;
        }

        if (isWorkdayStateFieldLabel(labelText)) {
            if (!required) {
                debugLog(`${WD} skip optional state field`);
                continue;
            }
            const stateVal = getConsistentUSStateForProfile(window.__wdApplyData?.profile);
            if (stateVal && isWorkdaySingleSelectFilled(container, [stateVal])) continue;
            if (stateVal) continue; // filled locally later via fillWorkdayField's isWorkdayStateFieldLabel branch
            // getConsistentUSStateForProfile only resolves US states — for any non-US profile (residency
            // country India, Canada, Australia, ...) it is always null here, and this used to fall through to
            // a bare `continue` unconditionally, so the field was NEVER added to `fields` and never streamed to
            // the AI at all. The State/Province dropdown then stayed permanently on "Select One" for every
            // non-US applicant on every tenant that renders a required State control for their country (see
            // chrome-extension.mdc Workday step stuck: information — generalizable, not tenant-specific). Queue
            // it like any other combobox so the model can pick a real state/province option for the country.
            if (isWorkdayStateFieldFilled(container)) continue;
            // Sending options:[] here left the model choosing blind — with zero real options to constrain
            // against, streamVacancyFields either timed out/aborted (retry-no-response) or occasionally
            // returned a non-option placeholder like "Decline to answer" (observed on uline.wd1: a non-US
            // profile applying to a US job, State field streamed with withOptions:0, response unusable both
            // ways across repeated step retries — not tenant-specific, hits any tenant with a required State
            // control whenever a live DOM option read isn't available at collect time). The Workday US State
            // dropdown is a fixed, well-known list regardless of tenant, so seed it directly instead of
            // depending on a live open (which also competes with the 2-open budget in
            // enrichSelectFieldsWithOptions/fillWorkdayStateDropdown).
            fields.push({ element, type: 'select', label: labelText, required, options: WORKDAY_US_STATE_OPTIONS });
            continue;
        }
        let knownValue = getProfileFieldValue(window.__wdApplyData?.profile || {}, labelText);
        if (isWorkdayClinicalSettingsQuestion(labelText) || isWorkdayShiftAvailabilityQuestion(labelText)) {
            knownValue = null;
        }
        if (knownValue != null && isWorkdayEeoDisclosureField(labelText)
            && shouldFallbackDisclosureToStream(labelText, container, window.__wdApplyData?.profile)) {
            knownValue = null;
        }
        const elementForSalary = element;
        if (knownValue != null && isCompensationFieldLabel(labelText)
            && isNumericCompensationField(labelText, elementForSalary)) {
            knownValue = getWorkdayNumericSalaryValue(window.__wdApplyData?.profile, labelText, elementForSalary);
        }
        if (knownValue != null && isCompensationFieldLabel(labelText) && elementForSalary?.value
            && /too large|number entered is too large/i.test(container.innerText || '')) {
            knownValue = getWorkdayNumericSalaryValue(window.__wdApplyData?.profile, labelText, elementForSalary);
        }
        // Deterministic Yes/No at collect (consent / always-no / school-id interrogatives) so the field
        // never streams free-text against options:[] and never burns the 2-open budget on a miss.
        // Gender/EEO stay streamed — never guess Male/Female locally.
        if ((knownValue === null || knownValue === undefined || knownValue === '')
            && !isWorkdayEeoDisclosureField(labelText)
            && !isWorkdayVeteranFieldLabel(labelText)
            && !isWorkdayDisclosureGenderField(labelText)
            && !isWorkdayGenderIdentityField(labelText)) {
            const ynKnown = getWorkdayYesNoSmartDefault(labelText);
            if (ynKnown) knownValue = ynKnown;
        }
        if (shouldStreamWorkdayQuestionField(labelText, container)) {
            knownValue = null;
        }

        if (knownValue === '' && !required && /middle name|address line 2|phone extension|georgian given|georgian family/i.test(labelText)) {
            continue;
        }

        if (/^(yes|no)$/i.test(String(knownValue)) && isWorkdayYesNoFilled(container, knownValue)) continue;
        // Check if this field has a Workday validation error (React state not synced)
        const previewText = (container.innerText || '').replace(/\s+/g, ' ');
        const hasFieldError = !!container.querySelector('[data-automation-id="errorMessage"], [class*="errorMessage"]')
            || /error:.*required and must have a value/i.test(previewText);
        if (knownValue !== null && knownValue !== undefined && element.type !== 'radio' && element.type !== 'checkbox' && element.value && !hasFieldError) {
            continue;
        }
        if (knownValue !== null && knownValue !== undefined && element.type !== 'radio' && element.type !== 'checkbox' && knownValue !== '') {
            // Will be filled locally; skip AI unless select/radio
        } else if (element.value && element.type !== 'radio' && element.type !== 'checkbox' && !hasFieldError) {
            continue;
        }

        if (element.type === 'radio' || element.type === 'checkbox') {
            if (container.dataset.wdCollected) continue;
            container.dataset.wdCollected = '1';

            // Collect all option labels and input elements in this group
            const optionLabels = [...container.querySelectorAll('label')].filter(l => {
                const t = (l.innerText || '').trim();
                return t && t !== labelText;
            });
            const options = optionLabels.map(l => (l.innerText || '').trim()).filter(Boolean);
            const elements = optionLabels.map(l => {
                const id = l.getAttribute('for');
                return id ? document.getElementById(id) : l.querySelector('input');
            }).filter(Boolean);

            // For single yes/no radio: handle locally if already known, skip if filled
            if (element.type === 'radio' || options.length <= 2) {
                const yesNoValue = getProfileFieldValue(window.__wdApplyData?.profile || {}, labelText);
                if (/^(yes|no)$/i.test(String(yesNoValue))) {
                    if (isWorkdayYesNoFilled(container, yesNoValue)) continue;
                    continue; // will be filled by fillKnownYesNoRadioFields
                }
                if (container.querySelector('input[type="radio"]:checked, input[type="checkbox"]:checked')) continue;
                // Single checkbox (consent/acknowledge) — skip, handled by checkboxes loop
                if (options.length <= 1 && element.type === 'checkbox') continue;
            }

            // Multi-option checkbox group (ethnicity, race, veteran, etc.)
            if (options.length <= 1) continue;
            if (isWorkdayEeoDisclosureField(labelText)) {
                const profile = window.__wdApplyData?.profile;
                if (isDisclosureLocalFillDone(labelText)) {
                    debugLog(`${WD} collect skip local disclosure`, labelText.slice(0, 60));
                    continue;
                }
                if (isWorkdayEeoCheckboxGroupFilled(container, labelText, profile)) {
                    debugLog(`${WD} collect skip filled disclosure checkbox`, labelText.slice(0, 60));
                    markDisclosureLocalFilled(labelText);
                    continue;
                }
            } else {
                const anyChecked = container.querySelector(
                    'input[type="checkbox"]:checked, [role="checkbox"][aria-checked="true"]'
                );
                if (anyChecked && required) continue;
            }
            if (!options.length) continue;
            fields.push({
                element: elements.length ? elements : [element],
                type: 'checkbox',
                label: labelText.split('\n')[0].trim(),
                required,
                options,
            });
            continue;
        }

        if (element.getAttribute('aria-haspopup') === 'listbox' || element.getAttribute('role') === 'combobox' || element.tagName === 'BUTTON') {
            if (/how did you hear/i.test(labelText)) continue;
            if (/^(yes|no)$/i.test(String(knownValue)) && isWorkdayYesNoFilled(container, knownValue)) {
                continue;
            }
            if (knownValue !== null && knownValue !== undefined && knownValue !== '') {
                const preview = container.innerText || '';
                // Only skip if clearly filled and no validation error present
                const hasDropdownError = !!container.querySelector('[data-automation-id="errorMessage"]')
                    || /is required and must have a value/i.test(preview)
                    || (window.__wdBlockedRequiredLabels && window.__wdBlockedRequiredLabels.has(labelText.toLowerCase()));
                if (!/select one|0 items selected/i.test(preview) && !hasDropdownError) continue;
            }
            fields.push({
                element,
                type: 'select',
                label: labelText,
                required,
                options: [],
                ...(knownValue !== null && knownValue !== undefined && knownValue !== '' ? { knownValue: String(knownValue) } : {}),
            });
            continue;
        }

        // For text/textarea fields with a known value: include them in fields with knownValue set
        // so fillWorkdayField can fill them directly. Skip streaming to AI for these fields.
        // Only skip entirely if value is already visible in the field with no error.
        if (knownValue !== null && knownValue !== undefined) {
            if (knownValue === '') {
                if (!required) continue;
                // A required field whose deterministic mapping resolved to "" (e.g. postal code
                // when the profile has no explicit zip) must NOT be locked in as knownValue: ''.
                // Doing so both (a) types nothing via the local fill path and (b) makes
                // workdayStreamVacancyFields treat the field as "already resolved", permanently
                // skipping AI streaming — guaranteeing the required field stays blank and the step
                // gets stuck (see chrome-extension.mdc Missing/insufficient profile data). Fall
                // through to the generic AI-streamed field below instead, so the model can derive a
                // plausible value from related profile facts (e.g. city -> postal code).
            } else {
                const alreadyFilled = element.value && !hasFieldError;
                if (!alreadyFilled) {
                    fields.push({
                        element,
                        type: element.tagName === 'TEXTAREA' ? 'textarea' : (element.type || 'text'),
                        label: labelText,
                        required,
                        knownValue: String(knownValue),
                    });
                }
                continue;
            }
        }

        fields.push({
            element,
            type: element.tagName === 'TEXTAREA' ? 'textarea' : (element.type || 'text'),
            label: labelText,
            required,
        });
    }

    debugLog(`${WD} collected fields`, fields.map(f => f.label));
    if (excludedSection.length) {
        debugLog(`${WD} excluded section fields`, [...new Set(excludedSection)].join(' | '));
    }
    return fields;
}

async function withHearDirectFill(fn) {
    window.__wdHearDirectFill = true;
    try {
        return await fn();
    } finally {
        window.__wdHearDirectFill = false;
    }
}

async function fillWorkdayDropdown(element, value) {
    if (!element || value === undefined || value === null) return false;
    const fieldRoot = element.closest?.('[data-automation-id*="formField"]') || element.parentElement;
    const labelLower = getContainerLabel(fieldRoot || element).toLowerCase();
    if (!window.__wdHearDirectFill && /how did you hear/i.test(labelLower)) {
        if (isHearFillDone(fieldRoot) || hasExplicitHearSelection(fieldRoot)) return true;
        return ensureHowDidYouHearFilled();
    }
    const values = Array.isArray(value) ? value : [value];
    for (const candidate of values) {
        if (await fillWorkdayDropdownOnce(element, candidate)) return true;
    }
    return false;
}

function isWrongOptionSample(sample, labelLower) {
    if (!sample) return false;
    if (isWorkdayStateFieldLabel(labelLower)) {
        if (/(\(\+\d\)|phone code|press delete to clear)/i.test(sample)) return true;
        if (/united states of america \(\+1\)/i.test(sample) && !/\bcalifornia\b|\balabama\b|\bselect one\b/i.test(sample)) return true;
    }
    if (/country.*territory/i.test(labelLower) && !/phone/i.test(labelLower) && /(\(\+\d\)|alabama|alaska)/i.test(sample)) return true;
    if (/phone code/i.test(labelLower) && /\bcalifornia\b|\balabama\b|\bselect one\b/i.test(sample) && !/\(\+\d\)/i.test(sample)) return true;
    // The Phone Code popup can stay open/targeted by a stale trigger reference and get mistaken for the
    // Phone Device Type popup's own options (both fields commonly sit right next to each other in the
    // phone field group) — not tenant-specific, hits any tenant that renders both fields adjacently
    // (observed on icf.wd5: "Phone Device Type" dropdown open kept returning
    // ["United States of America (+1)", ...] instead of ["Personal Cell","Work Cell",...], so no
    // candidate ever matched and the underlying combobox got a speculative setNativeValue that was never
    // actually committed via a real option click — see fillWorkdayDropdownOnce).
    if (/phone device type/i.test(labelLower) && /\(\+\d\)|united states of america/i.test(sample)) return true;
    // Hear-about listbox (Indeed/LinkedIn/…) can still be globally active after hear lock; must not
    // be treated as Phone Device Type options (solenis.wd1: match "indeed" from "personal cell").
    if (/phone device type/i.test(labelLower)
        && /indeed|linkedin|job board|company website|referral|campus event|social network|employee referral|how did you hear/i.test(sample)
        && !/personal cell|work cell|\bmobile\b|\btelephone\b|\bcellular\b/i.test(sample)) {
        return true;
    }
    // Same hear-about ghost popup after ensureHowDidYouHearFilled — City (bah.wd1) and other address
    // dropdowns were scanning ["indeed"] as their option list, burning the 2-open budget with no match
    // while the combobox still showed typed text + "required and must have a value".
    if ((isWorkdayAddressCityFieldLabel(labelLower) || /^city$/i.test(String(labelLower || '').replace(/\*/g, '').trim())
            || isWorkdayStateFieldLabel(labelLower) || isWorkdayCountyFieldLabel(labelLower))
        && /indeed|linkedin|job board|company website|referral|campus event|social network|employee referral|how did you hear|glassdoor|career builder/i.test(sample)
        && !/\bselect one\b|\balabama\b|\balaska\b|\bcalifornia\b|\bflorida\b|\bjacksonville\b|\bnew york\b|\blondon\b/i.test(sample)) {
        return true;
    }
    if (/non-compete|non-solicit|non-disclosure/i.test(labelLower) && /(\(\+\d\)|phone code|press delete to clear)/i.test(sample)) return true;
    if (/how did you hear/i.test(labelLower)) {
        if (/(\(\+\d{1,4}\)|united states.*\(\+1\)|georgia \(\+)/i.test(sample)) return true;
        if (/\(\+\d{1,4}\)/.test(sample) && !/campus event|job board|company web|social network|linkedin|indeed|referral|other/i.test(sample)) {
            return true;
        }
    }
    if (/field of study|major|area of study/i.test(labelLower)) {
        if (/press delete to clear|community college|items selected|gulf coast/i.test(sample)) return true;
    }
    if (/skills|type to add skills/i.test(labelLower)) {
        if (/press delete to clear|community college|gulf coast|items selected/i.test(sample)) return true;
    }
    if (isWorkdayClinicalSettingsQuestion(labelLower)) {
        if (/completed step|my information|my experience|application questions|current step|step \d+ of/i.test(sample)) {
            return true;
        }
    }
    return false;
}

function isWrongPopupForField(popup, labelLower) {
    if (!popup) return false;
    const sample = getScopedDropdownOptions(popup).slice(0, 8).map(optionText).join(' ').toLowerCase();
    return isWrongOptionSample(sample, labelLower);
}

async function fillWorkdayDropdownOnce(element, value) {
    if (!element || !value) return false;
    const fieldRoot = element.closest('[data-automation-id*="formField"]') || element.parentElement;
    const labelLower = getContainerLabel(fieldRoot || element).toLowerCase();
    if (isCommuteTimeFieldLabel(labelLower)) {
        const resolved = resolveStreamValueToDropdownOption(value, WORKDAY_COMMUTE_TIME_OPTIONS, labelLower)
            || getWorkdayStreamLocalFallback(labelLower, WORKDAY_COMMUTE_TIME_OPTIONS);
        if (resolved) value = resolved;
    }
    const openKey = normalizeDropdownOpenKey(labelLower);
    if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
        debugLog(`${WD} dropdown skip excess opens`, openKey.slice(0, 50), 'count=', wdDropdownOpenCounts[openKey]);
        return isWorkdaySingleSelectFilled(fieldRoot, [value]) || isWorkdayYesNoFilled(fieldRoot, value);
    }
    if (shouldSkipOptionalNameAffixField(fieldRoot, labelLower)) {
        debugLog(`${WD} dropdown skip optional affix`, labelLower.slice(0, 40));
        return true;
    }
    const strVal = String(Array.isArray(value) ? value[0] : value).trim();
    if (/^(yes|no)$/i.test(strVal)) {
        return fillWorkdaySingleSelectDropdown(element, [strVal], labelLower || 'yes-no');
    }
    if (!window.__wdHearDirectFill && /how did you hear/i.test(labelLower)) {
        if (isHearFillDone(fieldRoot)) return true;
        if (window.__wdHearFillInProgress) return false;
        return ensureHowDidYouHearFilled();
    }
    if (isCitizenshipFieldLabel(labelLower)) {
        return fillWorkdayCitizenshipDropdown(
            element.closest('[data-automation-id*="formField"]') || element.parentElement,
            window.__wdApplyData?.profile || {},
        );
    }
    if (isCountryFieldLabel(labelLower)) {
        return fillWorkdayCountryDropdown(element, window.__wdApplyData?.profile || {});
    }
    if (/phone code/i.test(labelLower)) {
        return fillWorkdayPhoneCodeDropdown(element, window.__wdApplyData?.profile || {});
    }
    if (/field of study|major|area of study/i.test(labelLower)) {
        const entry = window.__wdApplyData?.profile?.educations?.[0] || {};
        if (shouldSkipFieldOfStudyRefill(fieldRoot || element, entry)) return true;
        const studyValue = Array.isArray(value) ? value[0] : value;
        return fillWorkdayFieldOfStudyDropdown(element, entry, studyValue);
    }
    await closeWorkdayPopups();
    // `element` here already comes from getContainerControl() on THIS field's own narrow container, so
    // when it's itself a clickable trigger it is the more reliable target. `getWorkdayDropdownTrigger
    // (fieldRoot)` re-derives a trigger via `fieldRoot.querySelector('button, ...')`, and `fieldRoot`
    // (element.closest('[data-automation-id*="formField"]')) can resolve to a shared ancestor spanning
    // several adjacent controls (e.g. the whole phone field group: Country Phone Code + Phone Device
    // Type + Phone Number) — querySelector then returns the FIRST matching button in that broader scope,
    // which can belong to a sibling field, not this one. Observed on icf.wd5: clicking "Phone Device
    // Type"'s derived trigger kept opening the "Country Phone Code" popup instead — not tenant-specific,
    // hits any tenant whose phone fields share a formField ancestor.
    const isDirectTrigger = element.tagName === 'BUTTON'
        || element.getAttribute?.('role') === 'combobox'
        || element.getAttribute?.('aria-haspopup');
    const button = isDirectTrigger ? element : (fieldRoot ? getWorkdayDropdownTrigger(fieldRoot) : element);
    const isMultiSelect = /items selected/i.test(fieldRoot?.innerText || '');
    workdayScrollToTarget(element, 120);
    trackWorkdayDropdownOpen(labelLower || 'dropdown');
    await workdayClick(button || element);
    element.focus();
    await wait(1000);

    // getScopedDropdownOptions() below falls back to findActiveWorkdayPopup()/document whenever the
    // popup arg is null/undefined — so a null `popup` here is NOT "no popup to worry about", it means
    // whatever listbox is globally active (e.g. a stale, not-yet-closed Phone Code popup from the
    // previous field in the same phone field group) will get scanned instead. isWrongPopupForField(null,
    // ...) short-circuits to false, so the null case must be resolved to the same fallback scope before
    // validating, otherwise a stale unrelated popup's options sail through unchecked (observed on
    // icf.wd5: "Phone Device Type" got the just-closed "Country Phone Code" popup's options every time —
    // not tenant-specific, hits any tenant where these two fields sit adjacently and findPopupNearField
    // can't resolve a popup scoped to the second field specifically).
    let popup = findPopupNearField(fieldRoot, labelLower);
    const resolvePopup = () => popup || findActiveWorkdayPopup();
    if (!resolvePopup() || isWrongPopupForField(resolvePopup(), labelLower)) {
        await closeWorkdayPopups();
        await wait(300);
        await workdayClick(button || element);
        element.focus();
        await wait(1000);
        popup = findPopupNearField(fieldRoot, labelLower);
    }
    // Missing popup OR wrong sibling popup — never setNativeValue. Stamping "Personal Cell" /
    // "Mobile" without a real option click leaves Select One forever while input.value looks filled
    // (entegris.wd1 Phone Device Type; icf.wd5 Phone Code bleed).
    if (!resolvePopup() || isWrongPopupForField(resolvePopup(), labelLower)) {
        debugLog(`${WD} dropdown wrong/missing popup`, labelLower.slice(0, 50));
        await closeWorkdayPopups();
        return false;
    }

    const searchInput = resolvePopup()?.querySelector('input')
        || fieldRoot?.querySelector('input[placeholder*="Search" i], input[aria-label*="Search" i]');
    if (searchInput) {
        setNativeValue(searchInput, Array.isArray(value) ? value[0] : value);
        searchInput.dispatchEvent(new Event('input', { bubbles: true }));
    } else if (!isMultiSelect) {
        setNativeValue(element, Array.isArray(value) ? value[0] : value);
    }
    await wait(1000);

    popup = findPopupNearField(fieldRoot, labelLower) || popup;
    const options = filterDropdownOptionsForField(
        getScopedDropdownOptions(popup), labelLower, window.__wdApplyData?.profile,
    );
    // Check the SAME option elements that are about to be matched against, not a separately re-fetched
    // popup reference — findActiveWorkdayPopup()/getScopedDropdownOptions()'s internal document-wide
    // fallback is timing-sensitive (a stale popup can appear "gone" for one check and "visible" a moment
    // later), so re-deriving "popup" and checking it separately from `options` let a wrong popup's
    // content slip through undetected on icf.wd5 even with earlier checks in place. Validating the exact
    // `options` array closes that race for any tenant hitting the same adjacent-field popup bleed-through.
    const optionsSample = options.slice(0, 8).map(optionText).join(' ').toLowerCase();
    if (isWrongOptionSample(optionsSample, labelLower)) {
        debugLog(`${WD} dropdown wrong popup persists`, labelLower.slice(0, 50), 'at match time', optionsSample.slice(0, 80));
        await closeWorkdayPopups();
        return false;
    }
    const target = String(Array.isArray(value) ? value[0] : value).toLowerCase();
    let match = findDropdownMatch(options, target, labelLower);
    if (!match && isWorkdayCountyFieldLabel(labelLower)) {
        match = resolveCountyOptionAgainstList(options, window.__wdApplyData?.profile || {});
        if (match) {
            debugLog(`${WD} dropdown county resolved`, target.slice(0, 40), '->', optionText(match));
        }
    }

    if (match) {
        const combobox = fieldRoot?.querySelector('input[role="combobox"]');
        if (match.getAttribute('data-automation-id') === 'menuItem' || match.getAttribute('role') === 'option') {
            await clickWorkdayOption(match);
        } else {
            await workdayClick(match);
        }
        await wait(isMultiSelect ? 800 : 500);
        if (!isMultiSelect) {
            const displayText = String(Array.isArray(value) ? value[0] : value);
            const dataValue = match.getAttribute('data-value') || extractWorkdayOptionValue(match);
            // Always try to commit via combobox if available; otherwise commit via hidden inputs
            if (combobox) {
                await commitWorkdayComboboxSelection(fieldRoot, combobox, match, displayText);
            } else if (dataValue) {
                // No combobox — try to set value on hidden inputs directly
                for (const inp of (fieldRoot?.querySelectorAll('input[type="hidden"]') || [])) {
                    setNativeValue(inp, dataValue);
                    inp.dispatchEvent(new Event('change', { bubbles: true }));
                }
            }
        }
        if (isMultiSelect) {
            const label = getContainerLabel(fieldRoot || element);
            if (/how did you hear/i.test(label)) {
                await commitHearSelection(fieldRoot || element);
                return isMultiSelectFilled(fieldRoot || element);
            }
            const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
            if (pageTitle) await workdayClick(pageTitle);
            await wait(500);
            return !/select one|0 items selected/i.test(fieldRoot?.innerText || '');
        }
        await closeWorkdayPopups();
        const preview = fieldRoot?.innerText || '';
        return !/select one|0 items selected/i.test(preview) && !/error:/i.test(preview);
    }

    debugLog(`${WD} dropdown no match`, value, 'options=', options.slice(0, 8).map(o => (o.innerText || '').trim()));
    await closeWorkdayPopups();
    return false;
}

async function openDropdownAndGetOptions(element) {
    await closeWorkdayPopups();
    const fieldRoot = element.closest?.('[data-automation-id*="formField"]') || element;
    const button = getWorkdayDropdownTrigger(fieldRoot);
    button?.click();
    element.focus?.();
    await wait(1200);
    const options = [...document.querySelectorAll('[role="option"], [data-automation-id*="menuItem"]')]
        .map(el => (el.innerText || el.textContent || '').trim())
        .filter(Boolean);
    await closeWorkdayPopups();
    await wait(500);
    return [...new Set(options)];
}

/** Closest DOM ancestor that contains every element in the list (tightest common wrapper). */
function closestCommonAncestorEl(elements) {
    const list = (Array.isArray(elements) ? elements : [elements]).filter(Boolean);
    if (!list.length) return null;
    let ancestor = list[0];
    for (let i = 1; i < list.length; i++) {
        while (ancestor && !ancestor.contains(list[i])) {
            ancestor = ancestor.parentElement;
        }
    }
    return ancestor;
}

async function fillWorkdayField(field, started) {
    let fieldContainer = (Array.isArray(field.element) ? field.element[0] : field.element)
        ?.closest?.('[data-automation-id*="formField"]') || field.element;
    // A checkbox-group follow-up (e.g. "Have you ever worked at X in the following capacity:")
    // can be nested inside the SAME [data-automation-id*="formField"] wrapper as its unrelated
    // parent Yes/No radio question (e.g. "Have you been employed by X in the past?") when Workday
    // does not tag the checkbox sub-panel with its own formField id. .closest() then overshoots and
    // returns a container holding BOTH questions' controls. Every "already filled"/"exclusive
    // checkbox" check below scans this container for a checked radio/checkbox, so the sibling
    // question's checked "No" radio gets misread as *this* field's answer — the checkbox group is
    // reported filled while still empty in the DOM, and Workday's own validation keeps rejecting
    // Next ("is required and must have a value"), causing an endless re-stream loop and
    // "Workday step stuck: questions". Narrow to the tightest wrapper of just this field's own
    // elements whenever the resolved container also holds a foreign radio.
    if (Array.isArray(field.element) && field.element.length >= 2 && fieldContainer) {
        const foreignRadios = [...fieldContainer.querySelectorAll('input[type="radio"]')]
            .filter(r => !field.element.includes(r));
        if (foreignRadios.length) {
            const tight = closestCommonAncestorEl(field.element);
            if (tight && tight !== fieldContainer && !tight.querySelector('input[type="radio"]')) {
                debugLog(`${WD} narrow field container away from foreign radio`, field.label.slice(0, 60));
                fieldContainer = tight;
            }
        }
    }
    if (isWorkdayLockedYesNoField(field.label) && isWorkdayYesNoFieldLockedAndFilled(fieldContainer, field.label)) {
        debugLog(`${WD} skip fill locked yes/no`, field.label.slice(0, 60));
        return true;
    }
    const affixContainer = fieldContainer;
    if (shouldSkipOptionalNameAffixField(affixContainer, field.label)) {
        debugLog(`${WD} skip optional affix field`, field.label.slice(0, 40));
        return true;
    }
    if (started && started != agentStatus.applyStarted) return false;

    if (isWorkdaySectionOnlyField(fieldContainer, field.label)) {
        debugLog(`${WD} skip section-managed field`, field.label);
        return false;
    }

    if (/field of study|major|area of study/i.test(field.label)) {
        const studyEntry = window.__wdApplyData?.profile?.educations?.[0] || {};
        if (shouldSkipFieldOfStudyRefill(fieldContainer, studyEntry)) {
            debugLog(`${WD} skip committed field of study`, field.label.slice(0, 60));
            return true;
        }
    }

    if (/how did you hear/i.test(field.label)) {
        const container = field.element.closest?.('[data-automation-id*="formField"]') || field.element;
        if (isHearFillDone(container)) return true;
        if (window.__wdHearFillInProgress) return false;
        return ensureHowDidYouHearFilled();
    }

    // If field has a pre-computed knownValue (from getProfileFieldValue), use it directly
    // without waiting for AI response (handles text fields with required errors)
    if (isWorkdayClinicalSettingsQuestion(field.label)) {
        const ok = await fillWorkdayClinicalSettingsField(fieldContainer, field.label, window.__wdApplyData?.profile);
        if (ok) {
            debugLog(`${WD} filled clinical settings`, field.label.slice(0, 60));
            return true;
        }
    }
    if (isWorkdayShiftAvailabilityQuestion(field.label)) {
        const ok = await fillWorkdayShiftAvailabilityField(fieldContainer, field.label);
        if (ok) {
            debugLog(`${WD} filled shift availability`, field.label.slice(0, 60));
            return true;
        }
    }
    if (field.knownValue !== undefined && field.knownValue !== null && String(field.knownValue).trim()) {
        if (field.type === 'checkbox' || (field.type === 'radio' && isDisclosureChoiceGroup(fieldContainer))) {
            const labelLower = field.label.toLowerCase();
            if (isWorkdayClinicalSettingsQuestion(field.label)) {
                const ok = await fillWorkdayClinicalSettingsField(fieldContainer, field.label, window.__wdApplyData?.profile);
                if (ok) {
                    debugLog(`${WD} filled clinical settings checkbox`, field.label.slice(0, 60));
                    return true;
                }
            }
            if (isWorkdayShiftAvailabilityQuestion(field.label)) {
                const ok = await fillWorkdayShiftAvailabilityField(fieldContainer, field.label);
                if (ok) {
                    debugLog(`${WD} filled shift availability checkbox`, field.label.slice(0, 60));
                    return true;
                }
            }
            if (isWorkdayFormerEmployerQuestion(field.label)) {
                const ok = await fillWorkdayFormerEmployerField(fieldContainer, field.label);
                if (ok) {
                    debugLog(`${WD} filled former employer checkbox`, field.label.slice(0, 60));
                    return true;
                }
            }
            if (isWorkdayEeoDisclosureField(field.label) && isDisclosureChoiceGroup(fieldContainer)) {
                const profile = window.__wdApplyData?.profile;
                if (isDisclosureLocalFillDone(field.label)
                    || isWorkdayEeoCheckboxGroupFilled(fieldContainer, field.label, profile)) {
                    return true;
                }
                const choiceCandidates = /race|ethnicity/i.test(labelLower)
                    ? mapProfileRaceToWorkdayCandidates(profile?.general?.raceEthnicity)
                    : /veteran/i.test(labelLower)
                        ? getVeteranStatusCandidates()
                        : [String(field.knownValue)];
                const ok = await fillWorkdayExclusiveCheckboxGroup(fieldContainer, choiceCandidates, { label: field.label });
                if (ok) {
                    markDisclosureLocalFilled(field.label);
                    debugLog(`${WD} filled checkbox group with knownValue`, field.label.slice(0, 60));
                    return true;
                }
                if (isWorkdayEeoDisclosureField(field.label)) {
                    markDisclosureStreamFallback(field.label);
                }
                return false;
            }
            const choiceCandidates = /veteran/i.test(labelLower)
                ? getVeteranStatusCandidates()
                : /race|ethnicity/i.test(labelLower)
                    ? mapProfileRaceToWorkdayCandidates(window.__wdApplyData?.profile?.general?.raceEthnicity)
                    : [String(field.knownValue)];
            const ok = await fillWorkdayDisclosureChoiceGroup(fieldContainer, choiceCandidates);
            if (ok) {
                debugLog(`${WD} filled checkbox group with knownValue`, field.label.slice(0, 60));
                return true;
            }
            if (isWorkdayEeoDisclosureField(field.label)) {
                markDisclosureStreamFallback(field.label);
            }
        }
        if (field.type === 'select') {
            const el = Array.isArray(field.element) ? field.element[0] : field.element;
            if (el) {
                const labelLower = field.label.toLowerCase();
                if (isWorkdayJapanPostalSearchField(field.label)) {
                    const ok = await fillWorkdayJapanPostalSearchField(fieldContainer, field.knownValue || getJapanPostalCodeForJob());
                    if (ok) {
                        debugLog(`${WD} filled japan postal search with knownValue`, field.label.slice(0, 60), field.knownValue);
                        return true;
                    }
                }
                if (isCitizenshipFieldLabel(field.label)) {
                    const ok = await fillWorkdayCitizenshipDropdown(fieldContainer, window.__wdApplyData?.profile || {});
                    if (ok) {
                        debugLog(`${WD} filled citizenship status`, field.label.slice(0, 60));
                        return true;
                    }
                } else if (isWorkdayPlaceOfResidenceField(field.label)) {
                    const ok = await fillWorkdayPlaceOfResidenceField(fieldContainer, field.label);
                    if (ok) {
                        debugLog(`${WD} filled place of residence`, field.label.slice(0, 60));
                        return true;
                    }
                } else if (isCountryFieldLabel(field.label) || isNationalityCountryFieldLabel(field.label)) {
                    const ok = await fillWorkdayCountryDropdown(el, window.__wdApplyData?.profile || {});
                    if (ok) {
                        debugLog(`${WD} filled country with knownValue`, field.label.slice(0, 60), field.knownValue);
                        return true;
                    }
                }
                let selectCandidates = isWorkdayRaceEthnicityFieldLabel(labelLower)
                    ? getRaceEthnicityDropdownCandidates(field.label, field.knownValue, window.__wdApplyData?.profile)
                    : (/^(yes|no)$/i.test(String(field.knownValue))
                        ? (String(field.knownValue).toLowerCase() === 'yes'
                            ? getWorkdayConsentYesCandidates(field.label)
                            : ['No', 'no', 'Not Applicable', 'Not applicable', 'N/A', 'None'])
                        : [String(field.knownValue)]);
                // Clearance Yes/No lists use long "No, never have held..." labels — bare "No"
                // substring-matches the wrong inactive tier and often fails to commit (parsons.wd5).
                if (isWorkdayClearanceFieldLabel(field.label)) {
                    selectCandidates = getWorkdayClearanceCandidates().concat(
                        /^(yes|no)$/i.test(String(field.knownValue)) ? [String(field.knownValue)] : [],
                        selectCandidates,
                    );
                }
                const ok = await fillWorkdaySingleSelectDropdown(el, selectCandidates, field.label);
                if (ok) {
                    debugLog(`${WD} filled select with knownValue`, field.label.slice(0, 60), field.knownValue);
                    return true;
                }
                if (isWorkdayEeoDisclosureField(field.label)) {
                    markDisclosureStreamFallback(field.label);
                }
            }
        } else if (field.type !== 'radio' && field.type !== 'checkbox') {
            const el = Array.isArray(field.element) ? field.element[0] : field.element;
            if (el) {
                let kv = String(field.knownValue);
                if (isCompensationFieldLabel(field.label) && isNumericCompensationField(field.label, el)) {
                    kv = getWorkdayNumericSalaryValue(window.__wdApplyData?.profile, field.label, el);
                }
                workdayScrollToTarget(el, 120);
                el.focus?.();
                await wait(100);
                if (isCompensationFieldLabel(field.label) && isNumericCompensationField(field.label, el)) {
                    kv = getWorkdayNumericSalaryValue(window.__wdApplyData?.profile, field.label, el);
                    const ok = await commitWorkdayNumericInput(el, kv, field.label);
                    debugLog(`${WD} filled field with knownValue`, field.label.slice(0, 60), kv.slice(0, 40), 'ok=', ok);
                    return ok;
                }
                // Never dump MM/DD/YYYY into the Month spinbutton — produces Invalid Date like
                // 08//2008 (parsons.wd5 "When could you start?").
                if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(kv)
                    && (isWorkdayAvailabilityDateLabel(field.label)
                        || isMMDDYYYYContainer(fieldContainer)
                        || isMMDDYYYYPreview(fieldContainer?.innerText || ''))) {
                    const dateVal = normalizeMMDDYYYY(kv) || kv;
                    const ok = await fillWorkdayMaskedDate(
                        fieldContainer,
                        el,
                        dateVal,
                        (fieldContainer?.innerText || '').toLowerCase(),
                    );
                    debugLog(`${WD} filled date knownValue via masked`, field.label.slice(0, 60), dateVal, 'ok=', ok);
                    return ok;
                }
                const kvLabelLower = field.label.toLowerCase();
                const kvIsNameOrContact = /first name|last name|middle name|given name|family name|suffix|address line|city|postal|zip|email/i.test(kvLabelLower)
                    && !/phone code|device type|extension/i.test(kvLabelLower);
                if (kvIsNameOrContact) {
                    const ok = await workdayTypeElement(el, kv);
                    debugLog(`${WD} filled field with knownValue`, field.label.slice(0, 60), kv.slice(0, 40), 'typed=', ok);
                    return ok;
                }
                wdSetInputValue(el, kv);
                await wait(300);
                debugLog(`${WD} filled field with knownValue`, field.label.slice(0, 60), kv.slice(0, 40));
                return true;
            }
        }
    }
    if (field.knownValue === '' && !field.required) {
        debugLog(`${WD} skip optional empty knownValue`, field.label.slice(0, 60));
        return true;
    }

    if (isWorkdayRelativeConflictTextField(field.label, fieldContainer)) {
        return fillWorkdayRelativeConflictTextField(fieldContainer, field.label);
    }

    if (isWorkdayLicenseFollowUpTextField(field.label, fieldContainer)) {
        return fillWorkdayLicenseFollowUpTextField(fieldContainer, field.label);
    }

    if (isWorkdayPlaceOfResidenceField(field.label)) {
        return fillWorkdayPlaceOfResidenceField(fieldContainer, field.label);
    }

    if (isWorkdayVisaHoursPerWeekField(field.label)) {
        return fillWorkdayVisaHoursPerWeekField(fieldContainer, field.label);
    }

    if (isWorkdayVisaExpiryDateLabel(field.label)) {
        return fillWorkdayVisaExpiryDateField(fieldContainer, field.label);
    }

    if (isNotToMyKnowledgeQuestion(fieldContainer, field.label)) {
        return fillWorkdayNotToMyKnowledgeField(fieldContainer, field.label);
    }

    if (isWorkdayAlwaysNoQuestion(field.label, fieldContainer)) {
        const ok = await fillWorkdayAlwaysNoField(fieldContainer, field.label);
        return ok;
    }

    if (isWorkdayFormerEmployerAffiliateTextField(field.label)) {
        return fillWorkdayFormerEmployerAffiliateTextField(fieldContainer, field.label);
    }

    if (isWorkdayEeoDisclosureField(field.label)) {
        const profile = window.__wdApplyData?.profile;
        const labelLower = String(field.label || '').toLowerCase();
        if (isDisclosureLocalFillDone(field.label)
            || isWorkdayEeoFieldFilled(fieldContainer, field.label, profile)) {
            debugLog(`${WD} skip AI disclosure already filled`, field.label.slice(0, 60));
            return true;
        }
        if (isWorkdayRaceEthnicityFieldLabel(labelLower)) {
            const ok = await fillWorkdayEthnicityDisclosureField(fieldContainer, field.label, profile);
            if (ok) markDisclosureLocalFilled(field.label);
            return ok || isWorkdayEeoFieldFilled(fieldContainer, field.label, profile);
        }
        if (/disability/i.test(labelLower) && /consider yourself|do you have a disability|select.*yes.*option/i.test(labelLower)) {
            const ctrl = getContainerControl(fieldContainer)
                || (Array.isArray(field.element) ? field.element[0] : field.element);
            const candidates = ['No', 'No (India)', 'No, I Do Not Have A Disability', "No, I Don't Have A Disability", ...WORKDAY_DECLINE_PHRASES];
            const ok = ctrl && await fillWorkdayDisclosureSingleSelectDropdown(ctrl, candidates, labelLower);
            if (ok) markDisclosureLocalFilled(field.label);
            return ok || isWorkdayEeoFieldFilled(fieldContainer, field.label, profile);
        }
        if (isDisclosureChoiceGroup(fieldContainer)) {
            if (isWorkdayEeoCheckboxGroupFilled(fieldContainer, field.label, profile)) {
                markDisclosureLocalFilled(field.label);
                return true;
            }
        }
        if (!shouldFallbackDisclosureToStream(field.label, fieldContainer, profile)) {
            debugLog(`${WD} skip AI disclosure — local fill only`, field.label.slice(0, 60));
            return isWorkdayEeoFieldFilled(fieldContainer, field.label, profile);
        }
    }

    if (isSalaryAlignmentYesNoQuestion(field.label)) {
        if (isSalaryAlignmentFieldAcceptable(fieldContainer, field.label)) return true;
        const profile = window.__wdApplyData?.profile || {};
        const ok = await fillWorkdaySalaryAlignmentField(fieldContainer, profile, field.label);
        return ok || isSalaryAlignmentFieldAcceptable(fieldContainer, field.label);
    }

    if (isCompensationFieldLabel(field.label)) {
        const profile = window.__wdApplyData?.profile || {};
        const compControl = getContainerControl(fieldContainer);
        if (isCompensationFieldAcceptable(fieldContainer, field.label, compControl)) {
            return true;
        }
        resetWorkdayDropdownOpenCount(String(field.label || '').toLowerCase().slice(0, 80));
        const ok = await fillWorkdayCompensationField(fieldContainer, profile, field.label);
        if (ok || isCompensationFieldAcceptable(fieldContainer, field.label, compControl)) {
            return true;
        }
    }

    const hardcodedYn = getProfileDerivedYesNoAnswer(window.__wdApplyData?.profile || {}, field.label)
        || getHardcodedYesNoAnswer(field.label);
    if (hardcodedYn && (field.type === 'select' || field.type === 'radio')) {
        if (!isWorkdayYesNoFilled(fieldContainer, hardcodedYn)) {
            const ok = await fillWorkdayYesNoField(fieldContainer, hardcodedYn);
            if (ok) {
                debugLog(`${WD} filled hardcoded yes/no in fillWorkdayField`, field.label.slice(0, 60), hardcodedYn);
                return true;
            }
        } else {
            return true;
        }
    }

    if (agentStatus.streamFieldsFailed && field.type === 'textarea') {
        const profile = window.__wdApplyData?.profile || {};
        const fallback = String(
            profile.professionalSummary || profile.general?.professionalSummary
            || profile.coverLetter || profile.achievements || profile.general?.achievements || ''
        ).trim();
        if (fallback) {
            const el = Array.isArray(field.element) ? field.element[0] : field.element;
            if (el) {
                const text = fallback.slice(0, 600);
                workdayScrollToTarget(el, 120);
                await workdayTypeElement(el, text);
                debugLog(`${WD} filled textarea stream-fallback`, field.label.slice(0, 60), text.slice(0, 40));
                if ((el.value || '').trim()) return true;
            }
        }
    }

    let value;
    let completed;
    try {
        ({ value, completed } = await getFieldValueByFieldName(field.label));
    } catch (e) {
        logWorkdayException(`getFieldValueByFieldName: ${field.label.slice(0, 60)}`, e);
        return false;
    }
    value = sanitizeWorkdayAiFieldValue(value, field);
    value = resolveWorkdayStreamFieldValue(value, field);
    if (!value && value !== 0) return false;

    const radioContainer = fieldContainer
        || (Array.isArray(field.element) ? field.element[0]?.closest?.('[data-automation-id*="formField"]') : null)
        || field.element?.closest?.('[data-automation-id*="formField"]');

    if (field.type === 'radio' || (Array.isArray(field.element) && field.element.some?.(el => el?.type === 'radio'))) {
        const answer = Array.isArray(value) ? value[0] : value;
        if (/^(yes|no)$/i.test(String(answer))) {
            const ok = await fillWorkdayYesNoField(radioContainer, answer);
            debugLog(`${WD} filled radio`, field.label.slice(0, 70), answer, 'ok=', ok);
            return ok || isWorkdayYesNoFilled(radioContainer, answer);
        }
        const target = String(answer).toLowerCase();
        for (const radio of radioContainer.querySelectorAll('input[type="radio"]')) {
            const labelEl = document.querySelector(`label[for="${radio.id}"]`) || radio.closest('label');
            const optLabel = (labelEl?.innerText || '').trim().toLowerCase();
            if (optLabel === target || optLabel.startsWith(`${target} `) || textMatchesCandidate(optLabel, target)) {
                if (!radio.checked) await workdayClick(labelEl || radio);
                await wait(300);
                return radio.checked || isWorkdayYesNoFilled(radioContainer, answer);
            }
        }
        if (Array.isArray(field.element) && field.options?.length) {
            for (let i = 0; i < field.element.length; i++) {
                if (String(field.options[i]).toLowerCase() !== target) continue;
                const el = field.element[i];
                const labelEl = document.querySelector(`label[for="${el.id}"]`) || el.closest('label');
                if (!el.checked) await workdayClick(labelEl || el);
                await wait(300);
                return el.checked;
            }
        }
        return false;
    }

    if (Array.isArray(field.element)) {
        if (isWorkdayClinicalSettingsQuestion(field.label)) {
            const ok = await fillWorkdayClinicalSettingsField(fieldContainer, field.label, window.__wdApplyData?.profile);
            debugLog(`${WD} filled clinical settings (stream)`, field.label.slice(0, 60), 'ok=', ok);
            return ok;
        }
        if (isWorkdayShiftAvailabilityQuestion(field.label)) {
            const ok = await fillWorkdayShiftAvailabilityField(fieldContainer, field.label);
            debugLog(`${WD} filled shift availability (stream)`, field.label.slice(0, 60), 'ok=', ok);
            return ok;
        }
        if (isWorkdayFormerEmployerQuestion(field.label)) {
            const vals = Array.isArray(value) ? value : [value];
            const ok = await fillWorkdayFormerEmployerField(fieldContainer, field.label, vals);
            debugLog(`${WD} filled former employer checkbox (stream)`, field.label.slice(0, 60), 'value=', vals[0], 'ok=', ok);
            return ok;
        }
        if (isWorkdayEeoDisclosureField(field.label) && isDisclosureChoiceGroup(fieldContainer)) {
            const profile = window.__wdApplyData?.profile;
            if (isDisclosureLocalFillDone(field.label)
                || isWorkdayEeoCheckboxGroupFilled(fieldContainer, field.label, profile)) {
                debugLog(`${WD} skip stream disclosure already filled`, field.label.slice(0, 60));
                return true;
            }
            const resolved = resolveWorkdayDisclosureCheckboxValue(value, field.options, field.label);
            const ok = await fillWorkdayExclusiveCheckboxGroup(fieldContainer, resolved, { label: field.label });
            if (ok) markDisclosureLocalFilled(field.label);
            debugLog(`${WD} filled disclosure checkbox exclusive`, field.label.slice(0, 60), resolved[0], 'ok=', ok);
            return ok || isWorkdayEeoCheckboxGroupFilled(fieldContainer, field.label, profile);
        }
        const values = Array.isArray(value) ? value : [value];
        const options = (field.options || []).map(o => String(o).trim());
        if (options.length === 2 && options.every(o => /^(yes|no)$/i.test(o))
            && values.some(v => /^(yes|no)$/i.test(String(v)))
            && shouldUseBareYesNoForContainer(fieldContainer, values.find(v => /^(yes|no)$/i.test(String(v))), field.label)) {
            const answer = values.find(v => /^(yes|no)$/i.test(String(v))) || values[0];
            return fillWorkdayYesNoField(fieldContainer, answer);
        }
        let selected = false;
        for (let i = 0; i < field.element.length; i++) {
            const el = field.element[i];
            const opt = String(field.options?.[i] || '').toLowerCase();
            const optShort = opt.replace(/\s*\([^)]+\)\s*$/, '').trim(); // strip trailing "(United States...)"
            const shouldCheck = values.some(v => {
                const vl = String(v).toLowerCase().trim();
                const vlShort = vl.replace(/\s*\([^)]+\)\s*$/, '').trim();
                return vl === opt || vl === optShort || opt === vlShort
                    || opt.startsWith(vl) || vl.startsWith(optShort)
                    || textMatchesCandidate(opt, vl) || textMatchesCandidate(vl, opt);
            });
            if (shouldCheck && !isWorkdayCheckboxChecked(el)) {
                if (isWorkdayFormerEmployerQuestion(field.label)) {
                    await uncheckOtherWorkdayCheckboxes(fieldContainer, el, field.label);
                }
                const ok = await workdayClickCheckbox(el, field.label.slice(0, 60));
                await wait(300);
                selected = ok || selected;
            } else if (!shouldCheck && isWorkdayCheckboxChecked(el)) {
                await workdayUncheckCheckbox(el, `${field.label} uncheck-stream`);
                await wait(200);
            }
        }
        return selected || isDisclosureChoiceFilled(fieldContainer, values);
    }

    if (field.type === 'select') {
        const container = field.element.closest?.('[data-automation-id*="formField"]') || field.element;
        if (isWorkdayAlwaysNoQuestion(field.label)) {
            return fillWorkdayAlwaysNoField(container, field.label);
        }
        const knownValue = getProfileFieldValue(window.__wdApplyData?.profile || {}, field.label);
        if (/^(yes|no)$/i.test(String(knownValue)) && isWorkdayYesNoFilled(container, knownValue)) {
            return true;
        }
        if (isWorkdayStateFieldLabel(field.label)) {
            const profile = window.__wdApplyData?.profile;
            const streamed = Array.isArray(value) ? value[0] : value;
            const stateVal = getConsistentUSStateForProfile(profile);
            if (stateVal && streamed && stateVal.toLowerCase() !== String(streamed).toLowerCase()) {
                debugLog(`${WD} state prefer profile over stream`, streamed, '->', stateVal);
            }
            if (stateVal) {
                debugLog(`${WD} fill state from profile`, stateVal);
                return fillWorkdayStateDropdown(field.element, stateVal);
            }
            // getConsistentUSStateForProfile only ever resolves US states (zip/job-location/profile-address
            // parsing all assume a US address format). For a non-US profile (e.g. residency country India,
            // Canada, Australia, ...) it always returns null, and this used to unconditionally `return false`
            // here — discarding a perfectly valid AI-streamed option (e.g. "Maharashtra") and permanently
            // leaving the State/Province dropdown on "Select One". That guarantees every non-US applicant gets
            // stuck on this field on every tenant that renders a required State control for their country (see
            // chrome-extension.mdc Workday step stuck: information — generalizable, not tenant-specific). Fall
            // back to the model's streamed value instead of bailing.
            if (streamed) {
                debugLog(`${WD} fill state from stream (non-US profile)`, streamed);
                return fillWorkdayStateDropdown(field.element, String(streamed));
            }
            debugLog(`${WD} skip state stream job-location guess`, streamed);
            return false;
        }
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        if (!/select one|0 items selected|error:/i.test(preview)) {
            debugLog(`${WD} skip already-filled dropdown`, field.label, preview.slice(0, 50));
            return true;
        }
        const labelLower = field.label.toLowerCase();
        const profile = window.__wdApplyData?.profile || {};
        if (isWorkdayGenderIdentityField(field.label) || isWorkdayDisclosureGenderField(labelLower)) {
            // Profile never has a gender value — this field is only ever answered from the AI
            // stream response (never a local Male/Female guess, see chrome-extension.mdc
            // "Gender / sex disclosure fields — never choose locally"). Try the model's exact
            // value first, then fall back to decline-style candidates if it doesn't match any
            // real option (paraphrase, wrong casing, etc.) — never a hardcoded binary guess.
            const streamedValues = (Array.isArray(value) ? value : [value])
                .filter(v => v != null && v !== '' && !/^n\/?a$/i.test(String(v).trim()));
            // Decline-style candidates only as fallback — never inject Male/Female from field.options
            // (chrome-extension.mdc: never choose gender locally). Binary lists must come from stream.
            const candidates = [...streamedValues, ...getDisclosureGenderOrIdentityCandidates(field.label)];
            const ok = await fillWorkdayDisclosureSingleSelectDropdown(field.element, candidates, labelLower);
            debugLog(`${WD} filled gender identity (stream)`, field.label.slice(0, 60), 'value=', value, 'ok=', ok);
            if (ok) return true;
        }
        if (/disability/i.test(labelLower) && /consider yourself|do you have a disability/i.test(labelLower)) {
            const disabilityCandidates = ['No', 'No (India)', 'No, I Do Not Have A Disability', "No, I Don't Have A Disability", ...WORKDAY_DECLINE_PHRASES];
            const ok = await fillWorkdayDisclosureSingleSelectDropdown(field.element, disabilityCandidates, labelLower);
            debugLog(`${WD} filled disability (stream)`, field.label.slice(0, 60), 'ok=', ok);
            if (ok) return true;
        }
        if (isWorkdayRaceEthnicityFieldLabel(labelLower)) {
            const ok = await fillWorkdayRaceDropdown(field.element, profile, field.label, value);
            debugLog(`${WD} filled race/ethnicity (stream)`, field.label.slice(0, 60), 'ok=', ok);
            if (ok) return true;
        }
        // For pure BUTTON dropdowns (no combobox input), use fillWorkdaySingleSelectDropdown
        // which has better React-state commitment via commitWorkdayComboboxSelection
        const hasCombobox = container.querySelector('input[role="combobox"]');
        const candidates = getRaceEthnicityDropdownCandidates(field.label, value, profile);
        if (!hasCombobox && field.element.tagName === 'BUTTON') {
            return fillWorkdaySingleSelectDropdown(field.element, candidates, field.label);
        }
        if (/proficiency|fluency/i.test(labelLower) && /english|language|indicate your proficiency/i.test(labelLower)) {
            const profCandidates = [...candidates, ...getEnglishProficiencyCandidatesFromProfile(window.__wdApplyData?.profile)];
            const ok = await fillWorkdayProficiencyDropdown(field.element, profCandidates, field.label)
                || await fillWorkdaySingleSelectDropdown(field.element, profCandidates, field.label);
            if (ok) return true;
        }
        return fillWorkdayDropdown(field.element, Array.isArray(value) ? value[0] : value);
    }

    if (agentStatus.resumed && field.element.value) {
        const resumeContainer = field.element.closest?.('[data-automation-id*="formField"]') || field.element.parentElement;
        const resumePreview = (resumeContainer?.innerText || '').replace(/\s+/g, ' ');
        if (!/error:.*required and must have a value/i.test(resumePreview)) return true;
    }

    workdayScrollToTarget(field.element, 120);
    const textVal = String(Array.isArray(value) ? value[0] : value);

    // Masked date containers (split Month/Day/Year inputs, or "MM/DD/YYYY" preview text) must
    // always receive MM/DD/YYYY, regardless of the format the AI value arrived in. The AI often
    // returns ISO (YYYY-MM-DD) when a date-shaped question wasn't recognized as a date field
    // during collection (e.g. "Anticipated eligibility time for employment?" has no "date" in
    // the label) — detect the widget from the DOM first, then normalize the value, instead of
    // gating on the value's format (see chrome-extension.mdc Date fields rule).
    {
        const container = field.element.closest?.('[data-automation-id*="formField"]') || field.element.parentElement;
        const isDateWidget = container && (isMMDDYYYYContainer(container) || isMMDDYYYYPreview(container?.innerText || ''));
        const isMonthYearWidget = !isDateWidget && container && /^\d{2}\/\d{4}$/.test(textVal);
        if (isDateWidget || isMonthYearWidget) {
            const dateVal = normalizeWorkdayDateForMaskedField(textVal);
            if (dateVal) {
                debugLog(`${WD} fillWorkdayField via fillWorkdayMaskedDate`, field.label.slice(0, 60), dateVal);
                const ok = await fillWorkdayMaskedDate(container, field.element, dateVal, (container?.innerText || '').toLowerCase());
                debugLog(`${WD} fillWorkdayField date filled`, field.label.slice(0, 60), 'ok=', ok);
                return ok || completed !== false;
            }
            debugLog(`${WD} fillWorkdayField masked date value unparsed`, field.label.slice(0, 60), textVal);
        }
    }

    // Focus first so React treats this as an interactive change
    field.element.focus?.();
    await wait(100);
    if (isCompensationFieldLabel(field.label) && isNumericCompensationField(field.label, field.element)) {
        const numVal = sanitizeWorkdayAiFieldValue(value, field) || getWorkdayNumericSalaryValue(window.__wdApplyData?.profile, field.label, field.element);
        return commitWorkdayNumericInput(field.element, numVal, field.label);
    }
    const labelLower = field.label.toLowerCase();
    const isNameOrContactText = /first name|last name|middle name|given name|family name|suffix|address line|city|postal|zip|email/i.test(labelLower)
        && !/phone code|device type|extension/i.test(labelLower);
    if (isNameOrContactText || field.type === 'textarea') {
        let typedVal = textVal;
        if (field.type === 'textarea' && field.element?.maxLength > 0 && textVal.length > field.element.maxLength) {
            // Free-text questions (e.g. "list specialty skills…") often get a verbose AI answer that
            // exceeds this tenant's textarea maxlength. Some Workday widgets reject the overflow at
            // commit time but keep showing the plain "is required and must have a value" banner instead
            // of a length-specific error, which looks identical to a stale-banner false positive and
            // keeps the step permanently stuck across every retry (see chrome-extension.mdc Workday step
            // stuck: questions). Truncate to the widget's own limit (word boundary) before typing.
            const truncated = textVal.slice(0, field.element.maxLength);
            const lastSpace = truncated.lastIndexOf(' ');
            typedVal = lastSpace > field.element.maxLength * 0.6 ? truncated.slice(0, lastSpace) : truncated;
            debugLog(`${WD} fillWorkdayField truncate textarea to maxLength`, field.label.slice(0, 60),
                'maxLength=', field.element.maxLength, 'from=', textVal.length, 'to=', typedVal.length);
        }
        const ok = await workdayTypeElement(field.element, typedVal);
        if (field.type === 'textarea') textareaGrow();
        return ok || completed !== false;
    }
    wdSetInputValue(field.element, textVal);
    await wait(100);
    if (field.type === 'textarea') {
        textareaGrow();
    }
    return completed !== false;
}

async function ensureWorkdaySectionFormsClosed() {
    for (let i = 0; i < 4; i++) {
        if (await saveWorkdayEntryModal()) continue;
        if (await cancelWorkdayEntryModal()) continue;
        break;
    }
    await closeWorkdayPopups();
    await wait(500);
}

// Cancel any auto-opened empty inline forms in a section (e.g. Workday auto-opens after last entry)
async function cancelEmptyOpenSectionForms(section, kind = 'experience') {
    if (!section) return;
    const cancelBtns = [...section.querySelectorAll('button')].filter(b =>
        /^cancel$/i.test((b.innerText || '').trim()) && isVisibleElement(b));
    for (const cancelBtn of cancelBtns) {
        // Walk up to find the form root for this cancel button
        let formRoot = cancelBtn.parentElement;
        for (let d = 0; d < 10 && formRoot && formRoot !== section; d++) {
            const inputs = [...formRoot.querySelectorAll('input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"])')];
            if (inputs.length >= 2) break;
            formRoot = formRoot.parentElement;
        }
        const firstInput = formRoot?.querySelector('input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"])');
        if (!(firstInput?.value || '').trim()) {
            debugLog(`${WD} canceling empty open ${kind} inline form`);
            await workdayClick(cancelBtn);
            await wait(1200);
        }
    }
    // Also try Delete button on empty entry roots
    const deleteBtns = getWorkdaySectionDeleteButtons(section);
    if (deleteBtns.length > 0) {
        const roots = deleteBtns.map(btn => getEntryRootFromDeleteBtn(btn, section));
        for (let idx = roots.length - 1; idx >= 0; idx--) {
            if (isWorkdayEntryEmpty(roots[idx], kind)) {
                debugLog(`${WD} deleting empty ${kind} entry at index`, idx + 1);
                await workdayClick(deleteBtns[idx]);
                await wait(800);
                await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
                await wait(1200);
            }
        }
    }
}

async function workdayStreamVacancyFields(fields, started) {
    const allowed = [];
    const blocked = [];
    const alreadySent = [];
    window.__wdStreamedLabels = window.__wdStreamedLabels instanceof Map ? window.__wdStreamedLabels : new Map();
    for (const f of fields) {
        const el = Array.isArray(f.element) ? f.element[0] : f.element;
        const container = el?.closest?.('[data-automation-id*="formField"]') || el;
        if (/how did you hear/i.test(f.label)) {
            blocked.push(f.label);
            continue;
        }
        if (isWorkdaySectionOnlyField(container, f.label)) {
            blocked.push(f.label);
            continue;
        }
        const streamProfile = window.__wdApplyData?.profile;
        const streamContainer = el?.closest?.('[data-automation-id*="formField"]') || el;
        if (isWorkdayEeoDisclosureField(f.label)
            && !shouldFallbackDisclosureToStream(f.label, streamContainer, streamProfile)) {
            blocked.push(f.label);
            continue;
        }
        if (isWorkdayPrivacyConsentDropdownField(f.label, streamContainer)
            || containerPreviewHasAgreeDisagreePair(streamContainer)
            || isWorkdayAgreeDisagreeOptionsOnly(f.options)) {
            blocked.push(f.label);
            continue;
        }
        // Skip fields that have a pre-computed knownValue — they'll be filled directly without AI
        if (f.knownValue !== undefined && f.knownValue !== null) {
            if (isWorkdayEeoDisclosureField(f.label)
                && shouldFallbackDisclosureToStream(f.label, streamContainer, streamProfile)) {
                delete f.knownValue;
            } else {
                alreadySent.push(f.label);
                continue;
            }
        }
        if (f.type === 'checkbox' && isWorkdayEeoDisclosureField(f.label)) {
            if (isDisclosureLocalFillDone(f.label)
                || isWorkdayEeoCheckboxGroupFilled(streamContainer, f.label, streamProfile)) {
                alreadySent.push(f.label);
                continue;
            }
        }
        // Skip fields already streamed in this step to avoid duplicate backend calls
        // But re-stream if the field has a validation error (fill may not have registered)
        const elCheck = Array.isArray(f.element) ? f.element[0] : f.element;
        const containerCheck = elCheck?.closest?.('[data-automation-id*="formField"]') || elCheck?.parentElement;
        // A free-text control that already holds a non-empty value is not actually unfilled, even if
        // Workday's error banner text is still lingering in the container's innerText (see
        // countWorkdayStepEmptyRequired / validateWorkdayStep above for the same staleness). Re-streaming
        // it anyway just burns MAX_STREAM_CALLS_PER_STEP budget that other genuinely-empty fields need.
        const textCtrlCheck = containerCheck?.querySelector?.('textarea, input[type="text"], input:not([type])');
        const hasRealTextValue = Boolean(textCtrlCheck && !textCtrlCheck.getAttribute('role') && (textCtrlCheck.value || '').trim());
        const hasErrorCheck = !hasRealTextValue && !!(containerCheck?.querySelector('[data-automation-id="errorMessage"]')
            || containerCheck?.querySelector?.('[aria-live="assertive"]')
            || (containerCheck?.innerText || '').includes('is required and must have a value'));
        if (wdStreamedLabelsHas(f.label) && !hasErrorCheck) {
            const previewCheck = (containerCheck?.innerText || '').replace(/\s+/g, ' ');
            const stillEmptyDropdown = /select one|0 items selected/i.test(previewCheck);
            if (isCompensationFieldLabel(f.label) && stillEmptyDropdown) {
                debugLog(`${WD} re-stream compensation still empty`, f.label.slice(0, 60));
                wdStreamedLabelsDelete(f.label);
            } else {
                alreadySent.push(f.label);
                continue;
            }
        }
        if (hasErrorCheck && wdStreamedLabelsHas(f.label)) {
            if (isWorkdayEeoDisclosureField(f.label)
                && !shouldFallbackDisclosureToStream(f.label, containerCheck, streamProfile)) {
                debugLog(`${WD} skip re-stream disclosure`, f.label.slice(0, 60));
                alreadySent.push(f.label);
                continue;
            }
            debugLog(`${WD} re-stream field with error`, f.label.slice(0, 60));
            wdStreamedLabelsDelete(f.label);
        }
        allowed.push(f);
    }
    if (alreadySent.length) {
        debugLog(`${WD} streamVacancyFields skip already-sent`, alreadySent.length, alreadySent.slice(0, 3).join(' | '));
    }
    debugLog(`${WD} streamVacancyFields send`, allowed.length,
        allowed.map(f => `${f.label}${f.required ? '*' : ''}`).join(' | '));
    if (blocked.length) {
        debugLog(`${WD} streamVacancyFields blocked`, blocked.join(' | '));
    }
    const stepKey = wdTiming.stepKey || (typeof getCurrentStepKey === 'function' ? getCurrentStepKey() : 'unknown');
    window.__wdStreamCallsByStep = window.__wdStreamCallsByStep || {};
    const stepCalls = (window.__wdStreamCallsByStep[stepKey] || 0) + 1;
    if (allowed.length && stepCalls > MAX_STREAM_CALLS_PER_STEP) {
        debugLog(`${WD} streamVacancyFields skip`, `max ${MAX_STREAM_CALLS_PER_STEP} calls per step`, stepKey);
        return 0;
    }
    if (allowed.length) {
        window.__wdStreamCallsByStep[stepKey] = stepCalls;
        for (const f of allowed) wdStreamedLabelsAdd(f.label);
        wdTiming.noteStreamCall(allowed.length);
        const ok = await streamVacancyFields(allowed, started);
        if (!ok) {
            debugLog(`${WD} streamVacancyFields failed`, allowed.length, `step=${stepKey}`);
            return 0;
        }
    } else {
        debugLog(`${WD} streamVacancyFields skip`, 'no fields need AI this round');
    }
    return allowed.length;
}

/**
 * Open each select field's dropdown once to collect options, then close it.
 * This enriches field objects in-place with options[] before streaming to AI.
 * Each open is tracked in wdDropdownOpenCounts to count toward the per-field limit.
 */
async function enrichSelectFieldsWithOptions(fields) {
    const enrichT0 = Date.now();
    let enriched = 0;
    for (const field of fields) {
        if (field.knownValue !== undefined && field.knownValue !== null && String(field.knownValue).trim()) {
            // Still harvest options for eligibility / place-of-residence when knownValue alone
            // fails to match long Workday option labels (unimelb.wd105).
            const needOpts = (!field.options || field.options.length === 0)
                && (/eligible to work|work rights for|place of residence|confirm your current location/i.test(field.label || ''));
            if (!needOpts) continue;
        }
        if (isWorkdayLockedYesNoField(field.label)) {
            const affixRoot2 = (Array.isArray(field.element) ? field.element[0] : field.element)
                ?.closest?.('[data-automation-id*="formField"]');
            if (isWorkdayYesNoFieldLockedAndFilled(affixRoot2, field.label)) continue;
        }
        if (field.type !== 'select' || !field.element) continue;
        const affixRoot = (Array.isArray(field.element) ? field.element[0] : field.element)
            ?.closest?.('[data-automation-id*="formField"]');
        if (shouldSkipOptionalNameAffixField(affixRoot, field.label)) {
            debugLog(`${WD} enrich skip optional affix`, field.label.slice(0, 50));
            continue;
        }
        if (field.options && field.options.length > 0) { debugLog(`${WD} enrich skip has-opts`, field.label.slice(0,50), field.options.length); continue; }
        const el = field.element;
        // Skip location/school typeaheads — opening them would trigger search, not a static list
        // Use word boundaries to avoid matching substrings (e.g. "city" in "Ethnicity", "location" in "allocation")
        // Exception: office / basecamp / "working from" selects have a short static list (waystar.wd1) —
        // skipping enrich left stream with options:[] so the model answered with the profile city.
        // Exception: Yes/No interrogatives that merely mention school/university/city ("Have you already
        // identified the school/university…?") — skipping enrich left options:[] and the model invented
        // a school name that never matched Yes|No|Don't know (sanofi.wd3 questions).
        if (/\b(location|school|university|college|employer|company|city)\b/i.test(field.label)
            && !isCommuteTimeFieldLabel(field.label)
            && !isWorkdayYesNoInterrogativeLabel(field.label)
            && !isWorkdayPlaceOfResidenceField(field.label)
            && !/basecamp|working from|office location|which .{0,60}location would you|work location are you|prefer(?:red)? (?:office|work) location/i.test(field.label)) {
            debugLog(`${WD} enrich skip location`, field.label.slice(0,50));
            continue;
        }
        if (isCountryOrCitizenshipFieldLabel(field.label)) { debugLog(`${WD} enrich skip country/citizenship`, field.label.slice(0,50)); continue; }
        // Veteran: still skip enrich (local candidate list is sufficient).
        // Gender: MUST collect options for the AI stream — binary Male/Female tenants (mears.wd3)
        // have no decline option; streaming without options yields "N/A" that never matches.
        if (isWorkdayVeteranFieldLabel(field.label)) {
            debugLog(`${WD} enrich skip local disclosure`, field.label.slice(0, 60));
            continue;
        }
        if (/how did you hear/i.test(field.label)) {
            debugLog(`${WD} enrich skip hear (local fill)`, field.label.slice(0, 50));
            continue;
        }
        const openKey = normalizeDropdownOpenKey(field.label);
        // Local gender/race decline attempts burn the open budget before enrich — reset so we can
        // still harvest real options for the stream (mearsgroup gender; autodesk Canada ethnicity).
        if ((isWorkdayDisclosureGenderField(field.label) || isWorkdayGenderIdentityField(field.label)
                || isWorkdayRaceEthnicityFieldLabel(field.label) || /^ethnicity$/i.test(String(field.label || '').replace(/\*/g, '').trim()))
            && (!field.options || field.options.length === 0)
            && (wdDropdownOpenCounts[openKey] || 0) >= 2) {
            debugLog(`${WD} options collect reset disclosure for stream`, openKey.slice(0, 60));
            resetWorkdayDropdownOpenCount(openKey);
        }
        if ((wdDropdownOpenCounts[openKey] || 0) >= 2) {
            if (isWorkdayPrivacyConsentDropdownField(field.label)
                || /please read before signing/i.test(field.label || '')) {
                debugLog(`${WD} options collect skip privacy/agree excess`, openKey.slice(0, 60));
                continue;
            }
            if (isWorkdayEeoDisclosureField(field.label) && (!field.options || field.options.length === 0)) {
                debugLog(`${WD} options collect reset EEO`, openKey.slice(0, 60));
                resetWorkdayDropdownOpenCount(openKey);
            } else if (/how did you hear/i.test(field.label) && !isHearSelectionUsable(field.element)) {
                debugLog(`${WD} options collect reset stuck hear`, openKey.slice(0, 60));
                resetWorkdayDropdownOpenCount(openKey);
            } else if (isCompensationFieldLabel(field.label)) {
                const compRoot = (Array.isArray(field.element) ? field.element[0] : field.element)
                    ?.closest?.('[data-automation-id*="formField"]');
                const preview = (compRoot?.innerText || '').replace(/\s+/g, ' ');
                if (/select one|0 items selected/i.test(preview)) {
                    debugLog(`${WD} options collect reset stuck compensation`, openKey.slice(0, 60));
                    resetWorkdayDropdownOpenCount(openKey);
                } else {
                    debugLog(`${WD} options collect skip excess opens`, openKey.slice(0, 60));
                    continue;
                }
            } else {
            debugLog(`${WD} options collect skip excess opens`, openKey.slice(0, 60));
            continue;
            }
        }
        debugLog(`${WD} enrich proceed`, field.label.slice(0, 60), 'openKey=', openKey.slice(0, 40), 'cnt=', wdDropdownOpenCounts[openKey] || 0);
        const fieldT0 = Date.now();
        try {
            workdayScrollToTarget(el, 120);
            await wait(100);
            trackWorkdayDropdownOpen(openKey);
            await workdayClickElement(el);
            await wait(600);
            const fieldRoot = el.closest?.('[data-automation-id*="formField"]') || el.parentElement;
            // Try to get listbox items via multiple strategies
            const listboxId = el.getAttribute('aria-controls') || el.getAttribute('aria-owns');
            let listbox = listboxId ? document.getElementById(listboxId) : null;
            if (!listbox && fieldRoot) {
                listbox = fieldRoot.querySelector('[role="listbox"]');
            }
            let itemEls = listbox
                ? listbox.querySelectorAll('[role="option"]')
                : fieldRoot
                    ? fieldRoot.querySelectorAll('[role="listbox"] [role="option"], [data-automation-id*="promptOption"]')
                    : document.querySelectorAll('[role="listbox"] [role="option"], [data-automation-id*="promptOption"]');
            // Fallback: try any visible popup options (scoped to field when possible)
            if (itemEls.length === 0) {
                itemEls = fieldRoot
                    ? fieldRoot.querySelectorAll('[role="option"], [data-automation-id*="listItem"] [role="option"]')
                    : document.querySelectorAll('[role="option"], [data-automation-id*="listItem"] [role="option"]');
            }
            if (itemEls.length === 0) {
                // Try scrollable list items
                itemEls = document.querySelectorAll('[class*="listItem"], [class*="option"], li[role="option"]');
            }
            if (itemEls.length > 0) {
                field.options = [...itemEls]
                    .map(o => (o.innerText || o.textContent || '').replace(/\s+/g, ' ').trim())
                    .filter(t => t && !/select one/i.test(t));
                debugLog(`${WD} options collected`, field.label.slice(0, 60), field.options.length, field.options.slice(0, 5).join(' | '));
                // Agree / Do Not Agree (any long policy label) — fill locally, never stream
                if (isWorkdayAgreeDisagreeOptionsOnly(field.options)) {
                    const agree = pickWorkdayAgreeOption(field.options);
                    field.knownValue = agree;
                    debugLog(`${WD} enrich agree/disagree local`, field.label.slice(0, 60), '->', agree);
                    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
                    await wait(250);
                    trackWorkdayDropdownClose(openKey, 'enrich-agree-disagree');
                    await closeWorkdayPopups();
                    const root = el.closest?.('[data-automation-id*="formField"]') || el.parentElement;
                    clearWorkdaySingleSelectMissKey(field.label);
                    resetWorkdayDropdownOpenCount(openKey);
                    if (root && agree) {
                        await fillWorkdaySingleSelectDropdown(el, [agree, ...getWorkdayPrivacyConsentCandidates()], field.label);
                    }
                    enriched += 1;
                    continue;
                }
            } else {
                debugLog(`${WD} options collect empty for`, field.label.slice(0, 60), 'aria-expanded=', el.getAttribute('aria-expanded'));
            }
            // Close popup
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            await wait(250);
            trackWorkdayDropdownClose(openKey, 'enrich-collect');
            await closeWorkdayPopups();
            enriched += 1;
            if (Date.now() - fieldT0 >= 2000) {
                debugLog(`${WD} enrich SLOW`, field.label.slice(0, 60), `${Date.now() - fieldT0}ms`);
            }
        } catch (e) {
            debugLog(`${WD} options collect error`, field.label.slice(0, 60), String(e).slice(0, 80));
        }
    }
    const enrichMs = Date.now() - enrichT0;
    if (enriched > 0) {
        wdTiming.mark('enrich-select-done', `${enriched} fields ${enrichMs}ms`);
    }
}

async function tryFillSmartDropdownFields(profile) {
    let filled = false;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const ll = label.toLowerCase();
        if (!/notice period|working rights|keep in touch|sharing future career|preferred language/i.test(ll)) continue;
        if (isWorkdaySingleSelectFilled(container)) continue;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        if (!/select one|0 items selected|error:/i.test(preview)) continue;
        const ctrl = getWorkdayDropdownTrigger(container) || getContainerControl(container);
        if (!ctrl) continue;
        let cands = [];
        if (/notice period/i.test(ll)) {
            cands = ['2 weeks', '4 weeks', '1 month', 'Immediate', '2 weeks notice'];
        } else if (/working rights/i.test(ll)) {
            cands = getWorkdayWorkingRightsCandidates(profile, label || '');
        } else if (/preferred language/i.test(ll)) {
            cands = getPreferredLanguageCandidates(profile);
        } else if (/keep in touch|sharing future career/i.test(ll)) {
            cands = ['I consent', 'I Consent', "I don't consent", 'Yes', 'No'];
        }
        if (!cands.length) continue;
        debugLog(`${WD} smart dropdown pre-fill`, label.slice(0, 60));
        clearWorkdaySingleSelectMissKey(label);
        resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(label));
        if (await fillWorkdaySingleSelectDropdown(ctrl, cands, label)) filled = true;
    }
    return filled;
}

async function fillWorkdayFields(started, options = {}) {
    return runWorkdayPhase('fillWorkdayFields', async () => {
    if (!options.skipScrollReset) {
        workdayScroll.resetToTop();
    }
    await fillKnownYesNoRadioFields(window.__wdApplyData?.profile || {});
    for (let round = 0; round < MAX_FIELD_ROUNDS; round++) {
        await pause();
        if (started && started != agentStatus.applyStarted) return;

        // Close any open dropdowns before collecting — a stale-open dropdown can hide its trigger button
        if (document.querySelector('[role="listbox"], [data-automation-id*="promptContainer"]')) {
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            await wait(400);
        }

        let fields = collectWorkdayFields().filter(f => !/password|verify password|create account|sign in/i.test(f.label));
        fields = fields.filter(f => !/how did you hear/i.test(f.label));
        if (!fields.length) return;

        await tryFillSmartDropdownFields(window.__wdApplyData?.profile);

        // Collect options for select fields and add format hints for date text fields
        await enrichSelectFieldsWithOptions(fields);
        // After option discovery: fill any Agree/Disagree locally before AI stream
        for (const f of fields) {
            if (!f.options || !isWorkdayAgreeDisagreeOptionsOnly(f.options)) continue;
            if (f.knownValue) continue;
            const agree = pickWorkdayAgreeOption(f.options);
            if (!agree) continue;
            f.knownValue = agree;
            const el = Array.isArray(f.element) ? f.element[0] : f.element;
            const root = el?.closest?.('[data-automation-id*="formField"]');
            if (el && root && !isWorkdaySingleSelectFilled(root, [agree])) {
                clearWorkdaySingleSelectMissKey(f.label);
                resetWorkdayDropdownOpenCount(normalizeDropdownOpenKey(f.label));
                debugLog(`${WD} pre-stream agree/disagree fill`, f.label.slice(0, 60), agree);
                await fillWorkdaySingleSelectDropdown(el, [agree, ...getWorkdayPrivacyConsentCandidates()], f.label);
            }
        }
        for (const f of fields) {
            if (f.type !== 'select' && f.type !== 'radio' && f.type !== 'checkbox') {
                const labelLooksLikeDate = /date|start date|available from|date available|availability date/i.test(f.label)
                    && !/hours|per week|total hours/i.test(f.label);
                // DOM-first detection (see chrome-extension.mdc DOM-first development): many
                // date-shaped questions (e.g. "Anticipated eligibility time for employment?",
                // "Notice period end date") render as a masked Month/Day/Year widget without the
                // word "date" in the label. Detect from the actual control, not label text only,
                // so the hint (and downstream fillWorkdayMaskedDate) applies across tenants.
                const el = Array.isArray(f.element) ? f.element[0] : f.element;
                const container = el?.closest?.('[data-automation-id*="formField"]') || el?.parentElement;
                const isMaskedDateWidget = Boolean(container) && isMMDDYYYYContainer(container);
                if ((labelLooksLikeDate || isMaskedDateWidget) && !f.label.includes('(')) {
                    f.label = `${f.label} (format: MM/DD/YYYY)`;
                }
            }
        }

        debugLog(`${WD} field round`, round + 1, fields.length);
        const streamedCount = await workdayStreamVacancyFields(fields, started);
        if (streamedCount && agentStatus.streamFieldsFailed) {
            throw new SendCvError('Workday AI stream failed');
        }
        // streamVacancyFields is async — poll until AI starts responding (see chrome-extension.mdc)
        await waitForWorkdayStreamBatchReady(streamedCount);

        let fieldNum = 0;
        let filledAny = false;
        while (fieldNum < fields.length) {
            const field = fields[fieldNum];
            try {
                const filled = await fillWorkdayField(field, started);
                if (filled) filledAny = true;
                fieldNum += 1;
            } catch (e) {
                logWorkdayException(`fillWorkdayField: ${field.label}`, e);
                fieldNum += 1;
            }
            await wait(250);
        }

        if (!filledAny) break;
        if (streamedCount === 0 && round >= 1) {
            wdTiming.mark('field-rounds-stop', `no stream round=${round + 1}`);
            break;
        }
        await wait(streamedCount > 0 ? 800 : 300);
    }
    });
}

function isWorkdaySubmitButtonLabel(text) {
    return /^(submit|apply|finish)$/i.test(String(text || '').trim());
}

function findWorkdayResumeFileInput() {
    let fileInput = queryVisible('input[type="file"]')
        || document.querySelector('input[data-automation-id*="file"], input[data-automation-id*="upload"]');
    if (fileInput) return fileInput;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).toLowerCase();
        if (!/upload|resume|cv|attachment|photo|headshot|profile picture/i.test(label) || /linkedin|website|social/i.test(label)) continue;
        fileInput = container.querySelector('input[type="file"]');
        if (fileInput) return fileInput;
    }
    return null;
}

function isWorkdayResumeUploaded(cv) {
    const filenameStem = cv?.originalFilename?.replace(/\.[^.]+$/, '') || '';
    let sawUploadField = false;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).toLowerCase();
        if (!/upload|resume|cv|attachment|\bfile\b/i.test(label) || /linkedin|website|social/i.test(label)) continue;
        sawUploadField = true;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        // Empty dropzone still visible — not uploaded for this field
        const dropzoneEmpty = /drop files here|select files/i.test(preview)
            && !/successfully uploaded/i.test(preview)
            && !(filenameStem && preview.toLowerCase().includes(filenameStem.toLowerCase()));
        if (dropzoneEmpty) continue;
        if (/successfully uploaded/i.test(preview)) return true;
        if (filenameStem && preview.toLowerCase().includes(filenameStem.toLowerCase())) return true;
        // File chip / selected filename without the dropzone CTA
        if (container.querySelector('[data-automation-id*="fileName"], [data-automation-id*="uploadedFile"], [data-automation-id*="attachment"]')) {
            return true;
        }
    }
    if (!filenameStem) return false;
    const rootText = (getFormRoot()?.innerText || '').slice(0, 12000);
    // Require filename evidence — never treat bare "successfully uploaded" as done
    // (false positive skipped required "Upload a file" on HEI experience).
    if (rootText.toLowerCase().includes(filenameStem.toLowerCase())
        && /successfully uploaded|uploaded successfully|file uploaded/i.test(rootText)) {
        return true;
    }
    if (sawUploadField) return false;
    return false;
}

async function revealWorkdayResumeFileInput() {
    let fileInput = findWorkdayResumeFileInput();
    if (fileInput) return fileInput;

    const triggers = [
        queryVisible('[data-automation-id="uploadButton"]'),
        queryVisible('[data-automation-id*="resumeUpload"]'),
        ...[...document.querySelectorAll('button, [role="button"], a, span[role="button"]')].filter(isVisibleElement),
    ].filter(Boolean);

    for (const el of triggers) {
        const text = (el.innerText || el.getAttribute('aria-label') || '').trim();
        if (!/upload resume|attach resume|select files?|add attachment|drop files/i.test(text)) continue;
        workdayScrollToTarget(el, 120);
        await workdayClick(el);
        await wait(700);
        fileInput = findWorkdayResumeFileInput();
        if (fileInput) return fileInput;
    }

    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).toLowerCase();
        if (!/upload|resume|cv|attachment/i.test(label) || /linkedin|website|social/i.test(label)) continue;
        const selectFiles = [...container.querySelectorAll('button, [role="button"], a')].find(el => {
            const t = (el.innerText || el.getAttribute('aria-label') || '').trim();
            return /select files?|upload|attach|browse/i.test(t);
        });
        if (selectFiles) {
            workdayScrollToTarget(selectFiles, 120);
            await workdayClick(selectFiles);
            await wait(700);
            fileInput = container.querySelector('input[type="file"]') || findWorkdayResumeFileInput();
            if (fileInput) return fileInput;
        }
    }
    return null;
}

function hasWorkdayResumeUploadWidget() {
    if (findWorkdayResumeFileInput()) return true;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container).toLowerCase();
        if (!/upload|resume|cv|attachment/i.test(label) || /linkedin|website|social/i.test(label)) continue;
        if (/drop files|select files?/i.test(container.innerText || '')) return true;
    }
    return [...document.querySelectorAll('button, [role="button"], a, span[role="button"]')].some(el => {
        if (!isVisibleElement(el)) return false;
        const t = (el.innerText || el.getAttribute('aria-label') || '').trim();
        return /select files?|upload resume|drop files|attach resume/i.test(t);
    });
}

async function waitForWorkdayResumeUploadReady(timeoutMs = 6000) {
    for (let i = 0; i < Math.ceil(timeoutMs / 400); i++) {
        if (isWorkdayResumeUploaded(window.__wdCachedResume)) return true;
        if (findWorkdayResumeFileInput()) return true;
        for (const container of getWorkdayFieldContainers()) {
            const label = getContainerLabel(container).toLowerCase();
            if (!/upload|resume|cv|attachment/i.test(label) || /linkedin|website|social/i.test(label)) continue;
            if (/drop files|select files?/i.test(container.innerText || '')) return true;
        }
        const trigger = [...document.querySelectorAll('button, [role="button"], a, span[role="button"]')].find(el => {
            if (!isVisibleElement(el)) return false;
            const t = (el.innerText || el.getAttribute('aria-label') || '').trim();
            return /select files?|upload resume|drop files|attach resume/i.test(t);
        });
        if (trigger) return true;
        await wait(400);
    }
    debugLog(`${WD} resume upload widget wait timeout`);
    return false;
}

async function uploadResume(data) {
    // Always re-check live DOM — stale "already uploaded" must not skip a required dropzone.
    if (isWorkdayResumeUploaded(window.__wdCachedResume || data?.resume)) {
        debugLog(`${WD} resume already on page`, window.__wdCachedResume?.originalFilename || '');
        return;
    }
    if (!hasWorkdayResumeUploadWidget()) {
        await wait(400);
        if (!hasWorkdayResumeUploadWidget()) {
            if (getCurrentStepKey() === 'information') {
                debugLog(`${WD} no resume widget on information — skip upload`);
                return;
            }
            const ready = await waitForWorkdayResumeUploadReady(2000);
            if (!ready) {
                debugLog(`${WD} no resume widget on step — skip upload`);
                return;
            }
        }
    } else {
        await waitForWorkdayResumeUploadReady(4000);
    }
    const cv = await getWorkdayResumeOnce(data, 'uploadResume');
    if (isWorkdayResumeUploaded(cv)) {
        debugLog(`${WD} resume already on page`, cv?.originalFilename || '');
        return;
    }
    debugLog(`${WD} uploading resume`, cv?.originalFilename || '(no name)', 'url=', Boolean(cv?.url));
    let fileInput = null;
    for (let attempt = 0; attempt < 3; attempt++) {
        fileInput = await revealWorkdayResumeFileInput();
        if (fileInput) break;
        debugLog(`${WD} resume input not found, retry`, attempt + 1);
        await wait(400);
    }
    if (!fileInput) {
        debugLog(`${WD} no resume input on this step`);
        return;
    }
    if (!cv?.url) {
        if (fileInput.required) throw new SendCvError('CV required but not available');
        return;
    }
    const blob = await fetch(cv.url, { method: 'GET' }).then(res => res.blob());
    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(new File([blob], cv.originalFilename || 'resume.pdf', { type: blob.type || 'application/pdf', lastModified: Date.now() }));
    fileInput.files = dataTransfer.files;
    fileInput.dispatchEvent(new Event('change', { bubbles: true }));
    fileInput.dispatchEvent(new Event('input', { bubbles: true }));
    await waitForResumeProcessed(cv?.originalFilename);
    debugLog(`${WD} resume uploaded`, isWorkdayResumeUploaded(cv));
}

async function waitForResumeProcessed(filename) {
    for (let i = 0; i < 20; i++) {
        if (/successfully uploaded/i.test(document.body.innerText || '')) return true;
        if (filename && document.body.innerText.includes(filename.replace(/\.[^.]+$/, ''))) return true;
        await wait(500);
    }
    return false;
}

function isWorkdayDocumentUploadField(label, container = null) {
    const l = String(label || '').toLowerCase();
    if (!l) return false;
    if (/linkedin|website|social network|portfolio url/i.test(l)) return false;
    // Text questions about passport/visa *type* (not file uploads) — never treat as dropzone.
    if (/type of passport|passport\s*\/\s*visa|visa valid for|confirm the type of passport/i.test(l)
        && !/upload|attach|scan|copy of|photo of/i.test(l)) {
        return false;
    }
    const preview = String(container?.innerText || '').toLowerCase();
    const looksLikeDropzone = /drop files|select files/i.test(preview)
        || Boolean(container?.querySelector('input[type="file"]'));
    // Bare "passport" in a long question without upload UI is not a document field.
    if (!looksLikeDropzone && !/upload|attach|certificate|pay.?slip|nric|driver'?s license|document|scanned copy/i.test(l)) {
        return false;
    }
    return /upload|attach|certificate|pay.?slip|payslip|nric|passport|driver'?s license|vaccination|diploma|degree certificate|spm certificate|master\/?\s*degree|scanned copy/i.test(l)
        || (/drop files|select files/i.test(preview) && /upload|certificate|slip|nric|passport|license/i.test(l + ' ' + preview));
}

function isWorkdayUploadFieldFilled(container, filenameStem = '') {
    if (!container) return false;
    const preview = (container.innerText || '').replace(/\s+/g, ' ');
    if (/successfully uploaded/i.test(preview)) return true;
    if (filenameStem && preview.toLowerCase().includes(String(filenameStem).toLowerCase())) return true;
    if (container.querySelector('[data-automation-id*="fileName"], [data-automation-id*="uploadedFile"], [data-automation-id*="attachment"]')) {
        return true;
    }
    // Still showing empty dropzone CTA
    if (/drop files here|select files/i.test(preview) && !/successfully uploaded/i.test(preview)) {
        return false;
    }
    return false;
}

/** Required document dropzones (payslip, vaccination, NRIC, certificates) — reuse resume PDF. */
async function fillRequiredWorkdayDocumentUploads(data) {
    const cv = await getWorkdayResumeOnce(data, 'documentUploads');
    if (!cv?.url) {
        debugLog(`${WD} document uploads skipped — no resume`);
        return;
    }
    const filenameStem = cv.originalFilename?.replace(/\.[^.]+$/, '') || '';
    let blob = null;
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!isContainerRequired(container)) continue;
        if (!isWorkdayDocumentUploadField(label, container)) continue;
        if (isWorkdayUploadFieldFilled(container, filenameStem)) continue;
        // Skip dedicated resume/CV widgets — handled by uploadResume
        if (/^upload (a )?(resume|cv)\b|attach (your )?resume/i.test(label.replace(/\*/g, '').trim())) continue;

        let fileInput = container.querySelector('input[type="file"]');
        if (!fileInput) {
            const selectFiles = [...container.querySelectorAll('button, [role="button"], a')].find(el => {
                const t = (el.innerText || el.getAttribute('aria-label') || '').trim();
                return /select files?|upload|attach|browse/i.test(t);
            });
            if (selectFiles) {
                workdayScrollToTarget(selectFiles, 120);
                await workdayClick(selectFiles);
                await wait(500);
                fileInput = container.querySelector('input[type="file"]');
            }
        }
        if (!fileInput) {
            debugLog(`${WD} document upload no input`, label.slice(0, 60));
            continue;
        }
        if (!blob) {
            blob = await fetch(cv.url, { method: 'GET' }).then(res => res.blob());
        }
        const dataTransfer = new DataTransfer();
        dataTransfer.items.add(new File(
            [blob],
            cv.originalFilename || 'document.pdf',
            { type: blob.type || 'application/pdf', lastModified: Date.now() }
        ));
        fileInput.files = dataTransfer.files;
        fileInput.dispatchEvent(new Event('change', { bubbles: true }));
        fileInput.dispatchEvent(new Event('input', { bubbles: true }));
        await wait(800);
        debugLog(`${WD} document uploaded`, label.slice(0, 60), 'ok=', isWorkdayUploadFieldFilled(container, filenameStem));
    }
}

function toEpochMillis(d) {
    if (typeof d !== 'number' || !Number.isFinite(d)) return null;
    const digits = String(Math.trunc(Math.abs(d))).length;
    return digits <= 10 ? d * 1000 : d;
}

function parseEntryDates(entry) {
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    const parse = (d) => {
        if (d == null || d === '') return null;
        if (typeof d === 'number') {
            const ms = toEpochMillis(d);
            const dt = new Date(ms);
            if (!Number.isNaN(dt.getTime())) {
                const month = String(dt.getUTCMonth() + 1).padStart(2, '0');
                return { year: String(dt.getUTCFullYear()), month: months[dt.getUTCMonth()], iso: `${dt.getUTCFullYear()}-${month}` };
            }
        }
        const raw = String(d);
        const m = raw.match(/(\d{4})-(\d{2})/);
        if (!m) return null;
        return { year: m[1], month: months[Number(m[2]) - 1], iso: `${m[1]}-${m[2]}` };
    };
    return { start: parse(entry.startDate), end: parse(entry.endDate) };
}

function getEducationDateFallbacks(entry) {
    const dates = parseEntryDates(entry);
    if (dates.start && dates.end) return dates;
    const endYear = dates.end?.year || '2014';
    const startYear = dates.start?.year || String(Number(endYear) - 4);
    return {
        start: dates.start || { year: startYear, month: 'September', iso: `${startYear}-09` },
        end: dates.end || { year: endYear, month: 'May', iso: `${endYear}-05` },
    };
}

// A required "From" date left null (e.g. missing/corrupt startDate on one profile entry) stays
// permanently blank otherwise — countWorkdayStepEmptyRequired blocks Next indefinitely with no
// self-correcting retry (see chrome-extension.mdc Workday step stuck: experience). Mirror
// getEducationDateFallbacks: derive a plausible start relative to the end date (or ~2 years back
// from today for current/open-ended roles) instead of leaving the field empty forever.
function getExperienceDateFallbacks(entry) {
    const dates = parseEntryDates(entry);
    if (dates.start) return dates;
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    if (dates.end) {
        const m = (dates.end.iso || '').match(/(\d{4})-(\d{2})/);
        if (m) {
            const year = String(Number(m[1]) - 2);
            return { start: { year, month: dates.end.month, iso: `${year}-${m[2]}` }, end: dates.end };
        }
    }
    const now = new Date();
    const year = String(now.getUTCFullYear() - 2);
    const month = months[now.getUTCMonth()];
    const iso = `${year}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
    return { start: { year, month, iso }, end: dates.end };
}

const WORKDAY_DEGREE_CANDIDATES = [
    "Bachelor's Degree",
    'Bachelors Degree',
    'Bachelor of Science',
    'Bachelor of Arts',
    'Bachelor',
    "Master's Degree",
    'Master of Science',
    'Associate Degree',
    "Associate's Degree",
    'Other',
];

function normalizeDegreeSearchTerms(entry) {
    const raw = String(entry?.degree || '').trim();
    const terms = [];
    if (raw) terms.push(raw);
    if (/bachelor/i.test(raw) || !raw) {
        terms.push("Bachelor's Degree", 'Bachelors Degree', 'Bachelor of Science', 'Bachelor of Arts', 'Bachelor');
    } else if (/master/i.test(raw)) {
        terms.push("Master's Degree", 'Master of Science', 'Master');
    } else if (/associate/i.test(raw)) {
        terms.push("Associate's Degree", 'Associate Degree', 'Associate');
    }
    for (const t of WORKDAY_DEGREE_CANDIDATES) {
        if (!terms.includes(t)) terms.push(t);
    }
    return [...new Set(terms.filter(Boolean))];
}

function isChipDisplayPopup(popup) {
    if (!popup) return false;
    // Hear/phone selected chips are role=option with data-automation-id=selectedItem — not a
    // dropdown list. Bare `div` in the orphan-popup walk (below) used to return the chip itself
    // as the "active popup", so City (bah.wd1) scanned ["Indeed"] forever.
    if (popup.getAttribute?.('data-automation-id') === 'selectedItem'
        || popup.closest?.('[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"]') === popup
        || /^pill-/i.test(popup.id || '')) {
        return true;
    }
    const opts = getScopedDropdownOptions(popup).slice(0, 8).map(o => optionText(o).toLowerCase());
    if (!opts.length) return false;
    if (opts.every(t => /press delete to clear|press delete/i.test(t))) return true;
    if (opts.some(t => /press delete to clear|press delete/i.test(t)) && opts.length <= 4) return true;
    // Selected-chip chrome only: "Indeed" / phone-code pill without a real option list.
    if (opts.length <= 3
        && opts.every(t => /indeed|linkedin|press delete|united states of america \(\+\d\)|^\+\d+$/i.test(t))) {
        return true;
    }
    return false;
}

/** Visible Workday option lists — includes promptContainer (closeWorkdayPopups already targets it). */
function getWorkdayVisiblePopupCandidates() {
    const sels = [
        '[data-automation-id="activeListContainer"]',
        '[data-automation-id="wd-MenuList"]',
        '[data-automation-id="promptOptions"]',
        '[data-automation-id="promptOptionList"]',
        '[data-automation-id*="promptContainer"]',
        'ul[role="listbox"]',
        'div[role="listbox"]',
        '[role="listbox"]',
    ];
    const seen = new Set();
    const out = [];
    for (const el of document.querySelectorAll(sels.join(', '))) {
        if (seen.has(el) || !isVisibleElement(el) || isChipDisplayPopup(el)) continue;
        if (el.getAttribute('data-automation-id') === 'selectedItem') continue;
        if (el.getAttribute('role') === 'option') continue;
        seen.add(el);
        out.push(el);
    }
    // Options rendered outside a recognized listbox (ovationhealthcare.wd5 years/notice).
    if (!out.length) {
        const orphanOpts = [...document.querySelectorAll(
            '[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]',
        )].filter((el) => {
            if (!isVisibleElement(el)) return false;
            if (el.getAttribute('data-automation-id') === 'selectedItem') return false;
            if (el.closest('[data-automation-id="selectedItem"], [data-automation-id="selectedItemList"]')) return false;
            const t = optionText(el);
            if (/press delete to clear/i.test(t)) return false;
            return true;
        });
        if (orphanOpts.length) {
            let parent = orphanOpts[0].closest(
                '[data-automation-id="activeListContainer"], [data-automation-id="wd-MenuList"],'
                + '[data-automation-id="promptOptions"], [data-automation-id="promptOptionList"],'
                + '[data-automation-id*="promptContainer"], [role="listbox"], [role="menu"], ul',
            );
            // Never promote the option node itself (div[role=option] matched bare `div` before).
            if (!parent || parent === orphanOpts[0] || parent.getAttribute('role') === 'option') {
                parent = orphanOpts[0].parentElement;
                while (parent && (parent === orphanOpts[0] || parent.getAttribute('role') === 'option'
                    || parent.getAttribute('data-automation-id') === 'selectedItem')) {
                    parent = parent.parentElement;
                }
            }
            if (parent && isVisibleElement(parent) && !isChipDisplayPopup(parent)) out.push(parent);
        }
    }
    return out;
}

function findActiveWorkdayPopup() {
    const popups = getWorkdayVisiblePopupCandidates();
    return popups.length ? popups[popups.length - 1] : null;
}

function findPopupNearField(fieldRoot, labelLower = '') {
    const label = labelLower || getContainerLabel(fieldRoot || {}).toLowerCase();
    const trigger = fieldRoot ? getWorkdayDropdownTrigger(fieldRoot) : null;
    const controlsId = trigger?.getAttribute('aria-controls')
        || fieldRoot?.querySelector?.('[aria-controls]')?.getAttribute('aria-controls');
    if (controlsId) {
        const controlled = document.getElementById(controlsId);
        if (controlled && isVisibleElement(controlled) && !isWrongPopupForField(controlled, label)) return controlled;
    }
    const visiblePopups = getWorkdayVisiblePopupCandidates();
    const popups = visiblePopups.filter(popup => !isWrongPopupForField(popup, label) && !isChipDisplayPopup(popup));
    if (!fieldRoot || !popups.length) {
        if (/\bstate\b/i.test(label) && !/phone/i.test(label)) return null;
        // If some popup IS visible but every one of them was excluded as belonging to a different field
        // (isWrongPopupForField), falling back to findActiveWorkdayPopup() here would just hand back one
        // of those very same excluded popups unchecked — undoing the filter above. Only fall back to
        // "any visible popup" when nothing matched the popup selector at all (genuinely nothing open);
        // observed on icf.wd5, where a stale "Country Phone Code" listbox stayed the only visible
        // listbox while filling the adjacent "Phone Device Type" field, and this fallback kept handing
        // it back after the field-specific filter had already correctly rejected it.
        if (visiblePopups.length) return null;
        return findActiveWorkdayPopup();
    }
    const rect = fieldRoot.getBoundingClientRect();
    let best = null;
    let bestDist = Infinity;
    for (const popup of popups) {
        const pr = popup.getBoundingClientRect();
        const dist = Math.abs(pr.top - rect.bottom) + Math.abs(pr.left - rect.left) * 0.25;
        if (dist < bestDist) {
            bestDist = dist;
            best = popup;
        }
    }
    return best || popups[popups.length - 1];
}

function isDegreeLevelOption(text) {
    const t = String(text).toLowerCase().trim();
    if (!t || t === 'select one') return false;
    // Dotted abbreviations ("B.S.", "B.A.", "A.A.S.") are unambiguous degree-level codes —
    // check them before the field-of-study exclusion list below (observed on ryder.wd5).
    if (WORKDAY_DEGREE_ABBREVIATIONS.includes(normalizeDegreeAbbrev(t))) return true;
    if (/computer science|agriculture|accountancy|anthropology|engineering|finance\/banking|artificial intelligence|architectural|accounting and finance/i.test(t)) {
        return false;
    }
    return /primary|middle school|high school|secondary|vocational|technical|associate|bachelor|master|doctor|phd|ged|certificate|diploma|qualification|postgraduate|undergraduate|degree|^other$|^(as|aa|ba|bs|bas|bba|jd|mba|ms|ma|me|msieor|dsc)$/i.test(t);
}

function findDegreeLevelOptions(popup) {
    return getScopedDropdownOptions(popup).filter(o => isDegreeLevelOption(optionText(o)));
}

async function dispatchListKey(key, target) {
    const opts = { key, code: key, bubbles: true, cancelable: true };
    const el = target || document.activeElement;
    el?.dispatchEvent(new KeyboardEvent('keydown', opts));
    el?.dispatchEvent(new KeyboardEvent('keyup', opts));
}

async function pickDegreeBachelor(fieldRoot, popup, button) {
    const options = getScopedDropdownOptions(popup);
    const idx = findBachelorDegreeOptionIndex(options);
    if (idx < 0) return false;

    debugLog(`${WD} degree bachelor index`, idx, optionText(options[idx]));
    if (button) {
        await workdayClick(button);
        await wait(800);
        for (let i = 0; i <= idx; i++) {
            button.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', bubbles: true }));
            await wait(100);
        }
        button.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true }));
        await wait(800);
        if (isDegreeFilled(fieldRoot)) return true;
    }

    const match = options[idx];
    workdayScrollToTarget(match, 120);
    const clickTargets = [
        match,
        match.querySelector('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"]'),
        match.closest('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"]'),
    ].filter(Boolean);

    for (const target of clickTargets) {
        await workdayClick(target);
        await wait(500);
        if (isDegreeFilled(fieldRoot)) return true;
        workdayClickElement(target);
        await wait(500);
        if (isDegreeFilled(fieldRoot)) return true;
    }

    await clickWorkdayOption(match);
    await wait(500);
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await wait(400);
    return isDegreeFilled(fieldRoot);
}

function getScopedDropdownOptions(popup) {
    const scope = popup || findActiveWorkdayPopup() || document;
    return [...scope.querySelectorAll('[data-automation-id="promptOption"], [data-automation-id="promptLeafNode"], [role="option"], [data-automation-id="menuItem"], [data-automation-id*="menuItem"], li[data-automation-id*="option"]')]
        .filter((el) => {
            if (!isVisibleElement(el)) return false;
            if (el.getAttribute('data-automation-id') === 'selectedItem') return false;
            if (el.closest('[data-automation-id="selectedItemList"]')
                && el.getAttribute('data-automation-id') === 'selectedItem') return false;
            return true;
        });
}

function optionText(o) {
    return (o.getAttribute('aria-label') || o.innerText || o.textContent || '')
        .trim().toLowerCase().replace(/\s+not checked/i, '').replace(/^\d+\.\s*/, '');
}

const WORKDAY_COMMUTE_TIME_OPTIONS = ['<30 minutes', '30 min to 1 hour', '1-2 hours', '2+ hours'];

function isCommuteTimeFieldLabel(label) {
    return /commute time/i.test(String(label || ''));
}

function isKnownCommuteTimeOption(value) {
    const v = String(value || '').toLowerCase();
    return WORKDAY_COMMUTE_TIME_OPTIONS.some(o => o.toLowerCase() === v);
}

function getPhoneDeviceTypeCandidates() {
    // Workday tenants vary: Mobile/Cell vs Personal Cell/Work Cell vs Fax/Landline/Pager (solenis.wd1)
    // "Pers Mobile" is a common abbreviated Personal Mobile label (entegris.wd1).
    return [
        'Mobile',
        'Personal Cell',
        'Work Cell',
        'Cell',
        'Personal Mobile',
        'Pers Mobile',
        'Cellular',
        'Mobile Phone',
        'Cell Phone',
        'Telephone',
        'Landline',
        'Home',
        'Business',
        'Fax',
        'Pager',
    ];
}

function isPhoneDeviceTypeOptionText(text) {
    const t = String(text || '').trim();
    if (!t || /^select one$/i.test(t)) return false;
    // Reject hear-about / source options that leak into this field's option scan.
    if (/indeed|linkedin|job board|company website|referral|campus|social network|glassdoor|monster|ziprecruiter|how did you hear/i.test(t)
        && !/personal cell|work cell|\bmobile\b|\btelephone\b|\bcellular\b|\bhome\b|\bbusiness\b/i.test(t)) {
        return false;
    }
    return /personal cell|work cell|pers(?:onal)?\s*mobile|\bmobile\b|\bcell\b|\bcellular\b|\btelephone\b|mobile phone|cell phone|\bhome\b|\bbusiness\b/i.test(t);
}

function findPhoneDeviceTypeOption(options, preferredValues = null) {
    const opts = (options || []).filter(o => isPhoneDeviceTypeOptionText(optionText(o)));
    if (!opts.length) return null;
    const preferred = (Array.isArray(preferredValues) ? preferredValues : [preferredValues])
        .map(v => String(v || '').toLowerCase().trim())
        .filter(Boolean);
    for (const p of preferred) {
        const exact = opts.find(o => optionText(o).toLowerCase() === p);
        if (exact) return exact;
        const partial = opts.find(o => {
            const ot = optionText(o).toLowerCase();
            // Require substantial overlap — "personal cell".includes("indeed") must never match.
            if (ot.length < 3 || p.length < 3) return false;
            return ot.includes(p) || (p.includes(ot) && ot.length >= 4);
        });
        if (partial) return partial;
    }
    // Prefer mobile/cell variants over home/business when no preferred match — never opts[0]
    // from an unrelated listbox (that used to return "Indeed" on solenis.wd1).
    return opts.find(o => /personal cell|work cell/i.test(optionText(o)))
        || opts.find(o => /mobile|cell|cellular/i.test(optionText(o)))
        || opts.find(o => /telephone|phone/i.test(optionText(o)))
        || opts.find(o => /\bhome\b|\bbusiness\b/i.test(optionText(o)))
        || null;
}

function clearWorkdaySingleSelectMissKey(label) {
    const openKey = normalizeDropdownOpenKey(label);
    window.__wdSingleSelectMissKeys?.delete(openKey);
    resetWorkdayDropdownOpenCount(openKey);
}

function isWorkdayYesNoOptionList(optionLabels) {
    const options = (optionLabels || []).map(o => String(o).trim()).filter(o => o && !/^select one$/i.test(o));
    if (options.length < 2 || options.length > 6) return false;
    const hasYes = options.some(o => /^yes\b/i.test(o));
    const hasNo = options.some(o => /^no\b/i.test(o));
    if (!hasYes || !hasNo) return false;
    // Allow tertiary "Don't know" / "Unsure" (sanofi.wd3 apprenticeship Yes|No|Don't know).
    return options.every(o => /^(yes|no)\b/i.test(o)
        || /^(n\/a|na|not applicable|prefer not|decline|don'?t know|do not know|unsure|unknown|not sure)/i.test(o));
}

/** Map "20%" / "25" → nearest "up to 25%" band (guidehouse.wd1 travel dropdown). */
function resolveTravelPercentageOption(value, optionLabels) {
    const options = (optionLabels || []).map(o => String(o).trim()).filter(o => o && !/^select one$/i.test(o));
    if (!options.length) return null;
    const raw = String(value ?? '').trim();
    if (!raw) return null;
    const exact = options.find(o => o.toLowerCase() === raw.toLowerCase());
    if (exact) return exact;
    const pctMatch = raw.match(/(\d+)\s*%?/);
    if (!pctMatch && /unwilling|none|not willing|no travel/i.test(raw)) {
        return options.find(o => /unwilling|none|not willing|0\s*%/i.test(o)) || null;
    }
    if (!pctMatch) return null;
    const pct = parseInt(pctMatch[1], 10);
    const bands = options.map((o) => {
        const up = o.match(/up to\s*(\d+)\s*%/i);
        if (up) return { o, n: parseInt(up[1], 10), kind: 'up' };
        const exactPct = o.match(/^(\d+)\s*%$/i);
        if (exactPct) return { o, n: parseInt(exactPct[1], 10), kind: 'exact' };
        const range = o.match(/(\d+)\s*%?\s*[-–—]\s*(\d+)\s*%/i);
        if (range) return { o, n: parseInt(range[2], 10), kind: 'range', min: parseInt(range[1], 10) };
        return null;
    }).filter(Boolean).sort((a, b) => a.n - b.n);
    if (!bands.length) return null;
    const fit = bands.find(b => b.kind === 'up' && b.n >= pct)
        || bands.find(b => b.kind === 'exact' && b.n >= pct)
        || bands.find(b => b.kind === 'range' && pct >= b.min && pct <= b.n)
        || bands.find(b => b.n >= pct);
    return (fit || bands[bands.length - 1]).o;
}

function getWorkdayStreamLocalFallback(label, optionLabels) {
    const options = (optionLabels || []).map(o => String(o).trim()).filter(o => o && !/^select one$/i.test(o));
    if (!options.length) return null;
    if (isWorkdayAgreeDisagreeOptionsOnly(options)) {
        return pickWorkdayAgreeOption(options);
    }
    const ll = String(label || '').toLowerCase();
    // Plain Yes/No lists: invalid stream values (city, free text, profile snippets) must resolve
    // locally — never open/miss the dropdown on "Jacksonville" vs Yes|No (albemarle.wd5).
    if (isWorkdayYesNoOptionList(options)) {
        const answer = getWorkdayYesNoSmartDefault(label) || getHardcodedYesNoAnswer(label)
            // Invalid free-text stream (school name, city) against Yes|No|Don't know → local No
            // when the label is a Yes/No interrogative (sanofi.wd3 / albemarle.wd5 class).
            || (isWorkdayYesNoInterrogativeLabel(label) ? 'No' : null);
        if (answer) {
            return options.find(o => new RegExp(`^${String(answer).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i').test(o))
                || (answer === 'Yes'
                    ? options.find(o => /^yes\b/i.test(o))
                    : options.find(o => /^no\b/i.test(o)));
        }
    }
    if (/percentage.*travel|travel.*percentage|willing to travel|travel time|how much.*travel/i.test(ll)) {
        // No stream value here — pick a moderate default band when options are % buckets.
        return options.find(o => /up to\s*25\s*%/i.test(o))
            || options.find(o => /up to\s*50\s*%/i.test(o))
            || options.find(o => /20\s*%|25\s*%/i.test(o))
            || options.find(o => /up to/i.test(o))
            || null;
    }
    if (/commute time/i.test(ll)) {
        return options.find(o => /30 min to 1 hour/i.test(o))
            || options.find(o => /1-2 hours/i.test(o))
            || options.find(o => /<30 minutes/i.test(o))
            || options[0];
    }
    // Office / basecamp site lists (waystar.wd1) — stream often returns N/A or residency city
    if (/basecamp|working from|which .{0,60}location would you|prefer(?:red)? (?:office|work) location|office location would you/i.test(ll)) {
        const jobLoc = String(window.__wdHistoryLocation || '').toLowerCase();
        const byJob = options.find(o => jobLoc && jobLoc.includes(String(o).split(',')[0].trim().toLowerCase()));
        return byJob || options.find(o => /atlanta|louisville|duluth|lehi/i.test(o)) || options[0];
    }
    if (/work arrangement|hybrid|remote|onsite/i.test(ll)) {
        return options.find(o => /hybrid/i.test(o)) || options.find(o => /remote/i.test(o)) || options[0];
    }
    if (/work schedule|full.time|part.time/i.test(ll)) {
        return options.find(o => /full.time/i.test(o)) || options[0];
    }
    if (/availability to start|when.*start|available to start/i.test(ll)) {
        return options.find(o => /2 weeks|within 2/i.test(o))
            || options.find(o => /immediately|asap/i.test(o))
            || options.find(o => /1 week/i.test(o))
            || options.find(o => /3 weeks|4 weeks/i.test(o))
            || options[0];
    }
    if (/working rights|work authorization|right to work|legal right to work/i.test(ll)) {
        return options.find(o => /yes.*legal right|have the legal right/i.test(o) && !/do not|don'?t|no,/i.test(o))
            || options.find(o => /australian citizen/i.test(o))
            || options.find(o => /permanent resident/i.test(o))
            || options.find(o => /british|irish citizen/i.test(o))
            || options.find(o => /new zealand citizen/i.test(o))
            || options.find(o => /citizen/i.test(o) && !/require|visa/i.test(o))
            || options.find(o => /unlimited|unrestricted|full working/i.test(o))
            || options.find(o => /^yes\b/i.test(o) && !/do not|don'?t/i.test(o))
            || (profileExpectsUS(window.__wdApplyData?.profile)
                && !/legal right to work/i.test(ll)
                ? (options.find(o => /require visa|visa assistance/i.test(o)) || options.find(o => /^no\b/i.test(o)))
                : null)
            || options.find(o => /^yes\b/i.test(o))
            || options[0];
    }
    if (/notice period/i.test(ll)) {
        return options.find(o => /2 weeks/i.test(o))
            || options.find(o => /1 month|30 days|4 weeks/i.test(o))
            || options.find(o => /2 months|60 days/i.test(o))
            || options.find(o => /immediate|asap|none|n\/a/i.test(o))
            || options[0];
    }
    if (/how many years|years of experience|experience in the healthcare/i.test(ll)
        && !/^\s*(do|have|are)\s+you\b/i.test(ll)) {
        const band = getWorkdayYearsExperienceBandAnswer(ll, options, window.__wdApplyData?.profile);
        if (band) {
            return options.find(o => o.toLowerCase() === String(band).toLowerCase())
                || options.find(o => o.toLowerCase().includes(String(band).toLowerCase()))
                || band;
        }
        return options.find(o => /\d+\+\s*years|or more|over \d+/i.test(o))
            || options.find(o => /\d+\s*[-–]\s*\d+/i.test(o))
            || options[0];
    }
    if (isWorkdayDisclosureGenderField(ll) || isWorkdayGenderIdentityField(ll)
        || /please select your gender|please indicate your gender/i.test(ll)) {
        return options.find(o => /prefer not|decline|choose not|not declared|not specified|^unknown$/i.test(o))
            || null;
    }
    if (isWorkdayFormerEmployerQuestion(ll) || /worked for .{0,40}entities|following entities/i.test(ll)) {
        return options.find(o => /i have never worked|never worked for|have not worked for/i.test(o))
            || options.find(o => /^no\b/i.test(o))
            || null;
    }
    if (isWorkdayRelativeEmployerEntityQuestion(ll) || /relatives who work for/i.test(ll)) {
        return options.find(o => /do not have any relatives|no relatives who work/i.test(o))
            || options.find(o => /^no\b/i.test(o))
            || null;
    }
    if (/keep in touch|sharing future career|career opportunities at/i.test(ll)) {
        return options.find(o => /^i consent$/i.test(o))
            || options.find(o => /^yes$/i.test(o))
            || options.find(o => /^no$/i.test(o))
            || options[0];
    }
    if (/how long have you lived there/i.test(ll)) {
        return options.find(o => /over 5|5 years or more|more than 5/i.test(o))
            || options.find(o => /under 5|less than 5/i.test(o))
            || options[0];
    }
    if (/which region are you willing to work|region are you willing to work in/i.test(ll)) {
        return options.find(o => /central/i.test(o))
            || options.find(o => /north east|northeast/i.test(o))
            || options.find(o => /state.?wide|all/i.test(o))
            || options[0];
    }
    if (isCompensationFieldLabel(ll) || /salary|compensation|pay expectation/i.test(ll)) {
        const fakeOpts = options.map((text) => ({ innerText: text, textContent: text, getAttribute: () => null }));
        const match = findSalaryBracketDropdownMatch(
            fakeOpts,
            getProfileSalaryAmount(window.__wdApplyData?.profile || {}),
            getProfileSalaryAmountLocal(window.__wdApplyData?.profile || {}),
        );
        if (match) return optionText(match);
    }
    if (/clearance|security clearance/i.test(ll)) {
        return options.find(o => /never have held|no clearance|no security|not applicable|^none$/i.test(o))
            || options.find(o => /^no\b/i.test(o))
            // Highest-level dropdowns often only list clearance tiers — "Other" when never held.
            || (/highest level|previously obtained|currently held/i.test(ll)
                ? options.find(o => /^other$/i.test(o))
                : null)
            || null;
    }
    return null;
}

function resolveStreamValueToDropdownOption(streamValue, optionLabels, label = '') {
    const options = (optionLabels || []).map(o => String(o).trim()).filter(o => o && !/^select one$/i.test(o));
    if (!options.length || streamValue == null || streamValue === '') return null;
    let raw = String(Array.isArray(streamValue) ? streamValue[0] : streamValue).trim();
    if (!raw) return null;
    const ll = String(label || '').toLowerCase();
    // Never accept stream "No" for legal right to work Yes/No questions
    if (/do you have the (?:legal )?right to work|legal right to work/i.test(ll)
        && !/status|additional details|what is your current/i.test(ll)
        && /^(no\b|no,)/i.test(raw)) {
        raw = 'Yes';
    }
    let hit = options.find(o => o.toLowerCase() === raw.toLowerCase());
    if (hit) return hit;
    hit = options.find(o => textMatchesCandidate(o, raw) || textMatchesCandidate(raw, o));
    if (hit) return hit;
    const fakeOpts = options.map((text, i) => {
        const el = { innerText: text, textContent: text, getAttribute: () => null };
        return el;
    });
    const domMatch = findDropdownMatch(fakeOpts, raw, ll);
    if (domMatch) return optionText(domMatch);
    if (/commute time/i.test(ll)) {
        const vlow = raw.toLowerCase();
        if (/more than|over|longer|1\+|2\+|>\s*1|hour\+/i.test(vlow)) {
            return options.find(o => /2\+ hours/i.test(o)) || options.find(o => /1-2 hours/i.test(o));
        }
        if (/less than|under|<\s*30|30 min or less|short/i.test(vlow)) {
            return options.find(o => /<30 minutes/i.test(o));
        }
        if (/30 min|45 min|half/i.test(vlow)) {
            return options.find(o => /30 min to 1 hour/i.test(o));
        }
        if (/1-2|one to two|1 to 2/i.test(vlow)) {
            return options.find(o => /1-2 hours/i.test(o));
        }
    }
    if (/percentage.*travel|travel.*percentage|willing to travel|how much.*travel/i.test(ll)) {
        const travelHit = resolveTravelPercentageOption(raw, options);
        if (travelHit) return travelHit;
    }
    // Salary bands: AI often returns "100000 - 120000" while options are "$100,000 - $120,000"
    // (parsons.wd5 annualized salary). Normalize digits / match via bracket bounds.
    if (isCompensationFieldLabel(ll) || /salary|compensation|pay expectation/i.test(ll)) {
        const digits = raw.replace(/[^\d.\-–]/g, ' ').trim();
        const range = digits.match(/(\d+(?:\.\d+)?)\s*[-–]\s*(\d+(?:\.\d+)?)/);
        if (range) {
            const lo = Number(range[1]);
            const hi = Number(range[2]);
            const mid = (lo + hi) / 2;
            const fakeOpts = options.map((text) => ({ innerText: text, textContent: text, getAttribute: () => null }));
            const match = findSalaryBracketDropdownMatch(fakeOpts, mid, mid);
            if (match) return optionText(match);
            const byDigits = options.find((o) => {
                const od = String(o).replace(/[^\d.\-–]/g, ' ').replace(/\s+/g, ' ').trim();
                return od.includes(`${lo}`) && od.includes(`${hi}`);
            });
            if (byDigits) return byDigits;
        }
        const single = Number(String(raw).replace(/[^\d.]/g, ''));
        if (Number.isFinite(single) && single > 0) {
            const fakeOpts = options.map((text) => ({ innerText: text, textContent: text, getAttribute: () => null }));
            const match = findSalaryBracketDropdownMatch(fakeOpts, single, single);
            if (match) return optionText(match);
        }
    }
    if (/clearance|security clearance/i.test(ll)
        && /^(n\/a|na|none|not applicable|not available|no)$/i.test(raw)) {
        return options.find(o => /never have held|no clearance|no security|^none$/i.test(o))
            || options.find(o => /^no\b/i.test(o))
            || getWorkdayStreamLocalFallback(label, options);
    }
    if (/^(n\/a|na|none|not applicable|not available)$/i.test(raw)) {
        return getWorkdayStreamLocalFallback(label, options);
    }
    return null;
}

function resolveWorkdayStreamFieldValue(value, field) {
    let optionLabels = (field.options || []).map(o => String(o).trim()).filter(o => o && !/^select one$/i.test(o));
    if (!optionLabels.length && isCommuteTimeFieldLabel(field.label)) {
        optionLabels = WORKDAY_COMMUTE_TIME_OPTIONS.slice();
    }
    if (!optionLabels.length) return value;
    const usesOptions = field.type === 'select' || field.type === 'radio' || field.type === 'checkbox'
        || Array.isArray(field.element);
    if (!usesOptions) return value;
    if (Array.isArray(value)) {
        const resolved = [];
        for (const v of value) {
            const hit = resolveStreamValueToDropdownOption(v, optionLabels, field.label);
            if (hit) resolved.push(hit);
            else if (v != null && String(v).trim()) resolved.push(v);
        }
        if (resolved.length) return resolved;
        const fallback = getWorkdayStreamLocalFallback(field.label, optionLabels);
        return fallback ? [fallback] : value;
    }
    const raw = value;
    if (raw == null || raw === '') return value;
    const hit = resolveStreamValueToDropdownOption(raw, optionLabels, field.label);
    if (hit) {
        if (String(hit).toLowerCase() !== String(raw).toLowerCase()) {
            debugLog(`${WD} stream value resolved`, field.label.slice(0, 60), raw, '->', hit);
        }
        return hit;
    }
    const fallback = getWorkdayStreamLocalFallback(field.label, optionLabels);
    if (fallback) {
        debugLog(`${WD} stream value invalid — local fallback`, field.label.slice(0, 60), raw, '->', fallback);
        window.__wdStreamInvalidValues = window.__wdStreamInvalidValues || new Set();
        window.__wdStreamInvalidValues.add(field.label);
        return fallback;
    }
    debugLog(`${WD} stream value invalid — no option match`, field.label.slice(0, 60), raw,
        'options=', optionLabels.slice(0, 6).join(' | '));
    return value;
}

function findDropdownMatch(options, value, labelLower = '') {
    const target = String(value).toLowerCase();
    let match = options.find(o => optionText(o) === target);
    if (!match && /undeclared/i.test(target)) {
        match = options.find(o => /undeclared/i.test(optionText(o)));
    }
    if (!match && /do not wish to identify|don't wish to identify/i.test(target)) {
        match = options.find(o => /do not wish to identify|don't wish to identify/i.test(optionText(o)));
    }
    if (!match && /do not wish to self/i.test(target)) {
        match = options.find(o => /do not wish to self/i.test(optionText(o)));
    }
    if (!match && /gender/i.test(labelLower)) {
        match = options.find(o => /choose not|not to disclose|not declared|undeclared|decline to answer|prefer not|do not wish|don't wish|no response|is not listed/i.test(disclosureOptionText(o)));
    }
    if (!match && /ethnic/i.test(labelLower)) {
        match = options.find(o => /do not wish to identify|don't wish to identify/i.test(optionText(o)));
    }
    if (!match && /veteran/i.test(labelLower)) {
        match = options.find(o => /do not wish to self|not a veteran|non-veteran|i am not a veteran|i'm not a veteran/i.test(optionText(o)));
    }
    if (!match && target.includes('united states')) {
        match = options.find(o => /united states of america/i.test(o.innerText || o.textContent || ''));
    }
    if (!match && /phone code/i.test(labelLower)) {
        match = options.find(o => {
            const text = optionText(o);
            return /united states/i.test(text) && /\(\+1\)/.test(text);
        });
    }
    if (!match && /^\+1$/.test(String(value).trim())) {
        match = options.find(o => /\(\+1\)/.test(optionText(o)));
    }
    if (!match && /^degree$/i.test(labelLower.replace(/\*/g, '').trim())) {
        match = options.find(o => /^bachelor'?s$/i.test(optionText(o)))
            || options.find(o => /^bachelor'?s\b/i.test(optionText(o)) && !/nursing/i.test(optionText(o)));
    }
    if (!match && isWorkdayClearanceFieldLabel(labelLower)) {
        match = options.find(o => /^(none|no clearance|no security|not applicable|n\/a|no active)/i.test(optionText(o)));
    }
    if (!match && /^no$/i.test(target)) {
        match = options.find(o => /^no\b/i.test(disclosureOptionText(o)) && !/^yes\b/i.test(disclosureOptionText(o)));
    }
    if (!match && /disability/i.test(labelLower) && /^no/i.test(target)) {
        match = options.find(o => /^no\b/i.test(disclosureOptionText(o)));
    }
    if (!match && isCompensationFieldLabel(labelLower)) {
        match = findSalaryBracketDropdownMatch(
            options,
            getProfileSalaryAmount(window.__wdApplyData?.profile || {}),
            getProfileSalaryAmountLocal(window.__wdApplyData?.profile || {}),
        );
    }
    if (!match && isCommuteTimeFieldLabel(labelLower)) {
        const resolved = resolveStreamValueToDropdownOption(value, WORKDAY_COMMUTE_TIME_OPTIONS, labelLower);
        if (resolved) {
            match = options.find(o => optionText(o) === resolved.toLowerCase())
                || options.find(o => optionText(o).includes(resolved.toLowerCase()));
        }
    }
    if (!match) {
        match = options.find(o => {
            const text = optionText(o);
            if (!text) return false;
            if (/\(\+\d\)/.test(text) && isWorkdayStateFieldLabel(labelLower)) return false;
            if (/phone code/i.test(labelLower) && !/united states/i.test(text) && !/\(\+1\)/.test(text)) return false;
            if (/country/i.test(labelLower) && !/phone/i.test(labelLower) && text === 'georgia') return false;
            if (target.includes('united states') && text === 'georgia') return false;
            if (/^bachelor/i.test(target) && /agriculture|accountancy|computer science|anthropology/i.test(text) && !/degree|bachelor|master|associate|doctor|phd|diploma|certificate/i.test(text)) {
                return false;
            }
            if (target.length <= 3) return text === target || text.startsWith(`${target} `);
            return text.includes(target) || target.includes(text);
        });
    }
    if (!match) {
        match = options.find(o => {
            const text = optionText(o);
            if (/^bachelor/i.test(target)) return /bachelor/i.test(text);
            if (/^master/i.test(target)) return /master/i.test(text);
            if (/^associate/i.test(target)) return /associate/i.test(text);
            return false;
        });
    }
    if (!match && options.length === 1 && optionText(options[0])) match = options[0];
    return match;
}

function findWorkExperienceSection() {
    return queryVisible('[data-automation-id="workExperienceSection"]')
        || findSectionInForm(/^work experience/i)
        || findSectionInForm(/^experience/i)
        || findSectionByExperienceFields();
}

// Fallback: find a section on the page containing Job Title + Company + From fields
function findSectionByExperienceFields() {
    const form = getFormRoot();
    if (!form) return null;
    // Find a container that has "Job Title" and "Company" formField labels
    const containers = [...form.querySelectorAll('[data-automation-id*="formField"]')];
    for (const c of containers) {
        const label = getContainerLabel(c);
        if (!/^job title/i.test(label)) continue;
        // Found a Job Title field - walk up to find the enclosing section
        let node = c.parentElement;
        for (let d = 0; d < 10 && node && node !== form; d++) {
            // Check if this node also contains a Company field
            const hasCompany = node.querySelector('[data-automation-id*="formField"]')
                && [...node.querySelectorAll('[data-automation-id*="formField"]')].some(f => /^company/i.test(getContainerLabel(f)));
            if (hasCompany) return node;
            node = node.parentElement;
        }
    }
    return null;
}

function findSectionByEducationFields() {
    const form = getFormRoot();
    if (!form) return null;

    const isSchoolLabel = (label) => /school|university|institution|college/i.test(label);
    const isDegreeLabel = (label) => /^degree$/i.test(String(label || '').replace(/\*/g, '').trim());

    const schoolFields = [...form.querySelectorAll('[data-automation-id*="formField"]')]
        .filter(c => isSchoolLabel(getContainerLabel(c)));
    const degreeFields = [...form.querySelectorAll('[data-automation-id*="formField"]')]
        .filter(c => isDegreeLabel(getContainerLabel(c)));
    if (schoolFields.length && degreeFields.length) {
        const schoolEl = schoolFields[0];
        const degreeEl = degreeFields[0];
        let node = schoolEl.parentElement;
        while (node && node !== form) {
            if (node.contains(degreeEl)) {
                debugLog(`${WD} education section via inline school+degree fields`);
                return node;
            }
            node = node.parentElement;
        }
        debugLog(`${WD} education section via form root (inline school+degree)`);
        return form;
    }

    for (const c of form.querySelectorAll('[data-automation-id*="formField"]')) {
        const label = getContainerLabel(c).replace(/\*/g, '').trim().toLowerCase();
        if (!isSchoolLabel(label)) continue;
        let node = c.parentElement;
        for (let d = 0; d < 12 && node && node !== form; d++) {
            const fields = [...node.querySelectorAll('[data-automation-id*="formField"]')];
            const hasSchool = fields.some(f => isSchoolLabel(getContainerLabel(f)));
            const hasDegree = fields.some(f => isDegreeLabel(getContainerLabel(f)));
            if (hasSchool && hasDegree) return node;
            node = node.parentElement;
        }
    }
    return null;
}

function findEducationSectionEl() {
    return queryVisible('[data-automation-id="educationSection"]')
        || findSectionInForm(/^education/i)
        || findSectionByEducationFields();
}

function findSectionInForm(pattern) {
    const form = getFormRoot();
    for (const el of form.querySelectorAll('h2,h3,h4,legend,[data-automation-id*="label"], [data-automation-id*="heading"]')) {
        const text = (el.innerText || '').trim();
        if (text.length > 80 || !pattern.test(text)) continue;
        if (el.closest('nav, [role="navigation"], [data-automation-id*="progress"]')) continue;
        const section = el.closest('[data-automation-id*="Section"], section, [role="group"], [data-automation-id*="section"]')
            || el.parentElement?.parentElement;
        if (section && form.contains(section)) return section;
    }
    return null;
}

function findSectionByHeading(pattern) {
    return findSectionInForm(pattern);
}

function getSectionHeadingEl(section) {
    if (!section) return null;
    for (const sel of ['[data-automation-id*="sectionHeading"]', '[data-automation-id*="sectionLabel"]', 'h2', 'h3', 'h4', 'legend']) {
        const el = section.querySelector(sel);
        const text = (el?.innerText || el?.textContent || '').trim();
        if (el && text && text.length <= 80) return el;
    }
    return null;
}

/** Required if the section heading/title is marked with * or "(Required)". */
function isSectionHeadingRequired(section) {
    const headingEl = getSectionHeadingEl(section);
    const raw = (headingEl?.innerText || headingEl?.textContent || '').trim();
    if (raw.includes('*')) return true;
    if (/\(\s*required\s*\)/i.test(raw)) return true;
    if (section.getAttribute('aria-required') === 'true') return true;
    return false;
}

/**
 * Returns true when required education fields (School/Degree) remain visible on the page,
 * e.g. Starfish keeps a mandatory inline form even when the section heading has no asterisk.
 */
function isEducationFieldsStillRequired(section) {
    if (!section) return false;
    let hasRequiredSchool = false;
    let hasRequiredDegree = false;
    for (const c of section.querySelectorAll('[data-automation-id*="formField"]')) {
        if (!isContainerRequired(c)) continue;
        const lbl = getContainerLabel(c).replace(/\*/g, '').trim().toLowerCase();
        if (/school|university|institution|college/.test(lbl)) hasRequiredSchool = true;
        if (/^degree$/.test(lbl)) hasRequiredDegree = true;
    }
    return hasRequiredSchool && hasRequiredDegree;
}

/**
 * Returns true when the repeating section must be filled to progress.
 * Heading asterisk marks the whole section required. When heading has no asterisk and there
 * are no committed entries, optional sections (Labcorp) can be dismissed; mandatory inline
 * forms (Starfish) keep required School/Degree visible and must be filled.
 */
function isSectionRequired(section) {
    if (!section) return false;
    if (isSectionHeadingRequired(section)) return true;

    if (countWorkdaySectionEntries(section) === 0) {
        return isEducationFieldsStillRequired(section);
    }

    // Resume-imported or committed entries: finish only if required fields are still empty
    for (const c of section.querySelectorAll('[data-automation-id*="formField"]')) {
        if (!isContainerRequired(c)) continue;
        const preview = (c.innerText || '').replace(/\s+/g, ' ');
        if (/select one|0 items selected/i.test(preview)) return true;
        if (/error:.*required/i.test(preview)) return true;
    }
    return false;
}

async function shouldSkipOptionalEducationSection(section) {
    if (!section || isSectionHeadingRequired(section) || countWorkdaySectionEntries(section) > 0) {
        return false;
    }
    await dismissOptionalRepeatingSection(section, 'education');
    await wait(500);
    if (isEducationFieldsStillRequired(section)) {
        debugLog(`${WD} education mandatory — required School/Degree persist after dismiss`);
        return false;
    }
    return true;
}

async function dismissOptionalRepeatingSection(section, kind = 'education') {
    if (!section) return;
    debugLog(`${WD} optional ${kind} section — closing open inline forms`);
    await cancelEmptyOpenSectionForms(section, kind);
    await cancelWorkdayEntryModal();
    const preOpened = findEmptyInlineFormRoot(section);
    if (preOpened) {
        const cancelBtn = [...section.querySelectorAll('button')].find(b =>
            /^cancel$/i.test((b.innerText || '').trim()) && isVisibleElement(b));
        if (cancelBtn) {
            await workdayClick(cancelBtn);
        } else {
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        }
        await wait(1200);
    }
}

function logUnfilledDropdowns(root) {
    for (const container of (root || getFormRoot()).querySelectorAll('[data-automation-id*="formField"]')) {
        const label = getContainerLabel(container);
        const preview = (container.innerText || '').replace(/\s+/g, ' ').trim();
        if (/select one|0 items selected/i.test(preview)) {
            debugLog(`${WD} unfilled dropdown`, label, preview.slice(0, 80));
        }
    }
}

async function fillSelectOneFields(section, entry, { education = false, skipDegree = false, skipFieldOfStudy = false } = {}) {
    const dates = education ? getEducationDateFallbacks(entry) : parseEntryDates(entry);
    for (const container of section.querySelectorAll('[data-automation-id*="formField"]')) {
        const preview = (container.innerText || '');
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        if (/type to add skills|skills/i.test(labelLower)) continue;
        let control = getContainerControl(container);
        if (/^degree$/i.test(label.replace(/\*/g, '').trim()) && /select one/i.test(preview)) {
            control = control || getWorkdayDropdownTrigger(container) || container;
        }
        if (!control) continue;

        if (/^field of study/i.test(label.replace(/\*/g, '').trim())) {
            const studyEntry = entry || window.__wdApplyData?.profile?.educations?.[0] || {};
            if (skipFieldOfStudy || shouldSkipFieldOfStudyRefill(container, studyEntry)) continue;
        } else if (!/select one|0 items selected/i.test(preview)) {
            continue;
        }

        await closeWorkdayPopups();
        await wait(300);

        if (/^degree$/i.test(label.replace(/\*/g, '').trim())) {
            if (skipDegree) continue;
            if (!isContainerRequired(container) && !String(entry?.degree || '').trim()) continue;
            if (await fillWorkdayDegreeDropdown(control, entry)) continue;
        } else if (/^field of study/i.test(label.replace(/\*/g, '').trim())) {
            const studyEntry = entry || window.__wdApplyData?.profile?.educations?.[0] || {};
            if (!isContainerRequired(container) && !String(studyEntry?.fieldOfStudy || '').trim()) continue;
            if (await fillWorkdayFieldOfStudyDropdown(control, studyEntry)) {
                markFieldOfStudyCommitted(container);
                continue;
            }
        } else {
            let values = [];
            if (/from month|start month/i.test(labelLower) && dates.start) values = [dates.start.month];
            else if (/from year|start year/i.test(labelLower) && dates.start) values = [dates.start.year];
            else if (/to month|end month/i.test(labelLower) && dates.end) values = [dates.end.month];
            else if (/to year|end year|expected/i.test(labelLower) && dates.end) values = [dates.end.year];
            if (values.length) await fillWorkdayDropdown(control, values);
        }
        await wait(400);
    }
}

function getVisibleModal() {
    return queryVisible('[role="dialog"], [data-automation-id="wd-Modal"], [data-automation-id*="modalContainer"], [data-automation-id*="popupContainer"], [data-automation-id*="panelSlideOut"], [data-automation-id*="Popup"], [data-automation-id*="editPanel"]')
        || [...document.querySelectorAll('[role="dialog"], [data-automation-id*="Popup"], [data-automation-id*="SlideOut"]')]
            .find(el => isVisibleElement(el) && el.querySelectorAll('[data-automation-id*="formField"]').length >= 2);
}

async function commitWorkdayInlineSectionEntry(section, entryRoot, kind = 'education', entry = null) {
    if (!section) return false;
    const before = countWorkdaySectionEntries(section);
    const root = entryRoot || getLatestEntryRoot(section) || getFirstEntryRoot(section);
    const eduEntry = entry || window.__wdApplyData?.profile?.educations?.[0];

    if (root && kind === 'education') {
        markFieldOfStudyCommitted(root);
        const studyField = getFieldOfStudyContainer(root);
        if (studyField && isFieldOfStudyFilled(studyField, eduEntry)) {
            await dismissWorkdayFieldDropdown(studyField, 'field of study');
            await wait(400);
        }
    }

    if (root && await saveWorkdaySectionEntry(section, root)) {
        if (countWorkdaySectionEntries(section) > before) {
            await cancelEmptyOpenSectionForms(section, kind);
            return true;
        }
    }
    if (root) {
        const inputsToBlur = [...root.querySelectorAll('input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]),textarea')]
            .filter(i => (i.value || '').trim());
        for (const inp of inputsToBlur) {
            inp.dispatchEvent(new Event('change', { bubbles: true }));
            inp.dispatchEvent(new Event('blur', { bubbles: true }));
            inp.dispatchEvent(new KeyboardEvent('keyup', { key: 'Tab', bubbles: true }));
        }
        if (inputsToBlur.length) {
            const lastInput = inputsToBlur[inputsToBlur.length - 1];
            lastInput.focus();
            lastInput.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', code: 'Tab', bubbles: false, cancelable: true }));
            lastInput.dispatchEvent(new KeyboardEvent('keyup', { key: 'Tab', code: 'Tab', bubbles: false }));
        }
        await wait(800);
        for (let w = 0; w < 6; w++) {
            if (countWorkdaySectionEntries(section) > before) {
                await cancelEmptyOpenSectionForms(section, kind);
                return true;
            }
            await wait(500);
        }
    }

    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(1000);
        if (countWorkdaySectionEntries(section) > before) {
            await cancelEmptyOpenSectionForms(section, kind);
            return true;
        }
    }

    if (root && kind === 'education' && isEducationEntryReady(section, eduEntry, root)) {
        debugLog(`${WD} commit ${kind} inline entry accepted as ready without delete button`);
        await cancelEmptyOpenSectionForms(section, kind);
        return true;
    }
    if (root && kind === 'experience' && isExperienceEntryReady(section, entry, root)) {
        const slotNum = getWorkdayExperienceSlotNumberForRoot(section, root);
        const headingLayout = getWorkdayExperienceSlots(section).length > 0;
        if (!headingLayout || (slotNum && (!entry || isWorkdayExperienceSlotCommitted(section, slotNum, entry)))) {
            debugLog(`${WD} commit ${kind} inline entry accepted as ready without delete button`);
            await cancelEmptyOpenSectionForms(section, kind);
            return true;
        }
    }

    const addBtn = findAddButton(section);
    if (addBtn && isVisibleElement(addBtn) && !addBtn.disabled && kind !== 'experience') {
        debugLog(`${WD} commit ${kind} inline entry via Add`);
        await workdayClick(addBtn);
        await wdWait(1200, `commit ${kind} inline via Add`);
        for (let w = 0; w < 6; w++) {
            if (countWorkdaySectionEntries(section) > before) {
                await cancelEmptyOpenSectionForms(section, kind);
                return true;
            }
            await wait(500);
        }
        await cancelEmptyOpenSectionForms(section, kind);
    }

    return countWorkdaySectionEntries(section) > before;
}

async function saveWorkdaySectionEntry(section, entryRoot) {
    const modal = getVisibleModal();
    if (modal && isWorkdayEntryEditModal(modal)) {
        if (await saveWorkdayEntryModal()) return true;
    }

    const entriesBefore = section ? countWorkdaySectionEntries(section) : 0;

    function findSaveBtn(scope) {
        if (!scope) return null;
        return queryVisible('[data-automation-id="saveButton"], [data-automation-id*="SaveButton"], [data-automation-id="bottom-navigation-save-button"], [data-automation-id*="inlineEditSave"], [data-automation-id*="formFooterSave"], [data-automation-id*="formFooter"] button', scope)
            || [...scope.querySelectorAll('button,[role="button"],[data-automation-id*="CommandButton"],[data-automation-id*="commandButton"]')].find(b => {
                const t = (b.innerText || b.getAttribute('aria-label') || b.getAttribute('title') || '').trim();
                if (!isVisibleElement(b) || b.disabled || b.getAttribute('aria-disabled') === 'true') return false;
                return /^(save|done|ok|save changes|confirm|apply)$/i.test(t)
                    || /\bsave\b|\bdone\b|\bconfirm\b/i.test(t);
            })
            || [...(entryRoot?.parentElement?.querySelectorAll('button,[role="button"]') || [])].find(b => {
                const t = (b.innerText || b.getAttribute('aria-label') || '').trim();
                return isVisibleElement(b) && !b.disabled && /^(save|done)$/i.test(t);
            });
    }

    const scopes = [entryRoot, modal, section].filter(Boolean);
    for (const scope of scopes) {
        const saveBtn = findSaveBtn(scope);
        if (saveBtn) {
            debugLog(`${WD} saving section entry`, (saveBtn.innerText || saveBtn.getAttribute('aria-label') || '').trim());
            await workdayClick(saveBtn);
            await wait(2500);
            if (!section || countWorkdaySectionEntries(section) > entriesBefore) return true;
        }
    }

    // Blur all filled inputs to trigger Workday's autosave (for implementations without explicit Save button)
    const inputsToBlur = [...(entryRoot || section || document).querySelectorAll('textarea, input:not([type="checkbox"]):not([type="hidden"]):not([type="radio"])')].filter(i => (i.value || '').trim());
    for (const inp of inputsToBlur) {
        inp.dispatchEvent(new Event('blur', { bubbles: true }));
        inp.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true }));
    }
    if (inputsToBlur.length) await wait(1200);

    // Try icon-only save buttons (some inline section forms hide label text)
    for (const scope of scopes) {
        const iconSave = [...(scope?.querySelectorAll('button,[role="button"]') || [])].find(b => {
            if (!isVisibleElement(b) || b.disabled || b.getAttribute('aria-disabled') === 'true') return false;
            const label = (b.getAttribute('aria-label') || b.getAttribute('title') || b.innerText || '').trim();
            return /^(save|done|confirm|apply|check)$/i.test(label) || /\bsave changes\b/i.test(label);
        });
        if (iconSave) {
            debugLog(`${WD} saving section entry via icon`, iconSave.getAttribute('aria-label') || iconSave.getAttribute('title') || '');
            await workdayClick(iconSave);
            await wait(2500);
            if (!section || countWorkdaySectionEntries(section) > entriesBefore) return true;
        }
    }

    // Try clicking outside the form (e.g. page title) to trigger Workday blur-save
    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"]');
    if (pageTitle) {
        await workdayClick(pageTitle);
        await wait(800);
    }
    if (section && countWorkdaySectionEntries(section) > entriesBefore) {
        debugLog(`${WD} section entry saved via blur`);
        return true;
    }

    // Some tenants commit inline education/experience via Enter on the last filled field
    const lastInput = inputsToBlur[inputsToBlur.length - 1];
    if (lastInput) {
        lastInput.focus();
        await dispatchWorkdayEnterKey(lastInput);
        await wait(1500);
        if (section && countWorkdaySectionEntries(section) > entriesBefore) {
            debugLog(`${WD} section entry saved via Enter on last input`);
            return true;
        }
    }

    debugLog(`${WD} section entry save button not found`, 'modal=', Boolean(modal), 'fields=', entryRoot?.querySelectorAll?.('[data-automation-id*="formField"]')?.length);
    return false;
}

function getEntryRootByIndex(section, index) {
    const deleteBtns = getWorkdaySectionDeleteButtons(section);
    if (!deleteBtns[index]) return getFirstEntryRoot(section);
    return getEntryRootFromDeleteBtn(deleteBtns[index], section);
}

function isWorkdayEntryEmpty(root, kind = 'experience') {
    if (!root) return true;
    const text = (root.innerText || '').replace(/\s+/g, ' ');
    if (/error:.*required and must have a value/i.test(text)) return true;
    if (kind === 'experience') {
        const hasTitle = /job title|title/i.test(text) && !/error:\s*the field job title is required/i.test(text);
        const titleInput = root.querySelector('input:not([type="checkbox"]):not([type="hidden"])');
        const titleVal = titleInput?.value || '';
        if (!titleVal && /error:\s*the field job title/i.test(text)) return true;
        if (/select one/i.test(text) && /from|to/i.test(text)) return true;
    }
    if (kind === 'certification') {
        if (/error:\s*the field certification is required/i.test(text)) return true;
        // Certification issuer dropdown shows "0 items selected" when unfilled (fixed-list dropdown)
        if (/(select one|0 items selected)/i.test(text) && /certification/i.test(text)) return true;
        // The checklist-style multiselect widget for this field can briefly render neither
        // "0 items selected" nor an actual value — just its own label, or a transient "Minimized" state
        // (seen on multicare.wd1) — while nothing is really selected. Defaulting to "not empty" below in
        // that case made a failed fill silently look successful, so the "still empty after retry" giveup
        // (mark provider fixed, remove the unfillable entry) never triggered and the loop kept re-picking
        // an arbitrary/wrong option from the (tenant-specific closed) provider list forever. Check the
        // Certification field's own preview text (label stripped) directly instead of relying only on
        // known "empty" phrases.
        const certField = [...root.querySelectorAll('[data-automation-id*="formField"]')]
            .find(c => /^certification$/i.test(getContainerLabel(c).replace(/\*/g, '').trim()));
        if (certField) {
            const certLabel = getContainerLabel(certField).replace(/\s+/g, ' ').trim();
            let certValueText = (certField.innerText || '').replace(/\s+/g, ' ').trim();
            if (certLabel && certValueText.toLowerCase().startsWith(certLabel.toLowerCase())) {
                certValueText = certValueText.slice(certLabel.length).trim();
            }
            if (!certValueText || /^minimized$/i.test(certValueText)) return true;
        }
        const inputs = [...root.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"]), textarea')];
        const hasText = inputs.some(i => (i.value || '').trim().length > 0);
        if (!hasText && /select one|error:/i.test(text)) return true;
    }
    return false;
}

async function removeEmptyWorkdaySectionEntries(section, kind = 'experience') {
    if (!section) return;
    for (let guard = 0; guard < 5; guard++) {
        const deleteBtns = getWorkdaySectionDeleteButtons(section);
        if (deleteBtns.length <= 1) break;
        const roots = deleteBtns.map(btn => getEntryRootFromDeleteBtn(btn, section));
        const emptyIdx = roots.findIndex(r => isWorkdayEntryEmpty(r, kind));
        if (emptyIdx < 0) break;
        debugLog(`${WD} removing empty ${kind} entry`, emptyIdx + 1);
        await workdayClick(deleteBtns[emptyIdx]);
        await wait(800);
        await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
        await wait(1200);
    }
}

async function fixWorkdayExperienceStepGaps(profile) {
    await pause();
    debugLog(`${WD} fix experience step gaps start`);
    dumpWorkdayErrorsFoundBlock();
    await uploadResume(window.__wdApplyData || { profile });
    await waitForResumeProcessed(window.__wdCachedResume?.originalFilename);

    // Close any open inline forms/modals before re-processing
    await ensureWorkdaySectionFormsClosed();

    const section = findWorkExperienceSection();
    if (section) {
        await cancelEmptyOpenSectionForms(section, 'experience');
        await removeEmptyWorkdaySectionEntries(section, 'experience');
        await fillWorkdayExperienceEntries(section, profile?.experiences || []);
    }

    const eduSection = findEducationSectionEl();
    const edu = (profile?.educations || [])[0];

    // Helper: delete all education entries and mark as unfillable
    const removeAllEduEntries = async (reason) => {
        debugLog(`${WD} education unfillable (${reason}), removing all entries`);
        window.__wdEducationSchoolUnfillable = true;
        await ensureWorkdaySectionFormsClosed();
        for (let g = 0; g < 5; g++) {
            const delBtns = getWorkdaySectionDeleteButtons(eduSection);
            if (!delBtns.length) break;
            await workdayClick(delBtns[0]);
            await wait(800);
            await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
            await wait(1200);
        }
    };

    if (eduSection) {
        let skipEducation = false;
        if (!isSectionRequired(eduSection) && countWorkdaySectionEntries(eduSection) === 0) {
            skipEducation = await shouldSkipOptionalEducationSection(eduSection);
            if (skipEducation) {
                debugLog(`${WD} education section not required and empty — skipping`);
            }
        }
        if (!skipEducation) {
        if (window.__wdEducationSchoolUnfillable) {
            const leftover = getWorkdaySectionDeleteButtons(eduSection);
            if (leftover.length) await removeAllEduEntries('retry-unfillable');
        } else if (edu) {
            const gapEduRoot = getFirstEntryRoot(eduSection) || findEmptyInlineFormRoot(eduSection);
            if (isEducationEntryReady(eduSection, edu, gapEduRoot)) {
                debugLog(`${WD} education gap fix skip — already complete`);
                if (gapEduRoot && countWorkdaySectionEntries(eduSection) === 0) {
                    await commitWorkdayInlineSectionEntry(eduSection, gapEduRoot, 'education', edu);
                }
            } else if (countWorkdaySectionEntries(eduSection) === 0) {
                const preOpenedEdu = findEmptyInlineFormRoot(eduSection);
                if (!preOpenedEdu || preOpenedEdu === eduSection) {
                    await addWorkdaySectionEntry(eduSection, edu, { education: true });
                } else {
                    debugLog(`${WD} education: using pre-opened empty form`);
                }
                const eduRoot = getFirstEntryRoot(eduSection) || preOpenedEdu;
                await fillWorkdayInlineEntry(edu, eduSection, { education: true, entryRoot: eduRoot });
                markFieldOfStudyCommitted(eduRoot);
                for (const container of (getFirstEntryRoot(eduSection) || eduRoot).querySelectorAll('[data-automation-id*="formField"]')) {
                    const label = getContainerLabel(container).toLowerCase();
                    if (!/field of study|major|^degree$/i.test(label)) continue;
                    const control = getContainerControl(container);
                    if (!control) continue;
                    if (/^degree$/i.test(label.replace(/\*/g, '').trim())) {
                        if (!isDegreeFilled(container) && (isContainerRequired(container) || edu.degree)) {
                            await fillWorkdayDegreeDropdown(control, edu);
                        }
                        continue;
                    }
                    if (shouldSkipFieldOfStudyRefill(container, edu)) continue;
                    if (isContainerRequired(container) || edu.fieldOfStudy) {
                        await fillWorkdayFieldOfStudyDropdown(control, edu);
                        markFieldOfStudyCommitted(container);
                    }
                }

                const commitRoot = getFirstEntryRoot(eduSection) || findEmptyInlineFormRoot(eduSection);
                if (commitRoot && countWorkdaySectionEntries(eduSection) === 0) {
                    await commitWorkdayInlineSectionEntry(eduSection, commitRoot, 'education', edu);
                }
            }

            // If school required field is still empty after fill, remove education entry to unblock form
            if (window.__wdEducationSchoolUnfillable) {
                await removeAllEduEntries('school-typeahead-failed');
            } else {
                const finalRoot = getFirstEntryRoot(eduSection);
                if (finalRoot) {
                    const schoolContainer = [...finalRoot.querySelectorAll('[data-automation-id*="formField"]')]
                        .find(c => /school|university|institution|college/i.test(getContainerLabel(c)));
                    if (schoolContainer && isContainerRequired(schoolContainer)) {
                        if (!isSchoolFieldFilled(schoolContainer)) {
                            await removeAllEduEntries('school-field-empty');
                        }
                    }
                }
            }
        }
        }
    }

    await fillCertificationsSection(profile);
    await fillExperiencePageExtras(profile);
    if (hasRequiredEmptyLanguageFields()) {
        await fillInlineLanguageFields(profile);
    }
    dumpWorkdayErrorsFoundBlock();
    debugLog(`${WD} fix experience step gaps end`);
}

function findAddButton(section) {
    const scope = section || document;
    return [...scope.querySelectorAll('button, [role="button"]')].find(b => {
        const text = (b.innerText || '').trim();
        return /^add$/i.test(text) || /^add\s+/i.test(text);
    }) || scope.querySelector('[data-automation-id="add-button"], [data-automation-id*="addButton"]');
}

function formatWorkdayMonthYear(dateStr) {
    if (!dateStr) return [];
    if (typeof dateStr === 'number') {
        const ms = toEpochMillis(dateStr);
        const dt = new Date(ms);
        if (!Number.isNaN(dt.getTime())) {
            const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
            const y = String(dt.getUTCFullYear());
            const m = months[dt.getUTCMonth()];
            return [`${m} ${y}`, y, `${y}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}`];
        }
    }
    const raw = String(dateStr);
    const m = raw.match(/(\d{4})-(\d{2})/);
    if (m) {
        const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
        return [`${months[Number(m[2]) - 1]} ${m[1]}`, `${m[1]}`, raw];
    }
    return [raw];
}

async function clickModalActionButton(textPattern) {
    const modal = getVisibleModal();
    const scope = modal || document;
    const btn = [...scope.querySelectorAll('button, [role="button"]')].find(b =>
        textPattern.test((b.innerText || '').trim()) && isVisibleElement(b));
    if (btn) {
        await workdayClick(btn);
        return true;
    }
    return false;
}

async function cancelWorkdayEntryModal() {
    const modal = getVisibleModal();
    if (!modal || !isWorkdayEntryEditModal(modal)) return false;
    const cancelled = await clickModalActionButton(/^cancel$|^close$|^discard$/i);
    if (cancelled) {
        debugLog(`${WD} cancelled stale entry modal`);
        await wait(800);
        return true;
    }
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await wait(500);
    return true;
}

async function dismissOpenModals() {
    const modal = getVisibleModal();
    if (!modal) return;
    if (isWorkdayEntryEditModal(modal)) {
        await saveWorkdayEntryModal();
        return;
    }
    await clickModalActionButton(/^cancel$/i);
    await wait(500);
    if (getVisibleModal()) {
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await wait(500);
    }
}

function isInlineTextFieldEmpty(container, value = '') {
    const text = (container.innerText || '').replace(/\s+/g, ' ');
    if (/error:.*required and must have a value/i.test(text)) return true;
    if (value) {
        const pattern = value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').slice(0, Math.min(24, value.length));
        if (pattern.length >= 3 && new RegExp(pattern, 'i').test(text)) return false;
    }
    const inputs = [...container.querySelectorAll('input:not([type="checkbox"]):not([type="hidden"]), textarea')];
    if (inputs.length && inputs.every(i => !(i.value || '').trim())) return true;
    return false;
}

function inlineFieldNeedsRefill(container, control, value) {
    const preview = (container?.innerText || '').trim();
    const currentVal = (control?.value || '').trim();
    if (/error:.*required/i.test(preview)) return true;
    if (!value) return false;
    if (!currentVal) return true;
    if (isInlineTextFieldEmpty(container, value)) return true;
    return !textMatchesCandidate(currentVal, value);
}

async function fillWorkdayInlineEntry(entry, section, { education = false, useLatestEntry = false, certification = false, entryRoot = null, skipCertProvider = false, experienceSlot = null } = {}) {
    await pause();
    if (!isWorkdayEntryEditModal()) await closeWorkdayPopups();
    let root = resolveWorkdayEntryRoot(section, { useLatestEntry, entryRoot });
    if (!education && !certification && section && experienceSlot) {
        const slotRoot = resolveWorkdayExperienceRootForSlot(section, experienceSlot);
        if (slotRoot) {
            root = slotRoot;
        }
    } else if (!education && !certification && section) {
        const hasTitleInRoot = root && [...root.querySelectorAll('[data-automation-id*="formField"]')].some(c =>
            /job title|^title/.test(getContainerLabel(c).toLowerCase()));
        if (!hasTitleInRoot && !entryRoot) {
            const better = findOpenInlineExperienceRoot(section);
            if (better) {
                debugLog(`${WD} experience root expanded`, root?.querySelectorAll?.('[data-automation-id*="formField"]')?.length, '->', better.querySelectorAll('[data-automation-id*="formField"]').length);
                root = better;
            } else if (section.querySelector('[data-automation-id*="formField"]')) {
                root = section;
            }
        }
    }
    await wait(isWorkdayEntryEditModal() ? 1500 : 1000);
    const fieldCount = root.querySelectorAll('[data-automation-id*="formField"]').length;
    debugLog(`${WD} entry form fields`, fieldCount, certification ? 'certification' : (education ? 'education' : 'experience'));

    const isEducationSection = education || /education/i.test(section?.getAttribute?.('data-automation-id') || '')
        || /education/i.test(section?.querySelector('h2,h3,h4,legend')?.innerText || '');
    const isCertSection = certification || /certification/i.test(section?.getAttribute?.('data-automation-id') || '')
        || /certification/i.test(section?.querySelector('h2,h3,h4,legend')?.innerText || '');

    if (isEducationSection && section && !isSectionRequired(section) && !isEducationFieldsStillRequired(section)) {
        debugLog(`${WD} education inline skip — section not required`);
        return true;
    }

    if (!isEducationSection && !isCertSection) {
        await syncExperienceCurrentlyWorking(root, entry);
    }

    const containers = [...root.querySelectorAll('[data-automation-id*="formField"]')];
    const ordered = education
        ? [
            ...containers.filter(c => /school|university|institution|college/i.test(getContainerLabel(c).toLowerCase())),
            ...containers.filter(c => isDegreeFieldLabel(getContainerLabel(c))),
            ...containers.filter(c => /field of study|major|area of study/i.test(getContainerLabel(c).toLowerCase())),
            ...containers.filter(c => {
                const l = getContainerLabel(c).replace(/\*/g, '').trim().toLowerCase();
                return !isDegreeFieldLabel(l) && !/school|university|institution|college/i.test(l)
                    && !/field of study|major|area of study/i.test(l);
            }),
        ]
        : containers;

    for (const container of ordered) {
        await pause();
        const label = getContainerLabel(container);
        if (!label) continue;
        let control = getContainerControl(container);
        const labelLower = label.toLowerCase();
        const preview = (container.innerText || '').trim();

        if (isDegreeFieldLabel(label)) {
            if (!isDegreeFilled(container)) {
                await closeWorkdayPopups('before-degree');
                await wait(200);
                const degreeEl = control || getWorkdayDropdownTrigger(container) || container;
                await fillWorkdayDegreeDropdown(degreeEl, entry);
            } else {
                debugLog(`${WD} degree skip`, (getWorkdayFieldSelectedText(container) || preview).slice(0, 50));
            }
            await wait(400);
            continue;
        }

        if (/school|university|institution|college/i.test(labelLower) && entry?.school && !isSchoolFieldFilled(container)) {
            const schoolControl = control || getWorkdayDropdownTrigger(container) || container;
            debugLog(`${WD} filling school typeahead`, entry.school.slice(0, 50));
            const schoolFilled = await fillWorkdaySchoolViaSearch(schoolControl, entry.school);
            await closeWorkdayPopups('school-done');
            await wait(200);
            if (!schoolFilled && !isSchoolFieldFilled(container)) {
                window.__wdEducationSchoolUnfillable = true;
                debugLog(`${WD} school typeahead unfillable after all variants, marking for skip`);
            }
            await wait(400);
            continue;
        }

        if (!control) continue;

        if (/field of study|major|area of study/i.test(labelLower)) {
            if (!shouldSkipFieldOfStudyRefill(container, entry)) {
                await fillWorkdayFieldOfStudyDropdown(control, entry);
                markFieldOfStudyCommitted(container);
                await wait(400);
            }
            continue;
        }

        // getContainerLabel() falls back to the first <p>/<span> inside the field container when no
        // dedicated <label>/<legend>/aria-label exists — on tenants whose "Certification" multi-select
        // widget doesn't expose a proper label element (multicare.wd1 and similar), that fallback grabs
        // a wrapper span containing BOTH the field name and its live value preview, e.g.
        // "Certification* 0 items selected", so the old exact `^certification$` match silently missed
        // it. Strip the same "N items selected" / "select one" value-preview suffixes the rest of this
        // file already treats as "field is empty" before matching the field name.
        const labelCore = label.replace(/\*/g, '')
            .replace(/\b\d+\s+items?\s+selected\b/i, '')
            .replace(/\bselect one\b/i, '')
            .trim();
        if ((/^certification$/i.test(labelCore)
            || /certification\/credential|credential type|^credential$/i.test(labelLower))
            && isCertSection && entry?.name) {
            if (!skipCertProvider && /select one|0 items selected|error:/i.test(preview)) {
                // Extract issuer org from cert name (after "—", "–", "from", or at end)
                const issuerMatch = entry.name.match(/(?:—|–)\s*([A-Za-z][^—–]+)$/)
                    || entry.name.match(/\bfrom\s+(.+)$/i);
                const issuer = issuerMatch ? issuerMatch[1].trim() : '';
                // Use only issuer or first meaningful word - limit to 2 candidates
                const certCandidates = [issuer || entry.name.split(/[\s\-–—]+/).find(w => w.length > 3) || entry.name]
                    .filter(Boolean).slice(0, 2);
                debugLog(`${WD} filling certification dropdown`, entry.name, 'issuer=', issuer);
                // Try single-select first (opens 1-2 times), then typeahead once
                // The "Certification" control on some tenants (e.g. multicare.wd1) is a checklist-style
                // multiselectInputContainer widget ("N items selected"), not a true single-select
                // combobox/promptSelectionLabel dropdown. fillWorkdaySingleSelectDropdown() is built for
                // the latter — on the checklist widget its own isWorkdaySingleSelectFilled() pre-check can
                // report a false "already filled" (the widget's popup is portalled outside the formField
                // container, so the container's own innerText/selection-label reads misleadingly), making
                // this return `true` without ever actually opening the popup or clicking a matching option.
                // Because of `||` short-circuiting, the correct multiselect-typeahead path below never
                // even runs, leaving the field permanently empty ("Workday step stuck: experience"). Go
                // straight to the typeahead path for this widget type; only try the single-select path for
                // tenants where Certification really is a plain combobox/dropdown.
                const isCertMultiselect = Boolean(control?.closest?.('[data-automation-id="multiselectInputContainer"]'))
                    || control?.getAttribute?.('data-automation-id') === 'multiselectInputContainer';
                const typeaheadOpts = {
                    logTag: 'certification typeahead',
                    // Require a positive "N item(s) selected" (N>=1) confirmation rather than just the
                    // ABSENCE of "0 items selected"/"select one" — this checklist widget can render a
                    // transient state (e.g. just its bare label, or "Minimized") that contains neither
                    // phrase while nothing is actually selected, which made the Enter-key fallback's
                    // "isFilledFn" false-positive whenever no real dropdown option matched the search term
                    // (observed on multicare.wd1 with a closed/fixed healthcare-provider list that has no
                    // match for a generic tech certification name), silently leaving the field empty while
                    // every downstream check believed it was filled.
                    isFilledFn: (r) => /\b[1-9]\d*\s+items?\s+selected\b/i.test(r.innerText || ''),
                    maxItems: 1,
                };
                const filled = isCertMultiselect
                    ? (await fillWorkdayTypeaheadMultiField(control, certCandidates, typeaheadOpts)
                        || await fillWorkdayTypeaheadMultiField(control, [entry.name], typeaheadOpts))
                    : (await fillWorkdaySingleSelectDropdown(control, certCandidates, 'certification')
                        || await fillWorkdayTypeaheadMultiField(control, [issuer || entry.name].filter(Boolean), typeaheadOpts));
                debugLog(`${WD} certification fill result`, filled, (container.innerText || '').slice(0, 80));
            } else if (skipCertProvider) {
                debugLog(`${WD} skipping cert provider dropdown (fixed-list)`);
            }
            await wait(400);
            continue;
        }

        if (/select one|0 items selected/i.test(preview)) {
            if (/field of study|major/i.test(labelLower) && entry.fieldOfStudy) {
                if (!shouldSkipFieldOfStudyRefill(container, entry)) {
                    await fillWorkdayFieldOfStudyDropdown(control, entry);
                    markFieldOfStudyCommitted(container);
                }
            } else if (/country/i.test(labelLower)) {
                await fillWorkdayDropdown(control, ['United States of America', 'United States']);
            } else if (/school|university|institution|college/i.test(labelLower) && entry.school) {
                debugLog(`${WD} filling school typeahead`, entry.school.slice(0, 50));
                const fieldRootForSchool = control.closest('[data-automation-id*="formField"]') || control.parentElement;
                const schoolFilled = await fillWorkdaySchoolViaSearch(control, entry.school);
                await closeWorkdayPopups('school-done');
                await wait(200);
                if (!schoolFilled && !isSchoolFieldFilled(fieldRootForSchool)) {
                    window.__wdEducationSchoolUnfillable = true;
                    debugLog(`${WD} school typeahead unfillable after all variants, marking for skip`);
                }
            }
            await wait(400);
            continue;
        }

        let value = null;
        if (/certification name|certificate name|^name$/i.test(labelLower) && isCertSection) value = entry.name;
        else if (/certificate number|certification number|credential number/i.test(labelLower)) value = entry.certificateNumber;
        else if (/job title|^title/.test(labelLower)) value = entry.title;
        else if (/company|employer|organization/.test(labelLower)) value = entry.companyName || entry.company;
        else if (/school|university|institution|college/.test(labelLower)) value = entry.school;
        else if (/degree/.test(labelLower) && !/select one/i.test(preview)) value = entry.degree;
        else if (/field of study|major|area of study/.test(labelLower)) {
            if (shouldSkipFieldOfStudyRefill(container, entry)) continue;
            if (/0 items selected|select one/i.test(preview)) {
                await fillWorkdayFieldOfStudyDropdown(control, entry);
                markFieldOfStudyCommitted(container);
                await wait(300);
            }
            continue;
        } else if (/location|city/.test(labelLower)) {
            // Older/non-current experience entries frequently have an empty location in the
            // profile data (only the most recent job reliably has one) — when the tenant marks
            // this field required, an empty value here left it permanently blank, causing
            // "Workday step stuck: experience" on every retry with no way to recover (observed
            // on ffin.wd1, not tenant-specific: any profile with a blank-location past job hits
            // this once required-Location tenants are encountered). Fall back to the candidate's
            // own residency city, matching the existing fallback chain used for the analogous
            // "previous work location" question field.
            const residency = window.__wdApplyData?.profile?.residency
                || window.__wdApplyData?.profile?.general?.residency || {};
            value = entry.location || entry.city || residency.city || 'Remote';
        }
        else if (/role description|job description|description of role|responsibilities|duties|summary/i.test(labelLower)
            && !/field of study|degree|certification/i.test(labelLower)) {
            value = getExperienceDescription(entry);
        }

        if (value && inlineFieldNeedsRefill(container, control, value)) {
            if (control.tagName === 'TEXTAREA' || control.type === 'textarea') {
                // Use workdayTypeElement for textarea to ensure React state is updated
                debugLog(`${WD} inline fill textarea`, label.slice(0, 40), String(value).slice(0, 40));
                await workdayTypeElement(control, String(value).slice(0, 4000));
                await wait(300);
                continue;
            }
            if (control.getAttribute('aria-haspopup') === 'listbox' || control.getAttribute('role') === 'combobox' || control.tagName === 'BUTTON') {
                if (/location|city/i.test(labelLower) && value) {
                    const locOk = await fillWorkdayTypeaheadMultiField(control, [value, entry.city, 'Remote'].filter(Boolean), {
                        logTag: 'experience-location',
                        fieldLabel: label,
                        isFilledFn: (r) => {
                            const inp = r?.querySelector?.('input[role="combobox"], input[type="text"]') || r;
                            return Boolean((inp?.value || '').trim());
                        },
                        maxItems: 1,
                    });
                    if (locOk) {
                        await wait(300);
                        continue;
                    }
                }
                await fillWorkdayDropdown(control, value);
            } else {
                debugLog(`${WD} inline fill text`, label.slice(0, 40), String(value).slice(0, 40));
                await workdayTypeElement(control, value);
            }
            await wait(300);
        }

        if (/currently work|work here|present/i.test(labelLower)) {
            const cb = container.querySelector('input[type="checkbox"]');
            if (cb) {
                const shouldCheck = isExperienceCurrent(entry);
                if (shouldCheck !== cb.checked) await workdayClick(cb);
            }
            continue;
        }
    }

    if (isEducationSection) {
        const studyAlreadyFilled = containers.some(c => {
            const l = getContainerLabel(c).toLowerCase();
            return /field of study|major|area of study/.test(l) && shouldSkipFieldOfStudyRefill(c, entry);
        });
        await fillSelectOneFields(root, entry, {
            education: true,
            skipDegree: true,
            skipFieldOfStudy: studyAlreadyFilled,
        });
        await fillWorkdayDateInputs(root, entry, { education: true });
        markFieldOfStudyCommitted(root);
    } else if (isCertSection) {
        await fillWorkdayDateInputs(root, entry, { education: false, certification: true });
    } else {
        await fillSelectOneFields(root, entry, { education: false });
        await fillWorkdayDateInputs(root, entry, { education: false });
    }

    if (!isEducationSection && !isCertSection) {
        await syncExperienceCurrentlyWorking(root, entry);
    }

    // Fill role description textareas that may not expose .value on first pass
    if (!isEducationSection && !isCertSection) {
        const desc = getExperienceDescription(entry);
        if (desc) {
            for (const container of root.querySelectorAll('[data-automation-id*="formField"]')) {
                const labelLower = getContainerLabel(container).toLowerCase();
                if (!/role description|job description|description|responsibilities|duties|summary/i.test(labelLower)) continue;
                if (/field of study|degree|certification|language|skill/i.test(labelLower)) continue;
                const ta = container.querySelector('textarea') || getContainerControl(container);
                if (!ta || (ta.value || '').trim()) continue;
                debugLog(`${WD} filling role description`, labelLower.slice(0, 40));
                await workdayTypeElement(ta, desc.slice(0, 4000));
                await wait(400);
            }
        }
    }

    // For cert sections: check if the required Certification issuer dropdown is still empty.
    // If so, mark the provider as fixed-list unfillable BEFORE saving to prevent committing an empty entry.
    if (isCertSection && !skipCertProvider) {
        const certIssuerContainers = [...root.querySelectorAll('[data-automation-id*="formField"]')]
            .filter(c => /^certification$/i.test(getContainerLabel(c).replace(/\*/g, '').trim()));
        const issuerStillEmpty = certIssuerContainers.some(c => /(select one|0 items selected)/i.test(c.innerText || ''));
        if (issuerStillEmpty) {
            debugLog(`${WD} cert issuer dropdown still empty (fixed-list), marking and skipping save`);
            window.__wdCertProviderFixed = true;
            return false;
        }
    }

    const pageTitle = document.querySelector('[data-automation-id="applyFlowPageTitle"], h2');
    if (pageTitle) await workdayClick(pageTitle);
    await saveWorkdaySectionEntry(section, root);
    await wait(1500);
    logUnfilledDropdowns(root);
    if (isEducationSection) logWorkdayDropdownAudit('education-inline');
    return true;
}

async function addWorkdaySectionEntry(section, entry, { education = false, forceNew = false, certification = false } = {}) {
    await pause();
    if (!section) {
        debugLog(`${WD} section not found for entry`);
        return false;
    }
    if (education && !isSectionRequired(section) && !isEducationFieldsStillRequired(section)) {
        debugLog(`${WD} education add skip — section not required`);
        return true;
    }
    if (forceNew && isWorkExperienceSectionEl(section)
        && countWorkdaySectionEntries(section) >= MAX_WORKDAY_EXPERIENCE_ENTRIES) {
        debugLog(`${WD} experience entry cap reached, skip add click`, countWorkdaySectionEntries(section));
        return fillWorkdayInlineEntry(entry, section, {
            education,
            certification,
            entryRoot: getLatestEntryRoot(section),
        });
    }
    workdayScrollToTarget(section, 120);
    await wait(500);

    // Only save a prior open entry if one actually exists (has a Delete button).
    // Saving when count=0 would commit a Workday-pre-opened empty form as a real entry.
    const priorCount = countWorkdaySectionEntries(section);
    if (priorCount > 0 || getVisibleModal()) {
        await saveWorkdaySectionEntry(section, getLatestEntryRoot(section));
    } else if (education) {
        const openEduRoot = findOpenInlineEducationRoot(section);
        if (openEduRoot) {
            const schoolFilled = [...openEduRoot.querySelectorAll('[data-automation-id*="formField"]')].some(c => {
                const lbl = getContainerLabel(c).toLowerCase();
                if (!/school|university|institution|college/.test(lbl)) return false;
                const ctrl = getContainerControl(c);
                return Boolean((ctrl?.value || '').trim()) && !/0 items selected|select one/i.test(c.innerText || '');
            });
            if (schoolFilled || isEducationEntryReady(section, entry, openEduRoot)) {
                debugLog(`${WD} using open healthcare education inline form`);
                return fillWorkdayInlineEntry(entry, section, { education: true, entryRoot: openEduRoot });
            }
            if (entry && isEducationFieldsStillRequired(section)) {
                debugLog(`${WD} education: fill mandatory pre-opened inline form`);
                return fillWorkdayInlineEntry(entry, section, { education: true, entryRoot: openEduRoot });
            }
        }
        await cancelWorkdayEntryModal();
        const hasOpenInlineForm = section.querySelector(
            'input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]), textarea'
        );
        if (hasOpenInlineForm) {
            debugLog(`${WD} closing pre-opened inline form`);
            const cancelBtn = [...section.querySelectorAll('button')].find(b =>
                /^cancel$/i.test((b.innerText || '').trim()) && isVisibleElement(b));
            if (cancelBtn) {
                await workdayClick(cancelBtn);
            } else {
                document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            }
            await wait(1200);
        }
    } else if (isWorkExperienceSectionEl(section)) {
        const openExpRoot = findOpenInlineExperienceRoot(section);
        if (openExpRoot) {
            debugLog(`${WD} using open experience inline form`);
            return fillWorkdayInlineEntry(entry, section, { education: false, entryRoot: openExpRoot });
        }
        await cancelWorkdayEntryModal();
    } else if (certification) {
        // Resume/LinkedIn-imported certifications can pre-render a single open stub entry that already
        // exposes the "Certification" field but has no Delete button yet — the generic "close any open
        // inline form" branch below would cancel/discard that stub before it's ever filled, so the
        // subsequent "Add" click creates a differently-templated entry instead (e.g. a Specialty/
        // License-only row with no Certification field at all on multicare.wd1), permanently leaving the
        // real Certification field empty and blocking Next ("Workday step stuck: experience"). Reuse the
        // open stub directly whenever one is still empty, same pattern as the education branch above.
        const openCertRoot = findOpenInlineCertificationRoot(section);
        if (openCertRoot && entry && isWorkdayEntryEmpty(openCertRoot, 'certification')) {
            debugLog(`${WD} certification open stub entry found — filling instead of Add`);
            return fillWorkdayInlineEntry(entry, section, { certification, entryRoot: openCertRoot });
        }
        await cancelWorkdayEntryModal();
    } else {
        // Cancel any pre-opened empty form (modal or inline)
        await cancelWorkdayEntryModal();
        // Also close a pre-opened inline form (no modal, no delete buttons, but has visible inputs)
        const hasOpenInlineForm = section.querySelector(
            'input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]), textarea'
        );
        if (hasOpenInlineForm) {
            debugLog(`${WD} closing pre-opened inline form`);
            // Try Cancel button first, then Escape
            const cancelBtn = [...section.querySelectorAll('button')].find(b =>
                /^cancel$/i.test((b.innerText || '').trim()) && isVisibleElement(b));
            if (cancelBtn) {
                await workdayClick(cancelBtn);
            } else {
                document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            }
            await wait(1200);
        }
    }

    const hasEntry = !forceNew && [...section.querySelectorAll('button')].some(b =>
        /^delete$/i.test((b.innerText || '').trim()) && isVisibleElement(b));
    let resolvedRoot = null;
    if (!hasEntry) {
        const addBtn = findAddButton(section);
        if (!addBtn) {
            const openRoot = isWorkExperienceSectionEl(section)
                ? (findOpenInlineExperienceRoot(section) || section)
                : (education ? findOpenInlineEducationRoot(section) : null);
            if (openRoot && entry) {
                debugLog(`${WD} add button missing — filling open inline form`);
                return fillWorkdayInlineEntry(entry, section, { education, certification, entryRoot: openRoot });
            }
            debugLog(`${WD} add button not found in section`, (section.innerText || '').slice(0, 60));
            return false;
        }
        // Mark existing form containers before clicking Add so we can identify newly added ones
        markExistingInlineForms(section);
        debugLog(`${WD} clicking add in section`);
        await workdayClick(addBtn);
        await wait(2500);
    } else if (forceNew) {
        const addBtn = findAddButton(section);
        if (addBtn) {
            // Mark existing form containers before clicking Add
            markExistingInlineForms(section);
            debugLog(`${WD} clicking add for additional entry`);
            await workdayClick(addBtn);
            await wait(2500);
        }
    } else {
        debugLog(`${WD} inline entry exists in section`);
        resolvedRoot = getFirstEntryRoot(section);
        if (education && entry && isEducationEntryReady(section, entry, resolvedRoot)) {
            debugLog(`${WD} education entry already complete, skip refill`);
            markFieldOfStudyCommitted(resolvedRoot);
            return true;
        }
        return fillWorkdayInlineEntry(entry, section, {
            education,
            certification,
            entryRoot: resolvedRoot,
        });
    }
    // Wait for the newly added inline form to appear. We prefer a form root that was NOT marked
    // as pre-existing (added after the Add click). Fallback to empty-input form or latest entry root.
    for (let i = 0; i < 10; i++) {
        await wait(500);
        const newRoot = findNewlyAddedFormRoot(section);
        if (newRoot) {
            resolvedRoot = newRoot;
            debugLog(`${WD} found new inline form root`, i + 1, 'fields=', newRoot.querySelectorAll('[data-automation-id*="formField"]').length);
            break;
        }
        // Fallback: empty inputs form
        const emptyRoot = findEmptyInlineFormRoot(section);
        if (emptyRoot) {
            resolvedRoot = emptyRoot;
            debugLog(`${WD} found empty inline form root (fallback)`, i + 1);
            break;
        }
        // Last fallback: latest entry root if it has form fields
        const fallback = resolveWorkdayEntryRoot(section, { useLatestEntry: true });
        if (fallback && fallback.querySelectorAll('[data-automation-id*="formField"]').length >= 2) {
            resolvedRoot = fallback;
        }
    }
    if (!resolvedRoot) {
        resolvedRoot = resolveWorkdayEntryRoot(section, { useLatestEntry: forceNew });
    }
    return fillWorkdayInlineEntry(entry, section, {
        education,
        useLatestEntry: forceNew,
        certification,
        entryRoot: resolvedRoot,
    });
}

// Fallback: locate the repeating section via its "Certification" name field, then walk up until an
// ancestor exposes the section's own Add/Delete controls. Needed because findSectionInForm()'s generic
// "heading.parentElement.parentElement" heuristic assumes the heading sits directly above the section's
// field grid — on tenants whose combined "Certifications/Licenses" entry splits its fields across sibling
// sub-wrappers (e.g. Certification/Certification Number/Issued Date/Expiration Date in one branch,
// Specialty/Start Date/End Date in another — observed on multicare.wd1), that 2-level walk-up lands on the
// wrong branch: it still finds an Add button (so no error is raised) but the returned "section" never
// contains the actual Certification field, silently leaving it empty and blocking Next ("Workday step
// stuck: experience") — not specific to this one tenant's layout, any tenant using a split-branch layout
// for this section hits it.
function findSectionByCertificationField() {
    // Search the whole document rather than getFormRoot(): on tenants where Workday keeps a second,
    // stale/off-screen copy of the applyFlowPage container in the DOM (not display:none, so it still
    // passes queryVisible()'s rect check), getFormRoot() can resolve to that stale copy and miss the
    // live Certification field entirely, making this fallback silently return null every time.
    const certField = [...document.querySelectorAll('[data-automation-id*="formField"]')]
        .find(c => /^certification$/i.test(getContainerLabel(c).replace(/\*/g, '').trim()) && isVisibleElement(c));
    if (!certField) return null;
    let node = certField.parentElement;
    for (let d = 0; d < 15 && node && node !== document.body; d++) {
        const hasAddOrDelete = [...node.querySelectorAll('button')].some(b =>
            /^add\b|^delete$/i.test((b.innerText || '').trim()));
        if (hasAddOrDelete) return node;
        node = node.parentElement;
    }
    return null;
}

/** Open inline certification form (resume-prefilled stub with a Certification field, no Delete button yet). */
function findOpenInlineCertificationRoot(section) {
    if (!section) return null;
    for (const ff of section.querySelectorAll('[data-automation-id*="formField"]')) {
        const lbl = getContainerLabel(ff).replace(/\*/g, '').trim().toLowerCase();
        if (!/^certification$|certification number|credential/.test(lbl)) continue;
        let node = ff.parentElement;
        for (let d = 0; d < 10 && node; d++) {
            // Include `section` itself as a last-resort candidate — some tenants lay every field of a
            // single-entry (non-repeating-card) certification section flat as direct children with no
            // intermediate row wrapper grouping 2+ fields together, so the walk-up would otherwise reach
            // `section` without ever returning a match.
            if (node.querySelectorAll('[data-automation-id*="formField"]').length >= 2) return node;
            if (node === section) break;
            node = node.parentElement;
        }
    }
    return null;
}

function findCertificationsSectionEl() {
    return queryVisible('[data-automation-id="certificationsSection"]')
        || queryVisible('[data-automation-id="certificationSection"]')
        || findSectionByCertificationField()
        || findSectionInForm(/^certification/i);
}

async function fillCertificationsSection(profile) {
    const section = findCertificationsSectionEl();
    if (!section) {
        debugLog(`${WD} certifications section not found`);
        return;
    }
    const certs = (profile?.courseCertificates || []).filter(c => c?.name).slice(0, 3);

    // "Not required + 0 committed entries" used to short-circuit here unconditionally, before ever
    // checking profile data. countWorkdaySectionEntries() only counts committed (delete-button) rows —
    // some tenants pre-render an already-OPEN, empty "Add Certification" inline form with its own
    // required "Certification" name dropdown even though the committed count is 0. Dismissing that form
    // is not reliable on every tenant, so a profile with real certificates was left un-filled while the
    // stray required dropdown stayed empty and blocked Next ("Workday step stuck: experience") — only
    // skip/dismiss now when there is genuinely no certificate data to fill.
    if (!certs.length) {
        if (!isSectionRequired(section) && countWorkdaySectionEntries(section) === 0) {
            debugLog(`${WD} certifications section not required and empty — skipping`);
            await dismissOptionalRepeatingSection(section, 'certification');
        } else {
            debugLog(`${WD} no certifications in profile`);
        }
        return;
    }

    await removeEmptyWorkdaySectionEntries(section, 'certification');
    await trimWorkdaySectionEntries(section, certs.length);

    // Persist across retries — if provider was fixed in a previous call, don't add any certs
    if (window.__wdCertProviderFixed) {
        debugLog(`${WD} cert provider fixed (from prev run), skipping all certs`);
        return;
    }
    let certProviderFixed = false; // flag: dropdown only has fixed providers, not searchable
    for (let i = 0; i < certs.length; i++) {
        if (certProviderFixed || window.__wdCertProviderFixed) {
            // Provider dropdown has a fixed list that doesn't match our certs — stop adding more
            certProviderFixed = true;
            debugLog(`${WD} cert provider fixed, stopping at cert`, i + 1);
            // Remove any open (unsaved) cert entry form from the section
            await ensureWorkdaySectionFormsClosed();
            await removeEmptyWorkdaySectionEntries(section, 'certification');
            break;
        }
        if (i >= countWorkdaySectionEntries(section)) {
            debugLog(`${WD} fill certification`, i + 1, certs[i].name);
            await addWorkdaySectionEntry(section, certs[i], { education: false, forceNew: true, certification: true });
        } else {
            const entryRoot = resolveWorkdayEntryRoot(section, { useLatestEntry: false, entryRoot: getEntryRootByIndex(section, i) });
            await fillWorkdayInlineEntry(certs[i], section, {
                education: false,
                certification: true,
                entryRoot,
            });
        }
        const root = resolveWorkdayEntryRoot(section, { useLatestEntry: true, entryRoot: getEntryRootByIndex(section, i) });
        const rootHasCertField = root && [...root.querySelectorAll('[data-automation-id*="formField"]')]
            .some(c => /^certification$/i.test(getContainerLabel(c).replace(/\*/g, '').trim()));
        if (!rootHasCertField) {
            // The section's "Add" control can create a differently-templated entry that has no
            // Certification name field at all (e.g. a Specialty/License-only row on multicare.wd1) when
            // the pre-existing stub entry already used up the one Certification-type slot — such an
            // entry can never hold this cert's name and its own required field(s) (e.g. Specialty) would
            // stay empty forever, blocking Next. Remove just this mismatched entry and stop adding more;
            // any certs already filled above (including the reused stub) are left intact.
            debugLog(`${WD} added cert entry has no Certification field (template mismatch) — removing, stop adding more`);
            const delBtns = getWorkdaySectionDeleteButtons(section);
            const rootDelBtn = delBtns.find(b => getEntryRootFromDeleteBtn(b, section) === root);
            if (rootDelBtn) {
                await workdayClick(rootDelBtn);
                await wait(800);
                await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
                await wait(1200);
            } else {
                await ensureWorkdaySectionFormsClosed();
                await removeEmptyWorkdaySectionEntries(section, 'certification');
            }
            break;
        }
        if (isWorkdayEntryEmpty(root, 'certification')) {
            debugLog(`${WD} certification entry empty after fill, retry`, i + 1);
            await fillWorkdayInlineEntry(certs[i], section, { certification: true, entryRoot: root });
            // Check again - if still empty, mark provider dropdown as fixed to stop adding more certs
            const rootCheck = resolveWorkdayEntryRoot(section, { useLatestEntry: true, entryRoot: getEntryRootByIndex(section, i) });
            if (isWorkdayEntryEmpty(rootCheck, 'certification')) {
                certProviderFixed = true;
                window.__wdCertProviderFixed = true;
                debugLog(`${WD} cert provider dropdown is fixed-list, skipping remaining certs`);
            }
        }
        if (isWorkdayEntryEditModal()) await saveWorkdayEntryModal();
    }
    await trimWorkdaySectionEntries(section, certs.length);
    // Remove cert entries that are still empty (provider not found in dropdown)
    // to prevent them from blocking form submission
    await removeEmptyWorkdaySectionEntries(section, 'certification');

    // If cert provider is a fixed-list (not searchable), delete ALL cert entries
    // because committed entries in summary view hide "0 items selected" status
    if (window.__wdCertProviderFixed || certProviderFixed) {
        debugLog(`${WD} cert provider fixed, deleting all remaining cert entries`);
        for (let g = 0; g < 10; g++) {
            const allDelBtns = getWorkdaySectionDeleteButtons(section);
            if (!allDelBtns.length) break;
            await workdayClick(allDelBtns[0]);
            await wait(800);
            await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
            await wait(1200);
        }
    } else {
        // Also remove any single remaining empty cert entry (removeEmpty stops at 1)
        const deleteBtns = getWorkdaySectionDeleteButtons(section);
        if (deleteBtns.length === 1) {
            const lastRoot = getEntryRootFromDeleteBtn(deleteBtns[0], section);
            if (isWorkdayEntryEmpty(lastRoot, 'certification')) {
                debugLog(`${WD} removing last empty cert entry`);
                await workdayClick(deleteBtns[0]);
                await wait(800);
                await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
                await wait(1200);
            }
        }
    }
    const remaining = countWorkdaySectionEntries(section);
    if (remaining < certs.length) {
        debugLog(`${WD} removed unfillable cert entries, remaining=`, remaining, '/', certs.length);
    }
}

async function waitForResumeAutofillComplete(section, maxMs = 8000) {
    const t0 = Date.now();
    while (Date.now() - t0 < maxMs) {
        const entries = countWorkdaySectionEntries(section);
        if (entries > 0) {
            wdTiming.mark('resume-autofill-ready', `${entries} entries ${Date.now() - t0}ms`);
            return true;
        }
        const body = document.body?.innerText || '';
        if (!/parsing|processing|uploading|please wait/i.test(body)) {
            await wait(400);
            if (countWorkdaySectionEntries(section) > 0) return true;
        }
        await wait(300);
    }
    debugLog(`${WD} resume autofill wait timeout`, maxMs, 'ms');
    return false;
}

async function fillExperienceSection(profile) {
    await pause();
    await cancelWorkdayEntryModal();
    await closeWorkdayPopups();
    const section = findWorkExperienceSection();
    if (!section) {
        debugLog(`${WD} work experience section not found`);
        return;
    }

    const useResumeBtn = [...getFormRoot().querySelectorAll('button')].find(b =>
        /use.*resume|import.*resume|parse.*resume|autofill|apply with resume/i.test((b.innerText || '').trim()));
    if (useResumeBtn) {
        debugLog(`${WD} clicking use resume button`);
        await workdayClick(useResumeBtn);
        await waitForResumeAutofillComplete(section);
        await trimWorkdaySectionEntries(section, MAX_WORKDAY_EXPERIENCE_ENTRIES);
    }

    const experiences = (profile?.experiences || []).slice(0, MAX_WORKDAY_EXPERIENCE_ENTRIES);
    if (!experiences.length) {
        debugLog(`${WD} no experiences in profile`);
        return;
    }

    await removeEmptyWorkdaySectionEntries(section, 'experience');
    await fillWorkdayExperienceEntries(section, experiences);
}

async function fillEducationSection(profile) {
    await cancelWorkdayEntryModal();
    await closeWorkdayPopups('education-start');
    const section = findEducationSectionEl();
    if (!section) {
        debugLog(`${WD} education section not found`);
        return;
    }

    if (!isSectionRequired(section) && !isEducationFieldsStillRequired(section) && countWorkdaySectionEntries(section) === 0) {
        debugLog(`${WD} education section not required — skipping fill`);
        return;
    }

    if (!isSectionRequired(section) && countWorkdaySectionEntries(section) === 0) {
        if (await shouldSkipOptionalEducationSection(section)) {
            debugLog(`${WD} education section not required and empty — skipping`);
            return;
        }
    }

    const edu = (profile?.educations || [])[0];
    if (!edu) {
        debugLog(`${WD} no education in profile`);
        return;
    }

    // If previously marked unfillable — remove any leftover entries and skip
    if (window.__wdEducationSchoolUnfillable) {
        const leftover = getWorkdaySectionDeleteButtons(section);
        if (leftover.length) {
            debugLog(`${WD} education unfillable (retry), removing leftover entries`);
            await ensureWorkdaySectionFormsClosed();
            for (let g = 0; g < 5; g++) {
                const btns = getWorkdaySectionDeleteButtons(section);
                if (!btns.length) break;
                await workdayClick(btns[0]);
                await wait(800);
                await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
                await wait(1200);
            }
        }
        return;
    }

    debugLog(`${WD} fill education`, 1, edu.school);
    let eduRoot = null;
    const openInlineRoot = findOpenInlineEducationRoot(section);
    if (countWorkdaySectionEntries(section) === 0 && openInlineRoot
        && isEducationEntryReady(section, edu, openInlineRoot)) {
        debugLog(`${WD} education inline form already complete (healthcare)`);
        markFieldOfStudyCommitted(openInlineRoot);
        eduRoot = openInlineRoot;
        await commitWorkdayInlineSectionEntry(section, eduRoot, 'education', edu);
    } else if (countWorkdaySectionEntries(section) === 0) {
        const preOpenedEdu = openInlineRoot || findEmptyInlineFormRoot(section);
        if (preOpenedEdu && isEducationFieldsStillRequired(section)) {
            debugLog(`${WD} education: fill pre-opened mandatory inline form`);
            await fillWorkdayInlineEntry(edu, section, { education: true, entryRoot: preOpenedEdu });
            markFieldOfStudyCommitted(preOpenedEdu);
            await commitWorkdayInlineSectionEntry(section, preOpenedEdu, 'education', edu);
            eduRoot = getFirstEntryRoot(section) || preOpenedEdu;
        } else {
            await addWorkdaySectionEntry(section, edu, { education: true });
            eduRoot = getFirstEntryRoot(section) || findOpenInlineEducationRoot(section);
        }
    } else {
        await addWorkdaySectionEntry(section, edu, { education: true });
        eduRoot = getFirstEntryRoot(section);
    }

    // Check if school typeahead failed during inline fill
    if (window.__wdEducationSchoolUnfillable) {
        debugLog(`${WD} education school unfillable after fill, removing entries`);
        await ensureWorkdaySectionFormsClosed();
        for (let g = 0; g < 5; g++) {
            const btns = getWorkdaySectionDeleteButtons(section);
            if (!btns.length) break;
            await workdayClick(btns[0]);
            await wait(800);
            await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
            await wait(1200);
        }
        return;
    }

    eduRoot = eduRoot || getFirstEntryRoot(section) || findEmptyInlineFormRoot(section);
    if (!eduRoot) return;

    if (isEducationEntryReady(section, edu, eduRoot)) {
        debugLog(`${WD} education entry complete, skip post-fill`);
        if (countWorkdaySectionEntries(section) === 0) {
            await commitWorkdayInlineSectionEntry(section, eduRoot, 'education', edu);
        }
    } else {
        for (const container of eduRoot.querySelectorAll('[data-automation-id*="formField"]')) {
            const label = getContainerLabel(container).toLowerCase();
            if (!/field of study|major|^degree$/i.test(label)) continue;
            if (/^degree$/i.test(label.replace(/\*/g, '').trim())) {
                if (isDegreeFilled(container)) continue;
                const degreeEl = getContainerControl(container) || getWorkdayDropdownTrigger(container) || container;
                await fillWorkdayDegreeDropdown(degreeEl, edu);
                continue;
            }
            if (shouldSkipFieldOfStudyRefill(container, edu)) continue;
            const control = getContainerControl(container);
            if (control) {
                await fillWorkdayFieldOfStudyDropdown(control, edu);
                markFieldOfStudyCommitted(container);
            }
        }

        if (countWorkdaySectionEntries(section) === 0) {
            await commitWorkdayInlineSectionEntry(section, eduRoot, 'education', edu);
        }
    }

    // Final check: if school required field is still empty, remove entry
    const finalRoot = getFirstEntryRoot(section);
    if (finalRoot) {
        const schoolContainer = [...finalRoot.querySelectorAll('[data-automation-id*="formField"]')]
            .find(c => /school|university|institution|college/i.test(getContainerLabel(c)));
        if (schoolContainer && isContainerRequired(schoolContainer)) {
            if (!isSchoolFieldFilled(schoolContainer)) {
                const schoolControl = getContainerControl(schoolContainer) || getWorkdayDropdownTrigger(schoolContainer);
                if (schoolControl && edu?.school) {
                    debugLog(`${WD} education school retry via search`, edu.school.slice(0, 50));
                    const retryFilled = await fillWorkdaySchoolViaSearch(schoolControl, edu.school);
                    if (retryFilled || isSchoolFieldFilled(schoolContainer)) {
                        debugLog(`${WD} education school filled on retry`);
                        return;
                    }
                }
                debugLog(`${WD} education school required but empty, removing entry`);
                window.__wdEducationSchoolUnfillable = true;
                await ensureWorkdaySectionFormsClosed();
                for (let g = 0; g < 5; g++) {
                    const btns = getWorkdaySectionDeleteButtons(section);
                    if (!btns.length) break;
                    await workdayClick(btns[0]);
                    await wait(800);
                    await clickModalActionButton(/^delete$|^confirm$|^yes$|^ok$/i);
                    await wait(1200);
                }
            }
        }
    }
}

async function fillDisclosureCheckboxes() {
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        for (const checkbox of container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')) {
            if (isWorkdayCheckboxChecked(checkbox)) continue;
            const boxLabel = (checkbox.closest('label')?.innerText || container.innerText || '').toLowerCase();
            const combined = `${labelLower} ${boxLabel}`;
            const shouldCheck = isWorkdayAcknowledgmentCheckboxText(combined);
            if (shouldCheck) {
                const ok = await workdayClickCheckbox(checkbox);
                debugLog(`${WD} checked disclosure`, label.slice(0, 80), 'ok=', ok);
            }
        }
        if ((/consent to the terms|terms and conditions|^i consent$/i.test(labelLower.trim())) && isContainerRequired(container)) {
            const checkbox = container.querySelector('input[type="checkbox"], [role="checkbox"]');
            if (checkbox && !isWorkdayCheckboxChecked(checkbox)) {
                const ok = await workdayClickCheckbox(checkbox);
                debugLog(`${WD} checked consent terms`, label.slice(0, 80), 'ok=', ok);
            }
        }
    }
}

function isWorkdayAcknowledgmentCheckboxText(text) {
    // "true and complete" alone missed the equally common "true & accurate" / "true and accurate" /
    // "accurate and complete" attestation phrasing (observed on cabrini.wd3: "The information I have
    // provided in my job application is true & accurate." rendered as a plain checkbox, excluded from
    // collectWorkdayFields as a section-only/acknowledgment-style field, but never matched here either,
    // so fillDisclosureCheckboxes() never checked it — leaving a Workday-flagged required checkbox
    // permanently unchecked and the disclosures step stuck on every tenant using this common attestation
    // wording, not just this one).
    return /acknowledge|agree|certify|confirm|accept|terms|privacy|disclosure|read and understand|i have read|i verify|true and complete|true\s*&\s*accurate|true and accurate|accurate and complete|best of my knowledge|consent to the terms|\bi consent\b|handwritten signature|checking the checkbox is equivalent|electronic signature|equivalent to (?:a )?signature|by checking this box/i.test(String(text || ''));
}

function isWorkdayAcknowledgmentCheckboxField(container, label = '') {
    if (!container) return false;
    const boxes = container.querySelectorAll('input[type="checkbox"], [role="checkbox"]');
    if (!boxes.length) return false;
    // Multi-option EEO groups are not acknowledgment fields.
    if (boxes.length >= 2 && isDisclosureChoiceGroup(container) && isWorkdayEeoDisclosureField(label || getContainerLabel(container))) {
        return false;
    }
    const combined = `${label || getContainerLabel(container)} ${container.innerText || ''}`.toLowerCase();
    return isWorkdayAcknowledgmentCheckboxText(combined);
}

function isWorkdayAcknowledgmentCheckboxFilled(container) {
    if (!container) return false;
    return [...container.querySelectorAll('input[type="checkbox"], [role="checkbox"]')]
        .some(cb => isWorkdayCheckboxChecked(cb));
}

async function fillVoluntaryDisclosures(profile) {
    await waitForWorkdayFormReady();
    // Drop stale local-fill marks when Workday still shows empty/error (Escape undoes commit).
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!isDisclosureLocalFillDone(label)) continue;
        const stillEmpty = (isWorkdayDisclosureGenderField(label) && !isWorkdayDisclosureGenderFilled(container, label))
            || (isWorkdayVeteranFieldLabel(label) && !isWorkdayVeteranFilled(container))
            || (isWorkdayRaceEthnicityFieldLabel(label.toLowerCase())
                && !container.querySelector('input[type="checkbox"]:checked, input[type="radio"]:checked')
                && isWorkdayRequiredDropdownEmpty(container));
        if (stillEmpty) {
            window.__wdDisclosureLocalFilled?.delete(normalizeDropdownOpenKey(label));
            debugLog(`${WD} clear stale local disclosure mark`, label.slice(0, 60));
        }
    }
    await fillDisclosureCheckboxes();
    const containers = getWorkdayFieldContainers();
    for (const container of containers) {
        const label = getContainerLabel(container);
        if (!isCitizenshipFieldLabel(label) || !isContainerRequired(container)) continue;
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        const hasError = /error:.*required/i.test(preview);
        if (!isCitizenshipFilled(container, profile) || hasError) {
            debugLog(`${WD} filling citizenship status disclosure`, label.slice(0, 60), 'error=', hasError);
            await fillWorkdayCitizenshipDropdown(container, profile);
        }
    }
    for (const container of containers) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        if (/date of birth/i.test(labelLower)) {
            const control = getContainerControl(container);
            const dob = getProfileDateOfBirth(profile);
            const preview = (container.innerText || '').replace(/\s+/g, ' ');
            if (control && dob && (!isDateContainerFilled(container, dob) || /error:|is required/i.test(preview))) {
                const ok = await fillWorkdayMaskedDate(container, control, dob, preview);
                debugLog(`${WD} filled disclosure date of birth`, dob, 'ok=', ok);
            }
            continue;
        }
        if (/marital status/i.test(labelLower) && isContainerRequired(container)) {
            const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            const maritalCandidates = jobLocationExpectsEgyptResidency()
                ? ['Single (Egypt)', 'Single', 'Married (Egypt)', 'Married', 'Divorced (Egypt)', 'Widowed (Egypt)']
                : ['Single', 'Married', 'Divorced', 'Widowed'];
            if (control && !isWorkdaySingleSelectFilled(container, maritalCandidates)) {
                await fillWorkdaySingleSelectDropdown(control, maritalCandidates, labelLower);
            }
            continue;
        }
        if (isNationalityCountryFieldLabel(label) && isContainerRequired(container)) {
            const control = getContainerControl(container) || getWorkdayDropdownTrigger(container);
            if (control && !isCountryFilled(container, profile)) {
                debugLog(`${WD} filling nationality country dropdown`, label.slice(0, 60));
                await fillWorkdayCountryDropdown(control, profile);
            }
            continue;
        }
        if (isCitizenshipFieldLabel(label)) {
            continue;
        }
        if (/sexual orientation|lgbtqia/i.test(labelLower)) {
            const candidates = ['Prefer Not to Respond', 'Prefer Not to Respond (India)', 'Prefer Not to Say', ...WORKDAY_DECLINE_PHRASES];
            if (!isWorkdaySingleSelectFilled(container, candidates)) {
                const control = getContainerControl(container);
                if (control) {
                    await fillWorkdayDisclosureSingleSelectDropdown(control, candidates, labelLower);
                }
            }
        }
        // Gender/sex disclosure fields are never filled locally here — profile has no gender,
        // so the field is always resolved via the AI stream in fillWorkdayFields (see
        // chrome-extension.mdc "Gender / sex disclosure fields — never choose locally").
        if (/disability/i.test(labelLower) && /consider yourself|do you have a disability|select.*yes.*option/i.test(labelLower)) {
            const disabilityCandidates = ['No', 'No (India)', 'No, I Do Not Have A Disability', "No, I Don't Have A Disability", ...WORKDAY_DECLINE_PHRASES];
            if (!isWorkdayDisclosureSelectionFilled(container, disabilityCandidates)) {
                const control = getContainerControl(container);
                if (control) {
                    const ok = await fillWorkdayDisclosureSingleSelectDropdown(control, disabilityCandidates, labelLower);
                    if (ok) markDisclosureLocalFilled(label);
                }
            }
        }
        if (isWorkdayVeteranFieldLabel(label) && !isWorkdayVeteranFilled(container)) {
            await fillWorkdayVeteranField(container, label, profile);
        }
        if (isWorkdayRaceEthnicityFieldLabel(labelLower) && isDisclosureChoiceGroup(container)) {
            await fillWorkdayEthnicityDisclosureField(container, label, profile);
        }
        if (/sex at birth|sex.*birth|biological sex/i.test(labelLower) && !isWorkdaySingleSelectFilled(container, getDisclosureSexAtBirthCandidates())) {
            const control = getContainerControl(container);
            if (control) {
                await fillWorkdaySingleSelectDropdown(control, getDisclosureSexAtBirthCandidates(), labelLower);
            }
        }
    }
    await fillDisclosureCheckboxes();
}

function isSelfIdentifyLocalField(label) {
    const l = String(label || '').toLowerCase().trim();
    return /^name$/i.test(l)
        || /^date$/i.test(l)
        || /disabilit|check one of the boxes/i.test(l)
        || /employee id/i.test(l);
}

/** Commit text into a React-controlled input. No element.click(). */
function wdCommitReactTextInput(el, value) {
    if (!el) return false;
    const str = String(value ?? '');
    // React 16+ _valueTracker: setValue(previous) so the next native set is seen as a change.
    const previous = el.value ?? '';
    try {
        const protoSet = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set
            || Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value')?.set;
        if (protoSet) protoSet.call(el, str);
        else el.value = str;
    } catch (_) {
        el.value = str;
    }
    try {
        const tracker = el._valueTracker;
        if (tracker && typeof tracker.setValue === 'function') tracker.setValue(previous);
    } catch (_) { /* ignore */ }
    // Call React's own onChange — walk props on the node and parent fibers (Canvas Kit wraps inputs).
    try {
        const propKey = Object.keys(el).find(k => k.startsWith('__reactProps$') || k.startsWith('__reactEventHandlers$'));
        const props = propKey ? el[propKey] : null;
        if (props && typeof props.onChange === 'function') {
            props.onChange({ target: el, currentTarget: el, type: 'change', bubbles: true });
        }
        if (props && typeof props.onInput === 'function') {
            props.onInput({ target: el, currentTarget: el, type: 'input', bubbles: true });
        }
        const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
        let fiber = fiberKey ? el[fiberKey] : null;
        let walked = 0;
        while (fiber && walked < 12) {
            const fp = fiber.memoizedProps || fiber.pendingProps;
            if (fp && typeof fp.onChange === 'function') {
                fp.onChange({ target: el, currentTarget: el, type: 'change', bubbles: true });
                debugLog(`${WD} react fiber onChange depth=`, walked);
                break;
            }
            fiber = fiber.return;
            walked += 1;
        }
    } catch (e) {
        debugLog(`${WD} react props onChange failed`, e?.message || e);
    }
    try {
        if (typeof el.setRangeText === 'function') {
            el.focus?.();
            el.setRangeText(str, 0, (el.value || '').length, 'end');
            el.dispatchEvent(new InputEvent('input', {
                bubbles: true, composed: true, inputType: 'insertText', data: str,
            }));
        }
    } catch (_) { /* ignore */ }
    el.dispatchEvent(new InputEvent('input', {
        bubbles: true, composed: true, inputType: 'insertText', data: str,
    }));
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    return (el.value || '').trim() === str.trim();
}

/** Focus-only per-character typing for OFCCP Name — avoids click helpers; uses insertText. */
async function workdayTypeSelfIdentifyNameKeystroke(el, text) {
    if (!el || text == null || text === '') return false;
    workdayScrollToTarget(el, 120);
    await wait(80);
    try { el.focus?.(); } catch (_) { /* ignore */ }
    await wait(60);
    selectWorkdayInputText(el);
    try {
        document.execCommand('selectAll', false, null);
        document.execCommand('delete', false, null);
    } catch (_) { /* ignore */ }
    setNativeValue(el, '');
    el.dispatchEvent(new InputEvent('input', { inputType: 'deleteContentBackward', bubbles: true, composed: true }));
    await wait(60);
    const str = String(text);
    for (const ch of str) {
        el.dispatchEvent(new KeyboardEvent('keydown', { key: ch, code: ch === ' ' ? 'Space' : `Key${ch.toUpperCase()}`, bubbles: true, composed: true, cancelable: true }));
        el.dispatchEvent(new KeyboardEvent('keypress', { key: ch, bubbles: true, composed: true, cancelable: true }));
        let inserted = false;
        try { inserted = document.execCommand('insertText', false, ch); } catch (_) { /* ignore */ }
        if (!inserted) {
            const prev = el.value || '';
            setNativeValue(el, prev + ch);
            el.dispatchEvent(new InputEvent('input', { inputType: 'insertText', data: ch, bubbles: true, composed: true }));
        }
        el.dispatchEvent(new KeyboardEvent('keyup', { key: ch, bubbles: true, composed: true }));
        await wait(40);
    }
    el.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(120);
    return (el.value || '').trim() === str.trim();
}

/**
 * OFCCP / self_identify Name — Workday Canvas Kit often keeps React form state empty while
 * DOM .value shows the typed name (belron.wd3: Error-Name after Next despite "Elena Park").
 * Bulk setRangeText / wdCommitReactTextInput / "already set, re-commit" are not enough.
 * Always use per-keystroke fill so the controlled model updates; focus-only (no label click
 * that can hit nested policy <a> on nearby consent steps).
 */
async function fillWorkdaySelfIdentifyName(control, fullName, _opts = {}) {
    if (!control || !fullName) return false;
    const container = control.closest('[data-automation-id*="formField"]') || control.parentElement;
    try { dumpWorkdayDateContainerDom(container, 'name-field'); } catch (_) { /* ignore */ }
    workdayScrollToTarget(control, 120);
    await wait(80);

    try { control.focus?.(); } catch (_) { /* ignore */ }
    await wait(40);
    // Per-keystroke is required — bulk/react soft-commit leaves Error-Name on Next (belron.wd3).
    let ok = await workdayTypeSelfIdentifyNameKeystroke(control, fullName);
    if (!ok || (control.value || '').trim() !== fullName) {
        wdCommitReactTextInput(control, fullName);
        ok = (control.value || '').trim() === fullName;
    }
    control.dispatchEvent(new Event('blur', { bubbles: true }));
    await wait(200);
    try { control.focus?.(); } catch (_) { /* ignore */ }
    control.dispatchEvent(new KeyboardEvent('keydown', { key: 'Tab', bubbles: true, composed: true }));
    const footer = document.querySelector('[data-automation-id="applicationFooter"], [data-automation-id="pageFooter"]');
    if (footer) footer.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
    await wait(250);
    ok = (control.value || '').trim() === fullName;
    const stillErr = /error:\s*the field name is require|error-name/i.test(
        `${container?.innerText || ''}\n${dumpWorkdayErrorsFoundBlock(true) || ''}`
    );
    debugLog(`${WD} self-identify name keystroke`, fullName,
        'value=', (control.value || '').slice(0, 40), 'ok=', ok, 'bannerErr=', stillErr);
    return ok && !stillErr;
}

async function fillWorkdaySelfIdentifyDisabilityNo(container) {
    if (!container) return false;
    if (container.querySelector('input[type="radio"]:checked, input[type="checkbox"]:checked')) return true;
    for (const labelEl of container.querySelectorAll('label')) {
        const text = (labelEl.innerText || '').trim().toLowerCase();
        if (!/no, i do not have a disabili|no, i don't have a disabili|do not have a disability/i.test(text)) continue;
        const input = labelEl.control || document.getElementById(labelEl.getAttribute('for'));
        // Prefer label mousedown/up over workdayClick (.click can be slow); fall back to checked=.
        labelEl.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
        labelEl.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
        if (typeof labelEl.click === 'function') labelEl.click();
        if (input && !input.checked) {
            input.checked = true;
            input.dispatchEvent(new Event('input', { bubbles: true }));
            input.dispatchEvent(new Event('change', { bubbles: true }));
        }
        const filled = Boolean(input?.checked);
        debugLog(`${WD} filled disability checkbox`, text.slice(0, 60), 'checked=', filled);
        return filled;
    }
    for (const radio of container.querySelectorAll('input[type="radio"]')) {
        const optLabel = (document.querySelector(`label[for="${radio.id}"]`)?.innerText
            || radio.closest('label')?.innerText || '').trim().toLowerCase();
        if (!/no.*do not have a disabili|don't have a disabili|do not have a disability/i.test(optLabel)) continue;
        const labelEl = document.querySelector(`label[for="${radio.id}"]`) || radio;
        labelEl.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
        if (typeof labelEl.click === 'function') labelEl.click();
        if (!radio.checked) {
            radio.checked = true;
            radio.dispatchEvent(new Event('change', { bubbles: true }));
        }
        debugLog(`${WD} filled disability radio`, optLabel.slice(0, 60));
        return radio.checked;
    }
    return false;
}

async function fillSelfIdentifyFields(profile) {
    await waitForWorkdayFormReady();

    const firstName = profile?.firstName || profile?.general?.firstName || '';
    const lastName = profile?.lastName || profile?.general?.lastName || '';
    const fullName = `${firstName} ${lastName}`.trim();
    const now = new Date();
    const today = `${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')}/${now.getFullYear()}`;

    // Field labels Workday's own "Errors Found" banner flagged on a PRIOR failed Next click for this
    // step-try — force a re-fill of these below even when control.value looks already populated. See
    // getWorkdayErrorFieldLabelTokens(): the "Name" self-certification field is a recurring case where
    // the DOM control.value gets set correctly but Workday's React-controlled validation still reports
    // it blank, and the plain "skip if control.value is non-empty" check then leaves it stuck forever
    // across every retry (never re-attempted since it looks filled) -> "Workday step stuck: self_identify".
    const priorErrorTokens = getWorkdayErrorFieldLabelTokens();

    // Order matters on belron.wd3 OFCCP panel: disability choice → date (calendar) → Name last.
    // Filling Name before disability/date leaves Error-Name required despite DOM value.
    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (/disabilit|check one of the boxes/i.test(label)) {
            await fillWorkdaySelfIdentifyDisabilityNo(container);
        }
    }

    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!/^date$/i.test(label.toLowerCase())) continue;
        const control = getContainerControl(container);
        const preview = (container.innerText || '').replace(/\s+/g, ' ');
        const hasError = dateContainerHasBlockingError(container)
            || /invalid date|error:/i.test(preview)
            || priorErrorTokens.has('date');
        if (control && (!isDateContainerFilled(container, today) || hasError
            || !areSplitDateInputsFilled(container, ...today.split('/')))) {
            if (hasError) debugLog(`${WD} self-identify date error, refilling`, preview.slice(0, 80));
            const ok = await fillWorkdayMaskedDate(container, control, today, preview, { force: true });
            debugLog(`${WD} filled self-identify date`, today, 'ok=', ok, 'hadErr=', hasError);
        }
    }

    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        if (!/^name$/i.test(label.toLowerCase())) continue;
        const control = getContainerControl(container)
            || container.querySelector('input[name="name"], #selfIdentifiedDisabilityData--name');
        const hasNameError = priorErrorTokens.has('name')
            || /error:\s*the field name is require/i.test(container.innerText || '');
        if (control && fullName) {
            if (hasNameError) debugLog(`${WD} self-identify name error, refilling`, (control.value || '').slice(0, 40));
            const ok = await fillWorkdaySelfIdentifyName(control, fullName, { forceKeystroke: true });
            debugLog(`${WD} filled self-identify name`, fullName, 'ok=', ok, 'hadErr=', hasNameError);
        }
    }

    for (const container of getWorkdayFieldContainers()) {
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        if (/^name$/i.test(labelLower) || /^date$/i.test(labelLower)) continue;
        if (/disabilit|check one of the boxes/i.test(labelLower)) continue;

        if (isWorkdayGenderIdentityField(label) || isWorkdayDisclosureGenderField(labelLower)) {
            if (!isWorkdayDisclosureGenderFilled(container)) {
                await fillWorkdayDisclosureGenderField(container, label);
            }
            continue;
        }
    }

    // Final Name keystroke after gender/radio side effects (model can reset).
    for (const container of getWorkdayFieldContainers()) {
        if (!/^name$/i.test(getContainerLabel(container).toLowerCase())) continue;
        const control = getContainerControl(container)
            || container.querySelector('input[name="name"], #selfIdentifiedDisabilityData--name');
        if (control && fullName) {
            await fillWorkdaySelfIdentifyName(control, fullName, { forceKeystroke: true });
            debugLog(`${WD} filled self-identify name final`, fullName, 'value=', (control.value || '').slice(0, 40));
        }
    }

    for (const container of getWorkdayFieldContainers()) {
        if (container.querySelector('input[type="radio"]:checked')) continue;
        const label = getContainerLabel(container).toLowerCase();
        for (const radio of container.querySelectorAll('input[type="radio"]')) {
            const optLabel = (document.querySelector(`label[for="${radio.id}"]`)?.innerText
                || radio.closest('label')?.innerText || '').trim().toLowerCase();
            if (/decline|prefer not|do not wish|don't wish|choose not|not wish to disclose|not wish to answer/i.test(optLabel)) {
                await workdayClick(radio);
                debugLog(`${WD} filled self-identify radio`, label.slice(0, 50), optLabel);
                break;
            }
        }
    }

    for (const container of getWorkdayFieldContainers()) {
        const preview = (container.innerText || '');
        if (!/select one|0 items selected|error:/i.test(preview)) continue;
        const label = getContainerLabel(container);
        const labelLower = label.toLowerCase();
        // Name/Date/disability are filled above as text/date/checkbox — never open them as
        // dropdowns. Matching on "error:" alone was opening Name as a select (belron.wd3).
        if (isSelfIdentifyLocalField(label)) continue;
        if (isMMDDYYYYContainer(container) || isWorkdayMaskedDateField(container, labelLower)) continue;
        if (isWorkdayGenderIdentityField(label) || isWorkdayDisclosureGenderField(labelLower)) {
            if (!isWorkdayDisclosureGenderFilled(container)) {
                await fillWorkdayDisclosureGenderField(container, label);
            }
            continue;
        }
        const control = getContainerControl(container);
        if (!control) continue;
        // Plain text inputs with an error banner are not selects.
        if (control.tagName === 'TEXTAREA'
            || (control.tagName === 'INPUT' && !control.getAttribute('role')
                && !/combobox|listbox/i.test(control.getAttribute('aria-haspopup') || ''))) {
            continue;
        }
        const profileValue = getProfileFieldValue(profile, label);
        const candidates = profileValue
            ? [profileValue, ...WORKDAY_DECLINE_PHRASES.filter(p => p !== profileValue)]
            : WORKDAY_DECLINE_PHRASES;
        if (isWorkdaySingleSelectFilled(container, candidates)) continue;
        if (await fillWorkdaySingleSelectDropdown(control, candidates, label)) {
            debugLog(`${WD} filled self-identify`, label.slice(0, 60));
        } else if (await fillWorkdayDropdown(control, candidates[0])) {
            debugLog(`${WD} filled self-identify`, label.slice(0, 60), candidates[0]);
        }
    }

    logEmptyRequiredFields();
    logFieldValues();
    logWorkdayValidationErrors();
}

async function fillDisabilityDateField() {
    const labels = [...document.querySelectorAll('label')].filter(l => /disability|self-identification/i.test(l.innerText || ''));
    for (const label of labels) {
        const container = label.closest('[data-automation-id*="formField"]') || label.parentElement;
        const dateInput = container?.querySelector('input');
        if (!dateInput) continue;
        const candidates = [];
        const now = new Date();
        for (const offset of [0, -1, 1]) {
            const d = new Date(now);
            d.setDate(d.getDate() + offset);
            candidates.push(d.toLocaleDateString('en-US'));
            candidates.push(d.toISOString().slice(0, 10));
        }
        for (const value of candidates) {
            setNativeValue(dateInput, value);
            dateInput.dispatchEvent(new Event('change', { bubbles: true }));
            await wait(500);
            if (!dateInput.validationMessage) return;
        }
    }
}

function findWorkdayNextButton() {
    const footerScopes = [
        queryVisible('[data-automation-id="applicationFooter"]'),
        queryVisible('[data-automation-id="pageFooter"]'),
        queryVisible('[data-automation-id="applyFlowPrimaryPage"]'),
        getFormRoot(),
        document.body,
    ].filter(Boolean);

    const selectors = [
        '[data-automation-id="bottom-navigation-next-button"]',
        '[data-automation-id="pageFooterNextButton"]',
        '[data-automation-id="nextButton"]',
        '[data-automation-id="bottom-navigation-save-button"]',
        'button[data-automation-id="click_filter"]',
    ];

    for (const scope of footerScopes) {
        for (const sel of selectors) {
            const btn = queryVisible(sel, scope);
            if (!btn) continue;
            const text = (btn.innerText || btn.getAttribute('aria-label') || '').trim();
            if (isWorkdaySubmitButtonLabel(text)) continue;
            return btn;
        }
        const footerBtn = [...scope.querySelectorAll('button, [role="button"]')]
            .find(el => {
                if (!isVisibleElement(el)) return false;
                const text = (el.innerText || el.getAttribute('aria-label') || '').trim();
                if (isWorkdaySubmitButtonLabel(text)) return false;
                return /^(next|continue|save and continue|save)$/i.test(text);
            });
        if (footerBtn) return footerBtn;
    }

    return [...document.querySelectorAll('button, [role="button"]')]
        .find(el => {
            if (!isVisibleElement(el)) return false;
            const text = (el.innerText || el.getAttribute('aria-label') || '').trim();
            if (isWorkdaySubmitButtonLabel(text)) return false;
            return /^(next|continue|save and continue)$/i.test(text);
        }) || null;
}

async function clickNextButton(transitionContext = null) {
    blurWorkdayActiveInput();
    await wait(150);

    const footer = queryVisible('[data-automation-id="applicationFooter"]')
        || queryVisible('[data-automation-id="pageFooter"]');
    if (footer) {
        workdayScrollToTarget(footer, 0);
        await wait(200);
    } else {
        window.scrollTo(0, document.body.scrollHeight);
        await wait(200);
    }

    const nextBtn = findWorkdayNextButton();
    debugLog(`${WD} next button`, nextBtn ? (nextBtn.innerText || nextBtn.getAttribute('aria-label') || '').trim() : 'not found',
        'disabled=', nextBtn?.disabled, 'aria-disabled=', nextBtn?.getAttribute('aria-disabled'));
    if (!nextBtn) {
        const buttons = [...document.querySelectorAll('button, [role="button"]')]
            .filter(isVisibleElement)
            .map(el => (el.innerText || el.getAttribute('aria-label') || '').trim())
            .filter(t => t && t.length < 50)
            .slice(0, 15);
        debugLog(`${WD} visible buttons sample`, buttons.join(' | '));
    }
    if (!nextBtn || nextBtn.disabled || nextBtn.getAttribute('aria-disabled') === 'true') return false;
    workdayScrollToTarget(nextBtn, 120);
    await wait(150);
    await workdayClick(nextBtn);
    if (transitionContext) {
        await waitForWorkdayAfterNextClick(
            transitionContext.prevHref,
            transitionContext.prevStepKey,
            transitionContext.prevInfo
        );
    } else {
        await wait(1500);
    }
    dumpWorkdayErrorsFoundBlock();
    logWorkdayValidationErrors();
    return true;
}

function canSafelySubmitWorkdayApplication() {
    const info = getStepInfo();
    if (info.step && info.total && info.step < info.total) {
        debugLog(`${WD} submit blocked — not on final step`, info.step, '/', info.total);
        return false;
    }
    if (!isWorkdayApplicationReviewStep()) {
        debugLog(`${WD} submit blocked — not a review step`);
        return false;
    }
    if (workdayReviewHasUnansweredQuestions()) {
        debugLog(`${WD} submit blocked — unanswered questions on review`);
        return false;
    }
    const nextBtn = findWorkdayNextButton();
    if (nextBtn) {
        const text = (nextBtn.innerText || nextBtn.getAttribute('aria-label') || '').trim();
        debugLog(`${WD} submit blocked — Next button visible`, text);
        return false;
    }
    return true;
}

/** Review summary shows "No Response" when questionnaire selects never committed (unimelb.wd105). */
function workdayReviewHasUnansweredQuestions() {
    const text = String(document.body?.innerText || '');
    if (/answer all required questions to submit/i.test(text)) return true;
    if (/Errors Found/i.test(text) && /\bNo Response\b/i.test(text)) return true;
    const noResponseCount = (text.match(/\bNo Response\b/g) || []).length;
    if (noResponseCount >= 2
        && /eligible to work|place of residence|work rights|application questions/i.test(text)) {
        return true;
    }
    return false;
}

async function returnToWorkdayQuestionsFromReview() {
    // Prefer Workday "Errors Found" / No Response row buttons — they jump to the unanswered control.
    for (const el of document.querySelectorAll('button, a, [role="button"], li, [data-automation-id*="error"]')) {
        if (!isVisibleElement(el)) continue;
        const t = String(el.innerText || el.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (t.length < 8 || t.length > 220) continue;
        if (!/eligible to work|place of residence|work rights|hours per week.*visa|visa enable|current or most recent employer|availability to start/i.test(t)) {
            continue;
        }
        if (!/error|required|no response|edit/i.test(t)
            && !el.closest?.('[data-automation-id*="error"], [data-automation-id*="Error"], ol, ul')) {
            continue;
        }
        debugLog(`${WD} review → questions via error item`, t.slice(0, 70));
        workdayScrollToTarget(el, 80);
        await workdayClick(el);
        await wait(2500);
        if (!isWorkdayApplicationReviewStep()) return true;
        if (isWorkdayApplicationQuestionsStep() || getCurrentStepKey() === 'questions') return true;
    }
    // Explicit Edit on Application Questions section of the review summary.
    for (const el of document.querySelectorAll(
        'button, a, [role="button"], [data-automation-id*="Edit"], [data-automation-id*="edit"]',
    )) {
        if (!isVisibleElement(el)) continue;
        const t = String(el.innerText || el.getAttribute('aria-label') || el.getAttribute('data-automation-id') || '')
            .replace(/\s+/g, ' ').trim();
        if (!/^edit$/i.test(t) && !/edit/i.test(t)) continue;
        if (/edit account|edit profile|edit email/i.test(t)) continue;
        const section = el.closest('[data-automation-id*="panel"], section, article, div') || el.parentElement;
        const sectionText = String(section?.innerText || '').slice(0, 500);
        if (!/application questions|eligible to work|place of residence|my experience|questionnaire/i.test(sectionText)
            && !/application questions/i.test(t)) {
            // Prefer edits near No Response blocks
            if (!/\bno response\b/i.test(sectionText)) continue;
        }
        debugLog(`${WD} review → questions via Edit`, t.slice(0, 60));
        workdayScrollToTarget(el, 80);
        await workdayClick(el);
        await wait(2500);
        if (!isWorkdayApplicationReviewStep() || isWorkdayApplicationQuestionsStep()
            || getCurrentStepKey() === 'questions') {
            return true;
        }
    }
    const candidates = [
        ...document.querySelectorAll('[data-automation-id*="progressBar"] button, [data-automation-id*="progressBar"] a, [data-automation-id*="progressBar"] [role="button"], [data-automation-id*="progressBar"] li'),
        ...document.querySelectorAll('[data-automation-id="navigationItem"], button, a, [role="link"], [role="button"]'),
    ];
    for (const el of candidates) {
        if (!isVisibleElement(el)) continue;
        const t = String(el.innerText || el.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim();
        if (!/application questions/i.test(t)) continue;
        if (/^review$/i.test(t)) continue;
        debugLog(`${WD} review → questions click`, t.slice(0, 60));
        workdayScrollToTarget(el, 80);
        await workdayClick(el);
        await wait(2500);
        // Do NOT treat review-page field mirrors as success (getWorkdayFieldContainers >= 3 false positive).
        if (getCurrentStepKey() === 'questions' || isWorkdayApplicationQuestionsStep()
            || !isWorkdayApplicationReviewStep()) {
            return true;
        }
    }
    debugLog(`${WD} review → questions failed`);
    return false;
}

async function clickSubmitButton() {
    const submitBtn = queryVisible('[data-automation-id="bottom-navigation-next-button"]')
        || [...document.querySelectorAll('button')].find(el => /submit/i.test(el.innerText || ''));
    if (!submitBtn) throw new SendCvError('Submit button not found');
    markWorkdaySubmitPending();
    workdayScrollToTarget(submitBtn, 120);
    await wait(300);
    submitBtn.click();
    await wait(3000);
}

async function processCurrentStep(data, stepKey, started, stepTry = 1) {
    await pause();
    debugLog(`${WD} process step`, stepKey, getStepInfo());

    installWorkdayAccidentalSubmitGuard();
    installWorkdayExternalNavigationGuard();
    setWorkdayFillInProgress(true);
    try {
    switch (stepKey) {
        case 'loading':
            if (isIntroduceYourselfDone() && /\/applyManually/i.test(location.pathname)
                && getWorkdayFieldContainers().length === 0) {
                dumpPostIntroApplyShell('applyManually-empty');
                if (await activatePostIntroApplyShell()) break;
                debugLog(`${WD} post-introduceYourself empty applyManually — activate apply`);
                await clickWorkdayActiveProgressStep();
                await activateWorkdayCurrentStep();
                await wait(5000);
                if (getWorkdayFieldContainers().length > 0 || findWorkdayNextButton()) break;
                const applyUrl = location.href.replace(/\/applyManually\/?(?=[?#]|$)/i, '/apply');
                if (applyUrl !== location.href) {
                    debugLog(`${WD} post-introduceYourself applyManually -> /apply`, applyUrl.slice(0, 120));
                    try { sessionStorage.setItem(WD_APPLY_URL_KEY, applyUrl); } catch (_) { /* ignore */ }
                    window.top.location.replace(applyUrl);
                    await wait(10000);
                    await waitForWorkdayApplyContent(45000);
                    break;
                }
                const appUrl = location.href.replace(/\/applyManually\/?(?=[?#]|$)/i, '/apply/app');
                if (appUrl !== location.href) {
                    debugLog(`${WD} post-introduceYourself applyManually -> app`, appUrl.slice(0, 120));
                    try { sessionStorage.setItem(WD_APPLY_URL_KEY, appUrl); } catch (_) { /* ignore */ }
                    window.top.location.replace(appUrl);
                    await wait(10000);
                    await waitForWorkdayApplyContent(45000);
                    break;
                }
                debugLog(`${WD} post-introduceYourself empty applyManually — recover`);
                await recoverEmptyWorkdayApplyPage();
                if (getWorkdayFieldContainers().length === 0) {
                    const applyUrl = getWorkdayPostIntroApplyUrl(window.__wdApplyData);
                    if (applyUrl && applyUrl !== location.href) {
                        debugLog(`${WD} post-introduceYourself — direct apply url`, applyUrl.slice(0, 120));
                        try { sessionStorage.setItem(WD_APPLY_URL_KEY, applyUrl); } catch (_) { /* ignore */ }
                        window.top.location.replace(applyUrl);
                        await wait(10000);
                    }
                }
                await waitForWorkdayApplyContent(45000);
                break;
            }
            if (isWorkdayIntroduceYourselfPage()) {
                const introFields = getWorkdayFieldContainers().length;
                const introNext = findWorkdayNextButton();
                if (introFields > 0 || introNext) {
                    if (isIntroduceYourselfDone()) {
                        debugLog(`${WD} introduceYourself skip refill — applyManually`);
                        await goToPostIntroApplyManually();
                        await activatePostIntroApplyShell();
                        break;
                    }
                    debugLog(`${WD} introduceYourself profile form — fill`, 'fields=', introFields, 'next=', Boolean(introNext));
                    await fillAndSubmitIntroduceYourself(data, started);
                    break;
                }
                debugLog(`${WD} loading step on introduceYourself — return to apply`);
                await returnFromIntroduceYourselfToApply();
                break;
            }
            if (isWorkdayCandidateHomePage()) {
                debugLog(`${WD} loading step on candidate home — navigate to apply`);
                await returnToApplyFormFromCandidateHome();
                break;
            }
            if (isWorkdayAuthStepShell() || isWorkdayEmailSignInGateway() || findWorkdaySignInWithEmailButton()) {
                debugLog(`${WD} loading step auth shell — skip form wait`);
                break;
            }
            if (isWorkdayCreateAccountVisible()) {
                debugLog(`${WD} loading step but create account visible — auth`);
                notifyWorkdayCreateAccountAutofill();
                break;
            }
            if (/\/applyManually/i.test(location.pathname) && getWorkdayFieldContainers().length === 0) {
                let authDetected = false;
                for (let i = 0; i < 30; i++) {
                    if (isWorkdayAuthStepShell() || isWorkdayEmailSignInGateway() || findWorkdaySignInWithEmailButton()) {
                        debugLog(`${WD} loading step auth shell detected`, 'poll=', i + 1);
                        authDetected = true;
                        break;
                    }
                    if (getWorkdayFieldContainers().length >= 2) break;
                    await wait(200);
                }
                if (authDetected) break;
            }
            if (/\/applyManually/i.test(location.pathname) && getWorkdayFieldContainers().length === 0 && stepTry >= 3) {
                if (isIntroduceYourselfDone()) {
                    debugLog(`${WD} loading on applyManually after intro — activate apply`, stepTry);
                    await clickWorkdayActiveProgressStep();
                    await activateWorkdayCurrentStep();
                    await wait(5000);
                    if (getWorkdayFieldContainers().length > 0 || findWorkdayNextButton()) break;
                }
                debugLog(`${WD} loading on applyManually shell try`, stepTry);
                const recovered = await recoverEmptyWorkdayApplyPage();
                if (!recovered && stepTry >= 6) {
                    const basePath = location.pathname.replace(/\/applyManually\/?$/i, '');
                    const targetPath = /\/apply$/i.test(basePath) ? basePath : `${basePath.replace(/\/$/, '')}/apply`;
                    if (targetPath !== location.pathname) {
                        debugLog(`${WD} redirect from applyManually`, targetPath);
                        location.href = `${location.origin}${targetPath}${location.search}`;
                        await wait(8000);
                    }
                }
                await wait(1500);
                const introFieldCount = getWorkdayFieldContainers().length;
                const introNextBtn = findWorkdayNextButton();
                const onIntroShell = isWorkdayIntroduceYourselfPage()
                    || (!isIntroduceYourselfDone()
                        && /introduce yourself/i.test(`${getStepInfo().stepLine} ${getStepInfo().stepName}`));
                if (onIntroShell && (introFieldCount > 0 || introNextBtn)) {
                    if (isIntroduceYourselfDone()) {
                        debugLog(`${WD} introduceYourself skip refill — applyManually`);
                        await goToPostIntroApplyManually();
                        await activatePostIntroApplyShell();
                        break;
                    }
                    debugLog(`${WD} introduceYourself after recover — fill`, 'fields=', introFieldCount,
                        'href=', location.pathname.slice(-40));
                    await fillAndSubmitIntroduceYourself(data, started);
                }
                break;
            }
            debugLog(`${WD} waiting for apply form to render`);
            await waitForWorkdayFormReady();
            await wait(1000);
            if (isDuplicateApplicationPage()) {
                reportWorkdayAlreadyApplied();
                return 'already-applied';
            }
            break;
        case 'auth':
            if (isIntroduceYourselfDone()) {
                debugLog(`${WD} auth step after introduceYourself`);
                clearIntroduceYourselfDone();
            }
            await fillAuthStep(data.profile);
            if (abortIfWorkdayAlreadyApplied()) return 'already-applied';
            break;
        case 'experience':
            await waitForWorkdayFormReady();
            await uploadResume(data);
            await waitForResumeProcessed(window.__wdCachedResume?.originalFilename);
            if (stepTry <= 1) {
                await fillExperienceSection(data.profile);
                await fillEducationSection(data.profile);
                await fillCertificationsSection(data.profile);
                await fillExperiencePageExtras(data.profile);
            } else {
                debugLog(`${WD} experience retry`, stepTry, 'fix gaps only');
                await uploadResume(data);
                await fixWorkdayExperienceStepGaps(data.profile);
            }
            await saveWorkdayEntryModal();
            await ensureWorkdaySectionFormsClosed();
            {
                const expSec = findWorkExperienceSection();
                if (expSec) await cancelEmptyOpenSectionForms(expSec, 'experience');
            }
            await fillWorkdayFields(started);
            logFieldValues();
            logEmptyRequiredFields();
            logUnfilledDropdowns(getFormRoot());
            logWorkdayDropdownAudit('experience-step');
            logWorkdayValidationErrors();
            dumpWorkdayErrorsFoundBlock();
            break;
        case 'questions':
            resetWorkdayDropdownOpenCounts();
            await waitForWorkdayFormReady();
            // Only upload when this step actually has a file dropzone (e.g. required photo).
            if (hasWorkdayResumeUploadWidget()
                || [...getWorkdayFieldContainers()].some((c) => {
                    const l = getContainerLabel(c).toLowerCase();
                    return /upload.*photo|photo.*upload|headshot|profile picture/i.test(l)
                        && /drop files|select files?/i.test((c.innerText || '').toLowerCase());
                })) {
                await uploadResume(data);
            }
            await fillRequiredWorkdayDocumentUploads(data);
            await fillWorkdayPrivacyConsentFields();
            await fillWorkdaySmsConsentFields();
            // Retail Work Availability grids live outside formField collection
            await fillWorkdayAvailabilityTimeSlotGrid();
            // Reliable locals first (yes/no, dates, sponsorship, numeric salary), then AI stream
            await fillApplicationQuestions(data.profile);
            await fillWorkdayFields(started);
            await fillStreamPreferredQuestionFallbacks(data.profile);
            await fillEmptyRequiredDropdowns(data.profile);
            await fillRequiredWorkdayDocumentUploads(data);
            await fillWorkdayAvailabilityTimeSlotGrid();
            await fillWorkdayFields(started);
            await fillStreamPreferredQuestionFallbacks(data.profile);
            await fillApplicationQuestions(data.profile);
            await fillEmptyRequiredDropdowns(data.profile);
            await fillRequiredWorkdayDocumentUploads(data);
            await fillWorkdayAvailabilityTimeSlotGrid();
            logEmptyRequiredFields();
            logFieldValues();
            logUnfilledDropdowns(getFormRoot());
            logWorkdayValidationErrors();
            break;
        case 'disclosures':
            if (isWorkdayApplicationReviewStep()) {
                await waitForReviewPageReady();
                const reviewText = dumpReviewPageText('review');
                analyzeReviewPageText(reviewText, data.profile);
                return 'review';
            }
            resetWorkdayDropdownOpenCounts();
            await waitForWorkdayFormReady();
            await fillVoluntaryDisclosures(data.profile);
            await fillApplicationQuestions(data.profile);
            await fillEmptyRequiredDropdowns(data.profile);
            await fillWorkdayFields(started);
            await fillWorkdayFields(started);
            logEmptyRequiredFields();
            logWorkdayValidationErrors();
            break;
        case 'self_identify':
            await waitForWorkdayFormReady();
            await fillSelfIdentifyFields(data.profile);
            logEmptyRequiredFields();
            logWorkdayValidationErrors();
            break;
        case 'assessment':
            throw new SendCvSkipError('Take Assessment step — cannot auto-fill external assessment');
        case 'review': {
            await waitForReviewPageReady();
            if (workdayReviewHasUnansweredQuestions()) {
                window.__wdReviewQuestionsRecovery = (window.__wdReviewQuestionsRecovery || 0) + 1;
                debugLog(`${WD} review unanswered — return to Application Questions`,
                    'attempt=', window.__wdReviewQuestionsRecovery);
                if (window.__wdReviewQuestionsRecovery > 2) {
                    throw new SendCvError('Workday review still has unanswered questionnaire after recovery');
                }
                const ok = await returnToWorkdayQuestionsFromReview();
                if (ok) {
                    await waitForWorkdayFormReady();
                    await fillWorkdayFields(started);
                    await ensureWorkdayQuestionnaireSelectsCommitted();
                    await wait(800);
                    return 'continue';
                }
            }
            const reviewText = dumpReviewPageText('review');
            analyzeReviewPageText(reviewText, data.profile);
            return 'review';
        }
        default:
            if (isWorkdayAuthStepActive()) {
                await fillAuthStep(data.profile);
                break;
            }
            window.__wdHistoryLocation = window.__wdHistoryLocation || await getWorkdayJobLocation();
            const fieldCount = getWorkdayFieldContainers().length;
            if (!fieldCount && !findWorkdayNextButton()) {
                wdTiming.mark('apply-content-wait-start');
                await waitForWorkdayApplyContent(45000);
            } else {
                wdTiming.mark('apply-content-skip', `fields=${fieldCount}`);
            }
            if (!getWorkdayFieldContainers().length && !findWorkdayNextButton()) {
                await activateWorkdayCurrentStep();
                await waitForWorkdayApplyContent(20000);
            }
            await waitForWorkdayFormReady();
            await uploadResume(data);
            await fillBasicProfileFields(data.profile, started);
            await fillSelfIdentifyFields(data.profile);
            await fillWorkdayFields(started, { skipScrollReset: true });
            // Verify required fields are actually filled before allowing Next click.
            // React may not have committed values on first fill — retry if any are still empty.
            if (stepTry <= 1) {
                await wait(600);
                const emptyRequired = getWorkdayFieldContainers().filter(c => {
                    const lblRaw = getContainerLabel(c);
                    if (shouldSkipOptionalNameAffixField(c, lblRaw)) return false;
                    if (!isContainerRequired(c)) return false;
                    const ctrl = getContainerControl(c);
                    if (!ctrl) return false;
                    const lbl = lblRaw.toLowerCase();
                    if (/how did you hear|upload|file|resume|linkedin|website|social/i.test(lbl)) return false;
                    const preview = (c.innerText || '').replace(/\s+/g, ' ');
                    if (isWorkdayMaskedDateField(c, lbl) && isWorkdayDateFieldIncomplete(c)) return true;
                    return /select one|0 items selected/i.test(preview)
                        || (ctrl.tagName === 'INPUT' && ctrl.type !== 'radio' && ctrl.type !== 'checkbox'
                            && ctrl.type !== 'file' && !(ctrl.value || '').trim())
                        || (ctrl.tagName === 'TEXTAREA' && !(ctrl.value || '').trim());
                });
                if (emptyRequired.length > 0) {
                    debugLog(`${WD} information: ${emptyRequired.length} required fields still empty after fill, retrying`);
                    await fillBasicProfileFields(data.profile, started);
                    await fillWorkdayFields(started, { skipScrollReset: true });
                    await wait(500);
                }
            }
            logEmptyRequiredFields();
            logWorkdayValidationErrors();
            break;
    }
        return 'continue';
    } catch (e) {
        logWorkdayException(`processCurrentStep:${stepKey}`, e);
        throw e;
    } finally {
        setWorkdayFillInProgress(false);
    }
}

async function runWorkdayApplyLoop(data, started, loopState = {}) {
    const { devMode } = data;
    const stepTries = loopState.stepTries || {};
    let lastStepKey = loopState.lastStepKey ?? null;
    let loops = loopState.loops || 0;

    while (loops++ < MAX_STEP_LOOPS) {
        await pause();
        if (abortIfWorkdayAlreadyApplied()) return;
        throwIfWorkdayVacancyUnavailable('apply-loop');
        if (isWorkdaySomethingWentWrongPage()) {
            if (await recoverWorkdaySomethingWentWrongPage()) {
                continue;
            }
        }
        dismissWorkdayCookies();
        const stepKey = getCurrentStepKey();
        if (stepKey === 'loading' && isWorkdayIntroduceYourselfPage() && getWorkdayFieldContainers().length > 0
            && (stepTries['loading'] || 0) >= MAX_STEP_TRIES) {
            debugLog(`${WD} introduceYourself form visible — reset loading tries`);
            stepTries['loading'] = 0;
            lastStepKey = null;
        }
        if (stepKey === 'auth' && isWorkdayCreateAccountVisible()) {
            notifyWorkdayCreateAccountAutofill();
        }
        if (stepKey !== lastStepKey) {
            stepTries[stepKey] = 0;
            lastStepKey = stepKey;
            wdTiming.beginStep(stepKey);
            workdayScroll.resetForNewStep();
            resetWorkdayDropdownOpenCounts();
            agentStatus.webSocketStartedComplex = null;
            agentStatus.webSocketStartedSimple = null;
            window.__wdStreamCallsByStep = window.__wdStreamCallsByStep || {};
            window.__wdStreamCallsByStep[stepKey] = 0;
            window.__wdHearRejectedTerms = new Set();
            if (stepKey !== 'information') window.__wdHearAttempted = false;
        }
        stepTries[stepKey] = (stepTries[stepKey] || 0) + 1;
        if (stepKey === 'information' && stepTries[stepKey] > 1) {
            const hearContainer = findHearAboutContainer();
            if (hearContainer && !isHearFillDone(hearContainer)) {
                window.__wdHearFilled = false;
                window.__wdHearAttempted = false;
                debugLog(`${WD} hear retry reset`, 'try=', stepTries[stepKey]);
            }
        }
        if (stepTries[stepKey] > MAX_STEP_TRIES) {
            debugLog(`${WD} step stuck giving up`, stepKey, 'tries=', stepTries[stepKey], 'href=', location.href);
            dumpWorkdayErrorsFoundBlock();
            logEmptyRequiredFields();
            throw new SendCvError(`Workday step stuck: ${stepKey}`);
        }

        const prevHref = location.href;
        const prevInfo = getStepInfo();
        debugLog(`${WD} apply loop`, loops, 'step=', stepKey, 'try=', stepTries[stepKey]);
        wdTiming.mark('fill-start', `try=${stepTries[stepKey]}`);
        let result;
        try {
            result = await processCurrentStep(data, stepKey, started, stepTries[stepKey]);
        } catch (e) {
            logWorkdayException(`apply loop step ${stepKey} try ${stepTries[stepKey]}`, e);
            throw e;
        }
        wdTiming.mark('fill-end', `try=${stepTries[stepKey]}`);

        if (result === 'already-applied') return;

        if (result === 'review') {
            if (!canSafelySubmitWorkdayApplication()) {
                if (workdayReviewHasUnansweredQuestions()) {
                    window.__wdReviewQuestionsRecovery = (window.__wdReviewQuestionsRecovery || 0) + 1;
                    debugLog(`${WD} false review — unanswered questionnaire, returning to questions`,
                        'attempt=', window.__wdReviewQuestionsRecovery);
                    if (window.__wdReviewQuestionsRecovery > 2) {
                        throw new SendCvError('Workday review still has unanswered questionnaire after recovery');
                    }
                    const ok = await returnToWorkdayQuestionsFromReview();
                    if (ok) {
                        await waitForWorkdayFormReady();
                        await fillWorkdayFields(started);
                        await ensureWorkdayQuestionnaireSelectsCommitted();
                        await wait(800);
                    } else {
                        await wait(1500);
                    }
                } else {
                    debugLog(`${WD} false review detected — resuming apply loop`);
                }
                lastStepKey = null;
                continue;
            }
            wdTiming.mark('review-start');
            await validateWorkdayStep('review');
            if (!devMode) {
                wdTiming.mark('ready-to-submit-start');
                await readyToSubmit();
                wdTiming.mark('ready-to-submit-end');
                wdTiming.mark('submit-click-start');
                await clickSubmitButton();
                wdTiming.mark('submit-click-end');
                const afterText = dumpReviewPageText('after-submit');
                analyzeReviewPageText(afterText, data.profile);
                await waitForWorkdaySuccessMonitor();
                await validateWorkdayStep('after-submit');
            }
            logWorkdayPhase('apply success review');
            return;
        }

        await validateWorkdayStep(stepKey);
        wdTiming.mark('validate-end');
        if (stepKey === 'information' && !await ensureProfileLocationFields(data.profile)) {
            throw new SendCvError('Country or phone code does not match profile');
        }
        if (stepKey === 'loading') {
            if (isWorkdayCandidateHomePage()) {
                debugLog(`${WD} loading on candidate home — returning to apply`);
                await returnToApplyFormFromCandidateHome();
                await wait(3000);
                continue;
            }
            if (isWorkdayEmailSignInGateway()
                || queryVisible('[data-automation-id="signInWithEmailButton"]')
                || isWorkdayCreateAccountVisible()) {
                if (isWorkdayCreateAccountVisible()) notifyWorkdayCreateAccountAutofill();
                await wait(200);
                continue;
            }
            if (/\/applyManually/i.test(location.pathname) && getWorkdayFieldContainers().length === 0 && stepTries[stepKey] >= 8) {
                debugLog(`${WD} loading applyManually timeout — recover before give up`);
                await recoverEmptyWorkdayApplyPage();
                await wait(3000);
                continue;
            }
            debugLog(`${WD} form still loading, waiting before next click`);
            await wait(2000);
            continue;
        }
        if (stepKey === 'auth' && isWorkdayCandidateHomePage()) {
            debugLog(`${WD} auth on candidate home — returning to apply`);
            await returnToApplyFormFromCandidateHome();
            await wait(2000);
            continue;
        }
        if (stepKey === 'auth' && (isWorkdayCreateAccountVisible() || isWorkdayCreateAccountIncomplete())) {
            if (window.__wdCreateAccountJustSubmitted && isWorkdayLoginPage()) {
                debugLog(`${WD} auth step post-create — signing in`);
                await fillAuthStep(data.profile);
                await wait(1500);
                continue;
            }
            debugLog(`${WD} auth step incomplete, retrying`, 'createAccount=', isWorkdayCreateAccountVisible(), 'incomplete=', isWorkdayCreateAccountIncomplete());
            await fillAuthStep(data.profile);
            await wait(2000);
            continue;
        }
        if (stepKey === 'information' && hasEmptyRequiredInformationFields()) {
            debugLog(`${WD} blocking next — required information fields still empty`);
            logEmptyRequiredFields();
            await wait(2000);
            continue;
        }
        if (stepKey === 'questions') {
            await ensureWorkdayQuestionnaireSelectsCommitted();
            await wait(500);
        }
        const preNext = auditWorkdayPreNext(stepKey);
        const stepIssues = (stepKey === 'disclosures' || stepKey === 'questions' || stepKey === 'self_identify')
            ? await validateWorkdayStep(stepKey)
            : [];
        if (stepKey === 'information' && preNext.nextEnabled && preNext.emptyRequired <= 1 && preNext.fieldErrors === 0) {
            debugLog(`${WD} trust Workday Next enabled on information`, `empty=${preNext.emptyRequired}`);
        } else if (stepKey === 'disclosures' && preNext.nextEnabled && preNext.fieldErrors === 0
            && preNext.emptyRequired <= 1 && stepIssues.length === 0) {
            // TJX Data Protection checkbox etc. can be falsely counted empty after a successful check;
            // if Workday enables Next, the step is complete — do not spin 4 tries.
            debugLog(`${WD} trust Workday Next enabled on disclosures`, `empty=${preNext.emptyRequired}`);
        } else if (stepKey === 'questions' && preNext.nextEnabled && preNext.fieldErrors === 0
            && preNext.emptyRequired <= 1 && stepIssues.length === 0) {
            // UniMelb: optional visa-hours/expiry chrome can count empty=1 after citizen select.
            debugLog(`${WD} trust Workday Next enabled on questions`, `empty=${preNext.emptyRequired}`);
        } else if (stepKey === 'self_identify' && preNext.nextEnabled
            && preNext.emptyRequired === 0 && preNext.fieldErrors === 0 && stepIssues.length === 0) {
            // Only trust when Workday itself enables Next — ignoring banners while Next is disabled
            // just spins (belron.wd3 Name model not committed).
            debugLog(`${WD} trust self_identify after local Name/Date commit`, `nextEnabled=${preNext.nextEnabled}`);
        } else if (preNext.emptyRequired > 0 || preNext.fieldErrors > 0 || stepIssues.length > 0
            || (stepKey === 'self_identify' && !preNext.nextEnabled)) {
            debugLog(`${WD} blocking next — empty/invalid fields remain`, stepKey,
                `empty=${preNext.emptyRequired}`, `errors=${preNext.fieldErrors}`, `issues=${stepIssues.length}`);
            logEmptyRequiredFields();
            if (stepKey === 'experience') {
                await fixWorkdayExperienceStepGaps(data.profile);
                await fillEducationSection(data.profile);
                await fillCertificationsSection(data.profile);
                await fillWorkdayFields(started);
            } else if (stepKey === 'information') {
                await fillBasicProfileFields(data.profile, started);
                await fillWorkdayFields(started, { skipScrollReset: true });
            } else if (stepKey === 'disclosures') {
                await fillVoluntaryDisclosures(data.profile);
                await fillWorkdayPrivacyConsentFields();
                await fillWorkdayFields(started);
            } else if (stepKey === 'self_identify') {
                // Never fall through to fillWorkdayFields — it opens Name/Date as selects (belron.wd3 hang).
                await fillSelfIdentifyFields(data.profile);
            } else {
                await fillWorkdayFields(started);
            }
            await wait(1500);
            continue;
        }
        wdTiming.mark('next-click-start');
        const transitionCtx = { prevHref, prevStepKey: stepKey, prevInfo };
        const moved = await clickNextButton(transitionCtx);
        wdTiming.mark('next-click-end', `moved=${moved}`);
        if (checkWorkdayPostNextFailure(stepKey)) {
            await wait(1500);
            continue;
        }
        if (!moved) {
            debugLog(`${WD} next button not clicked on step`, stepKey);
            dumpWorkdayErrorsFoundBlock();
            logWorkdayValidationErrors();
            if (stepKey === 'experience' || stepKey === 'information') {
                debugLog(`${WD} attempting gap fix before retry next`, stepKey);
                if (stepKey === 'experience') {
                    await fixWorkdayExperienceStepGaps(data.profile);
                } else if (stepKey === 'information') {
                    const jobProfile = getProfileForJobLocation(data.profile);
                    await fixCountryForJobLocation(data.profile);
                    await fixPhoneCodeForProfile(jobProfile);
                    await fixJapanAddressFields(data.profile);
                    await fixPostalCodeForJobLocation(data.profile);
                    await fixPostalCodeStateMismatch(data.profile);
                    await fixStateForProfile(data.profile);
                }
                await wait(1200);
                dumpWorkdayErrorsFoundBlock();
                const retryMoved = await clickNextButton(transitionCtx);
                if (retryMoved) {
                    debugLog(`${WD} next succeeded after gap fix`, stepKey);
                    stepTries[stepKey] = 0;
                    continue;
                }
            }
            if (location.href === prevHref) {
                await wait(3000);
            }
        } else if (location.href !== prevHref) {
            stepTries[stepKey] = 0;
        } else {
            const newStepKey = getCurrentStepKey();
            const newInfo = getStepInfo();
            const stepAdvanced = newStepKey !== stepKey
                || (prevInfo.step && newInfo.step && newInfo.step > prevInfo.step);
            if (stepAdvanced) {
                stepTries[stepKey] = 0;
                lastStepKey = null;
                window.__wdBlockedRequiredLabels = new Set();
            } else {
                dumpWorkdayErrorsFoundBlock();
                logWorkdayValidationErrors();
                debugLog(`${WD} still on step after next click`, stepKey, 'step=', newInfo.step, '/', newInfo.total);
                // Clear streamed labels for any fields with visible validation errors so they are re-collected
                window.__wdBlockedRequiredLabels = window.__wdBlockedRequiredLabels || new Set();
                if (window.__wdStreamedLabels) {
                    for (const container of getWorkdayFieldContainers()) {
                        const hasErr = !!container.querySelector('[data-automation-id="errorMessage"], [data-automation-id*="validationError"]')
                            || /is required and must have a value/i.test(container.innerText || '');
                        if (hasErr) {
                            const lbl = getContainerLabel(container);
                            if (lbl) {
                                if (wdStreamedLabelsHas(lbl)) {
                                    debugLog(`${WD} force re-stream field with block error`, lbl.slice(0, 60));
                                    wdStreamedLabelsDelete(lbl);
                                }
                                window.__wdBlockedRequiredLabels.add(lbl.toLowerCase());
                                // Reset dropdown open count so blocked select fields can be re-enriched and re-filled
                                const dropKey = lbl.toLowerCase().slice(0, 80);
                                if (wdDropdownOpenCounts[dropKey] !== undefined) {
                                    debugLog(`${WD} reset dropdown count for blocked field`, dropKey.slice(0, 50));
                                    delete wdDropdownOpenCounts[dropKey];
                                }
                            }
                        }
                    }
                }
                if (stepKey === 'experience') {
                    debugLog(`${WD} experience step fix gaps after blocked next`);
                    await fixWorkdayExperienceStepGaps(data.profile);
                    await wait(1500);
                    dumpWorkdayErrorsFoundBlock();
                    await clickNextButton(transitionCtx);
                } else if (stepKey === 'information') {
                    debugLog(`${WD} information step fix postal/state after blocked next`);
                    await fixPostalCodeStateMismatch(data.profile);
                    await fixStateForProfile(data.profile);
                    await fixPhoneNumberForRegion(data.profile);
                    await wait(1200);
                    dumpWorkdayErrorsFoundBlock();
                    await clickNextButton(transitionCtx);
                } else if (stepKey === 'questions'
                    && (pageHasWorkdayTimeSlotRequirementError()
                        || pageHasWorkdayAvailabilityConflictError()
                        || isWorkdayAvailabilityStepActive())) {
                    debugLog(`${WD} questions step fix availability time slots after blocked next`);
                    await fillWorkdayAvailabilityTimeSlotGrid();
                    await wait(800);
                    dumpWorkdayErrorsFoundBlock();
                    await clickNextButton(transitionCtx);
                }
            }
        }
    }

    throw new SendCvError('Workday apply loop exceeded');
}

async function handleWorkdayApplyFailure(data, started, error) {
    const sessionStarted = started || agentStatus.applyStarted;
    let pendingError = error;

    while (true) {
        const err = pendingError instanceof Error ? pendingError : new SendCvError(String(pendingError));
        const resumed = await fillingErrors(err, { returnOnResume: true });
        if (!resumed) return;

        try {
            await resumeAfterManualFixWorkday(data, sessionStarted);
            return;
        } catch (resumeError) {
            logWorkdayException('apply resume', resumeError);
            if (resumeError instanceof SendCvSkipError) {
                clearWorkdayApplySession();
                chrome.runtime.sendMessage({ type: 'SEND-CV-TASK-SKIP', data: resumeError.message }).catch(console.error);
                return;
            }
            pendingError = resumeError;
        }
    }
}

async function resumeAfterManualFixWorkday(data, started) {
    agentStatus.resumed = true;
    debugLog(`${WD} resume from step`, getCurrentStepKey(), getStepInfo().stepName?.slice(0, 60) || '');

    if (started != agentStatus.applyStarted) return;

    const onApplyFlow = isApplyFormPage() || isWorkdayLoginPage() || /\/apply(?:\/|$)/i.test(location.pathname);
    if (!onApplyFlow && !isWorkdaySubmitPending()) {
        debugLog(`${WD} resume aborted`, 'not on apply flow', location.pathname);
        return;
    }

    appendStatusMessage('Resuming auto-apply...');
    await runWorkdayApplyLoop(data, started);
    if (!agentStatus.success && !isWorkdaySubmitSuccessPage()) {
        throw new SendCvError('Apply incomplete after resume');
    }
}

async function apply(data, options = {}) {
    if (abortIfWorkdayAlreadyApplied()) return;
    if (isWorkdayCreateAccountVisible()) {
        notifyWorkdayCreateAccountAutofill();
    }

    // Force en-US locale: if the current URL contains a non-en-US language segment, redirect immediately.
    const _enUsLocaleRe = /^(\/[^/]+)(\/(?!en-US\/)[a-z]{2,3}(?:-[A-Z]{2})?)\//;
    if (/myworkdayjobs\.com/i.test(location.hostname)) {
        const _localeMatch = location.pathname.match(/^(\/(?!en-US\/)[a-z]{2,3}(?:-[A-Z]{2})?)\//);
        if (_localeMatch) {
            const _enUsPath = location.pathname.replace(_localeMatch[1], '/en-US');
            const _enUsUrl = location.origin + _enUsPath + location.search + location.hash;
            debugLog(`${WD} non-en-US locale detected (${_localeMatch[1]}), redirecting to en-US:`, _enUsUrl);
            location.replace(_enUsUrl);
            return;
        }
    }

    if (window.__wdApplyRunning) {
        debugLog(`${WD} apply already running, skip duplicate`, location.pathname);
        return;
    }
    window.__wdApplyRunning = true;

    try {
    window.__wdApplyData = data;
    installWorkdayAccidentalSubmitGuard();
    installWorkdayExternalNavigationGuard();
    isIntroduceYourselfDone();
    const { devMode } = data;
    const sessionStarted = getWorkdayApplyStartedFromSession();
    const started = options.preserveStarted
        ? (agentStatus.applyStarted || sessionStarted || Date.now())
        : (agentStatus.applyStarted = sessionStarted || Date.now());
    if (!agentStatus.applyStarted || agentStatus.applyStarted !== started) {
        agentStatus.applyStarted = started;
    }
    debugLog(`${WD} apply started`, started, 'session=', sessionStarted, 'preserve=', Boolean(options.preserveStarted));
    markWorkdayApplySession(started, data?.url || location.href);

    startApplyHeartbeat('apply');
    wdTiming.beginApply();
    delete window.__wdCachedResume;
    delete window.__wdResumeFetchPromise;
    window.__wdResumeFetchLog = [];
    window.__wdLockedYesNoFilled = new Set();
    logWorkdayPhase('apply start');

    const continuing = options.resumeOnly || isWorkdayApplyContinuation(data);
    if (!continuing) {
        await waitForWorkdayPageReady(15000);
        throwIfWorkdayVacancyUnavailable('apply-start');
        if (isApplyFormPage()) {
            debugLog(`${WD} started on apply form, expecting description redirect via prepareURL`);
        }

        await navigateToApplyFormIfNeeded();
    } else {
        debugLog(`${WD} continuing apply after navigation`, location.pathname, 'started=', started);
        await waitForWorkdayPageReady(15000);
        // waitForWorkdayPageReady() returns early on a vacancy-unavailable page ("page ready vacancy
        // unavailable"), but until this check was added the continuing branch ignored that result and
        // fell straight into the isJobDescriptionPage() block below, which navigated to a
        // now-nonexistent /apply/applyManually URL and then hung for ~30s+ polling "waiting for apply
        // form to render" that would never appear (job closed/removed between the original attempt and
        // this resumed continuation). Fail fast here, same as the non-continuing branch above.
        throwIfWorkdayVacancyUnavailable('continuing-page-ready');
        if (isWorkdayCandidateHomePage()) {
            await returnToApplyFormFromCandidateHome();
        } else if (isWorkdayIntroduceYourselfPage()) {
            await returnFromIntroduceYourselfToApply();
        }
        if (isWorkdayCareersSearchPage()) {
            throw new SendCvSkipError('Job not found');
        }
        if (isJobDescriptionPage() && !isApplyFormPage()) {
            const jobPath = location.pathname.replace(/\/apply\/.*/i, '').replace(/\/$/, '');
            const manualUrl = /\/job\//i.test(jobPath) ? `${location.origin}${jobPath}/apply/applyManually` : '';
            if (manualUrl && isIntroduceYourselfDone()) {
                const navKey = sessionStorage.getItem('wdPostIntroNavDone') || '';
                if (navKey !== manualUrl) {
                    try { sessionStorage.setItem('wdPostIntroNavDone', manualUrl); } catch (_) { /* ignore */ }
                    debugLog(`${WD} job page — try applyManually`, manualUrl.slice(0, 120),
                        'intro=', isIntroduceYourselfDone());
                    window.top.location.replace(manualUrl);
                    await wait(10000);
                    throwIfWorkdayVacancyUnavailable('post-applyManually-nav');
                } else {
                    debugLog(`${WD} applyManually nav skip repeat`, manualUrl.slice(0, 80));
                    throwIfWorkdayVacancyUnavailable('applyManually-repeat');
                }
            } else {
                const savedApplyUrl = getWorkdaySavedApplyUrl(data);
                if (savedApplyUrl && /\/apply\//i.test(savedApplyUrl)) {
                    debugLog(`${WD} continuing on job page — direct to saved apply`, savedApplyUrl.slice(0, 120));
                    window.top.location.replace(savedApplyUrl);
                    await wait(10000);
                    throwIfWorkdayVacancyUnavailable('post-saved-apply-nav');
                } else {
                    await navigateToApplyFormIfNeeded();
                }
            }
        }
    }
    throwIfWorkdayVacancyUnavailable('pre-apply-loop');
    if (abortIfWorkdayAlreadyApplied()) return;

    await ensureWorkdayHistoryDetails(data);

    if (!sessionStorage.getItem('lcvWdRelevantJobsMsgShown') && !data.successfulSubmissions && !data.failedSubmissions) {
        sessionStorage.setItem('lcvWdRelevantJobsMsgShown', '1');
        if (!isWorkdayCreateAccountVisible()) {
            appendStatusMessage('Found relevant job openings. Starting auto-apply with the first one...');
            await wait(2000);
        }
    }

    await runWorkdayApplyLoop(data, started, options.loopState || {});
    } catch (e) {
        logWorkdayException('apply', e);
        throw e;
    } finally {
        window.__wdApplyRunning = false;
        stopApplyHeartbeat();
        wdTiming.dumpSummary('end');
        logWorkdayPhase('apply end');
    }
}

window.addEventListener('load', () => {
    if (!isWorkdayHost()) return;

    chrome.runtime.sendMessage({ type: 'GET-SEND-CV-TASK' }).then(async (value) => {
        value = await startApplyOne(value);
        const { type, data } = value;

        if (type !== 'SUCCESS') return;

        startWorkdayApplyEarlyMonitors();
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => abortIfWorkdayAlreadyApplied(), { once: true });
        }
        if (abortIfWorkdayAlreadyApplied()) return;

        window.addEventListener('error', (ev) => {
            logWorkdayException('window.onerror', ev.error || ev.message);
        });
        window.addEventListener('unhandledrejection', (ev) => {
            logWorkdayException('unhandledrejection', ev.reason);
        });

        if (isWorkdaySubmitSuccessPage()) {
            clearWorkdaySubmitPending();
            clearWorkdayApplySession();
            cvTaskDone();
            return;
        }

        const agentMode = getAgentModeForApply(data);
        debugLog(`${WD} agent mode`, agentMode, 'applyOneEnabled=', data.applyOneEnabled, 'storeMode=', data.agentMode);

        let applyStartedAt = null;
        try {
            if (abortIfWorkdayAlreadyApplied()) return;
            warmingUp(data.agentGeometry, data.agentMessages, agentMode);
            agentStatus.agentMode = agentMode;
            if (isWorkdayCreateAccountVisible()) {
                notifyWorkdayCreateAccountAutofill();
            }

            if (isWorkdayCareersSearchPage()) {
                throw new SendCvSkipError('Job not found');
            }

            if (!isJobDescriptionPage() && !isApplyFormPage() && !isWorkdayLoginPage() && !isWorkdayApplyContinuation(data)) {
                if (isWorkdaySubmitPending()) {
                    debugLog(`${WD} submit pending page`, location.href);
                    if (isWorkdaySubmitSuccessPage()) {
                        clearWorkdaySubmitPending();
                        clearWorkdayApplySession();
                        cvTaskDone();
                        return;
                    }
                    registerWorkdaySuccessMonitors();
                    await waitForWorkdaySuccessMonitor(120000);
                    clearWorkdaySubmitPending();
                    return;
                }
                throw new SendCvSkipError('Job not found');
            }

            countDown = startCountDownInStatusBlock(180, () => {
                debugLog(`${WD} tab timer ended`, location.href);
                chrome.runtime.sendMessage({
                    type: 'SEND-CV-TAB-TIMER-ENDED',
                    data: { url: window.location.href },
                });
            }, { maxTotal: 480, maxStepAdd: 180 });

            registerWorkdaySuccessMonitors();

            applyStartedAt = agentStatus.applyStarted;
            const continuing = isWorkdayApplyContinuation(data);
            const onApplyFlow = isApplyFormPage() || isWorkdayLoginPage() || /\/apply(?:\/|$)/i.test(location.pathname);
            if (abortIfWorkdayAlreadyApplied()) return;
            const startupDelay = (continuing && onApplyFlow) || isWorkdayCreateAccountVisible() ? 0 : (continuing ? 500 : 3000);
            await new Promise((resolve, reject) => {
                setTimeout(async () => {
                    try {
                        await apply(data, {
                            preserveStarted: true,
                            resumeOnly: continuing,
                        });
                        resolve();
                    } catch (e) {
                        logWorkdayException('apply promise', e);
                        reject(e);
                    }
                }, startupDelay);
            });

            if (window.__wdAlreadyAppliedAborted) return;
            if (!agentStatus.success) {
                debugLog(`${WD} apply finished without success flag`);
                await handleWorkdayApplyFailure(data, agentStatus.applyStarted || applyStartedAt, new SendCvError('timeout after submit'));
            }
        } catch (e) {
            logWorkdayException('apply load handler', e);
            if (e instanceof SendCvSkipError) {
                clearWorkdayApplySession();
                chrome.runtime.sendMessage({ type: 'SEND-CV-TASK-SKIP', data: e.message }).catch(console.error);
            } else {
                await handleWorkdayApplyFailure(data, agentStatus.applyStarted || applyStartedAt, e);
            }
        }
    }).catch((e) => {
        logWorkdayException('GET-SEND-CV-TASK', e);
    });
});
